    private sealed record PendingClarificationPreparation(string EffectiveUserMessage, DocumentRefResolver.AnalysisResult? AnalysisOverride, bool Consumed);

    private PendingClarificationPreparation PrepareUserMessageForPendingClarification(
        IReadOnlyList<(string role, string content)> chatHistory,
        string? userMessage)
    {
        var safeUserMessage = userMessage ?? string.Empty;
        var pending = _mem.PendingClarification;
        if ((pending is null || string.IsNullOrWhiteSpace(pending.OriginalUserMessage))
            && TryInferPendingClarificationFromHistory(chatHistory, out var inferredPending))
        {
            pending = inferredPending;
        }

        if (pending is null || string.IsNullOrWhiteSpace(pending.OriginalUserMessage))
            return new PendingClarificationPreparation(safeUserMessage, null, false);

        var current = safeUserMessage.Trim();
        if (current.Length == 0)
            return new PendingClarificationPreparation(safeUserMessage, null, false);

        if (DocumentRefResolver.IsRepairMessage(current) || TryDetectExplicitLanguageSwitch(current, out _))
        {
            ClearPendingClarification();
            return new PendingClarificationPreparation(safeUserMessage, null, false);
        }

        var expectsDocumentAnswer = string.Equals(pending.Kind, "doc_reference", StringComparison.OrdinalIgnoreCase)
            || string.Equals(pending.Kind, "document_reference", StringComparison.OrdinalIgnoreCase);
        var expectsTreeScope = string.Equals(pending.Kind, "tree_scope", StringComparison.OrdinalIgnoreCase);
        var expectsRagProbeRefinement = string.Equals(pending.Kind, "rag_probe", StringComparison.OrdinalIgnoreCase);
        var expectsBroadenedSourceSearch = string.Equals(pending.Kind, "source_backed_broaden_search", StringComparison.OrdinalIgnoreCase)
            || string.Equals(pending.Kind, "broader_source_search", StringComparison.OrdinalIgnoreCase);
        var expectsGenericClarification = IsGenericClarificationKind(pending.Kind);

        var isExpectedAnswer = expectsDocumentAnswer
            ? DocumentRefResolver.LooksLikeDocumentReferenceAnswer(current, _mem.LastFocusedDocument, _mem.LastListedDocuments, _mem.LastRequestedDocumentRef)
            : expectsTreeScope
                ? DocumentRefResolver.LooksLikeTreeScopeAnswer(current)
                : expectsRagProbeRefinement
                    ? current.Length >= 2
                    : expectsBroadenedSourceSearch
                        ? LooksLikeBroadenedSourceSearchConfirmation(current)
                        : expectsGenericClarification && LooksLikeGenericClarificationAnswer(current);

        if (!isExpectedAnswer)
        {
            if (LooksLikeClarificationMetaAck(current))
                return new PendingClarificationPreparation(safeUserMessage, null, false);

            ClearPendingClarification();
            return new PendingClarificationPreparation(safeUserMessage, null, false);
        }

        var effectiveUserMessage = expectsRagProbeRefinement
            ? $@"PREVIOUS_DOCUMENTARY_REQUEST:
{pending.OriginalUserMessage}

RETRIEVAL_REFINEMENT:
{current}"
            : expectsBroadenedSourceSearch
                ? $@"PREVIOUS_USER_REQUEST:
{pending.OriginalUserMessage}

USER_CONFIRMED_BROADER_SOURCE_SEARCH:
{current}

RESOLVED_REQUEST:
Continue the previous source-backed request by running a broader retrieval exploration across the relevant indexed corpus or category before answering. Use catalog/category hints, document profiles, title anchors and navigation/table-of-contents entries when useful. Keep the final answer grounded in sources and do not treat this confirmation as a new topic."
            : expectsGenericClarification
                ? $@"PREVIOUS_USER_REQUEST:
{pending.OriginalUserMessage}

USER_CLARIFICATION:
{current}

RESOLVED_REQUEST:
Continue the previous request using the clarification as the intended topic or scope."
            : $@"PREVIOUS_AMBIGUOUS_REQUEST:
{pending.OriginalUserMessage}

CLARIFICATION_ANSWER:
{current}";

        var analysisOverride = expectsRagProbeRefinement || expectsGenericClarification || expectsBroadenedSourceSearch
            ? null
            : DocumentRefResolver.Analyze(effectiveUserMessage, _mem.LastFocusedDocument, _mem.LastListedDocuments, _mem.LastRequestedDocumentRef);
        ClearPendingClarification();
        return new PendingClarificationPreparation(effectiveUserMessage, analysisOverride, true);
    }

    private static bool IsGenericClarificationKind(string? kind)
    {
        if (string.IsNullOrWhiteSpace(kind))
            return true;

        return string.Equals(kind, "generic", StringComparison.OrdinalIgnoreCase)
            || string.Equals(kind, "clarification", StringComparison.OrdinalIgnoreCase)
            || string.Equals(kind, "topic", StringComparison.OrdinalIgnoreCase)
            || string.Equals(kind, "topic_scope", StringComparison.OrdinalIgnoreCase)
            || string.Equals(kind, "topic_refinement", StringComparison.OrdinalIgnoreCase);
    }

    private static bool LooksLikeGenericClarificationAnswer(string? userMessage)
    {
        var s = (userMessage ?? string.Empty).Trim();
        if (s.Length < 2)
            return false;

        return s.Length <= 800;
    }

    private static bool TryInferPendingClarificationFromHistory(
        IReadOnlyList<(string role, string content)> chatHistory,
        out ToolMemory.PendingClarificationState? pending)
    {
        pending = null;
        if (chatHistory is null || chatHistory.Count < 2)
            return false;

        for (var assistantIndex = chatHistory.Count - 1; assistantIndex >= 1; assistantIndex--)
        {
            var assistantTurn = chatHistory[assistantIndex];
            if (!string.Equals(assistantTurn.role, "assistant", StringComparison.OrdinalIgnoreCase)
                || string.IsNullOrWhiteSpace(assistantTurn.content))
            {
                continue;
            }

            if (LooksLikeAssistantBroadenedSearchOffer(assistantTurn.content))
            {
                for (var userIndex = assistantIndex - 1; userIndex >= 0; userIndex--)
                {
                    var userTurn = chatHistory[userIndex];
                    if (!string.Equals(userTurn.role, "user", StringComparison.OrdinalIgnoreCase)
                        || string.IsNullOrWhiteSpace(userTurn.content))
                    {
                        continue;
                    }

                    pending = new ToolMemory.PendingClarificationState
                    {
                        Kind = "source_backed_broaden_search",
                        OriginalUserMessage = userTurn.content.Trim(),
                        Hint = "recovered_from_broadened_search_offer",
                        Language = DetectMessageLanguage(assistantTurn.content),
                        CreatedAtUtc = DateTimeOffset.UtcNow
                    };
                    return true;
                }

                return false;
            }

            if (!LooksLikeAssistantClarificationQuestion(assistantTurn.content))
                return false;

            for (var userIndex = assistantIndex - 1; userIndex >= 0; userIndex--)
            {
                var userTurn = chatHistory[userIndex];
                if (!string.Equals(userTurn.role, "user", StringComparison.OrdinalIgnoreCase)
                    || string.IsNullOrWhiteSpace(userTurn.content))
                {
                    continue;
                }

                pending = new ToolMemory.PendingClarificationState
                {
                    Kind = InferClarificationKindFromQuestion(assistantTurn.content),
                    OriginalUserMessage = userTurn.content.Trim(),
                    Hint = "recovered_from_chat_history",
                    Language = DetectMessageLanguage(assistantTurn.content),
                    CreatedAtUtc = DateTimeOffset.UtcNow
                };
                return true;
            }

            return false;
        }

        return false;
    }

    private static bool LooksLikeAssistantClarificationQuestion(string? assistantMessage)
    {
        var s = (assistantMessage ?? string.Empty).Trim();
        if (s.Length == 0 || !s.Contains('?', StringComparison.Ordinal))
            return false;

        return Regex.IsMatch(
            s,
            @"(?i)(clarif|precis|pr[ée]cis|quel\s+sujet|quelle\s+sujet|which\s+topic|what\s+topic|quel\s+document|which\s+document|scope|perimetre|p[ée]rim[èe]tre|category|cat[ée]gorie)");
    }

    private static string InferClarificationKindFromQuestion(string? assistantMessage)
    {
        var s = assistantMessage ?? string.Empty;
        if (Regex.IsMatch(s, @"(?i)(document|doc\b|pdf|file|fichier)"))
            return "doc_reference";
        if (Regex.IsMatch(s, @"(?i)(scope|perimetre|p[ée]rim[èe]tre|category|cat[ée]gorie|dossier|folder|arborescence)"))
            return "tree_scope";

        return "generic";
    }

    private void RememberPendingClarification(string kind, string originalUserMessage, string? hint, string? language)
    {
        _mem.PendingClarification = new ToolMemory.PendingClarificationState
        {
            Kind = string.IsNullOrWhiteSpace(kind) ? "generic" : kind.Trim(),
            OriginalUserMessage = originalUserMessage ?? string.Empty,
            Hint = hint,
            Language = language,
            CreatedAtUtc = DateTimeOffset.UtcNow
        };
    }

    private void ClearPendingClarification()
        => _mem.PendingClarification = null;

    private static bool LooksLikeClarificationMetaAck(string? userMessage)
    {
        var s = (userMessage ?? string.Empty).Trim();
        if (s.Length == 0)
            return false;

        return Regex.IsMatch(s, @"^(?:yes|yeah|yep|oui|ok|okay|d['\u2019]accord|exactly|exact|precisely|exactement|pr[ée]cis[eé]ment|correct|c['\u2019]est\s+ça|that['\u2019]?s\s+right)$", RegexOptions.IgnoreCase);
    }

    private static bool LooksLikeBroadenedSourceSearchConfirmation(string? userMessage)
    {
        var s = CollapseWhitespace(userMessage ?? string.Empty);
        if (s.Length == 0 || s.Length > 160)
            return false;

        var normalized = NormalizeLexicalLookup(s);
        return Regex.IsMatch(
            normalized,
            @"^(?:yes|yeah|yep|ok|okay|go|do it|continue|broaden(?: the search)?|search broader|oui|vas[- ]?y|lance(?: la)?(?: recherche)?|d accord|recherche plus large|elargis(?: la)?(?: recherche)?|cherche plus large)(?:\b.*)?$",
            RegexOptions.IgnoreCase);
    }

    private static bool LooksLikeAssistantBroadenedSearchOffer(string? assistantMessage)
        => ContainsBroadenedSourceSearchOffer(assistantMessage);

    private static bool ContainsBroadenedSourceSearchOffer(string? answer)
    {
        var normalized = NormalizeLexicalLookup(answer ?? string.Empty);
        if (normalized.Length == 0)
            return false;

        return normalized.Contains("recherche plus large", StringComparison.Ordinal)
            || normalized.Contains("broader corpus search", StringComparison.Ordinal)
            || normalized.Contains("broader search", StringComparison.Ordinal)
            || normalized.Contains("busqueda mas amplia", StringComparison.Ordinal)
            || normalized.Contains("pesquisa mais ampla", StringComparison.Ordinal)
            || normalized.Contains("breitere suche", StringComparison.Ordinal)
            || normalized.Contains("ricerca piu ampia", StringComparison.Ordinal);
    }

    private async Task<string> GenerateClarificationResponseAsync(
        IReadOnlyList<(string role, string content)> chatHistory,
        string userMessage,
        string language,
        string clarificationKind,
        string? hint,
        CancellationToken ct,
        Action<string>? onDelta)
    {
        var system = PromptCatalog.BuildClarificationSystemPrompt(language, clarificationKind, hint);
        var user = $@"
CHAT_TAIL:
{SerializeTail(chatHistory, maxTurns: 8)}

USER_MESSAGE:
{userMessage}
";

        return await CompleteTextResponseAsync(system, user, ct, onDelta).ConfigureAwait(false);
    }

    private async Task<string> EnsureAnswerMatchesRequestedLanguageAsync(string answer, string requestedLanguage, CancellationToken ct)
    {
        var trimmed = (answer ?? string.Empty).Trim();
        if (trimmed.Length == 0)
            return trimmed;

        var targetLanguage = NormalizeLanguageCode(requestedLanguage);
        var detectedLanguageRaw = DetectMessageLanguage(trimmed);
        if (string.IsNullOrWhiteSpace(targetLanguage) || string.IsNullOrWhiteSpace(detectedLanguageRaw))
            return trimmed;

        var detectedLanguage = NormalizeLanguageCode(detectedLanguageRaw);
        if (string.Equals(detectedLanguage, targetLanguage, StringComparison.OrdinalIgnoreCase))
            return trimmed;

        try
        {
            var system = $@"You are SAAIA assistant.
Translate the provided assistant answer faithfully.
Target language: {targetLanguage}
Rules:
- Keep the same meaning and tone.
- Do not add or remove facts.
- Keep document names, file names, page references and source citations unchanged.
- Return plain text only.";

            var translated = await _llm.CompleteAsync(new[]
            {
                ("system", system),
                ("user", trimmed)
            }, forceJson: false, ct).ConfigureAwait(false);

            translated = (translated ?? string.Empty).Replace("**", string.Empty).Trim();
            return string.IsNullOrWhiteSpace(translated) ? trimmed : translated;
        }
        catch
        {
            return trimmed;
        }
    }

    private async Task<string> GenerateRepairResponseAsync(
        IReadOnlyList<(string role, string content)> chatHistory,
        string userMessage,
        string language,
        CancellationToken ct,
        Action<string>? onDelta)
    {
        var system = PromptCatalog.BuildRepairSystemPrompt(language);
        var user = $@"
LAST_USER_MESSAGE:
{_mem.LastUserMessage}

LAST_ASSISTANT_ANSWER:
{_mem.LastAssistantAnswer}

LAST_ROUTER_INTENT:
{_mem.LastRouterIntent}

LAST_TOOLS:
{string.Join(", ", _mem.LastToolNames ?? new List<string>())}

LAST_ROUTER_CONFIDENCE:
{(_mem.LastRouterConfidence.HasValue ? _mem.LastRouterConfidence.Value.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture) : string.Empty)}

LAST_REASONING_TRACE_PUBLIC:
{string.Join(" | ", _mem.LastReasoningTracePublic ?? new List<string>())}

LAST_MEMORY_UPDATE:
{_mem.LastPlannerMemoryUpdate}

CHAT_TAIL:
{SerializeTail(chatHistory, maxTurns: 8)}

CURRENT_USER_MESSAGE:
{userMessage}
";

        return await CompleteTextResponseAsync(system, user, ct, onDelta).ConfigureAwait(false);
    }

    private async Task<string> CompleteTextResponseAsync(string system, string user, CancellationToken ct, Action<string>? onDelta)
    {
        if (onDelta is not null)
        {
            var streamed = new StringBuilder();
            await _llm.StreamAsync(new[] { ("system", system), ("user", user) }, forceJson: false, delta =>
            {
                if (string.IsNullOrEmpty(delta))
                    return;
                streamed.Append(delta);
                onDelta(delta);
            }, ct).ConfigureAwait(false);

            var txt = streamed.ToString().Replace("**", string.Empty).Trim();
            if (!string.IsNullOrWhiteSpace(txt))
                return txt;
        }

        var raw = await _llm.CompleteAsync(new[] { ("system", system), ("user", user) }, forceJson: false, ct).ConfigureAwait(false);
        return (raw ?? string.Empty).Replace("**", string.Empty).Trim();
    }

    private void RememberTurnState(string userMessage, string assistantAnswer, string? routerIntent, IEnumerable<string>? toolNames, IEnumerable<string>? reasoningTracePublic)
    {
        _mem.LastUserMessage = userMessage;
        _mem.LastAssistantAnswer = assistantAnswer;
        _mem.LastRouterIntent = routerIntent;
        _mem.LastToolNames = toolNames?.Where(x => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList() ?? new List<string>();
        _mem.LastReasoningTracePublic = reasoningTracePublic?.Where(x => !string.IsNullOrWhiteSpace(x)).ToList() ?? new List<string>();

        var hasExplicitLanguageSwitch = TryDetectExplicitLanguageSwitch(userMessage, out var requestedLanguage);
        var isOneShotTranslation = string.Equals(routerIntent, "meta.translate_last_answer", StringComparison.OrdinalIgnoreCase)
            || hasExplicitLanguageSwitch;

        var answerLanguage = isOneShotTranslation && !string.IsNullOrWhiteSpace(requestedLanguage)
            ? requestedLanguage
            : DetectMessageLanguage(assistantAnswer);

        if (!string.IsNullOrWhiteSpace(answerLanguage))
        {
            _mem.LastAnswerLanguage = answerLanguage;
            if (!isOneShotTranslation)
                _mem.LastLanguage = answerLanguage;
        }

        if (!isOneShotTranslation)
        {
            var userLanguage = DetectMessageLanguage(userMessage);
            if (string.IsNullOrWhiteSpace(userLanguage))
                userLanguage = "fr";

            _mem.LastUserDetectedLanguage = userLanguage;
        }
    }


    private static bool TryParseAnswerEnvelope(string json, out string? finalAnswer, out List<ToolMemory.SourceRef>? sources)
    {
        finalAnswer = null;
        sources = null;

        try
        {
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            if (root.TryGetProperty("finalAnswer", out var a) && a.ValueKind == JsonValueKind.String)
                finalAnswer = a.GetString();
            else
                finalAnswer = "";

            if (root.TryGetProperty("sources", out var sArr) && sArr.ValueKind == JsonValueKind.Array)
            {
                var list = new List<ToolMemory.SourceRef>();
                foreach (var s in sArr.EnumerateArray())
                {
                    if (s.ValueKind != JsonValueKind.Object) continue;

                    var source = TryBuildSourceRefFromJsonElement(s);
                    if (source is not null)
                        list.Add(source);
                }

                sources = list;
            }

            return true;
        }
        catch
        {
            return false;
        }
    }

    private static ToolMemory.SourceRef? TryBuildSourceFromResolveResult(ToolResults toolResults)
    {
        try
        {
            var item = toolResults.Items.LastOrDefault(x => x.ToolName == "sources.resolve");
            if (item is null) return null;

            var res = item.Result;
            if (res.ValueKind != JsonValueKind.Object) return null;
            if (!res.TryGetProperty("source", out var src) || src.ValueKind != JsonValueKind.Object) return null;

            return TryBuildSourceRefFromJsonElement(src);
        }
        catch
        {
            return null;
        }
    }

    private static ToolMemory.SourceRef? TryBuildSourceRefFromJsonElement(JsonElement src)
    {
        if (src.ValueKind != JsonValueKind.Object)
            return null;

        var docPath = TryGetString(src, "docPath") ?? TryGetString(src, "doc_path") ?? TryGetString(src, "path") ?? "";
        if (string.IsNullOrWhiteSpace(docPath))
            return null;

        var ps = TryGetInt(src, "pageStart") ?? TryGetInt(src, "page_start") ?? TryGetInt(src, "page") ?? 1;
        var pe = TryGetInt(src, "pageEnd") ?? TryGetInt(src, "page_end") ?? ps;
        ps = Math.Max(1, ps);
        pe = Math.Max(ps, pe);

        var docName = NullIfWhiteSpace(TryGetString(src, "docName") ?? TryGetString(src, "doc_name") ?? TryGetString(src, "DocName"));
        var label = TryGetString(src, "label")
            ?? docName
            ?? Path.GetFileName(docPath);
        if (string.IsNullOrWhiteSpace(label))
            label = docPath;

        var quality = ExtractRagHitExtractionQualitySignals(src);
        var chunkQuality = ExtractRagHitChunkQualitySignals(src);
        var qualityElement = TryGetObject(src, "extractionQuality") ?? TryGetObject(src, "extraction_quality") ?? TryGetObject(src, "ExtractionQuality");
        var contentSignalsElement =
            TryGetObject(src, "contentSignals")
            ?? TryGetObject(src, "content_signals")
            ?? TryGetObject(src, "ContentSignals")
            ?? TryGetObject(src, "context")
            ?? TryGetObject(src, "Context");
        var diagnosticSummary = TryBuildSourceExtractionDiagnosticRef(src, qualityElement);
        var extractionSource = qualityElement.HasValue
            ? TryGetString(qualityElement.Value, "extractionSource") ?? TryGetString(qualityElement.Value, "extraction_source") ?? TryGetString(qualityElement.Value, "ExtractionSource")
            : TryGetString(src, "extractionSource") ?? TryGetString(src, "extraction_source") ?? TryGetString(src, "ExtractionSource");
        var documentQualityStatus = qualityElement.HasValue
            ? TryGetString(qualityElement.Value, "documentQualityStatus") ?? TryGetString(qualityElement.Value, "document_quality_status") ?? TryGetString(qualityElement.Value, "DocumentQualityStatus")
            : TryGetString(src, "documentQualityStatus") ?? TryGetString(src, "document_quality_status") ?? TryGetString(src, "DocumentQualityStatus");
        var pageQualityStatus = qualityElement.HasValue
            ? TryGetString(qualityElement.Value, "pageQualityStatus") ?? TryGetString(qualityElement.Value, "page_quality_status") ?? TryGetString(qualityElement.Value, "PageQualityStatus")
            : TryGetString(src, "pageQualityStatus") ?? TryGetString(src, "page_quality_status") ?? TryGetString(src, "PageQualityStatus");
        var textStatus = qualityElement.HasValue
            ? TryGetString(qualityElement.Value, "textStatus") ?? TryGetString(qualityElement.Value, "text_status") ?? TryGetString(qualityElement.Value, "TextStatus")
            : TryGetString(src, "textStatus") ?? TryGetString(src, "text_status") ?? TryGetString(src, "TextStatus");
        var ocrAttempted = qualityElement.HasValue
            ? TryGetBool(qualityElement.Value, "ocrAttempted") ?? TryGetBool(qualityElement.Value, "ocr_attempted") ?? TryGetBool(qualityElement.Value, "OcrAttempted") ?? TryGetBool(qualityElement.Value, "OCRAttempted") ?? false
            : TryGetBool(src, "ocrAttempted") ?? TryGetBool(src, "ocr_attempted") ?? TryGetBool(src, "OcrAttempted") ?? TryGetBool(src, "OCRAttempted") ?? false;
        var ocrRecommended = qualityElement.HasValue
            ? TryGetBool(qualityElement.Value, "ocrRecommended") ?? TryGetBool(qualityElement.Value, "ocr_recommended") ?? TryGetBool(qualityElement.Value, "OcrRecommended") ?? false
            : TryGetBool(src, "ocrRecommended") ?? TryGetBool(src, "ocr_recommended") ?? TryGetBool(src, "OcrRecommended") ?? false;
        var signals = (quality.Signals ?? Array.Empty<string>())
            .Concat(qualityElement.HasValue ? ExtractCompactSignals(qualityElement.Value, "signals") : Array.Empty<string>())
            .Concat(qualityElement.HasValue ? ExtractCompactSignals(qualityElement.Value, "Signals") : Array.Empty<string>())
            .Where(static signal => !string.IsNullOrWhiteSpace(signal))
            .Select(static signal => signal.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();
        var chunkSignals = (chunkQuality.Signals ?? Array.Empty<string>())
            .Where(static signal => !string.IsNullOrWhiteSpace(signal))
            .Select(static signal => signal.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToList();

        var cards = ExtractRagHitMatchedContentCards(src)?
            .Where(static card => !string.IsNullOrWhiteSpace(card.Title))
            .Select(static card => new ToolMemory.SourceContentCardRef
            {
                Title = card.Title,
                ContentCardId = NullIfWhiteSpace(card.ContentCardId),
                PageStart = card.PageStart,
                PageEnd = card.PageEnd,
                Kind = NullIfWhiteSpace(card.Kind),
                Signals = card.Signals?
                    .Where(static signal => !string.IsNullOrWhiteSpace(signal))
                    .Select(static signal => signal.Trim())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Take(8)
                    .ToList() ?? new List<string>(),
                Evidence = GetSourceContentCardEvidenceElement(card)
            })
            .Take(5)
            .ToList() ?? new List<ToolMemory.SourceContentCardRef>();
        var selectionHints = TryGetObject(src, "selectionHints") ?? TryGetObject(src, "selection_hints") ?? TryGetObject(src, "SelectionHints");
        var provenanceInfo = TryGetObject(src, "provenanceInfo") ?? TryGetObject(src, "provenance_info") ?? TryGetObject(src, "ProvenanceInfo");
        var sectionTitle = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "sectionTitle") ?? TryGetString(contentSignalsElement.Value, "section_title") ?? TryGetString(contentSignalsElement.Value, "SectionTitle")
            : null;
        sectionTitle ??= TryGetString(src, "sectionTitle") ?? TryGetString(src, "section_title") ?? TryGetString(src, "SectionTitle");
        var headingPath = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "headingPath") ?? TryGetString(contentSignalsElement.Value, "heading_path") ?? TryGetString(contentSignalsElement.Value, "HeadingPath")
            : null;
        headingPath ??= TryGetString(src, "headingPath") ?? TryGetString(src, "heading_path") ?? TryGetString(src, "HeadingPath");
        var prevChunkId = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "prevChunkId") ?? TryGetString(contentSignalsElement.Value, "prev_chunk_id") ?? TryGetString(contentSignalsElement.Value, "PrevChunkId")
            : null;
        prevChunkId ??= TryGetString(src, "prevChunkId") ?? TryGetString(src, "prev_chunk_id") ?? TryGetString(src, "PrevChunkId");
        var nextChunkId = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "nextChunkId") ?? TryGetString(contentSignalsElement.Value, "next_chunk_id") ?? TryGetString(contentSignalsElement.Value, "NextChunkId")
            : null;
        nextChunkId ??= TryGetString(src, "nextChunkId") ?? TryGetString(src, "next_chunk_id") ?? TryGetString(src, "NextChunkId");
        var sameSectionChunkId = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "sameSectionChunkId") ?? TryGetString(contentSignalsElement.Value, "same_section_chunk_id") ?? TryGetString(contentSignalsElement.Value, "SameSectionChunkId")
            : null;
        sameSectionChunkId ??= TryGetString(src, "sameSectionChunkId") ?? TryGetString(src, "same_section_chunk_id") ?? TryGetString(src, "SameSectionChunkId");
        var originalChunkType = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "originalChunkType") ?? TryGetString(contentSignalsElement.Value, "original_chunk_type") ?? TryGetString(contentSignalsElement.Value, "OriginalChunkType")
            : null;
        originalChunkType ??= TryGetString(src, "originalChunkType") ?? TryGetString(src, "original_chunk_type") ?? TryGetString(src, "OriginalChunkType");
        var offsetStart = provenanceInfo.HasValue
            ? TryGetInt(provenanceInfo.Value, "offsetStart") ?? TryGetInt(provenanceInfo.Value, "offset_start") ?? TryGetInt(provenanceInfo.Value, "OffsetStart")
            : null;
        offsetStart ??= TryGetInt(src, "offsetStart") ?? TryGetInt(src, "offset_start") ?? TryGetInt(src, "OffsetStart");
        var offsetEnd = provenanceInfo.HasValue
            ? TryGetInt(provenanceInfo.Value, "offsetEnd") ?? TryGetInt(provenanceInfo.Value, "offset_end") ?? TryGetInt(provenanceInfo.Value, "OffsetEnd")
            : null;
        offsetEnd ??= TryGetInt(src, "offsetEnd") ?? TryGetInt(src, "offset_end") ?? TryGetInt(src, "OffsetEnd");
        var contentRole = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "contentRole") ?? TryGetString(contentSignalsElement.Value, "content_role") ?? TryGetString(contentSignalsElement.Value, "ContentRole")
            : null;
        contentRole ??= TryGetString(src, "contentRole") ?? TryGetString(src, "content_role") ?? TryGetString(src, "ContentRole");
        var navigationReason = contentSignalsElement.HasValue
            ? TryGetString(contentSignalsElement.Value, "navigationReason") ?? TryGetString(contentSignalsElement.Value, "navigation_reason") ?? TryGetString(contentSignalsElement.Value, "NavigationReason")
            : null;
        navigationReason ??= TryGetString(src, "navigationReason") ?? TryGetString(src, "navigation_reason") ?? TryGetString(src, "NavigationReason");
        var retrievalNavigationScore = contentSignalsElement.HasValue
            ? TryGetDouble(contentSignalsElement.Value, "retrievalNavigationScore") ?? TryGetDouble(contentSignalsElement.Value, "retrieval_navigation_score") ?? TryGetDouble(contentSignalsElement.Value, "RetrievalNavigationScore") ?? TryGetDouble(contentSignalsElement.Value, "navigationScore") ?? TryGetDouble(contentSignalsElement.Value, "navigation_score") ?? TryGetDouble(contentSignalsElement.Value, "NavigationScore")
            : null;
        retrievalNavigationScore ??= TryGetDouble(src, "retrievalNavigationScore") ?? TryGetDouble(src, "retrieval_navigation_score") ?? TryGetDouble(src, "RetrievalNavigationScore") ?? TryGetDouble(src, "navigationScore") ?? TryGetDouble(src, "navigation_score") ?? TryGetDouble(src, "NavigationScore");
        var contentDensityScore = contentSignalsElement.HasValue
            ? TryGetDouble(contentSignalsElement.Value, "contentDensityScore") ?? TryGetDouble(contentSignalsElement.Value, "content_density_score") ?? TryGetDouble(contentSignalsElement.Value, "ContentDensityScore")
            : null;
        contentDensityScore ??= TryGetDouble(src, "contentDensityScore") ?? TryGetDouble(src, "content_density_score") ?? TryGetDouble(src, "ContentDensityScore");

        return new ToolMemory.SourceRef
        {
            DocId = NullIfWhiteSpace(TryGetString(src, "docId") ?? TryGetString(src, "doc_id") ?? TryGetString(src, "DocId")),
            DocPath = docPath.Replace('\\', '/'),
            DocName = docName,
            PageStart = ps,
            PageEnd = pe,
            Label = label,
            SourceHash = NullIfWhiteSpace(TryGetString(src, "sourceHash") ?? TryGetString(src, "source_hash") ?? TryGetString(src, "SourceHash")),
            DocLanguage = NullIfWhiteSpace(TryGetDocumentLanguage(src)),
            ProfileLanguage = NullIfWhiteSpace(TryGetString(src, "profileLanguage") ?? TryGetString(src, "profile_language") ?? TryGetString(src, "ProfileLanguage")),
            Category = NullIfWhiteSpace(TryGetString(src, "category") ?? TryGetString(src, "Category")),
            CategoryRef = NullIfWhiteSpace(TryGetString(src, "categoryRef") ?? TryGetString(src, "category_ref") ?? TryGetString(src, "CategoryRef")),
            CategoryPath = NullIfWhiteSpace(TryGetString(src, "categoryPath") ?? TryGetString(src, "category_path") ?? TryGetString(src, "CategoryPath")),
            ChunkId = NullIfWhiteSpace(TryGetString(src, "chunkId") ?? TryGetString(src, "chunk_id") ?? TryGetString(src, "ChunkId")),
            SectionTitle = NullIfWhiteSpace(sectionTitle),
            HeadingPath = NullIfWhiteSpace(headingPath),
            PrevChunkId = NullIfWhiteSpace(prevChunkId),
            NextChunkId = NullIfWhiteSpace(nextChunkId),
            SameSectionChunkId = NullIfWhiteSpace(sameSectionChunkId),
            OriginalChunkType = NullIfWhiteSpace(originalChunkType),
            OffsetStart = offsetStart,
            OffsetEnd = offsetEnd,
            ExtractionSource = NullIfWhiteSpace(extractionSource),
            DocumentQualityStatus = NullIfWhiteSpace(documentQualityStatus),
            PageQualityStatus = NullIfWhiteSpace(pageQualityStatus),
            TextStatus = NullIfWhiteSpace(textStatus),
            ChunkTextStatus = NullIfWhiteSpace(chunkQuality.ChunkTextStatus),
            ChunkTextSparse = chunkQuality.ChunkTextSparse,
            ChunkOcrCandidate = chunkQuality.ChunkOcrCandidate,
            QualityStatus = NullIfWhiteSpace(quality.QualityStatus ?? pageQualityStatus ?? documentQualityStatus),
            ExtractionConfidence = quality.ExtractionConfidence,
            DocumentExtractionConfidence = quality.DocumentExtractionConfidence,
            PageExtractionConfidence = quality.PageExtractionConfidence,
            ManualReviewRecommended = quality.ManualReviewRecommended,
            DocumentManualReviewRecommended = quality.DocumentManualReviewRecommended,
            PageManualReviewRecommended = quality.PageManualReviewRecommended,
            OcrAttempted = ocrAttempted,
            OcrApplied = quality.OcrApplied,
            OcrRecommended = ocrRecommended,
            ExtractionDiagnosticSummary = diagnosticSummary,
            QualitySignals = signals,
            ChunkQualitySignals = chunkSignals,
            MatchedContentCards = cards,
            ProfileSignals = BuildSourceProfileSignalsRef(src),
            SelectionHintEvidenceRole = selectionHints.HasValue
                ? NullIfWhiteSpace(TryGetString(selectionHints.Value, "evidenceRole") ?? TryGetString(selectionHints.Value, "evidence_role") ?? TryGetString(selectionHints.Value, "EvidenceRole"))
                : null,
            SelectionHintActionabilityScore = selectionHints.HasValue
                ? TryGetInt(selectionHints.Value, "actionabilityScore") ?? TryGetInt(selectionHints.Value, "actionability_score") ?? TryGetInt(selectionHints.Value, "ActionabilityScore")
                : null,
            SelectionHintSupportScore = selectionHints.HasValue
                ? TryGetInt(selectionHints.Value, "supportScore") ?? TryGetInt(selectionHints.Value, "support_score") ?? TryGetInt(selectionHints.Value, "SupportScore")
                : null,
            SelectionHintFragmentScore = selectionHints.HasValue
                ? TryGetInt(selectionHints.Value, "fragmentScore") ?? TryGetInt(selectionHints.Value, "fragment_score") ?? TryGetInt(selectionHints.Value, "FragmentScore")
                : null,
            SelectionHintNavigationScore = selectionHints.HasValue
                ? TryGetInt(selectionHints.Value, "navigationScore") ?? TryGetInt(selectionHints.Value, "navigation_score") ?? TryGetInt(selectionHints.Value, "NavigationScore")
                : null,
            SelectionHintQualityPenalty = selectionHints.HasValue
                ? TryGetInt(selectionHints.Value, "qualityPenalty") ?? TryGetInt(selectionHints.Value, "quality_penalty") ?? TryGetInt(selectionHints.Value, "QualityPenalty")
                : null,
            ContentRole = NullIfWhiteSpace(contentRole),
            NavigationReason = NullIfWhiteSpace(navigationReason),
            RetrievalNavigationScore = retrievalNavigationScore,
            ContentDensityScore = contentDensityScore
        };
    }

    private static string? TryGetDocumentLanguage(JsonElement value)
        => TryGetString(value, "docLanguage")
           ?? TryGetString(value, "doc_language")
           ?? TryGetString(value, "DocLanguage")
           ?? TryGetString(value, "documentLanguage")
           ?? TryGetString(value, "document_language")
           ?? TryGetString(value, "DocumentLanguage")
           ?? TryGetString(value, "sourceLanguage")
           ?? TryGetString(value, "source_language")
           ?? TryGetString(value, "SourceLanguage");

    private static List<ToolMemory.SourceRef> DeriveSourcesFromRagHits(ToolResults toolResults)
    {
        try
        {
            // Accept both rag.search and rag.multi_search results.
            var candidates = toolResults.Items
                .Where(x => x.ToolName is "rag.search" or "rag.multi_search")
                .Select(x => x.Result)
                .ToList();

            var sources = new List<ToolMemory.SourceRef>();
            foreach (var res in candidates)
            {
                if (res.ValueKind != JsonValueKind.Object) continue;
                if (!res.TryGetProperty("hits", out var hits) || hits.ValueKind != JsonValueKind.Array) continue;

                foreach (var h in hits.EnumerateArray()
                    .Where(static h => h.ValueKind == JsonValueKind.Object)
                    .Select(static h => BuildRagHitSummary(h))
                    .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
                    .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit)))
                {
                    if (string.IsNullOrWhiteSpace(h.DocPath)) continue;
                    sources.Add(BuildSourceRefFromRagHit(h));
                }
            }

            return MergeSourceRefsByPage(sources)
                .Take(8)
                .ToList();
        }
        catch
        {
            return new List<ToolMemory.SourceRef>();
        }
    }

    private static bool HasRagHits(JsonElement result)
    {
        return result.ValueKind == JsonValueKind.Object
            && result.TryGetProperty("hits", out var hits)
            && hits.ValueKind == JsonValueKind.Array
            && hits.GetArrayLength() > 0;
    }

    private static int CountRagHits(JsonElement result)
    {
        return result.ValueKind == JsonValueKind.Object
            && result.TryGetProperty("hits", out var hits)
            && hits.ValueKind == JsonValueKind.Array
            ? hits.GetArrayLength()
            : 0;
    }

    private static List<ToolMemory.SourceRef> DeriveSourcesFromPlanningHits(ToolResults toolResults, string? query = null)
    {
        var planningSources = SelectSourceBackedPlanningCandidates(
                toolResults,
                query,
                ResolveSourceBackedPlanningTargetItemCount(query))
            .Select(candidate => candidate.Hit)
            .GroupBy(hit => $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .Take(8)
            .Select(BuildSourceRefFromRagHit)
            .ToList();

        return planningSources.Count > 0
            ? planningSources
            : DeriveSourcesFromRagHits(toolResults).Take(8).ToList();
    }

    private static string? TryInferDominantTopLevelCategoryScope(ToolResults toolResults, string? query = null)
    {
        var hits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();
        if (hits.Count == 0)
            return null;

        var grouped = hits
            .Select(hit => new
            {
                Hit = hit,
                TopLevel = ExtractTopLevelCategoryScope(hit)
            })
            .Where(static item => !string.IsNullOrWhiteSpace(item.TopLevel))
            .GroupBy(static item => item.TopLevel!, StringComparer.OrdinalIgnoreCase)
            .Select(group => new
            {
                Scope = group.Key,
                Count = group.Count(),
                MaxScore = group.Max(static item => item.Hit.Score),
                QueryRelevance = group.Max(item => ComputeRagHitLexicalRelevance(query ?? string.Empty, GetRagHitLookupText(item.Hit)))
            })
            .OrderByDescending(static group => group.Count)
            .ThenByDescending(static group => group.QueryRelevance)
            .ThenByDescending(static group => group.MaxScore)
            .ToList();

        var best = grouped.FirstOrDefault();
        if (best is null)
            return null;

        return best.Count >= 2 || grouped.Count == 1
            ? best.Scope
            : null;
    }

    private static string? ExtractTopLevelCategoryScope(RagHitSummary hit)
    {
        var path = CollapseWhitespace(hit.CategoryPath ?? string.Empty);
        if (string.IsNullOrWhiteSpace(path))
            path = CollapseWhitespace(hit.DocPath ?? string.Empty);
        if (string.IsNullOrWhiteSpace(path))
            return null;

        path = path.Replace('\\', '/').Trim('/');
        var first = path.Split('/', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).FirstOrDefault();
        if (string.IsNullOrWhiteSpace(first) || first.Contains(".pdf", StringComparison.OrdinalIgnoreCase))
            return null;

        return first;
    }

    private static List<ToolMemory.SourceRef> DeriveSourcesFromOptionHits(ToolResults toolResults, string? query = null)
    {
        var optionHits = SelectSourceBackedOptionAnswerCandidates(toolResults, query, minItems: 1).Items
            .Select(candidate => candidate.Hit)
            .GroupBy(hit => $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .Take(5)
            .Select(BuildSourceRefFromRagHit)
            .ToList();

        return optionHits.Count > 0
            ? optionHits
            : DeriveSourcesFromPlanningHits(toolResults, query);
    }

    private static List<ToolMemory.SourceRef> DeriveSourcesFromCountdownPlanningHits(ToolResults toolResults, string? query = null)
    {
        var countdownHits = SelectSourceBackedCountdownPlanningCandidates(toolResults, query)
            .Where(candidate => candidate.VisibleMinutes.HasValue)
            .OrderByDescending(candidate => candidate.VisibleMinutes!.Value)
            .ThenByDescending(candidate => candidate.Score)
            .Select(candidate => candidate.Hit)
            .GroupBy(hit => $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .Take(5)
            .Select(BuildSourceRefFromRagHit)
            .ToList();

        return countdownHits.Count > 0
            ? countdownHits
            : DeriveSourcesFromExtractiveHits(toolResults, query ?? string.Empty);
    }

    private static ToolMemory.SourceRef BuildSourceRefFromRagHit(RagHitSummary hit)
    {
        var label = string.IsNullOrWhiteSpace(hit.DocName) ? Path.GetFileName(hit.DocPath) : hit.DocName;
        return new ToolMemory.SourceRef
        {
            DocId = NullIfWhiteSpace(hit.DocId),
            DocPath = hit.DocPath.Replace('\\', '/'),
            DocName = NullIfWhiteSpace(hit.DocName) ?? NullIfWhiteSpace(Path.GetFileName(hit.DocPath)),
            PageStart = hit.PageStart,
            PageEnd = hit.PageEnd,
            Label = label,
            SourceHash = NullIfWhiteSpace(hit.SourceHash),
            DocLanguage = NullIfWhiteSpace(hit.DocLanguage),
            ProfileLanguage = NullIfWhiteSpace(hit.ProfileLanguage),
            Category = NullIfWhiteSpace(hit.Category),
            CategoryRef = NullIfWhiteSpace(hit.CategoryRef),
            CategoryPath = NullIfWhiteSpace(hit.CategoryPath),
            ChunkId = NullIfWhiteSpace(hit.ChunkId),
            SectionTitle = NullIfWhiteSpace(hit.SectionTitle),
            HeadingPath = NullIfWhiteSpace(hit.HeadingPath),
            PrevChunkId = NullIfWhiteSpace(hit.PrevChunkId),
            NextChunkId = NullIfWhiteSpace(hit.NextChunkId),
            SameSectionChunkId = NullIfWhiteSpace(hit.SameSectionChunkId),
            OriginalChunkType = NullIfWhiteSpace(hit.OriginalChunkType),
            OffsetStart = hit.OffsetStart,
            OffsetEnd = hit.OffsetEnd,
            ExtractionSource = NullIfWhiteSpace(hit.ExtractionSource),
            DocumentQualityStatus = NullIfWhiteSpace(hit.DocumentQualityStatus),
            PageQualityStatus = NullIfWhiteSpace(hit.PageQualityStatus),
            TextStatus = NullIfWhiteSpace(hit.TextStatus),
            ChunkTextStatus = NullIfWhiteSpace(hit.ChunkTextStatus),
            ChunkTextSparse = hit.ChunkTextSparse,
            ChunkOcrCandidate = hit.ChunkOcrCandidate,
            QualityStatus = NullIfWhiteSpace(hit.QualityStatus),
            ExtractionConfidence = hit.ExtractionConfidence,
            DocumentExtractionConfidence = hit.DocumentExtractionConfidence,
            PageExtractionConfidence = hit.PageExtractionConfidence,
            ManualReviewRecommended = hit.ManualReviewRecommended,
            DocumentManualReviewRecommended = hit.DocumentManualReviewRecommended,
            PageManualReviewRecommended = hit.PageManualReviewRecommended,
            OcrAttempted = hit.OcrAttempted,
            OcrApplied = hit.OcrApplied,
            OcrRecommended = hit.OcrRecommended,
            ExtractionDiagnosticSummary = CloneSourceExtractionDiagnostic(hit.ExtractionDiagnosticSummary),
            QualitySignals = hit.QualitySignals?
                .Where(static signal => !string.IsNullOrWhiteSpace(signal))
                .Select(static signal => signal.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList() ?? new List<string>(),
            ChunkQualitySignals = hit.ChunkQualitySignals?
                .Where(static signal => !string.IsNullOrWhiteSpace(signal))
                .Select(static signal => signal.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList() ?? new List<string>(),
            MatchedContentCards = hit.MatchedContentCards?
                .Where(static card => !string.IsNullOrWhiteSpace(card.Title))
                .Select(static card => new ToolMemory.SourceContentCardRef
                {
                    Title = card.Title,
                    ContentCardId = NullIfWhiteSpace(card.ContentCardId),
                    PageStart = card.PageStart,
                    PageEnd = card.PageEnd,
                    Kind = NullIfWhiteSpace(card.Kind),
                    Signals = card.Signals?
                        .Where(static signal => !string.IsNullOrWhiteSpace(signal))
                        .Select(static signal => signal.Trim())
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .Take(8)
                        .ToList() ?? new List<string>(),
                    Evidence = GetSourceContentCardEvidenceElement(card)
                })
                .Take(5)
                .ToList() ?? new List<ToolMemory.SourceContentCardRef>(),
            ProfileSignals = CloneSourceProfileSignalsRef(hit.ProfileSignals),
            SelectionHintEvidenceRole = NullIfWhiteSpace(hit.SelectionHintRole),
            SelectionHintActionabilityScore = hit.SelectionHintActionabilityScore,
            SelectionHintSupportScore = hit.SelectionHintSupportScore,
            SelectionHintFragmentScore = hit.SelectionHintFragmentScore,
            SelectionHintNavigationScore = hit.SelectionHintNavigationScore,
            SelectionHintQualityPenalty = hit.SelectionHintQualityPenalty,
            ContentRole = NullIfWhiteSpace(hit.ContentRole),
            NavigationReason = NullIfWhiteSpace(hit.NavigationReason),
            RetrievalNavigationScore = hit.NavigationScore,
            ContentDensityScore = hit.ContentDensityScore
        };
    }

    private static List<ToolMemory.SourceRef> MergeSourceRefsByPage(IEnumerable<ToolMemory.SourceRef> sources, int maxCardsPerSource = 5)
    {
        var candidates = sources
            .Where(static source => !string.IsNullOrWhiteSpace(source.DocPath))
            .ToList();
        CanonicalizeFilenameOnlySourceRefAliases(candidates);

        return candidates
            .GroupBy(
                BuildSourceRefVisiblePageMergeKey,
                StringComparer.OrdinalIgnoreCase)
            .Select(group => MergeSourceRefGroup(group, maxCardsPerSource))
            .OrderByDescending(ComputeSourceRefRichness)
            .ToList();
    }

    private static List<ToolMemory.SourceRef> MergeSourceRefsByPagePreservingOrder(IEnumerable<ToolMemory.SourceRef> sources, int maxCardsPerSource = 5)
    {
        var candidates = sources
            .Where(static source => !string.IsNullOrWhiteSpace(source.DocPath))
            .ToList();
        CanonicalizeFilenameOnlySourceRefAliases(candidates);

        var groups = new List<List<ToolMemory.SourceRef>>();
        var indexByKey = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        foreach (var source in candidates)
        {
            var key = BuildSourceRefVisiblePageMergeKey(source);
            if (!indexByKey.TryGetValue(key, out var index))
            {
                index = groups.Count;
                indexByKey[key] = index;
                groups.Add(new List<ToolMemory.SourceRef>());
            }

            groups[index].Add(source);
        }

        return groups
            .Where(static group => group.Count > 0)
            .Select(group => MergeSourceRefGroup(group, maxCardsPerSource, preserveVisibleIdentity: true))
            .ToList();
    }

    private static List<ToolMemory.SourceRef> NormalizeVisibleSourceRefsForMemory(IEnumerable<ToolMemory.SourceRef>? sources)
        => sources is null
            ? new List<ToolMemory.SourceRef>()
            : MergeSourceRefsByPagePreservingOrder(sources);

    private static void CanonicalizeFilenameOnlySourceRefAliases(List<ToolMemory.SourceRef> sources)
    {
        foreach (var source in sources)
        {
            var normalizedPath = NormalizeVisibleSourcePathIdentity(source.DocPath);
            if (string.IsNullOrWhiteSpace(normalizedPath) || normalizedPath.Contains('/'))
                continue;

            var fileName = FirstNonEmptySourceIdentity(Path.GetFileName(source.DocPath ?? string.Empty), source.DocName, source.Label);
            if (string.IsNullOrWhiteSpace(fileName))
                continue;

            var pageStart = Math.Max(1, source.PageStart);
            var pageEnd = Math.Max(pageStart, source.PageEnd);
            var hash = CollapseWhitespace(source.SourceHash ?? string.Empty).ToLowerInvariant();
            var category = FirstNonEmptySourceIdentity(source.CategoryPath, source.Category, source.CategoryRef);

            var matchingPaths = sources
                .Where(candidate => !ReferenceEquals(candidate, source))
                .Where(candidate =>
                {
                    var candidatePath = NormalizeVisibleSourcePathIdentity(candidate.DocPath);
                    if (string.IsNullOrWhiteSpace(candidatePath) || !candidatePath.Contains('/'))
                        return false;

                    var candidateFile = FirstNonEmptySourceIdentity(Path.GetFileName(candidate.DocPath ?? string.Empty), candidate.DocName, candidate.Label);
                    if (!string.Equals(candidateFile, fileName, StringComparison.OrdinalIgnoreCase))
                        return false;

                    var candidatePageStart = Math.Max(1, candidate.PageStart);
                    var candidatePageEnd = Math.Max(candidatePageStart, candidate.PageEnd);
                    if (candidatePageStart != pageStart || candidatePageEnd != pageEnd)
                        return false;

                    var candidateHash = CollapseWhitespace(candidate.SourceHash ?? string.Empty).ToLowerInvariant();
                    if (!string.IsNullOrWhiteSpace(hash)
                        && !string.IsNullOrWhiteSpace(candidateHash)
                        && !string.Equals(hash, candidateHash, StringComparison.OrdinalIgnoreCase))
                    {
                        return false;
                    }

                    var candidateCategory = FirstNonEmptySourceIdentity(candidate.CategoryPath, candidate.Category, candidate.CategoryRef);
                    return string.IsNullOrWhiteSpace(category)
                        || string.IsNullOrWhiteSpace(candidateCategory)
                        || string.Equals(category, candidateCategory, StringComparison.OrdinalIgnoreCase);
                })
                .Select(static candidate => candidate.DocPath)
                .Where(static path => !string.IsNullOrWhiteSpace(path))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(2)
                .ToList();

            if (matchingPaths.Count == 1)
                source.DocPath = matchingPaths[0];
        }
    }

    private static string FirstNonEmptySourceIdentity(params string?[] values)
        => values
            .Select(NormalizeLexicalLookup)
            .FirstOrDefault(static value => !string.IsNullOrWhiteSpace(value)) ?? string.Empty;

    private static string BuildSourceRefVisiblePageMergeKey(ToolMemory.SourceRef source)
    {
        var pageStart = Math.Max(1, source.PageStart);
        var pageEnd = Math.Max(pageStart, source.PageEnd);
        var pagePart = $"p:{pageStart}-{pageEnd}";

        var path = NormalizeVisibleSourcePathIdentity(source.DocPath);
        if (!string.IsNullOrWhiteSpace(path) && LooksLikeQualifiedDocumentPath(source.DocPath))
            return $"path:{path}|{pagePart}";

        var hash = CollapseWhitespace(source.SourceHash ?? string.Empty).ToLowerInvariant();
        if (!string.IsNullOrWhiteSpace(hash))
        {
            var fileName = NormalizeLexicalLookup(Path.GetFileName(source.DocPath ?? string.Empty));
            if (string.IsNullOrWhiteSpace(fileName))
                fileName = NormalizeLexicalLookup(source.DocName);
            var filePart = string.IsNullOrWhiteSpace(fileName) ? "unknown" : fileName;
            return $"hash:{hash}|file:{filePart}|{pagePart}";
        }

        if (!string.IsNullOrWhiteSpace(path))
            return $"path:{path}|{pagePart}";

        var docId = CollapseWhitespace(source.DocId ?? string.Empty).ToLowerInvariant();
        if (!string.IsNullOrWhiteSpace(docId))
            return $"id:{docId}|{pagePart}";

        var visibleName = NormalizeLexicalLookup(source.DocName);
        if (string.IsNullOrWhiteSpace(visibleName))
            visibleName = NormalizeLexicalLookup(source.Label);
        if (!string.IsNullOrWhiteSpace(visibleName))
            return $"name:{visibleName}|{pagePart}";

        return $"unknown:{pagePart}";
    }

    private static string NormalizeVisibleSourcePathIdentity(string? path)
    {
        var normalized = NormalizeLexicalLookup(path).Replace('\\', '/').TrimStart('/');
        if (string.IsNullOrWhiteSpace(normalized))
            return string.Empty;

        var marker = "/documents/";
        var markerIndex = normalized.LastIndexOf(marker, StringComparison.Ordinal);
        if (markerIndex >= 0)
            return normalized[(markerIndex + marker.Length)..].TrimStart('/');

        marker = "saaia-repo/documents/";
        markerIndex = normalized.LastIndexOf(marker, StringComparison.Ordinal);
        if (markerIndex >= 0)
            return normalized[(markerIndex + marker.Length)..].TrimStart('/');

        return normalized;
    }

    private static bool LooksLikeQualifiedDocumentPath(string? path)
        => !string.IsNullOrWhiteSpace(path)
           && (path.Contains('/', StringComparison.Ordinal)
               || path.Contains('\\', StringComparison.Ordinal)
               || path.Contains(':', StringComparison.Ordinal));

    private static ToolMemory.SourceRef MergeSourceRefGroup(
        IEnumerable<ToolMemory.SourceRef> group,
        int maxCardsPerSource,
        bool preserveVisibleIdentity = false)
    {
        var originalSources = group.ToList();
        var sources = originalSources
            .OrderByDescending(ComputeSourceRefRichness)
            .ToList();
        var primary = preserveVisibleIdentity ? originalSources[0] : sources[0];

        return new ToolMemory.SourceRef
        {
            DocId = PickSourceString(sources, static source => source.DocId),
            DocPath = primary.DocPath,
            DocName = PickSourceString(sources, static source => source.DocName),
            PageStart = primary.PageStart,
            PageEnd = primary.PageEnd,
            Label = primary.Label,
            SourceHash = PickSourceString(sources, static source => source.SourceHash),
            DocLanguage = PickSourceString(sources, static source => source.DocLanguage),
            ProfileLanguage = PickSourceString(sources, static source => source.ProfileLanguage),
            Category = PickSourceString(sources, static source => source.Category),
            CategoryRef = PickSourceString(sources, static source => source.CategoryRef),
            CategoryPath = PickSourceString(sources, static source => source.CategoryPath),
            ChunkId = PickSourceString(sources, static source => source.ChunkId),
            SectionTitle = PickSourceString(sources, static source => source.SectionTitle),
            HeadingPath = PickSourceString(sources, static source => source.HeadingPath),
            PrevChunkId = PickSourceString(sources, static source => source.PrevChunkId),
            NextChunkId = PickSourceString(sources, static source => source.NextChunkId),
            SameSectionChunkId = PickSourceString(sources, static source => source.SameSectionChunkId),
            OriginalChunkType = PickSourceString(sources, static source => source.OriginalChunkType),
            OffsetStart = PickSourceInt(sources, static source => source.OffsetStart),
            OffsetEnd = PickSourceInt(sources, static source => source.OffsetEnd),
            ExtractionSource = PickSourceString(sources, static source => source.ExtractionSource),
            DocumentQualityStatus = PickSourceString(sources, static source => source.DocumentQualityStatus),
            PageQualityStatus = PickSourceString(sources, static source => source.PageQualityStatus),
            TextStatus = PickSourceString(sources, static source => source.TextStatus),
            ChunkTextStatus = PickSourceString(sources, static source => source.ChunkTextStatus),
            ChunkTextSparse = PickSourceBool(sources, static source => source.ChunkTextSparse),
            ChunkOcrCandidate = PickSourceBool(sources, static source => source.ChunkOcrCandidate),
            QualityStatus = PickSourceString(sources, static source => source.QualityStatus),
            ExtractionConfidence = PickBestConfidence(sources, static source => source.ExtractionConfidence),
            DocumentExtractionConfidence = PickBestConfidence(sources, static source => source.DocumentExtractionConfidence),
            PageExtractionConfidence = PickBestConfidence(sources, static source => source.PageExtractionConfidence),
            ManualReviewRecommended = sources.Any(static source => source.ManualReviewRecommended),
            DocumentManualReviewRecommended = sources.Any(static source => source.DocumentManualReviewRecommended),
            PageManualReviewRecommended = sources.Any(static source => source.PageManualReviewRecommended),
            OcrAttempted = sources.Any(static source => source.OcrAttempted),
            OcrApplied = sources.Any(static source => source.OcrApplied),
            OcrRecommended = sources.Any(static source => source.OcrRecommended),
            ExtractionDiagnosticSummary = sources
                .Select(static source => CloneSourceExtractionDiagnostic(source.ExtractionDiagnosticSummary))
                .FirstOrDefault(static summary => summary is not null),
            QualitySignals = sources
                .SelectMany(static source => source.QualitySignals)
                .Where(static signal => !string.IsNullOrWhiteSpace(signal))
                .Select(static signal => signal.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList(),
            ChunkQualitySignals = sources
                .SelectMany(static source => source.ChunkQualitySignals)
                .Where(static signal => !string.IsNullOrWhiteSpace(signal))
                .Select(static signal => signal.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList(),
            MatchedContentCards = MergeSourceContentCards(sources, maxCardsPerSource),
            ProfileSignals = MergeSourceProfileSignals(sources),
            SelectionHintEvidenceRole = PickSourceString(sources, static source => source.SelectionHintEvidenceRole),
            SelectionHintActionabilityScore = PickBestScore(sources, static source => source.SelectionHintActionabilityScore),
            SelectionHintSupportScore = PickBestScore(sources, static source => source.SelectionHintSupportScore),
            SelectionHintFragmentScore = PickBestScore(sources, static source => source.SelectionHintFragmentScore),
            SelectionHintNavigationScore = PickBestScore(sources, static source => source.SelectionHintNavigationScore),
            SelectionHintQualityPenalty = PickBestScore(sources, static source => source.SelectionHintQualityPenalty),
            ContentRole = PickBestContentRole(sources),
            NavigationReason = PickSourceString(sources, static source => source.NavigationReason),
            RetrievalNavigationScore = PickLowestDouble(sources, static source => source.RetrievalNavigationScore),
            ContentDensityScore = PickBestConfidence(sources, static source => source.ContentDensityScore)
        };
    }

    private static List<ToolMemory.SourceContentCardRef> MergeSourceContentCards(
        IEnumerable<ToolMemory.SourceRef> sources,
        int maxCards)
        => sources
            .SelectMany(static source => source.MatchedContentCards)
            .Where(static card => !string.IsNullOrWhiteSpace(card.Title))
            .GroupBy(BuildSourceContentCardMergeKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => CloneSourceContentCardRef(
                group
                    .OrderByDescending(ComputeSourceContentCardRichness)
                    .First()))
            .OrderByDescending(ComputeSourceContentCardRichness)
            .Take(maxCards)
            .ToList();

    private static ToolMemory.SourceProfileSignalsRef? MergeSourceProfileSignals(IEnumerable<ToolMemory.SourceRef> sources)
    {
        var profiles = sources
            .Select(static source => source.ProfileSignals)
            .Where(static profile => profile is not null)
            .Select(static profile => profile!)
            .OrderByDescending(ComputeSourceProfileSignalsRichness)
            .ToArray();
        if (profiles.Length == 0)
            return null;

        var primary = profiles[0];
        var merged = new ToolMemory.SourceProfileSignalsRef
        {
            ProfileVersion = NullIfWhiteSpace(primary.ProfileVersion),
            Language = NullIfWhiteSpace(primary.Language),
            Keywords = MergeProfileSignalList(profiles.Select(static profile => profile.Keywords), 8),
            Entities = MergeProfileSignalList(profiles.Select(static profile => profile.Entities), 8),
            Topics = MergeProfileSignalList(profiles.Select(static profile => profile.Topics), 8),
            HypotheticalQuestions = MergeProfileSignalList(profiles.Select(static profile => profile.HypotheticalQuestions), 4),
            Limits = MergeProfileSignalList(profiles.Select(static profile => profile.Limits), 4),
            MatchedTerms = MergeProfileSignalList(profiles.Select(static profile => profile.MatchedTerms), 12),
            MatchCount = profiles
                .Select(static profile => profile.MatchCount)
                .Where(static count => count.HasValue)
                .Select(static count => count!.Value)
                .DefaultIfEmpty()
                .Max()
        };

        return ComputeSourceProfileSignalsRichness(merged) == 0 ? null : merged;
    }

    private static List<string> MergeProfileSignalList(IEnumerable<IEnumerable<string>> lists, int maxItems)
        => lists
            .SelectMany(static list => list)
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CompactClientProfileSignalValue)
            .Where(static value => value.Length >= 2)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(Math.Clamp(maxItems, 1, 24))
            .ToList();

    private static string CompactClientProfileSignalValue(string value)
    {
        var trimmed = value.Trim();
        return trimmed.Length <= 160 ? trimmed : trimmed[..160].TrimEnd();
    }

    private static ToolMemory.SourceContentCardRef CloneSourceContentCardRef(ToolMemory.SourceContentCardRef card)
        => new()
        {
            Title = card.Title,
            ContentCardId = NullIfWhiteSpace(card.ContentCardId),
            PageStart = card.PageStart,
            PageEnd = card.PageEnd,
            Kind = NullIfWhiteSpace(card.Kind),
            Signals = card.Signals
                .Where(static signal => !string.IsNullOrWhiteSpace(signal))
                .Select(static signal => signal.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(8)
                .ToList(),
            Evidence = CloneNullableJsonElement(card.Evidence)
        };

    private static ToolMemory.SourceProfileSignalsRef? CloneSourceProfileSignalsRef(ToolMemory.SourceProfileSignalsRef? profile)
    {
        if (profile is null)
            return null;

        var clone = new ToolMemory.SourceProfileSignalsRef
        {
            ProfileVersion = NullIfWhiteSpace(profile.ProfileVersion),
            Language = NullIfWhiteSpace(profile.Language),
            Keywords = CompactClientProfileSignalList(profile.Keywords, 8),
            Entities = CompactClientProfileSignalList(profile.Entities, 8),
            Topics = CompactClientProfileSignalList(profile.Topics, 8),
            HypotheticalQuestions = CompactClientProfileSignalList(profile.HypotheticalQuestions, 4),
            Limits = CompactClientProfileSignalList(profile.Limits, 4),
            MatchedTerms = CompactClientProfileSignalList(profile.MatchedTerms, 12),
            MatchCount = profile.MatchCount
        };

        return ComputeSourceProfileSignalsRichness(clone) == 0 ? null : clone;
    }

    private static List<string> CompactClientProfileSignalList(IEnumerable<string> values, int maxItems)
        => values
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CompactClientProfileSignalValue)
            .Where(static value => value.Length >= 2)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(Math.Clamp(maxItems, 1, 24))
            .ToList();

    private static JsonElement? GetSourceContentCardEvidenceElement(RagHitContentCardSummary card)
    {
        if (card.RawEvidence is { ValueKind: not JsonValueKind.Null and not JsonValueKind.Undefined } raw)
            return raw.Clone();

        return card.Evidence is null
            ? null
            : JsonSerializer.SerializeToElement(card.Evidence, ClientJson.CamelCase);
    }

    private static JsonElement? CloneNullableJsonElement(JsonElement? value)
        => value is { ValueKind: not JsonValueKind.Null and not JsonValueKind.Undefined } element
            ? element.Clone()
            : null;

    private static ToolMemory.SourceProfileSignalsRef? BuildSourceProfileSignalsRef(JsonElement source)
    {
        var profile = TryGetObject(source, "profileSignals")
                      ?? TryGetObject(source, "profile_signals")
                      ?? TryGetObject(source, "ProfileSignals");
        if (profile is null)
            return null;

        var value = profile.Value;
        var result = new ToolMemory.SourceProfileSignalsRef
        {
            ProfileVersion = NullIfWhiteSpace(TryGetString(value, "profileVersion") ?? TryGetString(value, "profile_version") ?? TryGetString(value, "ProfileVersion")),
            Language = NullIfWhiteSpace(TryGetString(value, "language") ?? TryGetString(value, "Language") ?? TryGetString(value, "profileLanguage") ?? TryGetString(value, "ProfileLanguage")),
            Keywords = ExtractProfileSignalList(value, "keywords", "keywordMatches", "Keywords", "KeywordMatches", maxItems: 8),
            Entities = ExtractProfileSignalList(value, "entities", "entityMatches", "Entities", "EntityMatches", maxItems: 8),
            Topics = ExtractProfileSignalList(value, "topics", "topicMatches", "Topics", "TopicMatches", maxItems: 8),
            HypotheticalQuestions = ExtractProfileSignalList(value, "hypotheticalQuestions", "hypothetical_questions", "HypotheticalQuestions", maxItems: 4),
            Limits = ExtractProfileSignalList(value, "limits", "limitMatches", "Limits", "LimitMatches", maxItems: 4),
            MatchedTerms = ExtractProfileSignalList(value, "matchedTerms", "matched_terms", "MatchedTerms", maxItems: 12),
            MatchCount = TryGetInt(value, "matchCount") ?? TryGetInt(value, "match_count") ?? TryGetInt(value, "MatchCount")
        };

        return ComputeSourceProfileSignalsRichness(result) == 0 ? null : result;
    }

    private static List<string> ExtractProfileSignalList(JsonElement source, string primaryName, string secondaryName, string thirdName, int maxItems)
        => ExtractProfileSignalList(source, primaryName, secondaryName, thirdName, null, maxItems);

    private static List<string> ExtractProfileSignalList(
        JsonElement source,
        string primaryName,
        string secondaryName,
        string thirdName,
        string? fourthName,
        int maxItems)
    {
        var values = ExtractCompactSignals(source, primaryName)
            .Concat(ExtractCompactSignals(source, secondaryName))
            .Concat(ExtractCompactSignals(source, thirdName));
        if (!string.IsNullOrWhiteSpace(fourthName))
            values = values.Concat(ExtractCompactSignals(source, fourthName));

        return values
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CompactClientProfileSignalValue)
            .Where(static value => value.Length >= 2)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(Math.Clamp(maxItems, 1, 24))
            .ToList();
    }

    private static string BuildSourceContentCardMergeKey(ToolMemory.SourceContentCardRef card)
    {
        var id = NullIfWhiteSpace(card.ContentCardId);
        if (!string.IsNullOrWhiteSpace(id))
            return $"id:{id}";

        return string.Join(
            "|",
            "shape",
            CollapseWhitespace(card.Title).ToLowerInvariant(),
            CollapseWhitespace(card.Kind ?? string.Empty).ToLowerInvariant(),
            card.PageStart?.ToString(CultureInfo.InvariantCulture) ?? string.Empty,
            card.PageEnd?.ToString(CultureInfo.InvariantCulture) ?? string.Empty);
    }

    private static int ComputeSourceRefRichness(ToolMemory.SourceRef source)
        => (source.MatchedContentCards.Count * 12)
           + (source.MatchedContentCards.Count(static card => card.Evidence is not null) * 6)
           + (ComputeSourceProfileSignalsRichness(source.ProfileSignals) * 2)
           + (source.QualitySignals.Count * 2)
           + (source.ChunkQualitySignals.Count * 2)
           + (!string.IsNullOrWhiteSpace(source.SourceHash) ? 3 : 0)
           + (!string.IsNullOrWhiteSpace(source.DocLanguage) ? 2 : 0)
           + (!string.IsNullOrWhiteSpace(source.ProfileLanguage) ? 2 : 0)
           + (!string.IsNullOrWhiteSpace(source.Category) ? 1 : 0)
           + (!string.IsNullOrWhiteSpace(source.ChunkId) ? 2 : 0)
           + (!string.IsNullOrWhiteSpace(source.SectionTitle) ? 1 : 0)
           + (!string.IsNullOrWhiteSpace(source.HeadingPath) ? 1 : 0)
           + (source.OffsetStart.HasValue ? 1 : 0)
           + (source.OffsetEnd.HasValue ? 1 : 0)
           + (!string.IsNullOrWhiteSpace(source.ContentRole) ? 2 : 0)
           + (source.ContentDensityScore.HasValue ? 1 : 0)
           + (source.ExtractionDiagnosticSummary is not null ? 2 : 0)
           + (!string.IsNullOrWhiteSpace(source.ChunkTextStatus) ? 2 : 0)
           + (source.ChunkTextSparse.HasValue ? 1 : 0)
           + (source.ChunkOcrCandidate.HasValue ? 1 : 0)
           + (source.SelectionHintActionabilityScore ?? 0)
           + (source.SelectionHintSupportScore ?? 0)
           - (source.SelectionHintNavigationScore ?? 0);

    private static int ComputeSourceProfileSignalsRichness(ToolMemory.SourceProfileSignalsRef? profile)
        => profile is null
            ? 0
            : (string.IsNullOrWhiteSpace(profile.ProfileVersion) ? 0 : 1)
              + (string.IsNullOrWhiteSpace(profile.Language) ? 0 : 1)
              + profile.Keywords.Count
              + profile.Entities.Count
              + profile.Topics.Count
              + profile.HypotheticalQuestions.Count
              + profile.Limits.Count
              + profile.MatchedTerms.Count
              + (profile.MatchCount is > 0 ? 1 : 0);

    private static int ComputeSourceContentCardRichness(ToolMemory.SourceContentCardRef card)
        => (!string.IsNullOrWhiteSpace(card.ContentCardId) ? 8 : 0)
           + (card.Evidence is not null ? 8 : 0)
           + (card.Signals.Count * 2)
           + (card.PageStart.HasValue ? 1 : 0)
           + (card.PageEnd.HasValue ? 1 : 0);

    private static string? PickSourceString(
        IEnumerable<ToolMemory.SourceRef> sources,
        Func<ToolMemory.SourceRef, string?> selector)
        => sources
            .Select(selector)
            .FirstOrDefault(static value => !string.IsNullOrWhiteSpace(value))?
            .Trim();

    private static double? PickBestConfidence(
        IEnumerable<ToolMemory.SourceRef> sources,
        Func<ToolMemory.SourceRef, double?> selector)
        => sources
            .Select(selector)
            .Where(static value => value.HasValue)
            .Select(static value => value!.Value)
            .DefaultIfEmpty()
            .Max() is var value && value > 0.0
                ? value
                : null;

    private static int? PickBestScore(
        IEnumerable<ToolMemory.SourceRef> sources,
        Func<ToolMemory.SourceRef, int?> selector)
        => sources
            .Select(selector)
            .Where(static value => value.HasValue)
            .Select(static value => value!.Value)
            .DefaultIfEmpty()
            .Max() is var value && value != 0
                ? value
                : null;

    private static int? PickSourceInt(
        IEnumerable<ToolMemory.SourceRef> sources,
        Func<ToolMemory.SourceRef, int?> selector)
        => sources
            .Select(selector)
            .FirstOrDefault(static value => value.HasValue);

    private static bool? PickSourceBool(
        IEnumerable<ToolMemory.SourceRef> sources,
        Func<ToolMemory.SourceRef, bool?> selector)
        => sources
            .Select(selector)
            .FirstOrDefault(static value => value.HasValue);

    private static double? PickLowestDouble(
        IEnumerable<ToolMemory.SourceRef> sources,
        Func<ToolMemory.SourceRef, double?> selector)
    {
        var values = sources
            .Select(selector)
            .Where(static value => value.HasValue)
            .Select(static value => value!.Value)
            .ToArray();
        return values.Length == 0 ? null : values.Min();
    }

    private static string? PickBestContentRole(IEnumerable<ToolMemory.SourceRef> sources)
    {
        var roles = sources
            .Select(static source => NullIfWhiteSpace(source.ContentRole))
            .Where(static role => !string.IsNullOrWhiteSpace(role))
            .ToArray();
        if (roles.Length == 0)
            return null;

        if (roles.Any(static role => string.Equals(role, "content", StringComparison.OrdinalIgnoreCase)))
            return "content";
        if (roles.Any(static role => string.Equals(role, "mixed_navigation_content", StringComparison.OrdinalIgnoreCase)))
            return "mixed_navigation_content";
        return roles[0];
    }

    private static object BuildSourcesPayload(List<ToolMemory.SourceRef> sources)
    {
        var mergedSources = MergeSourceRefsByPagePreservingOrder(sources);
        return new
        {
            sources = mergedSources.Select(x => new
            {
                docId = x.DocId,
                docPath = x.DocPath,
                docName = x.DocName,
                pageStart = x.PageStart,
                pageEnd = x.PageEnd,
                label = x.Label,
                sourceHash = x.SourceHash,
                docLanguage = x.DocLanguage,
                profileLanguage = x.ProfileLanguage,
                category = x.Category,
                categoryRef = x.CategoryRef,
                categoryPath = x.CategoryPath,
                chunkId = x.ChunkId,
                sectionTitle = x.SectionTitle,
                headingPath = x.HeadingPath,
                prevChunkId = x.PrevChunkId,
                nextChunkId = x.NextChunkId,
                sameSectionChunkId = x.SameSectionChunkId,
                originalChunkType = x.OriginalChunkType,
                provenanceInfo = BuildSourceProvenancePayload(x),
                contentSignals = BuildSourceContentSignalsPayload(x),
                extractionQuality = BuildSourceExtractionQualityPayload(x),
                matchedContentCards = BuildSourceContentCardsPayload(x),
                profileSignals = BuildSourceProfileSignalsPayload(x),
                selectionHints = BuildSourceSelectionHintsPayload(x)
            }).ToList()
        };
    }

    private static object BuildSourcesPayload(string intent, List<ToolMemory.SourceRef> sources)
        => new
        {
            intent,
            sources = BuildSourcePayloadItems(sources)
        };

    private static List<object> BuildSourcePayloadItems(List<ToolMemory.SourceRef> sources)
        => MergeSourceRefsByPagePreservingOrder(sources).Select(x => new
        {
            docId = x.DocId,
            docPath = x.DocPath,
            docName = x.DocName,
            pageStart = x.PageStart,
            pageEnd = x.PageEnd,
            label = x.Label,
            sourceHash = x.SourceHash,
            docLanguage = x.DocLanguage,
            profileLanguage = x.ProfileLanguage,
            category = x.Category,
            categoryRef = x.CategoryRef,
            categoryPath = x.CategoryPath,
            chunkId = x.ChunkId,
            sectionTitle = x.SectionTitle,
            headingPath = x.HeadingPath,
            prevChunkId = x.PrevChunkId,
            nextChunkId = x.NextChunkId,
            sameSectionChunkId = x.SameSectionChunkId,
            originalChunkType = x.OriginalChunkType,
            provenanceInfo = BuildSourceProvenancePayload(x),
            contentSignals = BuildSourceContentSignalsPayload(x),
            extractionQuality = BuildSourceExtractionQualityPayload(x),
            matchedContentCards = BuildSourceContentCardsPayload(x),
            profileSignals = BuildSourceProfileSignalsPayload(x),
            selectionHints = BuildSourceSelectionHintsPayload(x)
        }).Cast<object>().ToList();

    private static object? BuildSourceContentSignalsPayload(ToolMemory.SourceRef source)
        => string.IsNullOrWhiteSpace(source.ContentRole)
           && string.IsNullOrWhiteSpace(source.NavigationReason)
           && source.RetrievalNavigationScore is null
           && source.ContentDensityScore is null
            ? null
            : new
            {
                contentRole = source.ContentRole,
                navigationReason = source.NavigationReason,
                navigationScore = source.RetrievalNavigationScore,
                contentDensityScore = source.ContentDensityScore
            };

    private static object? BuildSourceProvenancePayload(ToolMemory.SourceRef source)
        => source.OffsetStart is null && source.OffsetEnd is null
            ? null
            : new
            {
                offsetStart = source.OffsetStart,
                offsetEnd = source.OffsetEnd
            };

    private static object? BuildSourceSelectionHintsPayload(ToolMemory.SourceRef source)
        => string.IsNullOrWhiteSpace(source.SelectionHintEvidenceRole)
           && source.SelectionHintActionabilityScore is null
           && source.SelectionHintSupportScore is null
           && source.SelectionHintFragmentScore is null
           && source.SelectionHintNavigationScore is null
           && source.SelectionHintQualityPenalty is null
            ? null
            : new
            {
                evidenceRole = source.SelectionHintEvidenceRole,
                actionabilityScore = source.SelectionHintActionabilityScore,
                supportScore = source.SelectionHintSupportScore,
                fragmentScore = source.SelectionHintFragmentScore,
                navigationScore = source.SelectionHintNavigationScore,
                qualityPenalty = source.SelectionHintQualityPenalty
            };

    private static object? BuildSourceProfileSignalsPayload(ToolMemory.SourceRef source)
    {
        var profile = source.ProfileSignals;
        if (profile is null || ComputeSourceProfileSignalsRichness(profile) == 0)
            return null;

        return new
        {
            profileVersion = profile.ProfileVersion,
            language = profile.Language,
            keywords = profile.Keywords.Count == 0 ? null : profile.Keywords,
            entities = profile.Entities.Count == 0 ? null : profile.Entities,
            topics = profile.Topics.Count == 0 ? null : profile.Topics,
            hypotheticalQuestions = profile.HypotheticalQuestions.Count == 0 ? null : profile.HypotheticalQuestions,
            limits = profile.Limits.Count == 0 ? null : profile.Limits,
            matchedTerms = profile.MatchedTerms.Count == 0 ? null : profile.MatchedTerms,
            matchCount = profile.MatchCount
        };
    }

    private static object? BuildSourceExtractionQualityPayload(ToolMemory.SourceRef source)
    {
        var diagnosticSummary = BuildSourceExtractionDiagnosticPayload(source.ExtractionDiagnosticSummary);
        if (string.IsNullOrWhiteSpace(source.QualityStatus)
            && string.IsNullOrWhiteSpace(source.ExtractionSource)
            && string.IsNullOrWhiteSpace(source.DocumentQualityStatus)
            && string.IsNullOrWhiteSpace(source.PageQualityStatus)
            && string.IsNullOrWhiteSpace(source.TextStatus)
            && string.IsNullOrWhiteSpace(source.ChunkTextStatus)
            && source.ChunkTextSparse is null
            && source.ChunkOcrCandidate is null
            && source.ExtractionConfidence is null
            && source.DocumentExtractionConfidence is null
            && source.PageExtractionConfidence is null
            && !source.ManualReviewRecommended
            && !source.DocumentManualReviewRecommended
            && !source.PageManualReviewRecommended
            && !source.OcrAttempted
            && !source.OcrApplied
            && !source.OcrRecommended
            && source.QualitySignals.Count == 0
            && source.ChunkQualitySignals.Count == 0
            && diagnosticSummary is null)
        {
            return null;
        }

        return new
        {
            extractionSource = source.ExtractionSource,
            documentQualityStatus = source.DocumentQualityStatus,
            pageQualityStatus = source.PageQualityStatus,
            textStatus = source.TextStatus,
            chunkTextStatus = source.ChunkTextStatus,
            chunkTextSparse = source.ChunkTextSparse,
            chunkOcrCandidate = source.ChunkOcrCandidate,
            qualityStatus = source.QualityStatus,
            extractionConfidence = source.ExtractionConfidence,
            documentExtractionConfidence = source.DocumentExtractionConfidence,
            pageExtractionConfidence = source.PageExtractionConfidence,
            manualReviewRecommended = source.ManualReviewRecommended,
            documentManualReviewRecommended = source.DocumentManualReviewRecommended,
            pageManualReviewRecommended = source.PageManualReviewRecommended,
            ocrAttempted = source.OcrAttempted,
            ocrApplied = source.OcrApplied,
            ocrRecommended = source.OcrRecommended,
            signals = source.QualitySignals.Count == 0 ? null : source.QualitySignals,
            chunkQualitySignals = source.ChunkQualitySignals.Count == 0 ? null : source.ChunkQualitySignals,
            diagnosticSummary
        };
    }

    private static object? BuildSourceExtractionDiagnosticPayload(ToolMemory.SourceExtractionDiagnosticRef? summary)
    {
        if (summary is null)
            return null;

        var compact = new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["nativeTextStatus"] = NullIfWhiteSpace(summary.NativeTextStatus),
            ["nativeOcrRecommended"] = summary.NativeOcrRecommended,
            ["ocrMode"] = NullIfWhiteSpace(summary.OcrMode),
            ["ocrLanguages"] = NullIfWhiteSpace(summary.OcrLanguages),
            ["ocrDurationMs"] = summary.OcrDurationMs,
            ["ocrFailureReason"] = NullIfWhiteSpace(summary.OcrFailureReason),
            ["ocrAppliedReason"] = NullIfWhiteSpace(summary.OcrAppliedReason),
            ["ocrTimedOut"] = summary.OcrTimedOut,
            ["ocrAttemptedPageCount"] = summary.OcrAttemptedPageCount,
            ["ocrSkippedPageCount"] = summary.OcrSkippedPageCount,
            ["ocrPagesWithNovelTextCount"] = summary.OcrPagesWithNovelTextCount,
            ["pageCount"] = summary.PageCount,
            ["textPageCount"] = summary.TextPageCount,
            ["emptyPageCount"] = summary.EmptyPageCount,
            ["sparsePageCount"] = summary.SparsePageCount,
            ["imagePageCount"] = summary.ImagePageCount,
            ["pageWarningCount"] = summary.PageWarningCount,
            ["pageReviewRecommendedCount"] = summary.PageReviewRecommendedCount,
            ["retrievalChunkQuality"] = BuildSourceRetrievalChunkQualityPayload(summary.RetrievalChunkQuality)
        };

        var nonEmpty = compact
            .Where(static pair => pair.Value is not null)
            .ToDictionary(static pair => pair.Key, static pair => pair.Value!, StringComparer.Ordinal);
        return nonEmpty.Count == 0 ? null : nonEmpty;
    }

    private static object? BuildSourceRetrievalChunkQualityPayload(ToolMemory.SourceRetrievalChunkQualityRef? summary)
    {
        if (summary is null)
            return null;

        var compact = new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["totalChunkCount"] = summary.TotalChunkCount,
            ["searchableChunkCount"] = summary.SearchableChunkCount,
            ["rejectedChunkCount"] = summary.RejectedChunkCount,
            ["manualReviewRecommended"] = summary.ManualReviewRecommended,
            ["rejectionReasons"] = summary.RejectionReasons.Count == 0 ? null : summary.RejectionReasons
        };

        var nonEmpty = compact
            .Where(static pair => pair.Value is not null)
            .ToDictionary(static pair => pair.Key, static pair => pair.Value!, StringComparer.Ordinal);
        return nonEmpty.Count == 0 ? null : nonEmpty;
    }

    private static object? BuildSourceContentCardsPayload(ToolMemory.SourceRef source)
        => source.MatchedContentCards.Count == 0
            ? null
            : source.MatchedContentCards.Select(static card => new
            {
                title = card.Title,
                contentCardId = card.ContentCardId,
                pageStart = card.PageStart,
                pageEnd = card.PageEnd,
                kind = card.Kind,
                signals = card.Signals,
                evidence = card.Evidence
            }).ToList();

    private static string? NullIfWhiteSpace(string? value)
        => string.IsNullOrWhiteSpace(value) ? null : value.Trim();

    private static List<ToolMemory.SourceRef> DeriveSourcesFromRankedRagHits(ToolResults toolResults, string query, int maxSources = 8)
    {
        var evidenceQuery = BuildRagEvidenceSelectionQuery(query);
        var requestedTitle = LooksLikeShortTechnicalEvidenceTopic(evidenceQuery)
            ? null
            : TryExtractRequestedItemTitle(query);
        var hits = EnumerateRagHitSummaries(toolResults)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit) || IsUsableExactItemNavigationOverride(requestedTitle, hit))
            .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit) || IsUsableExactItemNavigationOverride(requestedTitle, hit))
            .OrderByDescending(hit => ComputeRagHitLexicalRelevance(evidenceQuery, GetRagHitLookupText(hit)))
            .ToList();

        if (!string.IsNullOrWhiteSpace(requestedTitle))
        {
            var exactTitleHits = hits
                .Where(hit => RagHitContainsRequestedTitle(hit, requestedTitle!)
                    || RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit))
                .ToList();
            var anchoredExactTitleHits = exactTitleHits
                .Where(hit => RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit))
                .ToList();
            if (anchoredExactTitleHits.Count > 0)
                exactTitleHits = anchoredExactTitleHits;
            if (exactTitleHits.Count > 0)
                hits = exactTitleHits;
        }
        else
        {
            hits = FilterHitsToDominantTopLevel(hits, query).ToList();
        }

        return hits
            .GroupBy(hit => $"{hit.DocPath}|{hit.PageStart}", StringComparer.OrdinalIgnoreCase)
            .Select(g => g.First())
            .Take(maxSources)
            .Select(BuildSourceRefFromRagHit)
            .ToList();
    }

    private static List<ToolMemory.SourceRef> DeriveSourcesFromExtractiveHits(ToolResults toolResults, string query, int maxSources = 8)
    {
        if (LooksLikeDocumentVersionTraceabilityRequest(query))
        {
            var traceabilitySources = DeriveSourcesFromDocumentVersionTraceabilityHits(
                toolResults,
                query,
                Math.Min(maxSources, 4));
            if (traceabilitySources.Count > 0)
                return traceabilitySources;
        }

        var evidenceQuery = BuildRagEvidenceSelectionQuery(query);
        var requestedTitle = LooksLikeShortTechnicalEvidenceTopic(evidenceQuery)
            ? null
            : TryExtractRequestedItemTitle(query);
        var requestedDocumentFileTitle = ResolveRequestedDocumentFileTitle(query, requestedTitle);
        var explicitDocumentFileReferences = ExtractExplicitDocumentFileReferenceQueries(query);
        var hasMultipleExplicitComparativeDocumentReferences = LooksLikeComparativeDocumentaryRequest(query)
            && explicitDocumentFileReferences.Count > 1;
        var shouldScopeToSingleRequestedDocumentFile = !hasMultipleExplicitComparativeDocumentReferences
            && !string.IsNullOrWhiteSpace(requestedDocumentFileTitle);
        var allHits = EnumerateRagHitSummaries(toolResults)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit)
                || IsUsableExactItemNavigationOverride(requestedTitle, hit)
                || MatchesRequestedDocumentFileIdentity(requestedDocumentFileTitle, hit))
            .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit)
                || IsUsableExactItemNavigationOverride(requestedTitle, hit)
                || MatchesRequestedDocumentFileIdentity(requestedDocumentFileTitle, hit)
                || MatchesExplicitComparativeDocumentReference(query, hit))
            .ToList();
        if (string.IsNullOrWhiteSpace(requestedDocumentFileTitle)
            && !string.IsNullOrWhiteSpace(requestedTitle)
            && allHits.Count > 0
            && (!RagHitsContainRequestedTitle(allHits, requestedTitle!)
                || !allHits.Any(hit => (RagHitContainsRequestedTitle(hit, requestedTitle!)
                        || RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit)
                        || IsUsableExactItemNavigationOverride(requestedTitle!, hit))
                    && !LooksLikeExactItemReferenceOnlyHit(requestedTitle!, hit))))
        {
            return DeriveSourcesFromMissingExactItemCloseLeads(requestedTitle!, allHits);
        }

        var sourceLimit = maxSources;
        if (LooksLikeRankingDocumentaryRequest(query))
            sourceLimit = Math.Min(sourceLimit, 4);
        else if (!string.IsNullOrWhiteSpace(requestedTitle))
            sourceLimit = Math.Min(sourceLimit, 4);
        else if (LooksLikeSourceBackedQuantityScalingRequest(query))
            sourceLimit = Math.Min(sourceLimit, 1);
        else if (LooksLikeSourceBackedAdaptationRequest(query))
            sourceLimit = Math.Min(sourceLimit, 5);

        List<RagHitSummary> selectedHits;
        if (LooksLikeSourceBackedQuantityScalingRequest(query) && TryExtractTargetScaleCount(query, out var targetCount))
        {
            selectedHits = SelectQuantityScalingCandidates(EnumerateRagHitSummaries(toolResults), query, targetCount)
                .Select(candidate => candidate.Hit)
                .Take(sourceLimit)
                .ToList();
            if (selectedHits.Count == 0)
                selectedHits = SelectSourceBackedExtractiveHits(toolResults, query, sourceLimit).ToList();
        }
        else
        {
            selectedHits = SelectSourceBackedExtractiveHits(toolResults, query, sourceLimit).ToList();
        }
        if (shouldScopeToSingleRequestedDocumentFile)
        {
            var documentHits = selectedHits
                .Where(hit => CandidateMatchesDocumentIdentity(requestedDocumentFileTitle!, hit.DocName, hit.DocPath))
                .ToList();
            if (documentHits.Count == 0)
            {
                documentHits = allHits
                    .Where(hit => CandidateMatchesDocumentIdentity(requestedDocumentFileTitle!, hit.DocName, hit.DocPath))
                    .Take(sourceLimit)
                    .ToList();
            }

            if (documentHits.Count > 0)
                selectedHits = documentHits;
        }
        if (!string.IsNullOrWhiteSpace(requestedTitle) && !hasMultipleExplicitComparativeDocumentReferences)
        {
            var stronglyAnchoredHits = selectedHits
                .Where(hit => LooksLikeStructuredItemCardRequest(query)
                    ? ExactItemEvidenceStartsWithRequestedTitle(requestedTitle!, hit) || HasStrongExactItemTitleAnchor(requestedTitle!, hit) || IsUsableExactItemNavigationOverride(requestedTitle!, hit)
                    : RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit) || IsUsableExactItemNavigationOverride(requestedTitle!, hit))
                .ToList();
            if (stronglyAnchoredHits.Count > 0)
                selectedHits = stronglyAnchoredHits;

            selectedHits = selectedHits
                .OrderByDescending(hit => ComputeExactItemCardEvidenceScore(requestedTitle!, hit))
                .ThenByDescending(hit => hit.Score)
                .ToList();
        }
        else if (LooksLikeSourceBackedAdaptationRequest(query))
        {
            selectedHits = RankSourceBackedAdaptationHits(selectedHits, query)
                .Take(sourceLimit)
                .ToList();
        }
        else if (LooksLikeTechnicalRankingQuery(query))
        {
            var structuredEnoughHits = selectedHits
                .Where(static hit => !LooksLikeLowStructureShortProcedureHit(hit))
                .ToList();
            if (structuredEnoughHits.Count > 0)
                selectedHits = structuredEnoughHits;

            var nonVeryShortHits = selectedHits
                .Where(static hit => ExtractBestVisibleDurationMinutes(hit) is not int minutes || minutes > 3)
                .ToList();
            if (nonVeryShortHits.Count > 0)
                selectedHits = nonVeryShortHits;
        }

        var requestedMaxMinutes = TryExtractRequestedMaxMinutes(query);
        if (requestedMaxMinutes.HasValue)
        {
            var timeCompatibleHits = selectedHits
                .Where(hit =>
                {
                    var visibleMinutes = ExtractBestVisibleDurationMinutes(hit);
                    return !visibleMinutes.HasValue || visibleMinutes.Value <= requestedMaxMinutes.Value;
                })
                .ToList();
            if (timeCompatibleHits.Count > 0)
                selectedHits = timeCompatibleHits;
        }

        var excludedTerms = ExtractSourceBackedExcludedTerms(query);
        if (excludedTerms.Count > 0)
        {
            var compliantHits = selectedHits
                .Where(hit => !RagHitContainsAnyExcludedTerm(hit, excludedTerms))
                .ToList();
            if (compliantHits.Count > 0)
                selectedHits = compliantHits;
        }

        return selectedHits
            .GroupBy(hit => $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}", StringComparer.OrdinalIgnoreCase)
            .Select(g => g.First())
            .Take(sourceLimit)
            .Select(BuildSourceRefFromRagHit)
            .ToList();
    }

    private static IReadOnlyList<RagHitSummary> FilterHitsToDominantTopLevel(IReadOnlyList<RagHitSummary> hits, string? query)
    {
        if (hits.Count < 4 || ShouldPreserveCrossCategoryRagHits(query))
            return hits;

        var window = hits
            .Take(Math.Min(8, hits.Count))
            .Select((hit, index) => new
            {
                Hit = hit,
                Rank = index,
                TopLevel = ExtractTopLevelDocPath(hit.DocPath)
            })
            .Where(item => !string.IsNullOrWhiteSpace(item.TopLevel))
            .ToList();
        if (window.Count < 4)
            return hits;

        var groups = window
            .GroupBy(item => item.TopLevel, StringComparer.OrdinalIgnoreCase)
            .Select(group => new
            {
                TopLevel = group.Key,
                Count = group.Count(),
                BestRank = group.Min(item => item.Rank)
            })
            .OrderByDescending(group => group.Count)
            .ThenBy(group => group.BestRank)
            .ToList();
        if (groups.Count < 2 || groups[0].Count < 3)
            return hits;

        var best = groups[0];
        var secondCount = groups.Count > 1 ? groups[1].Count : 0;
        var share = best.Count / (double)window.Count;
        if (share < 0.55 && best.Count < secondCount + 2)
            return hits;

        var filtered = hits
            .Where(hit => string.Equals(ExtractTopLevelDocPath(hit.DocPath), best.TopLevel, StringComparison.OrdinalIgnoreCase))
            .ToList();
        return filtered.Count >= 2 ? filtered : hits;
    }

    private static bool ShouldPreserveCrossCategoryRagHits(string? query)
    {
        if (LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query))
        {
            return true;
        }

        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:compare|comparer|comparaison|comparatif|comparative|versus|different(?:es?)?|plusieurs|toutes?|tous|global|ensemble|categories?|categories|dossiers?|catalogue|across|all|multiple|various|varios|varias|vários|verschiedene|alle|tutti|tutte)\b",
            RegexOptions.CultureInvariant);
    }

    private static string ExtractTopLevelDocPath(string? docPath)
    {
        var normalized = (docPath ?? string.Empty).Trim().Replace('\\', '/').Trim('/');
        if (normalized.Length == 0)
            return string.Empty;

        var slash = normalized.IndexOf('/');
        return slash > 0 ? normalized[..slash] : string.Empty;
    }

    private static bool LooksLikeNoRagDataAnswer(string? answer)
    {
        var s = (answer ?? string.Empty).Trim();
        if (s.Length == 0)
            return false;

        if (LooksLikeNoRagDataAnswerInOtherSupportedLanguage(s))
            return true;

        if (Regex.IsMatch(
                s,
                @"(?i)\b(?:pas\s+assez\s+d['\u2019]informations?|informations?\s+n[ée]cessaires?.{0,100}(?:pas|non)\s+disponibles?|not\s+enough\s+information|insufficient\s+(?:data|information|sources)|(?:donn[ée]es?|sources?|informations?)\s+(?:insuffisantes?|non\s+disponibles?))\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        var noDataPattern =
            @"(?i)\b(?:je\s+n['\u2019]ai\s+pas|aucun(?:e)?|pas\s+de|pas\s+assez\s+d['\u2019]informations?|informations?\s+n[ée]cessaires?.{0,80}(?:pas|non)\s+disponibles?|(?:donn[ée]es?|sources?|informations?)\s+(?:insuffisantes?|non\s+disponibles?)|no\s+(?:specific\s+)?(?:data|document|source|information)|not\s+enough\s+information|insufficient\s+(?:data|information|sources)|nothing\s+specific)\b.{0,160}\b(?:donn[ée]es?|documents?|sources?|information|data|disponibles?|available|suffisantes?)\b";

        return Regex.IsMatch(s, noDataPattern, RegexOptions.CultureInvariant);
    }

    private static bool ShouldFallbackFromNoRagDataAnswer(string? answer)
    {
        if (string.IsNullOrWhiteSpace(answer))
            return true;

        return LooksLikeNoRagDataAnswer(answer)
            && !LooksLikeUsefulPartialSourceBackedAnswer(answer);
    }

    private static bool LooksLikeUsefulPartialSourceBackedAnswer(string? answer)
    {
        var s = (answer ?? string.Empty).Trim();
        if (s.Length < 140)
            return false;

        var hasSourceReference = s.Contains("[[open|", StringComparison.OrdinalIgnoreCase)
            || Regex.IsMatch(
                s,
                @"(?i)\b(?:p\.?|page|pagina|p[aÃ¡]gina|seite|pagina)\s*\d+\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                s,
                @"(?i)\b[\w.-]+\.[a-z0-9]{2,6}\b",
                RegexOptions.CultureInvariant);
        if (!hasSourceReference)
            return false;

        var bodyBeforeSourceList = Regex.Split(
            s,
            @"(?im)^\s*(?:source|sources|references?|r[eÃ©]f[eÃ©]rences?|fuente|fuentes|fonte|fontes|quelle|quellen|fonti)\s*:\s*$",
            RegexOptions.CultureInvariant)[0];
        var bulletCount = Regex.Matches(
            bodyBeforeSourceList,
            @"(?m)^\s*(?:[-*\u2022]|\d+[.)])\s+\S",
            RegexOptions.CultureInvariant).Count;
        var sentenceCount = Regex.Matches(
            bodyBeforeSourceList,
            @"[.!?]\s+",
            RegexOptions.CultureInvariant).Count;

        return bulletCount >= 1 || sentenceCount >= 3;
    }

    private static bool LooksLikeNoRagDataAnswerInOtherSupportedLanguage(string answer)
    {
        var normalized = NormalizeLexicalLookup(answer);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:no\s+(?:tengo|hay|encontre|encuentro)|informacion\s+insuficiente|nao\s+(?:tenho|ha|encontrei|encontro)|informacao\s+insuficiente|ich\s+habe\s+(?:keine|nicht\s+genug)|keine\s+(?:daten|quellen|informationen)|non\s+(?:ho|trovo|trovo\s+informazioni)|informazioni\s+insufficienti)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeDegenerateLlmOutput(string? answer)
    {
        var raw = answer ?? string.Empty;
        var s = CollapseWhitespace(raw);
        if (s.Length == 0)
            return false;

        if (Regex.IsMatch(
                s,
                @"(?i)\b(?:crit[e\u00e8]res?\s+attendus?|validation\s+points?|expected\s+answer|expected\s+criteria)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(s, @"https?://", RegexOptions.CultureInvariant | RegexOptions.IgnoreCase)
            && Regex.IsMatch(s, @"(?i)\b(?:sources?|documents?|\.pdf|p\.\s*\d+)\b", RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (s.Length < 160)
            return false;

        var repeatedLine = Regex.Split(raw, @"\r?\n")
            .Select(CollapseWhitespace)
            .Where(line => line.Length >= 18)
            .GroupBy(line => line, StringComparer.OrdinalIgnoreCase)
            .Any(group => group.Count() >= 3);
        if (repeatedLine)
            return true;

        var words = Regex.Matches(NormalizeLexicalLookup(s), @"[\p{L}\p{N}]+", RegexOptions.CultureInvariant)
            .Cast<Match>()
            .Select(match => match.Value)
            .Where(word => word.Length > 0)
            .ToList();

        if (words.Count < 32)
            return false;

        var uniqueRatio = words.Distinct(StringComparer.Ordinal).Count() / (double)words.Count;
        if (words.Count >= 70 && uniqueRatio < 0.34)
            return true;

        for (var n = 3; n <= 8; n++)
        {
            var counts = new Dictionary<string, int>(StringComparer.Ordinal);
            for (var i = 0; i <= words.Count - n; i++)
            {
                var key = string.Join(' ', words.Skip(i).Take(n));
                counts[key] = counts.TryGetValue(key, out var current) ? current + 1 : 1;
            }

            if (counts.Values.Any(count => count >= 4 && count * n >= Math.Max(18, words.Count / 4)))
                return true;
        }

        return false;
    }

    private static bool LooksLikeMissingExactItemWithoutSourceLeads(string? answer)
    {
        if (!LooksLikeMissingExactItemAnswer(answer))
            return false;

        var normalized = NormalizeLexicalLookup(answer);
        return !Regex.IsMatch(
            normalized,
            @"\b(?:pistes\s+proches|closest\s+source-backed\s+leads|pistas\s+cercanas|pistas\s+proximas|naheliegende\s+belegte\s+hinweise|indicazioni\s+vicine)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeMissingExactItemAnswer(string? answer)
    {
        var normalized = NormalizeLexicalLookup(answer);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:je\s+n['\s]?ai\s+pas\s+trouve\s+l['\s]?element\s+exact|i\s+did\s+not\s+find\s+the\s+exact\s+requested\s+item|no\s+he\s+encontrado\s+el\s+elemento\s+exacto|nao\s+encontrei\s+o\s+item\s+exato|ich\s+habe\s+den\s+exakt\s+angefragten\s+eintrag|non\s+ho\s+trovato\s+l['\s]?elemento\s+esatto)\b",
            RegexOptions.CultureInvariant);
    }

    internal static bool ShouldUseSourceBackedExtractiveAnswer(string query, ToolResults toolResults)
    {
        var hits = EnumerateRagHitSummaries(toolResults).Take(8).ToList();
        if (hits.Count == 0)
            return false;

        var normalizedQuery = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            return false;

        if (LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query))
        {
            return false;
        }

        if (!string.IsNullOrWhiteSpace(TryExtractRequestedItemTitle(query)))
            return true;

        if (Regex.IsMatch(
                normalizedQuery,
            @"\b(?:fiche|fiches|card|cards|element|elements|item|items|etape|etapes|étape|étapes|step|steps|procedure|procedures|process|processus)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        return LooksLikeSourceBackedQuantityScalingRequest(query)
            || LooksLikeSourceBackedAdaptationRequest(query)
            || LooksLikeRankingDocumentaryRequest(query)
            || LooksLikeComparativeDocumentaryRequest(query)
            || LooksLikeShortTechnicalEvidenceTopic(query);
    }

    private static string TryBuildCorpusClaimVerificationAnswer(ToolResults toolResults, string query, string language)
    {
        if (!LooksLikeCorpusClaimVerificationRequest(query))
            return string.Empty;

        language = NormalizeLanguageCode(language);
        var hits = SelectSourceBackedExtractiveHits(toolResults, query, maxHits: 5)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .GroupBy(hit => $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .Take(4)
            .ToList();
        if (hits.Count == 0)
            return string.Empty;

        var header = SourceBackedLabel(
            language,
            "Je ne peux pas confirmer une obligation generale ou un \"toujours\" avec les seuls extraits retrouves. Je limite donc la reponse a une verification prudente :",
            "I cannot confirm a general obligation or an \"always\" claim from the retrieved excerpts alone. I will keep this to a cautious source-backed check:",
            "No puedo confirmar una obligacion general o un \"siempre\" solo con los extractos recuperados. Limito la respuesta a una verificacion prudente:",
            "Nao posso confirmar uma obrigacao geral ou um \"sempre\" apenas com os excertos recuperados. Limito a resposta a uma verificacao prudente:",
            "Ich kann aus den gefundenen Auszuegen keine allgemeine Pflicht oder ein \"immer\" bestaetigen. Ich beschraenke die Antwort auf eine vorsichtige belegte Pruefung:",
            "Non posso confermare un obbligo generale o un \"sempre\" solo dagli estratti recuperati. Limito la risposta a una verifica prudente:");
        var conclusion = SourceBackedLabel(
            language,
            "Conclusion prudente : traite l'hypothese comme limitee ou a confirmer document par document, pas comme une regle universelle, sauf si une page source citee l'exprime explicitement.",
            "Cautious conclusion: treat the claim as limited or to be confirmed document by document, not as a universal rule, unless a cited source page says so explicitly.",
            "Conclusion prudente: trata la hipotesis como limitada o pendiente de confirmar documento por documento, no como regla universal, salvo que una pagina citada lo diga explicitamente.",
            "Conclusao prudente: trata a hipotese como limitada ou a confirmar documento por documento, nao como regra universal, salvo se uma pagina citada o disser explicitamente.",
            "Vorsichtige Schlussfolgerung: Behandle die Annahme als begrenzt oder dokumentweise zu pruefen, nicht als allgemeine Regel, ausser eine zitierte Quellseite sagt es ausdruecklich.",
            "Conclusione prudente: tratta l'ipotesi come limitata o da confermare documento per documento, non come regola universale, salvo che una pagina citata lo dica esplicitamente.");

        var sb = new StringBuilder();
        sb.AppendLine(header);
        foreach (var hit in hits.Take(4))
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 240);
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            sb.AppendLine(excerpt);
        }

        sb.Append(conclusion);
        return sb.ToString().TrimEnd();
    }

    private static string TryBuildComparativeDocumentaryAnswer(ToolResults toolResults, string query, string language)
    {
        if (!LooksLikeComparativeDocumentaryRequest(query))
            return string.Empty;
        if (LooksLikeRankingDocumentaryRequest(query))
            return string.Empty;

        language = NormalizeLanguageCode(language);
        var hits = SelectComparativeDocumentaryHits(EnumerateRagHitSummaries(toolResults), query, maxHits: 8)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit) || MatchesExplicitComparativeDocumentReference(query, hit))
            .GroupBy(hit => string.IsNullOrWhiteSpace(hit.DocPath) ? hit.DocName : hit.DocPath, StringComparer.OrdinalIgnoreCase)
            .Select(group => group.OrderByDescending(hit => ComputeComparativeDocumentaryEvidenceScore(hit, BuildRagEvidenceSelectionQuery(query), ExtractQuerySignalTerms(NormalizeLexicalLookup(query)).ToArray())).First())
            .Take(4)
            .ToList();
        if (hits.Select(hit => string.IsNullOrWhiteSpace(hit.DocPath) ? hit.DocName : hit.DocPath)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Count() < 2)
        {
            return string.Empty;
        }

        var labels = language switch
        {
            "en" => (
                Header: "Here is a source-separated comparison limited to the retrieved excerpts:",
                PerDoc: "By document:",
                Common: "Common ground: the selected sources address the requested theme, but I do not merge their rules beyond the cited excerpts.",
                Difference: "Differences: each document must be read in its own framework; use the cited pages to compare wording, scope and procedure.",
                Limit: "Limit: this is not an exhaustive legal or technical comparison of the full documents."),
            "es" => (
                Header: "Comparacion separada por fuente, limitada a los extractos recuperados:",
                PerDoc: "Por documento:",
                Common: "Puntos comunes: las fuentes seleccionadas tratan el tema pedido, pero no fusiono sus reglas mas alla de los extractos citados.",
                Difference: "Diferencias: cada documento debe leerse en su propio marco; usa las paginas citadas para comparar redaccion, alcance y procedimiento.",
                Limit: "Limite: no es una comparacion juridica o tecnica exhaustiva de los documentos completos."),
            "pt" => (
                Header: "Comparacao separada por fonte, limitada aos excertos recuperados:",
                PerDoc: "Por documento:",
                Common: "Pontos comuns: as fontes selecionadas tratam o tema pedido, mas nao junto as regras para alem dos excertos citados.",
                Difference: "Diferencas: cada documento deve ser lido no seu proprio enquadramento; usa as paginas citadas para comparar redacao, ambito e procedimento.",
                Limit: "Limite: nao e uma comparacao juridica ou tecnica exaustiva dos documentos completos."),
            "de" => (
                Header: "Quellengetrennte Gegenueberstellung, begrenzt auf die gefundenen Auszuege:",
                PerDoc: "Nach Dokument:",
                Common: "Gemeinsamkeit: Die ausgewaehlten Quellen behandeln das angefragte Thema, aber ich fuehre ihre Regeln nicht ueber die zitierten Auszuege hinaus zusammen.",
                Difference: "Unterschiede: Jedes Dokument muss in seinem eigenen Rahmen gelesen werden; nutze die zitierten Seiten fuer Wortlaut, Geltungsbereich und Verfahren.",
                Limit: "Grenze: Dies ist kein vollstaendiger rechtlicher oder technischer Vergleich der Gesamtdokumente."),
            "it" => (
                Header: "Confronto separato per fonte, limitato agli estratti recuperati:",
                PerDoc: "Per documento:",
                Common: "Punti comuni: le fonti selezionate trattano il tema richiesto, ma non fondo le loro regole oltre gli estratti citati.",
                Difference: "Differenze: ogni documento va letto nel proprio quadro; usa le pagine citate per confrontare formulazione, ambito e procedura.",
                Limit: "Limite: non e un confronto giuridico o tecnico esaustivo dei documenti completi."),
            _ => (
                Header: "Voici une comparaison separee par source, limitee aux extraits retrouves :",
                PerDoc: "Par document :",
                Common: "Points communs : les sources selectionnees traitent le theme demande, mais je ne fusionne pas leurs regles au-dela des extraits cites.",
                Difference: "Differences : chaque document doit etre lu dans son propre cadre ; utilise les pages citees pour comparer formulation, perimetre et procedure.",
                Limit: "Limite : ce n'est pas une comparaison juridique ou technique exhaustive des documents complets.")
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(labels.PerDoc);
        foreach (var hit in hits)
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 260);
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            sb.AppendLine(excerpt);
        }

        sb.AppendLine(labels.Common);
        sb.AppendLine(labels.Difference);
        sb.Append(labels.Limit);
        return sb.ToString().TrimEnd();
    }

    private static bool MatchesExplicitComparativeDocumentReference(string? query, RagHitSummary hit)
    {
        if (!LooksLikeComparativeDocumentaryRequest(query))
            return false;

        foreach (var fileReference in ExtractExplicitDocumentFileReferenceQueries(query).Take(6))
        {
            if (CandidateMatchesDocumentIdentity(fileReference, hit.DocName, hit.DocPath))
                return true;
        }

        return false;
    }

    private static bool MatchesRequestedDocumentFileIdentity(string? requestedTitle, RagHitSummary hit)
    {
        return !string.IsNullOrWhiteSpace(requestedTitle)
            && Regex.IsMatch(requestedTitle!, @"\.(?:pdf|docx?|xlsx?|pptx?|md|txt|csv)$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)
            && CandidateMatchesDocumentIdentity(requestedTitle!, hit.DocName, hit.DocPath);
    }

    private static string? ResolveRequestedDocumentFileTitle(string? query, string? requestedTitle)
    {
        if (!string.IsNullOrWhiteSpace(requestedTitle)
            && Regex.IsMatch(requestedTitle!, @"\.(?:pdf|docx?|xlsx?|pptx?|md|txt|csv)$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
        {
            return requestedTitle;
        }

        var explicitPdfTitle = TryExtractPdfFileNameRequestedTitle(query);
        if (!string.IsNullOrWhiteSpace(explicitPdfTitle))
            return explicitPdfTitle;

        return ExtractExplicitDocumentFileReferenceQueries(query).FirstOrDefault();
    }

    internal static string BuildSourceBackedExtractiveAnswer(ToolResults toolResults, string query, string language)
    {
        language = NormalizeLanguageCode(language);
        var versionTraceabilityAnswer = TryBuildDocumentVersionTraceabilityAnswer(toolResults, query, language);
        if (!string.IsNullOrWhiteSpace(versionTraceabilityAnswer))
            return versionTraceabilityAnswer;

        var missingRequiredEvidence = TryBuildMissingRequiredEvidenceAnswer(toolResults, query, language);
        if (!ShouldUseAdvisoryEvidenceGuardForBroadSynthesis(toolResults, query)
            && !string.IsNullOrWhiteSpace(missingRequiredEvidence))
            return missingRequiredEvidence;

        var corpusClaimVerificationAnswer = TryBuildCorpusClaimVerificationAnswer(toolResults, query, language);
        if (!string.IsNullOrWhiteSpace(corpusClaimVerificationAnswer))
            return corpusClaimVerificationAnswer;

        var comparativeAnswer = TryBuildComparativeDocumentaryAnswer(toolResults, query, language);
        if (!string.IsNullOrWhiteSpace(comparativeAnswer))
            return comparativeAnswer;

        var allHits = EnumerateRagHitSummaries(toolResults)
            .OrderBy(hit => LooksLikeNavigationOnlyHit(hit) ? 1 : 0)
            .ThenByDescending(hit => ComputeRagHitLexicalRelevance(query, GetRagHitLookupText(hit)))
            .ThenByDescending(hit => hit.Score)
            .ToList();

        if (allHits.Count == 0)
            return BuildRagEvidenceFallbackAnswer(toolResults, query, language);

        var evidenceQuery = BuildRagEvidenceSelectionQuery(query);
        var requestedTitle = LooksLikeShortTechnicalEvidenceTopic(evidenceQuery)
            ? null
            : TryExtractRequestedItemTitle(query);
        var requestedDocumentFileTitle = ResolveRequestedDocumentFileTitle(query, requestedTitle);
        var requestedTitleIsDocumentFile = !string.IsNullOrWhiteSpace(requestedDocumentFileTitle);
        var isQuantityScalingRequest = LooksLikeSourceBackedQuantityScalingRequest(query);
        if (!isQuantityScalingRequest
            && !requestedTitleIsDocumentFile
            && !string.IsNullOrWhiteSpace(requestedTitle)
            && !allHits.Any(hit => (RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit)
                    || IsUsableExactItemNavigationOverride(requestedTitle!, hit))
                && !LooksLikeExactItemReferenceOnlyHit(requestedTitle!, hit)))
        {
            var answer = BuildMissingExactItemAnswer(language, requestedTitle!, allHits);
            return LooksLikeSourceBypassOrUnsupportedInventionRequest(query)
                ? ApplySourcePolicyGuardPrefix(answer, language)
                : answer;
        }

        var hits = SelectSourceBackedExtractiveHits(toolResults, query, maxHits: 4).ToList();
        if (requestedTitleIsDocumentFile)
        {
            var documentHits = hits
                .Where(hit => CandidateMatchesDocumentIdentity(requestedDocumentFileTitle!, hit.DocName, hit.DocPath))
                .ToList();
            if (documentHits.Count == 0)
            {
                documentHits = allHits
                    .Where(hit => CandidateMatchesDocumentIdentity(requestedDocumentFileTitle!, hit.DocName, hit.DocPath))
                    .Take(4)
                    .ToList();
            }

            if (documentHits.Count > 0)
                hits = documentHits;
        }
        if (!isQuantityScalingRequest
            && !requestedTitleIsDocumentFile
            && !string.IsNullOrWhiteSpace(requestedTitle)
            && hits.Count == 0)
        {
            var answer = BuildMissingExactItemAnswer(language, requestedTitle!, allHits);
            return LooksLikeSourceBypassOrUnsupportedInventionRequest(query)
                ? ApplySourcePolicyGuardPrefix(answer, language)
                : answer;
        }

        var requestedMaxMinutes = TryExtractRequestedMaxMinutes(query);
        if (requestedMaxMinutes.HasValue)
        {
            var withinTimeHits = hits
                .Where(hit =>
                {
                    var visibleMinutes = ExtractBestVisibleDurationMinutes(hit);
                    return !visibleMinutes.HasValue || visibleMinutes.Value <= requestedMaxMinutes.Value;
                })
                .ToList();
            if (withinTimeHits.Count > 0)
                hits = withinTimeHits;
        }

        var excludedTerms = ExtractSourceBackedExcludedTerms(query);
        if (excludedTerms.Count > 0)
        {
            var compliantHits = hits
                .Where(hit => !RagHitContainsAnyExcludedTerm(hit, excludedTerms))
                .ToList();
            if (compliantHits.Count == 0)
                return BuildNoSourceBackedCompliantOptionAnswer(language, excludedTerms, hits);

            hits = compliantHits;
        }

        if (isQuantityScalingRequest)
        {
            var scaledAnswer = BuildSourceBackedQuantityScalingAnswer(language, query, hits);
            if (!string.IsNullOrWhiteSpace(scaledAnswer))
                return scaledAnswer;
        }

        if (LooksLikeSourceBackedAdaptationRequest(query))
        {
            var adaptationAnswer = BuildSourceBackedAdaptationAnswer(language, query, hits);
            if (!string.IsNullOrWhiteSpace(adaptationAnswer))
                return adaptationAnswer;
        }

        if (LooksLikeRankingDocumentaryRequest(query))
        {
            var rankingAnswer = BuildSourceBackedRankingAnswer(language, query, hits);
            if (!string.IsNullOrWhiteSpace(rankingAnswer))
                return rankingAnswer;
        }

        if (!string.IsNullOrWhiteSpace(requestedTitle) && !requestedTitleIsDocumentFile)
        {
            if (hits.Count > 0 && hits.Any(hit => (RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit)
                        || IsUsableExactItemNavigationOverride(requestedTitle!, hit))
                    && !LooksLikeExactItemReferenceOnlyHit(requestedTitle!, hit)))
                return BuildSourceBackedExactItemAnswer(language, requestedTitle!, hits, query);
        }

        var sb = new StringBuilder();
        sb.Append(BuildSourceBackedExtractiveHeader(language, noExplicitPairing: ShouldWarnNoExplicitPairing(query, hits)));

        sb.AppendLine();
        foreach (var hit in hits)
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var evidenceCue = BuildWriterEvidenceCueForPrompt(hit, query, maxLength: SourceBackedEvidenceMaxChars);
            if (string.IsNullOrWhiteSpace(evidenceCue))
                evidenceCue = CleanReadableProcedureArtifacts(FormatSourceBackedEvidenceExcerpt(hit, query, SourceBackedEvidenceMaxChars));
            if (string.IsNullOrWhiteSpace(evidenceCue))
                continue;

            sb.Append("- ");
            sb.Append(evidenceCue);
            sb.Append(" (");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.AppendLine(").");
        }

        AppendSourceBackedExtractionQualityCaveat(sb, hits, language);
        return sb.ToString().TrimEnd();
    }

    private static string? TryExtractRequestedItemTitle(string? query)
    {
        var s = CollapseWhitespace(query ?? string.Empty);
        if (s.Length == 0)
            return null;

        if (LooksLikeUnresolvedSourceBackedDeicticFollowup(s))
            return null;

        if (LooksLikeBroadSourceBackedCompositionRequest(s))
            return null;

        if (LooksLikeGenericCollectionOrOptionRequestWithoutExactTitle(s))
            return null;

        var explicitPdfTitle = TryExtractPdfFileNameRequestedTitle(s);
        if (!string.IsNullOrWhiteSpace(explicitPdfTitle))
            return explicitPdfTitle;

        var availableItemRequest = Regex.Match(
            s,
            @"(?i)\b(?:j['\u2019]ai|je\s+dispose\s+de|i\s+have|tengo|tenho|ich\s+habe|ho)\s+(?:du|de\s+la|de\s+l['\u2019]|des|un|une|some|a|an|el|la|los|las|o|a|os|as|ein|eine|einen|del|della|dei|delle)?\s*(?<title>[\p{L}0-9'\u2019 \-]{3,70}?)(?:[,;?.!]|$).{0,100}\b(?:tu\s+as|vous\s+avez|as[-\s]?tu|avez[-\s]?vous|do\s+you\s+have|can\s+you|could\s+you|puedes|podes|pode|kannst|puoi|hai|hast)\b",
            RegexOptions.CultureInvariant);
        if (availableItemRequest.Success)
        {
            var title = CleanupRequestedItemTitle(availableItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var quoted = Regex.Match(s, "[\\u00ab\"'`](?<title>[^\\u00bb\"'`]{3,90})[\\u00bb\"'`]", RegexOptions.CultureInvariant);
        if (quoted.Success)
        {
            if (LooksLikeCorpusClaimVerificationRequest(s))
                return null;

            var title = CleanupQuotedRequestedItemTitle(quoted.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
            {
                if (LooksLikeShortTechnicalEvidenceTopic(title) && !LooksLikeCompactTechnicalIdentifier(title))
                    return null;

                return title;
            }
        }

        if (LooksLikeShortTechnicalEvidenceTopic(s))
            return null;

        if (LooksLikeSoftChoiceRecommendationRequest(s))
            return null;

        var actionConnectorTarget = Regex.Match(
            s,
            @"(?i)(?:^|[,.!?;]\s*)(?:\b(?:peux(?:[-\s]+tu)?|pourrais(?:[-\s]+tu)?|tu\s+peux|vous\s+pouvez|can\s+you|could\s+you)\s+(?:me\s+|m['\u2019]|nous\s+)?)?(?:donner|donne|donnes|donnez|montrer|montre|montres|montrez|afficher|affiche|affiches|affichez|faire|fais|faites|give|show|make|mostrar|hacer|haz|fazer|mostra|machen|zeigen|fare)\b[^:?.!,;]{0,70}?\b(?:pour|about|on|de|du|de\s+la|des|d['\u2019]|sur|of|for|sobre|ueber|über|su)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        if (actionConnectorTarget.Success)
        {
            var title = CleanupRequestedItemTitle(actionConnectorTarget.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var metricForItemRequest = Regex.Match(
            s,
            @"(?i)\b(?:combien|quel|quelle|quels|quelles|what|which|how)\b.+?\b(?:pour|for|sur|about|on)\s+(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|some)?\s*(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        if (metricForItemRequest.Success)
        {
            var title = CleanupRequestedItemTitle(metricForItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var politeItemRequests = Regex.Matches(
            s,
            @"(?i)(?:^|[,.!?;]\s*)\b(?:peux(?:[-\s]+tu)?|pourrais(?:[-\s]+tu)?|tu\s+peux|vous\s+pouvez|can\s+you|could\s+you)\s+(?:me\s+|m['\u2019]|nous\s+)?(?:donner|montrer|afficher|chercher|trouver|faire|give|show|find|make)\s+(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|some)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        foreach (Match politeItemRequest in politeItemRequests)
        {
            var title = CleanupRequestedItemTitle(politeItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var leadingPurposeItem = Regex.Match(
            s,
            @"(?i)^(?<title>[\p{L}0-9'\u2019 \-]{4,70}?)(?:\s+(?:pour|for|para|per)\s+[^:?.!,;]{2,90})(?:[:?.!,;]|$)",
            RegexOptions.CultureInvariant);
        if (leadingPurposeItem.Success)
        {
            var title = CleanupRequestedItemTitle(leadingPurposeItem.Groups["title"].Value);
            var normalizedTitle = NormalizeLexicalLookup(title);
            var tokenCount = ExtractQuerySignalTerms(normalizedTitle).Count();
            if (!string.IsNullOrWhiteSpace(title)
                && tokenCount is >= 2 and <= 6
                && !Regex.IsMatch(normalizedTitle, @"\b(?:aide|aider|faire|calcule|calculer|adapte|adapter|ajuste|ajuster|convertis|convertir|besoin|veux|voudrais|souhaite|cherche|trouve|donne|propose|what|which|need|want|find|give|suggest)\b", RegexOptions.CultureInvariant)
                && LooksLikeDirectRequestedItemTitle(title))
            {
                return title;
            }
        }

        var namedItem = Regex.Match(
            s,
            @"(?i)\b(?:fiche|card|document|doc|contrat|contract|procedure|proc[ée]dure|processus|process|manuel|manual|guide|rapport|report|notice|policy|politique)\s+(?:claire\s+)?(?:pour|about|on|de|du|de\s+la|des|d['\u2019]|sur|sobre|ueber|über|su)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        if (namedItem.Success)
            return CleanupRequestedItemTitle(namedItem.Groups["title"].Value);

        var baseItem = Regex.Match(
            s,
            @"(?i)\b(?:element|item|objet|sujet|topic)\s+(?:de\s+base\s+)?(?:pour|about|on|de|du|de\s+la|des|d['\u2019]|sur|sobre|ueber|über|su)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        if (baseItem.Success)
            return CleanupRequestedItemTitle(baseItem.Groups["title"].Value);

        if (Regex.IsMatch(
                s,
                @"(?i)\b(?:ignore|ignorer|ignorez|sans\s+sources?|invente|inventer|inventez|hallucine|halluciner)\b",
                RegexOptions.CultureInvariant))
        {
            var guardedTarget = Regex.Match(
                s,
                @"(?i)(?:de\s+la|du|des|d['\u2019]|de)\s+(?<title>[\p{L}0-9'\u2019 \-]{3,90})[\.?!]?$",
                RegexOptions.CultureInvariant);
            if (guardedTarget.Success)
                return CleanupRequestedItemTitle(guardedTarget.Groups["title"].Value);
        }

        if (Regex.IsMatch(
                s,
            @"(?i)\b(?:vitesses?|speeds?|temp[e\u00e9]ratures?|temperatures?|r[e\u00e9]glages?|settings?|param[e\u00e8]tres?|parameters?|quantit[e\u00e9]s?|quantites?|[e\u00e9]tapes?|steps?|temps|time|values?|valeurs?)\b",
                RegexOptions.CultureInvariant))
        {
            if (Regex.IsMatch(
                    s,
                    @"(?i)\b(?:quantit[e\u00e9]s?|quantites?|organisation|amounts?|values?|valeurs?|counts?|units?|items?)\b|\b(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+\p{L}",
                    RegexOptions.CultureInvariant)
                && !Regex.IsMatch(s, @"(?i)^(?:combien|quel|quelle|quels|quelles|comment|calcule|calculer|adapte|adapter|ajuste|ajuster|convertis|convertir|what|which|how|calculate|adapt|adjust|scale)\b", RegexOptions.CultureInvariant))
            {
                var leadingSubject = Regex.Match(
                    s,
                    @"(?i)^(?<title>[\p{L}0-9'\u2019 \-]{3,90}?)(?:\s+(?:pour|for)\s+[^:?.!,;]{2,90}|:)",
                    RegexOptions.CultureInvariant);
                if (leadingSubject.Success)
                {
                    var title = CleanupRequestedItemTitle(leadingSubject.Groups["title"].Value);
                    if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                        return title;
                }
            }

            var parameterTarget = Regex.Match(
                s,
                @"(?i)\b(?:pour|for)\s+\d+\s+(?:[\p{L}'\u2019-]+\s+){0,3}(?:de|du|des|de\s+la|de\s+l['\u2019]|d['\u2019]|of)\s+(?<title>[^:?.!,;]{3,90})",
                RegexOptions.CultureInvariant);
            if (parameterTarget.Success)
                return CleanupRequestedItemTitle(parameterTarget.Groups["title"].Value);

            parameterTarget = Regex.Match(
                s,
                @"(?i)\b(?:pour|for|sur|about|on)\s+(?:le|la|les|l['\u2019]|the\s+)?(?<title>[^:?.!,;]{3,90})",
                RegexOptions.CultureInvariant);
            if (parameterTarget.Success)
            {
                var title = CleanupRequestedItemTitle(parameterTarget.Groups["title"].Value);
                if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                    return title;
            }

            parameterTarget = Regex.Match(
                s,
                @"(?i)\b(?:pour|for|de|du|de\s+la|des|d['\u2019]|sur|about|on)\s+(?:le|la|les|l['\u2019]|the\s+)?(?<title>[^:?.!,;]{3,90})",
                RegexOptions.CultureInvariant);
            if (parameterTarget.Success)
            {
                var title = CleanupRequestedItemTitle(parameterTarget.Groups["title"].Value);
                if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                    return title;
            }
        }

        var directItemRequests = Regex.Matches(
            s,
            @"(?i)(?:^|[,.!?;]\s*)\b(?:donne(?:s)?(?:[-\s]+moi)?|montre(?:[-\s]+moi)?|affiche(?:[-\s]+moi)?|cherche|recherche|trouve|adapte|adapter|ajuste|ajuster|convertis|convertir|calcule|calculer|find|search|give(?:\s+me)?|show(?:\s+me)?|adapt|adjust|scale|resize)\s+(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|some)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        foreach (Match directItemRequest in directItemRequests)
        {
            var title = CleanupRequestedItemTitle(directItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var directSearchRequests = Regex.Matches(
            s,
            @"(?i)(?:^|[,.!?;]\s*)\b(?:je\s+cherche|je\s+recherche|i\s+(?:am\s+)?(?:looking\s+for|searching\s+for))\s+(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|some)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        foreach (Match directSearchRequest in directSearchRequests)
        {
            var title = CleanupRequestedItemTitle(directSearchRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var wantedExactItemRequests = Regex.Matches(
            s,
            @"(?i)(?:^|[,.!?;]\s*)\b(?:je\s+(?:veux|voudrais|souhaite)|j['\u2019]aimerais|i\s+(?:want|would\s+like|need)|quiero|quisiera|quero|gostaria|ich\s+(?:will|moechte|möchte|brauche)|vorrei)\s+(?:trouver\s+|retrouver\s+|avoir\s+|voir\s+|find\s+|get\s+|see\s+|ver\s+|encontrar\s+)?(?:le|la|les|l['\u2019]|the|el|los|las|o|a|os|as|der|die|das|il|lo|gli)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        foreach (Match wantedExactItemRequest in wantedExactItemRequests)
        {
            var title = CleanupRequestedItemTitle(wantedExactItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var needExactItemRequests = Regex.Matches(
            s,
            @"(?i)(?:^|[,.!?;]\s*)\b(?:il\s+me\s+faut|j['\u2019]ai\s+besoin\s+de|i\s+need|necesito|preciso\s+de|ich\s+brauche|ho\s+bisogno\s+di)\s+(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|el|los|las|o|a|os|as|der|die|das|il|lo|gli)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        foreach (Match needExactItemRequest in needExactItemRequests)
        {
            var title = CleanupRequestedItemTitle(needExactItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var doingExactItemRequests = Regex.Matches(
            s,
            @"(?i)(?:^|[,.!?;]\s*)\b(?:je\s+(?:fais|prepare|prépare)|nous\s+(?:faisons|preparons|préparons)|i\s+(?:am\s+)?(?:making|preparing)|we\s+(?:are\s+)?(?:making|preparing))\s+(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|some)\s+(?<title>[^:?.!,;]{3,90}?)(?:\s+(?:avec|pour|for|with)\b|[:?.!,;]|$)",
            RegexOptions.CultureInvariant);
        foreach (Match doingExactItemRequest in doingExactItemRequests)
        {
            var title = CleanupRequestedItemTitle(doingExactItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var whatIsExactItemRequests = Regex.Matches(
            s,
            @"(?i)(?:^|[,.!?;]\s*)\b(?:c['\u2019]est\s+quoi|qu['\u2019]est\s+ce\s+que|qu['\u2019]est-ce\s+que|what\s+is|what['\u2019]?s|que\s+es|o\s+que\s+e|was\s+ist|cos['\u2019]e|cosa\s+e)\s+(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|some|el|los|las|o|a|os|as|der|die|das|il|lo|gli)?\s*(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        foreach (Match whatIsExactItemRequest in whatIsExactItemRequests)
        {
            var title = CleanupRequestedItemTitle(whatIsExactItemRequest.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        var quantitySubject = Regex.Match(
            s,
            @"(?i)\b(?:quantit[e\u00e9]s?|quantites?|values?|valeurs?)\s+(?:pour|for)\s+\d+\s+(?:[\p{L}'\u2019-]+\s+){0,3}(?:de|du|des|de\s+la|de\s+l['\u2019]|d['\u2019]|of)\s+(?<title>[^:?.!,;]{3,90})",
            RegexOptions.CultureInvariant);
        if (quantitySubject.Success)
        {
            var title = CleanupRequestedItemTitle(quantitySubject.Groups["title"].Value);
            if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                return title;
        }

        if (Regex.IsMatch(
                s,
                @"(?i)\b(?:quantit[e\u00e9]s?|quantites?|organisation|amounts?|values?|valeurs?|counts?|units?|items?)\b|\b(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+\p{L}",
                RegexOptions.CultureInvariant))
        {
            var leadingSubject = Regex.Match(
                s,
                @"(?i)^(?<title>[\p{L}0-9'\u2019 \-]{3,90}?)(?:\s+(?:pour|for)\s+[^:?.!,;]{2,90}|:)",
                RegexOptions.CultureInvariant);
            if (leadingSubject.Success)
            {
                var title = CleanupRequestedItemTitle(leadingSubject.Groups["title"].Value);
                if (!string.IsNullOrWhiteSpace(title) && LooksLikeDirectRequestedItemTitle(title))
                    return title;
            }
        }

        return null;
    }

    private static bool LooksLikeGenericCollectionOrOptionRequestWithoutExactTitle(string? query)
    {
        if (LooksLikeGenericCollectionOrListRequest(query))
            return true;

        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;

        if (!Regex.IsMatch(
                s,
                @"\b(?:liste|lister|list|listing|selection|s[e\u00e9]lection|seleccion|selecao|opti(?:on|ons)|suggest(?:ion|ions)?|idee|idees|idea|ideas|choix|choice|choices|auswahl|scelta)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        var collectionTargets = Regex.Matches(
                s,
                @"\b(?:liste|lister|list|listing|selection|s[e\u00e9]lection|seleccion|selecao|options?|suggestions?|idees?|ideas?|choix|choices?)\b\s+(?:de|des|d['\u2019]?|du|de\s+la|de\s+l['\u2019]?|of|for|pour|sobre|su)\s+(?<target>[^:?.!,;]{2,90})",
                RegexOptions.CultureInvariant)
            .Cast<Match>()
            .Select(match => CleanupRequestedItemTitle(match.Groups["target"].Value))
            .Where(static target => !string.IsNullOrWhiteSpace(target))
            .ToArray();

        if (collectionTargets.Any(target => LooksLikeGenericCollectionTarget(target, s)))
            return true;

        var qualifiedListTarget = Regex.Match(
            s,
            @"\b(?:donne|donner|montre|montrer|trouve|trouver|cherche|chercher|give|show|find|suggest|propose|proposer)\b.{0,80}\b(?:liste|list|selection|s[e\u00e9]lection|options?|suggestions?|idees?|ideas?)\b.{0,40}\b(?:de|des|d['\u2019]?|of|for)\s+(?<target>[^:?.!,;]{2,90})",
            RegexOptions.CultureInvariant);
        return qualifiedListTarget.Success
            && LooksLikeGenericCollectionTarget(CleanupRequestedItemTitle(qualifiedListTarget.Groups["target"].Value), s);
    }

    private static bool LooksLikeGenericCollectionOrListRequest(string? query)
    {
        var raw = CollapseWhitespace(query ?? string.Empty);
        var s = NormalizeLexicalLookup(raw);
        if (string.IsNullOrWhiteSpace(s))
            return false;

        if (!string.IsNullOrWhiteSpace(TryExtractPdfFileNameRequestedTitle(raw)))
            return false;

        if (Regex.IsMatch(raw, "[\\u00ab\"'`](?<title>[^\\u00bb\"'`]{3,90})[\\u00bb\"'`]", RegexOptions.CultureInvariant))
            return false;

        var hasCollectionCue = Regex.IsMatch(
            s,
            @"\b(?:liste|lister|list|listing|selection|s[e\u00e9]lection|seleccion|selecao|options?|suggestions?|idees?|ideas?|choix|choices?|disponibles?|available|existent|exist|existe|trouve(?:s|es)?|found|corpus|documents?|docs?|sources?)\b",
            RegexOptions.CultureInvariant);
        if (!hasCollectionCue)
            return false;

        if (LooksLikeMultipleCandidateSynthesisRequest(query)
            && !Regex.IsMatch(s, @"\b(?:liste|lister|list|listing)\b", RegexOptions.CultureInvariant)
            && !Regex.IsMatch(
                s,
                @"\b(?:quels|quelles|quel|quelle|which|what|cuales|cuais|welche|quali)\s+(?:documents?|docs?|sources?|items?|elements?|entries?|procedures?|proc[e\u00e9]dures?)\b",
                RegexOptions.CultureInvariant)
            && !Regex.IsMatch(
                s,
                @"\b(?:documents?|docs?|sources?|corpus|dossier|category|categorie|cat[e\u00e9]gorie)\b.{0,40}\b(?:items?|elements?|entries?|procedures?|proc[e\u00e9]dures?|documents?|sources?)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        var articleCollection = Regex.Match(
            s,
            @"\b(?:donne|donner|montre|montrer|trouve|trouver|cherche|chercher|propose|proposer|suggest|give|show|find|list|lister)\b.{0,70}\b(?:les|des|some|the|los|las|os|as|die|gli)\s+(?<target>[\p{L}'\u2019 \-]{3,70}?)\s+(?:disponibles?|available|exist(?:ent|s)?|existe(?:nt)?|trouve(?:s|es)?|found|dans|in|du|de\s+la|des|of|from)\b",
            RegexOptions.CultureInvariant);
        if (articleCollection.Success
            && LooksLikeGenericCollectionTarget(CleanupRequestedItemTitle(articleCollection.Groups["target"].Value), s))
        {
            return true;
        }

        var questionCollection = Regex.Match(
            s,
            @"\b(?:quels|quelles|quel|quelle|which|what|cuales|cuais|welche|quali)\s+(?<target>[\p{L}'\u2019 \-]{3,70}?)\s+(?:sont|sont\s+disponibles|existent|exist|available|disponibles?|dans|in|du|de\s+la|des|of|from)\b",
            RegexOptions.CultureInvariant);
        if (questionCollection.Success
            && LooksLikeGenericCollectionTarget(CleanupRequestedItemTitle(questionCollection.Groups["target"].Value), s))
        {
            return true;
        }

        foreach (Match match in Regex.Matches(
                     s,
                     @"\b(?:liste|lister|list|listing|selection|s[e\u00e9]lection|seleccion|selecao|options?|suggestions?|idees?|ideas?|choix|choices?)\b\s+(?:de|des|d['\u2019]?|du|de\s+la|de\s+l['\u2019]?|of|for|pour|sobre|su)?\s*(?<target>[^:?.!,;]{2,90})",
                     RegexOptions.CultureInvariant))
        {
            if (LooksLikeGenericCollectionTarget(CleanupRequestedItemTitle(match.Groups["target"].Value), s))
                return true;
        }

        foreach (Match match in Regex.Matches(
                     s,
                     @"\b(?:donne|donner|montre|montrer|trouve|trouver|cherche|chercher|propose|proposer|suggest|give|show|find|list|lister)\b.{0,60}\b(?:les|des|some|the|los|las|os|as|die|gli)\s+(?<target>[^:?.!,;]{2,70}?)(?:\s+(?:disponibles?|available|exist(?:ent|s)?|existe(?:nt)?|trouve(?:s|es)?|found|dans|in|du|de\s+la|des|of|from)\b|[?.!,;]|$)",
                     RegexOptions.CultureInvariant))
        {
            if (LooksLikeGenericCollectionTarget(CleanupRequestedItemTitle(match.Groups["target"].Value), s))
                return true;
        }

        foreach (Match match in Regex.Matches(
                     s,
                     @"\b(?:quels|quelles|quel|quelle|which|what|cuales|cuais|welche|quali)\s+(?<target>[^:?.!,;]{2,70}?)(?:\s+(?:sont|sont\s+disponibles|existent|exist|available|disponibles?|dans|in|du|de\s+la|des|of|from)\b|[?.!,;]|$)",
                     RegexOptions.CultureInvariant))
        {
            if (LooksLikeGenericCollectionTarget(CleanupRequestedItemTitle(match.Groups["target"].Value), s))
                return true;
        }

        return false;
    }

    private static bool TryExtractGenericCollectionTarget(string? query, out string target)
    {
        target = string.Empty;
        var raw = CollapseWhitespace(query ?? string.Empty);
        var s = NormalizeLexicalLookup(raw);
        if (string.IsNullOrWhiteSpace(s)
            || !string.IsNullOrWhiteSpace(TryExtractPdfFileNameRequestedTitle(raw)))
        {
            return false;
        }

        foreach (var pattern in new[]
                 {
                     @"\b(?:liste|lister|list|listing|selection|s[e\u00e9]lection|seleccion|selecao|options?|suggestions?|idees?|ideas?|choix|choices?)\b\s+(?:de|des|d['\u2019]?|du|de\s+la|de\s+l['\u2019]?|of|for|pour|sobre|su)?\s*(?<target>[^:?.!,;]{2,90})",
                     @"\b(?:donne|donner|montre|montrer|trouve|trouver|cherche|chercher|propose|proposer|suggest|give|show|find|list|lister)\b.{0,70}\b(?:les|des|some|the|los|las|os|as|die|gli)\s+(?<target>[^:?.!,;]{2,70}?)(?:\s+(?:disponibles?|available|exist(?:ent|s)?|existe(?:nt)?|trouve(?:s|es)?|found|dans|in|du|de\s+la|des|of|from)\b|[?.!,;]|$)",
                     @"\b(?:quels|quelles|quel|quelle|which|what|cuales|cuais|welche|quali)\s+(?<target>[^:?.!,;]{2,70}?)(?:\s+(?:sont|sont\s+disponibles|existent|exist|available|disponibles?|dans|in|du|de\s+la|des|of|from)\b|[?.!,;]|$)"
                 })
        {
            foreach (Match match in Regex.Matches(s, pattern, RegexOptions.CultureInvariant))
            {
                var candidate = CleanupRequestedItemTitle(match.Groups["target"].Value);
                if (LooksLikeGenericCollectionTarget(candidate, s))
                {
                    target = candidate!;
                    return true;
                }
            }
        }

        return false;
    }

    private static bool LooksLikeGenericCollectionTarget(string? target, string normalizedQuery)
    {
        var normalizedTarget = NormalizeLexicalLookup(target);
        if (string.IsNullOrWhiteSpace(normalizedTarget))
            return false;

        if (normalizedTarget.Contains('.', StringComparison.Ordinal)
            || Regex.IsMatch(normalizedTarget, @"\b(?:pdf|docx?|xlsx?|pptx?|csv|txt|md)\b", RegexOptions.CultureInvariant)
            || LooksLikeCompactTechnicalIdentifier(normalizedTarget))
        {
            return false;
        }

        var terms = ExtractQuerySignalTerms(normalizedTarget).Take(5).ToArray();
        if (terms.Length is < 1 or > 4)
            return false;

        if (terms.All(IsGenericCollectionTargetFieldNoise))
            return false;

        if (terms.All(static term => IsGenericOptionSurfaceTerm(term) || IsGenericCollectionTargetFieldNoise(term)))
            return false;

        if (terms.Any(static term => term.Length <= 1 || Regex.IsMatch(term, @"\d", RegexOptions.CultureInvariant)))
            return false;

        if (terms.Length == 1)
            return true;

        var hasScopeCue = Regex.IsMatch(
            normalizedQuery,
            @"\b(?:disponibles?|available|trouve(?:s|es)?|found|sources?|documents?|docs?|corpus|dossier|category|categorie|cat[e\u00e9]gorie)\b",
            RegexOptions.CultureInvariant);
        var hasClassLikeEnding = terms.All(static term =>
            term.EndsWith("s", StringComparison.OrdinalIgnoreCase)
            || term.EndsWith("es", StringComparison.OrdinalIgnoreCase)
            || term.EndsWith("en", StringComparison.OrdinalIgnoreCase)
            || term.EndsWith("i", StringComparison.OrdinalIgnoreCase));

        return hasScopeCue || hasClassLikeEnding;
    }

    private static bool IsGenericCollectionTargetFieldNoise(string term)
    {
        var normalized = NormalizeLexicalLookup(term);
        return normalized is "source" or "sources" or "page" or "pages" or "document" or "documents"
            or "details" or "detail" or "info" or "infos" or "information" or "informations"
            or "etape" or "etapes" or "step" or "steps"
            or "temps" or "time" or "duration" or "duree" or "quantite" or "quantites"
            or "quantity" or "quantities" or "valeur" or "valeurs" or "value" or "values"
            or "extrait" or "extraits" or "excerpt" or "excerpts"
            or "partir" or "part" or "from" or "available" or "disponible" or "disponibles";
    }

    private static bool IsGenericOptionSurfaceTerm(string term)
    {
        var normalized = NormalizeLexicalLookup(term);
        return normalized is "option" or "options" or "suggestion" or "suggestions"
            or "idee" or "idees" or "idea" or "ideas" or "choix" or "choice" or "choices"
            or "utile" or "utiles" or "useful" or "available" or "disponible" or "disponibles"
            or "plusieurs" or "multiple" or "multiples" or "several" or "many";
    }

    private static string? TryExtractPdfFileNameRequestedTitle(string? query)
    {
        var s = NormalizeDocumentFileExtractionInput(query);
        if (s.Length == 0 || !s.Contains(".pdf", StringComparison.OrdinalIgnoreCase))
            return null;

        var quoted = Regex.Matches(
                s,
                @"(?i)(?:`|""|\u00ab|\u201c)(?<title>[^`""\u00ab\u00bb\u201c\u201d]{2,300}?\.(?:pdf|docx?|xlsx?|pptx?|md|txt|csv))(?:`|""|\u00bb|\u201d)",
                RegexOptions.CultureInvariant)
            .Cast<Match>()
            .Select(match => CleanupExplicitDocumentFileTitle(match.Groups["title"].Value))
            .Where(static title => !string.IsNullOrWhiteSpace(title))
            .OrderByDescending(static title => title!.Length)
            .FirstOrDefault();
        if (!string.IsNullOrWhiteSpace(quoted))
            return quoted;

        var introduced = Regex.Matches(
                s,
                @"(?i)\b(?:de|du|des|d['\u2019]|dans|sur|pour|concernant|from|of|for|in|about|regarding|sobre|ueber|über|su)\s+[`""'\u00ab\u201c]?(?<title>[\p{L}\p{N}][^?;`""\u00ab\u00bb\u201c\u201d]{2,260}?\.pdf)[`""'\u00bb\u201d]?\b",
                RegexOptions.CultureInvariant)
            .Cast<Match>()
            .Select(match => CleanupExplicitDocumentFileTitle(match.Groups["title"].Value))
            .Where(static title => !string.IsNullOrWhiteSpace(title))
            .Select(static title => title!);

        var bare = Regex.Matches(
                s,
                @"(?i)[`""'\u00ab\u201c]?(?<title>[\p{L}\p{N}][\p{L}\p{N}'\u2019 .,+_()&/\-\u2010-\u2015]{2,260}?\.pdf)[`""'\u00bb\u201d]?\b",
                RegexOptions.CultureInvariant)
            .Cast<Match>()
            .Select(match => CleanupExplicitDocumentFileTitle(match.Groups["title"].Value))
            .Where(static title => !string.IsNullOrWhiteSpace(title))
            .Select(static title => title!);

        return FilterExplicitDocumentFileTitleCandidates(introduced.Concat(bare)).FirstOrDefault();
    }

    private static int CountExplicitDocumentFileReferences(string? query)
        => ExtractExplicitDocumentFileReferenceQueries(query).Count;

    private static IReadOnlyList<string> ExtractExplicitDocumentFileReferenceQueries(string? query)
    {
        var s = NormalizeDocumentFileExtractionInput(query);
        if (s.Length == 0)
            return Array.Empty<string>();

        var candidates = new List<string>();
        var introducedPdfTitle = TryExtractPdfFileNameRequestedTitle(query);
        if (!string.IsNullOrWhiteSpace(introducedPdfTitle))
            candidates.Add(introducedPdfTitle!);

        candidates.AddRange(Regex.Matches(
                s,
                @"(?i)(?<title>[\p{L}\p{N}][\p{L}\p{N}'\u2019 .,+_()&/\-\u2010-\u2015]{2,260}?\.(?:pdf|docx?|xlsx?|pptx?|md|txt|csv))\b",
                RegexOptions.CultureInvariant)
            .Cast<Match>()
            .Select(match => CleanupExplicitDocumentFileTitle(match.Groups["title"].Value))
            .Where(static title => !string.IsNullOrWhiteSpace(title))
            .Select(static title => title!));

        return FilterExplicitDocumentFileTitleCandidates(candidates);
    }

    private static IReadOnlyList<string> FilterExplicitDocumentFileTitleCandidates(IEnumerable<string> candidates)
    {
        var distinctCandidates = candidates
            .Where(static candidate => !string.IsNullOrWhiteSpace(candidate))
            .GroupBy(NormalizeDocumentLookupText, StringComparer.Ordinal)
            .Select(static group => group.First())
            .ToArray();

        return distinctCandidates
            .Where(candidate => !distinctCandidates.Any(other =>
                !string.Equals(candidate, other, StringComparison.OrdinalIgnoreCase)
                && ((IsSuffixDocumentFileTitle(other, candidate)
                        && !ShouldPreferSuffixDocumentFileTitle(other, candidate))
                    || (IsSuffixDocumentFileTitle(candidate, other)
                        && ShouldPreferSuffixDocumentFileTitle(candidate, other)))))
            .ToArray();
    }

    private static bool IsSuffixDocumentFileTitle(string longer, string shorter)
    {
        var longerCollapsed = CollapseWhitespace(longer);
        var shorterCollapsed = CollapseWhitespace(shorter);
        if (shorterCollapsed.Length == 0 || longerCollapsed.Length <= shorterCollapsed.Length + 2)
            return false;

        return longerCollapsed.EndsWith(shorterCollapsed, StringComparison.OrdinalIgnoreCase)
            || NormalizeDocumentLookupText(longerCollapsed).EndsWith(NormalizeDocumentLookupText(shorterCollapsed), StringComparison.Ordinal);
    }

    private static bool ShouldPreferSuffixDocumentFileTitle(string longer, string suffix)
    {
        var longerCollapsed = CollapseWhitespace(longer);
        var suffixCollapsed = CollapseWhitespace(suffix);
        if (!longerCollapsed.EndsWith(suffixCollapsed, StringComparison.OrdinalIgnoreCase))
            return false;

        var prefix = longerCollapsed[..^suffixCollapsed.Length].Trim();
        if (prefix.Length == 0)
            return false;

        return Regex.IsMatch(
                prefix,
                @"(?i)\b(?:affiche|afficher|combien|comment|donne|donner|extrais|extraire|explique|expliquer|fais|faire|montre|montrer|prepare|preparer|pr[e\u00e9]pare|pr[e\u00e9]parer|quel|quelle|quels|quelles|resume|r[e\u00e9]sume|resumer|r[e\u00e9]sumer|retrouve|retrouver|show|what|which|how|give|extract|explain|prepare|summarize|find)\b",
                RegexOptions.CultureInvariant)
            && Regex.IsMatch(
                prefix,
                @"(?i)\b(?:de|du|des|d['\u2019]|dans|sur|pour|concernant|from|of|for|in|about|regarding|sobre|ueber|Ã¼ber|su)\s*$",
                RegexOptions.CultureInvariant);
    }

    private static string? CleanupExplicitDocumentFileTitle(string? value)
    {
        var title = NormalizeDocumentFileExtractionInput(value)
            .Trim(' ', ':', '-', '.', '?', '!', ',', ';', '"', '\'', '`', '\u00ab', '\u00bb', '\u201c', '\u201d');
        if (title.Length == 0)
            return null;

        title = Regex.Replace(
            title,
            @"(?i)^(?:compare|comparer|comparaison|comparatif|comparative|confronta|confrontare|vergleiche|vergleichen|paragona|paragonare)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)^(?:et|and|y|e|und|vs|versus)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)^(?:dans|sur|pour|concernant|from|of|for|in|about|regarding|sobre|ueber|über|su)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim(' ', ':', '-', '.', '?', '!', ',', ';', '"', '\'', '`', '\u00ab', '\u00bb', '\u201c', '\u201d');

        return Regex.IsMatch(title, @"\.(?:pdf|docx?|xlsx?|pptx?|md|txt|csv)$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)
            ? title
            : null;
    }

    private static string NormalizeDocumentFileExtractionInput(string? value)
        => Regex.Replace(value ?? string.Empty, @"[\r\n\t]+", " ").Trim();

    private static bool LooksLikeSoftChoiceRecommendationRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(
                normalized,
                @"\b(?:vitesses?|speeds?|temperatures?|temperatures?|reglages?|settings?|parametres?|parameters?|quantites?|quantites?|etapes?|steps?|temps|time|values?|valeurs?)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        var hasChoiceCue = Regex.IsMatch(
            normalized,
            @"\b(?:choisir|choisis|choix|conseille|conseiller|recommande|recommander|propose|proposer|suggest|suggestion|recommend|choose|select|choice|which|what|quel|quelle|quels|quelles|cual|cuales|que|elegir|elige|escoger|escoge|recomienda|recomendar|aconseja|aconsejar|propone|proponer|sugiere|sugerir|qual|quais|escolher|escolhe|recomenda|recomendar|aconselha|aconselhar|propoe|propor|sugere|sugerir|welche|welcher|welches|was|waehlen|waehle|wahlen|wahle|empfiehl|empfehlen|rate|raten|vorschlag|quale|quali|cosa|scegliere|scegli|consiglia|consigliare|proponi|proporre|suggerisci|suggerire)\b",
            RegexOptions.CultureInvariant);
        if (!hasChoiceCue)
            return false;

        var hasRequestedOptionKind = Regex.IsMatch(
            normalized,
            @"\b(?:quel|quelle|quels|quelles|which|what|cual|qual|welche|welcher|welches|quale)\s+[\p{L}][\p{L}'\u2019-]{2,30}\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:option|options|idee|idees|idea|ideas|item|items|element|elements|solution|solutions|methode|methodes|method|methods|approche|approaches|opcion|opciones|opcao|opcoes|solucion|soluciones|solucao|solucoes|alternativa|alternativas|auswahl|vorschlag|vorschlaege|vorschlage|losung|loesung|losungen|loesungen|opzione|opzioni|scelta|scelte|soluzione|soluzioni|alternative)\b",
                RegexOptions.CultureInvariant);
        if (!hasRequestedOptionKind)
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:pour|for|para|per|avec|with|con|com|mit|adapte|adaptee|adapted|adaptado|adaptada|adequado|adequada|adatto|adatta|geeignet|passend|suitable|compatible|compatibile|compatibel|conseille|recommend|recommendation|recomienda|recomendar|recomenda|recomendar|empfiehl|empfehlen|consiglia|consigliare)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeBroadSourceBackedCompositionRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(normalized, @"\b(?:document|fiche|card|procedure|process)\s+(?:de|du|des|pour|about|on)\b", RegexOptions.CultureInvariant))
            return false;

        if (Regex.IsMatch(
                normalized,
                @"\b(?:quel|quelle|which|what|cual|qual|welche|welcher|welches|quale)\s+(?:option|opcion|opcao|opzione)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        var hasBroadIntent = Regex.IsMatch(
            normalized,
            @"\b(?:plan\s+complet|planning\s+complet|complete\s+plan|composition|compose|composer|propose|proposes|options?|idees?|suggestions?|selection|quoi\s+faire|what\s+to\s+use|which\s+option|proponer|propone|sugerir|sugiere|recomendar|recomienda|opciones|ideas|seleccion|composicion|o\s+que\s+fazer|propor|propoe|sugere|sugerir|opcoes|ideias|selecao|composicao|vorschlag|vorschlaege|vorschlage|empfehlen|optionen|ideen|auswahl|zusammenstellen|proponi|proporre|suggerisci|suggerire|opzioni|idee|scelta|composizione)\b",
            RegexOptions.CultureInvariant);

        return hasBroadIntent
            || Regex.IsMatch(
                normalized,
                @"\b(?:plan|planning|programme|program|selection|composition|programa|seleccion|composicion|plano|selecao|composicao|programm|auswahl|piano|programma|scelta|composizione)\s+(?:de|du|des|pour|for|about|para|per|fuer|fur)\b.*\b(?:avec|with|con|com|mit)\b",
                RegexOptions.CultureInvariant);
    }

    private static string? CleanupRequestedItemTitle(string? value)
    {
        var title = CollapseWhitespace(value ?? string.Empty)
            .Trim(' ', ':', '-', '.', '?', '!', ',', ';');
        if (title.Length == 0)
            return null;
        var originalTitle = title;

        if (title.Contains(".pdf", StringComparison.OrdinalIgnoreCase))
        {
            title = Regex.Replace(
                title,
                @"(?i)^(?:compare|comparer|comparaison|comparatif|comparative|confronta|confrontare|vergleiche|vergleichen|paragona|paragonare)\s+",
                string.Empty,
                RegexOptions.CultureInvariant).Trim();
        }

        title = Regex.Replace(
            title,
            @"(?i)^(?:le|la|les|l['\u2019]|un|une|des|du|de\s+la|de\s+l['\u2019]|the|a|an|some)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)^(?:fiche|card|document|source|element|item|objet|sujet|topic|procedure|process|methode|method)\s+(?:claire\s+|detaillee\s+|detaill[eé]e\s+|complete\s+|compl[eè]te\s+|sourcee\s+|sourc[eé]e\s+|clear\s+|detailed\s+)?(?:de\s+base\s+|base\s+)?(?:pour|about|on|de|du|de\s+la|des|d['\u2019]|sur|of|for|sobre|ueber|über|su)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();


        title = Regex.Replace(
            title,
            @"(?i)\s+(?:en\s+mode|mode|version|variante|pour\s+(?:\d+|un|une|des|le|la|les|l['\u2019]|the|a|an|some)\b|dans\s+(?:le|la|les|l['\u2019]|un|une|des|the|a|an)\b|du\s+(?:guide|pdf|document|manuel|livre|book|manual|file|document|corpus|dossier)\b|de\s+la\s+(?:base|page|fiche|notice|section)\b|des\s+(?:sources|documents|docs|fichiers|files)\b).*$",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();
        title = Regex.Replace(
            title,
            @"(?i)^(?:[\p{L}][\p{L}'\u2019-]{2,24}\s+){1,4}(?:de\s+base\s+|base\s+)?(?:pour|about|on|de|du|de\s+la|des|d['\u2019]|sur|of|for|sobre|ueber|über|su)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)^(?:element|item|objet|sujet|topic)\s+(?:de\s+base\s+)?(?:pour|about|on|de|du|de\s+la|des|d['\u2019]|sur|sobre|ueber|über|su)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)^base\s+(?:des|du|de\s+la|de\s+l['\u2019]|de|pour|about|on|d['\u2019]|sur|sobre|ueber|über|su)\s+",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)\s+(?:etapes?|[ée]tapes?|steps?|temps|time|source|sources|quantites?|values?|valeurs?|reglages?|r[ée]glages?)\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)\s+(?:disponibles?|available|exist(?:ent|s)?|existe(?:nt)?|trouve(?:s|es)?|found)\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        var preservedTitle = CleanupQuotedRequestedItemTitle(originalTitle);
        if (!string.IsNullOrWhiteSpace(preservedTitle)
            && LooksLikeConnectorInsideNaturalTitle(preservedTitle)
            && !LooksLikeGenericTitleDescriptorPrefix(preservedTitle)
            && LooksLikeDirectRequestedItemTitle(preservedTitle))
        {
            title = preservedTitle;
        }

        return title.Length >= 3 ? title : null;
    }

    private static string? CleanupQuotedRequestedItemTitle(string? value)
    {
        var title = CollapseWhitespace(value ?? string.Empty)
            .Trim(' ', ':', '-', '.', '?', '!', ',', ';', '"', '\'', '\u00ab', '\u00bb');
        if (title.Length == 0)
            return null;

        title = Regex.Replace(
            title,
            @"(?i)\s+(?:en\s+mode|mode|version|variante|pour\s+(?:\d+|un|une|des|le|la|les|l['\u2019]|the|a|an|some)\b|dans\s+(?:le|la|les|l['\u2019]|un|une|des|the|a|an)\b|du\s+(?:guide|pdf|document|manuel|livre|book|manual|file|document|corpus|dossier)\b|de\s+la\s+(?:base|page|fiche|notice|section)\b|des\s+(?:sources|documents|docs|fichiers|files)\b).*$",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        title = Regex.Replace(
            title,
            @"(?i)\s+(?:etapes?|[Ã©e]tapes?|steps?|temps|time|source|sources|quantites?|values?|valeurs?|reglages?|r[Ã©e]glages?)\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant).Trim();

        return title.Length >= 3 ? title : null;
    }

    private static bool LooksLikeConnectorInsideNaturalTitle(string? value)
    {
        var normalized = NormalizeLexicalLookup(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"^[\p{L}\p{N}'\u2019-]{3,}(?:\s+[\p{L}\p{N}'\u2019-]{2,}){0,4}\s+(?:de|du|des|d|of|with|a|au|aux|al|alla|di|con|mit)\s+[\p{L}\p{N}'\u2019-]{3,}",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeGenericTitleDescriptorPrefix(string? value)
    {
        var normalized = NormalizeLexicalLookup(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"^(?:fiche|card|document|source|element|item|objet|sujet|topic|procedure|process|methode|method|option|idee|idea|preparation|rapport|report|guide|manuel|manual|base)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeDirectRequestedItemTitle(string title)
    {
        var normalized = NormalizeLexicalLookup(title);
        if (normalized.Length < 3 || normalized.Length > 90)
            return false;

        if (Regex.IsMatch(normalized, @"^(?:corpus|documents?|sources?|fichiers?|files?|pdf)$", RegexOptions.CultureInvariant))
            return false;

        if (Regex.IsMatch(
                normalized,
                @"^(?:quantites?|quantit[e\u00e9]s?|quantities?|amounts?|values?|valeurs?|counts?|units?)$",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        if (Regex.IsMatch(normalized, @"^\d+\s+(?:items?|elements?|units?|pieces?)\b", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"^\d+\s+[\p{L}'\u2019.\-]{2,30}$", RegexOptions.CultureInvariant))
            return false;

        if (Regex.IsMatch(
                normalized,
                @"^(?:que|qu|tu|vous|me|moi|mets?|mettre|put|documents?|sources?|fichiers?|files?|what|which|how|comment)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:ca|cela|ceci|this|that|it|eso|esto|isso|isto|das|questo|quello)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:documents?|sources?|fichiers?|files?)\s+(?:qui|that)\s+(?:parle|parlent|mentionne|mentionnent|traite|traitent|talk|mentions?)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        return ExtractQuerySignalTerms(normalized).Any()
            || ExtractRequestedTitleSignalTerms(normalized).Any();
    }

    private static bool RagHitsContainRequestedTitle(IReadOnlyList<RagHitSummary> hits, string requestedTitle)
    {
        if (string.IsNullOrWhiteSpace(requestedTitle))
            return false;

        foreach (var hit in hits)
        {
            if (RagHitContainsRequestedTitle(hit, requestedTitle))
                return true;
        }

        return false;
    }

    private static bool RagHitContainsRequestedTitle(RagHitSummary hit, string requestedTitle)
    {
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        if (string.IsNullOrWhiteSpace(normalizedTitle))
            return false;

        var titleTerms = ExtractRequestedTitleSignalTerms(normalizedTitle);

        if (RagHitContainsRequestedTitle(hit, normalizedTitle, titleTerms))
            return true;

        foreach (var variant in BuildTypoTolerantQueryVariants(normalizedTitle))
        {
            var normalizedVariant = NormalizeLexicalLookup(variant);
            if (string.IsNullOrWhiteSpace(normalizedVariant))
                continue;

            var variantTerms = ExtractRequestedTitleSignalTerms(normalizedVariant);

            if (RagHitContainsRequestedTitle(hit, normalizedVariant, variantTerms))
                return true;
        }

        return false;
    }

    private static bool RagHitHasUsableRequestedTitleAnchor(string requestedTitle, RagHitSummary hit)
    {
        if (LooksLikeNavigationOnlyHit(hit) || string.IsNullOrWhiteSpace(requestedTitle))
            return false;

        if (ComputeBestSourceBackedDisplayTitleScore(requestedTitle, hit) >= 40)
            return true;

        if (RagHitContainsRequestedTitlePhraseAnchor(hit, requestedTitle))
            return true;

        if (RagHitHasCoherentRequestedTitleContent(hit, requestedTitle))
            return true;

        return ComputeExactItemAnchorStrengthScore(requestedTitle, hit) >= 80;
    }

    private static bool HasStrongExactItemTitleAnchor(string requestedTitle, RagHitSummary hit)
    {
        if (string.IsNullOrWhiteSpace(requestedTitle))
            return false;

        return ComputeBestSourceBackedDisplayTitleScore(requestedTitle, hit) >= 40
               || RagHitContainsRequestedTitlePhraseAnchor(hit, requestedTitle)
               || ComputeExactVisibleTitleMatchScore(requestedTitle, hit) >= 40;
    }

    private static bool ExactItemEvidenceStartsWithRequestedTitle(string requestedTitle, RagHitSummary hit)
    {
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        if (string.IsNullOrWhiteSpace(normalizedTitle))
            return false;

        foreach (var candidate in new[]
                 {
                     hit.Excerpt,
                     hit.FullText,
                     string.IsNullOrWhiteSpace(hit.ContextualSnippet) ? null : StripContextualMetadataForEvidence(hit.ContextualSnippet!)
                 })
        {
            var normalized = NormalizeLexicalLookup(candidate);
            if (string.IsNullOrWhiteSpace(normalized))
                continue;

            if (TextStartsWithRequestedTitlePhrase(normalized, normalizedTitle))
                return true;

            foreach (var variant in BuildTypoTolerantQueryVariants(normalizedTitle))
            {
                var normalizedVariant = NormalizeLexicalLookup(variant);
                if (!string.IsNullOrWhiteSpace(normalizedVariant)
                    && TextStartsWithRequestedTitlePhrase(normalized, normalizedVariant))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private static bool IsUsableExactItemNavigationOverride(string? requestedTitle, RagHitSummary hit)
    {
        if (string.IsNullOrWhiteSpace(requestedTitle))
            return false;
        if (!LooksLikeNavigationOnlyHit(hit))
            return false;
        if (LooksLikePageReferenceOnlyHit(hit) || LooksLikeExactItemReferenceOnlyHit(requestedTitle!, hit))
            return false;

        if (!ExactItemEvidenceStartsWithRequestedTitle(requestedTitle!, hit)
            && !HasStrongExactItemTitleAnchor(requestedTitle!, hit))
            return false;

        var evidence = GetFocusedExactItemEvidenceText(requestedTitle!, hit);
        var structuredCueScore = Math.Max(0, ComputeExactItemCardCompletenessCueScore(hit))
                                 + Math.Max(0, ComputeProcedureCompletenessCueScore(hit))
                                 + Math.Max(0, ComputeStructuredProcedureVisibleEvidenceCueScore(hit));
        if (structuredCueScore >= 4)
            return true;
        if (ExtractVisibleDurationsAndQuantities(evidence).Length > 0)
            return true;
        if (ExtractContentCardEvidenceFacts(new[] { hit }).Length > 0)
            return true;

        var normalizedEvidence = NormalizeLexicalLookup(evidence);
        return CountProcedureStepMarkers(normalizedEvidence) > 0
               || Regex.IsMatch(
                   normalizedEvidence,
                   @"\b(?:items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?|preparation|pr[e\u00e9]paration|operation|workflow|execution|procedure|etapes?|[e\u00e9]tapes?|temps|time|pour\s+\d{1,3}\s+\p{L}|\d+\s*(?:g|kg|mg|ml|cl|l|min(?:ute)?s?|h|heures?|hours?))\b",
                   RegexOptions.CultureInvariant);
    }

    private static bool RagHitHasCoherentRequestedTitleContent(RagHitSummary hit, string requestedTitle)
    {
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        var titleTerms = ExtractRequestedTitleSignalTerms(normalizedTitle);
        if (titleTerms.Length == 0)
            return false;

        var content = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        if (string.IsNullOrWhiteSpace(content))
            return false;

        if (!titleTerms.All(term => content.Contains(term, StringComparison.Ordinal)))
            return false;

        if (titleTerms.Length <= 2)
        {
            var lead = CollapseWhitespace(hit.Excerpt ?? string.Empty);
            if (lead.Length > 360)
                lead = lead[..360];
            var normalizedLead = NormalizeLexicalLookup(lead);
            return IndexOfRequestedTitlePhrase(normalizedLead, normalizedTitle) is >= 0 and <= 160
                && ComputeExactVisibleTitleMatchScore(requestedTitle, hit) >= 40;
        }

        return ComputeExactItemCardCompletenessCueScore(hit) >= 4
            || ComputeProcedureCompletenessCueScore(hit) >= 4
            || CountProcedureStepMarkers(content) >= 2;
    }

    private static bool RagHitContainsRequestedTitlePhraseAnchor(RagHitSummary hit, string requestedTitle)
    {
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        if (string.IsNullOrWhiteSpace(normalizedTitle))
            return false;

        var titleAnchors = NormalizeLexicalLookup(string.Join(' ', new[]
        {
            string.Join(' ', hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>()),
            string.Join(' ', ExtractProfileTitleCandidates(hit.ContextualSnippet ?? string.Empty)),
            hit.SectionTitle ?? string.Empty,
            hit.HeadingPath ?? string.Empty
        }));

        if (ContainsRequestedTitlePhrase(titleAnchors, normalizedTitle))
            return true;

        var lead = CollapseWhitespace(hit.Excerpt ?? string.Empty);
        if (lead.Length > 360)
            lead = lead[..360];
        var normalizedLead = NormalizeLexicalLookup(lead);
        var leadIndex = IndexOfRequestedTitlePhrase(normalizedLead, normalizedTitle);
        if (leadIndex == 0 && TextStartsWithRequestedTitlePhrase(normalizedLead, normalizedTitle))
            return true;
        if (leadIndex is >= 0 and <= 160 && ComputeExactVisibleTitleMatchScore(requestedTitle, hit) >= 40)
            return true;

        var contextualLead = CollapseWhitespace(StripContextualMetadataForEvidence(hit.ContextualSnippet ?? string.Empty));
        if (contextualLead.Length > 360)
            contextualLead = contextualLead[..360];
        var normalizedContextualLead = NormalizeLexicalLookup(contextualLead);
        var contextualLeadIndex = IndexOfRequestedTitlePhrase(normalizedContextualLead, normalizedTitle);
        if (contextualLeadIndex == 0 && TextStartsWithRequestedTitlePhrase(normalizedContextualLead, normalizedTitle))
            return true;
        if (contextualLeadIndex is >= 0 and <= 160 && ComputeExactVisibleTitleMatchScore(requestedTitle, hit) >= 40)
            return true;

        foreach (var variant in BuildTypoTolerantQueryVariants(normalizedTitle))
        {
            var normalizedVariant = NormalizeLexicalLookup(variant);
            if (ContainsRequestedTitlePhrase(titleAnchors, normalizedVariant))
            {
                return true;
            }

            leadIndex = IndexOfRequestedTitlePhrase(normalizedLead, normalizedVariant);
            if (leadIndex is >= 0 and <= 160 && ComputeExactVisibleTitleMatchScore(normalizedVariant, hit) >= 40)
                return true;
        }

        return false;
    }

    private static bool TextStartsWithRequestedTitlePhrase(string normalizedText, string normalizedTitle)
        => !string.IsNullOrWhiteSpace(normalizedText)
           && !string.IsNullOrWhiteSpace(normalizedTitle)
           && (normalizedText.Equals(normalizedTitle, StringComparison.Ordinal)
               || normalizedText.StartsWith(normalizedTitle + " ", StringComparison.Ordinal));

    private static bool ContainsRequestedTitlePhrase(string haystack, string normalizedTitle)
        => IndexOfRequestedTitlePhrase(haystack, normalizedTitle) >= 0;

    private static int IndexOfRequestedTitlePhrase(string haystack, string normalizedTitle)
    {
        if (string.IsNullOrWhiteSpace(haystack) || string.IsNullOrWhiteSpace(normalizedTitle))
            return -1;

        return haystack.IndexOf(normalizedTitle, StringComparison.Ordinal);
    }

    private static bool RagHitContainsRequestedTitle(RagHitSummary hit, string normalizedTitle, IReadOnlyList<string> titleTerms)
    {
        if (LooksLikeNavigationOnlyHit(hit))
            return false;

        var haystack = NormalizeLexicalLookup($"{hit.DocName} {hit.DocPath} {hit.SectionTitle} {hit.HeadingPath} {hit.Excerpt} {hit.FullText} {hit.ContextualSnippet}");
        if (haystack.Contains(normalizedTitle, StringComparison.Ordinal))
            return true;

        return titleTerms.Count > 0 && titleTerms.All(term => haystack.Contains(term, StringComparison.Ordinal));
    }

    private static string[] ExtractRequestedTitleSignalTerms(string normalizedTitle)
    {
        var normalized = NormalizeLexicalLookup(normalizedTitle);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var stopWords = new HashSet<string>(StringComparer.Ordinal)
        {
            "a", "an", "and", "au", "aux", "avec", "con", "da", "das", "de", "dei", "del", "della",
            "der", "des", "di", "do", "dos", "du", "e", "el", "en", "et", "for", "il", "in", "la",
            "las", "le", "les", "lo", "of", "on", "os", "per", "pour", "sur", "the", "to", "un",
            "una", "une", "und", "y"
        };

        var tokens = Regex.Matches(normalized, @"[\p{L}\p{N}]{1,}")
            .Select(match => match.Value)
            .Where(token => !string.IsNullOrWhiteSpace(token))
            .ToArray();
        if (tokens.Length == 0)
            return Array.Empty<string>();

        var terms = new List<string>();
        for (var i = 0; i < tokens.Length; i++)
        {
            var token = tokens[i];
            if (stopWords.Contains(token))
                continue;

            if (token.Length >= 4 || token.Any(char.IsDigit))
            {
                terms.Add(token);
                continue;
            }

            var isShortDisambiguator = token.Length is 2 or 3
                && (i == tokens.Length - 1 || tokens.Length <= 3);
            if (isShortDisambiguator)
                terms.Add(token);
        }

        return terms
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
    }

    private static bool LooksLikeNavigationOnlyHit(RagHitSummary hit)
    {
        if (BackendSelectionHintsPreferUsableEvidence(hit))
            return false;
        if (LooksLikeResolvedRouteTargetHit(hit))
            return false;
        if (BackendSelectionHintsPreferNavigation(hit))
            return true;

        var text = hit.Excerpt ?? string.Empty;
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var normalized = NormalizeLexicalLookup(text);
        var hasStructuredEvidenceCue = Regex.IsMatch(
            normalized,
            @"\b(?:preparation|operation|workflow|execution|procedure|procedures?|process|instruction|instructions|etape|etapes|step|steps|quantity|quantite|value|valeur|\d+\s*(?:g|kg|mg|ml|cl|l|min(?:ute)?s?|h|heures?|hours?|c|celsius))\b",
            RegexOptions.CultureInvariant);
        var hasNavigationCue = Regex.IsMatch(
            normalized,
            @"\b(?:sommaire|table des matieres|contents|index|inhaltsverzeichnis|indice|reperes de contenu|reperes contenus?|repere de contenu|sections principales|premiers extraits|table of contents|content overview)\b",
            RegexOptions.CultureInvariant);
        if (hasNavigationCue)
        {
            if (!hasStructuredEvidenceCue)
                return true;
        }

        var leaderCount = Regex.Matches(text, @"\.{3,}\s*\d{1,4}\b", RegexOptions.CultureInvariant).Count;
        if (leaderCount >= 3)
            return true;

        var compactListCount = Regex.Matches(text, @"[\p{L}\)]\d{1,3}(?:[•\u2022]|\s*[A-Z\u00c0-\u017f])", RegexOptions.CultureInvariant).Count;
        var titlePageRefs = Regex.Matches(
            normalized,
            @"\b[\p{L}][\p{L}'\-\s]{4,48}\s+\d{1,3}\b",
            RegexOptions.CultureInvariant).Count;
        var shortTitlePageSequence = Regex.IsMatch(
            normalized,
            @"\b[\p{L}'\-]{4,}(?:\s+[\p{L}'\-]{2,}){0,5}\s+\d{2,3}\s+[\p{L}'\-]{4,}",
            RegexOptions.CultureInvariant);
        return (compactListCount >= 6 || titlePageRefs >= 8 || (shortTitlePageSequence && normalized.Length < 420)) && !hasStructuredEvidenceCue
               || (hasNavigationCue && titlePageRefs >= 3);
    }

    private static bool ShouldExposeHitForSourceBackedEvidenceDiscovery(RagHitSummary hit)
    {
        if (LooksLikeResolvedRouteTargetHit(hit))
            return true;
        if (LooksLikeNavigationOnlyHit(hit))
            return IsRouteDiscoveryAnchorHit(hit);

        return !LooksLikeLowSignalContentCandidateHit(hit);
    }

    private static bool LooksLikeResolvedRouteTargetHit(RagHitSummary hit)
    {
        if (!LooksLikeTrustedResolvedRouteRetriever(hit))
            return false;
        if (string.IsNullOrWhiteSpace(hit.DocPath) && string.IsNullOrWhiteSpace(hit.DocName))
            return false;
        if (hit.PageStart <= 0)
            return false;

        var evidence = CollapseWhitespace(GetBestRagEvidenceText(hit));
        if (LooksLikeRouteTargetStructuredEvidence(evidence))
            return true;

        var contentRole = NormalizeLexicalLookup(hit.ContentRole);
        if (contentRole.Contains("content", StringComparison.Ordinal)
            && evidence.Length >= 80
            && !LooksLikePureRouteNavigationText(evidence))
        {
            return true;
        }

        if (hit.MatchedContentCards is { Count: > 0 } cards)
        {
            if (cards.Any(static card =>
                    card.RawEvidence.HasValue
                    || card.Evidence is { QuantityFacts.Count: > 0 }
                    || card.Evidence?.Facts is { Count: > 0 }))
            {
                return true;
            }

            if (cards.Any(static card => IsUsableSourceBackedOptionTitle(card.Title)))
                return true;
        }

        return false;
    }

    private static bool IsRouteDiscoveryAnchorHit(RagHitSummary hit)
    {
        if (!LooksLikeRouteBasedRetrievalHit(hit) && !HasRouteContentCardCue(hit))
            return false;
        if (string.IsNullOrWhiteSpace(hit.DocPath) && string.IsNullOrWhiteSpace(hit.DocName))
            return false;
        if (hit.PageStart <= 0)
            return false;

        var cue = ExtractRouteDiscoveryTitleCue(hit);
        if (!string.IsNullOrWhiteSpace(cue))
            return true;

        if (!string.IsNullOrWhiteSpace(hit.SectionTitle) || !string.IsNullOrWhiteSpace(hit.HeadingPath))
            return true;

        return CollapseWhitespace(GetBestRagEvidenceText(hit)).Length >= 40;
    }

    private static bool LooksLikeRouteBasedRetrievalHit(RagHitSummary hit)
        => ContainsRouteRetrievalCue(hit.Retriever)
           || ContainsRouteRetrievalCue(hit.EmbeddingBasis);

    private static bool LooksLikeTrustedResolvedRouteRetriever(RagHitSummary hit)
        => ContainsTrustedResolvedRouteCue(hit.Retriever)
           || ContainsTrustedResolvedRouteCue(hit.EmbeddingBasis);

    private static bool ContainsRouteRetrievalCue(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return false;

        return value.Contains("navigation_route", StringComparison.OrdinalIgnoreCase)
               || value.Contains("title_anchor_route", StringComparison.OrdinalIgnoreCase)
               || value.Contains("direct_title_token_route", StringComparison.OrdinalIgnoreCase)
               || value.Contains("local_title_token_route", StringComparison.OrdinalIgnoreCase)
               || value.Contains("explicit_document_title_route", StringComparison.OrdinalIgnoreCase)
               || value.Contains("fuzzy_title_lead", StringComparison.OrdinalIgnoreCase);
    }

    private static bool ContainsTrustedResolvedRouteCue(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return false;

        return value.Contains("navigation_route", StringComparison.OrdinalIgnoreCase)
               || value.Contains("title_anchor_route", StringComparison.OrdinalIgnoreCase)
               || value.Contains("explicit_document_title_route", StringComparison.OrdinalIgnoreCase);
    }

    private static bool HasRouteContentCardCue(RagHitSummary hit)
        => hit.MatchedContentCards is { Count: > 0 } cards
           && cards.Any(static card =>
               ContainsRouteRetrievalCue(card.Kind)
               || card.Signals?.Any(ContainsRouteRetrievalCue) == true);

    private static bool LooksLikeRouteTargetStructuredEvidence(string? evidence)
    {
        var normalized = NormalizeLexicalLookup(evidence);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:preparation|preparer|procedure|procedures?|operation|workflow|instruction|instructions|etape|etapes|steps?|duration|duree|temps|quantity|quantite|valeur|value|\d+\s*(?:g|kg|mg|ml|cl|l|min(?:ute)?s?|h|heures?|hours?|c|celsius))\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikePureRouteNavigationText(string? evidence)
    {
        var normalized = NormalizeLexicalLookup(evidence);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        var hasNavigationCue = Regex.IsMatch(
            normalized,
            @"\b(?:sommaire|table des matieres|table of contents|contents|index|sections principales|content overview|premiers extraits)\b",
            RegexOptions.CultureInvariant);
        return hasNavigationCue && !LooksLikeRouteTargetStructuredEvidence(normalized);
    }

    private static string ExtractRouteDiscoveryTitleCue(RagHitSummary hit)
        => ExtractRouteDiscoveryTitleCues(hit).FirstOrDefault() ?? string.Empty;

    private static IReadOnlyList<string> ExtractRouteDiscoveryTitleCues(RagHitSummary hit)
    {
        var cues = new List<string>();
        void AddCue(string? raw)
        {
            var title = CleanNavigationRouteAnchorTitle(raw);
            if (!IsUsableSourceBackedOptionTitle(title))
                return;

            if (!cues.Contains(title, StringComparer.OrdinalIgnoreCase))
                cues.Add(title);
        }

        if (hit.MatchedContentCards is { Count: > 0 } cards)
        {
            foreach (var card in cards.Where(static card =>
                         ContainsRouteRetrievalCue(card.Kind)
                         || card.Signals?.Any(ContainsRouteRetrievalCue) == true))
            {
                AddCue(card.Title);
            }
        }

        foreach (var text in new[] { hit.ContextualSnippet, hit.FullText, hit.Excerpt })
        {
            foreach (Match match in Regex.Matches(
                         text ?? string.Empty,
                         @"(?im)\bMatched\s+(?:navigation_route|title_anchor_route|direct_title_token_route|local_title_token_route|explicit_document_title_route|fuzzy_title_lead)\s*:\s*(?<title>[^\r\n|]+)",
                         RegexOptions.CultureInvariant))
            {
                AddCue(match.Groups["title"].Value);
            }

            foreach (var title in ExtractNavigationTitlePageCandidates(text))
                AddCue(title);
        }

        AddCue(hit.SectionTitle);
        AddCue(hit.HeadingPath);
        return cues.Take(12).ToArray();
    }

    private static IEnumerable<string> ExtractNavigationTitlePageCandidates(string? text)
    {
        var normalized = CollapseWhitespace(text ?? string.Empty);
        if (normalized.Length < 8)
            yield break;

        var hasNavigationCue = Regex.IsMatch(
            NormalizeLexicalLookup(normalized),
            @"\b(?:sommaire|table des matieres|table of contents|contents|index|sections principales|overview|contenu|indice|inhaltsverzeichnis|sommario)\b",
            RegexOptions.CultureInvariant);
        if (!hasNavigationCue)
            yield break;

        var emitted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var title in ExtractNavigationTitlePageCandidatesFromLines(text)
                     .Concat(ExtractNavigationTitlePageCandidatesFromCollapsed(normalized)))
        {
            var cleaned = CleanNavigationIndexCandidateTitle(title);
            if (string.IsNullOrWhiteSpace(cleaned)
                || LooksLikeNavigationIndexHeadingTitle(cleaned)
                || !emitted.Add(cleaned))
                continue;

            yield return cleaned;
        }
    }

    private static IEnumerable<string> ExtractNavigationTitlePageCandidatesFromLines(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
            yield break;

        foreach (var rawLine in Regex.Split(text, @"[\r\n]+", RegexOptions.CultureInvariant))
        {
            var line = CollapseWhitespace(rawLine);
            if (line.Length < 6)
                continue;

            foreach (Match match in Regex.Matches(
                         line,
                         @"(?i)^\s*(?:[\u2022\-*]\s*)?(?<title>[\p{L}][\p{L}\p{N}'\u2019&/(),.\- ]{3,90}?)\s*(?:\.{2,}|-{2,}|\s{2,})\s*(?:p(?:age)?\.?\s*)?(?<page>\d{1,4})(?:\s*[-\u2013]\s*\d{1,4})?\s*$",
                         RegexOptions.CultureInvariant))
            {
                yield return match.Groups["title"].Value;
            }

            foreach (Match match in Regex.Matches(
                         line,
                         @"(?i)^\s*(?:p(?:age)?\.?\s*)?(?<page>\d{1,4})(?:\s*[-\u2013]\s*\d{1,4})?\s*[:.\-\u2013]?\s*(?<title>[\p{L}][\p{L}\p{N}'\u2019&/(),.\- ]{3,90}?)\s*$",
                         RegexOptions.CultureInvariant))
            {
                yield return match.Groups["title"].Value;
            }
        }
    }

    private static IEnumerable<string> ExtractNavigationTitlePageCandidatesFromCollapsed(string normalized)
    {
        if (string.IsNullOrWhiteSpace(normalized))
            yield break;

        var pageMatches = Regex.Matches(
            normalized,
            @"(?i)(?<![\p{L}\p{N}])(?:p(?:age)?\.?\s*)?\d{1,4}(?:\s*[-\u2013]\s*\d{1,4})?(?![\p{L}\p{N}])",
            RegexOptions.CultureInvariant);
        if (pageMatches.Count == 0)
            yield break;

        var previousEnd = 0;
        foreach (Match match in pageMatches)
        {
            var length = match.Index - previousEnd;
            if (length > 0)
                yield return normalized.Substring(previousEnd, length);

            previousEnd = match.Index + match.Length;
        }
    }

    private static string CleanNavigationIndexCandidateTitle(string? value)
    {
        var title = CollapseWhitespace(value ?? string.Empty)
            .Trim(' ', '.', ',', ';', ':', '"', '\'', '\u2022', '\u00b7', '-', '\u2013');
        if (string.IsNullOrWhiteSpace(title))
            return string.Empty;

        title = Regex.Replace(
            title,
            @"(?i)^(?:sommaire|table\s+des\s+matieres|table\s+of\s+contents|contents|index|sections\s+principales|overview|contenu|indice|inhaltsverzeichnis|sommario)\b\s*[:.\-\u2013]*\s*",
            string.Empty,
            RegexOptions.CultureInvariant);
        title = Regex.Replace(
            title,
            @"(?i)^(?:chapitre|chapter|section|partie|part|annexe|appendix)\s+\d{1,4}\s*[:.\-\u2013]*\s*",
            string.Empty,
            RegexOptions.CultureInvariant);
        title = Regex.Replace(
            title,
            @"(?i)^(?:\d+|[ivxlcdm]{1,6})[.)]\s+",
            string.Empty,
            RegexOptions.CultureInvariant);

        return CleanNavigationRouteAnchorTitle(title);
    }

    private static string CleanNavigationRouteAnchorTitle(string? value)
    {
        var title = CollapseWhitespace(value ?? string.Empty)
            .Trim(' ', '.', ',', ';', ':', '"', '\'', '\u2022', '\u00b7', '-', '\u2013');
        if (string.IsNullOrWhiteSpace(title))
            return string.Empty;

        title = Regex.Replace(title, @"^(?:\d+|[ivxlcdm]{1,6})[.)]\s+", string.Empty, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"\s+", " ", RegexOptions.CultureInvariant).Trim(' ', '-', ':', '.', ',', ';');
        return title.Length <= 90 ? title : title[..90].TrimEnd();
    }

    private static bool LooksLikeNavigationIndexHeadingTitle(string? value)
    {
        var normalized = NormalizeLexicalLookup(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        return Regex.IsMatch(
            normalized,
            @"^(?:sommaire|table des matieres|table of contents|contents|index|page|pages|chapter|chapitre|section|partie|part|table|liste|list|overview|contenu|indice|inhaltsverzeichnis|sommario)$",
            RegexOptions.CultureInvariant);
    }

    private static string BuildMissingExplicitDocumentAnswer(string language, string requestedDocument, IReadOnlyList<RagHitSummary> hits)
    {
        language = NormalizeLanguageCode(language);
        requestedDocument = CleanupRequestedItemTitle(requestedDocument) ?? CollapseWhitespace(requestedDocument);
        var closeLeads = SelectMissingExactItemCloseLeads(requestedDocument, hits)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .Take(3)
            .ToList();

        var header = (closeLeads.Count > 0, language) switch
        {
            (true, "en") => $"I did not find the requested document \"{requestedDocument}\" in the indexed corpus. I will not summarize it or use it as a source. Closest documented alternatives:",
            (true, "es") => $"No he encontrado el documento solicitado \"{requestedDocument}\" en el corpus indexado. No voy a resumirlo ni usarlo como fuente. Pistas cercanas con fuente:",
            (true, "pt") => $"Nao encontrei o documento solicitado \"{requestedDocument}\" no corpus indexado. Nao vou resume-lo nem usa-lo como fonte. Pistas proximas com fonte:",
            (true, "de") => $"Ich habe das angefragte Dokument \"{requestedDocument}\" im indexierten Korpus nicht gefunden. Ich fasse es nicht zusammen und verwende es nicht als Quelle. Naheliegende belegte Hinweise:",
            (true, "it") => $"Non ho trovato il documento richiesto \"{requestedDocument}\" nel corpus indicizzato. Non lo riassumo ne lo uso come fonte. Indicazioni vicine con fonte:",
            (true, _) => $"Je n'ai pas trouve le document demande \"{requestedDocument}\" dans le corpus indexe. Je ne le resume pas et je ne l'utilise pas comme source principale. Alternatives documentees les plus proches :",
            (false, "en") => $"I did not find the requested document \"{requestedDocument}\" in the indexed corpus. I will not summarize it or use it as a source.",
            (false, "es") => $"No he encontrado el documento solicitado \"{requestedDocument}\" en el corpus indexado. No voy a resumirlo ni usarlo como fuente.",
            (false, "pt") => $"Nao encontrei o documento solicitado \"{requestedDocument}\" no corpus indexado. Nao vou resume-lo nem usa-lo como fonte.",
            (false, "de") => $"Ich habe das angefragte Dokument \"{requestedDocument}\" im indexierten Korpus nicht gefunden. Ich fasse es nicht zusammen und verwende es nicht als Quelle.",
            (false, "it") => $"Non ho trovato il documento richiesto \"{requestedDocument}\" nel corpus indicizzato. Non lo riassumo ne lo uso come fonte.",
            _ => $"Je n'ai pas trouve le document demande \"{requestedDocument}\" dans le corpus indexe. Je ne le resume pas et je ne l'utilise pas comme source principale."
        };

        if (closeLeads.Count == 0)
            return header;

        var sb = new StringBuilder();
        sb.AppendLine(header);
        foreach (var hit in closeLeads)
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var excerpt = CollapseWhitespace(hit.Excerpt);
            if (excerpt.Length > 240)
                excerpt = excerpt[..240].TrimEnd() + "...";

            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            sb.AppendLine(excerpt);
        }

        return sb.ToString().TrimEnd();
    }

    private static string BuildMissingExactItemAnswer(string language, string requestedTitle, IReadOnlyList<RagHitSummary> hits)
    {
        language = NormalizeLanguageCode(language);
        var closeLeads = SelectMissingExactItemCloseLeads(requestedTitle, hits);
        if (closeLeads.Count == 0)
        {
            var fallbackCandidates = hits
                .Where(hit => !LooksLikeNavigationOnlyHit(hit))
                .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit))
                .Where(hit => !LooksLikeExactItemReferenceOnlyHit(requestedTitle, hit))
                .Select(hit => new
                {
                    Hit = hit,
                    Relevance = ComputeTypoTolerantRagHitLexicalRelevance(requestedTitle, GetRagHitLookupText(hit)),
                    Structure = ComputeExactItemCardCompletenessCueScore(hit)
                })
                .Where(item => !LooksLikePageReferenceOnlyHit(item.Hit) || item.Structure >= 4 || item.Hit.PageEnd > item.Hit.PageStart)
                .OrderByDescending(item => item.Structure >= 4)
                .ThenByDescending(item => item.Relevance)
                .Take(3)
                .Select(item => item.Hit)
                .ToList();
            closeLeads = fallbackCandidates;
        }
        else if (closeLeads.Any(LooksLikePageReferenceOnlyHit))
        {
            closeLeads = closeLeads
                .Concat(hits
                    .Where(hit => !LooksLikeNavigationOnlyHit(hit))
                    .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit))
                    .Where(hit => !LooksLikePageReferenceOnlyHit(hit))
                    .Where(hit => !closeLeads.Any(existing => SameRagHitRange(existing, hit))))
                .OrderBy(hit => LooksLikePageReferenceOnlyHit(hit) ? 1 : 0)
                .ThenByDescending(hit => ComputeTypoTolerantRagHitLexicalRelevance(requestedTitle, GetRagHitLookupText(hit)))
                .Take(4)
                .ToList();
        }

        var typoResolutionLeads = closeLeads.Count > 0
            ? closeLeads
            : hits
                .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit))
                .OrderByDescending(hit => ComputeTypoTolerantRagHitLexicalRelevance(requestedTitle, GetRagHitLookupText(hit)))
                .Take(4)
                .ToList();
        var correctedTitle = TryResolveTypoTolerantCloseTitle(requestedTitle, typoResolutionLeads);
        if (!string.IsNullOrWhiteSpace(correctedTitle))
        {
            var usableTypoResolutionLeads = typoResolutionLeads
                .Where(hit => !LooksLikeExactItemReferenceOnlyHit(correctedTitle!, hit))
                .Where(hit => !LooksLikeNavigationOnlyHit(hit))
                .Where(hit => !LooksLikePageReferenceOnlyHit(hit))
                .Where(hit => ExactItemEvidenceStartsWithRequestedTitle(correctedTitle!, hit)
                    || RagHitHasUsableRequestedTitleAnchor(correctedTitle!, hit))
                .ToList();
            if (usableTypoResolutionLeads.Count > 0)
            {
                return BuildSourceBackedExactItemAnswer(
                    language,
                    correctedTitle!,
                    usableTypoResolutionLeads,
                    $"{correctedTitle} details source");
            }

            closeLeads = closeLeads
                .Where(hit => !LooksLikeExactItemReferenceOnlyHit(correctedTitle!, hit))
                .ToList();
        }

        var header = (closeLeads.Count > 0, language) switch
        {
            (true, "en") => $"I did not find the exact requested item \"{requestedTitle}\" in the available excerpts. I will not invent missing facts, quantities, steps, or details. Closest documented alternatives:",
            (true, "es") => $"No he encontrado el elemento exacto solicitado \"{requestedTitle}\" en los extractos disponibles. No voy a inventar hechos, cantidades, pasos ni detalles. Pistas cercanas con fuente:",
            (true, "pt") => $"Nao encontrei o item exato solicitado \"{requestedTitle}\" nos excertos disponiveis. Nao vou inventar factos, quantidades, passos nem detalhes. Pistas proximas com fonte:",
            (true, "de") => $"Ich habe den exakt angefragten Eintrag \"{requestedTitle}\" in den verfuegbaren Auszuegen nicht gefunden. Ich erfinde keine Fakten, Mengen, Schritte oder Details. Naheliegende belegte Hinweise:",
            (true, "it") => $"Non ho trovato l'elemento esatto richiesto \"{requestedTitle}\" negli estratti disponibili. Non invento fatti, quantita, passaggi o dettagli. Indicazioni vicine con fonte:",
            (true, _) => $"Je n'ai pas trouve l'element exact demande \"{requestedTitle}\" dans les extraits disponibles. Je n'invente donc pas les faits, quantites, etapes ou details manquants. Alternatives documentees les plus proches :",
            (false, "en") => $"I did not find the exact requested item \"{requestedTitle}\" in the available excerpts. I will not invent missing facts, quantities, steps, or details.",
            (false, "es") => $"No he encontrado el elemento exacto solicitado \"{requestedTitle}\" en los extractos disponibles. No voy a inventar hechos, cantidades, pasos ni detalles.",
            (false, "pt") => $"Nao encontrei o item exato solicitado \"{requestedTitle}\" nos excertos disponiveis. Nao vou inventar factos, quantidades, passos nem detalhes.",
            (false, "de") => $"Ich habe den exakt angefragten Eintrag \"{requestedTitle}\" in den verfuegbaren Auszuegen nicht gefunden. Ich erfinde keine Fakten, Mengen, Schritte oder Details.",
            (false, "it") => $"Non ho trovato l'elemento esatto richiesto \"{requestedTitle}\" negli estratti disponibili. Non invento fatti, quantita, passaggi o dettagli.",
            _ => $"Je n'ai pas trouve l'element exact demande \"{requestedTitle}\" dans les extraits disponibles. Je n'invente donc pas les faits, quantites, etapes ou details manquants."
        };

        var sb = new StringBuilder();
        sb.AppendLine(header);
        foreach (var hit in closeLeads)
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var excerpt = CollapseWhitespace(hit.Excerpt);
            if (excerpt.Length > 240)
                excerpt = excerpt[..240].TrimEnd() + "...";

            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            sb.AppendLine(excerpt);
        }

        return sb.ToString().TrimEnd();
    }

    private static string? TryResolveTypoTolerantCloseTitle(string requestedTitle, IReadOnlyList<RagHitSummary> closeLeads)
    {
        if (closeLeads.Count == 0)
            return null;

        var candidates = closeLeads
            .SelectMany(hit => ExtractSourceBackedTitleCandidates(hit).Concat(new[] { ExtractPlanItemTitleV2(GetPlanExtractionText(hit)) }))
            .Select(CleanSourceBackedOptionTitle)
            .Where(title => !string.IsNullOrWhiteSpace(title))
            .Where(IsUsableSourceBackedOptionTitle)
            .Select(title => new
            {
                Title = title,
                Score = ComputeTypoTolerantRagHitLexicalRelevance(requestedTitle, title)
            })
            .OrderByDescending(static item => item.Score)
            .ThenBy(static item => item.Title.Length)
            .ToArray();

        var best = candidates.FirstOrDefault(static item => item.Score >= 8);
        if (best is null)
        {
            foreach (var variant in BuildTypoTolerantQueryVariants(requestedTitle))
            {
                var normalizedVariant = NormalizeLexicalLookup(variant);
                if (string.IsNullOrWhiteSpace(normalizedVariant))
                    continue;

                var variantTerms = ExtractRequestedTitleSignalTerms(normalizedVariant);
                if (variantTerms.Length == 0)
                    continue;

                var hasVariantEvidence = closeLeads.Any(hit =>
                {
                    var lookup = NormalizeLexicalLookup(GetRagHitLookupText(hit));
                    return variantTerms.All(term => lookup.Contains(term, StringComparison.Ordinal));
                });
                if (hasVariantEvidence)
                    return CultureInfo.InvariantCulture.TextInfo.ToTitleCase(normalizedVariant);
            }

            return null;
        }

        return string.Equals(NormalizeLexicalLookup(best.Title), NormalizeLexicalLookup(requestedTitle), StringComparison.Ordinal)
            ? null
            : best.Title;
    }

    private static bool LooksLikeSourceBackedPlanningRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;
        if (LooksLikeCorpusClaimVerificationRequest(query))
            return false;
        if (LooksLikeSourceBackedCountdownPlanningRequest(query))
            return false;

        var asksForPlan = LooksLikeWeeklyPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query)
            || Regex.IsMatch(
            s,
                @"\b(?:plan|planning|calendrier|programme|organisation|schedule|calendar|wochenplan|programm|piano|programma|calendario|programa|organizacion|plano|organizacao|organizacao|programma|organizzazione|pianificazione)\b",
                RegexOptions.CultureInvariant);

        return asksForPlan && LooksLikeSourceBackedActionRequest(query);
    }

    private static bool LooksLikeAnyDocumentaryPlanningRequest(string? query)
        => LooksLikeSourceBackedPlanningRequest(query) || LooksLikeDocumentaryPlanningRequest(query);

    private static bool UsesSourceBackedPlanningCoverage(string? query)
        => RequiresStructuredSourceBackedPlanningCoverage(query)
           && !LooksLikeSourceBackedPairingRecommendationRequest(query)
           && !LooksLikeSoftChoiceRecommendationRequest(query);

    private static bool LooksLikeSourceBackedVerificationChecklistRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;

        var asksForVerification = Regex.IsMatch(
            s,
            @"\b(?:verifie|verifier|verification|check|verify|controle|controler|valide|valider|validation|audit|points?\s+a\s+valider|points?\s+de\s+controle|checklist)\b",
            RegexOptions.CultureInvariant);
        var asksForExplicitChecklistOrReviewShape = Regex.IsMatch(
            s,
            @"\b(?:verifie|verifier|verification|check|verify|valide|valider|validation|audit|checklist|points?\s+a\s+valider|points?\s+de\s+controle|etapes?|steps?|dois|devrais|faut|should|must)\b",
            RegexOptions.CultureInvariant);
        if (!asksForExplicitChecklistOrReviewShape
            && Regex.IsMatch(
                s,
                @"\b(?:explique|expliquer|expliquez|explain|explains|explica|explicar|erklaere|erklaren|spiega|spiegare)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        var asksForActionableShape = Regex.IsMatch(
            s,
            @"\b(?:que|quoi|what|which|comment|how|dois|devrais|faut|should|must|points?|etapes?|steps?|documents?|sources?)\b",
            RegexOptions.CultureInvariant);

        return asksForVerification && asksForActionableShape;
    }

    private static bool LooksLikeCorpusClaimVerificationRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;

        var asksVerification = Regex.IsMatch(
            s,
            @"\b(?:verifie|verifier|verification|check|verify|prouve|prouver|preuve|prove|proof|demontre|demontre|demonstrated|demonstrate)\b",
            RegexOptions.CultureInvariant);
        var hasCorpusScope = Regex.IsMatch(
            s,
            @"\b(?:corpus|documents?|sources?|pdfs?|base\s+de\s+connaissances?|knowledge\s+base)\b",
            RegexOptions.CultureInvariant);
        var hasStrongClaim = Regex.IsMatch(
            s,
            @"\b(?:toujours|jamais|always|never|obligation\s+generale|general\s+obligation|obligatoire|mandatory|required|requires?|impose|imposes?|condition\s+limitee|limited\s+condition|recommandation|recommendation|pas\s+demontre|not\s+demonstrated)\b",
            RegexOptions.CultureInvariant);

        return asksVerification && hasStrongClaim && (hasCorpusScope || s.Contains('`', StringComparison.Ordinal));
    }

    private static bool LooksLikeWeeklyPlanningRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;

        return Regex.IsMatch(
            s,
            @"\b(?:semaine|hebdo|hebdomadaire|7\s+jours?|sept\s+jours?|week|weekly|semana|semanal|woche|wochen|wochenplan|settimana|settimanale)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeDocumentaryPlanningRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;

        var hasPlanningCue = Regex.IsMatch(
            s,
            @"\b(?:semaine|hebdo|hebdomadaire|jours|journee|plan|planning|calendrier|programme|organisation|parallele|avance|preparation|preparer|week|weekly|schedule|calendar|parallel|advance|prepare|preparation|semana|semanal|dias|calendario|programa|organizacion|paralelo|preparar|preparacion|plano|organizacao|paralelo|preparar|preparacao|woche|wochenplan|kalender|programm|organisation|parallel|vorbereiten|piano|programma|organizzazione|pianificazione|parallelo|preparare|preparazione)\b",
            RegexOptions.CultureInvariant);
        if (!hasPlanningCue)
            return false;

        if (LooksLikeSourceBackedActionRequest(query))
            return true;

        return Regex.IsMatch(
            s,
            @"\b(?:documents?|docs?|sources?|fichiers?|pdfs?|extraits?|corpus|base\s+de\s+connaissances?|knowledge\s+base|documentos?|fuentes?|fontes?|dokumente?|quellen?|documenti|fonti)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeSourceBackedOptionRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s) || LooksLikeSourceBackedPlanningRequest(query))
            return false;

        if (LooksLikeCategoryOverviewOrDocumentOrientationRequest(query))
            return false;

        if (LooksLikeRankingDocumentaryRequest(query) || LooksLikeComparativeDocumentaryRequest(query))
            return false;

        if (!LooksLikeDocumentaryContentRequest(query) && !ExtractQuerySignalTerms(s).Any())
            return false;

        var hasNeedOrConstraintCue = Regex.IsMatch(
            s,
            @"\b(?:il\s+me\s+faut|j\s+ai\s+besoin|besoin|need|needed|necesito|preciso|brauche|serve|mi\s+serve|moins\s+de|sous|within|under|total)\b",
            RegexOptions.CultureInvariant);
        var hasCompositeCue = s.Contains('+', StringComparison.Ordinal)
            || Regex.IsMatch(
                s,
                @"\b(?:et|avec|plus|ensemble|combine|combiner|and|with|plus|together|total|complete|complet|completa|completo)\b",
                RegexOptions.CultureInvariant);
        if (hasNeedOrConstraintCue && hasCompositeCue)
            return true;

        if (Regex.IsMatch(s, @"\b(?:plan|planning|liste|list|options?|suggestions?|selection|sélection)\b", RegexOptions.CultureInvariant)
            && Regex.IsMatch(s, @"\b(?:complet|complete|sans|without|pas\s+de|uniquement|only|avec|with|pour|for|autour|around|total)\b", RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                s,
                @"\b(?:liste|lister|list|listing|selection|s[e\u00e9]lection|seleccion|selecao|options?|suggestions?|idees?|ideas?|choix|choices?)\b",
                RegexOptions.CultureInvariant)
            && (LooksLikeSourceBackedActionRequest(query)
                || LooksLikeDocumentaryContentRequest(query)
                || Regex.IsMatch(
                    s,
                    @"\b(?:disponibles?|available|sources?|documents?|docs?|corpus|dossier|category|categorie|cat[e\u00e9]gorie)\b",
                    RegexOptions.CultureInvariant)
                || ExtractQuerySignalTerms(s).Take(2).Any()))
        {
            return true;
        }

        if (Regex.IsMatch(s, @"\b(?:complet|complete|completa|completo|total)\b", RegexOptions.CultureInvariant)
            && Regex.IsMatch(s, @"\b(?:sans|without|pas\s+de|excluding|exclude|sauf|except|uniquement|only|avec|with)\b", RegexOptions.CultureInvariant)
            && LooksLikeSourceBackedActionRequest(query))
        {
            return true;
        }

        if (Regex.IsMatch(s, @"\b(?:fais|faire|compose|composer|cree|creer|prepare|preparer|make|compose|create|prepare)\b.{0,80}\b(?:plan|planning|liste|list|options?|suggestions?)\b", RegexOptions.CultureInvariant))
            return true;

        if (Regex.IsMatch(s, @"\b(?:fais|faire|compose|composer|cree|creer|prepare|preparer|make|compose|create|prepare)\b.{0,100}\b(?:composition|selection|sélection)\b", RegexOptions.CultureInvariant))
            return true;

        if (Regex.IsMatch(s, @"\b(?:compose|composer|cree|creer|prepare|preparer|make|create|prepare)\b.{0,100}\b(?:options?|idees?|ideas?|items?|elements?|liste|list|plan|planning)\b", RegexOptions.CultureInvariant))
            return true;

        return Regex.IsMatch(
            s,
            @"\b(?:propose|proposes|idee|idees|quoi|choisis|choisir|option|options|composition|suggest|suggestion|suggestions|which|what|cual|qual|welche|quale)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeCategoryOverviewOrDocumentOrientationRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;
        if (LooksLikeSourceBackedVerificationChecklistRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query)
            || LooksLikeComparativeDocumentaryRequest(query))
        {
            return false;
        }

        var hasScope = Regex.IsMatch(
            s,
            @"\b(?:categorie|category|categoria|kategorie|dossier|folder|corpus|base\s+de\s+connaissances?|knowledge\s+base)\b",
            RegexOptions.CultureInvariant);
        var hasDocumentSet = Regex.IsMatch(
            s,
            @"\b(?:pdfs?|documents?|docs?|sources?|fichiers?|files?)\b",
            RegexOptions.CultureInvariant);
        var hasOrientationCue = Regex.IsMatch(
            s,
            @"\b(?:overview|vue\s+d\s+ensemble|cartographie|orientation|utile|utiles|useful|important|importants|business\s+questions?|real\s+business|lire\s+en\s+premier|read\s+first|used\s+first|role|roles?|familles?|families|classer|group(?:er|ing)?|regrouper)\b",
            RegexOptions.CultureInvariant);

        return hasOrientationCue && (hasScope || hasDocumentSet);
    }

    private static bool LooksLikeSourceBackedPairingRecommendationRequest(string? query)
    {
        var s = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(s))
            return false;

        var hasStrongPairingCue = Regex.IsMatch(
            s,
            @"\b(?:irait\s+bien|va\s+bien|vont\s+bien|aller\s+avec|aille\s+avec|aillent\s+avec|accompagne|accompagner|associe|associer|compatible|compatibles|goes?\s+with|pair(?:ing)?|pairs?\s+with|compatible|acompanha|acompanhar|combina|combinar|passt\s+zu|kombinieren|abbinare|abbina|si\s+abbina)\b",
            RegexOptions.CultureInvariant);
        var hasWeakPairingCue = Regex.IsMatch(
            s,
            @"\b(?:avec|con)\b",
            RegexOptions.CultureInvariant);
        if (!hasStrongPairingCue && !hasWeakPairingCue)
            return false;

        if (!hasStrongPairingCue
            && Regex.IsMatch(
                s,
                @"\b(?:avec|con)\s+(?:les|des|de\s+las|las|le|i|gli|the)?\s*(?:sources?|documents?|fuentes?|fonti|quellen|documentos?)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        if (!hasStrongPairingCue
            && Regex.IsMatch(
                s,
                @"\b(?:quoi\s+faire|que\s+faire|what\s+to\s+do|organisation|organiser|organization|organize|organise|planning|plan|procedure|processus|process|workflow|etapes?|steps?|comment|how|dois|devrais|should)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        return Regex.IsMatch(
            s,
            @"\b(?:quel|quelle|quels|quelles|quoi|which|what|cual|cu[aá]l|qual|welche|welcher|welches|quale|propose|proposes|suggest|recommend|recommande|recommander|conseille|conseiller)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool ShouldUseSourceBackedOptionAnswer(string? requestedItemTitle, string query)
        => LooksLikeSourceBackedOptionRequest(query)
            && (string.IsNullOrWhiteSpace(requestedItemTitle)
                || LooksLikeBroadSourceBackedCompositionRequest(query));

    private static bool ShouldAvoidDeterministicSourceBackedOptionFallback(string? query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        return IsBroadenedSourceSearchConfirmationEnvelope(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeBroadSynthesisRequestShape(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query);
    }

    private static bool LooksLikeUnresolvedSourceBackedDeicticFollowup(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var hasDeicticReference = Regex.IsMatch(
            normalized,
            @"\b(?:ca|cela|ceci|this|that|it|eso|esto|isso|isto|das|questo|quello)\b",
            RegexOptions.CultureInvariant);
        if (!hasDeicticReference)
            return false;

        if (LooksLikeCompleteSourceBackedRequestWithDeicticReference(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:apres|après|precedent|pr[eé]c[eé]dent|document|source|element|item|mets|mettre|adapte|adapter|pour|after|previous|put|scale|adjust|adapt)\b|\b(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+\p{L}",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeCompleteSourceBackedRequestWithDeicticReference(string normalized)
    {
        var signalTermCount = ExtractQuerySignalTerms(normalized).Take(3).Count();
        if (signalTermCount < 2)
            return false;

        var hasPlanningCue = Regex.IsMatch(
            normalized,
            @"\b(?:plan|planning|calendrier|programme|organisation|schedule|calendar|semaine|hebdo|hebdomadaire|week|weekly|semana|semanal|woche|wochenplan|settimana|settimanale|piano|programma)\b",
            RegexOptions.CultureInvariant);
        var hasSelectionCue = Regex.IsMatch(
            normalized,
            @"\b(?:propose|proposes|proposer|idee|idees|quoi|quel|quelle|quels|quelles|option|options|suggestion|suggestions|choisir|choix|liste|lister|suggest|which|what|list|selection|seleccion|selecao|auswahl|scelta)\b",
            RegexOptions.CultureInvariant);
        var hasActionCue = Regex.IsMatch(
            normalized,
            @"\b(?:fais|faire|prepare|preparer|organise|organiser|structure|structurer|construis|construire|cree|creer|redige|rediger|compose|composer|elabore|elaborer|build|create|make|prepare|organize|organise|draft|compose|structure|prepara|preparar|organiza|organizar|crea|crear|redacta|redactar|prepara|preparar|organiza|organizar|cria|criar|redige|redigir|erstelle|erstellen|bereite|vorbereiten|organisiere|organisieren|verfasse|prepara|preparare|organizza|organizzare|crea|creare|redigi|redigere)\b",
            RegexOptions.CultureInvariant);
        var hasOverviewCue = Regex.IsMatch(
            normalized,
            @"\b(?:overview|vue\s+d\s+ensemble|cartographie|orientation|utile|utiles|important|importants|classer|regrouper|role|roles|famille|familles|documents?|sources?|corpus|base\s+de\s+connaissances?|knowledge\s+base)\b",
            RegexOptions.CultureInvariant);
        var hasSearchableObjectCue = Regex.IsMatch(
            normalized,
            @"\b(?:documents?|sources?|corpus|base\s+de\s+connaissances?|knowledge\s+base|plan|planning|calendrier|programme|procedure|processus|comparaison|compare|comparar|vergleich|confronto|recommandation|recommendation|synthese|summary|resumen|resumo|zusammenfassung|riassunto)\b",
            RegexOptions.CultureInvariant);

        return (hasPlanningCue && (hasSelectionCue || hasActionCue))
            || (hasOverviewCue && (hasSelectionCue || hasActionCue))
            || (hasActionCue && hasSearchableObjectCue && signalTermCount >= 3);
    }

    private static bool LooksLikeVagueVerificationScopeQuestion(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var asksSafeVerification = Regex.IsMatch(
            normalized,
            @"\b(?:reponse\s+sure|safe\s+answer|pas\s+d\s+une\s+supposition|not\s+a\s+guess|supposition|guess)\b",
            RegexOptions.CultureInvariant)
            && Regex.IsMatch(
                normalized,
                @"\b(?:verifie|verifier|verifies|verify|check|controle|controler|ou\s+exactement|where\s+exactly)\b",
                RegexOptions.CultureInvariant);
        var asksWhereExactly = Regex.IsMatch(
            normalized,
            @"\b(?:ou\s+exactement|where\s+exactly)\b",
            RegexOptions.CultureInvariant);
        if (!asksSafeVerification && !asksWhereExactly)
            return false;

        if (!string.IsNullOrWhiteSpace(TryExtractPdfFileNameRequestedTitle(query)))
            return false;

        return !Regex.IsMatch(
            normalized,
            @"\b(?:iso|iec|en|ul|nfpa|ansi|astm|din)\s*\d{2,}|\b(?:pdf|document|doc|fichier|file)\s+[\p{L}0-9_-]{3,}",
            RegexOptions.CultureInvariant);
    }

    private static string BuildVagueVerificationScopeClarification(string language)
        => SourceBackedLabel(
            NormalizeLanguageCode(language),
            "J'ai besoin du document, de la norme, de la categorie ou du sujet exact a verifier. Sans ce perimetre, je risquerais de choisir des sources au hasard; indique ce que je dois controler et je citerai les pages pertinentes.",
            "I need the exact document, standard, category, or topic to verify. Without that scope, I could pick sources at random; tell me what to check and I will cite the relevant pages.",
            "Necesito el documento, la norma, la categoria o el tema exacto que debo verificar. Sin ese alcance podria elegir fuentes al azar; dime que debo comprobar y citare las paginas pertinentes.",
            "Preciso do documento, norma, categoria ou tema exato a verificar. Sem esse ambito eu poderia escolher fontes ao acaso; diz-me o que devo verificar e citarei as paginas relevantes.",
            "Ich brauche das genaue Dokument, die Norm, die Kategorie oder das Thema, das ich pruefen soll. Ohne diesen Rahmen koennte ich Quellen zufaellig waehlen; sag mir, was ich pruefen soll, dann zitiere ich die passenden Seiten.",
            "Mi serve il documento, la norma, la categoria o il tema esatto da verificare. Senza questo perimetro rischierei di scegliere fonti a caso; dimmi cosa devo controllare e citero le pagine pertinenti.");

    private static string BuildUnresolvedSourceBackedDeicticFollowupAnswer(string language, string query)
    {
        language = NormalizeLanguageCode(language);
        var target = TryExtractTargetScaleCount(query, out var count)
            ? language switch
            {
                "en" => $" for {count}",
                "es" => $" para {count}",
                "pt" => $" para {count}",
                "de" => $" fuer {count}",
                "it" => $" per {count}",
                _ => $" pour {count}"
            }
            : string.Empty;
        return SourceBackedLabel(
            language,
            $"Je n'ai pas d'element precedent exploitable dans cette conversation. Donne-moi l'element, le document ou la source concernee, puis je pourrai l'adapter ou la citer{target} sans inventer.",
            $"I do not have an exploitable previous item in this conversation. Give me the item, document, or source involved, then I can adapt or cite it{target} without inventing details.",
            $"No tengo un elemento anterior explotable en esta conversacion. Dame el elemento, el documento o la fuente correspondiente y podre adaptarlo o citarlo{target} sin inventar detalles.",
            $"Nao tenho um elemento anterior utilizavel nesta conversa. Da-me o item, o documento ou a fonte em causa e poderei adapta-lo ou cita-lo{target} sem inventar detalhes.",
            $"Ich habe in dieser Unterhaltung kein nutzbares vorheriges Element. Gib mir den Eintrag, das Dokument oder die betroffene Quelle, dann kann ich ihn{target} anpassen oder zitieren, ohne Details zu erfinden.",
            $"Non ho un elemento precedente utilizzabile in questa conversazione. Dammi l'elemento, il documento o la fonte interessata e potro adattarlo o citarlo{target} senza inventare dettagli.");
    }

    private static bool LooksLikeBroadDocumentaryInformationRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(normalized, @"^(?:hi|hello|bonjour|salut|merci|thanks?|ok|okay)\b", RegexOptions.CultureInvariant))
            return false;

        var hasInformationIntent = Regex.IsMatch(
            normalized,
            @"\b(?:info|infos|information|informations|renseignement|renseignements|parle\s+moi|dis\s+moi|dis\s+m\s+en|que\s+sais\s+tu|je\s+veux\s+comprendre|aide\s+moi\s+sur|au\s+sujet\s+de|a\s+propos\s+de|about|tell\s+me\s+about|details|overview|explain|explica|explicame|informacion|informaciones|detalles|sobre|informacao|informacoes|detalhes|erklaere|erklaren|informationen|uber|ueber|spiega|informazioni|dettagli|riguardo)\b",
            RegexOptions.CultureInvariant);
        if (!hasInformationIntent)
            return false;

        var signalTerms = ExtractQuerySignalTerms(normalized)
            .Where(static term => !IsGenericDocumentaryProbeTerm(term))
            .Where(static term => !IsGenericPlanningCoverageTerm(term))
            .Take(2)
            .ToArray();

        return signalTerms.Length > 0;
    }

    private static bool LooksLikeDocumentaryContentRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (!string.IsNullOrWhiteSpace(TryExtractRequestedItemTitle(query)))
            return true;

        var mentionsCommonContentObject = Regex.IsMatch(
            normalized,
            @"\b(?:fiche|card|cards|document|documents|source|sources|element|elements|item|items|objet|objets|sujet|sujets|topic|topics|procedure|procedures|process|processus|method|methods|methode|methodes|notice|notices|instruction|instructions)\b",
            RegexOptions.CultureInvariant);
        if (mentionsCommonContentObject)
        {
            var hasCommonDirectiveNounPhrase = Regex.IsMatch(
                normalized,
                @"^(?:(?:un|une|des|du|de\s+la|the|a|an|some)\s+)?(?:fiche|card|document|source|element|item|objet|sujet|topic|procedure|process|method|methode|notice|instruction)\b",
                RegexOptions.CultureInvariant);
            var hasCommonRequestOperator = Regex.IsMatch(
                normalized,
                @"\b(?:quel|quelle|quels|quelles|quoi|peux|pourrais|donne|donner|trouve|trouver|cherche|chercher|fais|faire|faut|besoin|veux|voudrais|souhaite|aimerais|liste|lister|propose|proposer|existe|existent|which|what|can|could|give|find|search|make|need|want|list|suggest|exists|exist)\b",
                RegexOptions.CultureInvariant);
            var mentionsCommonDocumentarySource = Regex.IsMatch(
                normalized,
                @"\b(?:pdf|document|documents|doc|docs|source|sources|base|connaissance|knowledge|corpus|file|files)\b",
                RegexOptions.CultureInvariant);

            if (hasCommonDirectiveNounPhrase || hasCommonRequestOperator || mentionsCommonDocumentarySource)
                return true;
        }

        var mentionsDocumentarySource = Regex.IsMatch(
            normalized,
            @"\b(?:pdf|document|documents|doc|docs|source|sources|extrait|extraits|page|pages|base|connaissance|knowledge|corpus|file|files|archivo|archivos|documento|documentos|fonte|fontes|quelle|quellen|dokument|dokumente|documento|documenti|fonte|fonti)\b",
            RegexOptions.CultureInvariant);
        var mentionsContentObject = Regex.IsMatch(
            normalized,
            @"\b(?:element|elements|item|items|objet|objets|sujet|sujets|topic|topics|section|sections|extrait|extraits|passage|passages|clause|clauses|table|tables|fiche|card|checklist|liste|list|plan|planning|procedure|proc[eé]dure|procedimento|procedura|process|processus|method|methode|instruction|instructions|etape|etapes|[eé]tape|[eé]tapes|step|steps|quantite|quantites|quantit[eé]|quantit[eé]s|amount|amounts|valeur|valeurs|value|values|temps|time|duration|duree|durees)\b",
            RegexOptions.CultureInvariant);
        var hasRequestOperator = Regex.IsMatch(
            normalized,
            @"\b(?:quel|quelle|quels|quelles|quoi|qu est|qu est ce|peux|pourrais|donne|donner|trouve|trouver|cherche|chercher|fais|faire|faut|besoin|veux|voudrais|souhaite|aimerais|compare|comparer|liste|lister|resume|resumer|reponds|repondre|r[eé]ponds|r[eé]pondre|adapte|adapter|transforme|transformer|traduis|traduire|rends|rendre|existe|existent|which|what|can|could|give|find|search|make|need|want|compare|list|summarize|respond|answer|adapt|adjust|transform|translate|render|exists|exist|cual|cu[aá]l|que|puedes|podrias|dame|busca|encuentra|necesito|responde|traduce|existe|quero|pode|podes|procura|encontra|preciso|responde|traduz|existe|welche|was|kannst|suche|finde|brauche|antworte|uebersetze|ubersetze|existiert|quale|cosa|puoi|cerca|trova|bisogno|rispondi|traduci|esiste)\b",
            RegexOptions.CultureInvariant);
        var hasDirectiveNounPhrase = Regex.IsMatch(
            normalized,
            @"^(?:(?:un|une|des|du|de\s+la|the|a|an|some)\s+)?(?:liste|list|checklist|fiche|card|plan|planning|procedure|process|section|table)\b",
            RegexOptions.CultureInvariant);

        if (mentionsDocumentarySource && (mentionsContentObject || ExtractQuerySignalTerms(normalized).Any()))
            return true;

        if (LooksLikeShortStandaloneContentLookup(normalized))
            return true;

        return mentionsContentObject && (hasRequestOperator || hasDirectiveNounPhrase);
    }

    private static bool LooksLikeShortStandaloneContentLookup(string normalized)
    {
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(normalized, @"\b(?:bonjour|salut|hello|merci|thanks?|pourquoi|why|comment\s+ca\s+va|how\s+are\s+you)\b", RegexOptions.CultureInvariant))
            return false;

        var words = Regex.Matches(normalized, @"[\p{L}\p{N}]{2,}")
            .Select(match => match.Value)
            .ToArray();
        if (words.Length is < 2 or > 12)
            return false;

        var hasContentShape = Regex.IsMatch(
                normalized,
                @"^(?:un|une|des|du|de\s+la|the|a|an|some)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:options?|suggestions?|idees?|ideas?|classique|classic|simple|rapide|quick|technique|technical)\b",
                RegexOptions.CultureInvariant);

        return hasContentShape && ExtractQuerySignalTerms(normalized).Any();
    }

    private static string[] BuildPlanningRetrievalQueries(string query)
    {
        var normalized = NormalizeRagQueryForRetrieval(query);
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = query;

        var raw = CollapseWhitespace(query);
        var queries = new List<string>();
        var requestedTitle = TryExtractRequestedItemTitle(query);
        var normalizedLookup = NormalizeLooseLookup(normalized);
        var signalTerms = ExtractPlanningRetrievalTerms(normalizedLookup)
            .Where(static term => term.Length >= 4)
            .Take(5)
            .ToArray();

        AddDistinctQuery(queries, normalized);
        if (!string.IsNullOrWhiteSpace(raw)
            && !string.Equals(raw, normalized, StringComparison.OrdinalIgnoreCase)
            && (!string.IsNullOrWhiteSpace(requestedTitle) || signalTerms.Length > 0))
        {
            AddDistinctQuery(queries, raw);
        }

        if (!string.IsNullOrWhiteSpace(requestedTitle))
        {
            AddDistinctQuery(queries, requestedTitle);
            AddDistinctQuery(queries, $"\"{requestedTitle}\"");
        }

        if (signalTerms.Length > 0)
        {
            var signalQuery = string.Join(' ', signalTerms);
            AddDistinctQuery(queries, signalQuery);
            foreach (var suffix in BuildPlanningExpansionSuffixes(query))
                AddDistinctQuery(queries, $"{signalQuery} {suffix}");
        }

        return queries
            .Where(static q => !string.IsNullOrWhiteSpace(q))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(LooksLikeSourceBackedVerificationChecklistRequest(query) ? 6 : 16)
            .ToArray();
    }

    private static string[] BuildPlanningExplorationRetrievalQueries(string query)
    {
        var normalized = NormalizeRagQueryForRetrieval(query);
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = CollapseWhitespace(query);

        var queries = new List<string>();
        var normalizedLookup = NormalizeLooseLookup(normalized);
        var signalTerms = ExtractPlanningRetrievalTerms(normalizedLookup)
            .Where(static term => term.Length >= 4)
            .ToArray();
        var subjectTerms = signalTerms
            .Where(static term => !IsGenericPlanningCoverageTerm(term))
            .Take(5)
            .ToArray();
        var slotTerms = ExtractPlanningSlotRetrievalTerms(query)
            .Take(5)
            .ToArray();

        var supportTerms = BuildPlanningExplorationSupportTerms(query)
            .Take(5)
            .ToArray();
        var constraintTerms = ExtractPlanningConstraintRetrievalTerms(normalizedLookup)
            .Take(4)
            .ToArray();

        foreach (var retrievalQuery in BuildNavigationDiscoveryRetrievalQueries(query).Take(8))
            AddDistinctQuery(queries, retrievalQuery);

        foreach (var subject in subjectTerms)
        {
            foreach (var support in supportTerms)
                AddDistinctQuery(queries, $"{subject} {support}");

            foreach (var constraint in constraintTerms)
                AddDistinctQuery(queries, $"{subject} {constraint}");
        }

        foreach (var slot in slotTerms.Take(5))
        {
            foreach (var support in supportTerms.Take(2))
                AddDistinctQuery(queries, $"{slot} {support}");
        }

        foreach (var subject in subjectTerms)
        {
            foreach (var slot in slotTerms)
                AddDistinctQuery(queries, $"{subject} {slot}");
        }

        foreach (var subject in subjectTerms.Take(4))
        {
            foreach (var slot in slotTerms.Take(4))
            {
                foreach (var support in supportTerms.Take(2))
                    AddDistinctQuery(queries, $"{subject} {slot} {support}");
            }
        }

        foreach (var slot in slotTerms)
            AddDistinctQuery(queries, slot);

        foreach (var subject in subjectTerms)
            AddDistinctQuery(queries, subject);

        if (subjectTerms.Length > 1)
            AddDistinctQuery(queries, string.Join(' ', subjectTerms));

        foreach (var retrievalQuery in BuildSourceBackedActionRetrievalQueries(query))
            AddDistinctQuery(queries, retrievalQuery);

        foreach (var retrievalQuery in BuildPlanningRetrievalQueries(query))
            AddDistinctQuery(queries, retrievalQuery);

        return queries
            .Where(static q => !string.IsNullOrWhiteSpace(q))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(24)
            .ToArray();
    }

    private static IEnumerable<string> ExtractPlanningSlotRetrievalTerms(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            yield break;

        var patterns = new[]
        {
            @"petit[-\s]+dejeuner",
            @"breakfast",
            @"desayuno",
            @"pequeno\s+almoco",
            @"cafe\s+da\s+manha",
            @"fruhstuck",
            @"colazione",
            @"\bmidi\b",
            @"\bdejeuner\b",
            @"\blunch\b",
            @"\balmuerzo\b",
            @"\balmoco\b",
            @"\bmittag\b",
            @"\bpranzo\b",
            @"\bsoir\b",
            @"\bdiner\b",
            @"\bdinner\b",
            @"\bcena\b",
            @"\babend\b",
            @"\bmatin\b",
            @"\bmorning\b",
            @"\bmanha\b",
            @"\bmorgen\b",
            @"\bmattina\b",
            @"apres[-\s]+midi",
            @"\bafternoon\b",
            @"\btarde\b",
            @"\bnachmittag\b",
            @"\bpomeriggio\b",
            @"\blundi\b",
            @"\bmardi\b",
            @"\bmercredi\b",
            @"\bjeudi\b",
            @"\bvendredi\b",
            @"\bmonday\b",
            @"\btuesday\b",
            @"\bwednesday\b",
            @"\bthursday\b",
            @"\bfriday\b"
        };

        var emitted = new HashSet<string>(StringComparer.Ordinal);
        foreach (var pattern in patterns)
        {
            foreach (Match match in Regex.Matches(normalized, pattern, RegexOptions.CultureInvariant))
            {
                var value = CollapseWhitespace(match.Value);
                if (value.Length >= 4 && emitted.Add(value))
                    yield return value;
            }
        }
    }

    private static IEnumerable<string> ExtractPlanningRetrievalTerms(string normalizedQuery)
    {
        var stopWords = new HashSet<string>(StringComparer.Ordinal)
        {
            "aide", "aider", "avec", "avoir", "cette", "comment", "dans", "faire", "facile", "idee",
            "peux", "pour", "propose", "proposes", "quoi", "sais", "vais", "veux", "voudrais",
            "cherche", "chercher", "trouve", "trouver", "trouves", "recherche", "rechercher",
            "demande", "demandes", "souhaite", "souhaites", "souhaiter",
            "about", "find", "help", "make", "prepare", "recommend", "suggest", "what", "with",
            "can", "could", "give", "need", "want", "search", "looking", "look", "asked", "request",
            "ayuda", "ayudar", "ayudame", "puede", "puedes",
            "podrias", "propone", "recomienda", "ajuda", "ajudar", "pode", "podes", "recomenda",
            "kannst", "konntest", "helfen", "vorschlag", "empfiehl", "aiuta", "aiutami", "puoi",
            "consiglia"
        };

        return Regex.Matches(normalizedQuery, @"[\p{L}\p{N}]{4,}")
            .Select(m => m.Value)
            .Where(term => !stopWords.Contains(term))
            .Distinct(StringComparer.Ordinal)
            .Take(8);
    }

    private static bool LooksLikeSourceBackedAdaptationRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var mentionsSource = Regex.IsMatch(
            normalized,
            @"\b(?:pdf|document|documents|source|sources|extrait|extraits|base|connaissance|knowledge)\b",
            RegexOptions.CultureInvariant);
        var mentionsAdaptation = Regex.IsMatch(
            normalized,
            @"\b(?:adaptation|adaptations|adapte|adapter|adaptee|adaptees|adapted|adapt|extrapole|extrapoler|derive|derived)\b",
            RegexOptions.CultureInvariant);

        return mentionsSource && mentionsAdaptation;
    }

    private static bool LooksLikeRankingDocumentaryRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var hasRankingOperator = Regex.IsMatch(
            normalized,
            @"\b(?:quel|quelle|quels|quelles|which|what|cual|qual|welche|welcher|welches|quale)\b.{0,120}\b(?:plus|moins|meilleur|meilleure|meilleurs|meilleures|pire|pires|most|least|best|worst|mas|mais|menos|mejor|melhor|beste|bester|bestes|peggiore|migliore)\b|\b(?:le|la|les|the|el|los|las|o|a|os|as|der|die|das|il|lo|gli)\s+(?:plus|moins|meilleur|meilleure|meilleurs|meilleures|pire|pires|most|least|best|worst|mas|mais|menos|mejor|melhor|beste|bester|bestes|peggiore|migliore)\b",
            RegexOptions.CultureInvariant);
        if (!hasRankingOperator)
            return false;

        return ExtractQuerySignalTerms(normalized).Any()
            || Regex.IsMatch(normalized, @"\b(?:technique|technical|tecnico|tecnica|technisch|complique|complexe|complex|difficile|difficult|schwierig)\b", RegexOptions.CultureInvariant);
    }

    private static string[] BuildSourceBackedActionRetrievalQueries(string query)
    {
        var normalized = NormalizeRagQueryForRetrieval(query);
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = CollapseWhitespace(query);

        var queries = new List<string>();
        var raw = CollapseWhitespace(query);
        var hasDelimitedUserDemand = TryExtractDelimitedUserDemandTopic(query, out _);
        var collectionTarget = string.Empty;
        var hasCollectionTarget = !LooksLikeSourceBackedPairingRecommendationRequest(query)
            && (TryExtractGenericCollectionTarget(normalized, out collectionTarget)
                || TryExtractGenericCollectionTarget(query, out collectionTarget));
        if (hasCollectionTarget && !string.IsNullOrWhiteSpace(collectionTarget))
        {
            AddDistinctQuery(queries, collectionTarget);
            foreach (var structureTerm in BuildBroadDiscoveryStructureTerms(query).Take(4))
                AddDistinctQuery(queries, $"{collectionTarget} {structureTerm}");
        }
        if (hasDelimitedUserDemand && !string.IsNullOrWhiteSpace(normalized))
            AddDistinctQuery(queries, normalized);
        if (!hasCollectionTarget && !string.IsNullOrWhiteSpace(raw))
            AddDistinctQuery(queries, raw);
        if (!hasDelimitedUserDemand && !hasCollectionTarget)
        {
            if (!string.IsNullOrWhiteSpace(raw) && !string.Equals(raw, normalized, StringComparison.OrdinalIgnoreCase))
                AddDistinctQuery(queries, normalized);
            else if (!string.IsNullOrWhiteSpace(normalized))
                AddDistinctQuery(queries, normalized);
        }

        var retrievalSeed = hasCollectionTarget && !string.IsNullOrWhiteSpace(collectionTarget)
            ? collectionTarget
            : normalized;
        foreach (var variant in BuildTypoTolerantQueryVariants(retrievalSeed))
            AddDistinctQuery(queries, variant);
        foreach (var variant in BuildGenericRetrievalSemanticQueries(retrievalSeed))
            AddDistinctQuery(queries, variant);

        var normalizedLookup = NormalizeLexicalLookup(retrievalSeed);
        var termSeeds = new List<string> { normalizedLookup };
        foreach (var variant in BuildTypoTolerantQueryVariants(normalizedLookup))
            termSeeds.Add(NormalizeLexicalLookup(variant));

        var terms = termSeeds
            .SelectMany(ExtractQuerySignalTerms)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .SelectMany(BuildRetrievalTermVariants)
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();

        var fullQueryTerms = ExtractQuerySignalTerms(NormalizeLexicalLookup(query))
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !IsGenericPlanningCoverageTerm(term))
            .SelectMany(BuildRetrievalTermVariants)
            .Where(static term => term.Length >= 4)
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();

        if (!hasCollectionTarget && fullQueryTerms.Length > 1)
            AddDistinctQuery(queries, string.Join(' ', fullQueryTerms.Take(6)));

        if (terms.Length > 0)
            AddDistinctQuery(queries, string.Join(' ', terms));

        var softChoiceOptionKindQueries = BuildSoftChoiceOptionKindRetrievalQueries(query).ToArray();
        foreach (var optionKindQuery in softChoiceOptionKindQueries)
            AddDistinctQuery(queries, optionKindQuery);

        if (LooksLikeSourceBackedPairingRecommendationRequest(query))
        {
            var pairingOptionKindTerms = ExtractPairingRequestedOptionKindTerms(query)
                .SelectMany(BuildRetrievalTermVariants)
                .Where(static term => term.Length >= 4)
                .Distinct(StringComparer.Ordinal)
                .Take(5)
                .ToArray();
            var pairingTargetTerms = ExtractPairingTargetAnchorTerms(query)
                .SelectMany(BuildRetrievalTermVariants)
                .Where(static term => term.Length >= 4)
                .Distinct(StringComparer.Ordinal)
                .Take(4)
                .ToArray();

            foreach (var kindTerm in pairingOptionKindTerms)
            {
                AddDistinctQuery(queries, kindTerm);
                foreach (var targetTerm in pairingTargetTerms.Take(2))
                    AddDistinctQuery(queries, $"{kindTerm} {targetTerm}");
            }
        }

        var subjectTerms = terms
            .Where(static term => term.Length >= 5)
            .Where(static term => !Regex.IsMatch(term, @"\b(?:alleger|all[eé]ger|lighten|reduce|reduire|adapter|adaptation)\b", RegexOptions.CultureInvariant))
            .Take(5)
            .ToArray();
        if (subjectTerms.Length > 0)
            AddDistinctQuery(queries, string.Join(' ', subjectTerms));

        var softChoiceKindTerms = ExtractSoftChoiceRequestedOptionKindTerms(query)
            .SelectMany(BuildRetrievalTermVariants)
            .ToHashSet(StringComparer.Ordinal);
        var softChoicePhraseSingletonTermsToSuppress = softChoiceOptionKindQueries
            .Select(NormalizeLexicalLookup)
            .SelectMany(ExtractQuerySignalTerms)
            .SelectMany(BuildRetrievalTermVariants)
            .Where(term => !softChoiceKindTerms.Contains(term))
            .ToHashSet(StringComparer.Ordinal);

        foreach (var term in subjectTerms.Take(6))
        {
            if (softChoicePhraseSingletonTermsToSuppress.Contains(term))
                continue;

            AddDistinctQuery(queries, term);
        }

        foreach (var discoveryQuery in BuildBroadSourceBackedDiscoveryRetrievalQueries(query).Take(12))
            AddDistinctQuery(queries, discoveryQuery);

        return queries
            .Where(static q => !string.IsNullOrWhiteSpace(q))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(ResolveSourceBackedActionRetrievalQueryLimit(query))
            .ToArray();
    }

    private static string[] BuildSourceBackedEvidenceExpansionRetrievalQueries(string query)
    {
        if (UsesSourceBackedPlanningCoverage(query))
        {
            return BuildPlanningExplorationRetrievalQueries(query);
        }

        var queries = new List<string>();
        foreach (var optionKindQuery in BuildSoftChoiceOptionKindRetrievalQueries(query).Take(5))
        {
            AddDistinctQuery(queries, optionKindQuery);
            if (LooksLikeSourceBackedOptionRequest(query))
            {
                foreach (var suffix in BuildCandidateExpansionSuffixes(query).Take(3))
                    AddDistinctQuery(queries, $"{optionKindQuery} {suffix}");
            }
        }

        foreach (var retrievalQuery in BuildSourceBackedActionRetrievalQueries(query))
            AddDistinctQuery(queries, retrievalQuery);
        foreach (var retrievalQuery in BuildBroadSourceBackedDiscoveryRetrievalQueries(query).Take(14))
            AddDistinctQuery(queries, retrievalQuery);

        var normalized = NormalizeLexicalLookup(NormalizeRagQueryForRetrieval(query));
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = NormalizeLexicalLookup(query);

        var signalTerms = ExtractQuerySignalTerms(normalized)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !IsGenericPlanningCoverageTerm(term))
            .SelectMany(BuildRetrievalTermVariants)
            .Where(static term => term.Length >= 4)
            .Distinct(StringComparer.Ordinal)
            .Take(10)
            .ToArray();

        foreach (var term in signalTerms.Take(8))
            AddDistinctQuery(queries, term);

        if (signalTerms.Length > 1)
            AddDistinctQuery(queries, string.Join(' ', signalTerms.Take(6)));

        if (LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeSourceBackedOptionRequest(query))
        {
            foreach (var term in signalTerms.Take(5))
            {
                foreach (var suffix in BuildCandidateExpansionSuffixes(query))
                    AddDistinctQuery(queries, $"{term} {suffix}");
            }
        }

        foreach (var optionKindQuery in BuildSoftChoiceOptionKindRetrievalQueries(query).Take(5))
        {
            AddDistinctQuery(queries, optionKindQuery);
            if (LooksLikeSourceBackedOptionRequest(query))
            {
                foreach (var suffix in BuildCandidateExpansionSuffixes(query).Take(3))
                    AddDistinctQuery(queries, $"{optionKindQuery} {suffix}");
            }
        }

        if (LooksLikeSourceBackedPairingRecommendationRequest(query))
        {
            var kindTerms = ExtractPairingRequestedOptionKindTerms(query)
                .SelectMany(BuildRetrievalTermVariants)
                .Where(static term => term.Length >= 4)
                .Distinct(StringComparer.Ordinal)
                .Take(5)
                .ToArray();
            var targetTerms = ExtractPairingTargetAnchorTerms(query)
                .SelectMany(BuildRetrievalTermVariants)
                .Where(static term => term.Length >= 4)
                .Distinct(StringComparer.Ordinal)
                .Take(4)
                .ToArray();
            foreach (var kindTerm in kindTerms)
            {
                AddDistinctQuery(queries, kindTerm);
                foreach (var targetTerm in targetTerms.Take(3))
                    AddDistinctQuery(queries, $"{kindTerm} {targetTerm}");
            }
        }

        return queries
            .Where(static q => !string.IsNullOrWhiteSpace(q))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(16)
            .ToArray();
    }

    private const int MaxSourceBackedEvidenceExplorationPasses = 4;
    private const int MaxSourceBackedLlmEvidenceExplorationPasses = 2;
    private const int MaxSourceBackedLlmEvidenceExplorationRounds = 2;
    private const int MaxSourceBackedLlmEvidenceExplorationQueries = 12;

    private sealed record SourceBackedEvidenceExplorationPass(
        string Label,
        string Purpose,
        string[] Queries,
        string? CategoryScope = null);

    private static IReadOnlyList<SourceBackedEvidenceExplorationPass> BuildSourceBackedEvidenceExplorationPasses(
        ToolResults toolResults,
        string? query,
        string language,
        bool forceBroadenedExploration = false)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<SourceBackedEvidenceExplorationPass>();

        var analysis = AnalyzeSourceBackedEvidenceSufficiency(toolResults, query, language);
        forceBroadenedExploration |= IsBroadenedSourceSearchConfirmationEnvelope(query);
        if (!analysis.ShouldExplore && !forceBroadenedExploration)
            return Array.Empty<SourceBackedEvidenceExplorationPass>();

        var passes = new List<SourceBackedEvidenceExplorationPass>();
        var emittedQueries = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        void AddPass(string label, string purpose, IEnumerable<string> rawQueries, int maxQueries)
        {
            var queries = rawQueries
                .Where(static value => !string.IsNullOrWhiteSpace(value))
                .Select(CollapseWhitespace)
                .Where(static value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Where(emittedQueries.Add)
                .Take(maxQueries)
                .ToArray();
            if (queries.Length == 0)
                return;

            passes.Add(new SourceBackedEvidenceExplorationPass(label, purpose, queries));
        }

        var usesPlanningCoverage = UsesSourceBackedPlanningCoverage(query);
        if (usesPlanningCoverage)
        {
            AddPass(
                "navigation_discovery",
                "Find document profiles, indexes and title anchors before selecting concrete units.",
                BuildNavigationDiscoveryRetrievalQueries(query),
                16);
            AddPass(
                "planning_exploration",
                "Find more candidate units and slots for a structured source-backed plan.",
                BuildPlanningExplorationRetrievalQueries(query),
                18);
            AddPass(
                "candidate_discovery",
                "Explore adjacent candidate vocabulary when the first planning evidence is too narrow.",
                BuildSourceBackedCandidateDiscoveryRetrievalQueries(query),
                18);
            AddPass(
                "anchor_discovery",
                "Probe requested anchors, constraints and slot terms independently.",
                BuildSourceBackedAnchorDiscoveryRetrievalQueries(query),
                16);
        }
        else
        {
            AddPass(
                "navigation_discovery",
                "Find document profiles, indexes and title anchors before selecting concrete units.",
                BuildNavigationDiscoveryRetrievalQueries(query),
                16);
            AddPass(
                "evidence_expansion",
                "Broaden source-backed retrieval around the explicit request.",
                BuildSourceBackedEvidenceExpansionRetrievalQueries(query),
                16);
            AddPass(
                "candidate_discovery",
                "Explore option, candidate and support vocabulary for broad synthesis.",
                BuildSourceBackedCandidateDiscoveryRetrievalQueries(query),
                18);
            AddPass(
                "anchor_discovery",
                "Probe requested anchors and option kinds separately when direct evidence is sparse.",
                BuildSourceBackedAnchorDiscoveryRetrievalQueries(query),
                16);
        }

        return passes.Take(MaxSourceBackedEvidenceExplorationPasses).ToArray();
    }

    private static SourceBackedEvidenceExplorationPass? BuildSourceBackedRouteAnchorFollowupExplorationPass(
        ToolResults toolResults,
        string query,
        string language)
    {
        var queries = BuildSourceBackedRouteAnchorFollowupRetrievalQueries(toolResults, query, language);
        return queries.Length == 0
            ? null
            : new SourceBackedEvidenceExplorationPass(
                "anchor_followup",
                "Use discovered navigation/title anchors as concrete retrieval seeds.",
                queries);
    }

    private static bool HasSourceBackedRouteAnchorFollowupQueries(
        ToolResults toolResults,
        string query,
        string language)
        => BuildSourceBackedRouteAnchorFollowupRetrievalQueries(toolResults, query, language).Length > 0;

    private static string[] BuildSourceBackedRouteAnchorFollowupRetrievalQueries(
        ToolResults toolResults,
        string query,
        string language)
    {
        var queries = new List<string>();
        var emitted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var tried in EnumerateRagHitSummaries(toolResults)
                     .Select(static hit => hit.RetrievalQuery)
                     .Where(static value => !string.IsNullOrWhiteSpace(value))
                     .Select(static value => NormalizeGeneratedSourceBackedExplorationQueryForDedup(value)))
        {
            if (!string.IsNullOrWhiteSpace(tried))
                emitted.Add(tried);
        }

        var supportTerms = BuildPlanningExplorationSupportTerms(query)
            .Concat(BuildPlanningExpansionSuffixes(query))
            .Concat(BuildCandidateExpansionSuffixes(query))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(6)
            .ToArray();
        var slotTerms = ExtractPlanningSlotRetrievalTerms(query)
            .Concat(ExtractPlanningConstraintRetrievalTerms(NormalizeLexicalLookup(query)))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(6)
            .ToArray();
        var contentTerms = BuildRouteAnchorFollowupContentTerms(query, language)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToArray();

        var titles = ExtractSourceBackedRouteAnchorFollowupTitles(toolResults)
            .Concat(ExtractSourceBackedDocumentNavigationFollowupTitles(toolResults, query))
            .Concat(ExtractSourceBackedTreeFollowupTitles(toolResults, query))
            .Take(24)
            .ToArray();

        foreach (var title in titles)
            AddGeneratedSourceBackedFollowupQuery(queries, emitted, title);

        foreach (var title in titles)
        {
            AddGeneratedSourceBackedFollowupQuery(queries, emitted, QuoteLookupTitle(title));

            foreach (var variant in BuildTypoTolerantQueryVariants(title))
            {
                AddGeneratedSourceBackedFollowupQuery(queries, emitted, variant);
                AddGeneratedSourceBackedFollowupQuery(queries, emitted, QuoteLookupTitle(variant));
            }

            foreach (var term in contentTerms.Take(3))
                AddGeneratedSourceBackedFollowupQuery(queries, emitted, $"{title} {term}");

            foreach (var suffix in supportTerms.Take(2))
                AddGeneratedSourceBackedFollowupQuery(queries, emitted, $"{title} {suffix}");

            foreach (var slot in slotTerms.Take(2))
                AddGeneratedSourceBackedFollowupQuery(queries, emitted, $"{title} {slot}");

            if (queries.Count >= 32)
                break;
        }

        return queries
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(32)
            .ToArray();
    }

    private static IEnumerable<string> ExtractSourceBackedTreeFollowupTitles(ToolResults toolResults, string query)
    {
        var queryTerms = BuildSourceBackedTreeFollowupQueryTerms(query).ToArray();
        var rankedTitles = new List<(string Title, int Score, int Index)>();
        var emitted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var index = 0;

        foreach (var item in toolResults.Items
                     .Where(static item => item.ToolName == "documents.tree" && string.IsNullOrWhiteSpace(item.Error))
                     .TakeLast(2))
        {
            foreach (var rawLabel in ExtractTreeNavigationAnchorLabels(item.Result))
            {
                foreach (var title in ExpandTreeNavigationAnchorLabel(rawLabel))
                {
                    var cleaned = CleanNavigationRouteAnchorTitle(title);
                    if (!IsUsableSourceBackedOptionTitle(cleaned)
                        || LooksLikeNavigationIndexHeadingTitle(cleaned)
                        || !emitted.Add(cleaned))
                    {
                        continue;
                    }

                    var score = ComputeTreeNavigationAnchorFollowupScore(cleaned, rawLabel, queryTerms);
                    if (score <= 0 && !LooksLikeDocumentTreeNavigationAnchor(rawLabel, cleaned))
                        continue;

                    rankedTitles.Add((cleaned, score, index++));
                }
            }
        }

        return rankedTitles
            .OrderByDescending(static item => item.Score)
            .ThenBy(static item => item.Index)
            .Select(static item => item.Title)
            .Take(18)
            .ToArray();
    }

    private static IEnumerable<string> ExtractSourceBackedDocumentNavigationFollowupTitles(ToolResults toolResults, string query)
    {
        var queryTerms = BuildSourceBackedTreeFollowupQueryTerms(query).ToArray();
        var rankedTitles = new List<(string Title, int Score, int Index)>();
        var emitted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var index = 0;

        foreach (var item in toolResults.Items
                     .Where(static item => item.ToolName == "documents.navigation" && string.IsNullOrWhiteSpace(item.Error))
                     .TakeLast(3))
        {
            foreach (var candidate in ExtractDocumentNavigationFollowupLabels(item.Result))
            {
                foreach (var title in ExpandTreeNavigationAnchorLabel(candidate.Label))
                {
                    var cleaned = CleanNavigationRouteAnchorTitle(title);
                    if (!IsUsableSourceBackedOptionTitle(cleaned)
                        || LooksLikeNavigationIndexHeadingTitle(cleaned)
                        || LooksLikeWeakSourceBackedOptionTitle(cleaned)
                        || !emitted.Add(cleaned))
                    {
                        continue;
                    }

                    var score = ComputeTreeNavigationAnchorFollowupScore(cleaned, candidate.RawLabel, queryTerms)
                                + candidate.ScoreHint;
                    rankedTitles.Add((cleaned, score, index++));
                }
            }
        }

        return rankedTitles
            .OrderByDescending(static item => item.Score)
            .ThenBy(static item => item.Index)
            .Select(static item => item.Title)
            .Take(24)
            .ToArray();
    }

    private static IEnumerable<(string Label, string RawLabel, int ScoreHint)> ExtractDocumentNavigationFollowupLabels(JsonElement result)
    {
        if (result.ValueKind != JsonValueKind.Object
            || !result.TryGetProperty("items", out var items)
            || items.ValueKind != JsonValueKind.Array)
        {
            yield break;
        }

        foreach (var entry in items.EnumerateArray())
        {
            var label = CollapseWhitespace(
                TryGetString(entry, "label")
                ?? TryGetString(entry, "Label")
                ?? TryGetString(entry, "title")
                ?? TryGetString(entry, "Title")
                ?? string.Empty);
            if (string.IsNullOrWhiteSpace(label))
                continue;

            var docPath = CollapseWhitespace(TryGetString(entry, "docPath") ?? TryGetString(entry, "DocPath") ?? string.Empty);
            var docName = CollapseWhitespace(TryGetString(entry, "docName") ?? TryGetString(entry, "DocName") ?? Path.GetFileName(docPath));
            var kind = CollapseWhitespace(TryGetString(entry, "kind") ?? TryGetString(entry, "Kind") ?? string.Empty);
            var method = CollapseWhitespace(TryGetString(entry, "resolutionMethod") ?? TryGetString(entry, "ResolutionMethod") ?? string.Empty);
            var hasTargetChunk = TryGetBool(entry, "hasTargetChunk") ?? TryGetBool(entry, "HasTargetChunk") ?? false;
            var hasTargetAnchor = TryGetBool(entry, "hasTargetAnchor") ?? TryGetBool(entry, "HasTargetAnchor") ?? false;
            var confidence = TryGetDouble(entry, "confidence") ?? TryGetDouble(entry, "Confidence");
            var targetPageStart = TryGetInt(entry, "targetPageStart") ?? TryGetInt(entry, "TargetPageStart");
            var targetPageEnd = TryGetInt(entry, "targetPageEnd") ?? TryGetInt(entry, "TargetPageEnd");

            var scoreHint = 1;
            if (hasTargetChunk)
                scoreHint += 3;
            if (hasTargetAnchor)
                scoreHint += 2;
            if (targetPageStart is not null)
                scoreHint += 2;
            if (targetPageEnd is not null && targetPageStart is not null && targetPageEnd.Value >= targetPageStart.Value)
                scoreHint += 1;
            if (confidence is >= 0.65)
                scoreHint += 2;
            if (confidence is >= 0.9)
                scoreHint += 1;
            if (kind.Contains("title", StringComparison.OrdinalIgnoreCase)
                || method.Contains("chunk", StringComparison.OrdinalIgnoreCase))
            {
                scoreHint += 1;
            }

            var raw = string.Join(" | ", new[] { label, docName, docPath, kind, method }.Where(static value => !string.IsNullOrWhiteSpace(value)));
            yield return (label, raw, scoreHint);
        }
    }

    private static IEnumerable<string> ExtractTreeNavigationAnchorLabels(JsonElement result)
    {
        if (result.ValueKind == JsonValueKind.Object
            && result.TryGetProperty("markdown", out var markdown)
            && markdown.ValueKind == JsonValueKind.String)
        {
            foreach (var label in ExtractMarkdownTreeNavigationAnchorLabels(markdown.GetString()))
                yield return label;
        }

        foreach (var label in ExtractJsonTreeNavigationAnchorLabels(result, depth: 0))
            yield return label;
    }

    private static IEnumerable<string> ExtractMarkdownTreeNavigationAnchorLabels(string? markdown)
    {
        if (string.IsNullOrWhiteSpace(markdown))
            yield break;

        foreach (var raw in markdown.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries))
        {
            var text = CollapseWhitespace(raw);
            text = Regex.Replace(text, @"^[\s\-\*\+\u2022\u00b7|`>\\/.]+", string.Empty, RegexOptions.CultureInvariant);
            text = Regex.Replace(text, @"^(?:[â”œâ””â”‚â”€]+\s*)+", string.Empty, RegexOptions.CultureInvariant);
            text = CollapseWhitespace(text.Trim());
            if (!string.IsNullOrWhiteSpace(text))
                yield return text;
        }
    }

    private static IEnumerable<string> ExtractJsonTreeNavigationAnchorLabels(JsonElement element, int depth)
    {
        if (depth > 6)
            yield break;

        switch (element.ValueKind)
        {
            case JsonValueKind.Object:
                var label = TryBuildTreeJsonStructureLabel(element);
                if (!string.IsNullOrWhiteSpace(label))
                    yield return label;

                foreach (var property in element.EnumerateObject())
                {
                    if (property.Value.ValueKind is JsonValueKind.Object or JsonValueKind.Array
                        && IsTreeStructureProperty(property.Name))
                    {
                        foreach (var childLabel in ExtractJsonTreeNavigationAnchorLabels(property.Value, depth + 1))
                            yield return childLabel;
                    }
                }

                break;

            case JsonValueKind.Array:
                foreach (var item in element.EnumerateArray())
                {
                    foreach (var childLabel in ExtractJsonTreeNavigationAnchorLabels(item, depth + 1))
                        yield return childLabel;
                }

                break;
        }
    }

    private static IEnumerable<string> ExpandTreeNavigationAnchorLabel(string? rawLabel)
    {
        var cleaned = CollapseWhitespace(rawLabel ?? string.Empty)
            .Trim(' ', '.', ',', ';', ':', '"', '\'', '\u2022', '\u00b7', '-', '\u2013');
        if (string.IsNullOrWhiteSpace(cleaned))
            yield break;

        cleaned = Regex.Replace(cleaned, @"\s*\(\s*\d+\s+(?:docs?|documents?|fichiers?|files?)\s*\)\s*$", string.Empty, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        cleaned = Regex.Replace(cleaned, @"^(?:navigationOnly\s+tree\s*:\s*)", string.Empty, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        cleaned = CollapseWhitespace(cleaned);
        if (string.IsNullOrWhiteSpace(cleaned))
            yield break;

        yield return cleaned;

        foreach (var segment in Regex.Split(cleaned, @"\s*>\s*|[\\/]+", RegexOptions.CultureInvariant))
        {
            var part = CollapseWhitespace(segment)
                .Trim(' ', '.', ',', ';', ':', '"', '\'', '\u2022', '\u00b7', '-', '\u2013');
            if (string.IsNullOrWhiteSpace(part))
                continue;

            yield return part;

            if (Regex.IsMatch(part, @"\.(?:pdf|docx?|xlsx?|pptx?|txt|md)$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
            {
                var withoutExtension = CollapseWhitespace(Path.GetFileNameWithoutExtension(part));
                if (!string.IsNullOrWhiteSpace(withoutExtension))
                    yield return withoutExtension;
            }
        }
    }

    private static IEnumerable<string> BuildSourceBackedTreeFollowupQueryTerms(string? query)
    {
        var normalized = NormalizeLexicalLookup(NormalizeRagQueryForRetrieval(query ?? string.Empty));
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = NormalizeLexicalLookup(query);

        foreach (var term in ExtractQuerySignalTerms(normalized)
                     .Concat(ExtractPlanningRetrievalTerms(normalized))
                     .Concat(ExtractPlanningConstraintRetrievalTerms(normalized))
                     .SelectMany(BuildRetrievalTermVariants)
                     .Where(static term => term.Length >= 4)
                     .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
                     .Where(static term => !IsGenericPlanningCoverageTerm(term))
                     .Where(static term => !IsNavigationDiscoveryNoiseTerm(term))
                     .Distinct(StringComparer.Ordinal)
                     .Take(12))
        {
            yield return term;
        }
    }

    private static int ComputeTreeNavigationAnchorFollowupScore(string title, string rawLabel, IReadOnlyList<string> queryTerms)
    {
        var normalizedTitle = NormalizeLexicalLookup($"{title} {rawLabel}");
        if (string.IsNullOrWhiteSpace(normalizedTitle))
            return 0;

        var score = queryTerms.Count(term => normalizedTitle.Contains(NormalizeLexicalLookup(term), StringComparison.Ordinal));
        if (LooksLikeDocumentTreeNavigationAnchor(rawLabel, title))
            score += 1;
        if (Regex.IsMatch(normalizedTitle, @"\b(?:title|titre|heading|section|chapter|chapitre|document|file|fichier)\b", RegexOptions.CultureInvariant))
            score += 1;

        return score;
    }

    private static bool LooksLikeDocumentTreeNavigationAnchor(string? rawLabel, string? title)
    {
        var value = NormalizeLexicalLookup($"{rawLabel} {title}");
        if (string.IsNullOrWhiteSpace(value))
            return false;

        return Regex.IsMatch(value, @"\b(?:pdf|docx?|xlsx?|pptx?|txt|md)\b", RegexOptions.CultureInvariant)
               || Regex.IsMatch(value, @"\b(?:document|documents|file|files|fichier|fichiers|docpath|path)\b", RegexOptions.CultureInvariant);
    }

    private static IEnumerable<string> BuildRouteAnchorFollowupContentTerms(string? query, string language)
    {
        var normalizedQuery = NormalizeLexicalLookup(query);
        switch (NormalizeLanguageCode(language))
        {
            case "fr":
                yield return "contenu";
                yield return "details";
                yield return "etapes";
                yield return "methode";
                yield return "procedure";
                yield return "quantites";
                break;
            case "es":
                yield return "contenido";
                yield return "detalles";
                yield return "pasos";
                yield return "metodo";
                yield return "procedimiento";
                yield return "cantidades";
                break;
            case "pt":
                yield return "conteudo";
                yield return "detalhes";
                yield return "passos";
                yield return "metodo";
                yield return "procedimento";
                yield return "quantidades";
                break;
            case "de":
                yield return "inhalt";
                yield return "details";
                yield return "schritte";
                yield return "methode";
                yield return "verfahren";
                yield return "mengen";
                break;
            case "it":
                yield return "contenuto";
                yield return "dettagli";
                yield return "passaggi";
                yield return "metodo";
                yield return "procedura";
                yield return "quantita";
                break;
            default:
                yield return "content";
                yield return "details";
                yield return "steps";
                yield return "method";
                yield return "procedure";
                yield return "quantities";
                break;
        }

        if (UsesSourceBackedPlanningCoverage(query)
            || Regex.IsMatch(normalizedQuery, @"\b(?:plan|planning|programme|schedule|agenda|calendrier|semana|woche|settimana)\b", RegexOptions.CultureInvariant))
        {
            yield return "details";
            yield return "content";
            yield return "constraints";
        }

        if (LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeBroadSynthesisRequestShape(query))
        {
            yield return "options";
            yield return "examples";
            yield return "candidates";
        }
    }

    private static void AddGeneratedSourceBackedFollowupQuery(
        List<string> queries,
        HashSet<string> emitted,
        string? query)
    {
        var sanitized = SanitizeSourceBackedLlmExplorationQuery(query);
        if (string.IsNullOrWhiteSpace(sanitized))
            return;

        var key = NormalizeGeneratedSourceBackedExplorationQueryForDedup(sanitized);
        if (string.IsNullOrWhiteSpace(key) || !emitted.Add(key))
            return;

        queries.Add(sanitized);
    }

    private static IEnumerable<string> ExtractSourceBackedRouteAnchorFollowupTitles(ToolResults toolResults)
    {
        var emitted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var hit in EnumerateRagHitSummaries(toolResults))
        {
            if (!IsRouteDiscoveryAnchorHit(hit)
                && !LooksLikeNavigationOnlyHit(hit)
                && !LooksLikeResolvedRouteTargetHit(hit)
                && !HasRouteContentCardCue(hit))
            {
                continue;
            }

            foreach (var title in ExtractRouteDiscoveryTitleCues(hit)
                         .Concat(ExtractSourceBackedTitleCandidates(hit))
                         .Select(CleanNavigationRouteAnchorTitle)
                         .Where(IsUsableSourceBackedOptionTitle))
            {
                if (LooksLikeWeakSourceBackedOptionTitle(title))
                    continue;

                var key = NormalizeLexicalLookup(title);
                if (string.IsNullOrWhiteSpace(key) || !emitted.Add(key))
                    continue;

                yield return title;
            }
        }
    }

    private static IReadOnlyList<SourceBackedEvidenceExplorationPass> ParseSourceBackedLlmEvidenceExplorationPasses(
        string? rawJson,
        IEnumerable<string>? alreadyTriedQueries = null)
    {
        if (string.IsNullOrWhiteSpace(rawJson))
            return Array.Empty<SourceBackedEvidenceExplorationPass>();

        if (!TryExtractJsonObject(rawJson, out var json))
            json = rawJson;

        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json);
        }
        catch (JsonException)
        {
            return Array.Empty<SourceBackedEvidenceExplorationPass>();
        }
        using (doc)
        {
            if (doc.RootElement.ValueKind != JsonValueKind.Object)
                return Array.Empty<SourceBackedEvidenceExplorationPass>();

            var emitted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (alreadyTriedQueries is not null)
            {
                foreach (var query in alreadyTriedQueries)
                {
                    var normalized = NormalizeGeneratedSourceBackedExplorationQueryForDedup(query);
                    if (!string.IsNullOrWhiteSpace(normalized))
                        emitted.Add(normalized);
                }
            }

            var passes = new List<SourceBackedEvidenceExplorationPass>();
            if (doc.RootElement.TryGetProperty("passes", out var passesElement) && passesElement.ValueKind == JsonValueKind.Array)
            {
                foreach (var passElement in passesElement.EnumerateArray())
                {
                    if (passElement.ValueKind != JsonValueKind.Object)
                        continue;

                    var label = NormalizeSourceBackedLlmExplorationLabel(TryGetString(passElement, "label"));
                    var purpose = CollapseWhitespace(TryGetString(passElement, "purpose") ?? string.Empty);
                    var queries = ExtractSanitizedSourceBackedLlmExplorationQueries(passElement, emitted);
                    if (queries.Length == 0)
                        continue;

                    passes.Add(new SourceBackedEvidenceExplorationPass(
                        label,
                        string.IsNullOrWhiteSpace(purpose) ? "LLM-planned bounded evidence search." : purpose,
                        queries,
                        SanitizeSourceBackedLlmExplorationCategory(
                            TryGetString(passElement, "categoryScope")
                            ?? TryGetString(passElement, "category")
                            ?? TryGetString(passElement, "categoryPath")
                            ?? TryGetString(passElement, "categoryRef"))));
                    if (passes.Count >= MaxSourceBackedLlmEvidenceExplorationPasses)
                        break;
                }
            }
            else
            {
                var queries = ExtractSanitizedSourceBackedLlmExplorationQueries(doc.RootElement, emitted);
                if (queries.Length > 0)
                {
                    passes.Add(new SourceBackedEvidenceExplorationPass(
                        "llm_strategy",
                        "LLM-planned bounded evidence search.",
                        queries,
                        SanitizeSourceBackedLlmExplorationCategory(
                            TryGetString(doc.RootElement, "categoryScope")
                            ?? TryGetString(doc.RootElement, "category")
                            ?? TryGetString(doc.RootElement, "categoryPath")
                            ?? TryGetString(doc.RootElement, "categoryRef"))));
                }
            }

            return passes;
        }
    }

    private static string[] BuildSourceBackedCandidateDiscoveryRetrievalQueries(string query)
    {
        var queries = new List<string>();
        var normalized = NormalizeLexicalLookup(NormalizeRagQueryForRetrieval(query));
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = NormalizeLexicalLookup(query);

        foreach (var retrievalQuery in BuildSoftChoiceOptionKindRetrievalQueries(query))
            AddDistinctQuery(queries, retrievalQuery);

        var subjectTerms = ExtractQuerySignalTerms(normalized)
            .Concat(ExtractPlanningRetrievalTerms(normalized))
            .Where(static term => term.Length >= 4)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !IsGenericPlanningCoverageTerm(term))
            .SelectMany(BuildRetrievalTermVariants)
            .Where(static term => term.Length >= 4)
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        var supportTerms = BuildPlanningExplorationSupportTerms(query)
            .Take(5)
            .ToArray();
        var candidateSuffixes = BuildCandidateExpansionSuffixes(query)
            .Take(4)
            .ToArray();
        var slotTerms = ExtractPlanningSlotRetrievalTerms(query)
            .Take(5)
            .ToArray();
        var constraintTerms = ExtractPlanningConstraintRetrievalTerms(normalized)
            .Take(4)
            .ToArray();

        foreach (var retrievalQuery in BuildNavigationDiscoveryRetrievalQueries(query).Take(8))
            AddDistinctQuery(queries, retrievalQuery);
        foreach (var retrievalQuery in BuildBroadSourceBackedDiscoveryRetrievalQueries(query).Take(14))
            AddDistinctQuery(queries, retrievalQuery);

        foreach (var subject in subjectTerms)
        {
            AddDistinctQuery(queries, subject);
            foreach (var suffix in candidateSuffixes)
                AddDistinctQuery(queries, $"{subject} {suffix}");
            foreach (var support in supportTerms.Take(3))
                AddDistinctQuery(queries, $"{subject} {support}");
            foreach (var constraint in constraintTerms)
                AddDistinctQuery(queries, $"{subject} {constraint}");
        }

        foreach (var slot in slotTerms)
        {
            AddDistinctQuery(queries, slot);
            foreach (var support in supportTerms.Take(3))
                AddDistinctQuery(queries, $"{slot} {support}");
            foreach (var subject in subjectTerms.Take(4))
                AddDistinctQuery(queries, $"{subject} {slot}");
        }

        foreach (var retrievalQuery in BuildSourceBackedActionRetrievalQueries(query).Take(10))
            AddDistinctQuery(queries, retrievalQuery);

        return queries
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(18)
            .ToArray();
    }

    private static string[] BuildSourceBackedAnchorDiscoveryRetrievalQueries(string query)
    {
        var queries = new List<string>();
        var anchorTerms = ExtractPlanningCoverageAnchorTerms(query)
            .Concat(ExtractPairingTargetAnchorTerms(query))
            .Concat(ExtractPairingRequestedOptionKindTerms(query))
            .Concat(ExtractSoftChoiceRequestedOptionKindTerms(query))
            .SelectMany(BuildRetrievalTermVariants)
            .Where(static term => term.Length >= 4)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !IsGenericPlanningCoverageTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        var suffixes = BuildCandidateExpansionSuffixes(query)
            .Concat(BuildPlanningExpansionSuffixes(query))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(5)
            .ToArray();
        var slotTerms = ExtractPlanningSlotRetrievalTerms(query)
            .Take(5)
            .ToArray();

        foreach (var anchor in anchorTerms)
        {
            AddDistinctQuery(queries, anchor);
            foreach (var suffix in suffixes)
                AddDistinctQuery(queries, $"{anchor} {suffix}");
            foreach (var slot in slotTerms.Take(4))
                AddDistinctQuery(queries, $"{anchor} {slot}");
        }

        foreach (var slot in slotTerms)
            AddDistinctQuery(queries, slot);

        return queries
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(16)
            .ToArray();
    }

    private static string NormalizeSourceBackedLlmExplorationLabel(string? label)
    {
        var normalized = CollapseWhitespace(label ?? string.Empty)
            .ToLowerInvariant()
            .Replace('-', '_');
        normalized = Regex.Replace(normalized, @"[^a-z0-9_]+", "_", RegexOptions.CultureInvariant).Trim('_');
        return string.IsNullOrWhiteSpace(normalized) ? "llm_strategy" : normalized;
    }

    private static string[] ExtractSanitizedSourceBackedLlmExplorationQueries(
        JsonElement container,
        HashSet<string> emitted)
    {
        if (!container.TryGetProperty("queries", out var queriesElement) || queriesElement.ValueKind != JsonValueKind.Array)
            return Array.Empty<string>();

        var queries = new List<string>();
        foreach (var queryElement in queriesElement.EnumerateArray())
        {
            if (queryElement.ValueKind != JsonValueKind.String)
                continue;

            var sanitized = SanitizeSourceBackedLlmExplorationQuery(queryElement.GetString());
            if (string.IsNullOrWhiteSpace(sanitized))
                continue;

            var key = NormalizeGeneratedSourceBackedExplorationQueryForDedup(sanitized);
            if (string.IsNullOrWhiteSpace(key) || !emitted.Add(key))
                continue;

            queries.Add(sanitized);
            if (queries.Count >= MaxSourceBackedLlmEvidenceExplorationQueries)
                break;
        }

        return queries.ToArray();
    }

    private static string? SanitizeSourceBackedLlmExplorationCategory(string? category)
    {
        var value = CollapseWhitespace(category ?? string.Empty)
            .Trim(' ', '.', ',', ';', ':', '-', '\u2022', '\u00b7');
        if (value.Length < 3 || value.Length > 120)
            return null;

        if (LooksLikeUnsafeGeneratedSourceBackedExplorationQuery(value))
            return null;

        if (Regex.Matches(value, @"[{}<>]").Count > 0)
            return null;

        return value;
    }

    private static string? SanitizeSourceBackedLlmExplorationQuery(string? query)
    {
        var value = CollapseWhitespace(query ?? string.Empty)
            .Trim(' ', '.', ',', ';', ':', '-', '\u2022', '\u00b7');
        if (value.Length < 3 || value.Length > 120)
            return null;

        if (LooksLikeUnsafeGeneratedSourceBackedExplorationQuery(value))
            return null;

        if (Regex.Matches(value, @"[{}<>]").Count > 0)
            return null;

        var tokenCount = Regex.Matches(value, @"[\p{L}\p{N}][\p{L}\p{N}'’/-]*", RegexOptions.CultureInvariant).Count;
        if (tokenCount is < 1 or > 14)
            return null;

        var normalized = NormalizeRagQueryForRetrieval(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return null;

        normalized = CollapseWhitespace(normalized)
            .Trim(' ', '.', ',', ';', ':', '-', '\u2022', '\u00b7');
        if (normalized.Length < 3 || normalized.Length > 120)
            return null;

        return normalized;
    }

    private static bool LooksLikeUnsafeGeneratedSourceBackedExplorationQuery(string value)
    {
        var normalized = NormalizeLexicalLookup(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        if (Regex.IsMatch(
                normalized,
                @"\b(?:ignore|override|bypass|system prompt|developer message|tool result|tool_results|assistant response|final answer|json schema|execute|delete|drop table|powershell|cmd\.exe|http://|https://)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        return Regex.IsMatch(
            normalized,
            @"\b(?:reponds?|answer|write|redige|ecris|compose|summarize|resume)\b.+\b(?:directly|directement|finale?|utilisateur|user)\b",
            RegexOptions.CultureInvariant);
    }

    private static string NormalizeGeneratedSourceBackedExplorationQueryForDedup(string? query)
    {
        var normalized = NormalizeRagQueryForRetrieval(query ?? string.Empty);
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = CollapseWhitespace(query ?? string.Empty);

        return CollapseWhitespace(normalized).ToLowerInvariant();
    }

    private static int ResolveSourceBackedEvidenceExplorationTopK(string? query, string passLabel)
    {
        var baseTopK = UsesSourceBackedPlanningCoverage(query)
            ? NormalizeSourceBackedPlanningTopK(null, query ?? string.Empty)
            : Math.Max(12, NormalizeSourceBackedActionTopK(null, query ?? string.Empty));
        return string.Equals(passLabel, "candidate_discovery", StringComparison.OrdinalIgnoreCase)
               || string.Equals(passLabel, "anchor_followup", StringComparison.OrdinalIgnoreCase)
               || string.Equals(passLabel, "llm_strategy", StringComparison.OrdinalIgnoreCase)
            ? Math.Max(baseTopK, 18)
            : baseTopK;
    }

    private static IReadOnlyList<string> BuildNavigationDiscoveryRetrievalQueries(string? query)
    {
        if (string.IsNullOrWhiteSpace(query)
            || (!UsesSourceBackedPlanningCoverage(query)
                && !ShouldOfferBroadenedSourceSearch(query)
                && !LooksLikeGenericCollectionOrListRequest(query)
                && !LooksLikeBroadSourceBackedCompositionRequest(query)
                && !LooksLikeSourceBackedOptionRequest(query)))
        {
            return Array.Empty<string>();
        }

        var normalized = NormalizeLexicalLookup(NormalizeRagQueryForRetrieval(query));
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = NormalizeLexicalLookup(query);

        var navTerms = DetectRetrievalExpansionLanguage(query) switch
        {
            "en" => new[] { "table of contents", "contents", "index", "overview" },
            "es" => new[] { "indice", "contenido", "tabla de contenido", "resumen" },
            "pt" => new[] { "indice", "conteudo", "sumario", "visao geral" },
            "de" => new[] { "inhaltsverzeichnis", "inhalt", "index", "uebersicht" },
            "it" => new[] { "indice", "contenuto", "sommario", "panoramica" },
            _ => new[] { "sommaire", "table des matieres", "index", "sections principales" }
        };

        var signals = ExtractQuerySignalTerms(normalized)
            .Concat(ExtractPlanningRetrievalTerms(normalized))
            .Where(static term => term.Length >= 4)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !IsGenericPlanningCoverageTerm(term))
            .Where(static term => !IsNavigationDiscoveryNoiseTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(5)
            .ToArray();

        var queries = new List<string>();
        foreach (var signal in signals)
        {
            foreach (var navTerm in navTerms.Take(3))
            {
                AddDistinctQuery(queries, $"{signal} {navTerm}");
                AddDistinctQuery(queries, $"{navTerm} {signal}");
            }
        }

        foreach (var navTerm in navTerms)
            AddDistinctQuery(queries, navTerm);

        return queries
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(16)
            .ToArray();
    }

    private static IReadOnlyList<string> BuildBroadSourceBackedDiscoveryRetrievalQueries(string? query)
    {
        if (string.IsNullOrWhiteSpace(query) || !ShouldUseBroadSourceBackedDiscoveryQueries(query))
            return Array.Empty<string>();

        var normalized = NormalizeLexicalLookup(NormalizeRagQueryForRetrieval(query));
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = NormalizeLexicalLookup(query);

        var seeds = new List<string>();
        if (TryExtractGenericCollectionTarget(query, out var collectionTarget)
            || TryExtractGenericCollectionTarget(normalized, out collectionTarget))
        {
            AddDistinctQuery(seeds, collectionTarget);
        }

        foreach (var optionKindQuery in BuildSoftChoiceOptionKindRetrievalQueries(query).Take(4))
            AddDistinctQuery(seeds, optionKindQuery);

        foreach (var term in ExtractPairingRequestedOptionKindTerms(query)
                     .Concat(ExtractPairingTargetAnchorTerms(query))
                     .Concat(ExtractPlanningSlotRetrievalTerms(query))
                     .Concat(ExtractPlanningConstraintRetrievalTerms(normalized))
                     .Concat(ExtractQuerySignalTerms(normalized))
                     .SelectMany(BuildRetrievalTermVariants)
                     .Where(static term => term.Length >= 4)
                     .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
                     .Where(static term => !IsGenericPlanningCoverageTerm(term))
                     .Where(static term => !IsNavigationDiscoveryNoiseTerm(term))
                     .Distinct(StringComparer.Ordinal)
                     .Take(8))
        {
            AddDistinctQuery(seeds, term);
        }

        var structureTerms = BuildBroadDiscoveryStructureTerms(query).ToArray();
        var candidateTerms = BuildCandidateExpansionSuffixes(query)
            .Concat(BuildPlanningExpansionSuffixes(query))
            .Concat(BuildPlanningExplorationSupportTerms(query))
            .Concat(structureTerms)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToArray();

        var queries = new List<string>();
        foreach (var seed in seeds
                     .Select(CollapseWhitespace)
                     .Where(static value => !string.IsNullOrWhiteSpace(value))
                     .Distinct(StringComparer.OrdinalIgnoreCase)
                     .Take(8))
        {
            AddDistinctQuery(queries, seed);
            foreach (var candidateTerm in candidateTerms.Take(10))
                AddDistinctQuery(queries, $"{seed} {candidateTerm}");
        }

        foreach (var structureTerm in structureTerms.Take(6))
            AddDistinctQuery(queries, structureTerm);

        return queries
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(24)
            .ToArray();
    }

    private static bool ShouldUseBroadSourceBackedDiscoveryQueries(string? query)
        => LooksLikeGenericCollectionOrListRequest(query)
           || LooksLikeAnyDocumentaryPlanningRequest(query)
           || LooksLikeBroadSourceBackedCompositionRequest(query)
           || LooksLikeMultipleCandidateSynthesisRequest(query)
           || LooksLikeSoftChoiceRecommendationRequest(query)
           || LooksLikeSourceBackedPairingRecommendationRequest(query)
           || LooksLikeSourceBackedOptionRequest(query)
           || IsBroadenedSourceSearchConfirmationEnvelope(query);

    private static IReadOnlyList<string> BuildBroadDiscoveryStructureTerms(string? query)
        => DetectRetrievalExpansionLanguage(query) switch
        {
            "en" => new[] { "title", "titles", "sections", "summary", "topics", "keywords", "table of contents", "index" },
            "es" => new[] { "titulo", "titulos", "secciones", "resumen", "temas", "palabras clave", "indice" },
            "pt" => new[] { "titulo", "titulos", "secoes", "resumo", "temas", "palavras chave", "indice", "sumario" },
            "de" => new[] { "titel", "abschnitte", "zusammenfassung", "themen", "schluesselwoerter", "inhaltsverzeichnis", "index" },
            "it" => new[] { "titolo", "titoli", "sezioni", "riassunto", "argomenti", "parole chiave", "indice", "sommario" },
            _ => new[] { "titre", "titres", "sections", "resume", "sujets", "mots cles", "sommaire", "index" }
        };

    private static bool IsNavigationDiscoveryNoiseTerm(string term)
    {
        var normalized = NormalizeLexicalLookup(term);
        return normalized is "cherche" or "chercher" or "trouve" or "trouver" or "avoir" or "documents"
            or "document" or "available" or "disponibles" or "disponible" or "search" or "find" or "want"
            or "need" or "besoin" or "propose" or "proposer";
    }

    private static IReadOnlyList<string> BuildPlanningExpansionSuffixes(string? query)
        => DetectRetrievalExpansionLanguage(query) switch
        {
            "en" => new[] { "options", "examples", "suggestions", "ideas", "sources" },
            "es" => new[] { "opciones", "ejemplos", "sugerencias", "ideas", "fuentes" },
            "pt" => new[] { "opcoes", "exemplos", "sugestoes", "ideias", "fontes" },
            "de" => new[] { "optionen", "beispiele", "vorschlaege", "ideen", "quellen" },
            "it" => new[] { "opzioni", "esempi", "suggerimenti", "idee", "fonti" },
            _ => new[] { "options", "exemples", "suggestions", "idees", "sources" }
        };

    private static IReadOnlyList<string> BuildCandidateExpansionSuffixes(string? query)
        => DetectRetrievalExpansionLanguage(query) switch
        {
            "en" => new[] { "options", "examples", "candidates" },
            "es" => new[] { "opciones", "ejemplos", "candidatos" },
            "pt" => new[] { "opcoes", "exemplos", "candidatos" },
            "de" => new[] { "optionen", "beispiele", "kandidaten" },
            "it" => new[] { "opzioni", "esempi", "candidati" },
            _ => new[] { "options", "exemples", "candidats" }
        };

    private static IReadOnlyList<string> BuildPlanningExplorationSupportTerms(string? query)
        => DetectRetrievalExpansionLanguage(query) switch
        {
            "en" => new[] { "options", "examples", "ideas", "candidates", "steps" },
            "es" => new[] { "opciones", "ejemplos", "ideas", "candidatos", "pasos" },
            "pt" => new[] { "opcoes", "exemplos", "ideias", "candidatos", "passos" },
            "de" => new[] { "optionen", "beispiele", "ideen", "kandidaten", "schritte" },
            "it" => new[] { "opzioni", "esempi", "idee", "candidati", "passi" },
            _ => new[] { "options", "exemples", "idees", "candidats", "etapes" }
        };

    private static IEnumerable<string> ExtractPlanningConstraintRetrievalTerms(string normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            yield break;

        var patterns = new[]
        {
            @"\brapides?\b",
            @"\bquick\b",
            @"\bsimple[sz]?\b",
            @"\blegers?\b",
            @"\blight\b",
            @"\bvarie(?:e|es|s)?\b",
            @"\bvaried\b",
            @"\bmoins\s+de\s+\d{1,3}\s+minutes?\b",
            @"\bunder\s+\d{1,3}\s+minutes?\b",
            @"\ben\s+\d{1,3}\s+minutes?\b",
            @"\bin\s+\d{1,3}\s+minutes?\b"
        };

        var emitted = new HashSet<string>(StringComparer.Ordinal);
        foreach (var pattern in patterns)
        {
            foreach (Match match in Regex.Matches(normalizedQuery, pattern, RegexOptions.CultureInvariant))
            {
                var value = CollapseWhitespace(match.Value);
                if (value.Length >= 4 && emitted.Add(value))
                    yield return value;
            }
        }
    }

    private static string DetectRetrievalExpansionLanguage(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return "fr";

        var scores = new (string Language, int Score)[]
        {
            ("fr", CountRetrievalLanguageSignals(normalized, @"\b(?:aide|aider|peux|pourrais|semaine|hebdomadaire|lundi|mardi|mercredi|jeudi|vendredi|matin|midi|soir|dejeuner|diner|quoi|veux|voudrais|propose|conseille)\b")),
            ("en", CountRetrievalLanguageSignals(normalized, @"\b(?:help|make|week|weekly|monday|tuesday|wednesday|thursday|friday|morning|lunch|dinner|breakfast|what|which|want|would|suggest|recommend)\b")),
            ("es", CountRetrievalLanguageSignals(normalized, @"\b(?:ayuda|ayudame|hacer|semana|lunes|martes|miercoles|jueves|viernes|manana|desayuno|almuerzo|cena|quiero|puedes|podrias|sugiere|recomienda)\b")),
            ("pt", CountRetrievalLanguageSignals(normalized, @"\b(?:ajuda|ajudar|fazer|semana|segunda|terca|quarta|quinta|sexta|manha|almoco|jantar|quero|podes|poderias|sugere|recomenda|controlo)\b")),
            ("de", CountRetrievalLanguageSignals(normalized, @"\b(?:hilf|helfen|woche|wochenplan|montag|dienstag|mittwoch|donnerstag|freitag|morgen|mittag|abend|fruhstuck|erstellen|welche|was|mochte|vorschlag|empfiehl)\b")),
            ("it", CountRetrievalLanguageSignals(normalized, @"\b(?:aiuta|aiutami|fare|settimana|lunedi|martedi|mercoledi|giovedi|venerdi|mattina|colazione|pranzo|cena|voglio|puoi|potresti|suggerisci|consiglia)\b"))
        };

        var best = scores
            .OrderByDescending(static item => item.Score)
            .First();
        if (best.Score > 0)
            return best.Language;

        return LocalizedStrings.DetectLanguage(query, "fr");
    }

    private static int CountRetrievalLanguageSignals(string normalizedQuery, string pattern)
        => Regex.Matches(normalizedQuery, pattern, RegexOptions.CultureInvariant).Count;

    private static int ResolveSourceBackedActionRetrievalQueryLimit(string? query)
    {
        if (LooksLikeSourceBackedVerificationChecklistRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query))
        {
            return 5;
        }

        if (LooksLikeSourceBackedPairingRecommendationRequest(query))
            return 12;

        if (LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query))
        {
            return 10;
        }

        if (LooksLikeGenericCollectionOrListRequest(query))
            return 14;

        return 8;
    }

    private static string[] BuildShortTechnicalEvidenceRetrievalQueries(string query)
    {
        var normalized = NormalizeRagQueryForRetrieval(query);
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = CollapseWhitespace(query);

        var queries = new List<string>();
        if (!string.IsNullOrWhiteSpace(normalized))
            AddDistinctQuery(queries, normalized);

        if (TryExtractDelimitedUserDemandTopic(query, out _))
        {
            var raw = CollapseWhitespace(query);
            if (!string.IsNullOrWhiteSpace(raw))
                AddDistinctQuery(queries, raw);
        }

        foreach (var variant in BuildTypoTolerantQueryVariants(normalized))
            AddDistinctQuery(queries, variant);
        foreach (var variant in BuildGenericRetrievalSemanticQueries(normalized))
            AddDistinctQuery(queries, variant);

        var terms = ExtractQuerySignalTerms(NormalizeLexicalLookup(normalized))
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .SelectMany(BuildRetrievalTermVariants)
            .Distinct(StringComparer.Ordinal)
            .Take(12)
            .ToArray();
        if (terms.Length > 0)
            AddDistinctQuery(queries, string.Join(' ', terms));

        return queries
            .Where(static q => !string.IsNullOrWhiteSpace(q))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToArray();
    }

    private static int ResolveComparativeRetrievalQueryLimit(string? query)
        => CountExplicitDocumentFileReferences(query ?? string.Empty) > 1 ? 3 : 8;

    private static IEnumerable<string> BuildRetrievalTermVariants(string term)
    {
        var normalized = NormalizeLexicalLookup(term);
        if (string.IsNullOrWhiteSpace(normalized))
            yield break;

        yield return normalized;

        foreach (var variant in BuildGenericRetrievalSemanticVariants(normalized))
            yield return variant;

        if (normalized.Length > 5 && normalized.EndsWith("es", StringComparison.Ordinal))
            yield return normalized[..^2];
        if (normalized.Length > 4 && normalized.EndsWith("s", StringComparison.Ordinal))
            yield return normalized[..^1];
    }

    private static IEnumerable<string> BuildGenericRetrievalSemanticQueries(string query)
    {
        var normalizedQuery = NormalizeLexicalLookup(query);
        var terms = ExtractQuerySignalTerms(normalizedQuery)
            .SelectMany(BuildRetrievalTermVariants)
            .ToHashSet(StringComparer.Ordinal);
        if (terms.Count == 0)
            yield break;

        var hasProperty = terms.Contains("propriete")
            || terms.Contains("proprietes")
            || terms.Contains("property")
            || terms.Contains("properties");
        var hasElectrical = terms.Contains("electrique")
            || terms.Contains("electriques")
            || terms.Contains("electric")
            || terms.Contains("electrical")
            || terms.Contains("dielectric");
        var hasThermal = terms.Contains("thermique")
            || terms.Contains("thermiques")
            || terms.Contains("thermal")
            || terms.Contains("temperature")
            || terms.Contains("melt point")
            || terms.Contains("melting point");
        var hasSafetyDataSheet = LooksLikeSafetyDataSheetDocumentTypeRequest(query);
        var hasHistoricalVersion = ContainsHistoricalDocumentVersionSurface(normalizedQuery);
        var hasCurrentVersion = ContainsCurrentDocumentVersionSurface(normalizedQuery);
        var hasVersionSurface = Regex.IsMatch(
            normalizedQuery,
            @"\b(?:version|versions|edition|editions|document|documents|file|fichier|pdf)\b",
            RegexOptions.CultureInvariant);
        var subjectTerms = Regex.Matches(normalizedQuery, @"[\p{L}\p{N}]{3,}", RegexOptions.CultureInvariant)
            .Select(static match => match.Value)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !IsGenericDocumentVersionOrTypeRetrievalTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(4)
            .ToArray();
        var subjectPrefix = subjectTerms.Length == 0 ? string.Empty : string.Join(' ', subjectTerms) + " ";

        if (hasElectrical)
        {
            yield return hasProperty ? "electrical properties" : "electrical";
            yield return "dielectric properties";
        }

        if (hasThermal)
        {
            yield return hasProperty ? "thermal properties" : "thermal";
            yield return "melt point temperature";
        }

        if (hasSafetyDataSheet)
        {
            yield return $"{subjectPrefix}safety data sheet";
            yield return $"{subjectPrefix}material safety data sheet";
            yield return $"{subjectPrefix}msds";
            yield return $"{subjectPrefix}sds";
            yield return $"{subjectPrefix}fiche de donnees de securite";
        }

        if (hasHistoricalVersion && (hasVersionSurface || hasCurrentVersion))
        {
            yield return $"{subjectPrefix}old version";
            yield return $"{subjectPrefix}previous version";
            yield return $"{subjectPrefix}archived version";
            yield return $"{subjectPrefix}ancienne version";
        }

        if (hasCurrentVersion && (hasVersionSurface || hasHistoricalVersion))
        {
            yield return $"{subjectPrefix}current version";
            yield return $"{subjectPrefix}latest version";
            yield return $"{subjectPrefix}version courante";
            yield return $"{subjectPrefix}derniere version";
        }
    }

    private static IEnumerable<string> BuildGenericRetrievalSemanticVariants(string term)
    {
        switch (term)
        {
            case "propriete":
            case "proprietes":
            case "caracteristique":
            case "caracteristiques":
                yield return "property";
                yield return "properties";
                yield return "characteristic";
                yield return "characteristics";
                break;

            case "electrique":
            case "electriques":
            case "electric":
            case "electrical":
                yield return "electric";
                yield return "electrical";
                yield return "dielectric";
                break;

            case "thermique":
            case "thermiques":
            case "thermal":
                yield return "thermal";
                yield return "temperature";
                yield return "melt point";
                yield return "melting point";
                break;

            case "msds":
            case "sds":
            case "fds":
                yield return "msds";
                yield return "sds";
                yield return "safety data sheet";
                yield return "material safety data sheet";
                yield return "fiche de donnees de securite";
                break;

            case "ancienne":
            case "ancien":
            case "precedente":
            case "precedent":
            case "anterieure":
            case "anterieur":
            case "older":
            case "previous":
            case "prior":
            case "archived":
            case "archive":
            case "legacy":
            case "obsolete":
                yield return "ancienne version";
                yield return "old version";
                yield return "previous version";
                yield return "archived version";
                break;

            case "actuelle":
            case "actuel":
            case "courante":
            case "courant":
            case "derniere":
            case "nouvelle":
            case "nouveau":
            case "current":
            case "latest":
            case "newest":
            case "recent":
                yield return "version courante";
                yield return "current version";
                yield return "latest version";
                yield return "derniere version";
                break;
        }
    }

    private static bool IsGenericDocumentVersionOrTypeRetrievalTerm(string term)
        => Regex.IsMatch(
            NormalizeLexicalLookup(term),
            @"^(?:and|the|for|backed|compare|comparing|comparaison|comparison|version|versions|edition|editions|document|documents|file|fichier|pdf|old|older|previous|prior|archived|archive|legacy|obsolete|ancienne|ancien|precedente|precedent|anterieure|anterieur|current|latest|newest|recent|actuelle|actuel|courante|courant|derniere|nouvelle|nouveau|safety|securite|data|sheet|fiche|fiches|donnees|msds|sds|fds)$",
            RegexOptions.CultureInvariant);

    private static bool LooksLikeSafetyDataSheetDocumentTypeRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
                   normalized,
                   @"\b(?:msds|sds|fds|material\s+safety\s+data\s+sheets?|safety\s+data\s+sheets?|fiches?\s+de\s+donnees\s+de\s+securite|fiches?\s+donnees\s+securite|fiches?\s+de\s+securite)\b",
                   RegexOptions.CultureInvariant)
               || (Regex.IsMatch(normalized, @"\b(?:safety|securite)\b", RegexOptions.CultureInvariant)
                   && Regex.IsMatch(normalized, @"\b(?:data\s+sheets?|fiches?|donnees)\b", RegexOptions.CultureInvariant));
    }

    private static bool ContainsHistoricalDocumentVersionSurface(string? normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            return false;

        return Regex.IsMatch(
            normalizedQuery,
            @"\b(?:ancien(?:ne)?s?|precedent(?:e)?s?|anterieur(?:e)?s?|old|older|previous|prior|archived|archive|archives|historical|legacy|obsolete)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool ContainsCurrentDocumentVersionSurface(string? normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            return false;

        return Regex.IsMatch(
            normalizedQuery,
            @"\b(?:actuel(?:le)?s?|courant(?:e)?s?|derniere?s?|nouveau|nouvelle?s?|current|latest|newest|recent|newer)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool HistoricalDocumentVersionSurfaceIsNegated(string? normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            return false;

        return Regex.IsMatch(
            normalizedQuery,
            @"\b(?:pas|not|never|eviter|evite|avoid|sans|without)\b.{0,80}\b(?:ancienne?s?\s+versions?|old\s+versions?|older\s+versions?|previous\s+versions?|archived\s+versions?)\b|\b(?:ancienne?s?\s+versions?|old\s+versions?|older\s+versions?|previous\s+versions?|archived\s+versions?)\b.{0,80}\b(?:pas|not|never|eviter|evite|avoid|sans|without)\b",
            RegexOptions.CultureInvariant);
    }

    private static int ComputeRequestedDocumentTypeAnchorScore(string? query, RagHitSummary hit)
    {
        if (!LooksLikeSafetyDataSheetDocumentTypeRequest(query))
            return 0;

        var titleSignal = NormalizeLexicalLookup(string.Join(' ', new[]
        {
            hit.DocName,
            hit.DocPath,
            hit.SectionTitle,
            hit.HeadingPath,
            string.Join(' ', hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>())
        }.Where(static value => !string.IsNullOrWhiteSpace(value))));
        if (string.IsNullOrWhiteSpace(titleSignal))
            return 0;

        if (Regex.IsMatch(titleSignal, @"\b(?:msds|sds|fds)\b", RegexOptions.CultureInvariant))
            return 160;
        if (Regex.IsMatch(
                titleSignal,
                @"\b(?:material\s+safety\s+data\s+sheets?|safety\s+data\s+sheets?|fiches?\s+de\s+donnees\s+de\s+securite|fiches?\s+donnees\s+securite|fiches?\s+de\s+securite)\b",
                RegexOptions.CultureInvariant))
        {
            return 140;
        }

        return 0;
    }

    private static IEnumerable<string> BuildSoftChoiceOptionKindRetrievalQueries(string? query)
    {
        if (!LooksLikeSoftChoiceRecommendationRequest(query)
            && !LooksLikeSourceBackedOptionRequest(query))
            yield break;

        var emitted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var kind in ExtractSoftChoiceRequestedOptionKindTerms(query)
                     .Concat(ExtractGenericSourceBackedOptionKindTerms(query))
                     .SelectMany(BuildRetrievalTermVariants)
                     .Where(static term => term.Length >= 4)
                     .Distinct(StringComparer.Ordinal)
                     .Take(8))
        {
            if (emitted.Add(kind))
                yield return kind;
        }

        if (!LooksLikeSoftChoiceRecommendationRequest(query))
            yield break;

        var raw = CollapseWhitespace(query ?? string.Empty);
        foreach (Match match in Regex.Matches(
                     raw,
                     @"(?i)\b(?:quel|quelle|quels|quelles|which|what|cual|cu[aá]l|qual|welche|welcher|welches|quale)\s+(?<kind>[\p{L}'\u2019-]{3,30})(?:\s+(?<qualifier>[\p{L}'\u2019-]{3,30}))?",
                     RegexOptions.CultureInvariant))
        {
            var kind = CollapseWhitespace(match.Groups["kind"].Value);
            if (string.IsNullOrWhiteSpace(kind) || IsSourceBackedActionRetrievalNoiseTerm(kind))
                continue;

            var qualifier = CollapseWhitespace(match.Groups["qualifier"].Value);
            if (!string.IsNullOrWhiteSpace(qualifier)
                && !IsSourceBackedActionRetrievalNoiseTerm(qualifier)
                && !Regex.IsMatch(NormalizeLexicalLookup(qualifier), @"\b(?:choisir|choix|choose|select|recommend|suggest|propose)\b", RegexOptions.CultureInvariant))
            {
                var qualifiedKind = $"{kind} {qualifier}";
                if (emitted.Add(qualifiedKind))
                    yield return qualifiedKind;
            }

            if (emitted.Add(kind))
                yield return kind;
        }
    }

    private static IEnumerable<string> BuildTypoTolerantQueryVariants(string? query)
    {
        var normalized = CollapseWhitespace(query ?? string.Empty);
        if (string.IsNullOrWhiteSpace(normalized))
            yield break;

        var variants = new List<string>();
        void Add(string value)
        {
            value = CollapseWhitespace(value);
            if (string.IsNullOrWhiteSpace(value))
                return;
            if (string.Equals(value, normalized, StringComparison.OrdinalIgnoreCase))
                return;
            if (!variants.Any(x => string.Equals(x, value, StringComparison.OrdinalIgnoreCase)))
                variants.Add(value);
        }

        Add(Regex.Replace(normalized, @"(?i)ngn", "gn", RegexOptions.CultureInvariant));
        Add(Regex.Replace(normalized, @"(?i)\b([\p{L}]{3,})tt([\p{L}]{2,})\b", "$1t$2", RegexOptions.CultureInvariant));
        Add(Regex.Replace(normalized, @"(?i)ze\b", "se", RegexOptions.CultureInvariant));

        foreach (var variant in variants.Take(3))
            yield return variant;
    }

    private static bool IsSourceBackedActionRetrievalNoiseTerm(string term)
    {
        var normalized = NormalizeLexicalLookup(term);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        var stopWords = new HashSet<string>(StringComparer.Ordinal)
        {
            "adaptation", "adaptations", "adapte", "adapter", "adaptee", "adaptees", "bien", "cela",
            "cette", "comment", "como", "dans", "document", "documents", "extrait", "extraits", "faire", "how", "peux",
            "pdf", "source", "sources", "vient", "viennent", "what", "which", "source", "sources",
            "document", "documents", "adapt", "adapted", "derived", "please", "from", "retrouve", "retrouver", "retrouves",
            "choisir", "choix", "choose", "select", "selection", "option", "options", "recommend", "recommends", "recommendation",
            "recommande", "recommander", "conseille", "conseiller", "suggest", "suggestion", "suggestions",
            "orienter", "orientation", "utilisateur", "user", "users", "demande",
            "demandes", "demander", "asked", "asks", "question", "questions", "client", "customer", "customers",
            "prepare", "preparer", "repond", "reponds", "repondez", "reponse", "answer", "answers",
            "respond", "responds", "reply", "replies", "backed", "grounded", "sourced", "sourcee", "sourcees",
            "explique", "expliquer", "expliquez", "explained", "explain", "explains", "explica", "explicar",
            "erklaere", "erklaren", "erklaert", "spiega", "spiegare", "partir", "part", "available",
            "disponible", "disponibles", "utile", "utiles", "useful", "plusieurs", "multiple", "multiples",
            "several", "many", "organiser", "organize", "organise"
        };

        return stopWords.Contains(normalized);
    }

    private static bool LooksLikeComparativeDocumentaryRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var hasComparativeOperator = Regex.IsMatch(
                normalized,
                @"\b(?:compare|comparer|comparaison|comparatif|comparative|difference|differences|different|differents|differentes|versus|compara|comparar|comparacion|comparacao|vergleiche|vergleichen|vergleich|confronta|confrontare|confronto|paragona|paragonare)\b",
                RegexOptions.CultureInvariant);
        var hasRankingOperator = Regex.IsMatch(
                normalized,
                @"\b(?:quel|quelle|quels|quelles|which|what|cual|cuál|qual|welche|welcher|welches|quale)\b.{0,120}\b(?:plus|moins|meilleur|meilleure|meilleurs|meilleures|pire|pires|most|least|best|worst|mas|mais|menos|mejor|melhor|beste|bester|bestes|peggiore|migliore)\b|\b(?:le|la|les|the|el|los|las|o|a|os|as|der|die|das|il|lo|gli)\s+(?:plus|moins|meilleur|meilleure|meilleurs|meilleures|pire|pires|most|least|best|worst|mas|mais|menos|mejor|melhor|beste|bester|bestes|peggiore|migliore)\b",
                RegexOptions.CultureInvariant);

        if (!hasComparativeOperator && !hasRankingOperator)
            return false;

        return BuildComparativeRetrievalQueries(query ?? string.Empty).Length > 1
            || ExtractQuerySignalTerms(normalized).Any();
    }

    private static string[] BuildComparativeRetrievalQueries(string query)
    {
        var normalized = NormalizeRagQueryForRetrieval(query);
        if (string.IsNullOrWhiteSpace(normalized))
            normalized = CollapseWhitespace(query);

        var raw = CollapseWhitespace(query);
        var queries = new List<string>();
        var explicitFileReferences = ExtractExplicitDocumentFileReferenceQueries(raw).Take(4).ToArray();
        foreach (var fileReference in explicitFileReferences)
            AddDistinctQuery(queries, fileReference);

        var focus = TryBuildComparativeFocusQuery(normalized);
        AddDistinctQuery(queries, focus);
        if (explicitFileReferences.Length <= 1)
        {
            foreach (var fileReference in explicitFileReferences)
                AddDistinctQuery(queries, QuoteLookupTitle(fileReference));
        }
        AddDistinctQuery(queries, normalized);
        if (!string.IsNullOrWhiteSpace(raw) && !string.Equals(raw, normalized, StringComparison.OrdinalIgnoreCase))
            AddDistinctQuery(queries, raw);

        if (!string.IsNullOrWhiteSpace(focus))
        {
            AddDistinctQuery(queries, $"{focus} details");
            AddDistinctQuery(queries, $"{focus} procedure");
        }

        var signalTerms = ExtractQuerySignalTerms(NormalizeLexicalLookup(normalized))
            .Where(term => !IsComparativeRetrievalNoiseTerm(term))
            .Take(5)
            .ToArray();
        if (signalTerms.Length > 0)
            AddDistinctQuery(queries, string.Join(' ', signalTerms));

        return queries
            .Where(static q => !string.IsNullOrWhiteSpace(q))
            .Select(CollapseWhitespace)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(ResolveComparativeRetrievalQueryLimit(query))
            .ToArray();
    }

    private static string NormalizeComparativeSupplementalRetrievalQuery(string? query, string comparativeQuery)
    {
        var normalized = NormalizeRagQueryForRetrieval(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return string.Empty;

        var focus = TryBuildComparativeFocusQuery(comparativeQuery);
        if (string.IsNullOrWhiteSpace(focus))
            return normalized;

        var normalizedQuery = NormalizeLexicalLookup(normalized);
        var focusTerms = ExtractQuerySignalTerms(NormalizeLexicalLookup(focus))
            .Where(term => !IsComparativeRetrievalNoiseTerm(term))
            .ToArray();
        if (focusTerms.Length == 0 || focusTerms.Any(term => normalizedQuery.Contains(term, StringComparison.Ordinal)))
            return normalized;

        var supplementalTerms = ExtractQuerySignalTerms(normalizedQuery)
            .Where(term => !IsComparativeRetrievalNoiseTerm(term))
            .ToArray();
        if (supplementalTerms.Length == 0)
            return CollapseWhitespace($"{focus} {normalized}");

        return CollapseWhitespace($"{focus} {normalized}");
    }

    private static string? TryBuildComparativeFocusQuery(string query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return null;

        var candidate = normalized;
        var afterCompareVerb = Regex.Match(
            candidate,
            @"\b(?:compare|comparer|comparaison|comparatif|comparative|difference|differences|different|differents|differentes|versus|compara|comparar|comparacion|comparacao|vergleiche|vergleichen|vergleich|confronta|confrontare|confronto|paragona|paragonare)\b\s+(?<rest>.+)$",
            RegexOptions.CultureInvariant);
        if (afterCompareVerb.Success)
            candidate = afterCompareVerb.Groups["rest"].Value;

        var explicitTopic = Regex.Match(
            candidate,
            @"\b(?:sujet\s+suivant|theme\s+suivant|following\s+topic|following\s+subject|tema\s+siguiente|tema\s+seguinte|seguinte\s+tema|folgendes\s+thema|argomento\s+seguente)\b\s*:?\s*(?<topic>.+)$",
            RegexOptions.CultureInvariant);
        if (explicitTopic.Success)
            candidate = explicitTopic.Groups["topic"].Value;

        candidate = Regex.Split(
                candidate,
                @"\b(?:et|and|y|e|und)\s+(?:celle|celui|celles|ceux|celui-ci|celle-ci|celui-la|celle-la|the\s+one|that|quella|quello|quellas|quellos|diese|dieser|dieses)\b",
                RegexOptions.CultureInvariant)
            .FirstOrDefault()
            ?? candidate;

        var terms = Regex.Matches(candidate, @"[\p{L}\p{N}]{2,}", RegexOptions.CultureInvariant)
            .Select(match => match.Value)
            .Where(term => term.Length >= 3 || term.Any(char.IsDigit))
            .Where(term => !(term.All(char.IsDigit) && term.Length <= 3))
            .Where(term => !IsComparativeRetrievalNoiseTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(5)
            .ToArray();

        if (terms.Length == 0)
            return null;

        return string.Join(' ', terms);
    }

    private static void AddDistinctQuery(List<string> queries, string? query)
    {
        var value = CollapseWhitespace(query ?? string.Empty);
        if (string.IsNullOrWhiteSpace(value))
            return;

        if (!queries.Any(existing => string.Equals(existing, value, StringComparison.OrdinalIgnoreCase)))
            queries.Add(value);
    }

