    }

    private static string BuildSourceBackedPlanningAnswer(ToolResults toolResults, string language, int minItems = 1, string? query = null)
    {
        language = NormalizeLanguageCode(language);
        var targetItemCount = ResolveSourceBackedPlanningTargetItemCount(query);
        var wantsWeeklyPlan = LooksLikeWeeklyPlanningRequest(query);
        var wantsVerificationChecklist = LooksLikeSourceBackedVerificationChecklistRequest(query);
        var planItems = SelectSourceBackedPlanningCandidates(toolResults, query, targetItemCount, language)
            .ToList();

        if (planItems.Count == 0 || planItems.Count < minItems)
            return string.Empty;

        var requestedDayLabels = DetectRequestedDayAxisLabels(query, language);
        var requestedPeriodLabels = DetectRequestedPeriodAxisLabels(query, language);
        if (!wantsVerificationChecklist && requestedDayLabels.Count > 0 && requestedPeriodLabels.Count > 0)
        {
            return BuildStructuredSourceBackedPlanAnswer(
                planItems,
                requestedDayLabels,
                requestedPeriodLabels,
                language,
                query);
        }

        var header = wantsVerificationChecklist
            ? language switch
        {
            "en" => "Here are the source-backed checks to perform. I only list points supported by retrieved excerpts:",
            "es" => "Estas son las verificaciones respaldadas por fuente. Solo incluyo puntos sustentados por extractos recuperados:",
            "pt" => "Aqui estao as verificacoes com fonte. Incluo apenas pontos sustentados por excertos recuperados:",
            "de" => "Hier sind die quellenbasierten Pruefpunkte. Ich nenne nur Punkte aus den gefundenen Auszuegen:",
            "it" => "Ecco i controlli supportati da fonti. Includo solo punti sostenuti dagli estratti recuperati:",
            _ => "Voici les vérifications appuyées sur les documents disponibles. Je liste uniquement des points soutenus par les extraits retrouvés :"
        }
            : language switch
        {
            "en" => "Here is a source-backed plan from the available documents. I only list items found in the excerpts:",
            "es" => "Aqui tienes una propuesta basada en los documentos disponibles. Solo incluyo elementos encontrados en los extractos:",
            "pt" => "Aqui esta uma proposta baseada nos documentos disponiveis. Incluo apenas itens encontrados nos excertos:",
            "de" => "Hier ist ein quellenbasierter Plan aus den verfuegbaren Dokumenten. Ich nenne nur Elemente aus den Auszuegen:",
            "it" => "Ecco una proposta basata sui documenti disponibili. Includo solo elementi trovati negli estratti:",
            _ => "Voici une proposition appuyée sur les documents disponibles. Je liste uniquement des éléments retrouvés dans les extraits :"
        };

        var sb = new StringBuilder();
        sb.AppendLine(header);
        if (wantsWeeklyPlan && planItems.Count < targetItemCount)
        {
            var coverageNote = language switch
            {
                "en" => "The available sources do not cover the whole requested plan yet. I keep only the usable sourced items, without inventing the missing places.",
                "es" => "Las fuentes disponibles aun no cubren todo el plan solicitado. Mantengo solo los elementos utilizables con fuente, sin inventar los huecos que faltan.",
                "pt" => "As fontes disponiveis ainda nao cobrem todo o plano pedido. Mantenho apenas os itens utilizaveis com fonte, sem inventar os espacos em falta.",
                "de" => "Die verfuegbaren Quellen decken den angefragten Plan noch nicht vollstaendig ab. Ich nutze nur die belegten nutzbaren Elemente, ohne fehlende Plaetze zu erfinden.",
                "it" => "Le fonti disponibili non coprono ancora tutto il piano richiesto. Mantengo solo gli elementi utilizzabili con fonte, senza inventare gli spazi mancanti.",
                _ => "Les sources disponibles ne couvrent pas encore tout le planning demandé. Je garde uniquement les éléments réellement trouvés, sans inventer les créneaux manquants."
            };
            sb.AppendLine(coverageNote);
        }

        var useDayLabels = wantsWeeklyPlan && planItems.Count >= targetItemCount;
        for (var i = 0; i < planItems.Count; i++)
        {
            var label = wantsVerificationChecklist
                ? language switch
            {
                "en" => $"Check {i + 1}",
                "es" => $"Verificacion {i + 1}",
                "pt" => $"Verificacao {i + 1}",
                "de" => $"Pruefpunkt {i + 1}",
                "it" => $"Controllo {i + 1}",
                _ => $"Vérification {i + 1}"
            }
                : useDayLabels
                ? language switch
            {
                "en" => $"Day {i + 1}",
                "es" => $"Dia {i + 1}",
                "pt" => $"Dia {i + 1}",
                "de" => $"Tag {i + 1}",
                "it" => $"Giorno {i + 1}",
                _ => $"Jour {i + 1}"
            }
                : language switch
            {
                "es" => $"Opcion {i + 1}",
                "pt" => $"Opcao {i + 1}",
                "it" => $"Opzione {i + 1}",
                _ => $"Option {i + 1}"
            };

            var hit = planItems[i].Hit;
            sb.Append("- ");
            sb.Append(label);
            sb.Append(" : ");
            sb.Append(planItems[i].Title);
            sb.Append(" (");
            sb.Append(string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(")");
            sb.AppendLine();
        }

        var note = wantsVerificationChecklist
            ? language switch
        {
            "en" => "Note: treat this as a source-backed checklist, then validate exceptions, approvals and legal/compliance impact with the responsible humans before acting.",
            "es" => "Nota: tratalo como una lista de control con fuente y valida excepciones, aprobaciones e impacto legal/conformidad con las personas responsables antes de actuar.",
            "pt" => "Nota: trata isto como uma checklist com fonte e valida excecoes, aprovacoes e impacto legal/conformidade com as pessoas responsaveis antes de agir.",
            "de" => "Hinweis: Nutze dies als quellenbasierte Checkliste und pruefe Ausnahmen, Freigaben sowie rechtliche/Compliance-Auswirkungen mit den Verantwortlichen vor Umsetzung.",
            "it" => "Nota: trattala come checklist con fonte e valida eccezioni, approvazioni e impatti legali/compliance con i responsabili prima di agire.",
            _ => "Note : traite ceci comme une checklist sourcée, puis valide les exceptions, approbations et impacts juridiques/conformité avec les responsables avant d'agir."
        }
            : language switch
        {
            "en" => "Note: adapt quantities, timing, and constraints from the source pages before acting.",
            "es" => "Nota: adapta cantidades, tiempos y restricciones a partir de las paginas fuente antes de actuar.",
            "pt" => "Nota: adapta quantidades, tempos e restricoes a partir das paginas fonte antes de agir.",
            "de" => "Hinweis: Mengen, Zeiten und Einschraenkungen vor der Umsetzung anhand der Quellseiten anpassen.",
            "it" => "Nota: adatta quantita, tempi e vincoli dalle pagine fonte prima di agire.",
            _ => "Note : adapte les quantités, délais et contraintes à partir des pages source avant d'agir."
        };
        sb.AppendLine(note);

        var answer = sb.ToString().TrimEnd();
        return wantsWeeklyPlan && planItems.Count < targetItemCount
            ? AppendBroadenedSearchOfferIfHelpful(answer, query, language)
            : answer;
    }

    private static string BuildStructuredSourceBackedPlanAnswer(
        IReadOnlyList<SourceBackedOptionCandidate> planItems,
        IReadOnlyList<string> dayLabels,
        IReadOnlyList<string> periodLabels,
        string language,
        string? query)
    {
        if (planItems.Count == 0 || dayLabels.Count == 0 || periodLabels.Count == 0)
            return string.Empty;

        language = NormalizeLanguageCode(language);
        var requiredSlots = dayLabels.Count * periodLabels.Count;
        var hasPartialCandidateBank = planItems.Count < requiredSlots;
        var labels = language switch
        {
            "en" => (
                Header: "Here is a structured proposal based on the sourced elements available.",
                Partial: $"The documented base is still too small to fill the whole requested structure without repetition: {planItems.Count} usable elements for {requiredSlots} requested places. I use it as a starting point to validate rather than inventing missing items.",
                Complete: "The organization below is proposed by the assistant; each concrete item remains tied to a cited source.",
                Verify: "Before using it as a final plan, check the cited pages for quantities, timing, constraints and substitutions."),
            "es" => (
                Header: "Aqui tienes una propuesta estructurada basada en los elementos con fuente disponibles.",
                Partial: $"La base con fuente aun es demasiado pequena para cubrir toda la estructura solicitada sin repetir ({planItems.Count} elemento(s) util(es) para {requiredSlots} espacio(s)). La uso como punto de partida a validar, sin inventar elementos faltantes.",
                Complete: "La organizacion siguiente es una propuesta del asistente; cada elemento concreto sigue ligado a una fuente citada.",
                Verify: "Antes de usarlo como plan final, revisa las paginas citadas para cantidades, horarios, restricciones y sustituciones."),
            "pt" => (
                Header: "Aqui esta uma proposta estruturada baseada nos elementos com fonte disponiveis.",
                Partial: $"A base com fonte ainda e curta demais para cobrir toda a estrutura pedida sem repeticao ({planItems.Count} item(ns) util(eis) para {requiredSlots} espaco(s)). Uso-a como ponto de partida a validar, sem inventar elementos em falta.",
                Complete: "A organizacao abaixo e uma proposta do assistente; cada item concreto continua ligado a uma fonte citada.",
                Verify: "Antes de usar isto como plano final, verifica as paginas citadas para quantidades, horarios, restricoes e substituicoes."),
            "de" => (
                Header: "Hier ist ein strukturierter Vorschlag auf Basis der verfuegbaren belegten Elemente.",
                Partial: $"Die belegte Grundlage ist noch zu klein, um die ganze angefragte Struktur ohne Wiederholung zu fuellen ({planItems.Count} nutzbare Elemente fuer {requiredSlots} Plaetze). Ich nutze sie als zu pruefenden Ausgangspunkt, statt fehlende Punkte zu erfinden.",
                Complete: "Die folgende Organisation ist ein Vorschlag des Assistenten; jeder konkrete Punkt bleibt mit einer Quelle verbunden.",
                Verify: "Pruefe vor der finalen Nutzung die zitierten Seiten zu Mengen, Zeiten, Einschraenkungen und Alternativen."),
            "it" => (
                Header: "Ecco una proposta strutturata basata sugli elementi con fonte disponibili.",
                Partial: $"La base con fonte e ancora troppo piccola per coprire tutta la struttura richiesta senza ripetizioni ({planItems.Count} elemento/i utile/i per {requiredSlots} spazio/i). La uso come punto di partenza da validare, senza inventare elementi mancanti.",
                Complete: "L'organizzazione seguente e una proposta dell'assistente; ogni elemento concreto resta collegato a una fonte citata.",
                Verify: "Prima di usarlo come piano finale, controlla le pagine citate per quantita, tempi, vincoli e sostituzioni."),
            _ => (
                Header: "Voici une proposition structurée à partir des éléments sourcés disponibles.",
                Partial: $"La base documentée reste trop courte pour remplir toute la structure demandée sans répétitions : {planItems.Count} élément(s) exploitable(s) pour {requiredSlots} emplacements demandés. Je l'utilise comme point de départ à valider, plutôt que d'inventer les éléments manquants.",
                Complete: "L'organisation ci-dessous est proposée par l'assistant ; chaque élément concret reste relié à une source citée.",
                Verify: "Avant d'en faire un planning définitif, vérifie les pages citées pour les quantités, horaires, contraintes et remplacements.")
        };

        if (hasPartialCandidateBank
            && !HasEnoughSourceBackedCandidatesForStructuredPlan(planItems, requiredSlots))
        {
            return BuildStructuredSourceBackedCandidateBankAnswer(planItems, requiredSlots, language, query);
        }

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(hasPartialCandidateBank ? labels.Partial : labels.Complete);

        var slotIndex = 0;
        foreach (var day in dayLabels)
        {
            sb.AppendLine();
            sb.AppendLine($"{day} :");
            foreach (var period in periodLabels)
            {
                var candidate = planItems[slotIndex % planItems.Count];
                sb.Append("  - ");
                sb.Append(period);
                sb.Append(" : ");
                sb.Append(candidate.Title);
                sb.Append(" (");
                sb.Append(FormatSourceBackedCandidateReference(candidate, language));
                sb.AppendLine(").");
                slotIndex++;
            }
        }

        sb.AppendLine();
        sb.Append(labels.Verify);
        return hasPartialCandidateBank
            ? AppendBroadenedSearchOfferIfHelpful(sb.ToString(), query, language)
            : sb.ToString().TrimEnd();
    }

    private static bool HasEnoughSourceBackedCandidatesForStructuredPlan(
        IReadOnlyList<SourceBackedOptionCandidate> planItems,
        int requiredSlots)
    {
        var minimumCandidates = Math.Min(requiredSlots, Math.Max(4, (int)Math.Ceiling(requiredSlots * 0.45)));
        if (planItems.Count < minimumCandidates)
            return false;

        var distinctSourcePages = planItems
            .Select(static candidate => BuildRagHitVisiblePageMergeKey(candidate.Hit))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
        return distinctSourcePages >= Math.Min(3, minimumCandidates);
    }

    private static string BuildStructuredSourceBackedCandidateBankAnswer(
        IReadOnlyList<SourceBackedOptionCandidate> planItems,
        int requiredSlots,
        string language,
        string? query)
    {
        language = NormalizeLanguageCode(language);
        var labels = language switch
        {
            "en" => (
                Header: "The sources provide a few usable items, but not enough to fill the whole requested structure without repeating too much.",
                Intro: "Usable starting options:",
                Next: "To build a complete and varied plan, broaden the search or add more document-backed items before filling every place."),
            "es" => (
                Header: "Las fuentes ofrecen algunos elementos utilizables, pero no bastan para completar toda la estructura solicitada sin repetir demasiado.",
                Intro: "Opciones de partida utilizables:",
                Next: "Para construir un plan completo y variado, amplia la busqueda o anade mas elementos respaldados por documentos antes de llenar todos los huecos."),
            "pt" => (
                Header: "As fontes oferecem alguns itens utilizaveis, mas nao chegam para completar toda a estrutura pedida sem repetir demasiado.",
                Intro: "Opcoes iniciais utilizaveis:",
                Next: "Para criar um plano completo e variado, alarga a pesquisa ou adiciona mais itens apoiados pelos documentos antes de preencher todos os horarios."),
            "de" => (
                Header: "Die Quellen liefern einige nutzbare Elemente, aber nicht genug, um die ganze angefragte Struktur ohne zu viele Wiederholungen zu fuellen.",
                Intro: "Nutzbare Startoptionen:",
                Next: "Fuer einen vollstaendigen und abwechslungsreichen Plan sollte die Suche erweitert oder weitere belegte Elemente ergaenzt werden."),
            "it" => (
                Header: "Le fonti offrono alcuni elementi utilizzabili, ma non bastano per completare tutta la struttura richiesta senza troppe ripetizioni.",
                Intro: "Opzioni iniziali utilizzabili:",
                Next: "Per costruire un piano completo e vario, amplia la ricerca o aggiungi altri elementi supportati dai documenti prima di riempire tutti gli spazi."),
            _ => (
                Header: "Les sources donnent quelques éléments exploitables, mais pas assez pour remplir toute la structure demandée sans trop répéter.",
                Intro: "Options utilisables pour démarrer :",
                Next: "Pour obtenir un planning complet et varié, il faut élargir la recherche ou ajouter d'autres éléments appuyés par les documents avant de remplir tous les créneaux.")
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(labels.Intro);
        for (var i = 0; i < Math.Min(8, planItems.Count); i++)
        {
            var candidate = planItems[i];
            sb.Append("- ");
            sb.Append(candidate.Title);
            sb.Append(" (");
            sb.Append(FormatSourceBackedCandidateReference(candidate, language));
            sb.AppendLine(").");
        }

        sb.Append(labels.Next);
        return AppendBroadenedSearchOfferIfHelpful(sb.ToString(), query, language);
    }

    private static string FormatSourceBackedCandidateReference(SourceBackedOptionCandidate candidate, string language)
    {
        var hit = candidate.Hit;
        var source = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
        if (string.IsNullOrWhiteSpace(source))
            source = "source";

        return $"{source} {SourceBackedPagePrefix(language)}{Math.Max(1, hit.PageStart)}";
    }

    private static bool ShouldUseWriterForBroadSourceBackedPlanning(ToolResults toolResults, string? query, string language = "fr")
        => !string.IsNullOrWhiteSpace(query)
           && !LooksLikeSourceBackedCountdownPlanningRequest(query)
           && !LooksLikeSourceBackedVerificationChecklistRequest(query)
           && !LooksLikeSourceBackedPairingRecommendationRequest(query)
           && LooksLikeAnyDocumentaryPlanningRequest(query)
           && EvaluateSourceBackedPlanningCoverage(toolResults, query, language).IsAdequate;

    private static bool ShouldPreferWriterForPolishedSourceBackedAnswer(ToolResults toolResults, string? query)
    {
        if (string.IsNullOrWhiteSpace(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query)
            || LooksLikeStrictCertificationOrExactProofRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query)
            || LooksLikeExactPassageOrCitationRequest(query)
            || !toolResults.Items.Any(static item => item.ToolName is "rag.search" or "rag.multi_search" && HasRagHits(item.Result)))
        {
            return false;
        }

        return LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeBroadSynthesisRequestShape(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSourceBackedOptionRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeUserNeedsSynthesizedDecisionOrPlan(query)
            || LooksLikeSourceBackedActionRequest(query)
            || LooksLikeDocumentaryContentRequest(query)
            || ShouldUseSourceBackedExtractiveAnswer(query, toolResults);
    }

    private static bool ShouldAllowWriterForPartialSourceBackedPlanning(ToolResults toolResults, string? query, string language = "fr")
    {
        if (string.IsNullOrWhiteSpace(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeStrictCertificationOrExactProofRequest(query)
            || !LooksLikeAnyDocumentaryPlanningRequest(query))
        {
            return false;
        }

        var coverage = EvaluateSourceBackedPlanningCoverage(toolResults, query, language);
        if (coverage.CandidateCount <= 0 || coverage.DistinctSourcePages <= 0)
            return false;

        if (coverage.IsAdequate)
            return true;

        if (RequiresStructuredSourceBackedPlanningCoverage(query))
        {
            var enoughPartialMaterialForWriter =
                coverage.CandidateCount >= Math.Min(4, Math.Max(3, coverage.MinimumCandidates - 2))
                && coverage.DistinctSourcePages >= 2
                && coverage.HasRequiredAnchor;
            return enoughPartialMaterialForWriter;
        }

        var hasExplicitStructure = DetectRequestedDayAxisLabels(query, language).Count > 0
            || DetectRequestedPeriodAxisLabels(query, language).Count > 0;
        var asksForSynthesis = LooksLikeUserNeedsSynthesizedDecisionOrPlan(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query);

        return hasExplicitStructure
            || asksForSynthesis
            || coverage.CandidateCount >= Math.Min(2, coverage.MinimumCandidates);
    }

    private static bool ShouldExpandSourceBackedPlanningRetrieval(ToolResults toolResults, string? query, string language)
    {
        if (!LooksLikeAnyDocumentaryPlanningRequest(query))
            return false;

        var coverage = EvaluateSourceBackedPlanningCoverage(toolResults, query, language);
        return !coverage.IsAdequate;
    }

    private static bool IsBetterSourceBackedPlanningCoverage(
        ToolResults current,
        ToolResults candidate,
        string? query,
        string language)
    {
        var currentCoverage = EvaluateSourceBackedPlanningCoverage(current, query, language);
        var candidateCoverage = EvaluateSourceBackedPlanningCoverage(candidate, query, language);
        return candidateCoverage.Score > currentCoverage.Score;
    }

    private sealed record SourceBackedEvidenceSufficiency(
        bool IsSufficient,
        bool ShouldExplore,
        string Kind,
        string Reason,
        int Score,
        int UsableHitCount,
        int DistinctDocumentCount,
        int DistinctSourcePageCount,
        int NavigationAnchorCount,
        int CandidateCount,
        int MinimumCandidateCount,
        int TargetSlotCount,
        bool HasRequiredAnchor);

    private static SourceBackedEvidenceSufficiency AnalyzeSourceBackedEvidenceSufficiency(
        ToolResults toolResults,
        string? query,
        string language)
    {
        if (string.IsNullOrWhiteSpace(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query))
        {
            return new SourceBackedEvidenceSufficiency(
                true,
                false,
                "none",
                "not_explorable_request",
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                true);
        }

        if (UsesSourceBackedPlanningCoverage(query))
        {
            var coverage = EvaluateSourceBackedPlanningCoverage(toolResults, query, language);
            var reason = coverage.IsAdequate
                ? "adequate_planning_coverage"
                : coverage.CandidateCount <= 0
                    ? "no_planning_candidates"
                    : !coverage.HasRequiredAnchor
                        ? "missing_requested_anchor"
                        : coverage.CandidateCount < coverage.MinimumCandidates
                            ? "too_few_distinct_candidates"
                            : coverage.DistinctSourcePages < Math.Min(3, coverage.MinimumCandidates)
                                ? "low_source_page_diversity"
                                : "partial_planning_evidence";

            return new SourceBackedEvidenceSufficiency(
                coverage.IsAdequate,
                !coverage.IsAdequate,
                "planning",
                reason,
                coverage.Score,
                coverage.CandidateCount,
                0,
                coverage.DistinctSourcePages,
                CountSourceBackedNavigationDiscoveryAnchors(toolResults),
                coverage.CandidateCount,
                coverage.MinimumCandidates,
                coverage.TargetSlots,
                coverage.HasRequiredAnchor);
        }

        var canBenefitFromDiversity =
            LooksLikeSourceBackedActionRequest(query)
            || LooksLikeDocumentaryContentRequest(query)
            || LooksLikeComparativeDocumentaryRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeSourceBackedOptionRequest(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeUserNeedsSynthesizedDecisionOrPlan(query);
        if (!canBenefitFromDiversity)
        {
            return new SourceBackedEvidenceSufficiency(
                true,
                false,
                "broad",
                "request_not_diversity_sensitive",
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                true);
        }

        var broadCoverage = EvaluateBroadSourceBackedSynthesisCoverage(toolResults, query);
        var broadScore = ComputeBroadSourceBackedCoverageScore(broadCoverage);
        var broadReason = broadCoverage.IsAdequate
            ? "adequate_broad_coverage"
            : broadCoverage.UsableHitCount <= 0
                ? "no_usable_hits"
                : broadCoverage.DistinctSourcePageCount < Math.Min(2, ResolveMinimumBroadSourceBackedSynthesisHitCount(query))
                    ? "low_source_page_diversity"
                    : broadCoverage.RichEvidenceCount <= 0
                        ? "low_evidence_richness"
                        : "partial_broad_evidence";

        return new SourceBackedEvidenceSufficiency(
            broadCoverage.IsAdequate,
            !broadCoverage.IsAdequate,
            "broad",
            broadReason,
            broadScore,
            broadCoverage.UsableHitCount,
            broadCoverage.DistinctDocumentCount,
            broadCoverage.DistinctSourcePageCount,
            CountSourceBackedNavigationDiscoveryAnchors(toolResults),
            broadCoverage.UsableHitCount,
            ResolveMinimumBroadSourceBackedSynthesisHitCount(query),
            0,
            true);
    }

    private static bool ShouldExpandSourceBackedEvidenceRetrieval(ToolResults toolResults, string? query, string language)
        => AnalyzeSourceBackedEvidenceSufficiency(toolResults, query, language).ShouldExplore;

    private static bool IsBetterSourceBackedEvidenceCoverage(
        ToolResults current,
        ToolResults candidate,
        string? query,
        string language)
    {
        if (UsesSourceBackedPlanningCoverage(query))
            return IsBetterSourceBackedPlanningCoverage(current, candidate, query, language);

        var currentCoverage = EvaluateBroadSourceBackedSynthesisCoverage(current, query);
        var candidateCoverage = EvaluateBroadSourceBackedSynthesisCoverage(candidate, query);
        return ComputeBroadSourceBackedCoverageScore(candidateCoverage) > ComputeBroadSourceBackedCoverageScore(currentCoverage);
    }

    private static int ComputeBroadSourceBackedCoverageScore(BroadSourceBackedSynthesisCoverage coverage)
        => (coverage.UsableHitCount * 8)
           + (coverage.DistinctSourcePageCount * 5)
           + (coverage.DistinctDocumentCount * 3)
           + (coverage.RichEvidenceCount * 4)
           + Math.Min(18, coverage.EvidenceRichnessScore)
           + (coverage.IsAdequate ? 20 : 0);

    private static bool CandidateSourceBackedEvidenceAddsUsefulDiversity(
        SourceBackedEvidenceSufficiency current,
        SourceBackedEvidenceSufficiency candidate)
    {
        if (!string.Equals(current.Kind, candidate.Kind, StringComparison.OrdinalIgnoreCase))
            return candidate.Score > current.Score;

        if (candidate.CandidateCount >= candidate.MinimumCandidateCount
            && current.CandidateCount < current.MinimumCandidateCount)
        {
            return true;
        }

        if (candidate.NavigationAnchorCount > current.NavigationAnchorCount
            && candidate.Score >= current.Score - 12)
        {
            return true;
        }

        if (candidate.CandidateCount > current.CandidateCount
            && candidate.DistinctSourcePageCount >= current.DistinctSourcePageCount)
        {
            return true;
        }

        if (candidate.DistinctSourcePageCount > current.DistinctSourcePageCount
            && candidate.CandidateCount >= current.CandidateCount)
        {
            return true;
        }

        if (candidate.DistinctDocumentCount > current.DistinctDocumentCount
            && candidate.UsableHitCount >= current.UsableHitCount)
        {
            return true;
        }

        return !current.HasRequiredAnchor && candidate.HasRequiredAnchor;
    }

    private static int CountSourceBackedNavigationDiscoveryAnchors(ToolResults toolResults)
        => EnumerateRagHitSummaries(toolResults)
            .Where(IsRouteDiscoveryAnchorHit)
            .GroupBy(hit =>
            {
                var title = ExtractRouteDiscoveryTitleCue(hit);
                return $"{hit.DocPath}|{hit.DocName}|{hit.PageStart}|{NormalizeLexicalLookup(title)}";
            }, StringComparer.OrdinalIgnoreCase)
            .Count();

    private static SourceBackedPlanningCoverage EvaluateSourceBackedPlanningCoverage(
        ToolResults toolResults,
        string? query,
        string language)
    {
        language = NormalizeLanguageCode(language);
        var targetSlots = ResolveSourceBackedPlanningTargetItemCount(query);
        var hasStructuredAxes = DetectRequestedDayAxisLabels(query, language).Count > 0
            && DetectRequestedPeriodAxisLabels(query, language).Count > 0;
        var minimumCandidates = ResolveMinimumSourceBackedPlanningCandidateCount(query, targetSlots, hasStructuredAxes);
        var candidates = SelectSourceBackedPlanningCandidates(
                toolResults,
                query,
                Math.Max(20, targetSlots),
                language)
            .ToList();
        var distinctLeadCandidates = candidates
            .GroupBy(BuildSourceBackedPlanningCandidateLeadKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group
                .OrderByDescending(static candidate => candidate.Score)
                .ThenByDescending(static candidate => ComputeSourceBackedEvidenceRichnessScore(candidate.Hit))
                .ThenByDescending(static candidate => candidate.Hit.Score)
                .First())
            .ToList();
        var distinctCandidateCount = distinctLeadCandidates.Count;
        var distinctSourcePages = distinctLeadCandidates
            .Select(static candidate => BuildRagHitVisiblePageMergeKey(candidate.Hit))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
        var hasRequiredAnchor = HasSourceBackedPlanningAnchorCoverage(toolResults, query);
        var richEvidenceCount = distinctLeadCandidates.Count(static candidate => HasRichSourceBackedEvidence(candidate.Hit));
        var evidenceRichnessScore = distinctLeadCandidates.Sum(static candidate => ComputeSourceBackedEvidenceRichnessScore(candidate.Hit));

        var isAdequate = distinctCandidateCount >= minimumCandidates
            && distinctSourcePages >= Math.Min(3, minimumCandidates)
            && hasRequiredAnchor;
        var score = Math.Min(distinctCandidateCount, minimumCandidates) * 10
            + Math.Min(distinctSourcePages, Math.Min(3, minimumCandidates)) * 4
            + (hasRequiredAnchor ? 8 : 0)
            + (richEvidenceCount * 3)
            + Math.Min(16, evidenceRichnessScore)
            + (isAdequate ? 20 : 0);

        return new SourceBackedPlanningCoverage(
            distinctCandidateCount,
            distinctSourcePages,
            minimumCandidates,
            targetSlots,
            hasRequiredAnchor,
            richEvidenceCount,
            evidenceRichnessScore,
            isAdequate,
            score);
    }

    private static int ResolveMinimumSourceBackedPlanningCandidateCount(string? query, int targetSlots, bool hasStructuredAxes)
    {
        if (LooksLikeSourceBackedVerificationChecklistRequest(query))
            return Math.Min(3, Math.Max(1, targetSlots));

        if (!hasStructuredAxes)
            return Math.Min(3, Math.Max(2, targetSlots));

        return Math.Min(targetSlots, Math.Max(4, (int)Math.Ceiling(targetSlots * 0.45)));
    }

    private static bool HasSourceBackedPlanningAnchorCoverage(ToolResults toolResults, string? query)
    {
        var anchorTerms = ExtractPlanningCoverageAnchorTerms(query).ToArray();
        if (anchorTerms.Length == 0)
            return true;

        return EnumerateRagHitSummaries(toolResults)
            .Where(ShouldExposeHitForSourceBackedEvidenceDiscovery)
            .Any(hit => QueryAnchorTermsMatchHit(anchorTerms, hit));
    }

    private static IEnumerable<string> ExtractPlanningCoverageAnchorTerms(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            yield break;

        foreach (var term in ExtractPlanningRetrievalTerms(normalized))
        {
            if (term.Length >= 4 && !IsGenericPlanningCoverageTerm(term))
                yield return term;
        }
    }

    private static bool IsGenericPlanningCoverageTerm(string term)
    {
        var normalized = NormalizeLexicalLookup(term);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        return normalized is
            "plan" or "plans" or "planning" or "programme" or "program" or "schedule" or "calendar" or
            "calendrier" or "organisation" or "organizacion" or "organizacao" or "organizzazione" or
            "semaine" or "hebdo" or "hebdomadaire" or "week" or "weekly" or "semana" or "semanal" or
            "woche" or "wochenplan" or "settimana" or "settimanale" or
            "lundi" or "mardi" or "mercredi" or "jeudi" or "vendredi" or "samedi" or "dimanche" or
            "monday" or "tuesday" or "wednesday" or "thursday" or "friday" or "saturday" or "sunday" or
            "petit" or "dejeuner" or "midi" or "diner" or "soir" or "matin" or "breakfast" or "lunch" or
            "dinner" or "morning" or "afternoon" or "evening" or "desayuno" or "almuerzo" or "cena" or
            "almoco" or "jantar" or "fruhstuck" or "mittag" or "abend" or "colazione" or "pranzo" or
            "rapide" or "rapides" or "simple" or "simples" or "facile" or "faciles" or
            "options" or "option" or "suggestions" or "suggestion" or "idees" or "idee" or "ideas";
    }

    private sealed record SourceBackedPlanningCoverage(
        int CandidateCount,
        int DistinctSourcePages,
        int MinimumCandidates,
        int TargetSlots,
        bool HasRequiredAnchor,
        int RichEvidenceCount,
        int EvidenceRichnessScore,
        bool IsAdequate,
        int Score);

    private static bool ShouldUseAdvisoryEvidenceGuardForBroadSynthesis(ToolResults toolResults, string? query)
        => (ShouldUseWriterForBroadSourceBackedSynthesis(toolResults, query)
            || ShouldPreferWriterForPolishedSourceBackedAnswer(toolResults, query))
           && !LooksLikeStrictCertificationOrExactProofRequest(query);

    private static bool ShouldOfferBroadenedSourceSearch(string? query)
    {
        if (string.IsNullOrWhiteSpace(query)
            || IsBroadenedSourceSearchConfirmationEnvelope(query)
            || LooksLikeStrictCertificationOrExactProofRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query)
            || LooksLikeAmbiguousBareDocumentaryFragment(query))
        {
            return false;
        }

        return LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeComparativeDocumentaryRequest(query)
            || LooksLikeBroadSynthesisRequestShape(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeSourceBackedOptionRequest(query)
            || LooksLikeUserNeedsSynthesizedDecisionOrPlan(query);
    }

    private static string AppendBroadenedSearchOfferIfHelpful(string answer, string? query, string language)
    {
        if (string.IsNullOrWhiteSpace(answer) || !ShouldOfferBroadenedSourceSearch(query))
            return answer.TrimEnd();

        var offer = DeterministicAgentText.SourceBackedExpandedSearchOffer(language);
        if (answer.Contains(offer, StringComparison.OrdinalIgnoreCase))
            return answer.TrimEnd();

        return answer.TrimEnd() + Environment.NewLine + Environment.NewLine + offer;
    }

    private static bool ShouldUseWriterForBroadSourceBackedSynthesis(ToolResults toolResults, string? query)
    {
        if (string.IsNullOrWhiteSpace(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query))
        {
            return false;
        }

        var coverage = EvaluateBroadSourceBackedSynthesisCoverage(toolResults, query);
        if (coverage.UsableHitCount == 0)
            return false;

        if (LooksLikeComparativeDocumentaryRequest(query))
            return coverage.IsAdequate
                || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query);

        if (LooksLikeSourceBackedPairingRecommendationRequest(query))
            return coverage.IsAdequate
                || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query);

        if (LooksLikeSoftChoiceRecommendationRequest(query))
            return coverage.IsAdequate
                || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query);

        if (LooksLikeGenericCollectionOrListRequest(query))
            return coverage.IsAdequate
                || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query);

        if (LooksLikeAnyDocumentaryPlanningRequest(query))
        {
            return RequiresStructuredSourceBackedPlanningCoverage(query)
                ? ShouldAllowWriterForPartialSourceBackedPlanning(toolResults, query)
                : coverage.IsAdequate || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query);
        }

        if (LooksLikeBroadSynthesisRequestShape(query))
            return coverage.IsAdequate
                || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query);

        if (LooksLikeBroadSourceBackedCompositionRequest(query))
            return coverage.IsAdequate
                || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query);

        return LooksLikeUserNeedsSynthesizedDecisionOrPlan(query)
            && (coverage.IsAdequate
                || ShouldAllowWriterForPartialBroadSourceBackedSynthesis(coverage, query));
    }

    private static bool ShouldAllowWriterForPartialBroadSourceBackedSynthesis(
        BroadSourceBackedSynthesisCoverage coverage,
        string? query)
    {
        if (string.IsNullOrWhiteSpace(query)
            || coverage.UsableHitCount <= 0
            || LooksLikeStrictCertificationOrExactProofRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query))
        {
            return false;
        }

        if (LooksLikeComparativeDocumentaryRequest(query))
            return coverage.RichEvidenceCount >= 1
                && (coverage.UsableHitCount >= 2 || coverage.DistinctSourcePageCount >= 2);

        if (LooksLikeSourceBackedPairingRecommendationRequest(query))
            return coverage.RichEvidenceCount >= 1
                || coverage.DistinctSourcePageCount >= 2
                || coverage.UsableHitCount >= 2
                || coverage.EvidenceRichnessScore >= 6;

        if (LooksLikeSoftChoiceRecommendationRequest(query))
            return coverage.RichEvidenceCount >= 1
                || coverage.DistinctSourcePageCount >= 2
                || coverage.UsableHitCount >= 2;

        if (LooksLikeGenericCollectionOrListRequest(query))
        {
            var minimumHits = Math.Max(2, ResolveMinimumBroadSourceBackedSynthesisHitCount(query));
            return coverage.RichEvidenceCount >= 1
                || (coverage.UsableHitCount >= Math.Min(2, minimumHits)
                    && coverage.DistinctSourcePageCount >= Math.Min(2, minimumHits))
                || coverage.EvidenceRichnessScore >= 8;
        }

        if (LooksLikeMultipleCandidateSynthesisRequest(query))
        {
            return coverage.RichEvidenceCount >= 1
                || (coverage.UsableHitCount >= 2 && coverage.DistinctSourcePageCount >= 2)
                || coverage.EvidenceRichnessScore >= 8;
        }

        var canUsePartialWriter =
            LooksLikeBroadSynthesisRequestShape(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeUserNeedsSynthesizedDecisionOrPlan(query);
        if (!canUsePartialWriter)
            return false;

        return coverage.RichEvidenceCount >= 1
            || (coverage.DistinctSourcePageCount >= 2 && coverage.EvidenceRichnessScore >= 4)
            || (coverage.UsableHitCount >= 2 && coverage.DistinctSourcePageCount >= 2)
            || coverage.EvidenceRichnessScore >= 12;
    }

    private static BroadSourceBackedSynthesisCoverage EvaluateBroadSourceBackedSynthesisCoverage(
        ToolResults toolResults,
        string? query)
    {
        var usableHits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .GroupBy(BuildRagHitVisiblePageMergeKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group
                .OrderByDescending(ComputeSourceBackedEvidenceRichnessScore)
                .ThenByDescending(static hit => hit.Score)
                .First())
            .Take(12)
            .ToList();
        if (usableHits.Count == 0)
            return new BroadSourceBackedSynthesisCoverage(0, 0, 0, 0, 0, false);

        var distinctDocuments = usableHits
            .Select(static hit => string.IsNullOrWhiteSpace(hit.DocPath) ? hit.DocName : hit.DocPath)
            .Where(static source => !string.IsNullOrWhiteSpace(source))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
        var distinctSourcePages = usableHits
            .Select(static hit => BuildRagHitVisiblePageMergeKey(hit))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
        var minimumHits = ResolveMinimumBroadSourceBackedSynthesisHitCount(query);
        var hasRequiredComparativeCoverage = HasRequiredComparativeEntityCoverageForBroadSynthesis(usableHits, query);
        var hasEnoughDiversity = minimumHits <= 1
            || distinctSourcePages >= Math.Min(minimumHits, 2)
            || distinctDocuments >= Math.Min(minimumHits, 2);
        var richEvidenceCount = usableHits.Count(HasRichSourceBackedEvidence);
        var evidenceRichnessScore = usableHits.Sum(ComputeSourceBackedEvidenceRichnessScore);
        var allowsSingleRichEvidence =
            !LooksLikeStrictCertificationOrExactProofRequest(query)
            && !LooksLikeComparativeDocumentaryRequest(query)
            && !LooksLikeSoftChoiceRecommendationRequest(query)
            && !LooksLikeSourceBackedPairingRecommendationRequest(query)
            && !LooksLikeGenericCollectionOrListRequest(query)
            && (LooksLikeBroadSourceBackedCompositionRequest(query)
                || LooksLikeMultipleCandidateSynthesisRequest(query)
                || LooksLikeUserNeedsSynthesizedDecisionOrPlan(query));
        var hasRichSingleEvidenceFallback = allowsSingleRichEvidence
            && richEvidenceCount >= 1
            && hasRequiredComparativeCoverage;

        return new BroadSourceBackedSynthesisCoverage(
            usableHits.Count,
            distinctDocuments,
            distinctSourcePages,
            richEvidenceCount,
            evidenceRichnessScore,
            (usableHits.Count >= minimumHits && hasEnoughDiversity && hasRequiredComparativeCoverage)
            || hasRichSingleEvidenceFallback);
    }

    private static bool HasRichSourceBackedEvidence(RagHitSummary hit)
        => ComputeSourceBackedEvidenceRichnessScore(hit) >= 9;

    private static int ComputeSourceBackedEvidenceRichnessScore(RagHitSummary hit)
    {
        var score = ComputeEvidenceShapeScore(hit, GetBestRagEvidenceText(hit), includeBackendHints: true);
        if (BackendSelectionHintsPreferUsableEvidence(hit))
            score += 2;

        if (hit.MatchedContentCards is { Count: > 0 } cards)
        {
            score += Math.Min(4, cards.Count);
            score += Math.Min(6, cards.Count(static card =>
                card.RawEvidence.HasValue
                || card.Evidence is { QuantityFacts.Count: > 0 }
                || card.Evidence?.Facts is { Count: > 0 }) * 2);
        }

        if (!string.IsNullOrWhiteSpace(hit.FullText) && hit.FullText.Length >= 160)
            score += 2;
        if (!string.IsNullOrWhiteSpace(hit.ContextualSnippet) && hit.ContextualSnippet.Length >= 120)
            score += 1;
        if (!string.IsNullOrWhiteSpace(hit.SectionTitle) || !string.IsNullOrWhiteSpace(hit.HeadingPath))
            score += 1;
        if (hit.ContentDensityScore.HasValue && hit.ContentDensityScore.Value >= 0.45)
            score += 1;

        if (BackendSelectionHintsPreferNavigation(hit) || BackendSelectionHintsPreferLowSignal(hit))
            score -= 4;
        if (hit.ManualReviewRecommended || hit.PageManualReviewRecommended || hit.DocumentManualReviewRecommended)
            score -= 1;
        if (hit.ExtractionConfidence.HasValue && hit.ExtractionConfidence.Value < 0.50)
            score -= 2;

        return Math.Clamp(score, -8, 28);
    }

    private static int ResolveMinimumBroadSourceBackedSynthesisHitCount(string? query)
    {
        if (LooksLikeComparativeDocumentaryRequest(query))
            return 2;

        if (RequiresStructuredSourceBackedPlanningCoverage(query))
        {
            return 3;
        }

        if (LooksLikeGenericCollectionOrListRequest(query))
            return 3;

        if (LooksLikeSourceBackedPairingRecommendationRequest(query))
            return 3;

        if (LooksLikeSoftChoiceRecommendationRequest(query))
            return 3;

        if (LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query))
        {
            return 2;
        }

        return 1;
    }

    private static bool RequiresStructuredSourceBackedPlanningCoverage(string? query)
        => LooksLikeWeeklyPlanningRequest(query)
           || DetectRequestedDayAxisLabels(query, "en").Count > 0
           || DetectRequestedPeriodAxisLabels(query, "en").Count > 0;

    private static bool LooksLikeMultipleCandidateSynthesisRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(
                normalized,
                @"\b(?:quel|quelle|which|what|cual|qual|welche|welcher|welches|quale)\s+(?:option|opcion|opcao|opzione)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        return Regex.IsMatch(
            normalized,
            @"\b(?:plusieurs|different(?:es)?|vari(?:e|er|ees?)|liste|lister|idees|suggestions|alternatives|candidats|choix|several|multiple|different|varied|list|options|ideas|suggestions|alternatives|candidates|varias|varios|diferentes|lista|opciones|ideas|sugerencias|alternativas|candidatos|opcoes|ideias|sugestoes|alternativas|candidatos|mehrere|verschiedene|liste|optionen|ideen|vorschlaege|vorschlage|alternativen|kandidaten|diverse|differenti|lista|opzioni|idee|suggerimenti|alternative|candidati)\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:\d{1,2}|deux|trois|quatre|cinq|six|seven|two|three|four|five|six|dos|tres|cuatro|cinco|duas|dois|tres|quatro|cinco|zwei|drei|vier|funf|fuenf|sei|due|tre|quattro|cinque)\s+(?:options?|idees?|ideas?|suggestions?|alternatives?|candidats?|candidates?|opciones?|sugerencias?|candidatos?|opcoes?|ideias?|sugestoes?|optionen|ideen|vorschlaege|vorschlage|alternativen|kandidaten|opzioni?|idee|suggerimenti|alternative|candidati)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool HasRequiredComparativeEntityCoverageForBroadSynthesis(
        IReadOnlyList<RagHitSummary> hits,
        string? query)
    {
        if (!LooksLikeComparativeDocumentaryRequest(query))
            return true;

        var entityAnchors = ExtractComparativeEntityAnchorTerms(query);
        if (entityAnchors.Length < 2)
            return hits.Count >= 2;

        return CountComparativeEntityCoverage(hits, entityAnchors) >= Math.Min(entityAnchors.Length, 2);
    }

    private sealed record BroadSourceBackedSynthesisCoverage(
        int UsableHitCount,
        int DistinctDocumentCount,
        int DistinctSourcePageCount,
        int RichEvidenceCount,
        int EvidenceRichnessScore,
        bool IsAdequate);

    private static bool LooksLikeStrictCertificationOrExactProofRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:prouve|preuve|demontre|certifie|certifier|garantis|garantie|compatible|compatibilite|obligatoire|required|mandatory|explicitement|exactement|strictement|sans\s+supposer|valide\s+officiel|officially\s+validated|prove|proof|certify|guarantee|explicitly|exactly)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeExactPassageOrCitationRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:cite|citer|citation|quote|quotation|verbatim|mot\s+pour\s+mot|mot\s+a\s+mot|passage\s+exact|extrait\s+exact|copie|copy|recopie|copier)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeUserNeedsSynthesizedDecisionOrPlan(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:aide|aider|aide\s+moi|besoin\s+d\s+aide|je\s+ne\s+sais\s+pas|quoi\s+faire|propose|proposer|proposes|suggest|suggestion|recommend|recommendation|recommande|recommander|conseille|conseiller|organise|organiser|structure|structurer|choisis|choisir|decision|decider|plan|planning|programme|selection|options?|ayuda|ayudar|necesito|no\s+se|que\s+hacer|propone|proponer|sugiere|sugerir|recomienda|recomendar|aconseja|aconsejar|organiza|organizar|elige|elegir|decision|opciones?|ajuda|ajudar|preciso|nao\s+sei|o\s+que\s+fazer|propoe|propor|sugere|sugerir|recomenda|recomendar|aconselha|aconselhar|organiza|organizar|escolhe|escolher|decisao|opcoes?|hilfe|helfen|brauche|weiss\s+nicht|was\s+tun|schlag\s+vor|vorschlag|empfiehl|empfehlen|rate|raten|organisiere|organisieren|struktur|waehle|waehlen|entscheidung|optionen?|aiuto|aiutare|bisogno|non\s+so|cosa\s+fare|proponi|proporre|suggerisci|suggerire|consiglia|consigliare|organizza|organizzare|scegli|scegliere|decisione|opzioni?)\b",
            RegexOptions.CultureInvariant);
    }

    private static string BuildAnswerShapeGuidanceForWriter(string? query, string language)
    {
        var shape = ResolveRequestedAnswerShape(query);
        var targetLanguage = NormalizeLanguageCode(language);
        var requestedStructure = BuildRequestedStructureGuidanceForWriter(query, targetLanguage);

        var shapeSpecific = shape switch
        {
            "schedule_or_plan" => """
- The user asks for a plan, schedule, program or organized proposal. Build a usable structure that matches the requested granularity when possible: days, slots, phases, options or rotation.
- Every concrete item/action/value must come from the tool results. The organization layer may be yours, but label it as a proposed organization based on the available documented items.
- If the documents do not cover every slot, still provide a useful partial structure and mark missing/uncertain slots as to complete/validate. Do not answer with a raw list of excerpts.
- If the user explicitly gives axes or slots such as weekdays, time periods, phases, roles, priorities or criteria, mirror those axes in the answer. Prefer grouped sections or a compact structured list over one bullet per source.
- If there are fewer distinct documented items than requested places, do not fill the structure by repeating weak items. Place the sourced items where they fit and mark the remaining places as missing/to validate.
- If the available evidence is clearly too small for the requested grid, do not fill the whole grid by repetition. Return a readable partial proposal and explain that more documented items are needed for a complete varied plan.
- If the available evidence remains too small after retrieval, ask one concise question offering to broaden the search/corpus instead of fabricating missing places.
- Do not expose internal wording such as candidate(s), slot(s), coverage or evidence role. Translate that into natural user-facing language.
- Do not repeat the user request. Start with the useful proposal, then add a short caveat only where the available evidence is partial.
- Avoid opening with "I can build..." or "the sources do not prove..."; that reads like a refusal instead of a helpful answer.
""",
            "comparison" => """
- The user asks to compare. Separate the compared items/sources clearly, then give common points, differences, and limits.
- Do not merge obligations, values or procedures across sources unless the answer explicitly says it is a synthesis.
""",
            "procedure" => """
- The user asks for a method or steps. Present short ordered steps only when the steps are present in the tool results.
- If the retrieved text is partial, give the supported steps first and state what is missing before execution.
""",
            "recommendation" => """
- The user asks for a choice or recommendation. Give a direct recommendation when one candidate is better supported, then explain why from the sources and list alternatives only if useful.
- If the evidence is partial, say the recommendation is documented but not a certified compatibility decision.
""",
            "document_list" => """
- The user asks which documents/sources mention a topic. Return a clean source list with a one-line reason for each source, not a narrative answer.
""",
            "summary" => """
- The user asks for a summary. Synthesize the main points in a readable structure, preserving caveats and source limits.
""",
            _ => """
- Adapt the structure to the user's request. Prefer a short useful synthesis over copied excerpts.
"""
        };

        return $"""
Detected response shape: {shape}
Target answer language code: {targetLanguage}
Generic output contract:
- Answer directly in the target language with natural spelling, accents and punctuation.
- Correct obvious OCR/text-extraction damage, missing accents, broken spacing and malformed words when doing so does not change the source facts.
- Do not repeat the user's full question in the opening sentence.
- Do not dump raw excerpts or write bullets whose main content is "document p.N: copied passage".
- Use the retrieved material as evidence, not as prose to paste. Rewrite, group and translate it into a user-friendly answer while keeping concrete facts source-backed.
- Treat headings, table-of-contents entries, profile hints and navigation anchors as private orientation only. They can guide what to say or search next, but they are not enough by themselves to become a proposed item, step or conclusion.
- Do not copy PRIVATE_SOURCE_* or SOURCE_BACKED_* control wording. It is there to guide drafting, not to appear in the final answer.
- Avoid mechanical diagnostic phrasing such as "X candidate(s) for Y slot(s)" unless the user explicitly asks for diagnostics.
- Use source names/pages as short references after readable points.
- Do not add a final "Source:" section; clickable source cards are added by the application.
- For planning requests, start with the requested structure or proposal. Put source limits after the useful draft, not as the first sentence.
- Preserve source grounding: do not invent concrete facts, items, steps, values, quantities, dates or citations absent from the tool results.
- You may reformulate, group, prioritize and organize sourced evidence so the result is useful to a non-technical user.
{requestedStructure}
{shapeSpecific}
""";
    }

    private static string BuildSourceBackedCoverageHintsForWriter(ToolResults toolResults, string? query, string language)
    {
        if (string.IsNullOrWhiteSpace(query)
            || !toolResults.Items.Any(static item => item.ToolName is "rag.search" or "rag.multi_search"))
        {
            return "No source-backed coverage hint for this turn.";
        }

        language = NormalizeLanguageCode(language);
        if (LooksLikeAnyDocumentaryPlanningRequest(query))
        {
            var coverage = EvaluateSourceBackedPlanningCoverage(toolResults, query, language);
            var dayAxis = DetectRequestedDayAxisLabels(query, language);
            var periodAxis = DetectRequestedPeriodAxisLabels(query, language);
            var hasExplicitGrid = dayAxis.Count > 0 && periodAxis.Count > 0;
            var enoughForVariedGrid = coverage.CandidateCount >= coverage.TargetSlots
                || (coverage.CandidateCount >= Math.Min(coverage.TargetSlots, Math.Max(4, (int)Math.Ceiling(coverage.TargetSlots * 0.45)))
                    && coverage.DistinctSourcePages >= Math.Min(3, coverage.MinimumCandidates));

            var sb = new StringBuilder();
            sb.AppendLine($"Private drafting note: source coverage is {(coverage.IsAdequate ? "usable" : "partial")} for this requested structure.");
            sb.AppendLine($"Usable distinct items: {coverage.CandidateCount}; distinct source pages: {coverage.DistinctSourcePages}; requested cells/items: {coverage.TargetSlots}; preferred minimum usable items: {coverage.MinimumCandidates}.");
            if (hasExplicitGrid)
                sb.AppendLine($"Detected requested grid: {dayAxis.Count} day row(s) x {periodAxis.Count} column(s).");
            if (!enoughForVariedGrid && coverage.TargetSlots > coverage.CandidateCount)
            {
                sb.AppendLine("Important: the available evidence is too small for a complete varied grid. Do not fill every requested cell by rotating the same few items.");
                sb.AppendLine("Preferred behavior: write a practical partial answer from the sourced items, mark unsupported cells as to validate/complete, and offer a broader search if the user wants the full structure.");
            }
            else if (!coverage.IsAdequate)
            {
                sb.AppendLine("Important: evidence is partial. Be useful, but keep limits explicit and avoid certifying completeness.");
            }

            return sb.ToString().TrimEnd();
        }

        var broad = EvaluateBroadSourceBackedSynthesisCoverage(toolResults, query);
        if (broad.UsableHitCount == 0)
            return "No usable RAG hit is available. Ask for a narrower scope or offer an expanded search instead of inventing.";

        return $"""
Private drafting note: source coverage is {(broad.IsAdequate ? "usable" : "partial")} for this broad request.
Usable hits: {broad.UsableHitCount}; distinct documents: {broad.DistinctDocumentCount}; distinct source pages: {broad.DistinctSourcePageCount}; rich evidence hits: {broad.RichEvidenceCount}.
If evidence is partial, write the best useful sourced answer possible and state clear limits instead of overclaiming.
""";
    }

    private static string BuildSourceBackedWritingBriefForWriter(ToolResults toolResults, string? query, string language)
    {
        if (string.IsNullOrWhiteSpace(query)
            || !toolResults.Items.Any(static item => item.ToolName is "rag.search" or "rag.multi_search"))
        {
            return "No source-backed writing brief for this turn.";
        }

        language = NormalizeLanguageCode(language);
        var shape = ResolveRequestedAnswerShape(query);
        var sb = new StringBuilder();
        sb.AppendLine($"Private drafting objective: write a polished user-facing {shape} in language '{language}'.");
        sb.AppendLine("Use the evidence as a fact inventory, not as prose to copy. Rewrite, group, translate/paraphrase and prioritize while keeping every concrete item tied to a source.");
        sb.AppendLine("Do not expose internal control wording: candidate(s), slot(s), coverage, evidenceRole, writerEvidence, tool result, broad synthesis, retrieval, documented lead, candidate bank or option bank.");

        if (LooksLikeAnyDocumentaryPlanningRequest(query))
        {
            var coverage = EvaluateSourceBackedPlanningCoverage(toolResults, query, language);
            var dayAxis = DetectRequestedDayAxisLabels(query, language);
            var periodAxis = DetectRequestedPeriodAxisLabels(query, language);
            if (dayAxis.Count > 0 && periodAxis.Count > 0)
            {
                sb.AppendLine("The user requested an explicit grid. If evidence is sufficient, draft the grid. If not, provide a compact partial proposal first, then say naturally that more sources are needed to complete all cells.");
            }
            else
            {
                sb.AppendLine("The user wants an organized proposal. Prefer useful sections or a short ranked option list over one bullet per source.");
            }

            if (!coverage.IsAdequate)
            {
                sb.AppendLine("Evidence is partial: be helpful but do not invent missing concrete items. Avoid filling a complete schedule by repeating the same weak options.");
                sb.AppendLine("Start with what can already be used, then add a short caveat and offer to broaden the search if a complete answer is needed.");
            }
            else
            {
                sb.AppendLine("Evidence coverage is acceptable: write the requested structure directly, then mention limits only if extraction quality or source scope requires it.");
            }

            return sb.ToString().TrimEnd();
        }

        var broad = EvaluateBroadSourceBackedSynthesisCoverage(toolResults, query);
        if (!broad.IsAdequate)
        {
            sb.AppendLine("Evidence is partial: write the best source-backed answer possible, then state exactly what remains uncertain. Do not turn the answer into a raw evidence list.");
        }
        else
        {
            sb.AppendLine("Evidence coverage is acceptable: synthesize naturally and cite sources only as short references.");
        }

        return sb.ToString().TrimEnd();
    }

    private static string BuildRequestedStructureGuidanceForWriter(string? query, string language)
    {
        var dayLabels = DetectRequestedDayAxisLabels(query, language);
        var periodLabels = DetectRequestedPeriodAxisLabels(query, language);
        if (dayLabels.Count == 0 && periodLabels.Count == 0)
            return string.Empty;

        var sb = new StringBuilder();
        sb.AppendLine("Detected explicit structure from the user message:");
        if (dayLabels.Count > 0)
            sb.AppendLine($"- Day axis requested: {string.Join(" | ", dayLabels)}");
        if (periodLabels.Count > 0)
            sb.AppendLine($"- Slot/time axis requested: {string.Join(" | ", periodLabels)}");

        if (dayLabels.Count > 0 && periodLabels.Count > 0)
        {
            sb.AppendLine("- Use a compact grid with the requested days as rows and the requested slots as columns when that is readable.");
            sb.AppendLine("- Fill cells with sourced candidates or source-backed context; if a cell cannot be supported, write a short 'to validate/complete' marker instead of leaving the user's requested structure implicit.");
        }
        else
        {
            sb.AppendLine("- Mirror this detected axis explicitly in the answer instead of returning a loose list.");
        }

        return sb.ToString().TrimEnd();
    }

    private static IReadOnlyList<string> DetectRequestedDayAxisLabels(string? query, string language)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var labels = LocalizedWeekdayLabels(language);
        if (Regex.IsMatch(
                normalized,
                @"\b(?:lundi\s+(?:a|au|jusqu(?:a| au)?)\s+vendredi|monday\s+(?:to|through|-)\s+friday|lunes\s+(?:a|hasta|-)\s+viernes|segunda\s+(?:a|ate|-)\s+sexta|montag\s+(?:bis|-)\s+freitag|lunedi\s+(?:a|fino a|-)\s+venerdi)\b",
                RegexOptions.CultureInvariant))
        {
            return labels.Take(5).ToArray();
        }

        var aliases = new[]
        {
            new[] { "lundi", "monday", "lunes", "segunda", "montag", "lunedi" },
            new[] { "mardi", "tuesday", "martes", "terca", "dienstag", "martedi" },
            new[] { "mercredi", "wednesday", "miercoles", "quarta", "mittwoch", "mercoledi" },
            new[] { "jeudi", "thursday", "jueves", "quinta", "donnerstag", "giovedi" },
            new[] { "vendredi", "friday", "viernes", "sexta", "freitag", "venerdi" },
            new[] { "samedi", "saturday", "sabado", "samstag", "sabato" },
            new[] { "dimanche", "sunday", "domingo", "sonntag", "domenica" }
        };

        var found = new List<int>();
        for (var i = 0; i < aliases.Length; i++)
        {
            if (aliases[i].Any(alias => Regex.IsMatch(normalized, @"\b" + Regex.Escape(alias) + @"\b", RegexOptions.CultureInvariant)))
                found.Add(i);
        }

        return found.Count >= 2
            ? found.Distinct().OrderBy(static index => index).Select(index => labels[index]).ToArray()
            : Array.Empty<string>();
    }

    private static IReadOnlyList<string> DetectRequestedPeriodAxisLabels(string? query, string language)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var hasBreakfast = Regex.IsMatch(
            normalized,
            @"\b(?:petit[-\s]+dejeune(?:r)?|breakfast|desayuno|pequeno[-\s]+almoco|cafe[-\s]+da[-\s]+manha|fruhstuck|colazione)\b",
            RegexOptions.CultureInvariant);
        var hasLunch = Regex.IsMatch(
            normalized,
            @"\b(?:midi|dejeuner|lunch|almuerzo|almoco|mittag|pranzo)\b",
            RegexOptions.CultureInvariant);
        var hasDinner = Regex.IsMatch(
            normalized,
            @"\b(?:soir|diner|dinner|cena|abend)\b",
            RegexOptions.CultureInvariant);
        if (hasBreakfast || hasLunch || hasDinner)
        {
            var dailySlotLabels = LocalizedDailySlotLabels(language);
            return new[]
            {
                hasBreakfast ? dailySlotLabels[0] : null,
                hasLunch ? dailySlotLabels[1] : null,
                hasDinner ? dailySlotLabels[2] : null
            }.Where(static label => !string.IsNullOrWhiteSpace(label)).ToArray()!;
        }

        var hasMorning = Regex.IsMatch(normalized, @"\b(?:matin|morning|manana|manha|morgen|mattina)\b", RegexOptions.CultureInvariant);
        var hasAfternoon = Regex.IsMatch(normalized, @"\b(?:apres\s+midi|afternoon|tarde|nachmittag|pomeriggio)\b", RegexOptions.CultureInvariant);
        var hasEvening = Regex.IsMatch(normalized, @"\b(?:soir|soiree|evening|noche|noite|abend|sera)\b", RegexOptions.CultureInvariant);
        if (!hasMorning && !hasAfternoon && !hasEvening)
            return Array.Empty<string>();

        var periodLabels = LocalizedDayPeriodLabels(language);
        return new[]
        {
            hasMorning ? periodLabels[0] : null,
            hasAfternoon ? periodLabels[1] : null,
            hasEvening ? periodLabels[2] : null
        }.Where(static label => !string.IsNullOrWhiteSpace(label)).ToArray()!;
    }

    private static string[] LocalizedWeekdayLabels(string language)
        => NormalizeLanguageCode(language) switch
        {
            "en" => new[] { "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday" },
            "es" => new[] { "Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo" },
            "pt" => new[] { "Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado", "Domingo" },
            "de" => new[] { "Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag" },
            "it" => new[] { "Lunedì", "Martedì", "Mercoledì", "Giovedì", "Venerdì", "Sabato", "Domenica" },
            _ => new[] { "Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche" }
        };

    private static string[] LocalizedDailySlotLabels(string language)
        => NormalizeLanguageCode(language) switch
        {
            "en" => new[] { "Breakfast", "Lunch", "Dinner" },
            "es" => new[] { "Desayuno", "Almuerzo", "Cena" },
            "pt" => new[] { "Pequeno-almoço", "Almoço", "Jantar" },
            "de" => new[] { "Frühstück", "Mittagessen", "Abendessen" },
            "it" => new[] { "Colazione", "Pranzo", "Cena" },
            _ => new[] { "Petit-déjeuner", "Déjeuner", "Dîner" }
        };

    private static string[] LocalizedDayPeriodLabels(string language)
        => NormalizeLanguageCode(language) switch
        {
            "en" => new[] { "Morning", "Afternoon", "Evening" },
            "es" => new[] { "Mañana", "Tarde", "Noche" },
            "pt" => new[] { "Manhã", "Tarde", "Noite" },
            "de" => new[] { "Morgen", "Nachmittag", "Abend" },
            "it" => new[] { "Mattina", "Pomeriggio", "Sera" },
            _ => new[] { "Matin", "Après-midi", "Soir" }
        };

    private static string BuildSourceBackedCandidateLeadsForWriter(ToolResults toolResults, string query, string language)
    {
        if (!toolResults.Items.Any(static item => item.ToolName is "rag.search" or "rag.multi_search"))
            return "none";

        var lines = new List<string>();
        var isPlanning = LooksLikeAnyDocumentaryPlanningRequest(query);
        var maxCandidates = isPlanning
            ? 12
            : 6;
        var candidates = SelectSourceBackedPlanningCandidates(
                toolResults,
                query,
                maxCandidates,
                NormalizeLanguageCode(language))
            .ToList();

        foreach (var candidate in candidates)
        {
            AddSourceBackedCandidateLeadLine(lines, "item", candidate.Title, candidate.Hit, language);
        }

        var candidateKeys = candidates
            .Select(static candidate => BuildRagHitVisiblePageMergeKey(candidate.Hit))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var contextLimit = lines.Count == 0 ? 8 : Math.Max(2, 8 - lines.Count);
        var contextHits = EnumerateRagHitSummaries(toolResults)
            .Where(ShouldExposeHitForSourceBackedEvidenceDiscovery)
            .Where(hit => !candidateKeys.Contains(BuildRagHitVisiblePageMergeKey(hit)))
            .OrderByDescending(static hit => LooksLikeNavigationOnlyHit(hit) ? 0 : ComputeSourceBackedEvidenceRichnessScore(hit))
            .ThenByDescending(static hit => hit.Score)
            .Take(contextLimit)
            .ToList();

        foreach (var hit in contextHits)
        {
            var isDiscoveryAnchor = LooksLikeNavigationOnlyHit(hit) && IsRouteDiscoveryAnchorHit(hit);
            var title = isDiscoveryAnchor
                ? ExtractRouteDiscoveryTitleCue(hit)
                : ExtractReadablePartialPlanningLeadTitle(hit, query);
            if (string.IsNullOrWhiteSpace(title))
                title = CollapseWhitespace(hit.SectionTitle ?? hit.HeadingPath ?? string.Empty);
            if (string.IsNullOrWhiteSpace(title))
                title = "source-backed context";

            AddSourceBackedCandidateLeadLine(lines, isDiscoveryAnchor ? "navigation" : "context", title, hit, language);
        }

        return lines.Count == 0
            ? "none"
            : string.Join(Environment.NewLine, lines.Take(isPlanning ? 12 : 10));
    }

    private static void AddSourceBackedCandidateLeadLine(List<string> lines, string role, string title, RagHitSummary hit, string language)
    {
        var source = string.IsNullOrWhiteSpace(hit.DocName) ? Path.GetFileName(hit.DocPath) : hit.DocName;
        if (string.IsNullOrWhiteSpace(source))
            source = hit.DocPath;

        var supportCue = BuildSourceBackedCandidateSupportCue(hit);
        var contentRole = CollapseWhitespace(hit.SelectionHintRole ?? hit.ContentRole ?? string.Empty);
        var writingNote = BuildSourceBackedCandidateWritingNote(contentRole, hit, language);
        var supportSuffix = string.IsNullOrWhiteSpace(supportCue)
            ? string.Empty
            : $"; evidence=\"{CollapseWhitespace(supportCue)}\"";
        lines.Add(
            $"EVIDENCE_ITEM role=\"{role}\" title=\"{CollapseWhitespace(title)}\" source=\"{source}\" page=\"{Math.Max(1, hit.PageStart)}\" instruction=\"{writingNote}\"{supportSuffix}");
    }

    private static string BuildSourceBackedCandidateWritingNote(string contentRole, RagHitSummary hit, string language)
    {
        var role = NormalizeLexicalLookup(contentRole);
        if ((role.Contains("navigation", StringComparison.Ordinal) || BackendSelectionHintsPreferNavigation(hit))
            && !LooksLikeResolvedRouteTargetHit(hit))
            return "background only; do not present as a proposed item unless the same hit has concrete content";
        if (IsRouteDiscoveryAnchorHit(hit) && !LooksLikeResolvedRouteTargetHit(hit))
            return "discovery anchor; use it to search/read the target page before presenting a final item";
        if (role.Contains("fragment", StringComparison.Ordinal) || BackendSelectionHintsPreferLowSignal(hit))
            return "weak evidence; cite carefully and keep uncertainty visible";
        if (role.Contains("supporting", StringComparison.Ordinal) || role.Contains("advisory", StringComparison.Ordinal))
            return "context or caveat, not the main recommendation";
        if (role.Contains("actionable", StringComparison.Ordinal))
            return "can be proposed if the title/detail is clear; rewrite naturally";

        return "evidence inventory; rewrite naturally and keep the source reference short";
    }

    private static string BuildSourceBackedCandidateSupportCue(RagHitSummary hit)
    {
        var routeCue = ExtractRouteDiscoveryTitleCue(hit);
        if (!string.IsNullOrWhiteSpace(routeCue))
            return $"route title: {routeCue}";

        var cardTitle = hit.MatchedContentCards?
            .Select(static card => CleanSourceBackedOptionTitle(card.Title))
            .FirstOrDefault(static title => IsUsableSourceBackedOptionTitle(title)
                && !LooksLikeWeakSourceBackedOptionTitle(title));
        if (!string.IsNullOrWhiteSpace(cardTitle))
            return $"readable title: {cardTitle}";

        var section = CollapseWhitespace(hit.SectionTitle ?? hit.HeadingPath ?? string.Empty);
        if (!string.IsNullOrWhiteSpace(section))
            return $"related section: {section}";

        if (BackendSelectionHintsPreferUsableEvidence(hit))
            return "actionable source page";

        var evidence = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 100);
        if (string.IsNullOrWhiteSpace(evidence))
            evidence = FormatReadableEvidenceExcerpt(hit.ContextualSnippet ?? string.Empty, maxLength: 100);
        if (LooksLikeNoisyCandidateSupportCue(evidence))
            return string.Empty;

        return evidence;
    }

    private static string BuildWriterEvidenceCueForPrompt(RagHitSummary hit, string? query, int maxLength)
    {
        var cardEvidence = BuildWriterContentCardEvidenceCue(hit);
        if (!string.IsNullOrWhiteSpace(cardEvidence))
            return TruncateForPrompt(cardEvidence, maxLength);

        var title = ExtractReadablePartialPlanningLeadTitle(hit, query ?? string.Empty);
        if (!string.IsNullOrWhiteSpace(title)
            && !LooksLikeGenericWriterEvidenceCueTitle(title)
            && !LooksLikeNoisyCandidateSupportCue(title))
            return TruncateForPrompt(title, maxLength);

        var section = CollapseWhitespace(hit.SectionTitle ?? hit.HeadingPath ?? string.Empty);
        if (!string.IsNullOrWhiteSpace(section)
            && !LooksLikeGenericWriterEvidenceCueTitle(section)
            && !LooksLikeNoisyCandidateSupportCue(section))
            return TruncateForPrompt(section, maxLength);

        var evidence = CleanReadableProcedureArtifacts(FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength));
        if (LooksLikeNoisyCandidateSupportCue(evidence))
            evidence = CleanReadableProcedureArtifacts(FormatReadableEvidenceExcerpt(hit.ContextualSnippet ?? string.Empty, maxLength));

        return LooksLikeNoisyCandidateSupportCue(evidence)
            ? string.Empty
            : evidence;
    }

    private static string BuildWriterContentCardEvidenceCue(RagHitSummary hit)
    {
        if (hit.MatchedContentCards is null || hit.MatchedContentCards.Count == 0)
            return string.Empty;

        var fragments = new List<string>();
        foreach (var card in hit.MatchedContentCards.Take(2))
        {
            var title = CollapseWhitespace(card.Title);
            if (!string.IsNullOrWhiteSpace(title)
                && !LooksLikeGenericWriterEvidenceCueTitle(title)
                && !LooksLikeNoisyCandidateSupportCue(title))
                fragments.Add(title);

            var facts = card.Evidence?.Facts?
                .Select(fact => CollapseWhitespace(
                    !string.IsNullOrWhiteSpace(fact.SourceText)
                        ? fact.SourceText
                        : string.Join(' ', new[] { fact.Label, fact.Value, fact.Unit }.Where(static part => !string.IsNullOrWhiteSpace(part)))))
                .Where(static fact => !string.IsNullOrWhiteSpace(fact))
                .Where(static fact => !LooksLikeNoisyCandidateSupportCue(fact))
                .Take(2)
                .ToArray();
            if (facts is { Length: > 0 })
                fragments.AddRange(facts);

            var quantityFacts = card.Evidence?.QuantityFacts?
                .Select(fact => CollapseWhitespace(
                    !string.IsNullOrWhiteSpace(fact.SourceText)
                        ? fact.SourceText
                        : $"{fact.Label} {fact.Value.ToString(CultureInfo.InvariantCulture)} {fact.Unit}"))
                .Where(static fact => !string.IsNullOrWhiteSpace(fact))
                .Where(static fact => !LooksLikeNoisyCandidateSupportCue(fact))
                .Take(2)
                .ToArray();
            if (quantityFacts is { Length: > 0 })
                fragments.AddRange(quantityFacts);
        }

        return string.Join(" | ", fragments.Distinct(StringComparer.OrdinalIgnoreCase).Take(4));
    }

    private static bool LooksLikeGenericWriterEvidenceCueTitle(string? title)
    {
        var normalized = NormalizeLexicalLookup(title);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        return normalized is "document"
            or "property value"
            or "properties"
            or "content"
            or "content card"
            or "source"
            or "sourced lead"
            or "piste sourcee"
            or "option sourcee";
    }

    private static string BuildWriterUseCueForPrompt(RagHitSummary hit, string? query)
    {
        var role = NormalizeLexicalLookup(hit.SelectionHintRole ?? hit.ContentRole ?? string.Empty);
        if (role.Contains("navigation", StringComparison.Ordinal) || BackendSelectionHintsPreferNavigation(hit))
            return "Use only as navigation/context; do not promote as a proposed item unless the text itself contains a concrete item.";
        if (role.Contains("fragment", StringComparison.Ordinal) || BackendSelectionHintsPreferLowSignal(hit))
            return "Use only as weak context; mention uncertainty if it is cited.";
        if (role.Contains("supporting", StringComparison.Ordinal) || role.Contains("advisory", StringComparison.Ordinal))
            return "Use as supporting context or caveat, not as the main recommendation.";
        if (role.Contains("actionable", StringComparison.Ordinal) || LooksLikeAnyDocumentaryPlanningRequest(query))
            return "May be used as a concrete candidate if the title/evidence is clear; rewrite it naturally in the target language.";
        return "Use as evidence inventory; rewrite naturally and keep the source/page reference short.";
    }

    private static bool LooksLikeNoisyCandidateSupportCue(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var normalized = NormalizeLexicalLookup(text);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        var tokenCount = Regex.Matches(normalized, @"[\p{L}\p{N}]+", RegexOptions.CultureInvariant).Count;
        var digitCount = text.Count(char.IsDigit);
        var separatorCount = text.Count(static ch => ch is ';' or '|' or '/' or '\\' or '=');
        var upperCaseLetters = text.Count(char.IsUpper);
        var letters = text.Count(char.IsLetter);

        return tokenCount > 28
            || separatorCount >= 6
            || (digitCount >= 10 && tokenCount >= 10)
            || (letters >= 20 && upperCaseLetters > letters * 0.70);
    }

    private static bool LooksLikeWriterControlLeak(string? answer)
    {
        if (string.IsNullOrWhiteSpace(answer))
            return false;

        return answer.Contains("SOURCE_BACKED_", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("PRIVATE_SOURCE_", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("EVIDENCE_ITEM", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("TOOL_RESULTS", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("writerEvidence", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("writerUse", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("evidenceRole", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("candidate(s)", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("slot(s)", StringComparison.OrdinalIgnoreCase)
            || answer.Contains("lead(s)", StringComparison.OrdinalIgnoreCase)
            || Regex.IsMatch(answer, @"\btool\s+result\b", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                answer,
                @"\b(?:piste\(s\)\s+sourc\w*|candidat\(s\)\s+sourc\w*|element\(s\)\s+sourc\w*|élément\(s\)\s+sourc\w*|cr[ée]neau\(x\)\s+demand\w*|banque\s+d['’]options|source-backed\s+leads?|candidate\s+bank|option\s+bank)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                NormalizeLexicalLookup(answer),
                @"\b(?:source\s+backed\s+leads?|candidate\s+bank|option\s+bank|evidence\s+inventory|pistes?\s+sourcees?|piste\s+s\s+sourcee\s+s|banque\s+d\s+options?|candidats?\s+sources?|candidat\s+s\s+source\s+s|creneaux?\s+demandes?|creneau\s+x\s+demande\s+s|elements?\s+sources?\s+distincts?|element\s+s\s+source\s+s\s+distinct)\b",
                RegexOptions.CultureInvariant);
    }

    private static string ResolveRequestedAnswerShape(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return "auto";

        if (LooksLikeAnyDocumentaryPlanningRequest(query))
            return "schedule_or_plan";

        if (LooksLikeComparativeDocumentaryRequest(query) || LooksLikeRankingDocumentaryRequest(query))
            return "comparison";

        if (Regex.IsMatch(
                normalized,
                @"\b(?:procedure|procedures|processus|process|etapes?|steps?|mode\s+d\s+emploi|comment\s+faire|how\s+to|workflow|marche\s+a\s+suivre|methode|method|procedimiento|procedimientos|proceso|procesos|pasos?|como\s+hacer|metodo|metodos|procedimento|procedimentos|processo|processos|passos?|como\s+fazer|methode|methoden|schritte?|anleitung|wie\s+geht|wie\s+mache|procedura|procedure|processo|processi|passi|come\s+fare|metodo|metodi)\b",
                RegexOptions.CultureInvariant))
        {
            return "procedure";
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:documents?\s+qui|sources?\s+qui|fichiers?\s+qui|quels?\s+documents?|which\s+documents?|which\s+sources?|liste|lister|list|documentos?\s+que|fuentes?\s+que|archivos?\s+que|que\s+documentos?|lista|listar|documentos?\s+que|fontes?\s+que|ficheiros?\s+que|quais?\s+documentos?|liste|listar|welche\s+dokumente?|welche\s+quellen?|quellen?\s+die|dokumente?\s+die|liste|auflisten|quali\s+documenti?|quali\s+fonti?|documenti?\s+che|fonti?\s+che|elenca|lista)\b",
                RegexOptions.CultureInvariant))
        {
            return "document_list";
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:resume|resumer|synthese|synthetise|summary|summarize|summarise|about|de\s+quoi\s+parle|resumen|resumir|sintesis|sintetiza|sobre\s+que\s+trata|resumo|resumir|sintese|sintetiza|sobre\s+o\s+que\s+fala|zusammenfassung|zusammenfassen|fasse|worum\s+geht|riassunto|riassumere|riassumi|sintesi|sintetizza|di\s+cosa\s+parla)\b",
                RegexOptions.CultureInvariant))
        {
            return "summary";
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:quel|quelle|quels|quelles|quoi|choisir|choisis|choix|recommande|recommander|conseille|conseiller|propose|proposer|suggest|recommend|which|what|best|meilleur|meilleure|option|options|cual|cuales|que|elegir|elige|opcion|opciones|recomienda|recomendar|aconseja|aconsejar|propone|proponer|sugiere|sugerir|mejor|qual|quais|escolher|escolhe|opcao|opcoes|recomenda|recomendar|aconselha|aconselhar|propoe|propor|sugere|sugerir|melhor|welche|welcher|welches|was|waehlen|waehle|auswahl|optionen|empfiehl|empfehlen|rate|raten|vorschlag|beste|quale|quali|cosa|scegliere|scegli|scelta|opzione|opzioni|consiglia|consigliare|proponi|proporre|suggerisci|suggerire|migliore)\b",
                RegexOptions.CultureInvariant))
        {
            return "recommendation";
        }

        return "auto";
    }

    private static bool LooksLikeBroadSynthesisRequestShape(string? query)
    {
        var shape = ResolveRequestedAnswerShape(query);
        return shape is "schedule_or_plan" or "comparison" or "procedure" or "recommendation" or "document_list" or "summary"
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeUserNeedsSynthesizedDecisionOrPlan(query);
    }

    private static bool LooksLikeRawExcerptDumpPlanningAnswer(string? answer, string? query)
    {
        if (string.IsNullOrWhiteSpace(answer)
            || !LooksLikeBroadSynthesisRequestShape(query))
        {
            return false;
        }

        var text = answer.Trim();
        var sourceLeadLineCount = Regex.Matches(
            text,
            @"(?im)^\s*(?:[-*•]|\d+[.)])?\s*[^:\r\n]{1,160}\.(?:pdf|docx?|xlsx?|pptx?)\s+p\.?\s*\d+\s*(?::|-|–)",
            RegexOptions.CultureInvariant).Count;
        sourceLeadLineCount += Regex.Matches(
            text,
            @"(?im)^\s*\u2022\s*[^:\r\n]{1,160}\.(?:pdf|docx?|xlsx?|pptx?)\s+p\.?\s*\d+\s*(?::|-|–)",
            RegexOptions.CultureInvariant).Count;
        if (sourceLeadLineCount >= 2)
            return true;

        var longBulletWithSourceCount = Regex.Matches(
            text,
            @"(?im)^\s*(?:[-*•]|\d+[.)])\s+.{180,}\b(?:p\.?\s*\d+|page\s+\d+)\b",
            RegexOptions.CultureInvariant).Count;
        longBulletWithSourceCount += Regex.Matches(
            text,
            @"(?im)^\s*\u2022\s+.{180,}\b(?:p\.?\s*\d+|page\s+\d+)\b",
            RegexOptions.CultureInvariant).Count;
        longBulletWithSourceCount += Regex.Matches(
            text,
            @"(?im)^\s*(?:[-*\u2022\u25e6]|\d+[.)])\s+.{80,}\([^()\r\n]{1,180}\.(?:pdf|docx?|xlsx?|pptx?)\s+p\.?\s*\d+\)",
            RegexOptions.CultureInvariant).Count;
        if (longBulletWithSourceCount >= 2 && LooksLikeWeeklyPlanningRequest(query))
            return true;

        var rawSourceReferenceCount = Regex.Matches(
            text,
            @"(?i)\b(?:pdf|docx?|xlsx?|pptx?)\s+p\.?\s*\d+\s*(?::|-|–)",
            RegexOptions.CultureInvariant).Count;
        var organizationSignals = Regex.IsMatch(
            NormalizeLexicalLookup(text),
            @"\b(?:organisation|rotation|banque|options?|planning|calendrier|lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche|schedule|monday|tuesday|wednesday|thursday|friday|saturday|sunday|semana|wochenplan|settimana)\b",
            RegexOptions.CultureInvariant);

        if (rawSourceReferenceCount >= 3 && !organizationSignals)
            return true;

        return sourceLeadLineCount >= 1
            && rawSourceReferenceCount >= 2
            && LooksLikeWeeklyPlanningRequest(query)
            && Regex.IsMatch(
                NormalizeLexicalLookup(text),
                @"\b(?:pistes?\s+trouvees?|passages?\s+trouves?|extraits?\s+trouves?|brut|bruts|raw)\b",
                RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeOverfilledPartialPlanningAnswer(string answer, string? query)
    {
        if (!LooksLikeWeeklyPlanningRequest(query))
            return false;

        var normalized = NormalizeLexicalLookup(answer);
        var dayMentions = Regex.Matches(
                normalized,
                @"\b(?:lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche|monday|tuesday|wednesday|thursday|friday|saturday|sunday|lunes|martes|miercoles|jueves|viernes|sabado|domingo|segunda|terca|quarta|quinta|sexta|montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag|lunedi|martedi|mercoledi|giovedi|venerdi|sabato|domenica)\b",
                RegexOptions.CultureInvariant)
            .Select(static match => match.Value)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
        var slotLineCount = Regex.Matches(
            answer,
            @"(?im)^\s*(?:[-*\u2022\u25e6]|\d+[.)])?\s*(?:petit[- ]?d[ée]jeuner|d[ée]jeuner|d[îi]ner|soir|matin|midi|breakfast|lunch|dinner|morning|evening|desayuno|almuerzo|cena|jantar|fr[uü]hst[uü]ck|mittag|abend|colazione|pranzo)\s*:",
            RegexOptions.CultureInvariant).Count;
        if (dayMentions < 3 && slotLineCount < 6)
            return false;

        var sourceRefs = Regex.Matches(
                answer,
                @"(?i)\b[\p{L}\p{N}_ .,'()\-]+?\.(?:pdf|docx?|xlsx?|pptx?)\s*\(?\s*p\.?\s*\d+",
                RegexOptions.CultureInvariant)
            .Select(static match => NormalizeLexicalLookup(match.Value))
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .ToList();
        if (sourceRefs.Count < 6)
            return false;

        var grouped = sourceRefs
            .GroupBy(static value => value, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group.Count())
            .OrderByDescending(static count => count)
            .ToList();
        if (grouped.Count == 0)
            return false;

        return grouped.Count <= 3 && grouped[0] >= 3;
    }

    private static bool LooksLikePoorPlanningFallbackAnswer(string? answer, string? query)
    {
        if (string.IsNullOrWhiteSpace(answer))
        {
            return false;
        }

        var broadOrCollectionLikeQuery = LooksLikeBroadSynthesisRequestShape(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSourceBackedOptionRequest(query);
        if (!broadOrCollectionLikeQuery)
            return false;

        if (LooksLikeWriterControlLeak(answer))
            return true;

        if (LooksLikeRawExcerptDumpPlanningAnswer(answer, query))
            return true;

        if (LooksLikeOverfilledPartialPlanningAnswer(answer, query))
            return true;

        var normalized = NormalizeLexicalLookup(answer);
        if (Regex.IsMatch(
                normalized,
                @"\b(?:here\s+is\s+a\s+(?:cleaner\s+)?source\s+backed\s+starting\s+list|here\s+is\s+a\s+usable\s+starting\s+point|use\s+these\s+sourced\s+leads\s+as\s+a\s+base|cleaner\s+source\s+backed\s+starting\s+list|documented\s+candidates?\s+as\s+a\s+base|voici\s+une\s+liste\s+de\s+depart\s+plus\s+exploitable|utilise\s+ces\s+candidats?\s+documentes?\s+comme\s+base|a\s+utiliser\s+comme\s+point\s+de\s+depart|base\s+de\s+travail\s+exploitable\s+a\s+partir\s+des\s+elements?\s+sources?)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:elements?\s+documentaires?\s+partiels?\s+sur|elements?\s+documentes?\s+disponibles?|elements?\s+exploitables?|sources?\s+donnent?\s+quelques?\s+elements?|options?\s+utilisables?\s+pour\s+demarrer|pas\s+assez\s+pour\s+remplir|sources?\s+recuperees?\s+ne\s+suffisent?|pour\s+obtenir\s+un\s+planning\s+complet|pistes?\s+sourcees?\s+disponibles?|je\s+limite\s+la\s+reponse\s+aux\s+extraits?|je\s+peux\s+construire\s+une\s+base\s+exploitable|sources?\s+(?:retrouvees?\s+)?ne\s+prouvent?\s+pas|j\s+ai\s+trouve\s+\d+.{0,80}(?:pistes?|piste\s+s|elements?|element\s+s|candidats?|candidat\s+s).{0,60}(?:sourcees?|sourcee\s+s|sources?|source\s+s)|pistes?\s+sourcees?\s+distinctes?|piste\s+s\s+sourcee\s+s\s+distincte\s+s|creneaux?\s+demandes?|creneau\s+x\s+demande\s+s|banque\s+d\s+options?|partial\s+document\s+evidence\s+about|documented\s+base\s+is\s+incomplete|usable\s+elements?\s+for\s+\d+\s+requested\s+places|usable\s+starting\s+options?|i\s+can\s+build\s+an\s+usable\s+basis|sources?\s+do\s+not\s+prove|here\s+are\s+the\s+source\s+backed\s+leads?|without\s+adding\s+facts\s+quantities?\s+or\s+steps?|candidate\s+bank|option\s+bank|indicios?\s+documentales?\s+parciales?\s+sobre|indicios?\s+documentais?\s+parciais?\s+sobre|posso\s+construir\s+uma\s+base\s+util|as\s+fontes?\s+nao\s+provam|puedo\s+construir\s+una\s+base\s+util|las\s+fuentes?\s+no\s+prueban|ich\s+kann\s+eine\s+nutzbare\s+grundlage\s+erstellen|die\s+quellen?\s+belegen\s+nicht|posso\s+costruire\s+una\s+base\s+utile|le\s+fonti?\s+non\s+dimostrano)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (LooksLikeGenericCollectionOrListRequest(query)
            && Regex.IsMatch(
                normalized,
                @"\b(?:j\s+ai\s+trouve\s+l\s+element\s+demande|i\s+found\s+the\s+requested\s+item|elemento\s+solicitado|elemento\s+pedido|angefragte\s+element|elemento\s+richiesto)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        var sourceLeadLineCount = Regex.Matches(
            answer,
            @"(?im)^\s*(?:[-*\u2022â€¢]|\d+[.)])?\s*[^:\r\n]{1,160}\.(?:pdf|docx?|xlsx?|pptx?)\s+p\.?\s*\d+\s*(?::|-|–)",
            RegexOptions.CultureInvariant).Count;
        return sourceLeadLineCount >= 2;
    }

    private static bool LooksLikeUnderusedSourceBackedPlanningAnswer(string? answer, ToolResults toolResults, string? query)
    {
        if (string.IsNullOrWhiteSpace(answer)
            || !LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeWeeklyPlanningRequest(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query))
        {
            return false;
        }

        var targetItemCount = ResolveSourceBackedPlanningTargetItemCount(query);
        var candidates = SelectSourceBackedPlanningCandidates(toolResults, query, targetItemCount)
            .Take(Math.Min(5, targetItemCount))
            .ToList();
        if (candidates.Count < 2)
            return false;

        var normalizedAnswer = NormalizeLexicalLookup(answer);
        var mentionedCandidates = candidates.Count(candidate => SourceBackedPlanningCandidateMentioned(normalizedAnswer, candidate));
        if (mentionedCandidates >= Math.Min(2, candidates.Count))
            return false;

        var sourceLinkCount = Regex.Matches(answer, @"\[\[open\|", RegexOptions.CultureInvariant).Count;
        if (sourceLinkCount >= Math.Min(2, candidates.Count))
            return false;

        var bulletLikeLineCount = Regex.Matches(
            answer,
            @"(?m)^\s*(?:[-*]|\d+[.)]|(?:jour|day|dia|tag|giorno|option|opcion|opcao|opzione)\s+\d+)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Count;

        return bulletLikeLineCount < Math.Min(2, candidates.Count);
    }

    private static bool SourceBackedPlanningCandidateMentioned(string normalizedAnswer, SourceBackedOptionCandidate candidate)
    {
        if (string.IsNullOrWhiteSpace(normalizedAnswer))
            return false;

        var title = NormalizeLexicalLookup(candidate.Title);
        if (!string.IsNullOrWhiteSpace(title) && title.Length >= 4 && normalizedAnswer.Contains(title, StringComparison.Ordinal))
            return true;

        var titleTerms = ExtractQuerySignalTerms(title)
            .Where(static term => term.Length >= 5)
            .Take(4)
            .ToArray();
        if (titleTerms.Length >= 2 && titleTerms.Count(term => normalizedAnswer.Contains(term, StringComparison.Ordinal)) >= 2)
            return true;

        var sourceLabel = NormalizeLexicalLookup(candidate.Hit.DocName ?? candidate.Hit.DocPath);
        if (string.IsNullOrWhiteSpace(sourceLabel))
            return false;

        return normalizedAnswer.Contains(sourceLabel, StringComparison.Ordinal);
    }

    private static IReadOnlyList<SourceBackedOptionCandidate> SelectSourceBackedPlanningCandidates(ToolResults toolResults, string? query, int maxItems, string language = "")
    {
        var candidates = SelectSourceBackedOptionCandidates(toolResults, query, keepOverRequestedDuration: true, language: language)
            .Where(candidate => !LooksLikePageReferenceOnlyHit(candidate.Hit))
            .Where(IsUsableSourceBackedPlanningCandidate)
            .Where(candidate => string.IsNullOrWhiteSpace(query) || candidate.Score > 0)
            .GroupBy(BuildSourceBackedPlanningCandidateKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group
                .OrderByDescending(static candidate => candidate.Score)
                .ThenByDescending(static candidate => ComputeSourceBackedEvidenceRichnessScore(candidate.Hit))
                .ThenByDescending(static candidate => candidate.Hit.Score)
                .First())
            .Take(maxItems)
            .ToList();

        if (candidates.Count > 0)
            return candidates;

        var sourceHits = EnumerateRagHitSummaries(toolResults)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(hit => !LooksLikeLowSignalAppFeatureHit(hit, query ?? string.Empty))
            .Where(hit => LooksLikeResolvedRouteTargetHit(hit) || !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();
        if (!string.IsNullOrWhiteSpace(query))
            sourceHits = FilterHitsToDominantTopLevel(sourceHits, query).ToList();

        return sourceHits
            .Select(hit =>
            {
                var title = ExtractSourceBackedOptionTitle(hit, query);
                var visibleMinutes = ExtractBestVisibleDurationMinutes(hit);
                return new SourceBackedOptionCandidate(
                    hit,
                    title,
                    ComputeSourceBackedOptionHitScore(hit, title, query, requestedMaxMinutes: null, visibleMinutes),
                    visibleMinutes);
            })
            .Where(candidate => !string.IsNullOrWhiteSpace(candidate.Title))
            .Where(IsUsableSourceBackedPlanningCandidate)
            .Where(candidate => string.IsNullOrWhiteSpace(query) || candidate.Score > 0)
            .OrderByDescending(candidate => candidate.Score)
            .ThenByDescending(candidate => ComputeSourceBackedEvidenceRichnessScore(candidate.Hit))
            .ThenByDescending(candidate => candidate.Hit.Score)
            .GroupBy(BuildSourceBackedPlanningCandidateKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group.First())
            .Take(maxItems)
            .ToList();
    }

    private static string BuildSourceBackedPlanningCandidateKey(SourceBackedOptionCandidate candidate)
    {
        var cardId = candidate.Hit.MatchedContentCards?
            .Select(static card => NullIfWhiteSpace(card.ContentCardId))
            .FirstOrDefault(static id => !string.IsNullOrWhiteSpace(id));
        if (!string.IsNullOrWhiteSpace(cardId))
            return $"{candidate.Hit.DocPath}|{candidate.Hit.PageStart}|{candidate.Hit.PageEnd}|card:{cardId}";

        return $"{candidate.Hit.DocPath}|{candidate.Hit.PageStart}|{candidate.Hit.PageEnd}";
    }

    private static string BuildSourceBackedPlanningCandidateLeadKey(SourceBackedOptionCandidate candidate)
    {
        var titleKey = NormalizeLexicalLookup(candidate.Title);
        if (!string.IsNullOrWhiteSpace(titleKey))
            return $"title:{titleKey}";

        var cardTitle = candidate.Hit.MatchedContentCards?
            .Select(static card => NullIfWhiteSpace(card.Title))
            .FirstOrDefault(static title => !string.IsNullOrWhiteSpace(title));
        var cardTitleKey = NormalizeLexicalLookup(cardTitle);
        if (!string.IsNullOrWhiteSpace(cardTitleKey))
            return $"card-title:{cardTitleKey}";

        var cardId = candidate.Hit.MatchedContentCards?
            .Select(static card => NullIfWhiteSpace(card.ContentCardId))
            .FirstOrDefault(static id => !string.IsNullOrWhiteSpace(id));
        if (!string.IsNullOrWhiteSpace(cardId))
            return $"card:{cardId}";

        return BuildSourceBackedPlanningCandidateKey(candidate);
    }

    private static bool IsUsableSourceBackedPlanningCandidate(SourceBackedOptionCandidate candidate)
    {
        var normalizedTitle = NormalizeLexicalLookup(candidate.Title);
        if (string.IsNullOrWhiteSpace(normalizedTitle)
            || LooksLikePlanItemNoise(candidate.Title)
            || LooksLikeWeakSourceBackedOptionTitle(candidate.Title)
            || LooksLikeProcedureSentenceTitle(normalizedTitle))
        {
            return false;
        }

        var titleTerms = ExtractQuerySignalTerms(normalizedTitle)
            .Where(static term => term.Length >= 4)
            .ToArray();
        if (titleTerms.Length == 0)
            return false;

        return true;
    }

    private static int ResolveSourceBackedPlanningTargetItemCount(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (!string.IsNullOrWhiteSpace(normalized))
        {
            var explicitCount = Regex.Match(
                normalized,
                @"\b(?<n>\d{1,2})\s+(?:jours?|days?|items?|elements?|options?|etapes?|steps?)\b",
                RegexOptions.CultureInvariant);
            if (explicitCount.Success
                && int.TryParse(explicitCount.Groups["n"].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var count)
                && count is >= 1 and <= 20)
            {
                return count;
            }

            var requestedDays = DetectRequestedDayAxisLabels(query, "en");
            var requestedPeriods = DetectRequestedPeriodAxisLabels(query, "en");
            if (requestedDays.Count > 0 && requestedPeriods.Count > 0)
                return Math.Clamp(requestedDays.Count * requestedPeriods.Count, 1, 20);
        }

        return LooksLikeWeeklyPlanningRequest(query) ? 7 : 5;
    }

    private sealed record SourceBackedOptionCandidate(RagHitSummary Hit, string Title, int Score, int? VisibleMinutes);

    private sealed record SourceBackedOptionAnswerSelection(
        IReadOnlyList<SourceBackedOptionCandidate> Items,
        bool WantsTotalPairing,
        bool HasCertifiedTotalPair,
        int? RequestedMaxMinutes,
        int? VisibleTotalMinutes);

    private sealed record SourceBackedCountdownCandidate(RagHitSummary Hit, string Title, int Score, int? VisibleMinutes);

    private static bool LooksLikeSourceBackedCountdownPlanningRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var asksCountdown = Regex.IsMatch(
            normalized,
            @"\b(?:retroplanning|rebours|a\s+rebours|countdown|reverse\s+plan|backward\s+plan|planning\s+inverse|plan\s+inverse)\b",
            RegexOptions.CultureInvariant);
        var asksSchedule = Regex.IsMatch(
            normalized,
            @"\b(?:planning|plan|programme|horaire|schedule)\b",
            RegexOptions.CultureInvariant)
            && Regex.IsMatch(
                normalized,
                @"\b(?:preparation|preparer|procedure|process|operation|service|livraison|deliver|deadline|echeance|échéance|pret|prete|ready|start|finish|end)\b",
                RegexOptions.CultureInvariant);

        return (asksCountdown || asksSchedule)
            && (TryExtractRequestedClockTime(query).HasValue
                || Regex.IsMatch(normalized, @"\b\d{1,2}\s*h(?:\s*\d{2})?\b", RegexOptions.CultureInvariant));
    }

    private static string BuildSourceBackedCountdownPlanningAnswer(ToolResults toolResults, string query, string language)
    {
        language = NormalizeLanguageCode(language);
        var targetTime = TryExtractRequestedClockTime(query);
        if (!targetTime.HasValue)
            return string.Empty;

        var candidates = SelectSourceBackedCountdownPlanningCandidates(toolResults, query)
            .Take(6)
            .ToList();
        if (candidates.Count == 0)
            return string.Empty;

        var timed = candidates
            .Where(candidate => candidate.VisibleMinutes.HasValue)
            .OrderByDescending(candidate => candidate.VisibleMinutes!.Value)
            .ThenByDescending(candidate => candidate.Score)
            .Take(5)
            .ToList();
        if (timed.Count == 0)
            return string.Empty;

        var labels = language switch
        {
            "en" => (
                Header: "I do not have one selected item, so this reverse schedule only uses durations visible in the source excerpts:",
                Start: "start",
                Duration: "visible duration",
                Manual: "to place manually",
                Note: "If you choose the exact source items, I can rebuild a stricter schedule from those source pages only."),
            "es" => (
                Header: "No tengo un elemento unico seleccionado, asi que este plan inverso usa solo duraciones visibles en los extractos fuente:",
                Start: "iniciar",
                Duration: "duracion visible",
                Manual: "colocar manualmente",
                Note: "Si eliges los elementos exactos, puedo rehacer un planning mas estricto solo con esas paginas fuente."),
            "pt" => (
                Header: "Nao tenho um item unico selecionado, por isso este plano inverso usa apenas duracoes visiveis nos excertos fonte:",
                Start: "iniciar",
                Duration: "duracao visivel",
                Manual: "colocar manualmente",
                Note: "Se escolheres os itens exatos, posso refazer um plano mais rigoroso apenas com essas paginas fonte."),
            "de" => (
                Header: "Es ist kein einzelnes Element ausgewaehlt; dieser Rueckwaertsplan nutzt daher nur sichtbare Dauern aus den Quellenauszuegen:",
                Start: "starten",
                Duration: "sichtbare Dauer",
                Manual: "manuell einplanen",
                Note: "Wenn du die genauen Elemente auswaehlst, kann ich den Plan nur mit diesen Quellseiten strenger neu berechnen."),
            "it" => (
                Header: "Non ho un elemento unico selezionato, quindi questo piano a ritroso usa solo durate visibili negli estratti fonte:",
                Start: "avviare",
                Duration: "durata visibile",
                Manual: "da collocare manualmente",
                Note: "Se scegli gli elementi esatti, posso rifare un piano piu rigoroso solo da quelle pagine fonte."),
            _ => (
                Header: "Je n'ai pas un element unique selectionne ; ce retroplanning utilise donc uniquement les durees visibles dans les extraits sources :",
                Start: "lancer",
                Duration: "duree visible",
                Manual: "a caler manuellement",
                Note: "Si tu choisis les elements source exacts, je peux refaire un planning plus strict uniquement depuis ces pages source.")
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        foreach (var candidate in timed)
        {
            var startTime = targetTime.Value.Subtract(TimeSpan.FromMinutes(candidate.VisibleMinutes!.Value));
            while (startTime < TimeSpan.Zero)
                startTime += TimeSpan.FromDays(1);

            var hit = candidate.Hit;
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            sb.Append("- ");
            sb.Append(FormatClockTime(startTime));
            sb.Append(" : ");
            sb.Append(labels.Start);
            sb.Append(' ');
            sb.Append(candidate.Title);
            sb.Append(" (");
            sb.Append(labels.Duration);
            sb.Append(" : ");
            sb.Append(candidate.VisibleMinutes.Value.ToString(CultureInfo.InvariantCulture));
            sb.Append(" min, ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.AppendLine(")");
        }

        sb.AppendLine(labels.Note);
        return sb.ToString().TrimEnd();
    }

    private static IReadOnlyList<SourceBackedCountdownCandidate> SelectSourceBackedCountdownPlanningCandidates(ToolResults toolResults, string? query)
    {
        var sourceHits = EnumerateRagHitSummaries(toolResults)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(hit => !LooksLikeLowSignalAppFeatureHit(hit, query ?? string.Empty))
            .Where(hit => LooksLikeResolvedRouteTargetHit(hit) || !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();
        if (!string.IsNullOrWhiteSpace(query))
            sourceHits = FilterHitsToDominantTopLevel(sourceHits, query).ToList();

        return sourceHits
            .Select(hit =>
            {
                var title = ExtractSourceBackedOptionTitle(hit, query);
                if (string.IsNullOrWhiteSpace(title))
                    title = BuildCountdownFallbackTitle(hit);

                var visibleMinutes = ExtractBestVisibleDurationMinutes(hit);
                var score = ComputeRagHitLexicalRelevance(query ?? string.Empty, GetRagHitLookupText(hit))
                    + ComputeProcedureCompletenessCueScore(hit)
                    + ComputeStructuredProcedureEvidenceCueScore(hit)
                    + ComputeStructuredProcedureVisibleEvidenceCueScore(hit)
                    + (visibleMinutes.HasValue ? 18 : 0);
                if (LooksLikePageReferenceOnlyHit(hit))
                    score -= 25;
                if (LooksLikeMidProcedureFragment(hit))
                    score -= 6;

                return new SourceBackedCountdownCandidate(hit, title, score, visibleMinutes);
            })
            .Where(candidate => !string.IsNullOrWhiteSpace(candidate.Title))
            .Where(candidate => candidate.Score > 0)
            .OrderByDescending(candidate => candidate.VisibleMinutes.HasValue)
            .ThenByDescending(candidate => candidate.Score)
            .ThenByDescending(candidate => candidate.Hit.Score)
            .GroupBy(candidate => $"{NormalizeLexicalLookup(candidate.Title)}|{candidate.Hit.DocPath}|{candidate.Hit.PageStart}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .ToList();
    }

    private static string BuildCountdownFallbackTitle(RagHitSummary hit)
    {
        foreach (var raw in new[] { hit.SectionTitle, hit.HeadingPath })
        {
            var title = CleanSourceBackedOptionTitle(raw);
            if (IsUsableSourceBackedOptionTitle(title))
            {
                return title;
            }
        }

        var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? Path.GetFileName(hit.DocPath) : hit.DocName;
        return string.IsNullOrWhiteSpace(docLabel) ? "Element source" : docLabel;
    }

    private static TimeSpan? TryExtractRequestedClockTime(string? query)
    {
        var text = query ?? string.Empty;
        if (string.IsNullOrWhiteSpace(text))
            return null;

        foreach (var pattern in new[]
                 {
                     @"\b(?<h>[01]?\d|2[0-3])\s*h(?:\s*(?<m>[0-5]\d))?\b",
                     @"\b(?<h>[01]?\d|2[0-3])\s*[:.]\s*(?<m>[0-5]\d)\b",
                     @"\b(?<h>0?[1-9]|1[0-2])\s*(?<ampm>am|pm)\b"
                 })
        {
            var match = Regex.Match(text, pattern, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            if (!match.Success)
                continue;

            var hours = int.Parse(match.Groups["h"].Value, CultureInfo.InvariantCulture);
            var minutes = match.Groups["m"].Success
                ? int.Parse(match.Groups["m"].Value, CultureInfo.InvariantCulture)
                : 0;
            if (match.Groups["ampm"].Success)
            {
                var ampm = match.Groups["ampm"].Value.ToLowerInvariant();
                if (ampm == "pm" && hours < 12)
                    hours += 12;
                if (ampm == "am" && hours == 12)
                    hours = 0;
            }

            if (hours is >= 0 and <= 23 && minutes is >= 0 and <= 59)
                return new TimeSpan(hours, minutes, 0);
        }

        var normalized = NormalizeLexicalLookup(text);
        var looseMatch = Regex.Match(
            normalized,
            @"\b(?<h>[01]?\d|2[0-3])\s*h(?:\s*(?<m>[0-5]\d))?\b",
            RegexOptions.CultureInvariant);
        if (looseMatch.Success)
        {
            var hours = int.Parse(looseMatch.Groups["h"].Value, CultureInfo.InvariantCulture);
            var minutes = looseMatch.Groups["m"].Success
                ? int.Parse(looseMatch.Groups["m"].Value, CultureInfo.InvariantCulture)
                : 0;
            if (hours is >= 0 and <= 23 && minutes is >= 0 and <= 59)
                return new TimeSpan(hours, minutes, 0);
        }

        return null;
    }

    private static string FormatClockTime(TimeSpan value)
    {
        value = new TimeSpan((value.Hours + 24) % 24, value.Minutes, 0);
        return $"{value.Hours:00}h{value.Minutes:00}";
    }

    private static string BuildSourceBackedOptionAnswer(ToolResults toolResults, string language, int minItems = 1, string? query = null)
    {
        language = NormalizeLanguageCode(language);
        var missingPairingAnchor = TryBuildMissingPairingAnchorAnswer(toolResults, query ?? string.Empty, language);

        var selection = SelectSourceBackedOptionAnswerCandidates(toolResults, query, minItems, language);
        var optionItems = selection.Items.ToList();
        var requestedMaxMinutes = selection.RequestedMaxMinutes;
        var wantsTotalPairing = selection.WantsTotalPairing;

        if (!ShouldUseAdvisoryEvidenceGuardForBroadSynthesis(toolResults, query)
            && !string.IsNullOrWhiteSpace(missingPairingAnchor)
            && optionItems.Count == 0)
        {
            return missingPairingAnchor;
        }

        if (optionItems.Count == 0 || optionItems.Count < minItems)
            return string.Empty;

        var header = language switch
        {
            "en" => "Here are source-backed options found in the available documents:",
            "es" => "Aqui tienes opciones basadas en los documentos disponibles:",
            "pt" => "Aqui estao opcoes baseadas nos documentos disponiveis:",
            "de" => "Hier sind quellenbasierte Optionen aus den verfuegbaren Dokumenten:",
            "it" => "Ecco opzioni basate sui documenti disponibili:",
            _ => "Voici des options appuyees sur les documents disponibles :"
        };

        var sb = new StringBuilder();
        sb.AppendLine(header);
        var pairingLeadCaveat = BuildPairingLeadCaveat(query ?? string.Empty, language);
        if (!string.IsNullOrWhiteSpace(missingPairingAnchor) && !string.IsNullOrWhiteSpace(pairingLeadCaveat))
        {
            sb.AppendLine(pairingLeadCaveat);
        }
        else if (ShouldWarnNoExplicitPairing(query ?? string.Empty, optionItems.Select(static item => item.Hit).ToList()))
        {
            var pairingCaveat = language switch
            {
                "en" => "I did not find a passage that explicitly connects every part of the request, so I list these as documented options to verify, not as certified compatible recommendations.",
                "es" => "No he encontrado un pasaje que conecte explicitamente todas las partes de la solicitud; las enumero como pistas con fuente, no como recomendaciones compatibles certificadas.",
                "pt" => "Nao encontrei uma passagem que ligue explicitamente todas as partes do pedido; listo-as como pistas com fonte, nao como recomendacoes compativeis certificadas.",
                "de" => "Ich habe keine Stelle gefunden, die alle Teile der Anfrage ausdruecklich verbindet; ich liste sie daher als belegte Hinweise, nicht als bestaetigte kompatible Empfehlungen.",
                "it" => "Non ho trovato un passaggio che colleghi esplicitamente tutte le parti della richiesta; le elenco quindi come indicazioni con fonte, non come raccomandazioni compatibili certificate.",
                _ => "Je n'ai pas trouve de passage qui relie explicitement tous les elements de la demande ; je liste donc ces elements documentes a verifier, pas comme recommandations compatibles certifiees."
            };
            sb.AppendLine(AppendBroadenedSearchOfferIfHelpful(pairingCaveat, query, language));
        }

        if (wantsTotalPairing)
        {
            var requestedMaxMinutesValue = requestedMaxMinutes.GetValueOrDefault();
            var visibleCandidateTotal = !selection.HasCertifiedTotalPair
                && optionItems.Count >= 2
                && optionItems.All(static candidate => candidate.VisibleMinutes.HasValue)
                    ? optionItems.Sum(static candidate => candidate.VisibleMinutes!.Value)
                    : (int?)null;
            var pairingNote = (selection.HasCertifiedTotalPair, language) switch
            {
                (true, "en") => $"The visible durations fit the constraint: {selection.VisibleTotalMinutes} minutes total, within the requested {requestedMaxMinutesValue} minutes.",
                (true, "es") => $"Las duraciones visibles cumplen la restriccion: {selection.VisibleTotalMinutes} minutos en total, dentro de los {requestedMaxMinutesValue} minutos pedidos.",
                (true, "pt") => $"As duracoes visiveis respeitam a restricao: {selection.VisibleTotalMinutes} minutos no total, dentro dos {requestedMaxMinutesValue} minutos pedidos.",
                (true, "de") => $"Die sichtbaren Dauern erfuellen die Vorgabe: insgesamt {selection.VisibleTotalMinutes} Minuten, innerhalb der gewuenschten {requestedMaxMinutesValue} Minuten.",
                (true, "it") => $"Le durate visibili rispettano il vincolo: {selection.VisibleTotalMinutes} minuti totali, entro i {requestedMaxMinutesValue} minuti richiesti.",
                (true, _) => $"Les durees visibles respectent la contrainte : {selection.VisibleTotalMinutes} minutes au total, dans la limite demandee de {requestedMaxMinutesValue} minutes.",
                (false, "en") when visibleCandidateTotal.HasValue => $"I cannot certify the requested combined total under {requestedMaxMinutesValue} minutes: the visible total for the retained items is {visibleCandidateTotal.Value} minutes. I list them as documented options to verify, not as a compatible set.",
                (false, "es") when visibleCandidateTotal.HasValue => $"No puedo certificar el total combinado pedido en menos de {requestedMaxMinutesValue} minutos: el total visible de los elementos retenidos es {visibleCandidateTotal.Value} minutos. Los enumero como pistas con fuente, no como conjunto compatible.",
                (false, "pt") when visibleCandidateTotal.HasValue => $"Nao posso certificar o total combinado pedido em menos de {requestedMaxMinutesValue} minutos: o total visivel dos itens retidos e {visibleCandidateTotal.Value} minutos. Listo-os como pistas com fonte, nao como conjunto compativel.",
                (false, "de") when visibleCandidateTotal.HasValue => $"Ich kann die angefragte kombinierte Summe unter {requestedMaxMinutesValue} Minuten nicht bestaetigen: die sichtbare Summe der behaltenen Eintraege betraegt {visibleCandidateTotal.Value} Minuten. Ich liste sie als belegte Hinweise, nicht als kompatibles Set.",
                (false, "it") when visibleCandidateTotal.HasValue => $"Non posso certificare il totale combinato richiesto sotto {requestedMaxMinutesValue} minuti: il totale visibile degli elementi mantenuti e {visibleCandidateTotal.Value} minuti. Li elenco come piste con fonte, non come insieme compatibile.",
                (false, _) when visibleCandidateTotal.HasValue => $"Je ne peux pas certifier le total combine demande en moins de {requestedMaxMinutesValue} minutes : le total visible des elements retenus est de {visibleCandidateTotal.Value} minutes. Je les liste comme elements documentes a verifier, pas comme ensemble compatible.",
                (false, "en") => $"I do not have enough complete visible durations to guarantee the requested combined total under {requestedMaxMinutesValue} minutes; I only list source-backed components.",
                (false, "es") => $"No tengo suficientes duraciones completas visibles para garantizar el total combinado pedido en menos de {requestedMaxMinutesValue} minutos; solo enumero componentes con fuente.",
                (false, "pt") => $"Nao tenho duracoes completas visiveis suficientes para garantir o total combinado pedido em menos de {requestedMaxMinutesValue} minutos; listo apenas componentes com fonte.",
                (false, "de") => $"Ich habe nicht genug vollstaendige sichtbare Dauern, um die angefragte kombinierte Summe unter {requestedMaxMinutesValue} Minuten zu garantieren; ich liste nur belegte Bestandteile.",
                (false, "it") => $"Non ho durate complete visibili sufficienti per garantire il totale combinato richiesto sotto {requestedMaxMinutesValue} minuti; elenco solo componenti con fonte.",
                _ => $"Je n'ai pas assez de durees completes visibles pour garantir le total combine demande en moins de {requestedMaxMinutesValue} minutes ; je liste seulement des composants sources."
            };
            sb.AppendLine(pairingNote);
        }

        for (var i = 0; i < optionItems.Count; i++)
        {
            var hit = optionItems[i].Hit;
            var optionLabel = language switch
            {
                "es" => $"Opcion {i + 1}",
                "pt" => $"Opcao {i + 1}",
                "it" => $"Opzione {i + 1}",
                _ => $"Option {i + 1}"
            };

            sb.Append("- ");
            sb.Append(optionLabel);
            sb.Append(" : ");
            sb.Append(optionItems[i].Title);
            var visibleMinutes = optionItems[i].VisibleMinutes;
            if (visibleMinutes.HasValue)
            {
                sb.Append(" - ");
                sb.Append(visibleMinutes.Value.ToString(CultureInfo.InvariantCulture));
                sb.Append(' ');
                sb.Append(SourceBackedVisibleMinutesSuffix(language));
            }
            sb.Append(" (");
            sb.Append(string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(")");

            var evidence = ShouldRenderRawSourceBackedOptionEvidence(query)
                ? FormatSourceBackedOptionEvidence(hit)
                : string.Empty;
            if (!string.IsNullOrWhiteSpace(evidence))
            {
                sb.Append(" - ");
                sb.Append(evidence);
            }

            sb.AppendLine();
        }

        var note = language switch
        {
            "en" => "I keep quantities, timing, and substitutions tied to the source pages.",
            "es" => "Mantengo cantidades, tiempos y sustituciones ligados a las paginas fuente.",
            "pt" => "Mantenho quantidades, tempos e substituicoes ligados as paginas fonte.",
            "de" => "Mengen, Zeiten und Ersetzungen bleiben an die Quellseiten gebunden.",
            "it" => "Tengo quantita, tempi e sostituzioni legati alle pagine fonte.",
            _ => "Je garde les quantites, temps et substitutions rattaches aux pages source."
        };
        sb.AppendLine(note);

        return sb.ToString().TrimEnd();
    }

    private static bool ShouldRenderRawSourceBackedOptionEvidence(string? query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return true;

        return !IsBroadenedSourceSearchConfirmationEnvelope(query)
            && !LooksLikeGenericCollectionOrListRequest(query)
            && !LooksLikeAnyDocumentaryPlanningRequest(query)
            && !LooksLikeBroadSynthesisRequestShape(query)
            && !LooksLikeBroadSourceBackedCompositionRequest(query)
            && !LooksLikeMultipleCandidateSynthesisRequest(query)
            && !LooksLikeSoftChoiceRecommendationRequest(query)
            && !LooksLikeSourceBackedPairingRecommendationRequest(query);
    }

    private static SourceBackedOptionAnswerSelection SelectSourceBackedOptionAnswerCandidates(
        ToolResults toolResults,
        string? query,
        int minItems,
        string language = "")
    {
        var allOptionItems = SelectSourceBackedOptionCandidates(toolResults, query, keepOverRequestedDuration: true, language: language)
            .ToList();
        var requestedMaxMinutes = TryExtractRequestedMaxMinutes(query);
        var wantsTotalPairing = LooksLikeTotalDurationConstraintRequest(query, requestedMaxMinutes);

        if (!wantsTotalPairing)
        {
            return new SourceBackedOptionAnswerSelection(
                allOptionItems.Take(5).ToList(),
                WantsTotalPairing: false,
                HasCertifiedTotalPair: false,
                RequestedMaxMinutes: requestedMaxMinutes,
                VisibleTotalMinutes: null);
        }

        var timedItems = allOptionItems
            .Where(candidate => candidate.VisibleMinutes.HasValue)
            .Where(candidate => candidate.VisibleMinutes!.Value <= requestedMaxMinutes!.Value)
            .ToList();
        var requiredItems = wantsTotalPairing ? Math.Max(2, minItems) : Math.Max(1, minItems);
        var combined = SelectSourceBackedCombinedDurationSet(timedItems, requiredItems, requestedMaxMinutes!.Value);
        if (combined.Count >= requiredItems)
        {
            return new SourceBackedOptionAnswerSelection(
                combined,
                WantsTotalPairing: true,
                HasCertifiedTotalPair: true,
                RequestedMaxMinutes: requestedMaxMinutes,
                VisibleTotalMinutes: combined.Sum(static candidate => candidate.VisibleMinutes!.Value));
        }

        var fallbackSet = allOptionItems.Take(requiredItems).ToList();
        if (fallbackSet.Count >= requiredItems)
        {
            return new SourceBackedOptionAnswerSelection(
                fallbackSet,
                WantsTotalPairing: true,
                HasCertifiedTotalPair: false,
                RequestedMaxMinutes: requestedMaxMinutes,
                VisibleTotalMinutes: null);
        }

        var fallbackItems = timedItems.Count >= requiredItems
            ? timedItems.Take(5).ToList()
            : allOptionItems.Take(5).ToList();
        return new SourceBackedOptionAnswerSelection(
            fallbackItems,
            WantsTotalPairing: true,
            HasCertifiedTotalPair: false,
            RequestedMaxMinutes: requestedMaxMinutes,
            VisibleTotalMinutes: null);
    }

    private static bool LooksLikeTotalDurationConstraintRequest(string? query, int? requestedMaxMinutes)
    {
        if (!requestedMaxMinutes.HasValue || string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = NormalizeLexicalLookup(query);
        return Regex.IsMatch(
            normalized,
            @"\b(?:total|combined|combine|combinee|combin[eé]e|ensemble|overall|cumul|cumulative|cumule|cumul[eé])\b",
            RegexOptions.CultureInvariant)
            || (LooksLikeSourceBackedOptionRequest(query)
                && Regex.IsMatch(normalized, @"(?:\+|\b(?:et|and)\b)", RegexOptions.CultureInvariant));
    }

    private static IReadOnlyList<SourceBackedOptionCandidate> SelectSourceBackedCombinedDurationSet(
        IReadOnlyList<SourceBackedOptionCandidate> candidates,
        int minItems,
        int requestedMaxMinutes)
    {
        var selected = new List<SourceBackedOptionCandidate>();
        var total = 0;
        foreach (var candidate in candidates
            .Where(static candidate => candidate.VisibleMinutes.HasValue)
            .OrderByDescending(static candidate => candidate.Score))
        {
            if (total + candidate.VisibleMinutes!.Value > requestedMaxMinutes)
                continue;
            selected.Add(candidate);
            total += candidate.VisibleMinutes.Value;
            if (selected.Count >= minItems)
                break;
        }

        return selected.Count >= minItems ? selected : Array.Empty<SourceBackedOptionCandidate>();
    }

    private static IReadOnlyList<SourceBackedOptionCandidate> SelectSourceBackedOptionCandidates(
        ToolResults toolResults,
        string? query,
        bool keepOverRequestedDuration = false,
        string language = "")
    {
        var normalizedQuery = NormalizeLexicalLookup(query);
        var broadCollectionLikeRequest = LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query);
        var namedEntityTerms = ExtractNamedEntityLikeQueryTerms(query);
        var softChoiceOptionKindTerms = ExtractSoftChoiceRequestedOptionKindTerms(query);
        var requiresNamedEntityEvidence = namedEntityTerms.Count > 0
            && !broadCollectionLikeRequest
            && !LooksLikeSourceBackedPairingRecommendationRequest(query)
            && Regex.IsMatch(normalizedQuery, @"\b(?:uniquement|only|avec|with|using|utiliser|utilise|concernant|about|sur)\b", RegexOptions.CultureInvariant);
        var sourceHits = EnumerateRagHitSummaries(toolResults)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(hit => !LooksLikeLowSignalAppFeatureHit(hit, query ?? string.Empty))
            .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();

        if (!string.IsNullOrWhiteSpace(query))
            sourceHits = FilterHitsToDominantTopLevel(sourceHits, query).ToList();

        var maxMinutes = TryExtractRequestedMaxMinutes(query);
        var objectAnchorTerms = ExtractSourceBackedOptionObjectAnchorTerms(query)
            .Where(static term => term.Length >= 5)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !SourceBackedOptionConstraintTerms.Contains(term))
            .Distinct(StringComparer.Ordinal)
            .Take(5)
            .ToArray();
        var queryAnchorTerms = ExtractQuerySignalTerms(normalizedQuery)
            .Concat(objectAnchorTerms)
            .Where(static term => term.Length >= 5)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !SourceBackedOptionConstraintTerms.Contains(term))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        var hasConcreteObjectAnchor = objectAnchorTerms.Length > 0;
        var hasSourceBackedAnchorEvidence = queryAnchorTerms.Length > 0
            && (!broadCollectionLikeRequest || hasConcreteObjectAnchor)
            && !LooksLikeCompositeSourceBackedOptionAnchorRequest(normalizedQuery, maxMinutes.HasValue)
            && !LooksLikeSourceBackedPairingRecommendationRequest(query)
            && sourceHits.Any(hit => QueryAnchorTermsMatchHit(queryAnchorTerms, hit));

        var candidates = sourceHits
            .SelectMany(hit => BuildSourceBackedOptionCandidatesFromHit(
                hit,
                query,
                language,
                keepOverRequestedDuration ? null : maxMinutes,
                requiresNamedEntityEvidence,
                namedEntityTerms))
            .Where(candidate => !string.IsNullOrWhiteSpace(candidate.Title))
            .Where(candidate => !LooksLikeLowValueSourceBackedOptionCandidate(candidate, normalizedQuery))
            .Where(candidate => LooksLikeUsableSourceBackedOptionCandidate(candidate.Hit))
            .Where(candidate => keepOverRequestedDuration || !maxMinutes.HasValue || !candidate.VisibleMinutes.HasValue || candidate.VisibleMinutes.Value <= maxMinutes.Value)
            .Select(candidate => ApplySoftChoiceOptionKindScore(candidate, softChoiceOptionKindTerms))
            .Where(candidate => candidate.Score > -20)
            .OrderByDescending(candidate => candidate.Score)
            .ThenByDescending(candidate => candidate.Hit.Score)
            .GroupBy(candidate => $"{NormalizeLexicalLookup(candidate.Title)}|{candidate.Hit.DocPath}|{candidate.Hit.PageStart}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .ToList();

        var excludedTerms = ExtractSourceBackedExcludedTerms(query);
        if (excludedTerms.Count > 0)
        {
            candidates = candidates
                .Where(candidate => !RagHitContainsAnyExcludedTerm(candidate.Hit, excludedTerms))
                .ToList();
        }

        var pairingOptionKindTerms = ExtractPairingRequestedOptionKindTerms(query);
        if (pairingOptionKindTerms.Count > 0 && candidates.Count > 1)
        {
            var kindMatchedCandidates = candidates
                .Where(candidate => PairingOptionKindMatchesCandidate(pairingOptionKindTerms, candidate))
                .ToList();
            if (kindMatchedCandidates.Count > 0)
                candidates = kindMatchedCandidates;
        }

        if (softChoiceOptionKindTerms.Count > 0 && candidates.Count > 1)
        {
            var kindMatchedCandidates = candidates
                .Where(candidate => SoftChoiceOptionKindMatchesCandidate(softChoiceOptionKindTerms, candidate))
                .ToList();
            if (kindMatchedCandidates.Count > 0)
            {
                var kindMatchedKeys = kindMatchedCandidates
                    .Select(BuildSourceBackedOptionCandidateKey)
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);
                candidates = candidates
                    .Where(candidate => kindMatchedKeys.Contains(BuildSourceBackedOptionCandidateKey(candidate))
                        || IsPrimaryQueryTopConcreteCardCandidate(candidate))
                    .ToList();
            }

            candidates = candidates
                .Where(candidate => !OptionKindContradictsCandidate(softChoiceOptionKindTerms, candidate))
                .ToList();
        }

        if (hasSourceBackedAnchorEvidence)
        {
            candidates = candidates
                .Where(candidate => QueryAnchorTermsMatchHit(queryAnchorTerms, candidate.Hit))
                .ToList();
        }

        if (requiresNamedEntityEvidence)
        {
            candidates = candidates
                .Where(candidate => QueryAnchorTermsMatchHit(namedEntityTerms, candidate.Hit))
                .ToList();
        }

        return candidates;
    }

    private static IEnumerable<string> ExtractSourceBackedOptionObjectAnchorTerms(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            yield break;

        foreach (Match match in Regex.Matches(
                     normalized,
                     @"\b(?:pour|for|para|per|sur|about|concernant|regarding|avec|with|con|com|mit)\s+(?:le|la|les|l['\u2019]?|un|une|des|du|de\s+la|de\s+l['\u2019]?|the|a|an|some)?\s*(?<target>[\p{L}\p{N}'\u2019-]{3,60}(?:\s+[\p{L}\p{N}'\u2019-]{2,40}){0,3})",
                     RegexOptions.CultureInvariant))
        {
            var target = NormalizeLexicalLookup(match.Groups["target"].Value);
            foreach (var term in ExtractQuerySignalTerms(target)
                         .Where(static term => term.Length >= 4)
                         .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
                         .Where(static term => !SourceBackedOptionConstraintTerms.Contains(term)))
            {
                yield return term;
            }
        }
    }

    private static string BuildPairingLeadCaveat(string query, string language)
    {
        var targetTerms = ExtractPairingTargetAnchorTerms(query);
        if (targetTerms.Count == 0)
            return string.Empty;

        var optionKindTerms = ExtractPairingRequestedOptionKindTerms(query);
        var targetList = string.Join(", ", targetTerms.Select(static term => $"\"{term}\""));
        var optionKindList = optionKindTerms.Count > 0
            ? string.Join(", ", optionKindTerms.Select(static term => $"\"{term}\""))
            : SourceBackedLabel(language, "la demande", "the request", "la solicitud", "o pedido", "die Anfrage", "la richiesta");

        var answer = SourceBackedLabel(
            language,
            $"Je n'ai pas trouve de passage qui relie explicitement {targetList} a {optionKindList}. Je liste donc ces elements documentes a verifier, pas comme compatibilite certifiee.",
            $"I did not find a passage that explicitly connects {targetList} to {optionKindList}. I therefore list these items as documented options to verify, not as certified compatibility.",
            $"No he encontrado un pasaje que conecte explicitamente {targetList} con {optionKindList}. Por eso enumero estos elementos como pistas con fuente, no como compatibilidad certificada.",
            $"Nao encontrei uma passagem que ligue explicitamente {targetList} a {optionKindList}. Por isso listo estes elementos como pistas com fonte, nao como compatibilidade certificada.",
            $"Ich habe keine Stelle gefunden, die {targetList} ausdruecklich mit {optionKindList} verbindet. Deshalb liste ich diese Punkte als belegte Hinweise, nicht als bestaetigte Kompatibilitaet.",
            $"Non ho trovato un passaggio che colleghi esplicitamente {targetList} a {optionKindList}. Li elenco quindi come indicazioni con fonte, non come compatibilita certificata.");
        return AppendBroadenedSearchOfferIfHelpful(answer, query, language);
    }

    private static IEnumerable<SourceBackedOptionCandidate> BuildSourceBackedOptionCandidatesFromHit(
        RagHitSummary hit,
        string? query,
        string language,
        int? scoreMaxMinutes,
        bool requiresNamedEntityEvidence,
        IReadOnlyList<string> namedEntityTerms)
    {
        var emittedCardCandidate = false;
        foreach (var card in hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
        {
            var title = CleanSourceBackedOptionTitle(card.Title);
            if (!IsUsableSourceBackedOptionTitle(title))
            {
                continue;
            }

            var scopedHit = BuildSourceBackedCardScopedHit(hit, card);
            var visibleMinutes = ExtractBestVisibleDurationMinutes(scopedHit);
            emittedCardCandidate = true;
            yield return new SourceBackedOptionCandidate(
                scopedHit,
                title,
                ComputeSourceBackedOptionHitScore(scopedHit, title, query, scoreMaxMinutes, visibleMinutes) + 6,
                visibleMinutes);
        }

        if (emittedCardCandidate)
            yield break;

        var fallbackTitle = ExtractSourceBackedOptionTitle(hit, query);
        var fallbackTitleIsGeneratedFromNamedEntityEvidence = false;
        if (string.IsNullOrWhiteSpace(fallbackTitle)
            && requiresNamedEntityEvidence
            && QueryAnchorTermsMatchHit(namedEntityTerms, hit))
        {
            fallbackTitle = BuildSourceBackedFallbackOptionTitle(hit, language);
            fallbackTitleIsGeneratedFromNamedEntityEvidence = true;
        }

        if (!string.IsNullOrWhiteSpace(fallbackTitle)
            && !IsUsableSourceBackedOptionTitle(fallbackTitle)
            && !fallbackTitleIsGeneratedFromNamedEntityEvidence)
        {
            yield break;
        }

        var fallbackVisibleMinutes = ExtractBestVisibleDurationMinutes(hit);
        yield return new SourceBackedOptionCandidate(
            hit,
            fallbackTitle,
            ComputeSourceBackedOptionHitScore(hit, fallbackTitle, query, scoreMaxMinutes, fallbackVisibleMinutes),
            fallbackVisibleMinutes);
    }

    private static RagHitSummary BuildSourceBackedCardScopedHit(RagHitSummary hit, RagHitContentCardSummary card)
    {
        var pageStart = card.PageStart ?? hit.PageStart;
        var pageEnd = card.PageEnd ?? card.PageStart ?? hit.PageEnd;
        if (pageEnd < pageStart)
            pageEnd = pageStart;

        var cardEvidence = BuildSourceBackedCardEvidenceSnippet(card);
        return hit with
        {
            PageStart = pageStart,
            PageEnd = pageEnd,
            Excerpt = string.IsNullOrWhiteSpace(cardEvidence) ? card.Title : cardEvidence,
            FullText = null,
            ContextualSnippet = BuildSourceBackedCardContextSnippet(hit, card, cardEvidence),
            MatchedContentCards = new[] { card }
        };
    }

    private static string BuildSourceBackedCardContextSnippet(RagHitSummary hit, RagHitContentCardSummary card, string cardEvidence)
    {
        return CollapseWhitespace(string.Join(' ', new[]
        {
            $"Matched profile title: {card.Title}",
            string.IsNullOrWhiteSpace(hit.DocName) ? null : $"Document: {hit.DocName}",
            string.IsNullOrWhiteSpace(hit.SectionTitle) ? null : $"Section: {hit.SectionTitle}",
            string.IsNullOrWhiteSpace(cardEvidence) ? null : $"Evidence: {cardEvidence}"
        }.Where(static value => !string.IsNullOrWhiteSpace(value))));
    }

    private static string BuildSourceBackedCardEvidenceSnippet(RagHitContentCardSummary card)
    {
        var parts = new List<string> { card.Title };

        var evidence = card.Evidence;
        if (evidence is null)
            return CollapseWhitespace(card.Title);

        if (card.Signals is { Count: > 0 })
            parts.AddRange(card.Signals.Take(8));

        if (evidence is not null)
        {
            if (evidence.ScaleBasis is { Count: > 0 } basis)
            {
                parts.Add(CollapseWhitespace(string.Join(' ', new[]
                {
                    basis.Count.ToString(CultureInfo.InvariantCulture),
                    basis.Label
                }.Where(static value => !string.IsNullOrWhiteSpace(value)))));
            }

            foreach (var fact in evidence.QuantityFacts.Take(6))
            {
                parts.Add(CollapseWhitespace(string.Join(' ', new[]
                {
                    fact.Value.ToString("0.###", CultureInfo.InvariantCulture),
                    fact.Unit,
                    fact.Label,
                    fact.SourceText
                }.Where(static value => !string.IsNullOrWhiteSpace(value)))));
            }

            foreach (var fact in (evidence.Facts ?? []).Take(8))
            {
                parts.Add(CollapseWhitespace(string.Join(' ', new[]
                {
                    fact.Kind,
                    fact.Label,
                    fact.Value,
                    fact.Unit,
                    fact.SourceText
                }.Where(static value => !string.IsNullOrWhiteSpace(value)))));
            }

            parts.AddRange(evidence.NonScalableReasons.Take(4));
        }

        return CollapseWhitespace(string.Join(' ', parts.Where(static value => !string.IsNullOrWhiteSpace(value))));
    }

    private static SourceBackedOptionCandidate ApplySoftChoiceOptionKindScore(
        SourceBackedOptionCandidate candidate,
        IReadOnlyList<string> requestedKindTerms)
    {
        if (requestedKindTerms.Count == 0)
            return candidate;

        var bonus = ComputeSoftChoiceOptionKindMatchScore(requestedKindTerms, candidate);
        return bonus == 0
            ? candidate
            : candidate with { Score = candidate.Score + bonus };
    }

    private static bool LooksLikeCompositeSourceBackedOptionAnchorRequest(string normalizedQuery, bool hasRequestedMaxMinutes)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            return false;
        if (hasRequestedMaxMinutes || normalizedQuery.Contains('+', StringComparison.Ordinal))
            return true;

        return Regex.IsMatch(
            normalizedQuery,
            @"\b(?:total|combine|combiner|combined|ensemble|together|complet|complete|completa|completo)\b",
            RegexOptions.CultureInvariant);
    }

    private static IReadOnlyList<string> ExtractPairingRequestedOptionKindTerms(string? query)
    {
        if (!LooksLikeSourceBackedPairingRecommendationRequest(query))
            return Array.Empty<string>();

        var normalized = NormalizeLexicalLookup(query);
        var terms = new List<string>();
        foreach (Match match in Regex.Matches(
            normalized,
            @"\b(?:quel|quelle|quels|quelles|which|what|cual|cu[aá]l|qual|welche|welcher|welches|quale)\s+(?<kind>[\p{L}][\p{L}'\u2019-]{2,30})",
            RegexOptions.CultureInvariant))
        {
            var kind = NormalizeLexicalLookup(match.Groups["kind"].Value);
            if (kind.Length >= 4 && !IsSourceBackedActionRetrievalNoiseTerm(kind))
                terms.Add(kind);
        }

        foreach (Match match in Regex.Matches(
            normalized,
            @"\b(?:quel|quelle|quels|quelles|which|what|cual|cu[aÃ¡]l|qual|welche|welcher|welches|quale)\s+(?<kinds>[\p{L}\s'\u2019-]{3,90}?)(?=\s+(?:trouve|trouves|trouv[eé]s|dans|pour|avec|qui|que|would|could|found|in|for|with|para|con|com|mit|per|irait|iraient|vont|goes?|pair|pairs?|compatible)\b|[?.!,;:]|$)",
            RegexOptions.CultureInvariant))
        {
            var kinds = NormalizeLexicalLookup(match.Groups["kinds"].Value);
            foreach (var kind in Regex.Split(kinds, @"\s+(?:et|ou|and|or|y|e|und|oder|o)\s+", RegexOptions.CultureInvariant))
            {
                var cleanKind = NormalizeLexicalLookup(kind);
                if (cleanKind.Length >= 4 && !IsSourceBackedActionRetrievalNoiseTerm(cleanKind))
                    terms.Add(cleanKind);
            }
        }

        return terms
            .Distinct(StringComparer.Ordinal)
            .Take(5)
            .ToArray();
    }

    private static IReadOnlyList<string> ExtractSoftChoiceRequestedOptionKindTerms(string? query)
    {
        if (!LooksLikeSoftChoiceRecommendationRequest(query))
            return Array.Empty<string>();

        var normalized = NormalizeLexicalLookup(query);
        var terms = new List<string>();
        foreach (Match match in Regex.Matches(
            normalized,
            @"\b(?:quel|quelle|quels|quelles|which|what|cual|qual|welche|welcher|welches|quale)\s+(?<kind>[\p{L}][\p{L}'\u2019-]{2,30})",
            RegexOptions.CultureInvariant))
        {
            var kind = NormalizeLexicalLookup(match.Groups["kind"].Value);
            if (kind.Length >= 4 && !IsSourceBackedActionRetrievalNoiseTerm(kind))
                terms.Add(kind);
        }

        foreach (Match match in Regex.Matches(
            normalized,
            @"\b(?:quel|quelle|quels|quelles|which|what|cual|cu[aÃ¡]l|qual|welche|welcher|welches|quale)\s+(?<kinds>[\p{L}\s'\u2019-]{3,90}?)(?=\s+(?:trouve|trouves|trouves|dans|pour|avec|qui|que|would|could|found|in|for|with|para|con|com|mit|per)\b|[?.!,;:]|$)",
            RegexOptions.CultureInvariant))
        {
            var kinds = NormalizeLexicalLookup(match.Groups["kinds"].Value);
            foreach (var kind in Regex.Split(kinds, @"\s+(?:et|ou|and|or|y|e|und|oder|o)\s+", RegexOptions.CultureInvariant))
            {
                var cleanKind = NormalizeLexicalLookup(kind);
                if (cleanKind.Length >= 4 && !IsSourceBackedActionRetrievalNoiseTerm(cleanKind))
                    terms.Add(cleanKind);
            }
        }

        return terms
            .Distinct(StringComparer.Ordinal)
            .Take(5)
            .ToArray();
    }

    private static IReadOnlyList<string> ExtractGenericSourceBackedOptionKindTerms(string? query)
    {
        if (!LooksLikeSourceBackedOptionRequest(query))
            return Array.Empty<string>();

        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var terms = new List<string>();
        foreach (Match match in Regex.Matches(
            normalized,
            @"\b(?:liste|list|lista|elenco|auflistung)\s+(?:de|des|d|of|di|von|van)?\s*(?<kinds>[\p{L}\s'\u2019-]{3,80}?)(?=\s+(?:disponible|disponibles|available|trouve|trouves|trouver|dans|source|sources|document|documents|dossier|corpus|base)\b|[?.!,;:]|$)",
            RegexOptions.CultureInvariant))
        {
            AddGenericSourceBackedOptionKindTerms(terms, match.Groups["kinds"].Value);
        }

        foreach (Match match in Regex.Matches(
            normalized,
            @"\b(?:options?|suggestions?|idees?|ideas?|examples?|exemples?|candidats?|candidates?)\s+(?:de|des|d|of|di|pour|for|para|per|von)?\s*(?<kinds>[\p{L}\s'\u2019-]{3,80}?)(?=\s+(?:disponible|disponibles|available|trouve|trouves|trouver|dans|source|sources|document|documents|dossier|corpus|base)\b|[?.!,;:]|$)",
            RegexOptions.CultureInvariant))
        {
            AddGenericSourceBackedOptionKindTerms(terms, match.Groups["kinds"].Value);
        }

        return terms
            .Distinct(StringComparer.Ordinal)
            .Take(5)
            .ToArray();
    }

    private static void AddGenericSourceBackedOptionKindTerms(List<string> terms, string? rawKinds)
    {
        var normalized = NormalizeLexicalLookup(rawKinds);
        if (string.IsNullOrWhiteSpace(normalized))
            return;

        foreach (var rawKind in Regex.Split(normalized, @"\s+(?:et|ou|and|or|y|e|und|oder|o)\s+", RegexOptions.CultureInvariant))
        {
            var kind = NormalizeGenericSourceBackedOptionKindTerm(rawKind);
            if (kind.Length >= 4
                && !IsSourceBackedActionRetrievalNoiseTerm(kind)
                && !IsGenericPlanningCoverageTerm(kind)
                && !IsNavigationDiscoveryNoiseTerm(kind))
            {
                terms.Add(kind);
            }
        }
    }

    private static string NormalizeGenericSourceBackedOptionKindTerm(string? value)
    {
        var normalized = NormalizeLexicalLookup(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return string.Empty;

        normalized = Regex.Replace(
            normalized,
            @"\b(?:juste|uniquement|seulement|only|available|disponible|disponibles|trouve|trouves|trouver|source|sources|document|documents|dossier|corpus|base|dans|from|with|avec)\b",
            " ",
            RegexOptions.CultureInvariant);
        return CollapseWhitespace(normalized);
    }

    private static bool PairingOptionKindMatchesCandidate(IReadOnlyList<string> optionKindTerms, SourceBackedOptionCandidate candidate)
    {
        if (optionKindTerms.Count == 0)
            return true;

        var haystack = NormalizeLexicalLookup($"{candidate.Title} {candidate.Hit.SectionTitle} {candidate.Hit.HeadingPath} {GetRagHitPrimaryEvidenceText(candidate.Hit)}");
        return optionKindTerms.Any(term =>
            Regex.IsMatch(
                haystack,
                $@"(^|[^\p{{L}}\p{{N}}]){Regex.Escape(term)}(?:s|es)?([^\p{{L}}\p{{N}}]|$)",
                RegexOptions.CultureInvariant));
    }

    private static int ComputeSoftChoiceOptionKindMatchScore(IReadOnlyList<string> requestedKindTerms, SourceBackedOptionCandidate candidate)
    {
        if (requestedKindTerms.Count == 0)
            return 0;

        var titleAndCards = NormalizeLexicalLookup(
            $"{candidate.Title} {string.Join(' ', candidate.Hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>())}");
        var cardSignals = NormalizeLexicalLookup(
            string.Join(' ', candidate.Hit.MatchedContentCards?.SelectMany(static card => card.Signals ?? Array.Empty<string>()) ?? Array.Empty<string>()));
        var structural = NormalizeLexicalLookup($"{candidate.Hit.SectionTitle} {candidate.Hit.HeadingPath}");

        if (requestedKindTerms.Any(term => OptionKindTermMatchesText(titleAndCards, term)))
            return 18;
        if (requestedKindTerms.Any(term => OptionKindTermMatchesText(cardSignals, term)))
            return 16;
        if (requestedKindTerms.Any(term => OptionKindTermMatchesText(structural, term)))
            return 10;
        return 0;
    }

    private static bool SoftChoiceOptionKindMatchesCandidate(IReadOnlyList<string> requestedKindTerms, SourceBackedOptionCandidate candidate)
    {
        if (requestedKindTerms.Count == 0)
            return true;

        var haystack = NormalizeLexicalLookup(string.Join(' ', new[]
        {
            candidate.Title,
            candidate.Hit.SectionTitle,
            candidate.Hit.HeadingPath,
            string.Join(' ', candidate.Hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>()),
            string.Join(' ', candidate.Hit.MatchedContentCards?.SelectMany(static card => card.Signals ?? Array.Empty<string>()) ?? Array.Empty<string>())
        }.Where(static value => !string.IsNullOrWhiteSpace(value))));

        return requestedKindTerms.Any(term => OptionKindTermMatchesText(haystack, term));
    }

    private static bool OptionKindContradictsCandidate(IReadOnlyList<string> requestedKindTerms, SourceBackedOptionCandidate candidate)
    {
        if (requestedKindTerms.Count == 0)
            return false;

        var requested = requestedKindTerms
            .Select(NormalizeLexicalLookup)
            .Where(static term => term.Length >= 4)
            .ToHashSet(StringComparer.Ordinal);
        if (requested.Count == 0)
            return false;

        if (SoftChoiceOptionKindMatchesCandidate(requested.ToArray(), candidate))
            return false;

        return false;
    }

    private static bool OptionKindTermMatchesText(string? text, string? term)
    {
        var normalizedText = NormalizeLexicalLookup(text);
        var normalizedTerm = NormalizeLexicalLookup(term);
        if (string.IsNullOrWhiteSpace(normalizedText) || normalizedTerm.Length < 3)
            return false;

        if (normalizedText.Contains(normalizedTerm, StringComparison.Ordinal))
            return true;

        var singular = normalizedTerm.TrimEnd('s');
        if (singular.Length >= 3 && !string.Equals(singular, normalizedTerm, StringComparison.Ordinal))
        {
            if (normalizedText.Contains(singular, StringComparison.Ordinal))
                return true;
        }

        return Regex.IsMatch(
            normalizedText,
            $@"(^|[^\p{{L}}\p{{N}}]){Regex.Escape(normalizedTerm)}(?:s|es)?([^\p{{L}}\p{{N}}]|$)",
            RegexOptions.CultureInvariant);
    }

    private static bool RetrievalQueryNarrowlyTargetsOptionKind(string? retrievalQuery, string? term)
    {
        var normalizedQuery = NormalizeLexicalLookup(retrievalQuery);
        var normalizedTerm = NormalizeLexicalLookup(term);
        if (string.IsNullOrWhiteSpace(normalizedQuery) || normalizedTerm.Length < 3)
            return false;

        if (!OptionKindTermMatchesText(normalizedQuery, normalizedTerm))
            return false;

        var terms = ExtractQuerySignalTerms(normalizedQuery)
            .Where(static value => !IsSourceBackedActionRetrievalNoiseTerm(value))
            .ToArray();
        if (terms.Length == 0 || terms.Length > 3)
            return false;

        return terms.Any(value => OptionKindTermMatchesText(value, normalizedTerm));
    }

    private static bool LooksLikeUsableSourceBackedOptionCandidate(RagHitSummary hit)
    {
        var profile = ClassifyRagHitEvidenceProfile(hit);
        var backendRole = NormalizeRagEvidenceRole(hit.SelectionHintRole);
        if (!string.IsNullOrWhiteSpace(backendRole)
            && backendRole != "actionable_item"
            && !IsPrimaryQueryTopConcreteCardHit(hit))
        {
            return false;
        }

        if (profile.Role is "navigation" or "fragment" or "low_confidence")
            return false;

        var text = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        var evidence = NormalizeLexicalLookup($"{GetRagHitPrimaryEvidenceText(hit)} {hit.ContextualSnippet}");
        if (Regex.IsMatch(evidence, @"\b(?:a\s*pplication|application|communaute|community|carnets?|noter|notez|commenter|partagez|partager|share|rating|account)\b", RegexOptions.CultureInvariant)
            && ComputeStructuredProcedureVisibleEvidenceCueScore(hit) <= 0
            && CountProcedureStepMarkers(text) <= 0)
        {
            return false;
        }

        if (ComputeStructuredProcedureVisibleEvidenceCueScore(hit) >= 5)
            return true;
        if (ComputeProcedureCompletenessCueScore(hit) >= 7)
            return true;
        if (profile.ActionabilityScore >= 9)
            return true;
        if (ExtractBestVisibleDurationMinutes(hit).HasValue && ComputeStructuredProcedureVisibleEvidenceCueScore(hit) >= 3)
            return true;
        if (ExtractBestVisibleDurationMinutes(hit).HasValue && HasSourceBackedProfileTitle(hit))
            return true;
        if (ExtractBestVisibleDurationMinutes(hit).HasValue && CountProcedureStepMarkers(text) >= 2)
            return true;

        var title = ExtractSourceBackedOptionTitle(hit, query: null);
        if (!string.IsNullOrWhiteSpace(title)
            && IsUsableSourceBackedOptionTitle(title)
            && (hit.Score >= 0.5
                || ComputeEvidenceShapeScore(hit, GetRagHitLookupText(hit), includeBackendHints: true) >= 3))
        {
            return true;
        }

        return false;
    }

    private static bool LooksLikeLowValueSourceBackedOptionCandidate(
        SourceBackedOptionCandidate candidate,
        string normalizedQuery)
    {
        var title = CleanSourceBackedOptionTitle(candidate.Title);
        var hasConcreteTitle = IsUsableSourceBackedOptionTitle(title)
            && !LooksLikeWeakSourceBackedOptionTitle(title);
        if (!hasConcreteTitle)
            return true;

        var normalizedTitle = NormalizeLexicalLookup(title);
        if (string.IsNullOrWhiteSpace(normalizedTitle))
            return true;

        var evidence = NormalizeLexicalLookup($"{GetRagHitPrimaryEvidenceText(candidate.Hit)} {candidate.Hit.ContextualSnippet}");
        if (LooksLikeNavigationOnlyHit(candidate.Hit)
            && !LooksLikeResolvedRouteTargetHit(candidate.Hit)
            && !QueryAnchorTermsMatchHit(ExtractQuerySignalTerms(normalizedQuery).Take(6).ToArray(), candidate.Hit))
        {
            return true;
        }

        if (LooksLikeLowValueMarketingOrDocumentHeading(normalizedTitle)
            && ComputeStructuredProcedureVisibleEvidenceCueScore(candidate.Hit) <= 0
            && ComputeProcedureCompletenessCueScore(candidate.Hit) < 7)
        {
            return true;
        }

        if (LooksLikeNoisyCandidateSupportCue(title)
            && !HasSourceBackedProfileTitle(candidate.Hit)
            && ComputeStructuredProcedureVisibleEvidenceCueScore(candidate.Hit) < 1
            && ComputeProcedureCompletenessCueScore(candidate.Hit) < 1)
        {
            return true;
        }

        if (LooksLikeNoisyCandidateSupportCue(evidence)
            && !HasSourceBackedProfileTitle(candidate.Hit)
            && ComputeStructuredProcedureVisibleEvidenceCueScore(candidate.Hit) < 3
            && ComputeProcedureCompletenessCueScore(candidate.Hit) < 5)
        {
            return true;
        }

        return false;
    }

    private static string BuildSourceBackedOptionCandidateKey(SourceBackedOptionCandidate candidate)
        => $"{NormalizeLexicalLookup(candidate.Title)}|{candidate.Hit.DocPath}|{candidate.Hit.PageStart}|{candidate.Hit.PageEnd}";

    private static bool IsPrimaryQueryTopConcreteCardCandidate(SourceBackedOptionCandidate candidate)
        => IsPrimaryQueryTopConcreteCardHit(candidate.Hit);

    private static bool IsPrimaryQueryTopConcreteCardHit(RagHitSummary hit)
    {
        if (hit.RetrievalQueryIndex != 0 || hit.RetrievalHitRank is null or > 1)
            return false;

        return hit.MatchedContentCards?.Any(IsConcreteSourceBackedOptionCard) == true;
    }

    private static bool IsConcreteSourceBackedOptionCard(RagHitContentCardSummary card)
    {
        var title = CleanSourceBackedOptionTitle(card.Title);
        return IsUsableSourceBackedOptionTitle(title);
    }

    private static bool HasSourceBackedProfileTitle(RagHitSummary hit)
        => ExtractProfileTitleCandidates(hit.ContextualSnippet ?? string.Empty)
            .Select(CleanSourceBackedOptionTitle)
            .Any(IsUsableSourceBackedOptionTitle);

    private static bool QueryAnchorTermsMatchHit(IReadOnlyList<string> anchorTerms, RagHitSummary hit)
    {
        if (anchorTerms.Count == 0)
            return false;

        var evidence = NormalizeLexicalLookup(GetRagHitPrimaryEvidenceText(hit));
        var title = NormalizeLexicalLookup($"{hit.DocName} {hit.SectionTitle} {hit.HeadingPath} {ExtractSourceBackedOptionTitle(hit, null)}");
        return anchorTerms.Any(term =>
            evidence.Contains(term, StringComparison.Ordinal)
            || title.Contains(term, StringComparison.Ordinal));
    }

    private static readonly HashSet<string> SourceBackedOptionConstraintTerms = new(StringComparer.Ordinal)
    {
        "total", "moins", "minutes", "minute", "rapide", "rapides", "complete", "complet",
        "combined", "overall", "option", "options", "suggestion", "suggestions", "selection",
        "facile", "faciles", "easy", "simple", "simples", "rapido", "rapida", "rapidas",
        "rapidos", "schnell", "einfach", "veloce", "veloci"
    };

    private static readonly HashSet<string> SourceBackedPairingAnchorNoiseTerms = new(StringComparer.Ordinal)
    {
        "quel", "quelle", "quels", "quelles", "quoi", "which", "what", "cual", "qual",
        "welche", "welcher", "welches", "quale", "propose", "proposes", "suggest",
        "suggestion", "suggestions", "recommend", "recommends", "recommendation",
        "recommande", "recommander", "conseille", "conseiller", "irait", "vont",
        "bien", "avec", "with", "goes", "pair", "pairs", "pairing", "accompagne",
        "accompagner", "associe", "associer", "compatible", "compatibles", "con",
        "acompanha", "acompanhar", "combina", "combinar", "passt", "kombinieren",
        "abbinare", "abbina"
    };

    private static string BuildSourceBackedFallbackOptionTitle(RagHitSummary hit, string language)
    {
        var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? Path.GetFileName(hit.DocPath) : hit.DocName;
        return string.IsNullOrWhiteSpace(docLabel)
            ? $"Source {SourceBackedPagePrefix(language)}{hit.PageStart}"
            : $"{docLabel} {SourceBackedPagePrefix(language)}{hit.PageStart}";
    }

    private static IReadOnlyList<string> ExtractNamedEntityLikeQueryTerms(string? query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<string>();

        return Regex.Matches(query, @"\b[\p{Lu}][\p{L}\p{N}]{4,}\b", RegexOptions.CultureInvariant)
            .Select(match => NormalizeLexicalLookup(match.Value))
            .Where(static term => term.Length >= 5)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(4)
            .ToArray();
    }

    private static string ExtractSourceBackedOptionTitle(RagHitSummary hit, string? query)
    {
        var profileCandidates = ExtractProfileTitleCandidates(hit.ContextualSnippet ?? string.Empty)
            .Select(CleanSourceBackedOptionTitle)
            .Where(title => !string.IsNullOrWhiteSpace(title))
            .Where(IsUsableSourceBackedOptionTitle)
            .Select((title, index) => new
            {
                Title = title,
                Index = index,
                Score = ComputeSourceBackedOptionTitleScore(title, hit, query)
            })
            .Where(item => item.Score > -30)
            .OrderByDescending(item => item.Score)
            .ThenBy(item => item.Index)
            .ToArray();
        if (profileCandidates.Length > 0)
            return profileCandidates[0].Title;

        var candidates = ExtractSourceBackedTitleCandidates(hit)
            .Concat(new[] { ExtractPlanItemTitleV2(GetPlanExtractionText(hit)) })
            .Select(CleanSourceBackedOptionTitle)
            .Where(title => !string.IsNullOrWhiteSpace(title))
            .Where(IsUsableSourceBackedOptionTitle)
            .Select((title, index) => new
            {
                Title = title,
                Index = index,
                Score = ComputeSourceBackedOptionTitleScore(title, hit, query)
            })
            .Where(item => item.Score > -20)
            .OrderByDescending(item => item.Score)
            .ThenBy(item => item.Index)
            .ToArray();

        return candidates.FirstOrDefault()?.Title ?? string.Empty;
    }

    private static string CleanSourceBackedOptionTitle(string? value)
    {
        var title = HumanizePlanItemTitleV2(value ?? string.Empty);
        if (string.IsNullOrWhiteSpace(title))
            return string.Empty;

        title = Regex.Replace(
            title,
            @"^([\p{Lu}0-9 '&/\-,\u00c0-\u017f]{4,48})\s+(?:l['\u2019]|le|la|les|un|une)\b.+$",
            "$1",
            RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"^(?:D(?:E|[\u00c9])J)\s*(?=[\p{Lu}\u00c0-\u017f])", string.Empty, RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"^(?:de|du|des|d['\u2019])\s+", string.Empty, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"\bD[E\u00c9]\s+J(?=[\p{Lu}\u00c0-\u017f])", "DEJ ", RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"\bD[E\u00c9]J(?=[\p{Lu}\u00c0-\u017f])", "DEJ ", RegexOptions.CultureInvariant);
        title = Regex.Replace(
            title,
            @"(?<=[\p{Lu}\u00c0-\u017f]{4})(?:HEALTHY|LIGHT|EASY|QUICK|FAST|FACILE|RAPIDE|LEGER|L[E\u00c9]GER)(?=\d|\b)",
            string.Empty,
            RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"(?i)\b([\p{L}]{5,})aux\b", "$1 aux", RegexOptions.CultureInvariant);
        title = Regex.Replace(
            title,
            @"^(.{3,70}?)(?:\s+(?:pour\s+\d+|for\s+\d+|para\s+\d+|per\s+\d+|pr[e\u00e9]paration|preparation|preparaci[o\u00f3]n|preparacao|zubereitung|method|m[e\u00e9]thode|methode|procedure|proc[e\u00e9]dure|materials?|mat[e\u00e9]riel|materiel|items?)\b).*$",
            "$1",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        title = Regex.Replace(
            title,
            @"^(.{4,70}?)(?:\s+(?:se|est|sont|peut|peuvent|permet|permettent|pour\s+obtenir|le\s+temps|observer)\b).*$",
            "$1",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"\s+", " ", RegexOptions.CultureInvariant).Trim(' ', '-', ':', '.', ',', ';');

        return title.Length <= 90 ? title : title[..90].TrimEnd();
    }

    private static int ComputeSourceBackedOptionTitleScore(string title, RagHitSummary hit, string? query)
    {
        var normalizedTitle = NormalizeLexicalLookup(title);
        var normalizedSection = NormalizeLexicalLookup($"{hit.SectionTitle} {hit.HeadingPath}");
        var normalizedQuery = NormalizeLexicalLookup(query);
        var score = 0;

        if (!string.IsNullOrWhiteSpace(normalizedQuery))
            score += ComputeTypoTolerantRagHitLexicalRelevance(normalizedQuery, normalizedTitle) * 2;

        var wordCount = ExtractQuerySignalTerms(normalizedTitle).Count();
        if (wordCount is >= 2 and <= 7)
            score += 8;
        if (Regex.IsMatch(title, @"[\p{Lu}\u00c0-\u017f]", RegexOptions.CultureInvariant))
            score += 3;
        if (!string.IsNullOrWhiteSpace(normalizedSection) && normalizedSection.Contains(normalizedTitle, StringComparison.Ordinal))
            score -= 12;
        if (Regex.IsMatch(normalizedTitle, @"\b(?:document|section|categories?|modes?|preparation|operation|workflow|execution|pages?)\b", RegexOptions.CultureInvariant))
            score -= 16;
        if (LooksLikeWeakSourceBackedOptionTitle(title))
            score -= 50;

        return score;
    }

    private static int ComputeSourceBackedOptionHitScore(
        RagHitSummary hit,
        string title,
        string? query,
        int? requestedMaxMinutes,
        int? visibleMinutes)
    {
        var normalizedQuery = NormalizeLexicalLookup(query);
        var evidence = NormalizeLexicalLookup(GetRagHitPrimaryEvidenceText(hit));
        var score = ComputeTypoTolerantRagHitLexicalRelevance(normalizedQuery, evidence);
        score += ComputeProcedureCompletenessCueScore(hit);
        score += ComputeStructuredProcedureEvidenceCueScore(hit);
        score += ComputeStructuredProcedureVisibleEvidenceCueScore(hit);
        score += ComputeSourceBackedOptionTitleScore(title, hit, query);

        if (requestedMaxMinutes.HasValue)
        {
            if (visibleMinutes.HasValue && visibleMinutes.Value <= requestedMaxMinutes.Value)
                score += 18;
            else if (visibleMinutes.HasValue)
                score -= 60;
            else
                score -= 3;
        }

        var queryTerms = ExtractQuerySignalTerms(normalizedQuery)
            .Where(static term => term.Length >= 4)
            .Where(static term => !SourceBackedOptionConstraintTerms.Contains(term))
            .Take(8)
            .ToArray();
        if (queryTerms.Length > 0 && QueryAnchorTermsMatchHit(queryTerms, hit))
            score += 12;

        if (hit.RetrievalQueryIndex == 0)
        {
            score += hit.RetrievalHitRank switch
            {
                0 => 18,
                1 => 12,
                2 => 8,
                _ => 4
            };
        }

        if (LooksLikeMidProcedureFragment(hit))
            score -= 8;

        return score;
    }

    private static string FormatSourceBackedOptionEvidence(RagHitSummary hit)
    {
        var evidence = CleanReadableProcedureArtifacts(FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 220));
        if (string.IsNullOrWhiteSpace(evidence))
            return string.Empty;

        var title = ExtractSourceBackedOptionTitle(hit, query: null);
        return string.Equals(NormalizeLexicalLookup(evidence), NormalizeLexicalLookup(title), StringComparison.Ordinal)
            ? string.Empty
            : evidence;
    }

    private static int? TryExtractRequestedMaxMinutes(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return null;

        var match = Regex.Match(
            normalized,
            @"\b(?:moins\s+de|en\s+moins\s+de|sous|maximum|max|under|less\s+than|within)\s+(?<n>\d{1,3})\s*(?:min|minutes?)\b",
            RegexOptions.CultureInvariant);
        if (!match.Success)
        {
            match = Regex.Match(
                normalized,
                @"\b(?:moins|maximum|max|sous|under|less|within)\b.{0,32}\b(?<n>\d{1,3})\s*(?:min|minutes?)\b",
                RegexOptions.CultureInvariant);
        }
        if (match.Success)
        {
            return int.TryParse(match.Groups["n"].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var minutes)
                ? minutes
                : null;
        }

        var hourMatch = Regex.Match(
            normalized,
            @"\b(?:moins\s+de|en\s+moins\s+de|sous|maximum|max|under|less\s+than|within)\s+(?:(?<h>\d{1,2})|(?<one>un|une|one|a|an))\s*(?:h\b|hr\b|hrs\b|heure|heures|hour|hours)\b",
            RegexOptions.CultureInvariant);
        if (!hourMatch.Success)
        {
            hourMatch = Regex.Match(
                normalized,
                @"\b(?:moins|maximum|max|sous|under|less|within)\b.{0,32}\b(?:(?<h>\d{1,2})|(?<one>un|une|one|a|an))\s*(?:h\b|hr\b|hrs\b|heure|heures|hour|hours)\b",
                RegexOptions.CultureInvariant);
        }
        if (!hourMatch.Success)
            return null;

        var hours = hourMatch.Groups["one"].Success
            ? 1
            : int.TryParse(hourMatch.Groups["h"].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedHours)
                ? parsedHours
                : 0;

        return hours is > 0 and <= 24
            ? hours * 60
            : null;
    }

    private static int? ExtractBestVisibleDurationMinutes(RagHitSummary hit)
    {
        var text = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        var primaryDuration = ExtractBestVisibleDurationMinutesFromText(text);
        if (primaryDuration.HasValue)
            return primaryDuration;

        var lookupText = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        return string.Equals(lookupText, text, StringComparison.Ordinal)
            ? null
            : ExtractBestVisibleDurationMinutesFromText(lookupText);
    }

    private static int? ExtractBestVisibleDurationMinutesFromText(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return null;

        var labeledTotal = ExtractLabeledVisibleDurationTotalMinutes(text);
        if (labeledTotal.HasValue)
            return labeledTotal;

        var values = new List<int>();
        foreach (Match match in Regex.Matches(NormalizeDurationScanText(text), @"\b(?<h>\d{1,2})\s*(?:h\b|heures?\b)(?:\s*(?<m>\d{1,2})\s*min(?:utes?)?)?", RegexOptions.CultureInvariant))
        {
            var hours = int.Parse(match.Groups["h"].Value, CultureInfo.InvariantCulture);
            var minutes = match.Groups["m"].Success ? int.Parse(match.Groups["m"].Value, CultureInfo.InvariantCulture) : 0;
            values.Add(hours * 60 + minutes);
        }

        foreach (Match match in Regex.Matches(NormalizeDurationScanText(text), @"\b(?<m>\d{1,3})\s*min(?:utes?)?(?=\b|(?:preparation|prep|procedure|process|execution|repos|pause|wait|rest|total|temps|duree)\b)", RegexOptions.CultureInvariant))
            values.Add(int.Parse(match.Groups["m"].Value, CultureInfo.InvariantCulture));

        return values
            .Where(value => value is > 0 and <= 1440)
            .OrderByDescending(static value => value)
            .Cast<int?>()
            .FirstOrDefault();
    }

    private static int? ExtractLabeledVisibleDurationTotalMinutes(string normalizedText)
    {
        var text = NormalizeDurationScanText(normalizedText);
        var durations = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (Match match in Regex.Matches(
            text,
            @"\b(?<label>temps\s+total|duree\s+totale|total|preparation|prep|procedure|process|execution|operation|operations|repos|pause|wait|rest)\s*[:=\-]?\s*(?<duration>\d{1,2}\s*(?:h\b|heures?\b)(?:\s*\d{1,2}\s*min(?:utes?)?)?|\d{1,3}\s*min(?:utes?)?)",
            RegexOptions.CultureInvariant))
        {
            var label = NormalizeDurationLabel(match.Groups["label"].Value);
            var minutes = ParseVisibleDurationMinutes(match.Groups["duration"].Value);
            if (!minutes.HasValue)
                continue;

            if (label == "total")
                return minutes.Value;

            durations.TryAdd(label, minutes.Value);
        }

        foreach (Match match in Regex.Matches(
            text,
            @"\b(?<label>[\p{L}][\p{L}\-]{2,30})\s*[:=\-]\s*(?<duration>\d{1,2}\s*(?:h\b|heures?\b)(?:\s*\d{1,2}\s*min(?:utes?)?)?|\d{1,3}\s*min(?:utes?)?)",
            RegexOptions.CultureInvariant))
        {
            var label = NormalizeDurationLabel(match.Groups["label"].Value);
            if (LooksLikeDurationLabelNoise(label))
                continue;

            var minutes = ParseVisibleDurationMinutes(match.Groups["duration"].Value);
            if (minutes.HasValue)
                durations.TryAdd(label, minutes.Value);
        }

        return durations.Count >= 2
            ? durations.Values.Sum()
            : durations.Values.Cast<int?>().FirstOrDefault();
    }

    private static string NormalizeDurationScanText(string text)
    {
        return NormalizeStructuredScanText(text);
    }

    private static string NormalizeStructuredScanText(string? text)
    {
        var normalized = NormalizeLexicalLookup(text);
        if (string.IsNullOrWhiteSpace(normalized))
            return string.Empty;

        normalized = Regex.Replace(normalized, @"(?<=\d)(?=\p{L})", " ", RegexOptions.CultureInvariant);
        normalized = Regex.Replace(normalized, @"(?<=\p{L})(?=\d)", " ", RegexOptions.CultureInvariant);
        normalized = Regex.Replace(normalized, @"(?<=\p{Ll})(?=\p{Lu})", " ", RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"(?<=[\p{L}])(?=(?:preparation|prep|procedure|process|execution|repos|pause|wait|rest|total|temps|duree)\b)",
            " ",
            RegexOptions.CultureInvariant);
        return CollapseWhitespace(normalized);
    }

    private static string NormalizeDurationLabel(string label)
    {
        var normalized = NormalizeLexicalLookup(label);
        if (Regex.IsMatch(normalized, @"\b(?:temps\s+total|duree\s+totale|total)\b", RegexOptions.CultureInvariant))
            return "total";
        if (Regex.IsMatch(normalized, @"\b(?:preparation|prep)\b", RegexOptions.CultureInvariant))
            return "prep";
        if (Regex.IsMatch(normalized, @"\b(?:procedure|process|execution|operation|operations)\b", RegexOptions.CultureInvariant))
            return "process";
        if (Regex.IsMatch(normalized, @"\b(?:repos|pause|wait|rest)\b", RegexOptions.CultureInvariant))
            return "rest";
        return normalized;
    }

    private static bool LooksLikeDurationLabelNoise(string label)
        => string.IsNullOrWhiteSpace(label)
            || label.Length < 3
            || Regex.IsMatch(label, @"\b(?:min|mins|minute|minutes|heure|heures|hour|hours|page|pages|source|sources|document|documents|pdf)\b", RegexOptions.CultureInvariant);

    private static int? ParseVisibleDurationMinutes(string value)
    {
        var text = NormalizeLexicalLookup(value);
        var hourMatch = Regex.Match(
            text,
            @"\b(?<h>\d{1,2})\s*(?:h\b|heures?\b)(?:\s*(?<m>\d{1,2})\s*min(?:utes?)?)?",
            RegexOptions.CultureInvariant);
        if (hourMatch.Success)
        {
            var hours = int.Parse(hourMatch.Groups["h"].Value, CultureInfo.InvariantCulture);
            var minutes = hourMatch.Groups["m"].Success
                ? int.Parse(hourMatch.Groups["m"].Value, CultureInfo.InvariantCulture)
                : 0;
            var total = hours * 60 + minutes;
            return total is > 0 and <= 1440 ? total : null;
        }

        var minuteMatch = Regex.Match(
            text,
            @"\b(?<m>\d{1,3})\s*min(?:utes?)?",
            RegexOptions.CultureInvariant);
        if (!minuteMatch.Success)
            return null;

        var minuteTotal = int.Parse(minuteMatch.Groups["m"].Value, CultureInfo.InvariantCulture);
        return minuteTotal is > 0 and <= 1440 ? minuteTotal : null;
    }

    private static List<ToolMemory.SourceRef> DeriveSourcesFromMissingExactItemCloseLeads(string requestedTitle, IReadOnlyList<RagHitSummary> hits)
    {
        var closeLeads = SelectMissingExactItemCloseLeads(requestedTitle, hits);
        if (closeLeads.Count == 0)
            closeLeads = hits
                .Where(hit => !LooksLikeNavigationOnlyHit(hit))
                .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit))
                .Where(hit => !LooksLikeExactItemReferenceOnlyHit(requestedTitle, hit))
                .OrderByDescending(hit => ComputeTypoTolerantRagHitLexicalRelevance(requestedTitle, GetRagHitLookupText(hit)))
                .Take(3)
                .ToList();

        return closeLeads
            .Select(BuildSourceRefFromRagHit)
            .ToList();
    }

    private static List<RagHitSummary> SelectMissingExactItemCloseLeads(string requestedTitle, IReadOnlyList<RagHitSummary> hits)
    {
        return hits
            .Select(hit => new
            {
                Hit = hit,
                Score = ComputeTypoTolerantRagHitLexicalRelevance(requestedTitle, GetRagHitLookupText(hit))
            })
            .Where(item => !LooksLikeNavigationOnlyHit(item.Hit))
            .Where(item => !LooksLikeLowSignalContentCandidateHit(item.Hit))
            .Where(item => !LooksLikePageReferenceOnlyHit(item.Hit))
            .Where(item => !LooksLikeExactItemReferenceOnlyHit(requestedTitle, item.Hit))
            .Where(item => item.Score >= 4)
            .OrderByDescending(item => item.Score)
            .Select(item => item.Hit)
            .Take(2)
            .ToList();
    }

    private static int ComputeTypoTolerantRagHitLexicalRelevance(string query, string text)
    {
        var best = ComputeRagHitLexicalRelevance(query, text);
        foreach (var variant in BuildTypoTolerantQueryVariants(query))
            best = Math.Max(best, ComputeRagHitLexicalRelevance(variant, text));
        return best;
    }

    private static IReadOnlyList<RagHitSummary> SelectSourceBackedExtractiveHits(ToolResults toolResults, string query, int maxHits)
    {
        var evidenceQuery = BuildRagEvidenceSelectionQuery(query);
        var isShortTechnicalEvidenceTopic = LooksLikeShortTechnicalEvidenceTopic(evidenceQuery);
        var requestedTitle = isShortTechnicalEvidenceTopic
            ? null
            : TryExtractRequestedItemTitle(query);
        var requestedDocumentFileTitle = ResolveRequestedDocumentFileTitle(query, requestedTitle);
        var explicitDocumentFileReferences = ExtractExplicitDocumentFileReferenceQueries(query);
        var hasMultipleExplicitComparativeDocumentReferences = LooksLikeComparativeDocumentaryRequest(query)
            && explicitDocumentFileReferences.Count > 1;
        var shouldScopeToSingleRequestedDocumentFile = !hasMultipleExplicitComparativeDocumentReferences
            && !string.IsNullOrWhiteSpace(requestedDocumentFileTitle);
        var allHits = EnumerateRagHitSummaries(toolResults)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit)
                || IsUsableExactItemNavigationOverride(requestedTitle, hit)
                || MatchesRequestedDocumentFileIdentity(requestedDocumentFileTitle, hit))
            .Where(hit => !LooksLikeLowSignalAppFeatureHit(hit, query)
                || MatchesRequestedDocumentFileIdentity(requestedDocumentFileTitle, hit))
            .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit)
                || IsUsableExactItemNavigationOverride(requestedTitle, hit)
                || MatchesRequestedDocumentFileIdentity(requestedDocumentFileTitle, hit)
                || MatchesExplicitComparativeDocumentReference(query, hit))
            .Select(hit => new
            {
                Hit = hit,
                DocumentTypeScore = ComputeRequestedDocumentTypeAnchorScore(evidenceQuery, hit),
                DirectTechnicalEvidence = isShortTechnicalEvidenceTopic
                    ? ComputeDirectTechnicalEvidenceScore(evidenceQuery, hit)
                    : 0,
                PrimaryRelevance = ComputeRagHitLexicalRelevance(evidenceQuery, GetRagHitPrimaryEvidenceText(hit)),
                Relevance = ComputeRagHitLexicalRelevance(evidenceQuery, GetRagHitLookupText(hit))
            })
            .OrderByDescending(item => item.DocumentTypeScore)
            .ThenByDescending(item => item.DirectTechnicalEvidence)
            .ThenByDescending(item => item.PrimaryRelevance)
            .ThenByDescending(item => item.Relevance)
            .ThenByDescending(item => item.Hit.Score)
            .ToList();
        if (shouldScopeToSingleRequestedDocumentFile)
        {
            var documentScopedHits = allHits
                .Where(item => CandidateMatchesDocumentIdentity(requestedDocumentFileTitle!, item.Hit.DocName, item.Hit.DocPath))
                .ToList();
            if (documentScopedHits.Count > 0)
                allHits = documentScopedHits;
        }

        var requestedDocumentTypeHits = allHits
            .Where(static item => item.DocumentTypeScore > 0)
            .ToList();
        if (requestedDocumentTypeHits.Count > 0)
            allHits = requestedDocumentTypeHits;

        if (isShortTechnicalEvidenceTopic)
        {
            var phraseEvidenceHits = allHits
                .Where(item => HasShortTechnicalPhraseEvidence(evidenceQuery, item.Hit))
                .ToList();
            if (phraseEvidenceHits.Count > 0)
                allHits = phraseEvidenceHits;
        }

        var requestedMaxMinutes = TryExtractRequestedMaxMinutes(query);
        if (requestedMaxMinutes.HasValue)
        {
            var timeCompatibleHits = allHits
                .Where(item =>
                {
                    var visibleMinutes = ExtractBestVisibleDurationMinutes(item.Hit);
                    return !visibleMinutes.HasValue || visibleMinutes.Value <= requestedMaxMinutes.Value;
                })
                .ToList();
            if (timeCompatibleHits.Count > 0)
                allHits = timeCompatibleHits;
        }

        var softChoiceOptionKindTerms = ExtractSoftChoiceRequestedOptionKindTerms(query);
        if (softChoiceOptionKindTerms.Count > 0)
        {
            var compatibleHits = allHits
                .Where(item => !SoftChoiceOptionKindContradictsHit(softChoiceOptionKindTerms, item.Hit))
                .ToList();
            if (compatibleHits.Count > 0)
                allHits = compatibleHits;

            var kindMatchedHits = allHits
                .Where(item => SoftChoiceOptionKindMatchesHit(softChoiceOptionKindTerms, item.Hit))
                .ToList();
            if (kindMatchedHits.Count > 0)
                allHits = kindMatchedHits;
        }

        if (allHits.Count == 0)
            return Array.Empty<RagHitSummary>();

        if (LooksLikeRankingDocumentaryRequest(query))
        {
            var rankedHits = RankSourceBackedRankingHits(allHits.Select(item => item.Hit), query)
                .Take(maxHits)
                .ToList();
            if (rankedHits.Count > 0)
                return rankedHits;
        }

        if (LooksLikeComparativeDocumentaryRequest(query))
        {
            var comparativeHits = SelectComparativeDocumentaryHits(allHits.Select(item => item.Hit), query, maxHits);
            if (comparativeHits.Count > 0)
                return comparativeHits;
        }

        if (!string.IsNullOrWhiteSpace(requestedTitle))
        {
            var exactTitleHits = allHits
                .Select(item => item.Hit)
                .Where(hit => RagHitContainsRequestedTitle(hit, requestedTitle!)
                    || RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit)
                    || IsUsableExactItemNavigationOverride(requestedTitle!, hit))
                .Where(hit => !LooksLikeExactItemReferenceOnlyHit(requestedTitle!, hit))
                .ToList();
            if (exactTitleHits.Count > 0)
            {
                var isStructuredItemCardRequest = LooksLikeStructuredItemCardRequest(query);
                var anchoredTitleHits = exactTitleHits
                    .Where(hit => isStructuredItemCardRequest
                        ? ExactItemEvidenceStartsWithRequestedTitle(requestedTitle!, hit) || HasStrongExactItemTitleAnchor(requestedTitle!, hit) || IsUsableExactItemNavigationOverride(requestedTitle!, hit)
                        : RagHitHasUsableRequestedTitleAnchor(requestedTitle!, hit) || IsUsableExactItemNavigationOverride(requestedTitle!, hit))
                    .ToList();
                if (isStructuredItemCardRequest)
                {
                    var leadTitleHits = anchoredTitleHits
                        .Where(hit => ExactItemEvidenceStartsWithRequestedTitle(requestedTitle!, hit))
                        .ToList();
                    if (leadTitleHits.Count > 0)
                    {
                        anchoredTitleHits = leadTitleHits;
                        exactTitleHits = anchoredTitleHits;
                    }
                    else if (anchoredTitleHits.Count == 0)
                    {
                        var recoverableStructuredHits = exactTitleHits
                            .Where(hit => HasRecoverableStructuredExactItemEvidence(requestedTitle!, hit))
                            .ToList();
                        if (recoverableStructuredHits.Count == 0)
                            return Array.Empty<RagHitSummary>();

                        exactTitleHits = recoverableStructuredHits;
                    }
                    else
                    {
                        exactTitleHits = anchoredTitleHits;
                    }
                }
                else if (anchoredTitleHits.Count == 0
                         && !exactTitleHits.Any(hit => HasRecoverableStructuredExactItemEvidence(requestedTitle!, hit)))
                {
                    return Array.Empty<RagHitSummary>();
                }
                else if (anchoredTitleHits.Count > 0)
                {
                    exactTitleHits = anchoredTitleHits;
                }

                if (LooksLikeStructuredItemCardRequest(query))
                {
                    exactTitleHits = AddComplementaryStructuredHitsForExactItem(
                            exactTitleHits,
                            allHits.Select(static item => item.Hit))
                        .OrderByDescending(hit => ComputeExactItemCardEvidenceScore(requestedTitle!, hit))
                        .ThenByDescending(ComputeExactItemCardCompletenessCueScore)
                        .ThenByDescending(hit => ComputeRagHitLexicalRelevance(requestedTitle!, GetRagHitLookupText(hit)))
                        .ThenByDescending(hit => hit.Score)
                        .Take(maxHits)
                        .ToList();
                }
                else
                {
                    exactTitleHits = exactTitleHits
                        .Take(maxHits)
                        .ToList();
                }

                return exactTitleHits;
            }

            if (LooksLikeStructuredItemCardRequest(query))
                return Array.Empty<RagHitSummary>();
        }
        else
        {
            var primaryRelevantHits = allHits
                .Where(item => item.PrimaryRelevance > 0)
                .Select(item => item.Hit)
                .ToList();
            if (primaryRelevantHits.Count > 0)
                return FilterHitsToDominantTopLevel(primaryRelevantHits, query).Take(maxHits).ToList();

            var relevantHits = allHits
                .Where(item => item.Relevance > 0)
                .Select(item => item.Hit)
                .ToList();
            if (relevantHits.Count > 0)
                return FilterHitsToDominantTopLevel(relevantHits, query).Take(maxHits).ToList();

            var fallbackHits = allHits.Select(item => item.Hit).ToList();
            return FilterHitsToDominantTopLevel(fallbackHits, query).Take(maxHits).ToList();
        }

        return allHits.Select(item => item.Hit).Take(maxHits).ToList();
    }

    private static bool LooksLikeLowSignalAppFeatureHit(RagHitSummary hit, string query)
    {
        var queryLookup = NormalizeLexicalLookup(query);
        if (Regex.IsMatch(queryLookup, @"\b(?:liste\s+d['\u2019]elements|itemized\s+list|liste\s+detaillee|detailed\s+list)\b", RegexOptions.CultureInvariant))
            return false;

        var text = NormalizeLexicalLookup(GetBestRagEvidenceText(hit));
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var looksLikeAppFeatureCopy = Regex.IsMatch(
            text,
            @"\b(?:liste\s+d['\u2019]elements\s+a\s+partir|itemized\s+list\s+from|application|appli|app|interface|workflow|fonctionnalite|feature)\b",
            RegexOptions.CultureInvariant)
            && Regex.IsMatch(
                text,
                @"\b(?:documents?|sources?|corpus|base\s+de\s+connaissances?|knowledge\s+base|categories?|categories|dossiers?|folders?|fichiers?|files?)\b",
                RegexOptions.CultureInvariant);
        return looksLikeAppFeatureCopy
            && !Regex.IsMatch(text, @"\b(?:preparation|operation|workflow|execution|procedure|method|methode|etapes?|steps?|requirements?|values?|valeurs?|quantities?|quantites?|\d+\s*(?:g|kg|mg|ml|cl|l|min|h|mm|cm|m))\b", RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeLowSignalContentCandidateHit(RagHitSummary hit)
    {
        if (BackendSelectionHintsPreferUsableEvidence(hit))
            return false;
        if (BackendSelectionHintsPreferLowSignal(hit))
            return true;

        var primaryText = GetRagHitPrimaryContentText(hit);
        var text = NormalizeStructuredScanText(primaryText);
        if (string.IsNullOrWhiteSpace(text))
            return false;

        if (hit.PageStart <= 2 && LooksLikeGenericFrontMatterShape(primaryText))
            return true;

        var hasBodyStructure = Regex.IsMatch(
            text,
            @"\b(?:items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?|preparation|operation|workflow|execution|procedure|etapes?|steps?|method|methode|(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+\p{L}|\d+\s*(?:g|kg|mg|ml|cl|l|min(?:ute)?s?|h|heures?|hours?))\b",
            RegexOptions.CultureInvariant);
        var hasStrongStructuredEvidence = ComputeProcedureCompletenessCueScore(hit) >= 5
            || ComputeStructuredProcedureVisibleEvidenceCueScore(hit) >= 3
            || CountProcedureStepMarkers(text) > 0;
        if (hasBodyStructure && hasStrongStructuredEvidence)
            return false;

        if (Regex.IsMatch(text, @"^(?:si|lorsque|quand|when|if)\b", RegexOptions.CultureInvariant))
            return true;

        var hasCoverOrCatalogCue = Regex.IsMatch(
            text,
            @"\b(?:sommaire|index|contents|table\s+of\s+contents|catalogue|catalog|guide|introduction|avant-propos|preface|foreword|copyright|isbn|edition|publisher|front\s+matter)\b",
            RegexOptions.CultureInvariant);
        if (hasCoverOrCatalogCue)
            return true;

        return false;
    }

    private static bool LooksLikeGenericFrontMatterShape(string? text)
    {
        var raw = CollapseWhitespace(text ?? string.Empty);
        if (raw.Length < 80)
            return false;

        var normalized = NormalizeLexicalLookup(raw);
        var lead = normalized.Length <= 700 ? normalized : normalized[..700];
        var hasMarketingLead = Regex.IsMatch(lead, @"\b\d{2,4}\b", RegexOptions.CultureInvariant)
            && Regex.IsMatch(
                lead,
                @"\b(?:conseils?|tips?|guides?|simple|simples|accessible|accessibles|abordable|abordables|budget|rapide|rapides|quick|easy|pratique|pratiques)\b",
                RegexOptions.CultureInvariant)
            && !Regex.IsMatch(
                lead,
                @"\b(?:preparation|operation|workflow|execution|procedure|etapes?|steps?|method|methode)\b",
                RegexOptions.CultureInvariant);
        if (raw.Length <= 2200 && hasMarketingLead)
            return true;

        if (Regex.IsMatch(
                normalized,
                @"\b(?:sommaire|index|contents|table\s+of\s+contents|catalogue|catalog|copyright|isbn|edition|publisher|preface|foreword|avant-propos|introduction|www\.)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        var letters = raw.Where(char.IsLetter).ToArray();
        if (letters.Length < 24)
            return false;

        var upperRatio = letters.Count(char.IsUpper) / (double)letters.Length;
        var digitRatio = raw.Count(char.IsDigit) / (double)Math.Max(1, raw.Length);
        var punctuationRatio = raw.Count(ch => char.IsPunctuation(ch) || char.IsSymbol(ch)) / (double)Math.Max(1, raw.Length);
        var hasNumberedHeadline = Regex.IsMatch(
            raw,
            @"(?:^|\s)\d{2,4}\s+[\p{Lu}\p{Lt}][\p{Lu}\p{Lt}\s'\-]{6,}",
            RegexOptions.CultureInvariant);
        var hasDenseUppercaseHeadline = Regex.IsMatch(
            raw,
            @"(?:\b[\p{Lu}\p{Lt}]{4,}\b[\s+\-]*){3,}",
            RegexOptions.CultureInvariant);
        var hasGluedCaseBoundary = Regex.IsMatch(
            raw,
            @"[\p{Ll}]{4,}[\p{Lu}\p{Lt}]{4,}|[\p{Lu}\p{Lt}]{4,}[\p{Ll}]{4,}[\p{Lu}\p{Lt}]{4,}",
            RegexOptions.CultureInvariant);
        var hasMarketingCue = Regex.IsMatch(
            normalized,
            @"\b(?:conseils?|tips?|guide|guides?|simple|simples|accessible|accessibles|abordable|abordables|budget|rapide|rapides|quick|easy|pratique|pratiques)\b",
            RegexOptions.CultureInvariant);
        if (raw.Length <= 1600
            && (hasNumberedHeadline || hasDenseUppercaseHeadline || hasGluedCaseBoundary)
            && (hasMarketingCue || upperRatio >= 0.38))
        {
            return true;
        }

        return raw.Length <= 1400
            && upperRatio >= 0.48
            && digitRatio <= 0.18
            && punctuationRatio <= 0.22;
    }

    private static bool HasRecoverableStructuredExactItemEvidence(string requestedTitle, RagHitSummary hit)
    {
        if (string.IsNullOrWhiteSpace(requestedTitle))
            return false;

        if (LooksLikePageReferenceOnlyHit(hit) || LooksLikeExactItemReferenceOnlyHit(requestedTitle, hit))
            return false;

        var navigationOverride = IsUsableExactItemNavigationOverride(requestedTitle, hit);
        if (LooksLikeNavigationOnlyHit(hit) && !navigationOverride)
            return false;

        if (LooksLikeLowSignalContentCandidateHit(hit) && !navigationOverride)
            return false;

        if (HasContentCardEvidenceFacts(hit)
            || HasContentCardQuantityEvidence(new[] { hit })
            || HasContentCardScalableQuantityEvidence(hit))
        {
            return true;
        }

        if (ComputeExactItemCardCompletenessCueScore(hit) >= 4)
            return true;

        if (ComputeStructuredProcedureVisibleEvidenceCueScore(hit) >= 3)
            return true;

        var focusedEvidence = GetFocusedExactItemEvidenceText(requestedTitle, hit);
        var structuredEvidence = GetFocusedExactItemStructuredEvidenceText(requestedTitle, hit);
        if (ExtractItemizedQuantityFacts(structuredEvidence).Length >= 2)
            return true;

        if (ExtractVisibleDurationsAndQuantities(focusedEvidence).Length >= 2)
            return true;

        if (ExtractProcedureSteps(focusedEvidence).Length >= 2)
            return true;

        var normalizedFocusedEvidence = NormalizeStructuredScanText(focusedEvidence);
        if (CountProcedureStepMarkers(normalizedFocusedEvidence) >= 2)
            return true;

        return hit.PageEnd > hit.PageStart
            && Regex.IsMatch(
                normalizedFocusedEvidence,
                @"\b(?:items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?|preparation|operation|workflow|execution|procedure|etapes?|steps?|\d+\s*(?:g|kg|mg|ml|cl|l|min(?:ute)?s?|h|heures?|hours?))\b",
                RegexOptions.CultureInvariant);
    }

    private static IReadOnlyList<RagHitSummary> AddComplementaryStructuredHitsForExactItem(
        IReadOnlyList<RagHitSummary> exactHits,
        IEnumerable<RagHitSummary> allHits)
    {
        if (exactHits.Count == 0)
            return exactHits;

        var merged = exactHits.ToList();
        foreach (var candidate in allHits)
        {
            if (merged.Any(hit => SameRagHitRange(hit, candidate)))
                continue;

            var isAdjacentOrOverlapping = exactHits.Any(anchor =>
                string.Equals(anchor.DocPath, candidate.DocPath, StringComparison.OrdinalIgnoreCase)
                && candidate.PageStart <= anchor.PageEnd + 2
                && candidate.PageEnd >= Math.Max(1, anchor.PageStart - 2));
            if (!isAdjacentOrOverlapping)
                continue;

            if (ComputeExactItemCardCompletenessCueScore(candidate) < 8)
                continue;

            merged.Add(candidate);
        }

        return merged;
    }

    private static bool SameRagHitRange(RagHitSummary left, RagHitSummary right)
        => string.Equals(left.DocPath, right.DocPath, StringComparison.OrdinalIgnoreCase)
            && left.PageStart == right.PageStart
            && left.PageEnd == right.PageEnd;

    private static int ComputeExactItemCardCompletenessCueScore(RagHitSummary hit)
    {
        var score = ComputeProcedureCompletenessCueScore(hit)
            + ComputeStructuredProcedureEvidenceCueScore(hit)
            + ComputeStructuredProcedureVisibleEvidenceCueScore(hit);
        if (ContainsStructuredItemHeading(GetRagHitPrimaryContentText(hit)))
            score += 4;
        if (LooksLikeMidProcedureFragment(hit))
            score -= 8;
        return score;
    }

    private static IReadOnlyList<RagHitSummary> SelectComparativeDocumentaryHits(IEnumerable<RagHitSummary> hits, string query, int maxHits)
    {
        var evidenceQuery = BuildRagEvidenceSelectionQuery(query);
        var focusTerms = ExtractQuerySignalTerms(NormalizeLexicalLookup(evidenceQuery))
            .Where(term => !IsComparativeRetrievalNoiseTerm(term))
            .ToArray();
        var entityAnchors = ExtractComparativeEntityAnchorTerms(query);
        var shouldRequireEntityCoverage = entityAnchors.Length >= 2;

        var scored = hits
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Select((hit, index) => new
            {
                Hit = hit,
                Index = index,
                EntityMatches = GetMatchedComparativeEntityAnchorIndexes(hit, entityAnchors),
                ExplicitReference = MatchesExplicitComparativeDocumentReference(query, hit),
                Score = ComputeComparativeDocumentaryEvidenceScore(hit, evidenceQuery, focusTerms)
            })
            .Where(item => item.Score > 0 || item.ExplicitReference)
            .Where(item => !shouldRequireEntityCoverage || item.EntityMatches.Length > 0 || item.ExplicitReference)
            .Select(item => new ComparativeScoredHit(
                item.Hit,
                item.Index,
                item.EntityMatches,
                item.Score + (item.EntityMatches.Length * 10.0) + (item.ExplicitReference ? 5.0 : 0.0)))
            .OrderByDescending(item => item.EntityMatches.Length)
            .ThenByDescending(item => item.Score)
            .ThenBy(item => item.Index)
            .ToList();
        if (scored.Count == 0)
            return Array.Empty<RagHitSummary>();

        if (shouldRequireEntityCoverage)
            return SelectComparativeEntityCoverageHits(scored, entityAnchors.Length, maxHits);

        var bestByDocument = scored
            .GroupBy(item => string.IsNullOrWhiteSpace(item.Hit.DocPath) ? item.Hit.DocName : item.Hit.DocPath, StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .OrderByDescending(item => item.Score)
            .ThenBy(item => item.Index)
            .ToList();

        if (bestByDocument.Count >= 2)
            return bestByDocument.Take(maxHits).Select(item => item.Hit).ToList();

        return scored.Take(maxHits).Select(item => item.Hit).ToList();
    }

    private sealed record ComparativeScoredHit(RagHitSummary Hit, int Index, int[] EntityMatches, double Score);

    private static IReadOnlyList<RagHitSummary> SelectComparativeEntityCoverageHits(
        IReadOnlyList<ComparativeScoredHit> scored,
        int entityCount,
        int maxHits)
    {
        var selected = new List<ComparativeScoredHit>();
        var selectedKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var coveredEntities = new HashSet<int>();

        for (var entityIndex = 0; entityIndex < entityCount && selected.Count < maxHits; entityIndex++)
        {
            var best = scored
                .Where(item => item.EntityMatches.Contains(entityIndex))
                .Where(item => !selectedKeys.Contains(BuildRagHitIdentityKey(item.Hit)))
                .OrderByDescending(item => item.Score)
                .ThenBy(item => item.Index)
                .FirstOrDefault();
            if (best is null)
                continue;

            selected.Add(best);
            selectedKeys.Add(BuildRagHitIdentityKey(best.Hit));
            foreach (var match in best.EntityMatches)
                coveredEntities.Add(match);
        }

        foreach (var item in scored
                     .Where(item => !selectedKeys.Contains(BuildRagHitIdentityKey(item.Hit)))
                     .OrderByDescending(item => item.EntityMatches.Count(match => !coveredEntities.Contains(match)))
                     .ThenByDescending(item => item.Score)
                     .ThenBy(item => item.Index))
        {
            if (selected.Count >= maxHits)
                break;

            selected.Add(item);
            selectedKeys.Add(BuildRagHitIdentityKey(item.Hit));
            foreach (var match in item.EntityMatches)
                coveredEntities.Add(match);
        }

        return selected.Select(static item => item.Hit).ToList();
    }

    private static string[][] ExtractComparativeEntityAnchorTerms(string? query)
    {
        return ExtractComparativeEntityPhrases(query)
            .Select(phrase => ExtractQuerySignalTerms(NormalizeLexicalLookup(phrase))
                .Where(term => !IsComparativeRetrievalNoiseTerm(term))
                .Where(term => term.Length >= 3)
                .Distinct(StringComparer.Ordinal)
                .Take(5)
                .ToArray())
            .Where(static terms => terms.Length > 0)
            .Take(8)
            .ToArray();
    }

    private static IEnumerable<string> ExtractComparativeEntityPhrases(string? query)
    {
        var text = CollapseWhitespace(query ?? string.Empty);
        if (string.IsNullOrWhiteSpace(text))
            yield break;

        var match = Regex.Match(
            text,
            @"(?i)\b(?:entre|between|zwischen|tra|fra)\s+(?<items>.+?)(?:,\s*)?\b(?:quel|quelle|quels|quelles|lequel|laquelle|which|what|cual|cu[aá]l|qual|welche|welcher|welches|quale)\b",
            RegexOptions.CultureInvariant);
        if (!match.Success)
        {
            match = Regex.Match(
                text,
                @"(?i)\b(?:compare|comparer|comparaison|comparatif|comparative|versus|vs\.?|confronta|confrontare|vergleiche|vergleichen)\s+(?<items>.+?)(?:[?.!]|$)",
                RegexOptions.CultureInvariant);
        }

        if (!match.Success)
            yield break;

        var itemsText = Regex.Replace(
            match.Groups["items"].Value,
            @"(?i)\b(?:quel|quelle|quels|quelles|lequel|laquelle|which|what|cual|cu[aá]l|qual|welche|welcher|welches|quale)\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant);

        foreach (var part in Regex.Split(
                     itemsText,
                     @"\s*(?:,|;|/|\bet\b|\bou\b|\band\b|\bor\b|\by\b|\be\b|\bund\b|\boder\b)\s*",
                     RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
        {
            var phrase = CollapseWhitespace(part)
                .Trim(' ', '.', ',', ';', ':', '?', '!', '"', '\'', '\u00ab', '\u00bb');
            if (phrase.Length is >= 3 and <= 90)
                yield return phrase;
        }
    }

    private static int[] GetMatchedComparativeEntityAnchorIndexes(
        RagHitSummary hit,
        IReadOnlyList<string[]> entityAnchors)
    {
        if (entityAnchors.Count == 0)
            return Array.Empty<int>();

        var lookup = NormalizeLexicalLookup(GetRagHitComparativeEntityLookupText(hit));
        if (string.IsNullOrWhiteSpace(lookup))
            return Array.Empty<int>();

        var matches = new List<int>();
        for (var i = 0; i < entityAnchors.Count; i++)
        {
            var terms = entityAnchors[i];
            if (terms.Length == 0)
                continue;

            var matched = terms.Count(term => ComparativeEntityTermMatches(lookup, term));
            var required = terms.Length <= 3 ? terms.Length : terms.Length - 1;
            if (matched >= required)
                matches.Add(i);
        }

        return matches.ToArray();
    }

    private static bool ComparativeEntityTermMatches(string lookup, string term)
    {
        if (lookup.Contains(term, StringComparison.Ordinal))
            return true;

        return term.Length > 4
               && term.EndsWith('s')
               && lookup.Contains(term[..^1], StringComparison.Ordinal);
    }

    private static double ComputeComparativeDocumentaryEvidenceScore(RagHitSummary hit, string evidenceQuery, IReadOnlyList<string> focusTerms)
    {
        var primaryText = GetRagHitPrimaryEvidenceText(hit);
        var lookupText = GetRagHitLookupText(hit);
        var normalizedPrimary = NormalizeLexicalLookup(primaryText);
        var normalizedLookup = NormalizeLexicalLookup(lookupText);
        if (string.IsNullOrWhiteSpace(normalizedPrimary) && string.IsNullOrWhiteSpace(normalizedLookup))
            return 0;

        if (focusTerms.Count > 0
            && !focusTerms.Any(term =>
                normalizedPrimary.Contains(term, StringComparison.Ordinal)
                || normalizedLookup.Contains(term, StringComparison.Ordinal)))
        {
            return 0;
        }

        var score = ComputeRagHitLexicalRelevance(evidenceQuery, primaryText) * 8
            + ComputeRagHitLexicalRelevance(evidenceQuery, lookupText) * 2
            + Math.Min(2.0, Math.Max(0.0, hit.Score));

        var structuredProcedureScore = ComputeStructuredProcedureEvidenceCueScore(hit);
        score += structuredProcedureScore * 3.0;
        if (structuredProcedureScore >= 6
            && focusTerms.Count > 0
            && focusTerms.Any(term => normalizedLookup.Contains(term, StringComparison.Ordinal)))
        {
            score += 6;
        }

        if (Regex.IsMatch(normalizedPrimary, @"\b\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l|min|h)\b", RegexOptions.CultureInvariant))
            score += 2;
        if (Regex.IsMatch(normalizedPrimary, @"(?:^|\s)[1-9][\.)]\s+", RegexOptions.CultureInvariant))
            score += 2;
        if (Regex.IsMatch(normalizedPrimary, @"\b(?:" + ExactItemStructureHeadingPattern + @")\b", RegexOptions.CultureInvariant))
            score += 2;

        if (LooksLikeMidProcedureFragment(hit))
            score -= 80;
        else if (HasSourceBackedProfileTitle(hit)
                 || !string.IsNullOrWhiteSpace(ExtractSourceBackedOptionTitle(hit, query: null)))
            score += 4;

        if (Regex.IsMatch(normalizedPrimary, @"\b(?:introduction|bienvenue|sommaire|contents|index|overview|presentation|nous avons reuni|nous sommes prets)\b", RegexOptions.CultureInvariant)
            && structuredProcedureScore < 4)
        {
            score -= 16;
        }

        if (string.Equals(hit.EmbeddingBasis, "document_profile_v1", StringComparison.OrdinalIgnoreCase))
            score -= 5;

        return score;
    }

    private sealed record QuantityScaleLine(string Original, string Scaled, bool IsNumeric);

    private sealed record QuantityScalingCandidate(RagHitSummary Hit, int SourceCount, IReadOnlyList<QuantityScaleLine> Lines, double Score);

    private static IReadOnlyList<string> ExtractSourceBackedExcludedTerms(string? query)
    {
        var s = CollapseWhitespace(query ?? string.Empty);
        if (s.Length == 0)
            return Array.Empty<string>();

        var terms = new List<string>();
        foreach (Match match in Regex.Matches(
                     s,
                     @"(?i)\b(?:sans|pas\s+d['\u2019]?|pas\s+de|without|no|sin|sem|ohne|senza)\s+(?<term>[\p{L}\p{N}'\u2019 \-]{2,60})",
                     RegexOptions.CultureInvariant))
        {
            foreach (var rawPart in Regex.Split(
                match.Groups["term"].Value,
                @"\s*(?:,|/|\bet\b|\bou\b|\bni\b|\band\b|\bor\b|\bnor\b|\by\b|\bo\b|\be\b|\boder\b|\bund\b)\s*",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
            {
                var term = Regex.Replace(
                        rawPart,
                        @"(?i)\b(?:avec|with|dans|from|pour|for|sur|de|du|des|document|documents|source|sources|element|elements|item|items|option|options)\b.*$",
                        string.Empty,
                        RegexOptions.CultureInvariant)
                    .Trim(' ', '.', ',', ':', ';', '?', '!', '"', '\'');

                var normalized = NormalizeLexicalLookup(term);
                if (LooksLikeIdiomaticNoDetailExclusion(normalized, NormalizeLexicalLookup(match.Value)))
                    continue;
                if (normalized.Length >= 2)
                    terms.Add(normalized);
            }
        }

        foreach (Match match in Regex.Matches(
                     s,
                     @"(?i)\b(?:en\s+evitant|en\s+évitant|evitant|évitant|eviter|éviter|avoid(?:ing)?|except|sauf|salvo|sem|ohne|senza)\s+(?<terms>[^.?!;]{2,140})",
                     RegexOptions.CultureInvariant))
        {
            foreach (var rawPart in Regex.Split(match.Groups["terms"].Value, @"\s*(?:,|/|\bet\b|\bou\b|\bni\b|\band\b|\bor\b|\bnor\b|\by\b|\bo\b|\be\b|\boder\b|\bund\b)\s*", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
            {
                var part = Regex.Replace(
                        rawPart,
                        @"(?i)\b(?:dans|from|pour|for|sur|avec|with|document|documents|source|sources|element|elements|item|items|option|options)\b.*$",
                        string.Empty,
                        RegexOptions.CultureInvariant)
                    .Trim(' ', '.', ',', ':', ';', '?', '!', '"', '\'');
                var normalized = NormalizeLexicalLookup(part);
                if (LooksLikeIdiomaticNoDetailExclusion(normalized, NormalizeLexicalLookup(match.Value)))
                    continue;
                if (normalized.Length >= 2)
                    terms.Add(normalized);
            }
        }

        return terms.Distinct(StringComparer.Ordinal).Take(5).ToArray();
    }

    private static bool LooksLikeIdiomaticNoDetailExclusion(string normalizedTerm, string normalizedMatch)
    {
        if (string.IsNullOrWhiteSpace(normalizedTerm))
            return true;

        if (Regex.IsMatch(
                normalizedMatch,
                @"\b(?:sans|without|sin|sem|ohne|senza)\s+(?:rentrer|entrer|going|go|entrar|entrando)\s+(?:dans|into|en|em|in)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        return Regex.IsMatch(
            normalizedTerm,
            @"^(?:rentrer|entrer|going|go|entrar|entrando)(?:\s+(?:dans|into|en|em|in))?$",
            RegexOptions.CultureInvariant);
    }

    private static bool RagHitContainsAnyExcludedTerm(RagHitSummary hit, IReadOnlyList<string> excludedTerms)
    {
        if (excludedTerms.Count == 0)
            return false;

        var haystack = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        return excludedTerms.Any(term =>
        {
            return Regex.IsMatch(
                haystack,
                $@"(^|[^\p{{L}}\p{{N}}]){Regex.Escape(term)}(?:s|es)?([^\p{{L}}\p{{N}}]|$)",
                RegexOptions.CultureInvariant);
        });
    }

    private static string BuildNoSourceBackedCompliantOptionAnswer(string language, IReadOnlyList<string> excludedTerms, IReadOnlyList<RagHitSummary> hits)
    {
        language = NormalizeLanguageCode(language);
        var excluded = string.Join(", ", excludedTerms);
        var labels = language switch
        {
            "en" => (
                Header: $"I did not find a source-backed option that respects the exclusion: {excluded}.",
                Detail: "The retrieved source excerpts still contain the excluded element, so I will not invent a compliant variant.",
                Nearby: "Retrieved conflicting sources:"
            ),
            "es" => (
                Header: $"No he encontrado una opcion con fuente que respete la exclusion: {excluded}.",
                Detail: "Los extractos recuperados siguen conteniendo el elemento excluido, asi que no invento una variante conforme.",
                Nearby: "Fuentes recuperadas en conflicto:"
            ),
            "pt" => (
                Header: $"Nao encontrei uma opcao com fonte que respeite a exclusao: {excluded}.",
                Detail: "Os excertos recuperados ainda contem o elemento excluido, por isso nao invento uma variante conforme.",
                Nearby: "Fontes recuperadas em conflito:"
            ),
            "de" => (
                Header: $"Ich habe keine quellenbasierte Option gefunden, die den Ausschluss erfuellt: {excluded}.",
                Detail: "Die gefundenen Auszuege enthalten das ausgeschlossene Element weiterhin, daher erfinde ich keine passende Variante.",
                Nearby: "Gefundene widersprechende Quellen:"
            ),
            "it" => (
                Header: $"Non ho trovato un'opzione supportata dalle fonti che rispetti l'esclusione: {excluded}.",
                Detail: "Gli estratti recuperati contengono ancora l'elemento escluso, quindi non invento una variante conforme.",
                Nearby: "Fonti recuperate in conflitto:"
            ),
            _ => (
                Header: $"Je n'ai pas trouve d'option sourcee qui respecte l'exclusion : {excluded}.",
                Detail: "Les extraits retrouves contiennent encore l'element exclu, donc je n'invente pas une variante conforme.",
                Nearby: "Sources retrouvees en conflit :"
            )
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(labels.Detail);
        sb.AppendLine(labels.Nearby);
        foreach (var hit in hits.Take(3))
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 240);
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            sb.AppendLine(excerpt);
        }

        AppendSourceBackedExtractionQualityCaveat(sb, hits, language);
        return sb.ToString().TrimEnd();
    }

    private static void AppendSourceBackedExtractionQualityCaveat(StringBuilder sb, IReadOnlyList<RagHitSummary> hits, string language)
    {
        if (!hits.Any(ShouldFlagExtractionQualityCaveat))
            return;

        var note = NormalizeLanguageCode(language) switch
        {
            "en" => "Note: at least one cited page has a low extraction/OCR confidence flag, so verify the source page if the detail is critical.",
            "es" => "Nota: al menos una pagina citada tiene una marca de baja confianza de extraccion/OCR; verifica la pagina fuente si el detalle es critico.",
            "pt" => "Nota: pelo menos uma pagina citada tem baixa confianca de extracao/OCR; verifica a pagina fonte se o detalhe for critico.",
            "de" => "Hinweis: Mindestens eine zitierte Seite hat eine niedrige Extraktions- oder OCR-Vertrauensbewertung. Pruefe die Quellseite, wenn das Detail kritisch ist.",
            "it" => "Nota: almeno una pagina citata ha un indicatore di bassa affidabilita di estrazione/OCR; verifica la pagina sorgente se il dettaglio e critico.",
            _ => "Note : au moins une page citee a un signal de confiance faible d'extraction/OCR ; verifie la page source si le detail est critique."
        };

        sb.AppendLine();
        sb.Append(note);
    }

    private static bool ShouldFlagExtractionQualityCaveat(RagHitSummary hit)
    {
        if (hit.ManualReviewRecommended)
            return true;

        if (hit.ExtractionConfidence is <= 0.5)
            return true;

        var status = (hit.QualityStatus ?? string.Empty).Trim().ToLowerInvariant();
        return status.Contains("manual_review", StringComparison.Ordinal)
            || status.Contains("low_text", StringComparison.Ordinal)
            || status.Contains("ocr_failed", StringComparison.Ordinal)
            || status.Contains("low_confidence", StringComparison.Ordinal);
    }

    private static bool LooksLikeSourceBackedQuantityScalingRequest(string? query)
    {
        var normalized = NormalizeLooseLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var asksExplicitScaling = Regex.IsMatch(
            normalized,
                @"\b(?:adapte|adapter|ajuste|ajuster|convertis|convertir|multiplie|multiplier|calcule|calculer|mets|mettre|quantites?|quantit[eé]s?|amounts?|values?|valeurs?|scale|resize|adjust|adapt|convert|multiply|counts?|units?|items?)\b",
            RegexOptions.CultureInvariant);
        if (LooksLikeDocumentaryPlanningRequest(query) && !asksExplicitScaling)
            return false;

        return asksExplicitScaling && TryExtractTargetScaleCount(query, out _);
    }

    private static string BuildSourceBackedQuantityScalingAnswer(string language, string query, IReadOnlyList<RagHitSummary> hits)
    {
        language = NormalizeLanguageCode(language);
        if (!TryExtractTargetScaleCount(query, out var targetCount))
            return string.Empty;

        var candidates = SelectQuantityScalingCandidates(hits, query, targetCount);

        var selected = candidates.FirstOrDefault();
        if (selected is null)
            return string.Empty;

        var factor = targetCount / (double)selected.SourceCount;
        var labels = BuildQuantityScalingLabels(language);
        var docLabel = string.IsNullOrWhiteSpace(selected.Hit.DocName) ? selected.Hit.DocPath : selected.Hit.DocName;
        var factorText = FormatScaleNumber(factor);

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.Append(labels.Base);
        sb.Append(' ');
        sb.Append(docLabel);
        sb.Append(' ');
        sb.Append(SourceBackedPagePrefix(language));
        sb.Append(selected.Hit.PageStart);
        sb.Append(" - ");
        sb.Append(selected.SourceCount);
        sb.Append(" -> ");
        sb.Append(targetCount);
        sb.Append(" (");
        sb.Append(labels.Factor);
        sb.Append(" x");
        sb.Append(factorText);
        sb.AppendLine(").");

        sb.AppendLine(labels.ItemizedList);
        foreach (var line in selected.Lines.Take(18))
        {
            sb.Append("- ");
            sb.Append(line.Scaled);
            sb.Append(" (");
            sb.Append(labels.Source);
            sb.Append(": ");
            sb.Append(line.Original);
            sb.AppendLine(")");
        }

        sb.Append(labels.Caution);
        return sb.ToString().TrimEnd();
    }

    private static List<QuantityScalingCandidate> SelectQuantityScalingCandidates(IEnumerable<RagHitSummary> hits, string query, int targetCount)
    {
        var subject = TryExtractQuantityScalingSubject(query);
        return hits
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Select(hit =>
            {
                var text = GetBestRagEvidenceText(hit);
                int sourceCount;
                string? sourceCountLabel;
                List<QuantityScaleLine> lines;
                if (TryBuildQuantityScaleLinesFromCardEvidence(
                        hit,
                        query,
                        targetCount,
                        out sourceCount,
                        out sourceCountLabel,
                        out var evidenceLines))
                {
                    lines = evidenceLines;
                }
                else
                {
                    sourceCount = TryExtractSourceScaleBaseCount(text, out var baseCount, out sourceCountLabel) ? baseCount : 0;
                    lines = sourceCount > 0
                        ? ExtractQuantityScaleLines(text, targetCount / (double)sourceCount)
                        : new List<QuantityScaleLine>();
                }
                var isScalable = sourceCount > 0
                    && HasExplicitScalableQuantitySourceSignal(hit, query, text, sourceCountLabel, lines);
                var score = isScalable
                    ? ComputeRagHitLexicalRelevance(string.IsNullOrWhiteSpace(subject) ? query : subject!, GetRagHitLookupText(hit))
                      + 16
                      + Math.Min(lines.Count(static line => line.IsNumeric), 8)
                    : double.NegativeInfinity;
                return new QuantityScalingCandidate(hit, sourceCount, lines, score);
            })
            .Where(item => item.SourceCount > 0
                           && item.Lines.Count(static line => line.IsNumeric) >= 2
                           && !double.IsNegativeInfinity(item.Score))
            .OrderByDescending(item => item.Score)
            .ThenByDescending(item => item.Hit.Score)
            .ToList();
    }

    private static bool HasExplicitScalableQuantitySourceSignal(
        RagHitSummary hit,
        string query,
        string evidenceText,
        string? sourceCountLabel,
        IReadOnlyList<QuantityScaleLine> lines)
    {
        if (HasContentCardNonScalableEvidence(hit) && !HasContentCardScalableQuantityEvidence(hit))
            return false;

        if (LooksLikeSafetyOrComplianceQuantityContext(hit, query, evidenceText))
            return false;

        var numericLineCount = lines.Count(static line => line.IsNumeric);
        if (numericLineCount < 2)
            return false;

        TryExtractTargetScaleCount(query, out _, out var targetCountLabel);
        var labelsCompatible = ScaleCountLabelsLookCompatible(sourceCountLabel, targetCountLabel);
        var sourceLabelIsListHeading = IsQuantityScaleListHeadingLabel(sourceCountLabel);
        var sourceLabelLooksScalable = sourceLabelIsListHeading || IsLikelyScalableScaleCountLabel(sourceCountLabel);
        var cardHasScalableQuantityBasis = TryExtractScalableQuantityCardBasis(
            hit,
            out _,
            out var cardScaleCountLabel);
        var cardLabelsCompatible = ScaleCountLabelsLookCompatible(cardScaleCountLabel, targetCountLabel);

        var normalizedEvidence = NormalizeLooseLookup(evidenceText);
        var cardSignals = BuildQuantityScalingCardSignalText(hit);
        var sourceContext = NormalizeLooseLookup(
            $"{hit.SectionTitle} {hit.HeadingPath} {hit.CategoryPath} {normalizedEvidence} {cardSignals}");

        var hasExplicitBase = HasExplicitQuantityScaleBasePhrase(normalizedEvidence) || cardHasScalableQuantityBasis;
        var hasQuantityListSignal = HasQuantityListSignal(sourceContext)
                                    || HasQuantityListCardSignal(hit)
                                    || numericLineCount >= 3;
        var hasScalableSignal = HasScalableQuantitySignal(sourceContext) || cardHasScalableQuantityBasis;

        return hasExplicitBase
               && hasQuantityListSignal
               && (hasScalableSignal || labelsCompatible || cardLabelsCompatible || sourceLabelLooksScalable);
    }

    private static bool TryExtractScalableQuantityCardBasis(RagHitSummary hit, out int count, out string? label)
    {
        count = 0;
        label = null;
        if (hit.MatchedContentCards is not { Count: > 0 })
            return false;

        foreach (var card in hit.MatchedContentCards)
        {
            if (card.Evidence?.ScaleBasis is { Count: > 0 } basis
                && card.Evidence.NonScalableReasons.Count == 0
                && card.Evidence.QuantityFacts.Count >= 2)
            {
                count = basis.Count;
                label = basis.Label;
                return true;
            }

            var hasScaleBasis = false;
            var hasQuantityList = false;
            var hasScalableQuantities = false;
            var cardCount = 0;
            string? cardLabel = null;

            foreach (var signal in card.Signals ?? Array.Empty<string>())
            {
                var raw = CollapseWhitespace(signal).Trim();
                if (raw.Length == 0)
                    continue;

                var lower = raw.ToLowerInvariant();
                var normalized = NormalizeScaleSignalToken(raw);
                if (string.Equals(normalized, "scale_basis", StringComparison.Ordinal))
                {
                    hasScaleBasis = true;
                    continue;
                }

                if (string.Equals(normalized, "quantity_list", StringComparison.Ordinal))
                {
                    hasQuantityList = true;
                    continue;
                }

                if (string.Equals(normalized, "scalable_quantities", StringComparison.Ordinal))
                {
                    hasScalableQuantities = true;
                    continue;
                }

                if (lower.StartsWith("scale_basis_count:", StringComparison.Ordinal)
                    && int.TryParse(lower["scale_basis_count:".Length..], NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed)
                    && parsed is > 0 and <= 200)
                {
                    cardCount = parsed;
                    hasScaleBasis = true;
                    continue;
                }

                if (lower.StartsWith("scale_basis_label:", StringComparison.Ordinal))
                {
                    cardLabel = NormalizeScaleSignalToken(lower["scale_basis_label:".Length..]);
                }
            }

            if (cardCount > 0 && (hasScalableQuantities || (hasScaleBasis && hasQuantityList)))
            {
                count = cardCount;
                label = cardLabel;
                return true;
            }
        }

        return false;
    }

    private static bool TryBuildQuantityScaleLinesFromCardEvidence(
        RagHitSummary hit,
        string query,
        int targetCount,
        out int sourceCount,
        out string? sourceCountLabel,
        out List<QuantityScaleLine> lines)
    {
        sourceCount = 0;
        sourceCountLabel = null;
        lines = new List<QuantityScaleLine>();

        if (hit.MatchedContentCards is not { Count: > 0 }
            || LooksLikeSafetyOrComplianceQuantityContext(hit, query, GetBestRagEvidenceText(hit)))
        {
            return false;
        }

        foreach (var card in hit.MatchedContentCards)
        {
            var evidence = card.Evidence;
            if (evidence?.ScaleBasis is not { Count: > 0 } basis
                || evidence.NonScalableReasons.Count > 0
                || evidence.QuantityFacts.Count < 2)
            {
                continue;
            }

            var factor = targetCount / (double)basis.Count;
            var scaledLines = evidence.QuantityFacts
                .Where(static fact => fact.Value > 0
                                      && !string.IsNullOrWhiteSpace(fact.Unit)
                                      && !string.IsNullOrWhiteSpace(fact.Label))
                .Take(18)
                .Select(fact =>
                {
                    var source = string.IsNullOrWhiteSpace(fact.SourceText)
                        ? $"{FormatScaleNumber(fact.Value)} {fact.Unit} {fact.Label}"
                        : CollapseWhitespace(fact.SourceText);
                    var scaled = $"{FormatScaleNumber(fact.Value * factor)} {fact.Unit} {fact.Label}";
                    return new QuantityScaleLine(source, scaled, IsNumeric: true);
                })
                .ToList();

            if (scaledLines.Count(static line => line.IsNumeric) < 2)
                continue;

            sourceCount = basis.Count;
            sourceCountLabel = basis.Label;
            lines = scaledLines;
            return true;
        }

        return false;
    }

    private static bool HasQuantityListCardSignal(RagHitSummary hit)
    {
        if (hit.MatchedContentCards is not { Count: > 0 })
            return false;

        return hit.MatchedContentCards.Any(static card =>
            (card.Signals ?? Array.Empty<string>()).Any(static signal =>
            {
                var normalized = NormalizeScaleSignalToken(signal);
                return string.Equals(normalized, "quantity_list", StringComparison.Ordinal)
                       || string.Equals(normalized, "scalable_quantities", StringComparison.Ordinal);
            }));
    }

    private static string NormalizeScaleSignalToken(string? value)
    {
        var normalized = Regex.Replace(
                (value ?? string.Empty).Trim().ToLowerInvariant(),
                @"[^\p{L}\p{N}]+",
                "_",
                RegexOptions.CultureInvariant)
            .Trim('_');
        normalized = Regex.Replace(normalized, @"_+", "_", RegexOptions.CultureInvariant);
        return normalized;
    }

    private static bool LooksLikeSafetyOrComplianceQuantityContext(RagHitSummary hit, string query, string evidenceText)
    {
        var haystack = NormalizeLooseLookup(
            $"{query} {hit.DocName} {hit.DocPath} {hit.CategoryPath} {hit.SectionTitle} {hit.HeadingPath} {evidenceText} {BuildQuantityScalingCardSignalText(hit)}");

        if (string.IsNullOrWhiteSpace(haystack))
            return false;

        return Regex.IsMatch(
                haystack,
                @"\b(?:safety|security|securite|hazard|danger|risk|risque|warning|caution|emergency|incident|injury|explosion|fire|flammable|toxic|toxicity|exposure|contamination|ppe|epi|lockout|loto|compliance|conformite|conformity|regulatory|reglementaire|reglementation|regulation|directive|legal|law|statutory|norme|standard|iso|iec|clause|article|shall|must|mandatory|required|obligatoire|exigence|interdit|prohibited|forbidden|limit|limite|threshold|seuil)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                haystack,
                @"\b(?:do\s+not|must\s+not|shall\s+not|ne\s+pas|ne\s+jamais|il\s+faut|il\s+ne\s+faut\s+pas)\b",
                RegexOptions.CultureInvariant);
    }

    private static string BuildQuantityScalingCardSignalText(RagHitSummary hit)
        => hit.MatchedContentCards is null
            ? string.Empty
            : string.Join(
                ' ',
                hit.MatchedContentCards.Select(static card =>
                    $"{card.Title} {card.Kind} {string.Join(' ', card.Signals ?? Array.Empty<string>())} {string.Join(' ', card.Evidence?.NonScalableReasons ?? Array.Empty<string>())}"));

    private static bool HasExplicitQuantityScaleBasePhrase(string normalizedEvidence)
        => Regex.IsMatch(
               normalizedEvidence,
               @"\b(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s*[\p{L}'\u2019.\-]{0,30}\b",
               RegexOptions.CultureInvariant)
           || Regex.IsMatch(
               normalizedEvidence,
               @"\b(?:base|basis|batch|lot|serie|set|per\s+unit|par\s+unite|par\s+element)\b",
               RegexOptions.CultureInvariant)
           || Regex.IsMatch(
               normalizedEvidence,
                @"\b\d{1,3}\s*(?:items?|elements?|quantities?|quantites?|amounts?|values?|valeurs?|requirements?|materials?|materiel|components?|composants?|supplies|entries?)\s*\d",
               RegexOptions.CultureInvariant);

    private static bool HasQuantityListSignal(string normalizedContext)
        => Regex.IsMatch(
            normalizedContext,
            @"\b(?:quantites?|quantit[eé]s?|quantities?|amounts?|values?|valeurs?|items?|elements?|components?|composants?|materials?|materiel|supplies|entries?|requirements?)\b",
            RegexOptions.CultureInvariant);

    private static bool HasScalableQuantitySignal(string normalizedContext)
        => Regex.IsMatch(
            normalizedContext,
            @"\b(?:scale|scaled|scalable|scaling|adapter|adapte|adapted|adjust|adjusted|proportion(?:al|nel|nelle)?|ratio|factor|facteur|multiply|multiplier|base|basis|batch|lot|serie|personnes?|persons?|people|units?|items?)\b",
            RegexOptions.CultureInvariant);

    private static bool ScaleCountLabelsLookCompatible(string? sourceLabel, string? targetLabel)
    {
        var source = NormalizeScaleCountLabel(sourceLabel);
        var target = NormalizeScaleCountLabel(targetLabel);
        if (string.IsNullOrWhiteSpace(source) || string.IsNullOrWhiteSpace(target))
            return false;

        if (source == target)
            return true;

        if (IsQuantityScaleListHeadingLabel(source))
            return true;

        return (source, target) switch
        {
            ("personne", "people") or ("people", "personne") => true,
            ("person", "personne") or ("personne", "person") => true,
            ("unit", "unite") or ("unite", "unit") => true,
            ("item", "element") or ("element", "item") => true,
            _ => false
        };
    }

    private static bool IsLikelyScalableScaleCountLabel(string? label)
    {
        var normalized = NormalizeScaleCountLabel(label);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:personne|person|people|unit|unite|item|element|piece|part|batch|lot|set|serie)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool IsQuantityScaleListHeadingLabel(string? label)
    {
        var normalized = NormalizeScaleCountLabel(label);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:entry|item|element|quantity|quantite|amount|value|valeur|requirement|material|materiel|component|composant|supply)\b",
            RegexOptions.CultureInvariant);
    }

    private static string NormalizeScaleCountLabel(string? label)
    {
        var normalized = NormalizeLooseLookup(label)
            .Trim(' ', '.', ',', ';', ':', '-', '/', '\\');
        if (normalized.EndsWith("ies", StringComparison.Ordinal) && normalized.Length > 4)
            normalized = normalized[..^3] + "y";
        else if (normalized.EndsWith("es", StringComparison.Ordinal) && normalized.Length > 4)
            normalized = normalized[..^2];
        else if (normalized.EndsWith('s') && normalized.Length > 3)
            normalized = normalized[..^1];

        return normalized;
    }

    private static (string Header, string Base, string Factor, string ItemizedList, string Source, string Caution) BuildQuantityScalingLabels(string language)
    {
        return NormalizeLanguageCode(language) switch
        {
            "en" => (
                "Here is the deterministic quantity adaptation from the cited source.",
                "Source base:",
                "factor",
                "Adjusted quantities:",
                "source",
                "Quantities absent from the source stay unspecified; I do not invent missing steps."),
            "es" => (
                "Aqui tienes la adaptacion determinista de cantidades a partir de la fuente citada.",
                "Base fuente:",
                "factor",
                "Cantidades ajustadas:",
                "fuente",
                "Las cantidades ausentes de la fuente quedan sin especificar; no invento pasos que faltan."),
            "pt" => (
                "Aqui esta a adaptacao deterministica das quantidades a partir da fonte citada.",
                "Base da fonte:",
                "fator",
                "Quantidades ajustadas:",
                "fonte",
                "Quantidades ausentes da fonte ficam sem especificacao; nao invento passos em falta."),
            "de" => (
                "Hier ist die deterministische Mengenanpassung aus der zitierten Quelle.",
                "Quellbasis:",
                "Faktor",
                "Angepasste Mengen:",
                "Quelle",
                "Mengen, die in der Quelle fehlen, bleiben unspezifiziert; fehlende Schritte erfinde ich nicht."),
            "it" => (
                "Ecco l'adattamento deterministico delle quantita dalla fonte citata.",
                "Base fonte:",
                "fattore",
                "Quantita adattate:",
                "fonte",
                "Le quantita assenti dalla fonte restano non specificate; non invento passaggi mancanti."),
            _ => (
                "Voici l'adaptation deterministe des quantites a partir de la source citee.",
                "Base source :",
                "facteur",
                "Quantites adaptees :",
                "source",
                "Les quantites absentes de la source restent non specifiees ; je n'invente pas les etapes manquantes.")
        };
    }

    private static bool TryExtractTargetScaleCount(string? query, out int count)
        => TryExtractTargetScaleCount(query, out count, out _);

    private static bool TryExtractTargetScaleCount(string? query, out int count, out string? label)
        => TryExtractScaleCount(query, out count, out label);

    private static bool TryExtractSourceScaleBaseCount(string? text, out int count)
        => TryExtractSourceScaleBaseCount(text, out count, out _);

    private static bool TryExtractSourceScaleBaseCount(string? text, out int count, out string? label)
        => TryExtractScaleCount(text, out count, out label);

    private static bool TryExtractScaleCount(string? value, out int count, out string? label)
    {
        count = 0;
        label = null;
        var normalized = NormalizeLooseLookup(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var patterns = new[]
        {
            @"\b(?:pour|for|para|per|fur|fuer|zu|a|da)\s+(?<n>\d{1,3})(?:\s+(?<label>[\p{L}][\p{L}'\u2019.\-]{1,30}))?\b",
            @"\b(?<n>\d{1,3})\s*(?<label>[\p{L}][\p{L}'\u2019.\-]{1,30})(?=\d|\b)"
        };

        foreach (var pattern in patterns)
        {
            var match = Regex.Match(normalized, pattern, RegexOptions.CultureInvariant);
            if (match.Success
                && int.TryParse(match.Groups["n"].Value, out var n)
                && n is > 0 and <= 200
                && IsPlausibleScaleCountLabel(match.Groups["label"].Value))
            {
                count = n;
                label = NullIfWhiteSpace(match.Groups["label"].Value);
                return true;
            }
        }

        return false;
    }

    private static bool IsPlausibleScaleCountLabel(string? label)
    {
        var normalized = NormalizeLooseLookup(label);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        if (!Regex.IsMatch(normalized, @"^[\p{L}][\p{L}'\u2019.\-]{1,30}$", RegexOptions.CultureInvariant))
            return false;

        if (LooksLikeProcedureLeadLabel(normalized))
            return false;

        return !Regex.IsMatch(
            normalized,
            @"^(?:g|kg|mg|ml|cl|l|mm|cm|m|km|nm|bar|pa|kpa|mpa|v|kv|a|ma|w|kw|hz|rpm|%|s|sec|secs|secondes?|seconds?|min|mins|minutes?|h|hr|hrs|heures?|hours?|jour|jours|day|days|mois|month|months|annee|annees|year|years|c|celsius|fahrenheit)$",
            RegexOptions.CultureInvariant);
    }

    private const string OperationalActionLeadPattern =
        @"ouvrir|ouvrez|fermer|fermez|ajouter|ajoutez|appliquer|appliquez|configurer|configurez|connecter|connectez|installer|installez|lancer|lancez|demarrer|demarrez|arreter|arretez|retirer|retirez|supprimer|supprimez|remplacer|remplacez|valider|validez|verifier|verifiez|controler|controlez|mettre\s+a\s+jour|mettez\s+a\s+jour|actualiser|actualisez|executer|executez|activer|activez|desactiver|desactivez|selectionner|selectionnez|saisir|saisissez|regler|reglez|ajuster|ajustez|start|stop|open|close|add|apply|configure|connect|install|launch|run|execute|remove|delete|replace|validate|verify|check|update|enable|disable|select|enter|set|adjust|measure|restart";

    private static bool LooksLikeProcedureLeadLabel(string normalizedLabel)
        => Regex.IsMatch(
            NormalizeLooseLookup(normalizedLabel),
            @"^(?:pour|pendant|dans|puis|quand|lorsque|avant|apres|jusqu|jusque|then|when|after|before|until|while|durante|cuando|antes|despues|depois|quando|wenn|nach|bevor|" + OperationalActionLeadPattern + @")$",
            RegexOptions.CultureInvariant);

    private static string? TryExtractQuantityScalingSubject(string? query)
    {
        var s = CollapseWhitespace(query ?? string.Empty);
        if (s.Length == 0)
            return null;

        var patterns = new[]
        {
            @"(?i)\b(?:adapte|adapter|ajuste|ajuster|convertis|convertir|calcule|calculer|mets|mettre|scale|resize|adjust|adapt|convert)\s+(?:le|la|les|l['\u2019]|the\s+)?(?<title>.+?)\s+(?:pour|for|para|per|fur|fuer|zu|a)\s+\d{1,3}\b",
        };

        foreach (var pattern in patterns)
        {
            var match = Regex.Match(s, pattern, RegexOptions.CultureInvariant);
            if (match.Success)
            {
                var title = CleanupRequestedItemTitle(match.Groups["title"].Value);
                if (!string.IsNullOrWhiteSpace(title))
                    return title;
            }
        }

        return TryExtractRequestedItemTitle(query);
    }

    private static List<QuantityScaleLine> ExtractQuantityScaleLines(string text, double factor)
    {
        var normalized = text
            .Replace('\u2022', '|')
            .Replace('\u00b7', '|');
        normalized = Regex.Replace(
            normalized,
            @"(?<!^)(?<![\d,.])(?=\d+(?:[,.]\d+)?\s*(?:%|[a-zA-Z]{1,8}\.?|[\p{L}]{1,12})\b)",
            "|",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"(?<!^)(?<![\d,.])(?=\d+\s+[\p{L}'\u2019\-]{3,}(?:\s+[\p{L}'\u2019\-]{3,}){0,3}\b)",
            "|",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        var parts = Regex.Split(normalized, @"[|;\r\n]+", RegexOptions.CultureInvariant)
            .Select(CollapseWhitespace)
            .Where(part => part.Length > 0)
            .ToList();

        var lines = new List<QuantityScaleLine>();
        foreach (var part in parts.Skip(1))
        {
            if (LooksLikeQuantityListBoundary(part))
            {
                break;
            }

            if (TryScaleQuantitySegment(part, factor, out var scaled))
            {
                lines.Add(new QuantityScaleLine(part, scaled, IsNumeric: true));
                continue;
            }

            if (TryKeepQualitativeQuantitySegment(part, out var qualitative))
            {
                lines.Add(new QuantityScaleLine(part, qualitative, IsNumeric: false));
            }
        }

        return lines;
    }

    private static bool LooksLikeQuantityListBoundary(string text)
    {
        var normalized = NormalizeLooseLookup(text);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
                normalized,
                @"\b(?:preparation|workflow|workflows?|procedure|procedures?|process|execution|operation|operations|instructions?|method|methods?|methode|methodes|mode\s+operatoire|etape|etapes|steps?)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"^\d{1,3}\s*[\).\-]\s+\p{L}", RegexOptions.CultureInvariant);
    }

    private static bool TryKeepQualitativeQuantitySegment(string segment, out string scaled)
    {
        scaled = string.Empty;
        var cleaned = CollapseWhitespace(segment ?? string.Empty).Trim(' ', '.', ',', ';', ':', '-', '\u2022', '\u00b7');
        if (string.IsNullOrWhiteSpace(cleaned))
            return false;

        var normalized = NormalizeLexicalLookup(cleaned);
        if (!Regex.IsMatch(normalized, @"^[\p{L}'\-\s]{3,70}$", RegexOptions.CultureInvariant))
            return false;
        if (Regex.IsMatch(normalized, @"\b(?:preparation|operation|workflow|execution|procedure|method|methode|etapes?|steps?|instructions?|requirements?|values?|materiel|materials?|equipment|tools?|outils?)\b", RegexOptions.CultureInvariant))
            return false;

        scaled = $"{cleaned} (sans quantite sourcee)";
        return true;
    }

    private static bool TryScaleQuantitySegment(string segment, double factor, out string scaled)
    {
        scaled = string.Empty;
        var match = Regex.Match(
            segment,
            @"^\s*(?<num>\d+(?:[,.]\d+)?|[1-9]\d*\s*/\s*[1-9]\d*|\u00bd|\u00bc|\u00be)\s*(?<rest>.+)$",
            RegexOptions.CultureInvariant);
        if (!match.Success)
            return false;

        if (!TryParseFlexibleNumber(match.Groups["num"].Value, out var number))
            return false;

        var rest = CollapseWhitespace(match.Groups["rest"].Value);
        if (string.IsNullOrWhiteSpace(rest))
            return false;
        if (LooksLikeNonScalableQuantitySegment(rest))
            return false;

        var scaledNumber = number * factor;
        scaled = FormatScaleNumber(scaledNumber) + " " + rest;
        return true;
    }

    private static bool LooksLikeNonScalableQuantitySegment(string rest)
    {
        var normalized = NormalizeLooseLookup(rest);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        if (Regex.IsMatch(
                normalized,
                @"^(?:min|mins|minutes?|h|hr|hrs|heures?|hours?|s|sec|secs|secondes?|seconds?|jour|jours|days?)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"^(?:bar|pa|kpa|mpa|v|kv|a|ma|w|kw|hz|rpm|%|mm|cm|m|km|nm|eur|euro|euros|chf|usd|gbp)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"^(?:celsius|fahrenheit|degrees?|degres?)\b|^°\s*c\b|^c\s*$",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"^(?:items?|elements?|quantities?|quantites?|amounts?|values?|valeurs?|requirements?|materials?|materiel|components?|composants?|supplies|entries?)$",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"^(?:units?|unites?|personnes?|persons?|people)\s*:?$",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        return Regex.IsMatch(
            normalized,
            @"\b(?:temperature|temp|pressure|pression|voltage|tension|current|courant|speed|vitesse|frequency|frequence|torque|couple|force|setting|reglage|parametre|parameter|limit|limite|threshold|seuil|tolerance|clearance|jeu|distance|dimension|diameter|diametre|angle|slope|pente|concentration|dosage|ph)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool TryParseFlexibleNumber(string value, out double number)
    {
        number = 0;
        var s = CollapseWhitespace(value)
            .Replace(',', '.');

        if (s == "\u00bd")
        {
            number = 0.5;
            return true;
        }
        if (s == "\u00bc")
        {
            number = 0.25;
            return true;
        }
        if (s == "\u00be")
        {
            number = 0.75;
            return true;
        }

        var fraction = Regex.Match(s, @"^(?<a>\d+)\s*/\s*(?<b>\d+)$", RegexOptions.CultureInvariant);
        if (fraction.Success
            && double.TryParse(fraction.Groups["a"].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out var a)
            && double.TryParse(fraction.Groups["b"].Value, NumberStyles.Float, CultureInfo.InvariantCulture, out var b)
            && b != 0)
        {
            number = a / b;
            return true;
        }

        return double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out number);
    }

    private static string FormatScaleNumber(double value)
    {
        var rounded = Math.Abs(value - Math.Round(value)) < 0.0001
            ? Math.Round(value)
            : Math.Round(value, 2);

        return rounded.ToString(rounded % 1 == 0 ? "0" : "0.##", CultureInfo.InvariantCulture)
            .Replace('.', ',');
    }

    private static string BuildSourceBackedAdaptationAnswer(string language, string query, IReadOnlyList<RagHitSummary> hits)
    {
        language = NormalizeLanguageCode(language);
        var selected = RankSourceBackedAdaptationHits(hits, query)
            .Take(5)
            .ToList();
        if (selected.Count == 0)
            return string.Empty;

        var labels = BuildSourceBackedAdaptationLabels(language);
        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(labels.SourceSection);
        foreach (var hit in selected.Take(4))
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: SourceBackedEvidenceMaxChars);
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            sb.AppendLine(excerpt);
        }

        var targetFacts = ExtractSourceBackedAdaptationTargetFacts(selected, query, maxFacts: 5, language);
        if (targetFacts.Count > 0)
        {
            sb.AppendLine(SourceBackedLabel(
                language,
                "Cibles visibles a adapter :",
                "Visible targets to adapt:",
                "Objetivos visibles que adaptar:",
                "Alvos visiveis a adaptar:",
                "Sichtbare anzupassende Ziele:",
                "Obiettivi visibili da adattare:"));
            foreach (var fact in targetFacts)
            {
                sb.Append("- ");
                sb.AppendLine(fact);
            }
        }

        sb.AppendLine(labels.AdaptationSection);
        foreach (var note in BuildSourceBackedAdaptationNotes(language, query))
        {
            sb.Append("- ");
            sb.AppendLine(note);
        }

        sb.Append(labels.Caution);
        return sb.ToString().TrimEnd();
    }

    private static IReadOnlyList<RagHitSummary> RankSourceBackedAdaptationHits(IEnumerable<RagHitSummary> hits, string query)
    {
        var focusGroups = BuildSourceBackedAdaptationFocusGroups(query);
        var focusQuery = string.Join(' ', focusGroups.SelectMany(static group => group).Distinct(StringComparer.Ordinal));
        var scored = hits
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Select(hit =>
            {
                var primaryText = GetRagHitPrimaryEvidenceText(hit);
                var lookupText = GetRagHitLookupText(hit);
                var primaryMatches = CountMatchedFocusGroups(focusGroups, primaryText);
                var lookupMatches = CountMatchedFocusGroups(focusGroups, lookupText);
                return new
                {
                    Hit = hit,
                    MatchedFocusGroups = primaryMatches,
                    LookupMatchedFocusGroups = lookupMatches,
                    TargetFactScore = CountSourceBackedAdaptationTargetFacts(hit, query),
                    PrimaryRelevance = ComputeRagHitLexicalRelevance(focusQuery, primaryText),
                    Relevance = ComputeRagHitLexicalRelevance(focusQuery, lookupText),
                    IsIntroLead = LooksLikeIntroLeadInHit(hit)
                };
            })
            .ToList();

        if (scored.Count == 0)
            return Array.Empty<RagHitSummary>();

        var bestMatchCount = scored.Max(static item => item.MatchedFocusGroups);
        if (bestMatchCount >= 2)
        {
            scored = scored
                .Where(item => item.MatchedFocusGroups >= 2)
                .ToList();
        }

        var bestTargetFactScore = scored.Max(static item => item.TargetFactScore);
        if (bestTargetFactScore > 0)
        {
            scored = scored
                .Where(static item => item.TargetFactScore > 0)
                .ToList();
        }

        var nonIntroScored = scored
            .Where(static item => !item.IsIntroLead)
            .ToList();
        if (nonIntroScored.Count > 0)
            scored = nonIntroScored;

        return scored
            .OrderByDescending(static item => item.MatchedFocusGroups)
            .ThenByDescending(static item => item.TargetFactScore)
            .ThenByDescending(static item => item.LookupMatchedFocusGroups)
            .ThenByDescending(static item => item.PrimaryRelevance)
            .ThenByDescending(static item => item.Relevance)
            .ThenByDescending(static item => item.Hit.Score)
            .Select(static item => item.Hit)
            .ToList();
    }

    private static IReadOnlyList<IReadOnlyList<string>> BuildSourceBackedAdaptationFocusGroups(string query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<IReadOnlyList<string>>();

        return ExtractQuerySignalTerms(normalized)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !Regex.IsMatch(
                term,
                @"\b(?:alleger|all[e\u00e9]ger|lighten|reduce|reduire|adapter|adaptation|adapte|changer|modifier|change|modify|prudente|prudent)\b",
                RegexOptions.CultureInvariant))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .Select(static term => (IReadOnlyList<string>)BuildRetrievalTermVariants(term)
                .Distinct(StringComparer.Ordinal)
                .ToArray())
            .Where(static group => group.Count > 0)
            .ToArray();
    }

    private static int CountMatchedFocusGroups(IReadOnlyList<IReadOnlyList<string>> focusGroups, string? text)
    {
        if (focusGroups.Count == 0 || string.IsNullOrWhiteSpace(text))
            return 0;

        var normalizedText = NormalizeLexicalLookup(text);
        if (string.IsNullOrWhiteSpace(normalizedText))
            return 0;

        return focusGroups.Count(group => group.Any(term =>
            term.Length >= 3 && normalizedText.Contains(term, StringComparison.Ordinal)));
    }

