    private static IReadOnlyList<string> ExtractSourceBackedAdaptationTargetFacts(IReadOnlyList<RagHitSummary> hits, string query, int maxFacts, string language)
    {
        var targetGroups = BuildSourceBackedAdaptationTargetGroups(query);
        if (targetGroups.Count == 0)
            targetGroups = BuildSourceBackedAdaptationFocusGroups(query);
        if (targetGroups.Count == 0)
            return Array.Empty<string>();

        var facts = new List<string>();
        foreach (var hit in hits)
        {
            var segments = ExtractAdaptationEvidenceSegments(hit, targetGroups)
                .Take(3)
                .ToList();
            if (segments.Count == 0)
                continue;

            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            facts.Add($"{docLabel} {SourceBackedPagePrefix(language)}{hit.PageStart} : {string.Join("; ", segments)}");
            if (facts.Count >= maxFacts)
                break;
        }

        return facts;
    }

    private static int CountSourceBackedAdaptationTargetFacts(RagHitSummary hit, string query)
    {
        var targetGroups = BuildSourceBackedAdaptationTargetGroups(query);
        if (targetGroups.Count == 0)
            targetGroups = BuildSourceBackedAdaptationFocusGroups(query);
        if (targetGroups.Count == 0)
            return 0;

        return ExtractAdaptationEvidenceSegments(hit, targetGroups).Take(4).Count();
    }

    private static IReadOnlyList<IReadOnlyList<string>> BuildSourceBackedAdaptationTargetGroups(string query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<IReadOnlyList<string>>();

        var terms = new List<string>();
        foreach (Match match in Regex.Matches(
            normalized,
            @"\b(?:moins\s+de|less|reduce(?:d)?|reduire|reduit|diminuer|diminution|alleger|all[e\u00e9]ger|lighten|sans|without|en|in|de|du|des)\s+(?:la\s+|le\s+|les\s+|l\s+|d\s+|the\s+)?(?<target>[\p{L}][\p{L}\p{N}_-]{2,30})",
            RegexOptions.CultureInvariant))
        {
            var term = match.Groups["target"].Value;
            if (!IsSourceBackedActionRetrievalNoiseTerm(term))
                terms.Add(term);
        }

        return terms
            .Select(NormalizeLexicalLookup)
            .Where(static term => term.Length >= 3)
            .Where(static term => !Regex.IsMatch(term, @"\b(?:document|documents|pdf|source|sources|adaptation|prudente|base)\b", RegexOptions.CultureInvariant))
            .Distinct(StringComparer.Ordinal)
            .Take(6)
            .Select(static term => (IReadOnlyList<string>)BuildRetrievalTermVariants(term)
                .Distinct(StringComparer.Ordinal)
                .ToArray())
            .Where(static group => group.Count > 0)
            .ToArray();
    }

    private static IEnumerable<string> ExtractAdaptationEvidenceSegments(RagHitSummary hit, IReadOnlyList<IReadOnlyList<string>> targetGroups)
    {
        var text = CollapseWhitespace(GetRagHitPrimaryContentText(hit));
        if (string.IsNullOrWhiteSpace(text))
            yield break;

        var previousWasItemizedLabel = false;
        foreach (var segment in Regex.Split(text, @"(?:[•\n\r]|(?<=[.;:])\s+)"))
        {
            var value = CollapseWhitespace(segment).Trim(' ', '-', ':', ';', ',');
            if (value.Length < 5)
                continue;
            if (value.Length > 140)
                value = value[..140].TrimEnd() + "...";

            var normalizedSegment = NormalizeLexicalLookup(value);
            var carriesItemizedContext = previousWasItemizedLabel;
            previousWasItemizedLabel = Regex.IsMatch(
                normalizedSegment,
                @"^\b(?:items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?|materials?|materiel|mat[eé]riel|components?|composants?)\b$",
                RegexOptions.CultureInvariant);
            if (!targetGroups.Any(group => group.Any(term => term.Length >= 3 && normalizedSegment.Contains(term, StringComparison.Ordinal))))
                continue;

            var hasSpecificSignal = Regex.IsMatch(
                normalizedSegment,
                @"\b\d+(?:[,.]\d+)?\s*(?:%|[a-zA-Z]{1,8}\.?|[\p{L}]{1,12}|min|h)\b|\b(?:quantite|quantites|amount|quantity|constraint|contrainte)\b",
                RegexOptions.CultureInvariant);
            if (!hasSpecificSignal
                && (carriesItemizedContext || LooksLikeDelimitedTargetFact(value))
                && value.Contains(',', StringComparison.Ordinal))
            {
                hasSpecificSignal = true;
            }
            if (!hasSpecificSignal)
                continue;

            yield return value;
        }
    }

    private static string ExtractSourceBackedAdaptationObjective(string query)
    {
        var objective = CollapseWhitespace(query);
        objective = Regex.Replace(
            objective,
            @"(?i)\b(?:dis\s+bien|separe|separer|distingue|distinguer|indique|indiquer|precise|preciser|tell|separate|distinguish|show|state)\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant);
        objective = objective.Trim(' ', '.', '?', '!', ':', ';', ',');
        if (objective.Length == 0)
            objective = CollapseWhitespace(query);

        return objective.Length <= 140
            ? objective
            : objective[..140].TrimEnd() + "...";
    }

    private static IReadOnlyList<string> ExtractSourceBackedAdaptationFocusTerms(string query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        return ExtractQuerySignalTerms(normalized)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Where(static term => !Regex.IsMatch(
                term,
                @"\b(?:alleger|all[e\u00e9]ger|lighten|reduce|reduire|adapter|adaptation|adapte|changer|modifier|change|modify|prudente|prudent)\b",
                RegexOptions.CultureInvariant))
            .SelectMany(BuildRetrievalTermVariants)
            .Distinct(StringComparer.Ordinal)
            .Take(5)
            .ToArray();
    }

    private static string BuildSourceBackedRankingAnswer(string language, string query, IReadOnlyList<RagHitSummary> hits)
    {
        language = NormalizeLanguageCode(language);
        var entityAnchors = ExtractComparativeEntityAnchorTerms(query);
        var ranked = RankSourceBackedRankingHits(hits, query)
            .Take(4)
            .ToList();
        if (LooksLikeTechnicalRankingQuery(query))
        {
            var structuredEnoughRanked = ranked
                .Where(static hit => !LooksLikeLowStructureShortProcedureHit(hit))
                .ToList();
            if (structuredEnoughRanked.Count > 0)
                ranked = PreserveComparativeEntityCoverage(ranked, structuredEnoughRanked, entityAnchors);

            var nonVeryShortRanked = ranked
                .Where(static hit => ExtractBestVisibleDurationMinutes(hit) is not int minutes || minutes > 3)
                .ToList();
            if (nonVeryShortRanked.Count > 0)
                ranked = PreserveComparativeEntityCoverage(ranked, nonVeryShortRanked, entityAnchors);
        }
        if (ranked.Count == 0)
            return string.Empty;

        var labels = BuildSourceBackedRankingLabels(language);
        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);

        var winner = ranked[0];
        sb.Append("- ");
        sb.Append(labels.MainCandidate);
        sb.Append(" : ");
        sb.Append(FormatRankingHitReference(language, winner));
        sb.Append(" - ");
        sb.AppendLine(BuildSourceBackedRankingReason(language, winner, query));

        if (ranked.Count > 1)
        {
            sb.AppendLine(labels.OtherCandidates);
            foreach (var hit in ranked.Skip(1).Take(3))
            {
                sb.Append("- ");
                sb.Append(FormatRankingHitReference(language, hit));
                sb.Append(" - ");
                sb.AppendLine(BuildSourceBackedRankingReason(language, hit, query));
            }
        }

        sb.Append(labels.Caution);
        return sb.ToString().TrimEnd();
    }

    private static (string Header, string MainCandidate, string OtherCandidates, string Caution) BuildSourceBackedRankingLabels(string language)
    {
        return NormalizeLanguageCode(language) switch
        {
            "en" => (
                "Based only on the available excerpts, here is the most defensible ranking:",
                "Main candidate",
                "Other source-backed candidates:",
                "This is not an absolute ranking of the whole knowledge base; it only reflects the retrieved excerpts."),
            "es" => (
                "Basandome solo en los extractos disponibles, este es el ranking mas defendible:",
                "Candidato principal",
                "Otros candidatos con fuente:",
                "No es un ranking absoluto de toda la base de conocimiento; refleja solo los extractos recuperados."),
            "pt" => (
                "Com base apenas nos excertos disponiveis, este e o ranking mais defensavel:",
                "Candidato principal",
                "Outros candidatos com fonte:",
                "Nao e um ranking absoluto de toda a base de conhecimento; reflete apenas os excertos recuperados."),
            "de" => (
                "Nur auf Basis der verfuegbaren Auszuege ist dies die belastbarste Rangfolge:",
                "Hauptkandidat",
                "Weitere belegte Kandidaten:",
                "Das ist keine absolute Rangfolge der gesamten Wissensbasis; sie spiegelt nur die gefundenen Auszuege wider."),
            "it" => (
                "Basandomi solo sugli estratti disponibili, questa e la classifica piu difendibile:",
                "Candidato principale",
                "Altri candidati con fonte:",
                "Non e una classifica assoluta di tutta la base di conoscenza; riflette solo gli estratti recuperati."),
            _ => (
                "D'apres les extraits disponibles uniquement, voici le classement le plus defendable :",
                "Candidat principal",
                "Autres candidats sources :",
                "Ce n'est pas un classement absolu de toute la base de connaissance ; il reflete seulement les extraits retrouves.")
        };
    }

    private static IReadOnlyList<RagHitSummary> RankSourceBackedRankingHits(IEnumerable<RagHitSummary> hits, string query)
    {
        var candidateHits = hits.ToList();
        if (candidateHits.Count == 0)
            return Array.Empty<RagHitSummary>();

        var technicalRanking = LooksLikeTechnicalRankingQuery(query);
        if (technicalRanking)
        {
            var nonGenericCandidates = candidateHits
                .Where(static hit => !LooksLikeGenericTechniqueDefinitionHit(hit))
                .ToList();
            if (nonGenericCandidates.Count > 0)
                candidateHits = nonGenericCandidates;
        }

        var entityAnchors = ExtractComparativeEntityAnchorTerms(query);
        if (entityAnchors.Length >= 2)
        {
            var entityMatchedHits = candidateHits
                .Where(hit => GetMatchedComparativeEntityAnchorIndexes(hit, entityAnchors).Length > 0)
                .ToList();
            if (entityMatchedHits.Count > 0)
                candidateHits = entityMatchedHits;
        }

        var allCandidateHits = candidateHits;
        var dominantHits = FilterHitsToDominantTopLevel(candidateHits, query).ToList();
        var dominantTargetHits = FilterRankingHitsToRequestedContentTarget(dominantHits, query).ToList();
        var allTargetHits = FilterRankingHitsToRequestedContentTarget(allCandidateHits, query).ToList();
        if (!TargetFilterHasEnoughStructuredRankingSupport(allCandidateHits, allTargetHits))
        {
            dominantTargetHits = dominantHits;
            allTargetHits = allCandidateHits;
        }

        candidateHits = dominantHits;
        var targetFilteredHits = dominantTargetHits;
        if (allTargetHits.Count < allCandidateHits.Count
            && dominantTargetHits.Count == dominantHits.Count)
        {
            candidateHits = allTargetHits;
            targetFilteredHits = allTargetHits;
        }
        if (technicalRanking)
        {
            var targetHasStructuredEvidence = targetFilteredHits.Any(static hit => !LooksLikeLowStructureShortProcedureHit(hit));
            var allHitsHaveStructuredEvidence = candidateHits.Any(static hit => !LooksLikeLowStructureShortProcedureHit(hit));
            if (targetHasStructuredEvidence || !allHitsHaveStructuredEvidence)
                candidateHits = targetFilteredHits;
        }
        else
        {
            candidateHits = targetFilteredHits;
        }
        if (technicalRanking)
        {
            var singlePageHits = candidateHits
                .Where(static hit => hit.PageEnd <= hit.PageStart)
                .ToList();
            if (singlePageHits.Count >= 2)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, singlePageHits, entityAnchors);

            var structuredEnoughHits = candidateHits
                .Where(static hit => !LooksLikeLowStructureShortProcedureHit(hit))
                .ToList();
            if (structuredEnoughHits.Count > 0)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, structuredEnoughHits, entityAnchors);

            var nonGenericTechniqueHits = candidateHits
                .Where(static hit => !LooksLikeGenericTechniqueDefinitionHit(hit))
                .ToList();
            if (nonGenericTechniqueHits.Count > 0)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, nonGenericTechniqueHits, entityAnchors);

            var completeProcedureHits = candidateHits
                .Where(static hit => ComputeProcedureCompletenessCueScore(hit) >= 7)
                .ToList();
            if (completeProcedureHits.Count > 0)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, completeProcedureHits, entityAnchors);

            var nonMidProcedureFragmentHits = candidateHits
                .Where(static hit => !LooksLikeMidProcedureFragment(hit))
                .ToList();
            if (nonMidProcedureFragmentHits.Count > 0)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, nonMidProcedureFragmentHits, entityAnchors);

            var technicallyConstrainedHits = candidateHits
                .Where(static hit => ComputeTechnicalComplexityCueScore(hit) >= 5)
                .ToList();
            if (technicallyConstrainedHits.Count > 0)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, technicallyConstrainedHits, entityAnchors);

            var nonSimpleHits = candidateHits
                .Where(static hit => !LooksLikeVerySimpleProcedureHit(hit))
                .ToList();
            if (nonSimpleHits.Count >= 2)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, nonSimpleHits, entityAnchors);

            structuredEnoughHits = candidateHits
                .Where(static hit => !LooksLikeLowStructureShortProcedureHit(hit))
                .ToList();
            if (structuredEnoughHits.Count > 0)
                candidateHits = PreserveComparativeEntityCoverage(candidateHits, structuredEnoughHits, entityAnchors);
        }

        var evidenceQuery = BuildRagEvidenceSelectionQuery(query);
        return candidateHits
            .Where(hit => !LooksLikeNavigationOnlyHit(hit))
            .Select((hit, index) => new
            {
                Hit = hit,
                Index = index,
                Score = ComputeSourceBackedRankingScore(hit, query, evidenceQuery)
            })
            .OrderByDescending(item => item.Score)
            .ThenBy(item => item.Index)
            .GroupBy(item => $"{item.Hit.DocPath}|{item.Hit.PageStart}", StringComparer.OrdinalIgnoreCase)
            .Select(static group => group.First())
            .Select(item => item.Hit)
            .ToList();
    }

    private static bool TargetFilterHasEnoughStructuredRankingSupport(
        IReadOnlyList<RagHitSummary> allHits,
        IReadOnlyList<RagHitSummary> targetHits)
    {
        if (targetHits.Count == 0 || targetHits.Count == allHits.Count)
            return true;

        if (targetHits.All(LooksLikeMidProcedureFragment)
            && allHits.Any(hit => !LooksLikeMidProcedureFragment(hit) && HasStrongStructuredRankingEvidence(hit)))
        {
            return false;
        }

        if (targetHits.Any(HasStrongStructuredRankingEvidence))
            return true;

        var targetKeys = targetHits
            .Select(BuildRagHitIdentityKey)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        return !allHits
            .Where(hit => !targetKeys.Contains(BuildRagHitIdentityKey(hit)))
            .Any(HasStrongStructuredRankingEvidence);
    }

    private static List<RagHitSummary> PreserveComparativeEntityCoverage(
        IReadOnlyList<RagHitSummary> current,
        List<RagHitSummary> candidate,
        IReadOnlyList<string[]> entityAnchors)
    {
        if (candidate.Count == 0 || entityAnchors.Count < 2)
            return candidate;

        var currentCoverage = CountComparativeEntityCoverage(current, entityAnchors);
        var candidateCoverage = CountComparativeEntityCoverage(candidate, entityAnchors);
        var requiredCoverage = Math.Min(currentCoverage, entityAnchors.Count);
        return candidateCoverage >= requiredCoverage ? candidate : current.ToList();
    }

    private static int CountComparativeEntityCoverage(
        IEnumerable<RagHitSummary> hits,
        IReadOnlyList<string[]> entityAnchors)
    {
        if (entityAnchors.Count == 0)
            return 0;

        return hits
            .SelectMany(hit => GetMatchedComparativeEntityAnchorIndexes(hit, entityAnchors))
            .Distinct()
            .Count();
    }

    private static bool HasStrongStructuredRankingEvidence(RagHitSummary hit)
        => ComputeProcedureCompletenessCueScore(hit) >= 7
            || ComputeStructuredProcedureEvidenceCueScore(hit) >= 7
            || ComputeStructuredProcedureVisibleEvidenceCueScore(hit) >= 7;

    private static string BuildRagHitIdentityKey(RagHitSummary hit)
        => $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}";

    private static IReadOnlyList<RagHitSummary> FilterRankingHitsToRequestedContentTarget(IReadOnlyList<RagHitSummary> hits, string query)
    {
        var entityAnchors = ExtractComparativeEntityAnchorTerms(query);
        if (entityAnchors.Length >= 2)
        {
            var entityMatchedHits = hits
                .Where(hit => GetMatchedComparativeEntityAnchorIndexes(hit, entityAnchors).Length > 0)
                .ToList();
            if (entityMatchedHits.Count > 0)
                return entityMatchedHits;
        }

        var normalizedQuery = NormalizeLexicalLookup(query);
        var targetTerms = ExtractQuerySignalTerms(normalizedQuery)
            .Where(static term => term.Length >= 4)
            .Where(static term => !Regex.IsMatch(
                term,
                @"^(?:quel|quelle|quels|quelles|which|what|plus|moins|meilleur|meilleure|best|worst|most|least|technique|technical|complexe|complex|difficile|difficult|classement|ranking|candidat|candidate)$",
                RegexOptions.CultureInvariant))
            .Distinct(StringComparer.Ordinal)
            .Take(4)
            .ToArray();
        if (targetTerms.Length == 0)
            return hits;

        var matchingHits = hits
            .Where(hit =>
            {
                var lookup = NormalizeLexicalLookup($"{hit.DocName} {hit.DocPath} {hit.SectionTitle} {hit.HeadingPath} {GetRagHitPrimaryContentText(hit)}");
                return targetTerms.Any(term => lookup.Contains(term, StringComparison.Ordinal));
            })
            .ToList();

        return matchingHits.Count > 0 ? matchingHits : hits;
    }

    private static double ComputeSourceBackedRankingScore(RagHitSummary hit, string query, string evidenceQuery)
    {
        var score = ComputeRagHitLexicalRelevance(evidenceQuery, GetRagHitPrimaryEvidenceText(hit)) * 3
            + ComputeRagHitLexicalRelevance(evidenceQuery, GetRagHitLookupText(hit))
            + Math.Min(3.0, Math.Max(0.0, hit.Score));

        if (LooksLikeTechnicalRankingQuery(query))
            score += ComputeTechnicalEvidenceCueScore(hit);

        var structuredProcedureScore = 0;
        if (LooksLikeProcedureRankingQuery(query))
        {
            structuredProcedureScore = ComputeStructuredProcedureEvidenceCueScore(hit);
            score += structuredProcedureScore;
        }

        return score;
    }

    private static bool LooksLikeTechnicalRankingQuery(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        return Regex.IsMatch(
            normalized,
            @"\b(?:technique|technical|tecnico|tecnica|technisch|complexe|complex|complique|difficile|difficult|schwierig|avance|advanced)\b",
            RegexOptions.CultureInvariant);
    }

    private static int ComputeTechnicalEvidenceCueScore(RagHitSummary hit)
    {
        return Math.Clamp(
            ComputeEvidenceShapeScore(hit, GetRagHitLookupText(hit), includeBackendHints: true),
            -4,
            12);
    }

    private static int ComputeTechnicalComplexityCueScore(RagHitSummary hit)
    {
        var rawText = GetRagHitPrimaryEvidenceText(hit);
        var text = NormalizeLexicalLookup(rawText);
        if (string.IsNullOrWhiteSpace(text))
            return 0;

        var labelCount = CountLabelValueMarkers(rawText);
        var stepCount = CountProcedureStepMarkers(text);
        var measuredCount = CountMeasuredValueMarkers(text);

        var score = 0;
        if (labelCount > 0 || stepCount >= 3)
            score += Math.Min(5, measuredCount);
        score += Math.Min(4, labelCount * 2);
        score += Math.Min(4, stepCount);
        score += Math.Min(3, CountBulletListMarkers(rawText));

        if (HasMeasurableConstraintEvidence(rawText, text))
            score += 3;
        if (labelCount >= 2 || stepCount >= 4)
            score += 2;
        if (ScoreMatchedContentCardShape(hit.MatchedContentCards) >= 3)
            score += 1;

        return score;
    }

    private static int ComputeProcedureCompletenessCueScore(RagHitSummary hit)
    {
        return Math.Clamp(
            ComputeEvidenceShapeScore(hit, GetRagHitPrimaryContentText(hit), includeBackendHints: true),
            -4,
            14);
    }

    private static int CountProcedureStepMarkers(string normalizedText)
    {
        if (string.IsNullOrWhiteSpace(normalizedText))
            return 0;

        var numeric = Regex.Matches(
            normalizedText,
            @"(?:^|[\r\n.;:]\s*|\s)[1-9]\d{0,2}[\.)]\s+\S",
            RegexOptions.CultureInvariant).Count;
        var bullets = Regex.Matches(
            normalizedText,
            @"[•\-]\s*(?:\p{L}{4,})(?:\s+\p{L}{2,}){2,}",
            RegexOptions.CultureInvariant).Count;

        return numeric + bullets;
    }

    private static int ComputeEvidenceShapeScore(
        RagHitSummary hit,
        string? evidenceText,
        bool includeBackendHints)
    {
        var rawText = evidenceText ?? string.Empty;
        var normalizedText = NormalizeStructuredScanText(rawText);
        if (string.IsNullOrWhiteSpace(normalizedText)
            && hit.MatchedContentCards is not { Count: > 0 }
            && string.IsNullOrWhiteSpace(hit.SelectionHintRole))
        {
            return 0;
        }

        var score = 0;
        if (includeBackendHints)
        {
            score += ScoreEvidenceRoleHint(hit);
            score += ScoreSelectionHintNumbers(hit);
        }

        if (hit.ExactMatchHit)
            score += 3;

        var retriever = NormalizeLexicalLookup(hit.Retriever);
        if (retriever.Contains("exact", StringComparison.Ordinal))
            score += 2;
        else if (retriever.Contains("sparse", StringComparison.Ordinal))
            score += 1;

        if (!string.IsNullOrWhiteSpace(hit.SectionTitle) || !string.IsNullOrWhiteSpace(hit.HeadingPath))
            score += 1;
        if (HasSourceBackedProfileTitle(hit))
            score += 2;

        score += ScoreMatchedContentCardShape(hit.MatchedContentCards);
        score += Math.Min(4, CountProcedureStepMarkers(rawText));
        score += Math.Min(3, CountBulletListMarkers(rawText));
        score += Math.Min(3, CountNumericFactMarkers(normalizedText));
        score += Math.Min(2, CountLabelValueMarkers(rawText));

        if (Regex.IsMatch(rawText, @"\|.+\|", RegexOptions.CultureInvariant))
            score += 1;

        if (hit.ManualReviewRecommended)
            score -= 1;
        if (hit.ExtractionConfidence.HasValue && hit.ExtractionConfidence.Value < 0.55)
            score -= 2;

        return Math.Clamp(score, -8, 18);
    }

    private static int ScoreEvidenceRoleHint(RagHitSummary hit)
    {
        return NormalizeRagEvidenceRole(hit.SelectionHintRole) switch
        {
            "actionable_item" => 4,
            "advisory" => 2,
            "supporting_context" => 1,
            "fragment" => -4,
            "navigation" => -5,
            "low_confidence" => -4,
            _ => 0
        };
    }

    private static int ScoreSelectionHintNumbers(RagHitSummary hit)
    {
        var score = 0;
        score += ScorePositiveHint(hit.SelectionHintActionabilityScore, high: 9, medium: 7, low: 5, highScore: 5, mediumScore: 3, lowScore: 1);
        score += ScorePositiveHint(hit.SelectionHintSupportScore, high: 8, medium: 5, low: 3, highScore: 2, mediumScore: 1, lowScore: 0);
        score -= ScorePositiveHint(hit.SelectionHintFragmentScore, high: 8, medium: 5, low: 3, highScore: 4, mediumScore: 2, lowScore: 1);
        score -= ScorePositiveHint(hit.SelectionHintNavigationScore, high: 8, medium: 5, low: 3, highScore: 4, mediumScore: 2, lowScore: 1);
        score -= ScorePositiveHint(hit.SelectionHintQualityPenalty, high: 8, medium: 5, low: 3, highScore: 3, mediumScore: 2, lowScore: 1);
        return score;
    }

    private static int ScorePositiveHint(
        int? value,
        int high,
        int medium,
        int low,
        int highScore,
        int mediumScore,
        int lowScore)
    {
        if (!value.HasValue)
            return 0;
        if (value.Value >= high)
            return highScore;
        if (value.Value >= medium)
            return mediumScore;
        return value.Value >= low ? lowScore : 0;
    }

    private static int ScoreMatchedContentCardShape(IReadOnlyList<RagHitContentCardSummary>? cards)
    {
        if (cards is not { Count: > 0 })
            return 0;

        var score = 0;
        foreach (var card in cards.Take(5))
        {
            if (!string.IsNullOrWhiteSpace(card.Title) && IsUsefulSourceBackedDisplayTitle(card.Title))
                score += 1;

            var kind = NormalizeLexicalLookup(card.Kind);
            if (kind.Contains("unit", StringComparison.Ordinal)
                || kind.Contains("exact", StringComparison.Ordinal)
                || kind.Contains("lead", StringComparison.Ordinal))
            {
                score += 2;
            }

            if (card.Signals is { Count: > 0 })
                score += 1;
        }

        return Math.Min(7, score);
    }

    private static int CountBulletListMarkers(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return 0;

        return Regex.Matches(
            text,
            @"(?:^|[\r\n]\s*)[-*+\u2022\u00b7]\s*\S+(?:\s+\S+){2,}",
            RegexOptions.CultureInvariant).Count;
    }

    private static int CountNumericFactMarkers(string normalizedText)
    {
        if (string.IsNullOrWhiteSpace(normalizedText))
            return 0;

        return Regex.Matches(
            normalizedText,
            @"\b\d+(?:[,.]\d+)?(?:\s*(?:%|\p{L}{1,12}\.?|\p{Sc}))?\b",
            RegexOptions.CultureInvariant).Count;
    }

    private static int CountMeasuredValueMarkers(string normalizedText)
    {
        if (string.IsNullOrWhiteSpace(normalizedText))
            return 0;

        return Regex.Matches(
            normalizedText,
            @"\b\d+(?:[,.]\d+)?\s*(?:%|\p{L}{1,12}\.?|\p{Sc})\b|(?:<=|>=|<|>|=)\s*\d",
            RegexOptions.CultureInvariant).Count;
    }

    private static bool HasMeasurableConstraintEvidence(string rawText, string normalizedText)
        => CountLabelValueMarkers(rawText) >= 1
           || (CountProcedureStepMarkers(normalizedText) >= 3 && CountMeasuredValueMarkers(normalizedText) >= 2)
           || Regex.IsMatch(normalizedText, @"(?:^|\s)(?:<=|>=|<|>|=)\s*\d", RegexOptions.CultureInvariant);

    private static bool HasExplicitConstraintEvidence(string rawText, string normalizedText)
        => CountLabelValueMarkers(rawText) >= 1
           || Regex.IsMatch(normalizedText, @"(?:^|\s)(?:<=|>=|<|>|=)\s*\d", RegexOptions.CultureInvariant);

    private static bool LooksLikeVeryShortTimedOperation(string normalizedText)
        => Regex.IsMatch(normalizedText, @"\b(?:1|2|3)\s*(?:s|sec|secs|min|h|hr|hrs)\b", RegexOptions.CultureInvariant);

    private static int CountLabelValueMarkers(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return 0;

        return Regex.Matches(
            text,
            @"(?:^|[\r\n.;]\s*)[\p{L}\p{N}][^:\r\n]{2,48}:\s+\S",
            RegexOptions.CultureInvariant).Count;
    }

    private static bool LooksLikeMidProcedureFragment(RagHitSummary hit)
    {
        var text = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var hasItemizedData = Regex.IsMatch(text, @"\b(?:items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?)\b", RegexOptions.CultureInvariant);
        var hasEarlySteps = Regex.IsMatch(text, @"(?:^|\s|preparation|procedure|process|operation|technique)[\s:]*[1-3][\.)]\s*", RegexOptions.CultureInvariant);
        var hasLateSteps = Regex.IsMatch(text, @"(?:^|\s)[4-9][\.)]\s*", RegexOptions.CultureInvariant);
        var startsMidSentence = Regex.IsMatch(
            text,
            @"^(?:arreter|ajouter|appliquer|verifier|controler|mesurer|regler|ajuster|retirer|transvider|lorsque|quand|stop|add|apply|verify|check|measure|set|adjust|when|remove)\b",
            RegexOptions.CultureInvariant);

        return (startsMidSentence && !hasItemizedData)
            || (hasLateSteps && !hasEarlySteps && !hasItemizedData);
    }

    private static bool LooksLikeIntroLeadInHit(RagHitSummary hit)
    {
        var text = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var lead = text.Length <= 360 ? text : text[..360];
        var hasIntroLead = Regex.IsMatch(
            lead,
                @"\b(?:bienvenue|introduction|avant propos|preface|sommaire|table des matieres|reperes de contenu|premiers extraits)\b",
            RegexOptions.CultureInvariant);
        if (!hasIntroLead)
            return false;

        var firstStructure = Regex.Match(
            text,
            @"\b(?:items?|elements?|requirements?|quantities?|preparation|preparacion|preparacao|procedure|process|operation|workflow|instructions?|(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+\p{L}|\d+\s+(?:units?|items?))\b",
            RegexOptions.CultureInvariant);
        return !firstStructure.Success || firstStructure.Index > 280;
    }

    private static bool LooksLikeVerySimpleProcedureHit(RagHitSummary hit)
    {
        var text = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var lookupText = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        var hasSimpleWording = Regex.IsMatch(
            text,
            @"\b(?:facile|faciles|simple|simples|rapide|rapides|plus simple|very simple|easy|quick)\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                lookupText,
                @"\b(?:facile|faciles|simple|simples|rapide|rapides|plus simple|very simple|easy|quick)\b",
            RegexOptions.CultureInvariant);
        var hasVeryShortDuration = LooksLikeVeryShortTimedOperation(text);
        var hasControlledParameter = HasExplicitConstraintEvidence(GetRagHitPrimaryContentText(hit), text)
            || CountProcedureStepMarkers(text) >= 4;
        var lacksControlledParameter = !hasControlledParameter;

        if (hasSimpleWording && hasVeryShortDuration && !hasControlledParameter)
            return true;
        if (hasVeryShortDuration && !hasControlledParameter && CountProcedureStepMarkers(text) <= 3)
            return true;

        return (hasSimpleWording || hasVeryShortDuration)
            && lacksControlledParameter
            && ComputeTechnicalComplexityCueScore(hit) < 9;
    }

    private static bool LooksLikeLowStructureShortProcedureHit(RagHitSummary hit)
    {
        var text = NormalizeLexicalLookup($"{GetRagHitPrimaryContentText(hit)} {GetRagHitLookupText(hit)}");
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var hasControlledParameter = HasExplicitConstraintEvidence(GetRagHitPrimaryContentText(hit), text)
            || CountProcedureStepMarkers(text) >= 4;
        var hasVeryShortOperation = LooksLikeVeryShortTimedOperation(text);
        var hasLowStructure = CountProcedureStepMarkers(text) <= 3
            && Regex.Matches(text, @"\b\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l|mm|cm|m|bar|pa|kpa|mpa|v|a|w|hz|rpm|%|min|h)\b", RegexOptions.CultureInvariant).Count < 5;

        if (!hasControlledParameter && hasVeryShortOperation && hasLowStructure)
            return true;
        if (!hasControlledParameter && hasVeryShortOperation && ComputeTechnicalComplexityCueScore(hit) < 9)
            return true;
        if (!hasControlledParameter
            && hasVeryShortOperation
            && Regex.IsMatch(text, @"\b(?:immediat|immediate|instant|quick|rapide)\b", RegexOptions.CultureInvariant))
            return true;

        return !hasControlledParameter
            && hasLowStructure
            && ComputeTechnicalComplexityCueScore(hit) < 12;
    }

    private static bool LooksLikeGenericTechniqueDefinitionHit(RagHitSummary hit)
    {
        var text = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var hasDefinitionWording = Regex.IsMatch(
            text,
            @"\b(?:cette\s+technique\s+consiste|technique\s+consiste|mode\s+de\s+preparation|modes\s+de\s+preparation|mode\s+operatoire|modes\s+operatoires|preparation\s+method|operation\s+method|workflow\s+method|process\s+method|procedure\s+method)\b",
            RegexOptions.CultureInvariant);
        var hasGenericTechniqueHeading = Regex.IsMatch(
            text,
            @"\b(?:technique|method|methode|procedure)\s*[:\-]",
            RegexOptions.CultureInvariant);
        var hasGenericTechniqueOverview = Regex.IsMatch(
            text,
            @"\b(?:technique|method|methode|procedure)\s+(?:generale|general|overview|vue\s+d\s+ensemble)\b",
            RegexOptions.CultureInvariant);
        if (!hasDefinitionWording && !hasGenericTechniqueHeading && !hasGenericTechniqueOverview)
            return false;

        var hasStructuredItemEvidence = Regex.IsMatch(
                text,
                @"\b(?:items?|elements?|requirements?|components?|composants?|materials?|materiel|equipment|preparation\s*[:•]|operation\s*[:•]|workflow\s*[:•]|procedure\s*[:•]|method\s*[:•])\b",
                RegexOptions.CultureInvariant)
            || CountProcedureStepMarkers(text) >= 2
            || Regex.Matches(text, @"\b\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l|mm|cm|m|bar|pa|kpa|mpa|v|a|w|hz|rpm|%|min|h)\b", RegexOptions.CultureInvariant).Count >= 2;

        return !hasStructuredItemEvidence
            && (!hasGenericTechniqueHeading || ComputeProcedureCompletenessCueScore(hit) < 7);
    }

    private static bool LooksLikeProcedureRankingQuery(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        return Regex.IsMatch(
            normalized,
            @"\b(?:procedura|procedure|procedures|procedimento|process|processus|operation|operations|workflow|workflows|method|methode|instruction|instructions|execution|preparation|preparacion|preparacao|etape|etapes|steps|pasos|passos)\b",
            RegexOptions.CultureInvariant);
    }

    private static int ComputeStructuredProcedureEvidenceCueScore(RagHitSummary hit)
    {
        return Math.Clamp(
            ComputeEvidenceShapeScore(hit, GetRagHitPrimaryEvidenceText(hit), includeBackendHints: true),
            -4,
            12);
    }

    private static int ComputeStructuredProcedureVisibleEvidenceCueScore(RagHitSummary hit)
    {
        return Math.Clamp(
            ComputeEvidenceShapeScore(hit, GetRagHitPrimaryContentText(hit), includeBackendHints: true),
            -4,
            12);
    }

    private static string FormatRankingHitReference(string language, RagHitSummary hit)
    {
        var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
        return $"{docLabel} {SourceBackedPagePrefix(language)}{hit.PageStart}";
    }

    private static string BuildSourceBackedRankingReason(string language, RagHitSummary hit, string query)
    {
        var reasons = BuildSourceBackedRankingReasonFragments(language, hit, query);
        var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 260);
        if (reasons.Count == 0)
            reasons.Add(NormalizeLanguageCode(language) switch
            {
                "en" => "it is one of the strongest retrieved matches",
                "es" => "es una de las coincidencias recuperadas mas fuertes",
                "pt" => "e uma das correspondencias recuperadas mais fortes",
                "de" => "es ist einer der staerksten gefundenen Treffer",
                "it" => "e una delle corrispondenze recuperate piu forti",
                _ => "c'est une des correspondances retrouvees les plus fortes"
            });

        var because = NormalizeLanguageCode(language) switch
        {
            "en" => "because",
            "es" => "porque",
            "pt" => "porque",
            "de" => "weil",
            "it" => "perche",
            _ => "car"
        };

        var excerptLabel = SourceBackedLabel(language, "Extrait", "Excerpt", "Extracto", "Excerto", "Auszug", "Estratto");
        return $"{because} {string.Join(", ", reasons)}. {excerptLabel}: {excerpt}";
    }

    private static List<string> BuildSourceBackedRankingReasonFragments(string language, RagHitSummary hit, string query)
    {
        var normalizedLanguage = NormalizeLanguageCode(language);
        var text = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        var fragments = new List<string>();

        if (LooksLikeTechnicalRankingQuery(query)
            && Regex.IsMatch(text, @"\b(?:technique|procedure|procedures|mode operatoire|operation|workflow|execution|instruction|instructions|etape|etapes|step|steps|preparation|method|methode)\b", RegexOptions.CultureInvariant))
        {
            fragments.Add(normalizedLanguage switch
            {
                "en" => "the excerpt contains explicit procedural or technical wording",
                "es" => "el extracto contiene vocabulario procedimental o tecnico explicito",
                "pt" => "o excerto contem vocabulario procedural ou tecnico explicito",
                "de" => "der Auszug enthaelt ausdrueckliche Verfahrens- oder Technikbegriffe",
                "it" => "l'estratto contiene lessico procedurale o tecnico esplicito",
                _ => "l'extrait contient du vocabulaire procedural ou technique explicite"
            });
        }

        if (HasMeasurableConstraintEvidence(GetRagHitLookupText(hit), text))
        {
            fragments.Add(normalizedLanguage switch
            {
                "en" => "it includes parameters, timing, or measurable constraints",
                "es" => "incluye parametros, tiempos o restricciones medibles",
                "pt" => "inclui parametros, tempos ou restricoes mensuraveis",
                "de" => "er enthaelt Parameter, Zeiten oder messbare Vorgaben",
                "it" => "include parametri, tempi o vincoli misurabili",
                _ => "il contient des parametres, temps ou contraintes mesurables"
            });
        }

        if (ScoreEvidenceRoleHint(hit) > 0
            || CountLabelValueMarkers(GetRagHitLookupText(hit)) > 0
            || CountProcedureStepMarkers(text) >= 3)
        {
            fragments.Add(normalizedLanguage switch
            {
                "en" => "it has structured or constraint-bearing evidence",
                "es" => "aporta evidencia estructurada o con restricciones",
                "pt" => "traz evidencia estruturada ou com restricoes",
                "de" => "er enthaelt strukturierte oder einschraenkende Nachweise",
                "it" => "contiene evidenza strutturata o vincolante",
                _ => "il contient des indices structures ou contraints"
            });
        }

        return fragments;
    }

    private static string BuildRagEvidenceSelectionQuery(string query)
    {
        if (LooksLikeComparativeDocumentaryRequest(query))
        {
            var focused = TryBuildComparativeFocusQuery(query);
            if (!string.IsNullOrWhiteSpace(focused))
                return focused!;
        }

        return query;
    }

    private static string BuildSourceBackedExactItemAnswer(string language, string requestedTitle, IReadOnlyList<RagHitSummary> hits, string query)
    {
        if (LooksLikeGenericCollectionOrListRequest(query))
            return string.Empty;

        language = NormalizeLanguageCode(language);
        var displayTitle = ResolveSourceBackedExactItemDisplayTitle(requestedTitle, hits);
        var header = language switch
        {
            "en" => $"I found the requested item \"{displayTitle}\" in the available sources. I keep the answer limited to the cited excerpts:",
            "es" => $"He encontrado el elemento solicitado \"{displayTitle}\" en las fuentes disponibles. Limito la respuesta a los extractos citados:",
            "pt" => $"Encontrei o item solicitado \"{displayTitle}\" nas fontes disponiveis. Limito a resposta aos excertos citados:",
            "de" => $"Ich habe den angefragten Eintrag \"{displayTitle}\" in den verfuegbaren Quellen gefunden. Die Antwort bleibt auf die zitierten Auszuege begrenzt:",
            "it" => $"Ho trovato l'elemento richiesto \"{displayTitle}\" nelle fonti disponibili. Limito la risposta agli estratti citati:",
            _ => $"J'ai trouve l'element demande \"{displayTitle}\" dans les sources disponibles. Je limite la reponse aux extraits cites :"
        };

        if (LooksLikeParameterLookupRequest(query))
            return BuildSourceBackedExactItemParameterAnswer(language, requestedTitle, hits, header);

        var hasStructuredExactItemEvidence = hits.Any(hit =>
            RagHitContainsRequestedTitle(hit, requestedTitle)
            && (ComputeExactItemCardCompletenessCueScore(hit) >= 8
                || HasContentCardEvidenceFacts(hit)));
        if (LooksLikeStructuredItemCardRequest(query) || hasStructuredExactItemEvidence)
            return BuildSourceBackedExactItemCardAnswer(language, requestedTitle, hits, header);

        var sb = new StringBuilder();
        sb.AppendLine(header);
        foreach (var hit in hits.Take(3))
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            if (ShouldIncludeRawSourceExcerptForAnswerLanguage(language, hit))
            {
                var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: SourceBackedEvidenceMaxChars);
                sb.AppendLine(excerpt);
            }
            else
            {
                sb.AppendLine(SourceBackedLabel(
                    language,
                    "extrait disponible dans la langue du document sur la page citee",
                    "excerpt available in the document language on the cited page",
                    "extracto disponible en el idioma del documento en la pagina citada",
                    "excerto disponivel na lingua do documento na pagina citada",
                    "Auszug in der Dokumentsprache auf der zitierten Seite verfuegbar",
                    "estratto disponibile nella lingua del documento nella pagina citata"));
            }
        }

        var note = language switch
        {
            "en" => "If you need a step-by-step card, I can only expand the parts visible in these excerpts.",
            "es" => "Si necesitas una ficha paso a paso, solo puedo desarrollar las partes visibles en estos extractos.",
            "pt" => "Se precisares de uma ficha passo a passo, so posso desenvolver as partes visiveis nestes excertos.",
            "de" => "Falls du eine Schritt-fuer-Schritt-Karte brauchst, kann ich nur die in diesen Auszuegen sichtbaren Teile ausarbeiten.",
            "it" => "Se ti serve una scheda passo passo, posso sviluppare solo le parti visibili in questi estratti.",
            _ => "Si tu veux une fiche pas a pas, je ne peux developper que les elements visibles dans ces extraits."
        };
        sb.AppendLine(note);
        AppendSourceBackedExtractionQualityCaveat(sb, hits, language);
        return sb.ToString().TrimEnd();
    }

    private static string ResolveSourceBackedExactItemDisplayTitle(string requestedTitle, IReadOnlyList<RagHitSummary> hits)
    {
        var candidates = hits
            .SelectMany(ExtractSourceBackedTitleCandidates)
            .Where(IsUsefulSourceBackedDisplayTitle)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Select(title => new
            {
                Title = title,
                Score = ComputeSourceBackedDisplayTitleScore(requestedTitle, title)
            })
            .OrderByDescending(static item => item.Score)
            .ThenByDescending(static item => item.Title.Any(char.IsUpper))
            .ThenBy(static item => item.Title.Length)
            .ToArray();

        var best = candidates.FirstOrDefault(static item => item.Score > 0);
        if (best is not null && LooksLikeOcrTitleRunOn(requestedTitle, best.Title))
            return requestedTitle;

        return best?.Title ?? requestedTitle;
    }

    private static bool LooksLikeOcrTitleRunOn(string requestedTitle, string candidateTitle)
    {
        var requested = NormalizeLexicalLookup(requestedTitle);
        var candidate = NormalizeLexicalLookup(candidateTitle);
        if (requested.Length < 4 || candidate.Length <= requested.Length + 14)
            return false;

        if (candidate.StartsWith(requested, StringComparison.Ordinal))
        {
            return !Regex.IsMatch(candidate[requested.Length..], @"^\s+(?:de|du|des|a|au|aux|with|and|et)\b", RegexOptions.CultureInvariant);
        }

        var index = candidate.IndexOf(requested, StringComparison.Ordinal);
        if (index is > 0 and <= 80)
        {
            var prefix = candidate[..index].Trim();
            return prefix.Length >= 12
                && Regex.IsMatch(prefix, @"\b(?:apres|after|avant|before|prevoir|prevoyez|" + OperationalActionLeadPattern + @")\b", RegexOptions.CultureInvariant);
        }

        return false;
    }

    private static IEnumerable<string> ExtractSourceBackedTitleCandidates(RagHitSummary hit)
    {
        foreach (var card in hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
        {
            if (!string.IsNullOrWhiteSpace(card.Title))
                yield return card.Title;
        }

        foreach (var source in new[] { hit.ContextualSnippet, hit.SectionTitle, hit.HeadingPath })
        {
            if (string.IsNullOrWhiteSpace(source))
                continue;

            foreach (var title in ExtractProfileTitleCandidates(source))
                yield return title;
        }
    }

    private static IEnumerable<string> ExtractProfileTitleCandidates(string value)
    {
        foreach (Match match in Regex.Matches(
            value,
            @"(?i)\bMatched\s+(?:profile|quoted)\s+title\s*:\s*(?<titles>.+?)(?=\s*(?:\|\s*)?(?:Document|Section|HeadingPath|ChunkType|Pages|Evidence)\s*:|$)"))
        {
            var titles = match.Groups["titles"].Value;
            foreach (var title in SplitSourceBackedTitleList(titles))
                yield return title;
        }

        var trimmed = CollapseWhitespace(value);
        if (!trimmed.Contains(':', StringComparison.Ordinal)
            && trimmed.Length is >= 3 and <= 90)
        {
            yield return trimmed;
        }
    }

    private static IEnumerable<string> SplitSourceBackedTitleList(string value)
    {
        foreach (var part in Regex.Split(value ?? string.Empty, @"\s*;\s*"))
        {
            var title = CollapseWhitespace(part)
                .Trim(' ', '.', ',', ';', ':', '"', '\'', '\u2022', '\u00b7');
            if (!string.IsNullOrWhiteSpace(title))
                yield return title;
        }
    }

    private static bool IsUsefulSourceBackedDisplayTitle(string title)
    {
        var normalized = NormalizeLexicalLookup(title);
        if (normalized.Length is < 3 or > 90)
            return false;

        if (LooksLikeProcedureSentenceTitle(normalized))
            return false;

        return normalized is not "document" and not "document profile";
    }

    private static bool IsUsableSourceBackedOptionTitle(string? title)
    {
        if (string.IsNullOrWhiteSpace(title))
            return false;

        var cleaned = CleanSourceBackedOptionTitle(title);
        if (string.IsNullOrWhiteSpace(cleaned))
            return false;

        var normalized = NormalizeLexicalLookup(cleaned);
        return IsUsefulSourceBackedDisplayTitle(cleaned)
            && !LooksLikePlanItemNoise(cleaned)
            && !LooksLikeWeakSourceBackedOptionTitle(cleaned)
            && !LooksLikeProcedureSentenceTitle(normalized);
    }

    private static bool LooksLikeWeakSourceBackedOptionTitle(string? title)
    {
        var raw = CollapseWhitespace(title ?? string.Empty);
        var normalized = NormalizeLexicalLookup(raw);
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        var lead = StripShortOcrPrefixForTitleQuality(normalized);
        if (Regex.IsMatch(
                lead,
                @"^(?:\d+[a-z]?|[ivxlcdm]{1,6})\s+(?:a\s+voir|voir|see|refer|consulter|page|section|chapter|part|partie|annexe|appendix|table|index)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        var structuredText = NormalizeStructuredScanText(raw);
        var startsWithQuantity = Regex.IsMatch(
            lead,
            @"^\d+(?:[,.]\d+)?\s*(?:x\b|g\b|kg\b|mg\b|ml\b|cl\b|l\b|oz\b|lb\b|lbs\b|mm\b|cm\b|m\b|%|\p{L}{3,})",
            RegexOptions.CultureInvariant);
        var unitMarkerCount = Regex.Matches(
                lead,
                @"\b(?:g|kg|mg|ml|cl|l|oz|lb|lbs|mm|cm|m|%|tablespoons?|teaspoons?|tsp|tbsp|boites?|pieces?|items?|units?|valeurs?|values?)\b",
                RegexOptions.CultureInvariant)
            .Count;
        if (startsWithQuantity
            && (CountNumericFactMarkers(structuredText) >= 2
                || unitMarkerCount > 0
                || ExtractQuerySignalTerms(lead).Count() >= 8))
        {
            return true;
        }

        if (Regex.IsMatch(
                lead,
                @"^(?:\p{L}{1,3}\s+){0,3}(?:mettre|mettez|placer|placez|ajouter|ajoutez|retirer|retirez|ouvrir|ouvrez|fermer|fermez|programmer|programmez|verifier|verifiez|controler|controlez|inspecter|inspectez|noter|notez|signer|signez|set|add|remove|place|put|open|close|program|check|verify|inspect|record|sign)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                lead,
                @"^(?:a\s+voir|voir\s+aussi|see\s+also|refer\s+to|pictogrammes?|pictograms?|symbols?|symboles?)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (unitMarkerCount >= 2 && ExtractQuerySignalTerms(lead).Count() >= 7)
            return true;

        if (CountNumericFactMarkers(structuredText) >= 3)
            return true;

        if (LooksLikeLowValueMarketingOrDocumentHeading(lead))
            return true;

        var words = ExtractQuerySignalTerms(normalized).ToArray();
        if (words.Length >= 7
            && Regex.IsMatch(normalized, @"\b(?:et|and|avec|with|puis|then|de|du|des|of|the)\b", RegexOptions.CultureInvariant)
            && CountNumericFactMarkers(structuredText) >= 1)
        {
            return true;
        }

        var letters = raw.Where(char.IsLetter).ToArray();
        if (letters.Length >= 8)
        {
            var upperRatio = letters.Count(char.IsUpper) / (double)letters.Length;
            if (upperRatio >= 0.82
                && words.Length is >= 2 and <= 5
                && Regex.IsMatch(
                    normalized,
                    @"\b(?:become|welcome|companion|community|creative|solution|solutions|catalog|catalogue|guide|edition|copyright|isbn|introduction|foreword|preface)\b",
                    RegexOptions.CultureInvariant))
            {
                return true;
            }
        }

        return false;
    }

    private static bool LooksLikeLowValueMarketingOrDocumentHeading(string? normalizedTitle)
    {
        var title = NormalizeLexicalLookup(normalizedTitle);
        if (string.IsNullOrWhiteSpace(title))
            return false;

        var words = ExtractQuerySignalTerms(title).Take(8).ToArray();
        if (words.Length == 0 || words.Length > 6)
            return false;

        if (Regex.IsMatch(
                title,
                @"^(?:become|welcome|discover|explore|learn|start|getting\s+started|introduction|foreword|preface|copyright|isbn)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                title,
                @"\b(?:catalog|catalogue|companion|community|newsletter|account|rating|share|copyright|isbn)\b",
                RegexOptions.CultureInvariant)
            && words.Length <= 5)
        {
            return true;
        }

        return false;
    }

    private static string StripShortOcrPrefixForTitleQuality(string normalized)
    {
        var value = CollapseWhitespace(normalized);
        for (var i = 0; i < 2; i++)
        {
            var trimmed = Regex.Replace(
                value,
                @"^(?:[a-z]{1,3}|[ivxlcdm]{1,4})\s+(?=\p{L}{4,})",
                string.Empty,
                RegexOptions.CultureInvariant).Trim();
            if (string.Equals(trimmed, value, StringComparison.Ordinal))
                break;

            value = trimmed;
        }

        return value;
    }

    private static bool LooksLikeProcedureSentenceTitle(string normalizedTitle)
    {
        if (string.IsNullOrWhiteSpace(normalizedTitle))
            return false;

        if (Regex.IsMatch(
                normalizedTitle,
                @"^(?:le|la|les|l|un|une|des|du|de\s+la|the|a|an)?\s*(?:occuper|occupez|organiser|organize|planifier|planifiez|schedule|utiliser|use|using|" + OperationalActionLeadPattern + @")\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        return Regex.IsMatch(
            normalizedTitle,
            @"\b(?:\d+\s*(?:min|h|hours?|minutes?|seconds?|secondes?|%|(?:\u00b0|deg|degres?)\s*c)|step\s+\d+|etape\s+\d+|page\s+\d+|section\s+\d+)\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalizedTitle, @"[.;:!?]\s+\p{L}", RegexOptions.CultureInvariant);
    }

    private static int ComputeSourceBackedDisplayTitleScore(string requestedTitle, string candidateTitle)
    {
        var requested = NormalizeLexicalLookup(requestedTitle);
        var candidate = NormalizeLexicalLookup(candidateTitle);
        if (string.IsNullOrWhiteSpace(requested) || string.IsNullOrWhiteSpace(candidate))
            return 0;

        if (string.Equals(candidate, requested, StringComparison.Ordinal))
            return 100;

        var requestSeeds = new List<string> { requested };
        requestSeeds.AddRange(BuildTypoTolerantQueryVariants(requested).Select(NormalizeLexicalLookup));
        var requestTerms = requestSeeds
            .SelectMany(ExtractRequestedTitleSignalTerms)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        if (requestTerms.Length == 0)
            return 0;

        var matchedIndexes = requestTerms
            .Select((term, index) => new { Term = term, Index = index })
            .Where(item => candidate.Contains(item.Term, StringComparison.Ordinal))
            .Select(static item => item.Index)
            .Distinct()
            .OrderBy(static index => index)
            .ToArray();
        if (matchedIndexes.Length == 0)
            return 0;

        var score = matchedIndexes.Length * 20;
        score += matchedIndexes.Sum(index => Math.Max(1, requestTerms.Length - index) * 3);
        if (matchedIndexes.SequenceEqual(Enumerable.Range(0, matchedIndexes.Length)) && matchedIndexes.Length >= 2)
            score += 20;
        if (matchedIndexes[0] > 0)
            score -= matchedIndexes[0] * 10;
        if (matchedIndexes.Length == requestTerms.Length)
            score += 30;
        if (candidate.Contains(requested, StringComparison.Ordinal) || requested.Contains(candidate, StringComparison.Ordinal))
            score += 20;

        return score;
    }

    private static bool LooksLikeParameterLookupRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        return Regex.IsMatch(
            normalized,
            @"\b(?:vitesse|vitesses|speed|speeds|temperature|temperatures|reglage|reglages|setting|settings|parametre|parametres|parameter|parameters|programme|program)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeStructuredItemCardRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (Regex.IsMatch(
                normalized,
                @"\b(?:items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?|components?|composants?|preparation|operation|workflow|execution|technique|materiel|material|materials|procedure|process|method|methode)\b",
                RegexOptions.CultureInvariant))
            return true;

        return Regex.IsMatch(
            normalized,
            @"\b(?:fiche|card|item|items|element|elements|etape|etapes|steps|temps|time|source|sources|procedure|process|values?|valeurs?)\b",
            RegexOptions.CultureInvariant);
    }

    private static string BuildSourceBackedExactItemParameterAnswer(string language, string requestedTitle, IReadOnlyList<RagHitSummary> hits, string header)
    {
        var sb = new StringBuilder();
        sb.AppendLine(header);
        sb.AppendLine(SourceBackedLabel(language, "Parametres visibles dans les extraits :", "Visible parameters in the excerpts:", "Parametros visibles en los extractos:", "Parametros visiveis nos excertos:", "Sichtbare Parameter in den Auszuegen:", "Parametri visibili negli estratti:"));

        foreach (var hit in hits.Take(3))
        {
            var facts = ExtractParameterFacts(GetBestRagEvidenceText(hit)).Take(8).ToArray();
            if (facts.Length == 0)
                continue;

            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.Append(" : ");
            sb.AppendLine(string.Join("; ", facts));
        }

        if (!Regex.IsMatch(sb.ToString(), @"\s(?:p\.|S\.)\d+", RegexOptions.CultureInvariant))
        {
            foreach (var hit in hits.Take(2))
            {
                var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
                sb.Append("- ");
                sb.Append(docLabel);
                sb.Append(' ');
                sb.Append(SourceBackedPagePrefix(language));
                sb.Append(hit.PageStart);
                sb.Append(" : ");
                sb.AppendLine(FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 260));
            }
        }

        AppendControlExcerpt(sb, language, hits);
        return sb.ToString().TrimEnd();
    }

    private static string BuildSourceBackedExactItemCardAnswer(string language, string requestedTitle, IReadOnlyList<RagHitSummary> hits, string header)
    {
        var cardHits = hits
            .Where(hit => ExactItemEvidenceTextMatchesRequestedTitle(requestedTitle, hit)
                || RagHitContainsRequestedTitle(hit, requestedTitle)
                || RagHitHasUsableRequestedTitleAnchor(requestedTitle, hit)
                || IsUsableExactItemNavigationOverride(requestedTitle, hit))
            .OrderByDescending(hit => ExactItemEvidenceStartsWithRequestedTitle(requestedTitle, hit))
            .ThenByDescending(hit => HasStrongExactItemTitleAnchor(requestedTitle, hit)
                || IsUsableExactItemNavigationOverride(requestedTitle, hit))
            .ThenByDescending(hit => ComputeExactItemCardEvidenceScore(requestedTitle, hit))
            .ThenByDescending(hit => hit.Score)
            .ToList();
        var structuredCompanions = hits
            .Where(hit => hit.PageEnd > hit.PageStart || !LooksLikeNavigationOnlyHit(hit))
            .Where(hit => ComputeExactItemCardCompletenessCueScore(hit) >= 8 || hit.PageEnd > hit.PageStart)
            .Where(hit => !cardHits.Any(existing => SameRagHitRange(existing, hit)))
            .ToList();
        if (structuredCompanions.Count > 0)
        {
            cardHits = cardHits
                .Concat(structuredCompanions)
                .OrderByDescending(hit => ExactItemEvidenceStartsWithRequestedTitle(requestedTitle, hit))
                .ThenByDescending(hit => HasStrongExactItemTitleAnchor(requestedTitle, hit)
                    || IsUsableExactItemNavigationOverride(requestedTitle, hit))
                .ThenByDescending(hit => ComputeExactItemCardEvidenceScore(requestedTitle, hit))
                .ThenByDescending(hit => hit.Score)
                .ToList();
        }

        if (cardHits.Count == 0)
        {
            cardHits = hits
                .OrderByDescending(hit => ExactItemEvidenceStartsWithRequestedTitle(requestedTitle, hit))
                .ThenByDescending(hit => HasStrongExactItemTitleAnchor(requestedTitle, hit)
                    || IsUsableExactItemNavigationOverride(requestedTitle, hit))
                .ThenByDescending(hit => ComputeExactItemCardEvidenceScore(requestedTitle, hit))
                .ThenByDescending(hit => hit.Score)
                .ToList();
        }

        var primary = cardHits.FirstOrDefault(hit =>
                !LooksLikePageReferenceOnlyHit(hit)
                && !LooksLikeNavigationOnlyHit(hit)
                && RagHitHasUsableRequestedTitleAnchor(requestedTitle, hit)
                && ComputeExactItemCardCompletenessCueScore(hit) >= 4)
            ?? cardHits.FirstOrDefault(hit =>
                !LooksLikePageReferenceOnlyHit(hit)
                && IsUsableExactItemNavigationOverride(requestedTitle, hit)
                && ComputeExactItemCardCompletenessCueScore(hit) >= 4)
            ?? cardHits.FirstOrDefault(hit =>
                !LooksLikePageReferenceOnlyHit(hit)
                && !LooksLikeNavigationOnlyHit(hit)
                && RagHitHasUsableRequestedTitleAnchor(requestedTitle, hit))
            ?? cardHits.FirstOrDefault(hit =>
                !LooksLikePageReferenceOnlyHit(hit)
                && IsUsableExactItemNavigationOverride(requestedTitle, hit))
            ?? cardHits.First();
        var primaryDoc = string.IsNullOrWhiteSpace(primary.DocName) ? primary.DocPath : primary.DocName;
        var evidenceHits = SelectExactItemCardEvidenceHits(cardHits, primary);
        var evidence = CollapseWhitespace(string.Join(' ', evidenceHits.Select(hit => GetFocusedExactItemEvidenceText(requestedTitle, hit))));
        var itemizedEvidence = CollapseWhitespace(string.Join(' ', evidenceHits.Select(hit => GetFocusedExactItemStructuredEvidenceText(requestedTitle, hit))));
        var procedureEvidence = CollapseWhitespace(string.Join(' ', evidenceHits
            .OrderByDescending(hit => ComputeExactItemProcedureEvidenceScore(requestedTitle, hit))
            .Select(hit => GetFocusedExactItemEvidenceText(requestedTitle, hit))));
        var visibleDurationsAndQuantities = ExtractVisibleDurationsAndQuantities(procedureEvidence).Take(8).ToArray();
        var itemizedFacts = ExtractItemizedQuantityFacts(itemizedEvidence).Take(10).ToArray();
        var steps = ExtractProcedureSteps(procedureEvidence).Take(10).ToArray();
        var cardEvidenceFacts = ExtractContentCardEvidenceFacts(evidenceHits).Take(12).ToArray();
        var cardQuantityEvidenceFacts = ExtractContentCardQuantityEvidenceFacts(evidenceHits).Take(12).ToArray();
        var cardGenericEvidenceFacts = ExtractContentCardGenericEvidenceFacts(evidenceHits).Take(12).ToArray();
        var cardNonScalableReasons = ExtractContentCardNonScalableReasons(evidenceHits).Take(8).ToArray();
        var hasCardQuantityEvidence = HasContentCardQuantityEvidence(evidenceHits);
        var hasAnyCardEvidence = HasContentCardEvidence(evidenceHits);

        var sb = new StringBuilder();
        sb.AppendLine(header);
        sb.AppendLine(SourceBackedLabel(language, "Fiche sourcee :", "Source-backed card:", "Ficha con fuente:", "Ficha com fonte:", "Belegte Karte:", "Scheda con fonte:"));
        sb.Append("- ");
        sb.Append(SourceBackedLabel(language, "Source principale", "Main source", "Fuente principal", "Fonte principal", "Hauptquelle", "Fonte principale"));
        sb.Append(" : ");
        sb.Append(primaryDoc);
        sb.Append(' ');
        sb.Append(SourceBackedPagePrefix(language));
        sb.AppendLine(primary.PageStart.ToString(CultureInfo.InvariantCulture));

        if (!ShouldIncludeRawSourceExcerptForAnswerLanguage(language, primary))
        {
            sb.Append("- ");
            sb.Append(SourceBackedLabel(
                language,
                "Contenu visible",
                "Visible content",
                "Contenido visible",
                "Conteudo visivel",
                "Sichtbarer Inhalt",
                "Contenuto visibile"));
            sb.Append(" : ");
            sb.AppendLine(SourceBackedLabel(
                language,
                "les elements, valeurs, temps et etapes doivent etre lus sur la page citee dans la langue du document.",
                "items, values, timing and steps should be read on the cited page in the document language.",
                "los elementos, valores, tiempos y pasos deben leerse en la pagina citada, en el idioma del documento.",
                "os elementos, valores, tempos e etapas devem ser lidos na pagina citada, na lingua do documento.",
                "Elemente, Werte, Zeiten und Schritte sind auf der zitierten Seite in der Dokumentsprache zu lesen.",
                "elementi, valori, tempi e passaggi vanno letti nella pagina citata, nella lingua del documento."));
            return sb.ToString().TrimEnd();
        }

        if (hasAnyCardEvidence)
        {
            if (hasCardQuantityEvidence)
            {
                AppendFactList(sb, SourceBackedLabel(language, "Durees / quantites visibles", "Visible durations / quantities", "Duraciones / cantidades visibles", "Duracoes / quantidades visiveis", "Sichtbare Dauern / Mengen", "Durate / quantita visibili"), cardQuantityEvidenceFacts, language);
            }

            if (cardGenericEvidenceFacts.Length > 0 || !hasCardQuantityEvidence)
            {
                var genericFacts = cardGenericEvidenceFacts.Length > 0 ? cardGenericEvidenceFacts : cardEvidenceFacts;
                AppendFactList(sb, SourceBackedLabel(language, "Informations visibles", "Visible information", "Informacion visible", "Informacao visivel", "Sichtbare Informationen", "Informazioni visibili"), genericFacts, language);
            }

            if (cardNonScalableReasons.Length > 0)
            {
                AppendFactList(sb, SourceBackedLabel(language, "Contraintes non adaptables", "Non-scalable constraints", "Restricciones no adaptables", "Restricoes nao adaptaveis", "Nicht skalierbare Vorgaben", "Vincoli non scalabili"), cardNonScalableReasons, language);
            }
        }
        else if (primary.MatchedContentCards is { Count: > 0 }
                 || evidenceHits.Any(static hit => hit.MatchedContentCards is { Count: > 0 }))
        {
            var visibleInfo = visibleDurationsAndQuantities
                .Concat(itemizedFacts)
                .Concat(steps)
                .Where(static item => !string.IsNullOrWhiteSpace(item))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(12)
                .ToArray();
            AppendFactList(sb, SourceBackedLabel(language, "Informations visibles", "Visible information", "Informacion visible", "Informacao visivel", "Sichtbare Informationen", "Informazioni visibili"), visibleInfo, language);
        }
        else
        {
            AppendFactList(sb, SourceBackedLabel(language, "Durees / quantites visibles", "Visible durations / quantities", "Duraciones / cantidades visibles", "Duracoes / quantidades visiveis", "Sichtbare Dauern / Mengen", "Durate / quantita visibili"), visibleDurationsAndQuantities, language);
            AppendFactList(sb, SourceBackedLabel(language, "Elements / quantites visibles", "Visible items / quantities", "Elementos / cantidades visibles", "Elementos / quantidades visiveis", "Sichtbare Elemente / Mengen", "Elementi / quantita visibili"), itemizedFacts, language);
            AppendFactList(sb, SourceBackedLabel(language, "Etapes visibles", "Visible steps", "Pasos visibles", "Passos visiveis", "Sichtbare Schritte", "Passaggi visibili"), steps, language);
        }
        AppendExactItemControlExcerpt(sb, language, requestedTitle, cardHits);
        return sb.ToString().TrimEnd();
    }

    private static IReadOnlyList<RagHitSummary> SelectExactItemCardEvidenceHits(IReadOnlyList<RagHitSummary> cardHits, RagHitSummary primary)
    {
        var primaryDocPath = (primary.DocPath ?? string.Empty).Replace('\\', '/');
        var evidenceHits = cardHits
            .Where(hit => string.Equals((hit.DocPath ?? string.Empty).Replace('\\', '/'), primaryDocPath, StringComparison.OrdinalIgnoreCase)
                && (hit.PageStart == primary.PageStart || IsLinkedExactItemEvidenceHit(primary, hit)))
            .OrderByDescending(hit => SameRagHitRange(hit, primary))
            .ThenBy(hit => Math.Abs(hit.PageStart - primary.PageStart))
            .ThenByDescending(ComputeExactItemCardCompletenessCueScore)
            .Take(4)
            .ToArray();

        return evidenceHits.Length > 0
            ? evidenceHits
            : cardHits.Take(1).ToArray();
    }

    private static bool IsLinkedExactItemEvidenceHit(RagHitSummary primary, RagHitSummary candidate)
    {
        if (SameRagHitRange(primary, candidate))
            return true;

        if (!string.Equals(primary.DocPath, candidate.DocPath, StringComparison.OrdinalIgnoreCase))
            return false;

        if (LooksLikeNavigationOnlyHit(candidate) || LooksLikeLowSignalContentCandidateHit(candidate))
            return false;

        if (IsChunkLinkedToPrimary(primary, candidate))
            return true;

        var primarySection = NormalizeLexicalLookup(
            string.IsNullOrWhiteSpace(primary.SectionTitle) ? primary.HeadingPath : primary.SectionTitle);
        var candidateSection = NormalizeLexicalLookup(
            string.IsNullOrWhiteSpace(candidate.SectionTitle) ? candidate.HeadingPath : candidate.SectionTitle);
        if (!string.IsNullOrWhiteSpace(primarySection)
            && primarySection.Length >= 4
            && string.Equals(primarySection, candidateSection, StringComparison.Ordinal)
            && candidate.PageStart <= primary.PageEnd + 2
            && candidate.PageEnd >= Math.Max(1, primary.PageStart - 2))
        {
            return true;
        }

        return false;
    }

    private static bool IsChunkLinkedToPrimary(RagHitSummary primary, RagHitSummary candidate)
    {
        static bool SameChunk(string? left, string? right)
            => !string.IsNullOrWhiteSpace(left)
               && !string.IsNullOrWhiteSpace(right)
               && string.Equals(left, right, StringComparison.OrdinalIgnoreCase);

        return SameChunk(primary.NextChunkId, candidate.ChunkId)
               || SameChunk(primary.PrevChunkId, candidate.ChunkId)
               || SameChunk(primary.SameSectionChunkId, candidate.ChunkId)
               || SameChunk(candidate.NextChunkId, primary.ChunkId)
               || SameChunk(candidate.PrevChunkId, primary.ChunkId)
               || SameChunk(candidate.SameSectionChunkId, primary.ChunkId);
    }

    private static int ComputeExactItemCardEvidenceScore(string requestedTitle, RagHitSummary hit)
    {
        var evidence = GetFocusedExactItemEvidenceText(requestedTitle, hit);
        var itemizedEvidence = GetFocusedExactItemStructuredEvidenceText(requestedTitle, hit);
        var displayTitleScore = ComputeBestSourceBackedDisplayTitleScore(requestedTitle, hit);
        var score = 0;
        if (ExactItemEvidenceTextMatchesRequestedTitle(requestedTitle, hit))
            score += 20;
        else if (RagHitContainsRequestedTitle(hit, requestedTitle))
            score += ComputeExactItemCardCompletenessCueScore(hit) >= 4 ? 10 : -12;
        if (displayTitleScore >= 40)
            score += 60 + displayTitleScore;
        else if (ExtractRequestedTitleSignalTerms(NormalizeLexicalLookup(requestedTitle)).Length >= 3 && displayTitleScore < 20)
            score -= 40;
        score += ComputeExactItemHeadTermEvidenceScore(requestedTitle, hit);
        score += ComputeExactItemAnchorStrengthScore(requestedTitle, hit);
        score += ComputeRequestedDocumentTypeAnchorScore(requestedTitle, hit);
        score += ComputeExactVisibleTitleMatchScore(requestedTitle, hit);
        score += ExtractItemizedQuantityFacts(itemizedEvidence).Length * 4;
        score += ExtractProcedureSteps(evidence).Length * 3;
        score += ExtractVisibleDurationsAndQuantities(evidence).Length;
        score += ExtractContentCardEvidenceFacts(new[] { hit }).Length * 4;
        if (LooksLikeNavigationOnlyHit(hit))
            score -= 120;
        if (LooksLikePageReferenceOnlyHit(hit))
            score -= 220;
        return score;
    }

    private static int ComputeExactItemHeadTermEvidenceScore(string requestedTitle, RagHitSummary hit)
    {
        var titleTerms = ExtractRequestedTitleSignalTerms(NormalizeLexicalLookup(requestedTitle));
        if (titleTerms.Length < 2)
            return 0;

        var headTerms = titleTerms.Take(Math.Min(2, titleTerms.Length)).ToArray();
        var content = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        var titleText = NormalizeLexicalLookup(string.Join(' ', ExtractSourceBackedTitleCandidates(hit)));

        var matchedContentHeadTerms = headTerms.Count(term => content.Contains(term, StringComparison.Ordinal));
        var matchedTitleHeadTerms = headTerms.Count(term => titleText.Contains(term, StringComparison.Ordinal));

        var score = matchedContentHeadTerms * 45 + matchedTitleHeadTerms * 25;
        if (matchedContentHeadTerms == headTerms.Length)
            score += 70;
        if (matchedTitleHeadTerms == headTerms.Length)
            score += 50;
        if (titleTerms.Length >= 3 && matchedContentHeadTerms == 0 && matchedTitleHeadTerms == 0)
            score -= 160;

        return score;
    }

    private static int ComputeBestSourceBackedDisplayTitleScore(string requestedTitle, RagHitSummary hit)
        => ExtractSourceBackedTitleCandidates(hit)
            .Where(IsUsefulSourceBackedDisplayTitle)
            .Select(title => ComputeSourceBackedDisplayTitleScore(requestedTitle, title))
            .DefaultIfEmpty(0)
            .Max();

    private static int ComputeExactItemAnchorStrengthScore(string requestedTitle, RagHitSummary hit)
    {
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        var titleTerms = ExtractRequestedTitleSignalTerms(normalizedTitle);
        if (titleTerms.Length == 0)
            return 0;

        static bool AllTermsIn(string text, IReadOnlyList<string> terms)
        {
            var normalized = NormalizeLexicalLookup(text);
            return !string.IsNullOrWhiteSpace(normalized)
                && terms.All(term => normalized.Contains(term, StringComparison.Ordinal));
        }

        var score = 0;
        var cardTitles = string.Join(' ', hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>());
        if (AllTermsIn(cardTitles, titleTerms))
            score += 90;

        var contextualTitleText = string.Join(' ', ExtractProfileTitleCandidates(hit.ContextualSnippet ?? string.Empty));
        if (AllTermsIn(contextualTitleText, titleTerms))
            score += 80;

        if (AllTermsIn($"{hit.SectionTitle} {hit.HeadingPath}", titleTerms))
            score += 60;

        var excerptLead = CollapseWhitespace(hit.Excerpt ?? string.Empty);
        if (excerptLead.Length > 260)
            excerptLead = excerptLead[..260];
        if (AllTermsIn(excerptLead, titleTerms))
            score += 45;

        if (AllTermsIn(hit.Excerpt ?? string.Empty, titleTerms))
            score += 25;

        if (score == 0 && AllTermsIn(GetBestExactItemEvidenceText(requestedTitle, hit), titleTerms))
            score += 8;

        return score;
    }

    private static bool LooksLikePageReferenceOnlyHit(RagHitSummary hit)
    {
        var text = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var hasStructuredEvidence = Regex.IsMatch(
            text,
            @"\b(?:items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?|preparation|operation|workflow|execution|procedure|etapes?|steps?|\d+\s*(?:g|kg|ml|cl|l))\b",
            RegexOptions.CultureInvariant);
        if (hasStructuredEvidence)
            return false;

        return Regex.IsMatch(
            text,
            @"\b[\p{L}'\-]{4,}(?:\s+[\p{L}'\-]{2,}){0,5}\s+\d{2,3}\s+[\p{L}'\-]{4,}",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeExactItemReferenceOnlyHit(string requestedTitle, RagHitSummary hit)
    {
        if (LooksLikeExactItemIndexAssetOnlyHit(requestedTitle, hit))
            return true;

        var evidence = NormalizeLexicalLookup(GetBestExactItemEvidenceText(requestedTitle, hit));
        if (string.IsNullOrWhiteSpace(evidence))
            return false;

        var hasStructuredDetails = Regex.IsMatch(
            evidence,
            @"\b(?:" + ExactItemStructureHeadingPattern + @")\b|\b\d+\s*(?:g|kg|mg|ml|cl|l|min(?:ute)?s?|h|heures?|hours?|s|sec(?:onde)?s?|(?:\u00b0|deg|degres?)\s*c)\b|(?:^|\s)[1-9][\.)]\s+",
            RegexOptions.CultureInvariant);
        if (hasStructuredDetails)
            return false;

        if (ExactItemEvidenceStartsWithRequestedTitle(requestedTitle, hit)
            && Regex.IsMatch(
                evidence,
                @"\b\d+\s*(?:min(?:ute)?s?|h|heures?|hours?|s|sec(?:onde)?s?|(?:\u00b0|deg|degres?)\s*c)\b",
                RegexOptions.CultureInvariant | RegexOptions.IgnoreCase))
        {
            return false;
        }

        if (LooksLikeNavigationOnlyHit(hit) || LooksLikePageReferenceOnlyHit(hit))
            return true;

        var titleIndex = FindApproximateRequestedTitleIndex(requestedTitle, evidence);
        if (titleIndex < 0)
        {
            foreach (var variant in BuildTypoTolerantQueryVariants(requestedTitle))
            {
                titleIndex = FindApproximateRequestedTitleIndex(variant, evidence);
                if (titleIndex >= 0)
                    break;
            }
        }

        if (!ExactItemEvidenceStartsWithRequestedTitle(requestedTitle, hit)
            && LooksLikeIndexAssetTail(evidence))
        {
            return true;
        }

        if (titleIndex < 0)
            return false;

        var titlePageReferenceCount = Regex.Matches(
            evidence,
            @"\b[\p{L}'\-]{3,}(?:\s+[\p{L}'\-]{2,}){0,5}\s+\d{1,3}\b",
            RegexOptions.CultureInvariant).Count;
        return titlePageReferenceCount >= 2;
    }

    private static bool LooksLikeIndexAssetTail(string evidence)
    {
        var normalized = NormalizeLexicalLookup(evidence);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var indexMatch = Regex.Match(
            normalized,
            @"\b(?:index|sommaire|table\s+of\s+contents|indice|inhalt)\b",
            RegexOptions.CultureInvariant);
        if (!indexMatch.Success)
            return false;

        var indexAtTail = indexMatch.Index >= normalized.Length * 0.35 || normalized.Length - indexMatch.Index <= 520;
        if (!indexAtTail)
            return false;

        var tailStart = Math.Min(indexMatch.Index, Math.Max(0, evidence.Length - 1));
        var tail = evidence[tailStart..];
        var assetRefCount = Regex.Matches(
            tail,
            @"(?i)\b(?:[a-z]{2,}\d{4,}[a-z0-9_-]*|[a-z0-9]{4,}[_-][a-z0-9][a-z0-9_-]{5,}|[a-z]{2,4}\d*[_-][a-z0-9_-]{6,})\b",
            RegexOptions.CultureInvariant).Count;
        var multiSeparatorTokenCount = Regex.Matches(
            tail,
            @"\b[\p{L}\p{N}]+(?:[_-][\p{L}\p{N}]+){2,}\b",
            RegexOptions.CultureInvariant).Count;

        return assetRefCount + multiSeparatorTokenCount >= 2;
    }

    private static bool LooksLikeExactItemIndexAssetOnlyHit(string requestedTitle, RagHitSummary hit)
    {
        var candidates = new[]
            {
                hit.Excerpt,
                hit.FullText,
                string.IsNullOrWhiteSpace(hit.ContextualSnippet) ? null : StripContextualMetadataForEvidence(hit.ContextualSnippet!),
                GetBestExactItemEvidenceText(requestedTitle, hit)
            }
            .Where(static text => !string.IsNullOrWhiteSpace(text))
            .Select(static text => CollapseWhitespace(text!))
            .Distinct(StringComparer.Ordinal)
            .ToArray();

        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        return candidates.Any(candidate =>
        {
            if (Regex.IsMatch(
                    candidate,
                    @"(?i)\[\s*index\s*:?\s*\].{0,700}\b[a-z]{2,}\d{4,}[a-z0-9_-]*",
                    RegexOptions.CultureInvariant))
            {
                return true;
            }

            if (LooksLikeExactItemIndexAssetOnlyText(requestedTitle, candidate))
                return true;

            var normalizedCandidate = NormalizeLexicalLookup(candidate);
            return LooksLikeIndexAssetTail(candidate)
                   && !TextStartsWithRequestedTitlePhrase(normalizedCandidate, normalizedTitle);
        });
    }

    private static bool LooksLikeExactItemIndexAssetOnlyText(string requestedTitle, string evidence)
    {
        if (evidence.Length < 80)
            return false;

        var titleIndex = FindApproximateRequestedTitleIndex(requestedTitle, evidence);
        if (titleIndex < 0)
        {
            foreach (var variant in BuildTypoTolerantQueryVariants(requestedTitle))
            {
                titleIndex = FindApproximateRequestedTitleIndex(variant, evidence);
                if (titleIndex >= 0)
                    break;
            }
        }
        if (titleIndex < 0)
            return false;

        var titleAtTail = titleIndex >= evidence.Length * 0.45 || evidence.Length - titleIndex <= 420;
        if (!titleAtTail)
            return false;

        var afterTitle = evidence[Math.Min(titleIndex, evidence.Length)..];
        var normalizedAfterTitle = NormalizeLexicalLookup(afterTitle);
        var hasUsableDetailsAfterTitle = Regex.IsMatch(
            normalizedAfterTitle,
            @"\b(?:" + ExactItemStructureHeadingPattern + @")\b|\b\d+\s*(?:g|kg|ml|cl|l)\b|(?:^|\s)[1-9][\.)]\s+",
            RegexOptions.CultureInvariant);
        if (hasUsableDetailsAfterTitle)
            return false;

        var hasIndexCue = Regex.IsMatch(
            normalizedAfterTitle,
            @"\b(?:index|sommaire|table\s+of\s+contents|indice|inhalt)\b",
            RegexOptions.CultureInvariant);
        var assetRefCount = Regex.Matches(
            afterTitle,
            @"(?i)\b(?:[a-z]{2,}\d{4,}[a-z0-9_-]*|[a-z0-9]{4,}[_-][a-z0-9][a-z0-9_-]{5,}|[a-z]{2,4}\d*[_-][a-z0-9_-]{6,})\b",
            RegexOptions.CultureInvariant).Count;
        var multiSeparatorTokenCount = Regex.Matches(
            afterTitle,
            @"\b[\p{L}\p{N}]+(?:[_-][\p{L}\p{N}]+){2,}\b",
            RegexOptions.CultureInvariant).Count;

        return (hasIndexCue && assetRefCount + multiSeparatorTokenCount >= 2) || assetRefCount >= 3;
    }

    private static int FindApproximateRequestedTitleIndex(string requestedTitle, string text)
    {
        var normalizedText = NormalizeLexicalLookup(text);
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        if (string.IsNullOrWhiteSpace(normalizedText) || string.IsNullOrWhiteSpace(normalizedTitle))
            return -1;

        var directIndex = normalizedText.IndexOf(normalizedTitle, StringComparison.Ordinal);
        if (directIndex >= 0)
            return Math.Min(directIndex, Math.Max(0, text.Length - 1));

        var titleTerms = ExtractRequestedTitleSignalTerms(normalizedTitle);
        if (titleTerms.Length == 0)
            return -1;

        var loosePattern = string.Join(@"[\s_\-./]+", titleTerms.Select(Regex.Escape));
        var looseMatch = Regex.Match(normalizedText, loosePattern, RegexOptions.CultureInvariant);
        if (looseMatch.Success)
            return Math.Min(looseMatch.Index, Math.Max(0, text.Length - 1));

        var cursor = 0;
        var firstIndex = -1;
        foreach (var term in titleTerms)
        {
            var termIndex = normalizedText.IndexOf(term, cursor, StringComparison.Ordinal);
            if (termIndex < 0)
                return -1;
            if (firstIndex < 0)
                firstIndex = termIndex;
            cursor = termIndex + term.Length;
        }

        return Math.Min(firstIndex, Math.Max(0, text.Length - 1));
    }

    private static int ComputeExactVisibleTitleMatchScore(string requestedTitle, RagHitSummary hit)
    {
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        if (string.IsNullOrWhiteSpace(normalizedTitle))
            return 0;

        var evidence = NormalizeLexicalLookup(GetBestExactItemEvidenceText(requestedTitle, hit));
        if (string.IsNullOrWhiteSpace(evidence))
            return 0;

        var escapedTitle = Regex.Escape(normalizedTitle);
        if (Regex.IsMatch(
                evidence,
                $@"(?<![\p{{L}}\p{{N}}]){escapedTitle}(?:\s*(?:$|[\.:;\u2022\u00b7])|(?=\s*(?:pour|items?|elements?|quantities?|preparation|operation|workflow|execution|procedure|temps|time|repos|rest)\b)|(?=(?:pour|items?|elements?|quantities?|preparation|operation|workflow|execution|procedure|temps|time|repos|rest)\b))",
                RegexOptions.CultureInvariant))
        {
            return 40;
        }

        if (evidence.Equals(normalizedTitle, StringComparison.Ordinal)
            || evidence.StartsWith(normalizedTitle + " ", StringComparison.Ordinal))
        {
            return 40;
        }

        return evidence.Contains(normalizedTitle, StringComparison.Ordinal) ? 4 : 0;
    }

    private static int ComputeExactItemProcedureEvidenceScore(string requestedTitle, RagHitSummary hit)
    {
        var evidence = GetFocusedExactItemEvidenceText(requestedTitle, hit);
        var score = ExtractProcedureSteps(evidence).Length * 6
            + ExtractVisibleDurationsAndQuantities(evidence).Length * 2;
        if (Regex.IsMatch(evidence, @"(?i)(?:^|\s)[1-9][\.)]\s+", RegexOptions.CultureInvariant))
            score += 18;
        score += ComputeExactVisibleTitleMatchScore(requestedTitle, hit);
        return score;
    }

    private static string GetFocusedExactItemEvidenceText(string requestedTitle, RagHitSummary hit)
    {
        var text = GetBestExactItemEvidenceText(requestedTitle, hit);
        var normalizedText = NormalizeLexicalLookup(text);
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        var idx = string.IsNullOrWhiteSpace(normalizedTitle)
            ? -1
            : normalizedText.IndexOf(normalizedTitle, StringComparison.Ordinal);
        if (idx < 0)
            return text;

        var start = Math.Max(0, Math.Min(idx, text.Length) - 760);
        var length = Math.Min(1800, text.Length - start);
        return TrimAfterLikelyExactItemBoundary(text.Substring(start, length));
    }

    private static string GetFocusedExactItemStructuredEvidenceText(string requestedTitle, RagHitSummary hit)
    {
        var text = GetBestExactItemEvidenceText(requestedTitle, hit);
        var normalizedText = NormalizeLexicalLookup(text);
        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        var idx = string.IsNullOrWhiteSpace(normalizedTitle)
            ? -1
            : normalizedText.IndexOf(normalizedTitle, StringComparison.Ordinal);
        if (idx >= 0)
        {
            var prefix = text[..Math.Min(idx, text.Length)];
            var prefixLooksLikePreviousStructuredItem =
                CountQuantityLikeSignals(prefix) >= 2
                && ContainsStructuredItemHeading(prefix);
            var hasPreTitleStructuredEvidence =
                !prefixLooksLikePreviousStructuredItem
                && (Regex.IsMatch(NormalizeLexicalLookup(prefix), @"\b(?:procedure|procedures?|instructions?|method|methode|etape|etapes|steps?|preparation|operation|workflow|execution|technique)\b", RegexOptions.CultureInvariant)
                    || Regex.IsMatch(prefix, @"[\u2022\u00b7]\s*\p{L}{3,}", RegexOptions.CultureInvariant));
            var start = hasPreTitleStructuredEvidence
                ? Math.Max(0, Math.Min(idx, text.Length) - 760)
                : Math.Min(idx, text.Length);
            var length = Math.Min(1800, text.Length - start);
            return TrimAfterLikelyExactItemBoundary(text.Substring(start, length));
        }

        return TrimAfterLikelyExactItemBoundary(text);
    }

    private static string GetBestExactItemEvidenceText(string requestedTitle, RagHitSummary hit)
    {
        var excerpt = CollapseWhitespace(hit.Excerpt ?? string.Empty);
        var fullText = CollapseWhitespace(hit.FullText ?? string.Empty);
        var contextual = CollapseWhitespace(hit.ContextualSnippet ?? string.Empty);
        var structuredEvidence = BuildRagHitContentCardEvidenceText(hit);
        if (contextual.Length > excerpt.Length + 40 && ExactItemTextMatchesRequestOrStructure(requestedTitle, contextual))
            return StripContextualMetadataForEvidence(contextual);
        if (fullText.Length > excerpt.Length + 120 && ExactItemTextMatchesRequestOrStructure(requestedTitle, fullText))
            return AppendContentCardEvidenceText(fullText, structuredEvidence);

        if (excerpt.Length >= 40)
            return AppendContentCardEvidenceText(excerpt, structuredEvidence);
        if (!string.IsNullOrWhiteSpace(fullText))
            return AppendContentCardEvidenceText(fullText, structuredEvidence);
        return GetBestRagEvidenceText(hit);
    }

    private static string StripContextualMetadataForEvidence(string contextual)
    {
        var value = CollapseWhitespace(contextual);
        value = Regex.Replace(
            value,
            @"(?i)\bMatched\s+(?:profile|quoted)\s+title\s*:\s*.+?(?=\s*\|\s*(?:Document|Section|HeadingPath|ChunkType|Pages|PreviousEvidence|NextEvidence|Evidence)\s*:|$)",
            string.Empty,
            RegexOptions.CultureInvariant);
        value = Regex.Replace(
            value,
            @"(?i)\bMatched\s+(?:direct_title_token_route|local_title_token_route|title_anchor_route)\s*:\s*.+?(?=\s*(?:\|\s*)?(?:Document|Section|HeadingPath|ChunkType|Pages|Context|Excerpt|PreviousContext|NextContext|PreviousEvidence|NextEvidence|Evidence)\s*:|$)",
            string.Empty,
            RegexOptions.CultureInvariant);
        value = Regex.Replace(
            value,
            @"(?i)\b(?:Matched\s+(?:profile|quoted)\s+title|Matched\s+(?:direct_title_token_route|local_title_token_route|title_anchor_route)|Document|Section|HeadingPath|ChunkType|Pages)\s*:\s*.+?(?=\s*\b(?:Matched\s+(?:profile|quoted)\s+title|Matched\s+(?:direct_title_token_route|local_title_token_route|title_anchor_route)|Document|Section|HeadingPath|ChunkType|Pages|Context|PreviousContext|NextContext|Excerpt|PreviousEvidence|NextEvidence|Evidence)\s*:|$)",
            " ",
            RegexOptions.CultureInvariant);
        value = Regex.Replace(
            value,
            @"(?i)\s*\|\s*(?:Document|Section|HeadingPath|ChunkType|Pages)\s*:[^|]+",
            " ",
            RegexOptions.CultureInvariant);
        value = Regex.Replace(
            value,
            @"(?i)\s*\|\s*(?:PreviousEvidence|NextEvidence|Evidence)\s*:\s*",
            ". ",
            RegexOptions.CultureInvariant);
        value = Regex.Replace(
            value,
            @"(?i)\b(?:Context|PreviousContext|NextContext|Excerpt|PreviousEvidence|NextEvidence|Evidence)\s*:\s*",
            ". ",
            RegexOptions.CultureInvariant);
        return CollapseWhitespace(value).Trim(' ', '.', ',', ';', ':');
    }

    private const string ItemizedSectionHeadingPattern =
        @"items?|elements?|requirements?|quantities?|quantites?|values?|valeurs?|materials?|materiel|mat[eé]riel|components?|composants?";

    private const string ProcedureSectionHeadingPattern =
        @"preparation|pr(?:e|\u00e9)paration|preparacion|prepara(?:c|\u00e7)(?:a|\u00e3)o|preparazione|zubereitung|procedure|procedures?|process|processus|operation|operations?|workflow|workflows?|execution|instruction|instructions|method|methods?|methode|methodes|m(?:e|\u00e9)thode|m(?:e|\u00e9)thodes|mode\s+operatoire|technique|etape|etapes|(?:e|\u00e9)tapes?|steps?";

    private const string ExactItemStructureHeadingPattern =
        ItemizedSectionHeadingPattern + "|" + ProcedureSectionHeadingPattern;

    private const string NonItemizedSectionHeadingPattern =
        ItemizedSectionHeadingPattern + "|" + ProcedureSectionHeadingPattern;

    private static bool ExactItemTextMatchesRequestOrStructure(string requestedTitle, string text)
    {
        var normalizedText = NormalizeLexicalLookup(text);
        if (string.IsNullOrWhiteSpace(normalizedText))
            return false;

        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        if (!string.IsNullOrWhiteSpace(normalizedTitle) && normalizedText.Contains(normalizedTitle, StringComparison.Ordinal))
            return true;

        var titleTerms = ExtractRequestedTitleSignalTerms(normalizedTitle);
        if (titleTerms.Length > 0 && titleTerms.All(term => normalizedText.Contains(term, StringComparison.Ordinal)))
            return true;

        return false;
    }

    private static string TrimAfterLikelyExactItemBoundary(string text)
    {
        var value = text ?? string.Empty;
        if (value.Length < 260)
            return value;

        var boundaries = new[]
        {
            @"\b\d{1,4}\s*[\u2022\u00b7]\s*(?:[A-Z\u00c0-\u017f]|\p{Lu})",
            @"\b\d{1,4}\s*\|\s*[\p{L} ]{3,50}"
        };

        var cutAt = value.Length;
        foreach (var pattern in boundaries)
        {
            var match = Regex.Match(value, pattern, RegexOptions.CultureInvariant);
            if (match.Success && match.Index >= 220)
                cutAt = Math.Min(cutAt, match.Index);
        }

        return cutAt < value.Length
            ? value[..cutAt].TrimEnd(' ', '.', ',', ';', ':')
            : value;
    }

    private static bool ExactItemEvidenceTextMatchesRequestedTitle(string requestedTitle, RagHitSummary hit)
    {
        var evidence = NormalizeLexicalLookup(GetBestExactItemEvidenceText(requestedTitle, hit));
        if (string.IsNullOrWhiteSpace(evidence))
            return false;

        var normalizedTitle = NormalizeLexicalLookup(requestedTitle);
        if (!string.IsNullOrWhiteSpace(normalizedTitle) && evidence.Contains(normalizedTitle, StringComparison.Ordinal))
            return true;

        var titleTerms = ExtractRequestedTitleSignalTerms(normalizedTitle);
        return titleTerms.Length > 0 && titleTerms.All(term => evidence.Contains(term, StringComparison.Ordinal));
    }

    private static void AppendFactList(StringBuilder sb, string title, IReadOnlyList<string> items, string language)
    {
        sb.Append("- ");
        sb.Append(title);
        sb.Append(" : ");
        sb.AppendLine(items.Count == 0 ? SourceBackedNotVisibleLabel(language) : string.Join("; ", items));
    }

    private static string[] ExtractContentCardEvidenceFacts(IEnumerable<RagHitSummary> hits)
        => ExtractContentCardQuantityEvidenceFacts(hits)
            .Concat(ExtractContentCardGenericEvidenceFacts(hits))
            .Concat(ExtractContentCardNonScalableReasons(hits))
            .Where(static fact => !string.IsNullOrWhiteSpace(fact))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();

    private static string[] ExtractContentCardQuantityEvidenceFacts(IEnumerable<RagHitSummary> hits)
    {
        var facts = new List<string>();
        foreach (var card in hits
                     .SelectMany(static hit => hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
                     .Where(static card => card.Evidence is not null))
        {
            var evidence = card.Evidence!;
            if (evidence.ScaleBasis is { Count: > 0 } basis)
            {
                var label = CollapseWhitespace(basis.Label ?? string.Empty);
                if (!string.IsNullOrWhiteSpace(label) && basis.Count is >= 1 and <= 50)
                {
                    facts.Add(CleanContentCardDisplayFactValue(CollapseWhitespace(string.Join(' ', new[]
                    {
                        basis.Count.ToString(CultureInfo.InvariantCulture),
                        label
                    }))));
                }
            }

            foreach (var fact in evidence.QuantityFacts.Take(8))
            {
                facts.Add(BuildContentCardDisplayFact(
                    fact.SourceText,
                    fact.Value.ToString("0.###", CultureInfo.InvariantCulture),
                    fact.Unit,
                    fact.Label));
            }
        }

        return facts
            .Where(static fact => !string.IsNullOrWhiteSpace(fact))
            .Where(IsUsefulContentCardDisplayFact)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string[] ExtractContentCardGenericEvidenceFacts(IEnumerable<RagHitSummary> hits)
    {
        var facts = new List<string>();
        foreach (var evidence in hits
                     .SelectMany(static hit => hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
                     .Select(static card => card.Evidence)
                     .Where(static evidence => evidence is not null))
        {
            var hasStructuredQuantities = evidence!.ScaleBasis is not null || evidence.QuantityFacts.Count > 0;
            foreach (var fact in (evidence!.Facts ?? []).Take(12))
            {
                if (hasStructuredQuantities && IsContentCardQuantityLikeGenericFact(fact))
                    continue;

                facts.Add(BuildContentCardDisplayFact(
                    fact.SourceText,
                    fact.Label,
                    fact.Value,
                    fact.Unit));
            }
        }

        return facts
            .Where(static fact => !string.IsNullOrWhiteSpace(fact))
            .Where(IsUsefulContentCardDisplayFact)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static bool IsContentCardQuantityLikeGenericFact(RagHitEvidenceFactSummary fact)
    {
        var kind = NormalizeLexicalLookup(fact.Kind);
        if (kind is "quantity" or "quantities" or "duration" or "durations")
            return true;

        if (double.TryParse(fact.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out _))
            return true;

        var unit = NormalizeLexicalLookup(fact.Unit);
        if (!string.IsNullOrWhiteSpace(unit)
            && double.TryParse(fact.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out _))
        {
            return true;
        }

        return false;
    }

    private static string BuildContentCardDisplayFact(string? sourceText, params string?[] structuredParts)
    {
        var structured = CollapseWhitespace(string.Join(' ', structuredParts.Where(static value => !string.IsNullOrWhiteSpace(value))));
        var source = CollapseWhitespace(sourceText ?? string.Empty);
        if (string.IsNullOrWhiteSpace(source))
            return CleanContentCardDisplayFactValue(structured);

        if (!string.IsNullOrWhiteSpace(structured)
            && (source.Length > 90 || LooksLikeNoisyContentCardSourceText(source)))
        {
            return CleanContentCardDisplayFactValue(structured);
        }

        var value = !string.IsNullOrWhiteSpace(structured) ? structured : source;
        return CleanContentCardDisplayFactValue(value);
    }

    private static string CleanContentCardDisplayFactValue(string value)
    {
        value = Regex.Replace(value, @"(?i)\bscale_basis\b", string.Empty, RegexOptions.CultureInvariant);
        value = Regex.Replace(value, @"(?i)\b(\d+(?:[\.,]\d+)?)\s*(g|kg|mg|ml|cl|l|min|s|h|cm|mm)(?=\p{L}{3,})", "$1 $2 ", RegexOptions.CultureInvariant);
        value = Regex.Replace(value, @"(?<=\p{L})(?=\d)", " ", RegexOptions.CultureInvariant);
        value = Regex.Replace(value, @"(?<=\d)(?=\p{L})", " ", RegexOptions.CultureInvariant);
        value = Regex.Replace(value, @"(?i)\b(\p{L}{4,})(cette|celui|celle|this|that)\b", "$1", RegexOptions.CultureInvariant);
        value = Regex.Replace(value, @"\b\d{5,}\b", string.Empty, RegexOptions.CultureInvariant);
        value = Regex.Replace(value, @"\s+\+\s+.*$", string.Empty, RegexOptions.CultureInvariant);
        value = Regex.Replace(value, @"(?i)\b(?:preparation|pr\u00e9paration|operation|workflow|execution|procedure)\b.*$", string.Empty, RegexOptions.CultureInvariant);
        value = CollapseWhitespace(value.Trim(' ', ';', ',', ':', '-'));
        return FormatReadableEvidenceExcerpt(value, maxLength: 90);
    }

    private static bool IsUsefulContentCardDisplayFact(string fact)
    {
        fact = CollapseWhitespace(fact);
        if (fact.Length < 3)
            return false;

        var normalized = NormalizeLexicalLookup(fact);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(normalized, @"^\d+(?:[\.,]\d+)?$", RegexOptions.CultureInvariant))
            return false;

        return !normalized.Contains("scale_basis", StringComparison.Ordinal);
    }

    private static bool LooksLikeNoisyContentCardSourceText(string source)
    {
        var normalized = NormalizeLexicalLookup(source);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return normalized.Contains("scale_basis", StringComparison.Ordinal)
            || Regex.Matches(source, @"[;,+]").Count >= 4
            || Regex.Matches(source, @"\p{L}{2,}").Count > 18;
    }

    private static string[] ExtractContentCardNonScalableReasons(IEnumerable<RagHitSummary> hits)
        => hits
            .SelectMany(static hit => hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
            .Select(static card => card.Evidence)
            .Where(static evidence => evidence is not null)
            .SelectMany(static evidence => evidence!.NonScalableReasons)
            .Select(CollapseWhitespace)
            .Where(static reason => !string.IsNullOrWhiteSpace(reason))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();

    private static bool HasContentCardEvidenceFacts(RagHitSummary hit)
        => ExtractContentCardEvidenceFacts(new[] { hit }).Length > 0;

    private static bool HasContentCardEvidence(IEnumerable<RagHitSummary> hits)
        => hits
            .SelectMany(static hit => hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
            .Any(static card => card.Evidence is not null);

    private static bool HasContentCardQuantityEvidence(IEnumerable<RagHitSummary> hits)
        => hits
            .SelectMany(static hit => hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
            .Any(static card => card.Evidence?.ScaleBasis is not null || card.Evidence?.QuantityFacts.Count > 0);

    private static bool HasContentCardNonScalableEvidence(RagHitSummary hit)
        => hit.MatchedContentCards?
            .Any(static card => card.Evidence?.NonScalableReasons.Count > 0) == true;

    private static bool HasContentCardScalableQuantityEvidence(RagHitSummary hit)
        => hit.MatchedContentCards?
            .Any(static card => card.Evidence?.ScaleBasis is { Count: > 0 }
                                && card.Evidence.NonScalableReasons.Count == 0
                                && card.Evidence.QuantityFacts.Count >= 2) == true;

    private static bool ContainsProcedureEvidenceCue(string text)
    {
        var normalized = NormalizeLexicalLookup(text);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(normalized, @"\b(?:" + ProcedureSectionHeadingPattern + @")\b", RegexOptions.CultureInvariant)
            || Regex.IsMatch(text, @"(?:^|\s)(?:[1-9][\.)]\s+|[\u2022\u00b7]\s+\p{L})", RegexOptions.CultureInvariant);
    }

    private static void AppendControlExcerpt(StringBuilder sb, string language, IReadOnlyList<RagHitSummary> hits)
    {
        var hit = hits.FirstOrDefault();
        if (hit is null)
            return;

        var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
        sb.Append("- ");
        sb.Append(SourceBackedLabel(language, "Extrait de controle", "Control excerpt", "Extracto de control", "Excerto de controlo", "Kontrollauszug", "Estratto di controllo"));
        sb.Append(" : ");
        sb.Append(docLabel);
        sb.Append(' ');
        sb.Append(SourceBackedPagePrefix(language));
        sb.Append(hit.PageStart);
        sb.Append(" - ");
        sb.AppendLine(CleanReadableProcedureArtifacts(FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 360)));
    }

    private static void AppendExactItemControlExcerpt(StringBuilder sb, string language, string requestedTitle, IReadOnlyList<RagHitSummary> hits)
    {
        var hit = hits.FirstOrDefault();
        if (hit is null)
            return;
        if (!ShouldIncludeRawSourceExcerptForAnswerLanguage(language, hit))
            return;

        var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
        sb.Append("- ");
        sb.Append(SourceBackedLabel(language, "Extrait de controle", "Control excerpt", "Extracto de control", "Excerto de controlo", "Kontrollauszug", "Estratto di controllo"));
        sb.Append(" : ");
        sb.Append(docLabel);
        sb.Append(' ');
        sb.Append(SourceBackedPagePrefix(language));
        sb.Append(hit.PageStart);
        sb.Append(" - ");
        sb.AppendLine(CleanReadableProcedureArtifacts(FormatReadableEvidenceExcerpt(GetFocusedExactItemStructuredEvidenceText(requestedTitle, hit), maxLength: 360)));
    }

    private static bool ShouldIncludeRawSourceExcerptForAnswerLanguage(string language, RagHitSummary hit)
    {
        var answerLanguage = NormalizeLanguageCode(language);
        var docLanguage = NormalizeDocumentLanguageTag(hit.DocLanguage ?? hit.ProfileLanguage);
        if (string.Equals(docLanguage, "und", StringComparison.Ordinal))
            return string.Equals(answerLanguage, "fr", StringComparison.Ordinal);

        var docPrimary = docLanguage.Split('-', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).FirstOrDefault();
        return string.Equals(answerLanguage, docPrimary, StringComparison.OrdinalIgnoreCase);
    }

    private static string SourceBackedLabel(string language, string fr, string en, string es, string pt, string de, string it)
        => NormalizeLanguageCode(language) switch
        {
            "en" => en,
            "es" => es,
            "pt" => pt,
            "de" => de,
            "it" => it,
            _ => fr
        };

    private static string SourceBackedNotVisibleLabel(string language)
        => SourceBackedLabel(
            language,
            "non visible dans les extraits retenus",
            "not visible in the retained excerpts",
            "no visible en los extractos retenidos",
            "nao visivel nos excertos retidos",
            "in den behaltenen Auszuegen nicht sichtbar",
            "non visibile negli estratti mantenuti");

    private static string SourceBackedPagePrefix(string language)
        => SourceBackedLabel(language, "p.", "p.", "p.", "p.", "S.", "p.");

    private static string SourceBackedVisibleMinutesSuffix(string language)
        => SourceBackedLabel(
            language,
            "min visibles",
            "visible minutes",
            "min visibles",
            "min visiveis",
            "sichtbare Min.",
            "min visibili");

    private static string[] ExtractParameterFacts(string text)
    {
        var readable = FormatReadableEvidenceExcerpt(text, maxLength: 900);
        var matches = Regex.Matches(
                readable,
                @"(?i)\b(?:programme\s+[A-Z][\p{L}\-]*|mode\s+manuel|fonction\s+[A-Z][\p{L}\-]*|vitesse\s*\d+|speed\s*\d+|\d+\s*(?:°\s*)?C|\d+\s*(?:min|minutes?|h|heures?))\b",
                RegexOptions.CultureInvariant)
            .Select(static match => CollapseWhitespace(match.Value))
            .Where(static value => value.Length >= 2)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        return matches;
    }

    private static string[] ExtractVisibleDurationsAndQuantities(string text)
    {
        var readable = FormatReadableEvidenceExcerpt(text, maxLength: 900);
        return Regex.Matches(
                readable,
                @"(?i)\b(?:(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+[\p{L}'\u2019.\-]{2,30}|\d{1,3}\s+[\p{L}'\u2019.\-]{2,30}|\d+\s*(?:min|minutes?|h|heures?|hours?))\b",
                RegexOptions.CultureInvariant)
            .Select(static match => CollapseWhitespace(match.Value))
            .Where(static value => LooksLikeVisibleDurationOrQuantityFact(value))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static bool LooksLikeVisibleDurationOrQuantityFact(string value)
    {
        var normalized = NormalizeLooseLookup(value);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(normalized, @"\b\d+\s*(?:min|minutes?|h|heures?|hours?)\b", RegexOptions.CultureInvariant))
            return true;

        var labelMatch = Regex.Match(normalized, @"(?:^|\s)(?<n>\d{1,3})\s+(?<label>[\p{L}'\u2019.\-]{2,30})\b", RegexOptions.CultureInvariant);
        return labelMatch.Success && IsPlausibleScaleCountLabel(labelMatch.Groups["label"].Value);
    }

    private static string[] ExtractItemizedQuantityFacts(string text)
    {
        var readable = FormatReadableEvidenceExcerpt(text, maxLength: 1200);
        readable = Regex.Replace(readable, @"(?<=\p{L})(?=\d)", " ", RegexOptions.CultureInvariant);
        readable = Regex.Replace(readable, @"(?<=\d)(?=\p{L})", " ", RegexOptions.CultureInvariant);
        readable = RemoveMalformedFrenchFairePastParticipleFragments(readable);
        var compactItemizedSegments = ExtractCompactItemizedSegments(readable);
        var matches = Regex.Matches(
                readable,
                @"(?i)\b\d+(?:[,.]\d+)?\s*(?:%|[a-zA-Z]{1,8}\.?|[\p{L}]{1,12})\s*(?:de|d['’‘`])?\s*[\p{L}'’‘`\-\s]{2,55}",
                RegexOptions.CultureInvariant)
            .Select(static match => CleanItemizedQuantityFact(match.Value))
            .Where(IsLikelyItemizedSegment)
            .Where(static value => value.Length is >= 5 and <= 90 && !LooksLikeTruncatedItemizedFact(value) && !LooksLikeTruncatedProcedureSegment(value))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        matches.AddRange(Regex.Matches(
                readable,
                @"(?i)\b\d+(?:[,.]\d+)?\s+[\p{L}'’‘`\-]{3,}(?:\s+(?:de|d['’‘`]|du|des)\s*[\p{L}'’‘`\-]{3,})?",
                RegexOptions.CultureInvariant)
            .Select(static match => CleanItemizedSegment(match.Value))
            .Where(IsLikelyItemizedSegment));

        matches.AddRange(compactItemizedSegments);
        matches = matches
            .Where(static value => !LooksLikeMaterialOnlyFact(value))
            .Where(static value => !LooksLikeTruncatedProcedureSegment(value))
            .Where(static value => !LooksLikeProcedureInstructionSegment(value))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(12)
            .ToList();

        if (matches.Count == 0)
        {
            matches.AddRange(SplitEvidenceSegments(readable)
                .Where(static segment => ContainsStructuredItemHeading(segment) || CountQuantityLikeSignals(segment) >= 2)
                .Select(static segment => CleanItemizedSegment(segment))
                .Where(static segment => segment.Length is >= 5 and <= 160)
                .Where(static segment => !LooksLikeTruncatedItemizedFact(segment))
                .Where(static segment => !LooksLikeTruncatedProcedureSegment(segment))
                .Where(static segment => !LooksLikeProcedureInstructionSegment(segment))
                .Where(static segment => !LooksLikeMaterialOnlyFact(segment))
                .Take(6));
        }

        return matches.ToArray();
    }

    private static bool LooksLikeProcedureInstructionSegment(string segment)
    {
        var normalized = NormalizeLexicalLookup(segment).Trim();
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(
                normalized,
                @"^(?:a\s+la\s+fin|au\s+bout|dans|puis|ensuite|then|when|after|before|" + OperationalActionLeadPattern + @")\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        return Regex.IsMatch(normalized, @"\b(?:vitesse|speed|programme|program|mode|cycle|sequence|operation|execution|parametre|parametres|setting|settings|configuration)\b", RegexOptions.CultureInvariant)
               && Regex.IsMatch(normalized, @"\b\d+\s*(?:min(?:ute)?s?|h|heures?|hours?|s|sec(?:onde)?s?|(?:\u00b0|deg|degres?)\s*c)\b", RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeMaterialOnlyFact(string value)
    {
        if (Regex.IsMatch(
                value ?? string.Empty,
                @"(?i)\b(?:mat[eé]riel|mat(?:é|.)?riel|materials?|equipment)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        var normalized = NormalizeLexicalLookup(value);
        return Regex.IsMatch(normalized, @"\b(?:materiel|materials?|equipment|tools?|outils?|devices?|instruments?)\b", RegexOptions.CultureInvariant);
    }

    private static string CleanItemizedQuantityFact(string value)
    {
        var cleaned = CollapseWhitespace((value ?? string.Empty).Trim(' ', '.', ',', ';', ':'));
        cleaned = RemoveMalformedFrenchFairePastParticipleFragments(cleaned);
        cleaned = Regex.Replace(
            cleaned,
            @"(?i)\s+\b(?:pour|for|para|per)\s+(?:la|le|les|l['’]|the|a|el|los|las|o|os|as|il|lo|gli|die|der|das)?\s*[\p{L}'’\-\s]{2,}$",
            string.Empty,
            RegexOptions.CultureInvariant);
        return CollapseWhitespace(cleaned).Trim(' ', '.', ',', ';', ':');
    }

    private static IEnumerable<string> ExtractCompactItemizedSegments(string readable)
    {
        var scoped = ExtractItemizedScope(readable);
        foreach (var segment in SplitEvidenceSegments(scoped))
        {
            var cleaned = CleanItemizedSegment(segment);
            if (IsLikelyItemizedSegment(cleaned))
                yield return cleaned;
        }
    }

    private static string ExtractItemizedScope(string readable)
    {
        var match = Regex.Match(
            readable,
            @"(?is)\b(?:" + ItemizedSectionHeadingPattern + @")\b\s*[:\-]?\s*(?<body>.+?)(?:\b(?:" + ProcedureSectionHeadingPattern + @")\b|$)",
            RegexOptions.CultureInvariant);
        return match.Success ? CutBeforeSectionHeading(match.Groups["body"].Value, NonItemizedSectionHeadingPattern) : readable;
    }

    private static string ExtractPreparationScope(string readable)
    {
        var proceduralMatch = Regex.Match(
            readable,
            @"(?is)\b(?:" + ProcedureSectionHeadingPattern + @")\b\s*[:\-]?\s*(?<body>.+)$",
            RegexOptions.CultureInvariant);
        if (proceduralMatch.Success)
            return proceduralMatch.Groups["body"].Value;

        var match = Regex.Match(
            readable,
            @"(?is)\b(?:preparation|pr[eé]paration|preparacion|prepara[cç][aã]o|preparazione|zubereitung|operation|operations?|workflow|workflows?|execution|procedure|procedures?|process|processus|instructions?|etapes?|[eé]tapes?|steps?)\b\s*[:\-]?\s*(?<body>.+)$",
            RegexOptions.CultureInvariant);
        return match.Success ? match.Groups["body"].Value : readable;
    }

    private static string CutBeforeSectionHeading(string text, string headingPattern)
    {
        var value = text ?? string.Empty;
        var match = Regex.Match(
            value,
            @"(?is)\b(?:" + headingPattern + @")\b\s*[:\-]?",
            RegexOptions.CultureInvariant);
        return match.Success ? value[..match.Index] : value;
    }

    private static string CleanItemizedSegment(string segment)
    {
        var cleaned = CollapseWhitespace(segment)
            .Trim(' ', '.', ',', ';', ':', '-', '\u2022', '\u00b7');
        cleaned = RemoveMalformedFrenchFairePastParticipleFragments(cleaned);
        cleaned = Regex.Replace(
            cleaned,
            @"(?is)\b(?:" + NonItemizedSectionHeadingPattern + @")\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant);
        cleaned = Regex.Replace(
            cleaned,
            @"(?is)\b(?:" + ProcedureSectionHeadingPattern + @")\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant);
        cleaned = Regex.Replace(
            cleaned,
            @"(?i)^\b(?:" + ItemizedSectionHeadingPattern + @")\b\s*[:\-]?\s*",
            string.Empty,
            RegexOptions.CultureInvariant);
        return CollapseWhitespace(cleaned).Trim(' ', '.', ',', ';', ':', '-', '\u2022', '\u00b7');
    }

    private static bool IsLikelyItemizedSegment(string segment)
    {
        if (string.IsNullOrWhiteSpace(segment) || segment.Length is < 3 or > 100)
            return false;
        if (LooksLikeTruncatedItemizedFact(segment))
            return false;

        var normalized = NormalizeLexicalLookup(segment);
        if (LooksLikeProcedureInstructionSegment(normalized))
            return false;
        if (Regex.IsMatch(normalized, @"\b(?:preparation|operation|workflow|execution|etape|etapes|temps|time|duration|duree|procedure|method|methode|instructions?|steps?)\b", RegexOptions.CultureInvariant))
            return false;
        if (Regex.IsMatch(normalized, @"^\d+(?:[,.]\d+)?\s*(?:min|minutes?|h|heures?|hour|hours|c|celsius)\b", RegexOptions.CultureInvariant))
            return false;
        if (Regex.IsMatch(normalized, @"^\d+(?:[,.]\d+)?\s+(?:a|l)\b", RegexOptions.CultureInvariant))
            return false;
        var leadingNumberLabel = Regex.Match(normalized, @"^\d+(?:[,.]\d+)?\s+(?<label>[\p{L}'\u2019.\-]{2,30})\b", RegexOptions.CultureInvariant);
        if (leadingNumberLabel.Success && LooksLikeProcedureLeadLabel(leadingNumberLabel.Groups["label"].Value))
            return false;
        var leadingWord = Regex.Match(normalized, @"^(?<label>[\p{L}'\u2019.\-]{2,30})\b", RegexOptions.CultureInvariant);
        if (leadingWord.Success && LooksLikeProcedureLeadLabel(leadingWord.Groups["label"].Value))
            return false;
        if (Regex.IsMatch(normalized, @"^\d+(?:[,.]\d+)?\s+(?:dans|puis|quand|when|then|after|before|until|jusqu|pendant)\b", RegexOptions.CultureInvariant))
            return false;
        if (Regex.IsMatch(normalized, @"^\d+(?:[,.]\d+)?\s+(?:materials?|equipment|tools?|outils?|devices?|instruments?)\b", RegexOptions.CultureInvariant))
            return false;
        if (Regex.IsMatch(normalized, @"^\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l|mm|cm|m|bar|pa|kpa|mpa|v|a|w|hz|rpm|%|[a-z]{1,8}\.?|units?|items?|pieces?)\b", RegexOptions.CultureInvariant))
            return true;
        if (Regex.IsMatch(normalized, @"^\d+(?:[,.]\d+)?\s+\p{L}{3,}(?:\s+\p{L}{2,}){0,5}$", RegexOptions.CultureInvariant))
            return true;

        return Regex.IsMatch(normalized, @"^[\p{L}'\-]{3,}(?:\s+[\p{L}'\-]{2,}){0,5}$", RegexOptions.CultureInvariant)
            && !Regex.IsMatch(normalized, @"\b(?:items?|elements?|requirements?|preparation|operation|workflow|execution|procedure|method|methode|technique|materiel|materials?|equipment|tools?|outils?)\b", RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeTruncatedItemizedFact(string value)
    {
        var normalized = NormalizeLexicalLookup(value);
        return Regex.IsMatch(normalized, @"\b(?:de|d)\s+\p{L}{1,2}$", RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeItemizedListSegment(string segment)
    {
        var normalized = NormalizeLexicalLookup(segment);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(normalized, @"\b(?:" + ItemizedSectionHeadingPattern + @")\b", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"^(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+\p{L}", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"^\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l|mm|cm|m|bar|pa|kpa|mpa|v|a|w|hz|rpm|%|[a-z]{1,8}\.?|units?|items?|pieces?)\b", RegexOptions.CultureInvariant);
    }

    private static string[] ExtractProcedureSteps(string text)
    {
        var readable = FormatReadableEvidenceExcerpt(text, maxLength: 1400);
        readable = Regex.Replace(readable, @"(?<=\p{L})\.(?=[1-9]\.)", ". ", RegexOptions.CultureInvariant);
        readable = Regex.Replace(readable, @"(?<=[1-9]\.)(?=\p{L})", " ", RegexOptions.CultureInvariant);
        var proceduralScope = ExtractPreparationScope(readable);
        var numbered = Regex.Matches(
                proceduralScope,
                @"(?i)(?:^|\s)(?:[1-9][\.)]\s*)(?<step>.{18,190}?)(?=\s*[1-9][\.)]\s*|$)",
                RegexOptions.CultureInvariant)
            .Select(static match => CleanProcedureStep(match.Groups["step"].Value))
            .Where(static value => value.Length is >= 12 and <= 220 && !LooksLikeItemizedListSegment(value) && !LooksLikeTruncatedProcedureSegment(value))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(6)
            .ToArray();
        if (numbered.Length > 0)
            return numbered;

        var scopedCandidates = ExtractProcedureCandidateSegments(proceduralScope).ToArray();
        var allCandidates = ExtractProcedureCandidateSegments(readable).ToArray();
        if (allCandidates.Length > scopedCandidates.Length)
            return allCandidates.Take(10).ToArray();

        return scopedCandidates.Take(10).ToArray();
    }

    private static IEnumerable<string> ExtractProcedureCandidateSegments(string text)
    {
        return SplitEvidenceSegments(text)
            .Select(static segment => CleanProcedureStep(segment))
            .Where(static segment => !LooksLikeItemizedListSegment(segment))
            .Where(static segment => !LooksLikeTruncatedProcedureSegment(segment))
            .Where(static segment => LooksLikeProcedureCandidateSegment(segment));
    }

    private static bool LooksLikeProcedureCandidateSegment(string segment)
    {
        var normalized = NormalizeLexicalLookup(segment);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (Regex.IsMatch(normalized, @"\b(?:procedure|procedures?|instructions?|method|methode|etape|etapes|steps?|process|processus)\b", RegexOptions.CultureInvariant))
            return true;

        var wordCount = Regex.Matches(normalized, @"\b\p{L}{3,}\b", RegexOptions.CultureInvariant).Count;
        if (wordCount < 3)
            return false;

        return wordCount >= 3
            || Regex.IsMatch(normalized, @"\b(?:puis|ensuite|avant|apres|lorsque|quand|when|then|after|before|until|jusqu|pendant|pendant\s+que|while)\b", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"\b\d+(?:[,.]\d+)?\s*(?:s|sec|secs|secondes?|seconds?|min|h|hours?|mm|cm|m|g|kg|mg|ml|cl|l|%|(?:\u00b0|deg|degres?)\s*c)\b", RegexOptions.CultureInvariant)
            || segment.Contains(';', StringComparison.Ordinal)
            || segment.Contains(',', StringComparison.Ordinal);
    }

    private static string CleanProcedureStep(string value)
    {
        var cleaned = CollapseWhitespace(value ?? string.Empty).Trim(' ', '.', ';', ':');
        cleaned = RemoveMalformedFrenchFairePastParticipleFragments(cleaned);
        cleaned = Regex.Replace(
            cleaned,
            @"(?<=\p{L})\.\s*[1-9]\.?\s*$",
            string.Empty,
            RegexOptions.CultureInvariant);
        return CollapseWhitespace(cleaned).Trim(' ', '.', ';', ':');
    }

    private static string CleanReadableProcedureArtifacts(string value)
    {
        var cleaned = CollapseWhitespace(value ?? string.Empty);
        cleaned = RemoveMalformedFrenchFairePastParticipleFragments(cleaned);
        return CollapseWhitespace(cleaned).Trim(' ', '.', ';', ':');
    }

    private static string RemoveMalformedFrenchFairePastParticipleFragments(string value)
        => Regex.Replace(
            value ?? string.Empty,
            @"(?i)\bfaites?\s+\p{L}{4,}i\b\.?\s*(?=(?:\s*(?:[-*\u2022\u00b7]|\p{Lu})|$))",
            string.Empty,
            RegexOptions.CultureInvariant);

    private static bool LooksLikeTruncatedProcedureSegment(string segment)
    {
        var normalized = NormalizeLexicalLookup(segment).Trim();
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        return Regex.IsMatch(normalized, @"\b(?:de|du|des|d|a|avec|sans|et|puis|jusqu|jusque|pendant|pour)$", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"\bfaites?\s+\p{L}{4,}i\b", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"\b\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l)\s+(?:de|d)\s+\p{L}{1,2}$", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"\b(?:de|d)\s+\p{L}{1,2}$", RegexOptions.CultureInvariant);
    }

    private static IEnumerable<string> SplitEvidenceSegments(string text)
    {
        foreach (var segment in Regex.Split(text, @"(?:\s*[\u2022\u00b7]\s*|(?<=[\.;!?])\s+)", RegexOptions.CultureInvariant))
        {
            var cleaned = CollapseWhitespace(segment).Trim(' ', '.', ',', ';', ':');
            if (cleaned.Length is >= 8 and <= 220)
                yield return cleaned;
        }
    }

    private static string FormatReadableEvidenceExcerpt(string? excerpt, int maxLength)
    {
        var text = PrepareReadableEvidenceText(excerpt);
        if (text.Length == 0)
            return string.Empty;

        return text.Length <= maxLength
            ? text
            : text[..maxLength].TrimEnd() + "...";
    }

    private static string PrepareReadableEvidenceText(string? excerpt)
    {
        var text = CollapseWhitespace(excerpt ?? string.Empty);
        if (text.Length == 0)
            return string.Empty;

        text = Regex.Replace(text, @"(?<=\p{Ll})(?=\p{Lu})", " ", RegexOptions.CultureInvariant);
        text = Regex.Replace(text, @"(?<=\p{Lu})(?=\p{Lu}\p{Ll})", " ", RegexOptions.CultureInvariant);
        text = Regex.Replace(text, @"(?<=\d)(?=\p{Lu})", " ", RegexOptions.CultureInvariant);
        text = Regex.Replace(text, @"(?<=\p{L})(?=\d+\s*min\b)", " ", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        return Regex.Replace(text, @"\s+", " ").Trim();
    }

    private static string FormatSourceBackedEvidenceExcerpt(RagHitSummary hit, string query, int maxLength)
    {
        var evidence = GetBestRagEvidenceText(hit);
        if (LooksLikeShortTechnicalEvidenceTopic(query))
        {
            var focused = FocusShortTechnicalEvidenceText(hit, query, maxLength);
            if (!string.IsNullOrWhiteSpace(focused))
                evidence = focused;
        }

        return FormatReadableEvidenceExcerpt(evidence, maxLength);
    }

    private static string FocusShortTechnicalEvidenceText(RagHitSummary hit, string query, int maxLength)
    {
        var readable = PrepareReadableEvidenceText($"{hit.SectionTitle} {hit.HeadingPath} {hit.FullText} {hit.ContextualSnippet} {BuildRagHitContentCardEvidenceText(hit)}");
        if (string.IsNullOrWhiteSpace(readable))
            readable = PrepareReadableEvidenceText(GetBestRagEvidenceText(hit));
        if (string.IsNullOrWhiteSpace(readable))
            return string.Empty;

        var topic = NormalizeLexicalLookup(NormalizeRagQueryForRetrieval(BuildRagEvidenceSelectionQuery(query)));
        var phraseIndex = FindShortTechnicalPhraseEvidenceIndex(topic, readable);
        if (phraseIndex < 0)
            phraseIndex = FindShortTechnicalTermEvidenceIndex(topic, readable);
        if (phraseIndex < 0)
            return string.Empty;

        var lead = Math.Max(40, maxLength / 4);
        var start = Math.Max(0, phraseIndex - lead);
        if (start > 0)
        {
            var boundary = readable.LastIndexOfAny(new[] { '.', ';', ':', '\n' }, Math.Min(phraseIndex, readable.Length - 1));
            if (boundary >= 0 && phraseIndex - boundary <= lead + 80)
                start = Math.Min(readable.Length, boundary + 1);
        }

        start = Math.Max(0, start);
        var length = Math.Min(readable.Length - start, Math.Max(maxLength + 120, maxLength));
        var window = readable.Substring(start, length).Trim();
        return start > 0 ? "... " + window : window;
    }

    private static int FindShortTechnicalPhraseEvidenceIndex(string normalizedTopic, string readableEvidence)
    {
        var terms = BuildShortTechnicalEvidenceSelectionTerms(normalizedTopic).ToHashSet(StringComparer.Ordinal);
        var hasProperty = terms.Overlaps(new[] { "propriete", "proprietes", "property", "properties", "caracteristique", "caracteristiques", "characteristic", "characteristics" });
        var hasElectrical = terms.Overlaps(new[] { "electrique", "electriques", "electric", "electrical", "dielectric" });
        var hasThermal = terms.Overlaps(new[] { "thermique", "thermiques", "thermal", "temperature", "temperatures" });

        if (hasProperty && hasElectrical)
            return MatchIndex(readableEvidence, @"\b(?:electrical\s+properties|electric\s+properties|dielectric\s+properties|properties\s+(?:electrical|electric|dielectric)|electrical\s+characteristics|dielectric\s+strength|propri[eé]t[eé]s?\s+[eé]lectriques?|caract[eé]ristiques?\s+[eé]lectriques?)\b");

        if (hasProperty && hasThermal)
            return MatchIndex(readableEvidence, @"\b(?:thermal\s+properties|temperature\s+properties|properties\s+thermal|thermal\s+characteristics|melt\s+point|service\s+temperature|propri[eé]t[eé]s?\s+thermiques?|caract[eé]ristiques?\s+thermiques?)\b");

        return -1;
    }

    private static int FindShortTechnicalTermEvidenceIndex(string normalizedTopic, string readableEvidence)
    {
        var propertyTerms = new HashSet<string>(new[] { "propriete", "proprietes", "property", "properties", "caracteristique", "caracteristiques", "characteristic", "characteristics" }, StringComparer.Ordinal);
        var terms = BuildShortTechnicalEvidenceSelectionTerms(normalizedTopic)
            .Where(term => !propertyTerms.Contains(term))
            .OrderByDescending(static term => term.Length)
            .Concat(BuildShortTechnicalEvidenceSelectionTerms(normalizedTopic).Where(propertyTerms.Contains))
            .Distinct(StringComparer.Ordinal)
            .ToArray();

        foreach (var term in terms)
        {
            var pattern = term switch
            {
                "electrique" or "electriques" => @"\b[eé]lectriques?\b",
                "thermique" or "thermiques" => @"\bthermiques?\b",
                _ => @"\b" + Regex.Escape(term) + @"\b"
            };
            var index = MatchIndex(readableEvidence, pattern);
            if (index >= 0)
                return index;
        }

        return -1;
    }

    private static int MatchIndex(string text, string pattern)
    {
        var match = Regex.Match(text, pattern, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        return match.Success ? match.Index : -1;
    }

    private static string GetBestRagEvidenceText(RagHitSummary hit)
    {
        var excerpt = CollapseWhitespace(hit.Excerpt ?? string.Empty);
        var fullText = CollapseWhitespace(hit.FullText ?? string.Empty);
        var structuredEvidence = BuildRagHitContentCardEvidenceText(hit);

        if (fullText.Length > excerpt.Length + 80 && LooksLikeTruncatedEvidenceLead(excerpt))
            return AppendContentCardEvidenceText(fullText, structuredEvidence);
        if (excerpt.Length >= 40)
            return AppendContentCardEvidenceText(excerpt, structuredEvidence);
        if (fullText.Length > excerpt.Length + 80)
            return AppendContentCardEvidenceText(fullText, structuredEvidence);
        if (!string.IsNullOrWhiteSpace(structuredEvidence))
            return string.IsNullOrWhiteSpace(excerpt)
                ? structuredEvidence
                : $"{excerpt} {structuredEvidence}";
        if (!string.IsNullOrWhiteSpace(excerpt))
            return AppendContentCardEvidenceText(excerpt, structuredEvidence);
        return fullText;
    }

    private static string AppendContentCardEvidenceText(string primary, string structuredEvidence)
    {
        primary = CollapseWhitespace(primary ?? string.Empty);
        structuredEvidence = CollapseWhitespace(structuredEvidence ?? string.Empty);
        if (string.IsNullOrWhiteSpace(primary) || string.IsNullOrWhiteSpace(structuredEvidence))
            return primary;

        var normalizedPrimary = NormalizeLexicalLookup(primary);
        var normalizedEvidence = NormalizeLexicalLookup(structuredEvidence);
        if (!string.IsNullOrWhiteSpace(normalizedEvidence)
            && normalizedPrimary.Contains(normalizedEvidence, StringComparison.Ordinal))
            return primary;

        return CollapseWhitespace($"{primary} {structuredEvidence}");
    }

    private static string BuildRagHitContentCardEvidenceText(RagHitSummary hit)
    {
        if (hit.MatchedContentCards is not { Count: > 0 })
            return string.Empty;

        var parts = new List<string>();
        foreach (var evidence in hit.MatchedContentCards.Select(static card => card.Evidence).Where(static evidence => evidence is not null))
        {
            if (evidence!.ScaleBasis is { Count: > 0 } basis)
            {
                parts.Add(CleanContentCardDisplayFactValue(CollapseWhitespace(string.Join(' ', new[]
                {
                    basis.Count.ToString(CultureInfo.InvariantCulture),
                    basis.Label
                }.Where(static value => !string.IsNullOrWhiteSpace(value))))));
            }

            foreach (var fact in evidence.QuantityFacts.Take(8))
            {
                parts.Add(CleanContentCardDisplayFactValue(CollapseWhitespace(string.Join(' ', new[]
                {
                    fact.Value.ToString("0.###", CultureInfo.InvariantCulture),
                    fact.Unit,
                    fact.Label,
                    fact.SourceText
                }.Where(static value => !string.IsNullOrWhiteSpace(value))))));
            }

            foreach (var fact in (evidence.Facts ?? []).Take(12))
            {
                parts.Add(CleanContentCardDisplayFactValue(CollapseWhitespace(string.Join(' ', new[]
                {
                    fact.Kind,
                    fact.Label,
                    fact.Value,
                    fact.Unit,
                    fact.SourceText
                }.Where(static value => !string.IsNullOrWhiteSpace(value))))));
            }

            foreach (var reason in evidence.NonScalableReasons.Take(6))
            {
                parts.Add(CollapseWhitespace(reason));
            }
        }

        return CollapseWhitespace(string.Join(' ', parts.Where(static part => !string.IsNullOrWhiteSpace(part))));
    }

    private static bool LooksLikeTruncatedEvidenceLead(string? value)
    {
        var text = CollapseWhitespace(value ?? string.Empty).Trim();
        text = text.TrimStart('.', '\u2026', ' ', '-', ':');
        if (text.Length < 12)
            return false;

        var normalized = NormalizeLexicalLookup(text);
        if (Regex.IsMatch(normalized, @"^(?:nt|es|e|s|de|du|des|la|le|les|a|au|aux|et|ou)\b", RegexOptions.CultureInvariant))
            return true;

        return char.IsLower(text[0])
            && !Regex.IsMatch(normalized, @"^(?:preparation|operation|workflow|execution|procedure|pour|for|para|per)\b", RegexOptions.CultureInvariant);
    }

    private static string BuildReadableSourceBackedFallbackIfUseful(ToolResults toolResults, string query, string language)
    {
        var intentQuery = ResolveSourceBackedFallbackIntentQuery(query);
        if (LooksLikeAnyDocumentaryPlanningRequest(intentQuery))
        {
            var hits = SelectSourceBackedExtractiveHits(toolResults, intentQuery, maxHits: 8).ToList();
            var planningFallback = BuildReadablePartialPlanningEvidenceAnswer(hits, intentQuery, language);
            if (!string.IsNullOrWhiteSpace(planningFallback))
                return SuppressBroadenedSearchOfferIfAlreadyConfirmed(planningFallback, query, language);
        }

        var candidateFallback = BuildReadableSourceBackedCandidateListFallbackAnswer(toolResults, intentQuery, language);
        if (!string.IsNullOrWhiteSpace(candidateFallback))
            return SuppressBroadenedSearchOfferIfAlreadyConfirmed(candidateFallback, query, language);

        if (!LooksLikeAnyDocumentaryPlanningRequest(intentQuery))
        {
            var hits = SelectSourceBackedExtractiveHits(toolResults, intentQuery, maxHits: 8).ToList();
            var planningFallback = BuildReadablePartialPlanningEvidenceAnswer(hits, intentQuery, language);
            if (!string.IsNullOrWhiteSpace(planningFallback))
                return SuppressBroadenedSearchOfferIfAlreadyConfirmed(planningFallback, query, language);
        }

        return string.Empty;
    }

    private static string BuildSourceBackedPlanningOrExtractiveAnswer(ToolResults toolResults, string query, string language, int minPlanningItems = 1)
    {
        var intentQuery = ResolveSourceBackedFallbackIntentQuery(query);
        var avoidRawSourceBackedFallback = ShouldAvoidRawSourceBackedFallback(query);

        var missingRequiredEvidence = TryBuildMissingRequiredEvidenceAnswer(toolResults, query, language);
        if (!ShouldUseAdvisoryEvidenceGuardForBroadSynthesis(toolResults, query)
            && !string.IsNullOrWhiteSpace(missingRequiredEvidence))
            return AppendBroadenedSearchOfferIfHelpful(missingRequiredEvidence, query, language);

        var missingPairingAnchor = TryBuildMissingPairingAnchorAnswer(toolResults, query, language);
        if (!ShouldUseAdvisoryEvidenceGuardForBroadSynthesis(toolResults, query)
            && !string.IsNullOrWhiteSpace(missingPairingAnchor))
            return AppendBroadenedSearchOfferIfHelpful(missingPairingAnchor, query, language);

        var documentVersionAnswer = TryBuildDocumentVersionTraceabilityAnswer(toolResults, query, language);
        if (!string.IsNullOrWhiteSpace(documentVersionAnswer))
            return documentVersionAnswer;

        var countdownAnswer = BuildSourceBackedCountdownPlanningAnswer(toolResults, query, language);
        if (!string.IsNullOrWhiteSpace(countdownAnswer))
            return countdownAnswer;

        if (avoidRawSourceBackedFallback
            && (LooksLikeAnyDocumentaryPlanningRequest(query)
                || LooksLikeGenericCollectionOrListRequest(query)
                || LooksLikeBroadSourceBackedCompositionRequest(query)
                || LooksLikeMultipleCandidateSynthesisRequest(query)
                || LooksLikeSoftChoiceRecommendationRequest(query)
                || LooksLikeSourceBackedOptionRequest(query)
                || LooksLikeSourceBackedPairingRecommendationRequest(query)))
        {
            return BuildBroadEvidenceStillInsufficientAnswer(
                language,
                query,
                intentQuery,
                EnumerateRagHitSummaries(toolResults).Count());
        }

        if (LooksLikeAnyDocumentaryPlanningRequest(query))
        {
            var planningAnswer = BuildSourceBackedPlanningAnswer(toolResults, language, minItems: minPlanningItems, query: query);
            if (!string.IsNullOrWhiteSpace(planningAnswer))
                return planningAnswer;
        }

        if (ShouldPreferPartialEvidenceFallbackOverOptions(toolResults, query))
        {
            var readableFallback = BuildReadableSourceBackedFallbackIfUseful(toolResults, query, language);
            if (!string.IsNullOrWhiteSpace(readableFallback))
                return readableFallback;
            if (!avoidRawSourceBackedFallback)
                return BuildRagEvidenceFallbackAnswer(toolResults, query, language);
        }

        if (ShouldUseFallbackForBroadMethodOptionRequest(query))
        {
            var readableFallback = BuildReadableSourceBackedFallbackIfUseful(toolResults, query, language);
            if (!string.IsNullOrWhiteSpace(readableFallback))
                return readableFallback;
            if (!avoidRawSourceBackedFallback)
                return BuildRagEvidenceFallbackAnswer(toolResults, query, language);
        }

        if (!avoidRawSourceBackedFallback
            && !LooksLikeSourceBackedOptionRequest(query)
            && !LooksLikeSourceBackedPairingRecommendationRequest(query)
            && !LooksLikeAnyDocumentaryPlanningRequest(query))
        {
            var extractiveAnswer = BuildSourceBackedExtractiveAnswer(toolResults, query, language);
            return !string.IsNullOrWhiteSpace(extractiveAnswer)
                ? extractiveAnswer
                : BuildRagEvidenceFallbackAnswer(toolResults, query, language);
        }

        var optionAnswer = BuildSourceBackedOptionAnswer(toolResults, language, minItems: 1, query: query);
        if (!string.IsNullOrWhiteSpace(optionAnswer))
            return optionAnswer;

        if (avoidRawSourceBackedFallback)
        {
            var readableOptionFallback = BuildReadableSourceBackedFallbackIfUseful(toolResults, query, language);
            return !string.IsNullOrWhiteSpace(readableOptionFallback)
                ? readableOptionFallback
                : BuildSourceBackedSafeFallbackAnswer(toolResults, query, language, shouldAvoidRaw: true);
        }

        return BuildSourceBackedExtractiveAnswer(toolResults, query, language);
    }

    private static string? TryBuildDocumentVersionTraceabilityAnswer(ToolResults toolResults, string query, string language)
    {
        if (!LooksLikeDocumentVersionTraceabilityRequest(query))
            return null;

        language = NormalizeLanguageCode(language);
        var hits = SelectDocumentVersionTraceabilityHits(toolResults, query, maxHits: 4).ToList();
        if (hits.Count == 0)
            return null;

        var normalized = NormalizeLexicalLookup(query);
        var asksReplacement = Regex.IsMatch(
            normalized,
            @"\b(?:remplace|remplacer|replacement|replace|replaces|substitue|supersede|supersedes|automatiquement|automatically)\b",
            RegexOptions.CultureInvariant);
        var asksMainOrStatus = Regex.IsMatch(
            normalized,
            @"\b(?:(?:document|doc|fichier|file)\s+(?:principal|main)|\bac\b|corrigendum|correction|berichtigung|amendment|amendement)\b",
            RegexOptions.CultureInvariant);
        var asksLatestDefault = Regex.IsMatch(
            normalized,
            @"\b(?:ne\s+precise\s+pas|sans\s+preciser|sans\s+dire.{0,40}annee|without\s+specifying|without\s+saying.{0,40}year|derniere|latest|newest|recent|recente|current|actuelle|plus\s+recente)\b",
            RegexOptions.CultureInvariant);
        var asksProof = Regex.IsMatch(
            normalized,
            @"\b(?:prouve|prouver|preuve|prove|proves|proof|trace|tracabilite|traceability|utilise\s+bien|uses?\s+the\s+right|bonne\s+version|correct\s+version|version|fichier\s+proche|nearby\s+file)\b",
            RegexOptions.CultureInvariant);
        var latestYear = hits
            .Select(ExtractDocumentVersionYear)
            .Where(static year => year.HasValue)
            .Select(static year => year!.Value)
            .DefaultIfEmpty()
            .Max();

        var header = language switch
        {
            "en" when asksReplacement => "I cannot prove an automatic replacement from the retrieved excerpts. Keep the related documents separate and verify an explicit replacement/adoption clause:",
            "en" when asksMainOrStatus => "Use both levels: the main document for the baseline requirement, and the correction/amendment document for the associated change. The retrieved excerpts do not prove that the correction replaces the full main document:",
            "en" when asksLatestDefault && latestYear > 0 => $"If the user does not specify a year, cite the latest version supported by the selected sources first, and keep older versions as historical context. The latest detected year in these sources is {latestYear}:",
            "en" when asksLatestDefault => "If the user does not specify a year, cite the latest version supported by the selected sources first, and keep older versions as historical context:",
            "en" when asksProof => "To prove the answer uses the intended version, cite the exact file name and page for each source, and keep nearby versions separated:",
            "en" => "Cite these sources separately and keep the evidence limited to the retrieved pages:",
            _ when asksReplacement => "Je ne peux pas prouver un remplacement automatique avec les extraits retrouves. Garde les documents lies separes et verifie une clause explicite de remplacement ou d'adoption :",
            _ when asksMainOrStatus => "Je m'appuie uniquement sur les sources disponibles : il faut garder deux niveaux, le document principal pour l'exigence de base, puis l'AC/correctif/amendement pour la modification associee. Les extraits retrouves ne prouvent pas que le correctif remplace tout le document principal :",
            _ when asksLatestDefault && latestYear > 0 => $"Si l'utilisateur ne precise pas l'annee, je cite d'abord la version la plus recente soutenue par les sources selectionnees, et je garde les anciennes versions comme contexte historique. L'annee la plus recente detectee dans ces sources est {latestYear} :",
            _ when asksLatestDefault => "Si l'utilisateur ne precise pas l'annee, je cite d'abord la version la plus recente soutenue par les sources selectionnees, et je garde les anciennes versions comme contexte historique :",
            _ when asksProof => "Pour prouver que la reponse utilise la bonne version, je cite le nom exact du fichier et la page, en separant les versions ou fichiers proches :",
            _ => "Je cite ces sources separement et je limite la reponse aux pages retrouvees :"
        };

        var sb = new StringBuilder();
        sb.AppendLine(header);
        var duplicateLabels = FindDuplicateDocumentVersionTraceabilityLabels(hits);
        foreach (var hit in hits)
        {
            var docLabel = BuildDocumentVersionTraceabilityHitLabel(hit, duplicateLabels);
            var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 260);
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            if (hit.PageEnd > hit.PageStart)
            {
                sb.Append('-');
                sb.Append(hit.PageEnd);
            }

            if (!string.IsNullOrWhiteSpace(excerpt))
            {
                sb.Append(" : ");
                sb.Append(excerpt);
            }

            sb.AppendLine();
        }

        var caveat = language == "en"
            ? "Conclusion: use these pages as traceability evidence, but do not infer a replacement, status change or full applicability unless the cited page explicitly says so."
            : "Conclusion : utilise ces pages comme preuves de tracabilite, mais n'infere pas un remplacement, un changement de statut ou une applicabilite complete si la page citee ne le dit pas explicitement.";
        sb.Append(caveat);
        return sb.ToString().TrimEnd();
    }

    private static List<ToolMemory.SourceRef> DeriveSourcesFromDocumentVersionTraceabilityHits(ToolResults toolResults, string query, int maxSources = 4)
    {
        var hits = SelectDocumentVersionTraceabilityHits(toolResults, query, maxSources).ToList();
        var duplicateLabels = FindDuplicateDocumentVersionTraceabilityLabels(hits);
        return hits
            .Select(hit =>
            {
                var source = BuildSourceRefFromRagHit(hit);
                source.Label = BuildDocumentVersionTraceabilityHitLabel(hit, duplicateLabels);
                return source;
            })
            .ToList();
    }

    private static HashSet<string> FindDuplicateDocumentVersionTraceabilityLabels(IReadOnlyList<RagHitSummary> hits)
        => hits
            .GroupBy(static hit => string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName, StringComparer.OrdinalIgnoreCase)
            .Where(static group => group.Select(hit => hit.DocPath).Distinct(StringComparer.OrdinalIgnoreCase).Count() > 1)
            .Select(static group => group.Key)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

    private static string BuildDocumentVersionTraceabilityHitLabel(RagHitSummary hit, IReadOnlySet<string> duplicateLabels)
    {
        var label = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
        if (string.IsNullOrWhiteSpace(label) || !duplicateLabels.Contains(label))
            return label;

        var context = GetNearestDisambiguatingPathSegment(hit.DocPath);
        return string.IsNullOrWhiteSpace(context) ? label : $"{label} ({context})";
    }

    private static string GetNearestDisambiguatingPathSegment(string? docPath)
    {
        if (string.IsNullOrWhiteSpace(docPath))
            return string.Empty;

        var segments = docPath
            .Split(new[] { '/', '\\' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        for (var i = segments.Length - 2; i >= 0; i--)
        {
            var segment = segments[i].Trim();
            if (segment.Length == 0)
                continue;

            var normalized = NormalizeLexicalLookup(segment);
            if (Regex.IsMatch(normalized, @"^(?:pdf|documents?|docs?|sources?|files?|fichiers?)$", RegexOptions.CultureInvariant))
                continue;

            return segment;
        }

        return string.Empty;
    }

    private static IReadOnlyList<RagHitSummary> SelectDocumentVersionTraceabilityHits(ToolResults toolResults, string query, int maxHits)
    {
        var normalizedQuery = NormalizeLexicalLookup(query);
        var requestedReferenceKeys = ExtractRequestedDocumentSpecificReferenceKeys(normalizedQuery);
        var allHits = EnumerateRagHitSummaries(toolResults)
            .Where(hit => !LooksLikeNavigationOnlyHit(hit)
                || LooksLikeDocumentStatusHit(hit)
                || TraceabilityHitMatchesRequestedReference(hit, requestedReferenceKeys))
            .Where(hit => !LooksLikeLowSignalContentCandidateHit(hit)
                || LooksLikeDocumentStatusHit(hit)
                || TraceabilityHitMatchesRequestedReference(hit, requestedReferenceKeys))
            .ToList();
        if (allHits.Count == 0 || maxHits <= 0)
            return [];

        var queryStatusTokens = ExtractRequestedDocumentStatusTokens(normalizedQuery).ToHashSet(StringComparer.Ordinal);
        var queryStatusSurfaceTerms = ExtractRequestedDocumentStatusSurfaceTerms(normalizedQuery);
        var asksReplacement = Regex.IsMatch(
            normalizedQuery,
            @"\b(?:remplace|remplacer|replacement|replace|replaces|substitue|supersede|supersedes|automatiquement|automatically)\b",
            RegexOptions.CultureInvariant);
        var asksLatestDefault = Regex.IsMatch(
            normalizedQuery,
            @"\b(?:ne\s+precise\s+pas|sans\s+preciser|sans\s+dire.{0,40}annee|without\s+specifying|without\s+saying.{0,40}year|derniere|latest|newest|recent|recente|plus\s+recente|current|actuelle)\b",
            RegexOptions.CultureInvariant);
        var asksHistoricalVersion = LooksLikeHistoricalDocumentVersionRequest(normalizedQuery);
        var asksVersionContrast = LooksLikeDocumentVersionContrastRequest(normalizedQuery);
        var maxYear = asksLatestDefault
            ? allHits.Select(ExtractDocumentVersionYear).Where(static year => year.HasValue).DefaultIfEmpty().Max()
            : null;
        var explicitYears = ExtractDocumentVersionYears(normalizedQuery);

        var ranked = allHits
            .Select((hit, index) => new DocumentTraceabilityRankedHit(
                hit,
                index,
                GetDocumentStatusToken(hit),
                ExtractDocumentVersionYear(hit),
                Score:
                    ComputeRagHitLexicalRelevance(query, $"{hit.DocName} {hit.DocPath}") * 5
                    + ComputeRagHitLexicalRelevance(query, $"{hit.SectionTitle} {hit.HeadingPath}") * 2
                    + ComputeRagHitLexicalRelevance(query, GetRagHitLookupText(hit))
                    + ComputeBackendSelectionPriority(hit)
                    + (hit.RetrievalQueryIndex == 0 ? 12 : 0)
                    + ((hit.RetrievalHitRank is >= 0 and <= 1) ? 8 : 0)
                    + (LooksLikeDocumentStatusHit(hit) ? 8 : 0)
                    + (LooksLikeMainDocumentHit(hit) ? 5 : 0)
                    + hit.Score))
            .Select(item => item with
            {
                Score = item.Score
                        + (!string.IsNullOrWhiteSpace(item.Status) && queryStatusTokens.Contains(item.Status!) ? 45 : 0)
                        + (DocumentStatusSurfaceMatches(item.Hit, queryStatusSurfaceTerms) ? 80 : 0)
                        + (maxYear.HasValue && item.Year == maxYear ? 24 : 0)
            })
            .OrderByDescending(static item => item.Score)
            .ThenBy(static item => item.Index)
            .ToList();
        if (asksVersionContrast && explicitYears.Length == 0 && queryStatusTokens.Count == 0 && !asksReplacement)
        {
            ranked = KeepContrastingTraceabilityVersionsByReference(ranked)
                .ToList();
        }
        else if (asksHistoricalVersion && explicitYears.Length == 0 && queryStatusTokens.Count == 0 && !asksReplacement)
        {
            ranked = KeepHistoricalTraceabilityVersionsByReference(ranked)
                .ToList();
        }
        else if (explicitYears.Length > 0 && queryStatusTokens.Count == 0 && !asksReplacement)
        {
            var explicitYearHits = ranked
                .Where(item => item.Year.HasValue && explicitYears.Contains(item.Year.Value))
                .ToList();
            if (explicitYearHits.Count > 0)
                ranked = explicitYearHits;
        }
        else if (queryStatusTokens.Count == 0 && !asksReplacement)
        {
            ranked = KeepLatestTraceabilityVersionsByReference(ranked)
                .ToList();
        }

        var selected = new List<RagHitSummary>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        void Add(RagHitSummary hit)
        {
            if (selected.Count >= maxHits)
                return;

            var key = $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}";
            if (seen.Add(key))
                selected.Add(hit);
        }

        var wantsMainAndStatus = Regex.IsMatch(
            normalizedQuery,
            @"\b(?:(?:document|doc|fichier|file)\s+(?:principal|main)|\bac\b|corrigendum|correction|berichtigung|amendment|amendement)\b",
            RegexOptions.CultureInvariant);
        if (wantsMainAndStatus)
        {
            var statusHit = ranked.FirstOrDefault(static item => LooksLikeDocumentStatusHit(item.Hit));
            if (statusHit is not null)
                Add(statusHit.Hit);

            var mainHit = ranked.FirstOrDefault(static item => LooksLikeMainDocumentHit(item.Hit));
            if (mainHit is not null)
                Add(mainHit.Hit);

            if (selected.Count >= 2)
                return selected;
        }

        if (asksLatestDefault && maxYear.HasValue)
        {
            var latestHit = ranked.FirstOrDefault(item => item.Year == maxYear.Value);
            if (latestHit is not null)
                Add(latestHit.Hit);
        }

        if (asksVersionContrast)
        {
            var contrastFamily =
                selected
                    .Select(GetDocumentReferenceFamilyKey)
                    .FirstOrDefault(static family => !string.IsNullOrWhiteSpace(family))
                ?? ranked
                    .Select(item => GetDocumentReferenceFamilyKey(item.Hit))
                    .FirstOrDefault(static family => !string.IsNullOrWhiteSpace(family));

            static bool SameFamily(string? expectedFamily, RagHitSummary hit)
            {
                if (string.IsNullOrWhiteSpace(expectedFamily))
                    return true;

                var family = GetDocumentReferenceFamilyKey(hit);
                return string.IsNullOrWhiteSpace(family)
                       || string.Equals(family, expectedFamily, StringComparison.Ordinal);
            }

            var historicalHit = ranked.FirstOrDefault(item =>
                SameFamily(contrastFamily, item.Hit)
                && LooksLikeHistoricalDocumentVersionHit(item.Hit))
                ?? ranked.FirstOrDefault(item => LooksLikeHistoricalDocumentVersionHit(item.Hit));
            if (historicalHit is not null)
                Add(historicalHit.Hit);

            var historicalFamily = historicalHit is null
                ? string.Empty
                : GetDocumentReferenceFamilyKey(historicalHit.Hit);
            var currentHit = string.IsNullOrWhiteSpace(historicalFamily)
                ? null
                : ranked.FirstOrDefault(item =>
                    SameFamily(historicalFamily, item.Hit)
                    && !LooksLikeHistoricalDocumentVersionHit(item.Hit));
            if (currentHit is null && historicalHit is not null)
            {
                currentHit = ranked
                    .Where(static item => !LooksLikeHistoricalDocumentVersionHit(item.Hit))
                    .Select(item => new
                    {
                        Item = item,
                        Overlap = ComputeDocumentVersionReferenceOverlapScore(historicalHit.Hit, item.Hit)
                    })
                    .Where(static item => item.Overlap > 0)
                    .OrderByDescending(static item => item.Overlap)
                    .ThenByDescending(static item => item.Item.Score)
                    .Select(static item => item.Item)
                    .FirstOrDefault();
            }

            currentHit ??= ranked.FirstOrDefault(item =>
                SameFamily(contrastFamily, item.Hit)
                && !LooksLikeHistoricalDocumentVersionHit(item.Hit));
            currentHit ??= ranked.FirstOrDefault(item => !LooksLikeHistoricalDocumentVersionHit(item.Hit));
            if (currentHit is not null)
                Add(currentHit.Hit);
        }

        foreach (var requestedReferenceKey in requestedReferenceKeys)
        {
            var referenceHit = ranked.FirstOrDefault(item =>
                string.Equals(GetDocumentSpecificReferenceKey(item.Hit), requestedReferenceKey, StringComparison.Ordinal));
            if (referenceHit is not null)
                Add(referenceHit.Hit);
        }

        if (queryStatusTokens.Count > 0)
        {
            foreach (var status in queryStatusTokens)
            {
                var statusHit = ranked.FirstOrDefault(item => string.Equals(item.Status, status, StringComparison.Ordinal));
                if (statusHit is not null)
                    Add(statusHit.Hit);
            }
        }

        if (explicitYears.Length > 0)
        {
            var yearsToRepresent = asksLatestDefault
                ? explicitYears.OrderByDescending(static year => year).ToArray()
                : explicitYears;
            foreach (var year in yearsToRepresent)
            {
                var yearHit = ranked.FirstOrDefault(item => item.Year == year);
                if (yearHit is not null)
                    Add(yearHit.Hit);
            }

            if (asksReplacement && selected.Count >= 2)
                return selected;
        }

        var prefersHistoricalSurface = asksHistoricalVersion
            && explicitYears.Length == 0
            && queryStatusTokens.Count == 0
            && !asksReplacement;
        if (prefersHistoricalSurface)
        {
            foreach (var item in ranked.Where(static item => LooksLikeHistoricalDocumentVersionHit(item.Hit)))
                Add(item.Hit);

            if (selected.Count >= maxHits)
                return selected;
        }

        var dominantFamily = selected
            .Select(GetDocumentReferenceFamilyKey)
            .FirstOrDefault(static family => !string.IsNullOrWhiteSpace(family))
            ?? GetDocumentReferenceFamilyKey(ranked[0].Hit);
        foreach (var item in ranked)
        {
            if (!string.IsNullOrWhiteSpace(dominantFamily))
            {
                var family = GetDocumentReferenceFamilyKey(item.Hit);
                if (!string.IsNullOrWhiteSpace(family)
                    && !string.Equals(family, dominantFamily, StringComparison.Ordinal))
                {
                    continue;
                }
            }

            Add(item.Hit);
        }

        return selected;
    }

    private static bool LooksLikeHistoricalDocumentVersionRequest(string normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            return false;
        if (HistoricalDocumentVersionSurfaceIsNegated(normalizedQuery))
            return false;

        if (Regex.IsMatch(
                normalizedQuery,
                @"\b(?:compare|comparer|comparaison|vs|versus|difference\s+entre|difference\s+between|differences\s+between)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        return Regex.IsMatch(
            normalizedQuery,
            @"\b(?:ancien(?:ne)?s?\s+versions?|ancien(?:ne)?\s+edition|version\s+(?:precedente|anterieure)|old\s+version|older\s+version|previous\s+version|prior\s+version|archived\s+(?:version|document)|archives?|legacy\s+version|obsolete\s+version|historical\s+version)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeDocumentVersionContrastRequest(string normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery) || HistoricalDocumentVersionSurfaceIsNegated(normalizedQuery))
            return false;

        var hasHistorical = ContainsHistoricalDocumentVersionSurface(normalizedQuery);
        if (!hasHistorical)
            return false;

        var hasCurrent = ContainsCurrentDocumentVersionSurface(normalizedQuery);
        var hasContrast = Regex.IsMatch(
            normalizedQuery,
            @"\b(?:compare|comparer|comparaison|vs|versus|difference|differences|distinguer|distingue|distinguish|equivalence|equivalent|equivaut|courante|current|latest|actuelle|nouvelle|newest)\b",
            RegexOptions.CultureInvariant);

        return hasCurrent || hasContrast;
    }

    private static bool LooksLikeHistoricalDocumentVersionHit(RagHitSummary hit)
    {
        var doc = NormalizeLexicalLookup($"{hit.DocName} {hit.DocPath}");
        if (string.IsNullOrWhiteSpace(doc))
            return false;

        return Regex.IsMatch(
            doc,
            @"\b(?:old\s+versions?|old_versions?|older|previous|prior|archived?|archives?|historical|legacy|obsolete|ancienne?s?|ancien?s?|precedent(?:e)?s?|anterieur(?:e)?s?)\b",
            RegexOptions.CultureInvariant);
    }

    private static int ComputeDocumentVersionReferenceOverlapScore(RagHitSummary anchor, RagHitSummary candidate)
    {
        var anchorTerms = ExtractDocumentVersionReferenceTerms(anchor);
        if (anchorTerms.Count == 0)
            return 0;

        var score = 0;
        var anchorLead = GetDocumentVersionLeadingReferenceToken(anchor);
        var candidateLead = GetDocumentVersionLeadingReferenceToken(candidate);
        if (!string.IsNullOrWhiteSpace(anchorLead)
            && string.Equals(anchorLead, candidateLead, StringComparison.Ordinal))
        {
            score += 12;
        }

        foreach (var term in ExtractDocumentVersionReferenceTerms(candidate))
        {
            if (!anchorTerms.Contains(term))
                continue;

            score += Regex.IsMatch(term, @"\d", RegexOptions.CultureInvariant)
                ? 3
                : term.Length <= 3 ? 2 : 1;
        }

        return score;
    }

    private static string GetDocumentVersionLeadingReferenceToken(RagHitSummary hit)
    {
        var normalized = NormalizeLexicalLookup($"{hit.DocName} {Path.GetFileNameWithoutExtension(hit.DocPath)}");
        foreach (Match match in Regex.Matches(normalized, @"[a-z0-9]{2,}", RegexOptions.CultureInvariant))
        {
            var term = match.Value;
            if (Regex.IsMatch(
                    term,
                    @"^(?:old|older|version|versions|current|latest|newest|recent|archive|archives|archived|historical|legacy|obsolete|ancienne|anciennes|ancien|anciens|nouvelle|nouvelles|actuelle|actuelles|courante|courantes|document|documents|pdf|file|files)$",
                    RegexOptions.CultureInvariant))
            {
                continue;
            }

            return term;
        }

        return string.Empty;
    }

    private static HashSet<string> ExtractDocumentVersionReferenceTerms(RagHitSummary hit)
    {
        var normalized = NormalizeLexicalLookup($"{hit.DocName} {Path.GetFileNameWithoutExtension(hit.DocPath)}");
        var terms = Regex.Matches(normalized, @"[a-z0-9]{2,}", RegexOptions.CultureInvariant)
            .Select(static match => match.Value)
            .Where(static term => !Regex.IsMatch(
                term,
                @"^(?:old|older|version|versions|current|latest|newest|recent|archive|archives|archived|historical|legacy|obsolete|ancienne|anciennes|ancien|anciens|nouvelle|nouvelles|actuelle|actuelles|courante|courantes|document|documents|pdf|file|files|data|sheet|sheets|safety|technical|technique)$",
                RegexOptions.CultureInvariant))
            .ToHashSet(StringComparer.Ordinal);

        return terms;
    }

    private static bool LooksLikeDocumentVersionTraceabilityRequest(string query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var hasDocumentSurface = Regex.IsMatch(
            normalized,
            @"\b(?:document|documents|doc|fichier|file|pdf|source|sources|principal|main|policy|policies|politique|standard|standards|norme|normes|certificate|certificates|certificat|certificats|iso|iec|en)\b",
            RegexOptions.CultureInvariant);
        var hasVersionOrStatus = Regex.IsMatch(
            normalized,
            @"\b(?:version|versions|edition|editions|annee|annees|year|years|status|statut|ac|a\d+|pra\d+|corrigendum|correction|berichtigung|amendment|amendement|remplace|replace|replacement|latest|derniere|recente|current|actuelle|ancienne|anciennes|older|old|precedente|previous)\b",
            RegexOptions.CultureInvariant);
        var hasDocumentStatusSurface = Regex.IsMatch(
            normalized,
            @"\b(?:ac|a\d+|pra\d+|corrigendum|correction|correctif|rectificatif|berichtigung|erratum|errata|amendment|amendement)\b",
            RegexOptions.CultureInvariant);
        var hasTraceabilityIntent = Regex.IsMatch(
            normalized,
            @"\b(?:separement|separately|prouve|prouver|preuve|prove|proves|proof|trace|tracabilite|traceability|utilise\s+bien|bonne\s+version|correct\s+version|fichier\s+proche|nearby\s+file|regarder|look|appliquer|apply|remplace|replace|replacement|contient|contenir|contenu|complete|complet|tout|toute|full|whole|contains|content|verifier|verify|check|issue|ancienne|anciennes|older|old|precedente|previous|signaler|signal|mentionne|mentionner|existe|existence|exists?|annee|annees|year|years|vient|viennent|comes?|dire|specifie|specifies?|precise|preciser)\b",
            RegexOptions.CultureInvariant);
        var hasStandardReference = MatchDocumentStandardReference(normalized).Success;

        return (hasVersionOrStatus || hasStandardReference)
            && hasTraceabilityIntent
            && (hasDocumentSurface || hasStandardReference || hasDocumentStatusSurface || TryExtractPdfFileNameRequestedTitle(query) is not null);
    }

    private static string BuildDocumentVersionTraceabilityExactSearchQuery(string exactTitle, string query)
    {
        var normalizedTitle = NormalizeLexicalLookup(exactTitle);
        var compact = new List<string>();
        var reference = MatchDocumentStandardReference(normalizedTitle);
        if (reference.Success)
        {
            var referenceKey = BuildDocumentSpecificReferenceKey(reference);
            if (!string.IsNullOrWhiteSpace(referenceKey))
                compact.Add(referenceKey);
        }

        foreach (var year in ExtractDocumentVersionYears(exactTitle).OrderByDescending(static year => year).Take(2))
            compact.Add(year.ToString(CultureInfo.InvariantCulture));

        foreach (var status in ExtractRequestedDocumentStatusSurfaceTerms(NormalizeLexicalLookup($"{exactTitle} {query}")).Take(2))
            compact.Add(status);

        AddDocumentVersionTraceabilitySurfaceTerms(compact, NormalizeLexicalLookup($"{exactTitle} {query}"));

        var parts = new List<string> { exactTitle };
        parts.AddRange(compact);
        return CollapseWhitespace(string.Join(' ', parts.Distinct(StringComparer.OrdinalIgnoreCase)));
    }

    private static string BuildDocumentVersionTraceabilitySearchQuery(string query)
    {
        var exactTitle = TryExtractPdfFileNameRequestedTitle(query);
        if (!string.IsNullOrWhiteSpace(exactTitle))
            return BuildDocumentVersionTraceabilityExactSearchQuery(exactTitle!, query);

        var normalized = NormalizeLexicalLookup(query);
        var compact = new List<string>();
        var reference = MatchDocumentStandardReference(normalized);
        if (reference.Success)
        {
            var referenceKey = BuildDocumentSpecificReferenceKey(reference);
            if (!string.IsNullOrWhiteSpace(referenceKey))
                compact.Add(referenceKey);
        }

        foreach (var year in ExtractDocumentVersionYears(query).OrderByDescending(static year => year).Take(2))
            compact.Add(year.ToString(CultureInfo.InvariantCulture));

        foreach (var status in ExtractRequestedDocumentStatusSurfaceTerms(normalized).Take(2))
            compact.Add(status);

        AddDocumentVersionTraceabilitySurfaceTerms(compact, normalized);

        if (compact.Count > 0)
            return CollapseWhitespace(string.Join(' ', compact.Distinct(StringComparer.OrdinalIgnoreCase)));

        return string.Empty;
    }

    private static string[] BuildDocumentVersionTraceabilitySearchQueries(string query)
    {
        var queries = new List<string>();

        void Add(string? value)
        {
            var candidate = CollapseWhitespace(value ?? string.Empty);
            if (candidate.Length == 0)
                return;

            if (!queries.Any(existing => string.Equals(existing, candidate, StringComparison.OrdinalIgnoreCase)))
                queries.Add(candidate);
        }

        Add(BuildDocumentVersionTraceabilitySearchQuery(query));
        Add(query);
        Add(NormalizeRagQueryForRetrieval(query));

        var quotedOrRequestedTitle = TryExtractRequestedItemTitle(query);
        if (!string.IsNullOrWhiteSpace(quotedOrRequestedTitle))
            Add(BuildDocumentVersionTraceabilityExactSearchQuery(quotedOrRequestedTitle!, query));

        return queries.Take(4).ToArray();
    }

    private static void AddDocumentVersionTraceabilitySurfaceTerms(List<string> terms, string normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery) || HistoricalDocumentVersionSurfaceIsNegated(normalizedQuery))
            return;

        var hasHistorical = ContainsHistoricalDocumentVersionSurface(normalizedQuery);
        var hasCurrent = ContainsCurrentDocumentVersionSurface(normalizedQuery);
        var hasContrast = LooksLikeDocumentVersionContrastRequest(normalizedQuery);

        if (hasHistorical)
        {
            terms.Add("ancienne version");
            terms.Add("old versions");
            terms.Add("old version");
        }

        if (hasCurrent || hasContrast)
        {
            terms.Add("version courante");
            terms.Add("current versions");
            terms.Add("current version");
        }

        if (hasContrast)
        {
            terms.Add("nouvelle version");
            terms.Add("latest version");
        }
    }

    private static IReadOnlyList<string> ExtractRequestedDocumentStatusTokens(string normalizedQuery)
    {
        var tokens = new List<string>();
        if (Regex.IsMatch(normalizedQuery, @"\bpra\d*\b", RegexOptions.CultureInvariant))
            tokens.Add("draft_amendment");
        if (Regex.IsMatch(normalizedQuery, @"\ba\d+\b", RegexOptions.CultureInvariant))
            tokens.Add("amendment");
        if (Regex.IsMatch(normalizedQuery, @"\bac\b|corrigendum|correction|berichtigung|errata", RegexOptions.CultureInvariant))
            tokens.Add("correction");
        return tokens.Distinct(StringComparer.Ordinal).ToArray();
    }

    private static IReadOnlyList<string> ExtractRequestedDocumentStatusSurfaceTerms(string normalizedQuery)
    {
        var terms = new List<string>();
        foreach (Match match in Regex.Matches(
                     normalizedQuery ?? string.Empty,
                     @"\b(?:pra\d+|a\d+|ac|corrigendum|correction|correctif|rectificatif|berichtigung|erratum|errata|amendment|amendement)\b",
                     RegexOptions.CultureInvariant))
        {
            terms.Add(match.Value);
        }

        return terms
            .Where(static term => !string.IsNullOrWhiteSpace(term))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
    }

    private static bool DocumentStatusSurfaceMatches(RagHitSummary hit, IReadOnlyList<string> requestedSurfaceTerms)
    {
        if (requestedSurfaceTerms.Count == 0)
            return false;

        var doc = NormalizeLexicalLookup($"{hit.DocName} {hit.DocPath}");
        if (string.IsNullOrWhiteSpace(doc))
            return false;

        foreach (var term in requestedSurfaceTerms)
        {
            if (term.Length <= 2)
            {
                if (Regex.IsMatch(doc, $@"\b{Regex.Escape(term)}\b", RegexOptions.CultureInvariant))
                    return true;
            }
            else if (doc.Contains(term, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }

    private static bool LooksLikeDocumentStatusHit(RagHitSummary hit)
        => !string.IsNullOrWhiteSpace(GetDocumentStatusToken(hit));

    private static bool LooksLikeMainDocumentHit(RagHitSummary hit)
    {
        var doc = NormalizeLexicalLookup($"{hit.DocName} {hit.DocPath}");
        if (string.IsNullOrWhiteSpace(doc))
            return false;

        return !Regex.IsMatch(
            doc,
            @"\b(?:ac|a\d+|pra\d+|corrigendum|correction|berichtigung|errata|amendment|amendement)\b",
            RegexOptions.CultureInvariant);
    }

    private static string? GetDocumentStatusToken(RagHitSummary hit)
    {
        var doc = NormalizeLexicalLookup($"{hit.DocName} {hit.DocPath}");
        if (Regex.IsMatch(doc, @"\bpra\d*\b", RegexOptions.CultureInvariant))
            return "draft_amendment";
        if (Regex.IsMatch(doc, @"\bac\b|corrigendum|correction|berichtigung|errata", RegexOptions.CultureInvariant))
            return "correction";
        if (Regex.IsMatch(doc, @"\ba\d+\b|amendment|amendement", RegexOptions.CultureInvariant))
            return "amendment";
        return null;
    }

    private static int? ExtractDocumentVersionYear(RagHitSummary hit)
    {
        var text = $"{hit.DocName} {hit.DocPath}";
        var years = ExtractDocumentVersionYears(text);
        return years.Length == 0 ? null : years.Max();
    }

    private static int[] ExtractDocumentVersionYears(string text)
        => Regex.Matches(text ?? string.Empty, @"(?<!\d)(?:19|20)\d{2}(?!\d)", RegexOptions.CultureInvariant)
            .Select(match => int.TryParse(match.Value, NumberStyles.None, CultureInfo.InvariantCulture, out var year) ? year : (int?)null)
            .Where(static year => year.HasValue)
            .Select(static year => year!.Value)
            .Distinct()
            .ToArray();

    private sealed record DocumentTraceabilityRankedHit(RagHitSummary Hit, int Index, string? Status, int? Year, double Score);

    private static IReadOnlyList<DocumentTraceabilityRankedHit> KeepLatestTraceabilityVersionsByReference(IReadOnlyList<DocumentTraceabilityRankedHit> ranked)
    {
        var latestByReference = ranked
            .GroupBy(item => GetDocumentSpecificReferenceKey(item.Hit), StringComparer.Ordinal)
            .Where(static group => !string.IsNullOrWhiteSpace(group.Key))
            .Select(static group => new
            {
                Reference = group.Key,
                LatestYear = group.Select(static item => item.Year).Where(static year => year.HasValue).DefaultIfEmpty().Max()
            })
            .Where(static item => item.LatestYear.HasValue)
            .ToDictionary(static item => item.Reference, static item => item.LatestYear!.Value, StringComparer.Ordinal);

        if (latestByReference.Count == 0)
        {
            return DropHistoricalTraceabilityVersionsWhenCurrentExists(ranked);
        }

        var byYear = ranked
            .Where(item =>
            {
                var reference = GetDocumentSpecificReferenceKey(item.Hit);
                if (string.IsNullOrWhiteSpace(reference)
                    || !latestByReference.TryGetValue(reference, out var latestYear))
                {
                    return true;
                }

                return !item.Year.HasValue || item.Year.Value == latestYear;
            })
            .ToList();
        return DropHistoricalTraceabilityVersionsWhenCurrentExists(byYear);
    }

    private static IReadOnlyList<DocumentTraceabilityRankedHit> KeepHistoricalTraceabilityVersionsByReference(IReadOnlyList<DocumentTraceabilityRankedHit> ranked)
    {
        var byArchiveSurface = KeepArchiveSurfaceTraceabilityVersionsByReference(ranked);
        if (byArchiveSurface.Count < ranked.Count)
            return byArchiveSurface;

        var oldestByReference = ranked
            .GroupBy(item => GetDocumentSpecificReferenceKey(item.Hit), StringComparer.Ordinal)
            .Where(static group => !string.IsNullOrWhiteSpace(group.Key))
            .Select(static group => new
            {
                Reference = group.Key,
                OldestYear = group.Select(static item => item.Year).Where(static year => year.HasValue).DefaultIfEmpty().Min()
            })
            .Where(static item => item.OldestYear.HasValue)
            .ToDictionary(static item => item.Reference, static item => item.OldestYear!.Value, StringComparer.Ordinal);

        if (oldestByReference.Count == 0)
            return ranked;

        return ranked
            .Where(item =>
            {
                var reference = GetDocumentSpecificReferenceKey(item.Hit);
                if (string.IsNullOrWhiteSpace(reference)
                    || !oldestByReference.TryGetValue(reference, out var oldestYear))
                {
                    return true;
                }

                return !item.Year.HasValue || item.Year.Value == oldestYear;
            })
            .ToList();
    }

    private static IReadOnlyList<DocumentTraceabilityRankedHit> DropHistoricalTraceabilityVersionsWhenCurrentExists(IReadOnlyList<DocumentTraceabilityRankedHit> ranked)
    {
        var referencesWithCurrent = ranked
            .GroupBy(item => GetDocumentSpecificReferenceKey(item.Hit), StringComparer.Ordinal)
            .Where(static group => !string.IsNullOrWhiteSpace(group.Key))
            .Where(static group => group.Any(item => LooksLikeHistoricalDocumentVersionHit(item.Hit))
                                   && group.Any(item => !LooksLikeHistoricalDocumentVersionHit(item.Hit)))
            .Select(static group => group.Key!)
            .ToHashSet(StringComparer.Ordinal);
        if (referencesWithCurrent.Count == 0)
            return ranked;

        return ranked
            .Where(item =>
            {
                var reference = GetDocumentSpecificReferenceKey(item.Hit);
                return string.IsNullOrWhiteSpace(reference)
                       || !referencesWithCurrent.Contains(reference)
                       || !LooksLikeHistoricalDocumentVersionHit(item.Hit);
            })
            .ToList();
    }

    private static IReadOnlyList<DocumentTraceabilityRankedHit> KeepArchiveSurfaceTraceabilityVersionsByReference(IReadOnlyList<DocumentTraceabilityRankedHit> ranked)
    {
        var referencesWithArchive = ranked
            .GroupBy(item => GetDocumentSpecificReferenceKey(item.Hit), StringComparer.Ordinal)
            .Where(static group => !string.IsNullOrWhiteSpace(group.Key))
            .Where(static group => group.Any(item => LooksLikeHistoricalDocumentVersionHit(item.Hit)))
            .Select(static group => group.Key!)
            .ToHashSet(StringComparer.Ordinal);
        if (referencesWithArchive.Count == 0)
            return ranked;

        return ranked
            .Where(item =>
            {
                var reference = GetDocumentSpecificReferenceKey(item.Hit);
                return string.IsNullOrWhiteSpace(reference)
                       || !referencesWithArchive.Contains(reference)
                       || LooksLikeHistoricalDocumentVersionHit(item.Hit);
            })
            .ToList();
    }

    private static IReadOnlyList<DocumentTraceabilityRankedHit> KeepContrastingTraceabilityVersionsByReference(IReadOnlyList<DocumentTraceabilityRankedHit> ranked)
    {
        var result = new List<DocumentTraceabilityRankedHit>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        void Add(DocumentTraceabilityRankedHit item)
        {
            var key = $"{item.Hit.DocPath}|{item.Hit.PageStart}|{item.Hit.PageEnd}";
            if (seen.Add(key))
                result.Add(item);
        }

        foreach (var group in ranked
                     .GroupBy(item => GetDocumentSpecificReferenceKey(item.Hit), StringComparer.Ordinal)
                     .Where(static group => !string.IsNullOrWhiteSpace(group.Key)))
        {
            var historical = group.FirstOrDefault(item => LooksLikeHistoricalDocumentVersionHit(item.Hit));
            var current = group.FirstOrDefault(item => !LooksLikeHistoricalDocumentVersionHit(item.Hit));
            if (historical is null || current is null)
                continue;

            Add(current);
            Add(historical);
        }

        foreach (var item in ranked)
            Add(item);

        return result;
    }

    private static string GetDocumentReferenceFamilyKey(RagHitSummary hit)
    {
        var doc = NormalizeLexicalLookup($"{hit.DocName} {Path.GetFileNameWithoutExtension(hit.DocPath)}");
        if (string.IsNullOrWhiteSpace(doc))
            return string.Empty;

        var standard = MatchDocumentStandardReference(doc);
        if (standard.Success)
            return BuildDocumentReferenceFamilyKey(standard);

        doc = Regex.Replace(
            doc,
            @"\b(?:19|20)\d{2}\b|\b(?:ac|a\d+|pra\d+|corrigendum|correction|berichtigung|errata|amendment|amendement|main|principal|requirements?|document|doc|file|pdf)\b",
            " ",
            RegexOptions.CultureInvariant);
        var tokens = ExtractQuerySignalTerms(doc)
            .Where(static term => term.Length >= 3)
            .Where(static term => !Regex.IsMatch(term, @"^(?:safety|machinery|part|parts|general|principles|design|standard|norme|normes)$", RegexOptions.CultureInvariant))
            .Take(4)
            .ToArray();

        return tokens.Length == 0 ? string.Empty : string.Join(' ', tokens);
    }

    private static string GetDocumentSpecificReferenceKey(RagHitSummary hit)
    {
        var doc = NormalizeLexicalLookup($"{hit.DocName} {Path.GetFileNameWithoutExtension(hit.DocPath)}");
        if (string.IsNullOrWhiteSpace(doc))
            return string.Empty;

        var standard = MatchDocumentStandardReference(doc);
        if (standard.Success)
            return BuildDocumentSpecificReferenceKey(standard);

        return GetDocumentReferenceFamilyKey(hit);
    }

    private static IReadOnlyList<string> ExtractRequestedDocumentSpecificReferenceKeys(string normalizedQuery)
    {
        var keys = new List<string>();
        foreach (Match match in Regex.Matches(
                     normalizedQuery ?? string.Empty,
                     DocumentStandardReferencePattern,
                     RegexOptions.CultureInvariant))
        {
            var family = BuildDocumentReferenceFamilyKey(match);
            var part1 = match.Groups["part1"].Success ? match.Groups["part1"].Value : string.Empty;
            var part2 = match.Groups["part2"].Success ? match.Groups["part2"].Value : string.Empty;
            if (!string.IsNullOrWhiteSpace(part1) && !string.IsNullOrWhiteSpace(part2))
            {
                keys.Add($"{family} {part1}");
                keys.Add($"{family} {part2}");
            }
            else if (!string.IsNullOrWhiteSpace(part1))
            {
                keys.Add($"{family} {part1}");
            }
            else
            {
                keys.Add(family);
            }
        }

        return keys.Distinct(StringComparer.Ordinal).ToArray();
    }

    private const string DocumentStandardReferencePattern =
        @"\b(?<prefix>fd\s+cen\s+tr|cen\s+tr|iso|en|iec|din|sn|nf)\s+(?<number>\d{2,})(?:(?:[\s_\-./]+)(?<part1>\d{1,3}))?(?:(?:\s*/\s*|[\s_]+)(?<part2>\d{1,3}))?\b";

    private static Match MatchDocumentStandardReference(string normalizedText)
        => Regex.Match(normalizedText ?? string.Empty, DocumentStandardReferencePattern, RegexOptions.CultureInvariant);

    private static string BuildDocumentReferenceFamilyKey(Match match)
    {
        var prefix = CollapseWhitespace(match.Groups["prefix"].Value);
        var number = match.Groups["number"].Value;
        return string.IsNullOrWhiteSpace(prefix) || string.IsNullOrWhiteSpace(number)
            ? string.Empty
            : $"{prefix} {number}";
    }

    private static string BuildDocumentSpecificReferenceKey(Match match)
    {
        var family = BuildDocumentReferenceFamilyKey(match);
        if (string.IsNullOrWhiteSpace(family))
            return string.Empty;

        var part = match.Groups["part1"].Success ? match.Groups["part1"].Value : string.Empty;
        return string.IsNullOrWhiteSpace(part)
            ? family
            : $"{family} {part}";
    }

    private static bool TraceabilityHitMatchesRequestedReference(RagHitSummary hit, IReadOnlyList<string> requestedReferenceKeys)
    {
        if (requestedReferenceKeys.Count == 0)
            return false;

        var hitKey = GetDocumentSpecificReferenceKey(hit);
        if (string.IsNullOrWhiteSpace(hitKey))
            return false;

        return requestedReferenceKeys.Any(key => string.Equals(key, hitKey, StringComparison.Ordinal));
    }

    private static bool ShouldPreferPartialEvidenceFallbackOverOptions(ToolResults toolResults, string query)
    {
        if (!LooksLikeSourceBackedOptionRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query))
        {
            return false;
        }

        var normalized = NormalizeLexicalLookup(query);
        if (!Regex.IsMatch(
                normalized,
                @"\b(?:idee|idees|ideas?|technique|methode|method|approche|approach|organisation|organization|strategie|strategy|planning|parallele|parallel)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        var candidates = SelectSourceBackedOptionAnswerCandidates(toolResults, query, minItems: 1).Items.ToList();
        if (candidates.Count == 0)
            return false;

        var titleAnchorTerms = ExtractQuerySignalTerms(normalized)
            .Where(static term => term.Length >= 5)
            .Where(static term => !SourceBackedOptionConstraintTerms.Contains(term))
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(6)
            .ToArray();
        if (titleAnchorTerms.Length == 0)
            return false;

        var anyTitleAnchor = candidates.Any(candidate =>
        {
            var title = NormalizeLexicalLookup(
                $"{candidate.Title} {candidate.Hit.SectionTitle} {candidate.Hit.HeadingPath} {string.Join(' ', candidate.Hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>())}");
            return titleAnchorTerms.Any(term => title.Contains(term, StringComparison.Ordinal));
        });
        if (anyTitleAnchor)
            return false;

        return EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Any(hit => ComputeRagHitLexicalRelevance(query, GetRagHitLookupText(hit)) >= 4);
    }

    private static bool ShouldUseFallbackForBroadMethodOptionRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeWeeklyPlanningRequest(query))
        {
            return false;
        }

        return Regex.IsMatch(
            normalized,
            @"\b(?:idee|idees|ideas?|technique|methode|method|approche|approach|organisation|organization|strategie|strategy|planning|parallele|parallel)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeOverPromotedSourceBackedOptionAnswer(string? answer)
    {
        var normalized = NormalizeLexicalLookup(answer);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(normalized, @"\b(?:option|opcion|opcao|opzione)\s+1\b", RegexOptions.CultureInvariant)
            || Regex.IsMatch(normalized, @"\b(?:voici|here\s+are|aqui|ecco).{0,40}\b(?:options?|suggestions?|pistes)\b", RegexOptions.CultureInvariant);
    }

    private static bool ShouldReplaceOverPromotedSourceBackedOptionAnswer(
        string? answer,
        ToolResults toolResults,
        string? query)
    {
        if (!LooksLikeOverPromotedSourceBackedOptionAnswer(answer))
            return false;

        if (LooksLikeUsefulPartialSourceBackedAnswer(answer))
            return false;

        var normalizedAnswer = NormalizeLexicalLookup(answer);
        if (string.IsNullOrWhiteSpace(normalizedAnswer))
            return true;

        var anchoredHitCount = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .Take(8)
            .Count(hit => RagHitIdentityAppearsInAnswer(hit, normalizedAnswer));

        return anchoredHitCount == 0;
    }

    private static bool RagHitIdentityAppearsInAnswer(RagHitSummary hit, string normalizedAnswer)
    {
        var identities = new[]
        {
            hit.DocName,
            Path.GetFileName(hit.DocPath),
            Path.GetFileNameWithoutExtension(hit.DocName),
            Path.GetFileNameWithoutExtension(hit.DocPath)
        };

        return identities
            .Select(NormalizeLexicalLookup)
            .Where(static identity => identity.Length >= 4)
            .Distinct(StringComparer.Ordinal)
            .Any(identity => normalizedAnswer.Contains(identity, StringComparison.Ordinal));
    }

    private static bool LooksLikeUnsupportedBroadOptionComposition(string? query, string? answer)
    {
        var normalizedQuery = NormalizeLexicalLookup(query);
        var normalizedAnswer = NormalizeLexicalLookup(answer);
        if (string.IsNullOrWhiteSpace(normalizedQuery) || string.IsNullOrWhiteSpace(normalizedAnswer))
            return false;

        var broadComposition = Regex.IsMatch(
            normalizedQuery,
            @"\b(?:idee|idees|ideas?|technique|methode|method|approche|approach|organisation|organization|strategie|strategy|planning|parallele|parallel|selection|composition)\b",
            RegexOptions.CultureInvariant);
        if (!broadComposition || LooksLikeSourceBackedPairingRecommendationRequest(query))
            return false;

        return Regex.IsMatch(
            normalizedAnswer,
            @"\b(?:pas\s+trouve\s+de\s+passage\s+qui\s+relie|did\s+not\s+find\s+a\s+passage\s+that\s+explicitly\s+connects|no\s+he\s+encontrado\s+un\s+pasaje|nao\s+encontrei\s+uma\s+passagem|keine\s+stelle\s+gefunden|non\s+ho\s+trovato\s+un\s+passaggio)\b",
            RegexOptions.CultureInvariant);
    }

    private static string TryBuildMissingRequiredEvidenceAnswer(ToolResults toolResults, string query, string language)
    {
        var requiredTerms = ExtractStrictRequiredEvidenceTerms(query);
        if (requiredTerms.Count == 0)
            return string.Empty;

        var usableHits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();
        if (usableHits.Count == 0)
            return string.Empty;

        var missingTerms = requiredTerms
            .Where(term => !usableHits.Any(hit => RequiredEvidenceTermMatchesHit(term, hit)))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        if (missingTerms.Length == 0)
            return string.Empty;

        var termList = string.Join(", ", missingTerms.Select(static term => $"\"{term}\""));
        return SourceBackedLabel(
            language,
            $"Je n'ai pas trouve de passage qui mentionne explicitement {termList} dans les sources disponibles. Je ne construis donc pas une reponse a partir de passages voisins.",
            $"I did not find a passage that explicitly mentions {termList} in the available sources, so I will not build an answer from nearby passages.",
            $"No he encontrado un pasaje que mencione explicitamente {termList} en las fuentes disponibles, asi que no construire una respuesta a partir de pasajes cercanos.",
            $"Nao encontrei uma passagem que mencione explicitamente {termList} nas fontes disponiveis, por isso nao vou construir uma resposta a partir de passagens proximas.",
            $"Ich habe keine Stelle gefunden, die {termList} in den verfuegbaren Quellen ausdruecklich erwaehnt, daher baue ich keine Antwort aus benachbarten Passagen.",
            $"Non ho trovato un passaggio che menzioni esplicitamente {termList} nelle fonti disponibili, quindi non costruisco una risposta da passaggi vicini.");
    }

    private static string TryBuildMissingBroadCompositionAnchorAnswer(ToolResults toolResults, string query, string language)
    {
        if (!LooksLikeSourceBackedOptionRequest(query)
            || LooksLikeWeeklyPlanningRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || !string.IsNullOrWhiteSpace(TryExtractRequestedItemTitle(query)))
        {
            return string.Empty;
        }

        var normalized = NormalizeLexicalLookup(query);
        if (!Regex.IsMatch(
                normalized,
                @"\b(?:idee|idees|ideas?|technique|methode|method|approche|approach|organisation|organization|strategie|strategy|planning|parallele|parallel|selection|composition)\b",
                RegexOptions.CultureInvariant))
        {
            return string.Empty;
        }

        var anchorTerms = ExtractBroadCompositionAnchorTerms(query);
        if (anchorTerms.Length < 2)
            return string.Empty;

        var usableHits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();
        if (usableHits.Count == 0)
            return string.Empty;

        var missingTerms = anchorTerms
            .Where(term => !usableHits.Any(hit => RequiredEvidenceTermMatchesHit(term, hit)))
            .ToArray();
        var specificMissingTerms = missingTerms
            .Where(IsSpecificBroadCompositionAnchorTerm)
            .ToArray();
        if (missingTerms.Length < Math.Min(2, anchorTerms.Length) && specificMissingTerms.Length == 0)
            return string.Empty;

        var displayedTerms = specificMissingTerms.Length > 0 ? specificMissingTerms : missingTerms;
        var termList = string.Join(", ", displayedTerms.Select(static term => $"\"{term}\""));
        var answer = SourceBackedLabel(
            language,
            $"Je n'ai pas trouve de passage qui couvre clairement {termList} dans les sources disponibles. Je peux citer des passages voisins, mais je ne construis pas une proposition comme si cette idee etait sourcee.",
            $"I did not find passages that clearly cover {termList} in the available sources. I can cite nearby passages, but I will not build a proposal as if that idea were sourced.",
            $"No he encontrado pasajes que cubran claramente {termList} en las fuentes disponibles. Puedo citar pasajes cercanos, pero no construire una propuesta como si esa idea estuviera documentada.",
            $"Nao encontrei passagens que cubram claramente {termList} nas fontes disponiveis. Posso citar passagens proximas, mas nao construirei uma proposta como se essa ideia estivesse documentada.",
            $"Ich habe keine Stellen gefunden, die {termList} in den verfuegbaren Quellen klar abdecken. Ich kann nahe Treffer nennen, baue daraus aber keinen belegten Vorschlag.",
            $"Non ho trovato passaggi che coprano chiaramente {termList} nelle fonti disponibili. Posso citare passaggi vicini, ma non costruisco una proposta come se l'idea fosse documentata.");
        return AppendBroadenedSearchOfferIfHelpful(answer, query, language);
    }

    private static bool IsSpecificBroadCompositionAnchorTerm(string term)
    {
        var normalized = NormalizeLexicalLookup(term);
        if (normalized.Length < 6)
            return false;

        return !BroadCompositionGenericAnchorTerms.Contains(normalized);
    }

    private static readonly HashSet<string> BroadCompositionGenericAnchorTerms = new(StringComparer.Ordinal)
    {
        "idee", "idees", "ideas", "technique", "techniques", "methode", "methodes", "method",
        "methods", "approche", "approaches", "organisation", "organization", "strategie",
        "strategy", "planning", "parallele", "parallel", "selection", "composition",
        "execution", "executer", "preparer", "prepare", "preparation", "organiser",
        "organize", "compatible", "compatibles", "sourcee", "sourcees", "source",
        "sources", "documents", "document"
    };

    private static string TryBuildMissingPairingAnchorAnswer(ToolResults toolResults, string query, string language)
    {
        if (!LooksLikeSourceBackedPairingRecommendationRequest(query))
            return string.Empty;

        var targetTerms = ExtractPairingTargetAnchorTerms(query);
        if (targetTerms.Count == 0)
            return string.Empty;

        var usableHits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();
        if (usableHits.Count == 0)
            return string.Empty;

        var hasTargetAnchor = usableHits.Any(hit => PairingTargetAnchorMatchesHit(targetTerms, hit));
        if (hasTargetAnchor)
            return string.Empty;

        var targetList = string.Join(", ", targetTerms.Select(static term => $"\"{term}\""));
        var optionKindTerms = ExtractPairingRequestedOptionKindTerms(query);
        var optionKindList = optionKindTerms.Count > 0
            ? string.Join(", ", optionKindTerms.Select(static term => $"\"{term}\""))
            : SourceBackedLabel(language, "la demande", "the request", "la solicitud", "o pedido", "die Anfrage", "la richiesta");

        var answer = SourceBackedLabel(
            language,
            $"Je n'ai pas trouve de passage qui relie explicitement {targetList} a {optionKindList} dans les sources disponibles. Je ne transforme donc pas des passages voisins en recommandation compatible.",
            $"I did not find a passage that explicitly connects {targetList} to {optionKindList} in the available sources, so I will not turn nearby passages into a compatible recommendation.",
            $"No he encontrado un pasaje que conecte explicitamente {targetList} con {optionKindList} en las fuentes disponibles, asi que no convertire pasajes cercanos en una recomendacion compatible.",
            $"Nao encontrei uma passagem que ligue explicitamente {targetList} a {optionKindList} nas fontes disponiveis, por isso nao transformo passagens proximas numa recomendacao compativel.",
            $"Ich habe keine Stelle gefunden, die {targetList} in den verfuegbaren Quellen ausdruecklich mit {optionKindList} verbindet, daher mache ich aus benachbarten Passagen keine kompatible Empfehlung.",
            $"Non ho trovato un passaggio che colleghi esplicitamente {targetList} a {optionKindList} nelle fonti disponibili, quindi non trasformo passaggi vicini in una raccomandazione compatibile.");
        return AppendBroadenedSearchOfferIfHelpful(answer, query, language);
    }

    private static IReadOnlyList<string> ExtractPairingTargetAnchorTerms(string? query)
    {
        if (!LooksLikeSourceBackedPairingRecommendationRequest(query))
            return Array.Empty<string>();

        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var optionKindTerms = ExtractPairingRequestedOptionKindTerms(query);
        return ExtractQuerySignalTerms(normalized)
            .Where(static term => term.Length >= 4)
            .Where(term => !optionKindTerms.Contains(term, StringComparer.Ordinal))
            .Where(static term => !SourceBackedPairingAnchorNoiseTerms.Contains(term))
            .Where(static term => !SourceBackedOptionConstraintTerms.Contains(term))
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(4)
            .ToArray();
    }

    private static bool PairingTargetAnchorMatchesHit(IReadOnlyList<string> targetTerms, RagHitSummary hit)
        => targetTerms.Count > 0 && targetTerms.All(term => RequiredEvidenceTermMatchesHit(term, hit));

    private static bool LooksLikeMissingPairingAnchorAnswer(string? answer)
    {
        var normalized = NormalizeLexicalLookup(answer);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:pas\s+trouve\s+de\s+passage\s+qui\s+relie|did\s+not\s+find\s+a\s+passage\s+that\s+explicitly\s+connects|no\s+he\s+encontrado\s+un\s+pasaje\s+que\s+conecte|nao\s+encontrei\s+uma\s+passagem\s+que\s+ligue|keine\s+stelle\s+gefunden.*verbindet|non\s+ho\s+trovato\s+un\s+passaggio\s+che\s+colleghi)\b",
            RegexOptions.CultureInvariant);
    }

    private static string[] ExtractBroadCompositionAnchorTerms(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        return ExtractQuerySignalTerms(normalized)
            .Where(static term => term.Length >= 5)
            .Where(static term => !SourceBackedOptionConstraintTerms.Contains(term))
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Distinct(StringComparer.Ordinal)
            .Take(6)
            .ToArray();
    }

    private static IReadOnlyList<string> ExtractStrictRequiredEvidenceTerms(string? query)
    {
        var text = CollapseWhitespace(query ?? string.Empty);
        var normalized = NormalizeLexicalLookup(text);
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var strictCue = Regex.IsMatch(
            normalized,
            @"\b(?:uniquement|only|solo|apenas|nur|obligatoire|required|mandatory|must|explicitement|explicitly|mentionne|mentionnes|mentions?|parle|parlent|utilise|utilisent|emploie|emploient|uses?|using|contains?|contient|a\s+partir\s+des?\s+(?:pdf|documents?|sources?)|from\s+(?:the\s+)?(?:pdf|documents?|sources?))\b",
            RegexOptions.CultureInvariant);
        if (!strictCue)
            return Array.Empty<string>();

        var terms = new List<string>();
        terms.AddRange(ExtractNamedEntityLikeQueryTerms(text));

        foreach (Match match in Regex.Matches(
            text,
            @"[\u00ab""'](?<term>[^\u00bb""']{3,80})[\u00bb""']",
            RegexOptions.CultureInvariant))
        {
            AddStrictRequiredEvidenceTerm(terms, match.Groups["term"].Value);
        }

        foreach (Match match in Regex.Matches(
            text,
            @"(?i)\b(?:parle(?:nt)?|mentionne(?:nt|s)?|mentions?|contient|contains?|about|sur|sobre|ueber|uber|su)\s+(?:du|de\s+la|de\s+l['\u2019]|des|d['\u2019]|the|le|la|les|l['\u2019])?\s*(?<term>[\p{L}\p{N}'\u2019 \-]{3,80})",
            RegexOptions.CultureInvariant))
        {
            AddStrictRequiredEvidenceTerm(terms, match.Groups["term"].Value);
        }

        foreach (Match match in Regex.Matches(
            text,
            @"(?i)\b(?:utilise(?:nt)?|emploie(?:nt)?|uses?|using)\s+(?:du|de\s+la|de\s+l['\u2019]|des|d['\u2019]|the|le|la|les|l['\u2019])?\s*(?<term>[\p{L}\p{N}'\u2019 \-]{3,80})",
            RegexOptions.CultureInvariant))
        {
            AddStrictRequiredEvidenceTerm(terms, match.Groups["term"].Value);
        }

        return terms
            .Select(NormalizeStrictRequiredEvidenceTerm)
            .Where(static term => term.Length >= 4)
            .Where(static term => !IsSourceBackedActionRetrievalNoiseTerm(term))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(4)
            .ToArray();
    }

    private static void AddStrictRequiredEvidenceTerm(List<string> terms, string value)
    {
        var term = NormalizeStrictRequiredEvidenceTerm(value);
        if (!string.IsNullOrWhiteSpace(term))
            terms.Add(term);
    }

    private static string NormalizeStrictRequiredEvidenceTerm(string? value)
    {
        var term = CollapseWhitespace(value ?? string.Empty)
            .Trim(' ', '.', ',', ';', ':', '?', '!', '"', '\'', '\u00ab', '\u00bb');
        term = Regex.Replace(
            term,
            @"(?i)\s+\b(?:avec|with|con|com|mit|per|pour|for|only|uniquement|a\s+partir|from|dans|in|des?\s+pdf|documents?|sources?|options?|ideas?|idees?)\b.*$",
            string.Empty,
            RegexOptions.CultureInvariant);
        term = Regex.Replace(
            term,
            @"(?i)^(?:de\s+l['\u2019]|d['\u2019]|de\s+la|du|des|de|the|le|la|les|l['\u2019])\s+",
            string.Empty,
            RegexOptions.CultureInvariant);
        return CollapseWhitespace(term).Trim(' ', '.', ',', ';', ':');
    }

    private static bool RequiredEvidenceTermMatchesHit(string term, RagHitSummary hit)
    {
        var normalizedTerm = NormalizeLexicalLookup(term);
        if (string.IsNullOrWhiteSpace(normalizedTerm))
            return true;

        var haystack = NormalizeLexicalLookup(
            $"{hit.DocName} {hit.DocPath} {hit.SectionTitle} {hit.HeadingPath} {GetRagHitLookupText(hit)} {string.Join(' ', hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>())}");
        if (haystack.Contains(normalizedTerm, StringComparison.Ordinal))
            return true;

        var terms = ExtractQuerySignalTerms(normalizedTerm)
            .Where(static item => item.Length >= 4)
            .ToArray();
        if (terms.Length == 0)
            return false;

        var matchedTerms = terms.Count(item => haystack.Contains(item, StringComparison.Ordinal));
        if (matchedTerms == terms.Length)
            return true;

        return terms.Length >= 4 && matchedTerms >= terms.Length - 1 && matchedTerms >= 3;
    }

    private static string GetPlanExtractionText(RagHitSummary hit)
        => string.IsNullOrWhiteSpace(hit.FullText) ? hit.Excerpt : hit.FullText!;

    private static string ExtractPlanItemTitleV2(string? excerpt)
    {
        var text = CollapseWhitespace(excerpt ?? string.Empty);
        if (text.Length == 0)
            return string.Empty;

        text = Regex.Replace(text, @"^\d+", string.Empty, RegexOptions.CultureInvariant).Trim();
        text = Regex.Replace(text, @"(?<=[\p{Ll}])(?=(?:Pour|For|Para|Per)\b)", " ", RegexOptions.CultureInvariant);
        var patterns = new[]
        {
            @"^(?:[\p{Lu}\p{Lt}][\p{Ll}]{2,24})?(?<title>[\p{Lu}\p{Lt}][\p{Lu}\p{Lt}0-9 '&/,\-]{5,90}?)(?:\d+\s*min|\d+(?:[,.]\d+)?\s*(?:eur|euros?|chf))",
            @"(?i)^(?<title>\p{Lu}[\p{L}'\u2019 \-/]{5,80}?)\s+(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+[\p{L}'\u2019.\-]{2,30}\b",
            @"(?i)\b(?:pour|for|para|per|fur|fuer|zu|a|da)\s+\d{1,3}\s+[\p{L}'\u2019.\-]{2,30}\s+(?<title>\p{Lu}[\p{L}'\u2019 \-/]{5,80}?)(?:\s+(?:Items?|Elements?|Requirements?|Quantities?|Values?|Materials?|Components?|Procedure|Instructions?|Method|Preparation|Operation|Workflow|\d+\s*min))",
            @"(?i)(?:^|[\s:;])(?<title>\p{Lu}[\p{Lu}0-9 '&/,\-]{5,90}?)(?:\d+\s*min|\d+(?:[,.]\d+)?\s*(?:eur|euros?|chf)|Items?|Elements?|Requirements?|Quantities?|Values?|Materials?|Components?|Procedure|Instructions?|Method|Preparation|Operation|Workflow|Temps\s+total|Total\s+time)",
            @"(?i)\b(?<title>\p{Lu}[\p{L}'\u2019 \-/]{5,80})\s+(?:\d+\s*(?:items?|elements?|units?|pieces?)|Items?|Elements?|Requirements?|Quantities?|Values?|Materials?|Components?|Procedure|Instructions?|Method|Preparation|Operation|Workflow)"
        };

        foreach (var pattern in patterns)
        {
            var match = Regex.Match(text, pattern, RegexOptions.CultureInvariant);
            if (!match.Success)
                continue;

            var title = HumanizePlanItemTitleV2(match.Groups["title"].Value);
            if (!LooksLikePlanPageHeading(text, title) && IsUsableSourceBackedOptionTitle(title))
                return title;
        }

        return string.Empty;
    }

    private static bool LooksLikePlanPageHeading(string text, string title)
    {
        if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(title))
            return false;

        var escapedTitle = Regex.Escape(CollapseWhitespace(title));
        return Regex.IsMatch(
            CollapseWhitespace(text),
            $@"(?:^|\s)(?:\d+\s*)?\|\s*{escapedTitle}\s*(?:Pour|For|Para|Per)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }

    private static string HumanizePlanItemTitleV2(string value)
    {
        var title = CollapseWhitespace(value);
        title = Regex.Replace(title, @"(?<=\p{Ll})(?=\p{Lu})", " ", RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"(?<=\p{Lu})(?=\p{Lu}\p{Ll})", " ", RegexOptions.CultureInvariant);
        title = Regex.Replace(
            title,
            @"(?<=[\p{Lu}\p{Lt}]{4})\b(?=(?:WITHOUT|SENZA|SELON|AVEC|SANS|PARA|OHNE|WITH|POUR|AUX|DES|AND|FOR|CON|SIN|MIT|PER|DU|DE|AU|A|D['\u2019])\b)",
            " ",
            RegexOptions.CultureInvariant);
        title = Regex.Replace(
            title,
            @"\b(?:WITHOUT|SENZA|SELON|AVEC|SANS|PARA|OHNE|WITH|POUR|AUX|DES|AND|FOR|CON|SIN|MIT|PER|DU|DE|AU|A|D['\u2019])(?=[\p{Lu}\p{Lt}]{4})",
            "$0 ",
            RegexOptions.CultureInvariant);
        title = Regex.Replace(title, @"\s+", " ").Trim(' ', '-', ':');
        return title;
    }

    private static bool LooksLikePlanItemNoise(string value)
    {
        var normalized = NormalizeLexicalLookup(value);
        if (normalized.Length < 4)
            return true;
        if (normalized.Length > 90)
            return true;

        var trimmed = value.TrimStart();
        if (trimmed.Length > 0 && char.IsLower(trimmed[0]))
            return true;

        if (Regex.IsMatch(normalized, @"^(?:si|lorsque|quand|when|if)\b", RegexOptions.CultureInvariant))
            return true;
        if (Regex.IsMatch(normalized, @"^(?:en\s+)?moins\s+de\b|^under\s+\d+\b|^less\s+than\s+\d+\b", RegexOptions.CultureInvariant))
            return true;

        if (Regex.IsMatch(
                normalized,
            @"\b(?:liste|source|sources|page|pages|sommaire|index|contents|catalogue|copyright|isbn|edition|preparation|operation|workflow|execution|organisation|planning|calendrier|modele|outil|conseils?|consiste|prendre|heures?|temps|documents?|disponibles?|materiel|service|utilisez|utiliser|choisissez|installation|lors|ouvrir|programmer|extraire|volonte|limiter|limit)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"(^|\s)\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l|oz|lb|lbs)\b",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"^(?:p\s*)?(?:preparation|operation|workflow)\s*\d*$",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:de|du|des|d|a|au|aux|of|the|for|with|con|por|para|per|di|da|von|zu)$",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        if (Regex.IsMatch(
                normalized,
                @"\b(?:le|la|les|un|une|der|die|das|il|lo|gli|el|los|las)$",
                RegexOptions.CultureInvariant))
        {
            return true;
        }

        var meaningfulTerms = ExtractQuerySignalTerms(normalized)
            .Where(static term => term.Length >= 4)
            .ToArray();
        if (meaningfulTerms.Length == 0)
            return true;

        var letterCount = normalized.Count(char.IsLetter);
        return letterCount < Math.Max(4, normalized.Length / 3);
    }

    internal static string BuildSourceBackedExtractiveHeader(string language, bool noExplicitPairing)
    {
        language = NormalizeLanguageCode(language);
        if (noExplicitPairing)
        {
            return language switch
            {
                "en" => "I did not find a passage that connects every part of the request. The useful passages I can cite from the available documents are:",
                "es" => "No he encontrado un pasaje que conecte todas las partes de la solicitud. Los pasajes útiles que puedo citar en los documentos disponibles son:",
                "pt" => "Não encontrei uma passagem que ligue todas as partes do pedido. Os excertos úteis que posso citar nos documentos disponíveis são:",
                "de" => "Ich habe keine Stelle gefunden, die alle Teile der Anfrage verbindet. Die nützlichen Passagen aus den verfügbaren Dokumenten sind:",
                "it" => "Non ho trovato un passaggio che colleghi tutte le parti della richiesta. I passaggi utili che posso citare nei documenti disponibili sono:",
                _ => "Je n'ai pas trouvé de passage qui relie tous les éléments de la demande. Les passages utiles que je peux citer dans les documents disponibles sont :"
            };
        }

        return language switch
        {
            "en" => "Here are the useful passages found in the available documents:",
            "es" => "Estos son los pasajes útiles encontrados en los documentos disponibles:",
            "pt" => "Estes são os excertos úteis encontrados nos documentos disponíveis:",
            "de" => "Hier sind die nützlichen Passagen aus den verfügbaren Dokumenten:",
            "it" => "Ecco i passaggi utili trovati nei documenti disponibili:",
            _ => "Voici les passages utiles trouvés dans les documents disponibles :"
        };
    }

    private static int ComputeRagHitLexicalRelevance(string query, string? excerpt)
    {
        var normalizedQuery = NormalizeLexicalLookup(query);
        var normalizedExcerpt = NormalizeLexicalLookup(excerpt);
        var score = 0;

        foreach (var term in ExtractQuerySignalTerms(normalizedQuery))
        {
            if (normalizedExcerpt.Contains(term, StringComparison.Ordinal))
                score += term.Length >= 7 ? 4 : 2;
        }

        return score;
    }

    private static bool LooksLikeShortTechnicalEvidenceTopic(string? query)
    {
        var topic = NormalizeRagQueryForRetrieval(BuildRagEvidenceSelectionQuery(query ?? string.Empty));
        var normalized = NormalizeLexicalLookup(topic);
        if (normalized.Length is < 3 or > 120)
            return false;

        if (Regex.IsMatch(
                normalized,
                @"\b(?:planning|planifier|choose|choisir|propose|suggest|recommend|selection|options?)\b",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        var terms = ExtractQuerySignalTerms(normalized).ToArray();
        if (terms.Length is 0 or > 6)
            return false;

        if (LooksLikeCompactTechnicalIdentifier(topic))
            return true;

        return Regex.IsMatch(
            normalized,
            @"\b(?:proprietes?|properties?|property|caracteristiques?|characteristics?|specifications?|specs?|technical|technique|table|valeurs?|values?|mesures?|measurement|dimensions?|density|densite|temperature|thermique|thermal|electri(?:que|ques|cal)|electric|dielectric|resistance|pression|pressure|voltage|tension|puissance|power|unites?|units?|normes?|standards?)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeCompactTechnicalIdentifier(string? value)
    {
        var topic = NormalizeRagQueryForRetrieval(BuildRagEvidenceSelectionQuery(value ?? string.Empty));
        var normalized = NormalizeLexicalLookup(topic);
        if (normalized.Length is < 3 or > 120)
            return false;

        var terms = ExtractQuerySignalTerms(normalized).ToArray();
        if (terms.Length is 0 or > 4)
            return false;

        var acronymLikeTerms = Regex.Matches(
            topic,
            @"\b(?=[A-Z0-9_-]*[A-Z])(?=[A-Z0-9_-]*[A-Z0-9])[A-Z0-9]{2,}(?:[-_][A-Z0-9]{2,})*\b",
            RegexOptions.CultureInvariant).Count;
        return acronymLikeTerms >= 2;
    }

    private static int ComputeDirectTechnicalEvidenceScore(string query, RagHitSummary hit)
    {
        if (!LooksLikeShortTechnicalEvidenceTopic(query))
            return 0;

        var topic = NormalizeRagQueryForRetrieval(BuildRagEvidenceSelectionQuery(query));
        var normalizedTopic = NormalizeLexicalLookup(topic);
        var terms = BuildShortTechnicalEvidenceSelectionTerms(normalizedTopic);
        if (terms.Length == 0)
            return 0;

        var visible = NormalizeLexicalLookup(GetRagHitVisibleTechnicalEvidenceText(hit));
        var primary = NormalizeLexicalLookup(GetRagHitPrimaryEvidenceText(hit));
        var lookup = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        var structured = NormalizeLexicalLookup(GetRagHitStructuredEvidenceText(hit));
        var titleText = NormalizeLexicalLookup($"{hit.SectionTitle} {hit.HeadingPath}");
        var cardTitleText = NormalizeLexicalLookup(string.Join(' ', hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>()));
        var directEvidence = NormalizeLexicalLookup($"{titleText} {visible}");

        var primaryMatches = terms.Count(term => visible.Contains(term, StringComparison.Ordinal));
        var lookupMatches = terms.Count(term => lookup.Contains(term, StringComparison.Ordinal));
        var structuredMatches = terms.Count(term => structured.Contains(term, StringComparison.Ordinal));
        var titleMatches = terms.Count(term => titleText.Contains(term, StringComparison.Ordinal));
        var cardTitleMatches = terms.Count(term => cardTitleText.Contains(term, StringComparison.Ordinal));
        var directPhraseScore = ComputeShortTechnicalPhraseEvidenceScore(normalizedTopic, directEvidence);
        var structuredPhraseScore = ComputeShortTechnicalPhraseEvidenceScore(normalizedTopic, NormalizeLexicalLookup($"{structured} {cardTitleText}"));
        if (primaryMatches == 0
            && lookupMatches == 0
            && structuredMatches == 0
            && titleMatches == 0
            && cardTitleMatches == 0
            && directPhraseScore <= 0
            && structuredPhraseScore <= 0)
        {
            return 0;
        }

        var score = 0;
        score += titleMatches * 9;
        score += primaryMatches * 5;
        score += lookupMatches;
        score += structuredMatches * 2;
        score += cardTitleMatches;
        if (directPhraseScore > 0)
            score += directPhraseScore + 24;
        else if (structuredPhraseScore > 0)
            score += Math.Min(16, structuredPhraseScore / 5);

        var significantTerms = ExtractQuerySignalTerms(normalizedTopic).ToArray();
        if (significantTerms.Length > 0)
        {
            var directCoverage = significantTerms.Count(term =>
                DirectTechnicalEvidenceTermMatches(term, titleText)
                || DirectTechnicalEvidenceTermMatches(term, visible));
            if (directCoverage == significantTerms.Length)
                score += 16;
            else if (directCoverage >= Math.Min(2, significantTerms.Length))
                score += 8;
        }

        if (hit.HasTable)
            score += structuredMatches > 0 || titleMatches > 0 ? 18 : 8;
        if (HasContentCardEvidenceFacts(hit) && (directPhraseScore > 0 || primaryMatches > 0))
            score += Math.Min(8, ExtractContentCardEvidenceFacts(new[] { hit }).Length);
        if (Regex.IsMatch(titleText, @"\b(?:properties?|property|proprietes?|caracteristiques?|characteristics?|specifications?|technical\s+data|data\s+sheet|table|valeurs?|values?)\b", RegexOptions.CultureInvariant))
            score += 8;

        var role = NormalizeLexicalLookup(hit.SelectionHintRole);
        if (role is "navigation" or "fragment" or "low_confidence")
            score -= 12;
        if (NormalizeLexicalLookup(hit.ContentRole) == "navigation")
            score -= 10;
        if (NormalizeLexicalLookup(hit.ContentRole) == "mixed_navigation_content")
            score -= 2;
        if (hit.NavigationScore.GetValueOrDefault() >= 0.65)
            score -= 8;
        else if (hit.NavigationScore.GetValueOrDefault() >= 0.60)
            score -= 3;
        if (hit.SelectionHintNavigationScore.GetValueOrDefault() >= 70)
            score -= 6;
        if (hit.OcrApplied)
            score -= 6;
        if (hit.ManualReviewRecommended || hit.DocumentManualReviewRecommended || hit.PageManualReviewRecommended)
            score -= 6;
        if (!hit.HasTable && !HasContentCardEvidenceFacts(hit) && CollapseWhitespace(GetRagHitPrimaryContentText(hit)).Length < 80)
            score -= 4;

        return score;
    }

    private static bool HasShortTechnicalPhraseEvidence(string query, RagHitSummary hit)
    {
        if (!LooksLikeShortTechnicalEvidenceTopic(query))
            return false;

        var topic = NormalizeLexicalLookup(NormalizeRagQueryForRetrieval(BuildRagEvidenceSelectionQuery(query)));
        var evidence = NormalizeLexicalLookup(GetRagHitVisibleTechnicalEvidenceText(hit));
        return ComputeShortTechnicalPhraseEvidenceScore(topic, evidence) > 0;
    }

    private static int ComputeShortTechnicalPhraseEvidenceScore(string normalizedTopic, string normalizedEvidence)
    {
        var terms = BuildShortTechnicalEvidenceSelectionTerms(normalizedTopic).ToHashSet(StringComparer.Ordinal);
        var hasProperty = terms.Overlaps(new[] { "propriete", "proprietes", "property", "properties", "caracteristique", "caracteristiques", "characteristic", "characteristics" });
        var hasElectrical = terms.Overlaps(new[] { "electrique", "electriques", "electric", "electrical", "dielectric" });
        var hasThermal = terms.Overlaps(new[] { "thermique", "thermiques", "thermal", "temperature", "temperatures" });

        if (hasProperty && hasElectrical)
        {
            return Regex.IsMatch(
                normalizedEvidence,
                @"\b(?:electrical\s+properties|electric\s+properties|dielectric\s+properties|dielectric\s+strength|volume\s+resistivity|surface\s+resistance|electrical\s+insulat(?:ing|ion)|proprietes?\s+electriques?|caracteristiques?\s+electriques?)\b",
                RegexOptions.CultureInvariant)
                ? 80
                : -12;
        }

        if (hasProperty && hasThermal)
        {
            return Regex.IsMatch(
                normalizedEvidence,
                @"\b(?:thermal\s+properties|temperature\s+properties|melt(?:ing)?\s+point|thermal\s+conductivity|proprietes?\s+thermiques?|caracteristiques?\s+thermiques?)\b",
                RegexOptions.CultureInvariant)
                ? 80
                : -12;
        }

        return 0;
    }

    private static string[] BuildShortTechnicalEvidenceSelectionTerms(string normalizedTopic)
    {
        var terms = new List<string>();
        foreach (var term in ExtractQuerySignalTerms(normalizedTopic))
        {
            terms.Add(term);
            if (Regex.IsMatch(term, @"^(?:propriete|proprietes|property|properties|caracteristique|caracteristiques|characteristic|characteristics)$", RegexOptions.CultureInvariant))
                terms.AddRange(new[] { "property", "properties", "propriete", "proprietes", "characteristic", "characteristics", "caracteristique", "caracteristiques" });
            if (Regex.IsMatch(term, @"^(?:electrique|electriques|electric|electrical|dielectric)$", RegexOptions.CultureInvariant))
                terms.AddRange(new[] { "electric", "electrical", "electrique", "electriques", "dielectric" });
            if (Regex.IsMatch(term, @"^(?:thermique|thermiques|thermal|temperature|temperatures)$", RegexOptions.CultureInvariant))
                terms.AddRange(new[] { "thermal", "thermique", "thermiques", "temperature", "temperatures" });
            if (Regex.IsMatch(term, @"^(?:valeur|valeurs|value|values)$", RegexOptions.CultureInvariant))
                terms.AddRange(new[] { "value", "values", "valeur", "valeurs" });
            if (Regex.IsMatch(term, @"^(?:specification|specifications|spec|specs|technique|technical)$", RegexOptions.CultureInvariant))
                terms.AddRange(new[] { "specification", "specifications", "technical", "technique", "data" });
        }

        return terms
            .Where(static term => !string.IsNullOrWhiteSpace(term))
            .Select(NormalizeLexicalLookup)
            .Where(static term => term.Length >= 4)
            .Distinct(StringComparer.Ordinal)
            .Take(24)
            .ToArray();
    }

    private static bool DirectTechnicalEvidenceTermMatches(string term, string normalizedEvidence)
    {
        if (normalizedEvidence.Contains(term, StringComparison.Ordinal))
            return true;

        return term switch
        {
            "propriete" or "proprietes" or "property" or "properties" =>
                Regex.IsMatch(normalizedEvidence, @"\b(?:property|properties|proprietes?|characteristics?|caracteristiques?)\b", RegexOptions.CultureInvariant),
            "electrique" or "electriques" or "electric" or "electrical" or "dielectric" =>
                Regex.IsMatch(normalizedEvidence, @"\b(?:electric|electrical|electriques?|dielectric)\b", RegexOptions.CultureInvariant),
            "thermique" or "thermiques" or "thermal" or "temperature" or "temperatures" =>
                Regex.IsMatch(normalizedEvidence, @"\b(?:thermal|thermiques?|temperatures?)\b", RegexOptions.CultureInvariant),
            _ => false
        };
    }

    private static bool ShouldWarnNoExplicitPairing(string query, IReadOnlyList<RagHitSummary> hits)
    {
        if (hits.Count == 0)
            return false;

        if (LooksLikeShortTechnicalEvidenceTopic(query)
            && hits.Any(hit => HasShortTechnicalPhraseEvidence(query, hit)))
        {
            return false;
        }

        var pairingQuery = LooksLikeShortTechnicalEvidenceTopic(query)
            ? NormalizeRagQueryForRetrieval(BuildRagEvidenceSelectionQuery(query))
            : query;
        var terms = ExtractQuerySignalTerms(NormalizeLexicalLookup(pairingQuery))
            .Where(static term => term.Length >= 5)
            .Take(5)
            .ToArray();
        if (terms.Length < 2)
            return false;

        var evidence = NormalizeLexicalLookup(string.Join(' ', hits.Take(3).Select(GetRagHitLookupText)));
        if (string.IsNullOrWhiteSpace(evidence))
            return false;

        var covered = LooksLikeShortTechnicalEvidenceTopic(query)
            ? terms.Count(term => DirectTechnicalEvidenceTermMatches(term, evidence))
            : terms.Count(term => evidence.Contains(term, StringComparison.Ordinal));
        return covered < Math.Min(2, terms.Length);
    }

    private static string GetRagHitLookupText(RagHitSummary hit)
        => $"{hit.SectionTitle} {hit.HeadingPath} {hit.Excerpt} {hit.FullText} {hit.ContextualSnippet} {hit.RetrievalQuery} {GetRagHitStructuredEvidenceText(hit)}";

    private static string GetRagHitVisibleTechnicalEvidenceText(RagHitSummary hit)
        => $"{hit.SectionTitle} {hit.HeadingPath} {hit.Excerpt} {hit.FullText}";

    private static string GetRagHitComparativeEntityLookupText(RagHitSummary hit)
    {
        var cardText = hit.MatchedContentCards is { Count: > 0 }
            ? string.Join(' ', hit.MatchedContentCards.SelectMany(static card =>
                new[] { card.Title }.Concat(card.Signals ?? Array.Empty<string>())))
            : string.Empty;

        return $"{hit.DocName} {hit.DocPath} {hit.SectionTitle} {hit.HeadingPath} {hit.Excerpt} {hit.FullText} {hit.ContextualSnippet} {cardText}";
    }

    private static string GetRagHitPrimaryEvidenceText(RagHitSummary hit)
        => $"{hit.DocName} {hit.DocPath} {hit.SectionTitle} {hit.HeadingPath} {hit.Excerpt} {hit.FullText} {GetRagHitStructuredEvidenceText(hit)}";

    private static string GetRagHitStructuredEvidenceText(RagHitSummary hit)
    {
        var cardText = hit.MatchedContentCards is { Count: > 0 }
            ? string.Join(' ', hit.MatchedContentCards.SelectMany(static card =>
                new[] { card.Title, card.Kind }.Concat(card.Signals ?? Array.Empty<string>())))
            : string.Empty;
        return CollapseWhitespace($"{cardText} {BuildRagHitContentCardEvidenceText(hit)}");
    }

    private static string GetRagHitPrimaryContentText(RagHitSummary hit)
        => $"{hit.Excerpt} {hit.FullText}";

    private static RagHitEvidenceProfile ClassifyRagHitEvidenceProfile(RagHitSummary hit, string? query = null)
    {
        var lookup = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        var content = NormalizeLexicalLookup(GetRagHitPrimaryContentText(hit));
        var titleText = NormalizeLexicalLookup(
            $"{hit.SectionTitle} {hit.HeadingPath} {string.Join(' ', hit.MatchedContentCards?.Select(static card => card.Title) ?? Array.Empty<string>())}");

        var navigationScore = 0;
        var backendContentRole = NormalizeLexicalLookup(hit.ContentRole);
        if (backendContentRole == "navigation") navigationScore += 10;
        if (backendContentRole == "mixed_navigation_content") navigationScore += 2;
        if (hit.NavigationScore.HasValue && hit.NavigationScore.Value >= 0.82) navigationScore += 8;
        if (hit.ContentDensityScore.HasValue && hit.ContentDensityScore.Value < 0.25) navigationScore += 2;
        if (LooksLikeNavigationOnlyHit(hit)) navigationScore += 10;
        if (LooksLikePageReferenceOnlyHit(hit)) navigationScore += 6;
        if (Regex.IsMatch(lookup, @"\b(?:sommaire|contents|index|table\s+of\s+contents|catalogue|copyright|isbn|edition)\b", RegexOptions.CultureInvariant))
            navigationScore += 4;

        var fragmentScore = 0;
        if (Regex.IsMatch(CollapseWhitespace(hit.Excerpt ?? string.Empty), @"^(?:\.{2,}|\u2026)", RegexOptions.CultureInvariant))
            fragmentScore += 5;
        if (LooksLikeMidProcedureFragment(hit)) fragmentScore += 7;
        if (LooksLikeTruncatedEvidenceLead(hit.Excerpt)) fragmentScore += 4;
        if (content.Length is > 0 and < 80) fragmentScore += 3;
        if (Regex.IsMatch(content, @"\b(?:de|du|des|d|a|avec|sans|et|puis|jusqu|pour)$", RegexOptions.CultureInvariant))
            fragmentScore += 3;

        var actionabilityScore = 0;
        actionabilityScore += Math.Max(0, ComputeStructuredProcedureVisibleEvidenceCueScore(hit));
        actionabilityScore += Math.Max(0, ComputeProcedureCompletenessCueScore(hit));
        if (ExtractBestVisibleDurationMinutes(hit).HasValue) actionabilityScore += 3;
        if (CountProcedureStepMarkers(lookup) >= 2) actionabilityScore += 4;
        if (hit.ExactMatchHit) actionabilityScore += 3;
        foreach (var card in hit.MatchedContentCards ?? Array.Empty<RagHitContentCardSummary>())
        {
            var cardTitle = NormalizeLexicalLookup(card.Title);
            var kind = NormalizeLexicalLookup(card.Kind);
            if (!string.IsNullOrWhiteSpace(cardTitle) && IsUsefulSourceBackedDisplayTitle(card.Title))
                actionabilityScore += 2;
            if (kind.Contains("unit", StringComparison.Ordinal) || kind.Contains("exact", StringComparison.Ordinal) || kind.Contains("lead", StringComparison.Ordinal))
                actionabilityScore += 3;
        }

        var supportScore = ComputeRagHitLexicalRelevance(query ?? string.Empty, lookup);
        if (Regex.IsMatch(lookup, @"\b(?:conseil|conseils|note|notes|warning|attention|caution|recommendation|recommandation|guidance|astuce|tips?|hinweis|avviso)\b", RegexOptions.CultureInvariant))
            supportScore += 4;
        if (!string.IsNullOrWhiteSpace(hit.ContextualSnippet)) supportScore += 2;
        if (!string.IsNullOrWhiteSpace(titleText)) supportScore += 2;

        var qualityPenalty = 0;
        if (hit.ManualReviewRecommended || hit.OcrRecommended) qualityPenalty += 5;
        if (hit.ExtractionConfidence.HasValue && hit.ExtractionConfidence.Value < 0.55) qualityPenalty += 4;
        if (Regex.IsMatch(
                NormalizeLexicalLookup($"{hit.QualityStatus} {hit.DocumentQualityStatus} {hit.PageQualityStatus} {hit.TextStatus}"),
                @"\b(?:low|poor|empty|failed|manual|review)\b",
                RegexOptions.CultureInvariant))
        {
            qualityPenalty += 3;
        }

        var role = "supporting_context";
        if (navigationScore >= 4
            && hit.PageStart <= 2
            && hit.MatchedContentCards is not { Count: > 0 })
            role = "navigation";
        else if (navigationScore >= Math.Max(7, actionabilityScore + 2))
            role = "navigation";
        else if (fragmentScore >= Math.Max(7, actionabilityScore + 2))
            role = "fragment";
        else if (qualityPenalty >= 7 && actionabilityScore < 7)
            role = "low_confidence";
        else if (actionabilityScore >= 9 && actionabilityScore >= fragmentScore + 2)
            role = "actionable_item";
        else if (supportScore >= 5)
            role = "advisory";

        if (HasBackendSelectionHints(hit))
        {
            var backendRole = NormalizeRagEvidenceRole(hit.SelectionHintRole)
                              ?? InferBackendEvidenceRoleFromScores(hit)
                              ?? role;
            return new RagHitEvidenceProfile(
                backendRole,
                hit.SelectionHintActionabilityScore ?? actionabilityScore,
                hit.SelectionHintSupportScore ?? supportScore,
                hit.SelectionHintFragmentScore ?? fragmentScore,
                hit.SelectionHintNavigationScore ?? navigationScore,
                hit.SelectionHintQualityPenalty ?? qualityPenalty);
        }

        return new RagHitEvidenceProfile(role, actionabilityScore, supportScore, fragmentScore, navigationScore, qualityPenalty);
    }

    private static string? NormalizeRagEvidenceRole(string? value)
    {
        var role = NormalizeLexicalLookup(value);
        if (string.IsNullOrWhiteSpace(role))
            return null;

        return role switch
        {
            "actionable" or "actionable_item" or "actionableitem" => "actionable_item",
            "support" or "supporting" or "supporting_context" or "supportingcontext" => "supporting_context",
            "advice" or "advisory" => "advisory",
            "fragment" or "partial_fragment" or "partialfragment" => "fragment",
            "navigation" or "nav" => "navigation",
            "low_confidence" or "lowconfidence" or "low_quality" or "lowquality" => "low_confidence",
            _ => role
        };
    }

    private static bool HasBackendSelectionHints(RagHitSummary hit)
        => !string.IsNullOrWhiteSpace(hit.SelectionHintRole)
           || hit.SelectionHintActionabilityScore.HasValue
           || hit.SelectionHintSupportScore.HasValue
           || hit.SelectionHintFragmentScore.HasValue
           || hit.SelectionHintNavigationScore.HasValue
           || hit.SelectionHintQualityPenalty.HasValue;

    private static bool BackendSelectionHintsPreferUsableEvidence(RagHitSummary hit)
    {
        var role = NormalizeRagEvidenceRole(hit.SelectionHintRole);
        if (role is "actionable_item" or "supporting_context" or "advisory")
            return true;
        if (role is "navigation" or "fragment")
            return false;

        var actionability = hit.SelectionHintActionabilityScore ?? 0;
        var support = hit.SelectionHintSupportScore ?? 0;
        var navigation = hit.SelectionHintNavigationScore ?? 0;
        var fragment = hit.SelectionHintFragmentScore ?? 0;
        var qualityPenalty = hit.SelectionHintQualityPenalty ?? 0;
        var positive = Math.Max(actionability, support);

        return positive >= 8
               && navigation < 8
               && fragment < 8
               && qualityPenalty < 10;
    }

    private static bool BackendSelectionHintsPreferNavigation(RagHitSummary hit)
    {
        var role = NormalizeRagEvidenceRole(hit.SelectionHintRole);
        if (role == "navigation")
            return true;
        if (role is "actionable_item" or "supporting_context" or "advisory")
            return false;

        var navigation = hit.SelectionHintNavigationScore ?? 0;
        var actionability = hit.SelectionHintActionabilityScore ?? 0;
        var support = hit.SelectionHintSupportScore ?? 0;
        return navigation >= 8
               && navigation >= actionability + 2
               && navigation >= support + 2;
    }

    private static bool BackendSelectionHintsPreferLowSignal(RagHitSummary hit)
    {
        var role = NormalizeRagEvidenceRole(hit.SelectionHintRole);
        if (role is "navigation" or "fragment" or "low_confidence")
            return true;
        if (role is "actionable_item" or "supporting_context" or "advisory")
            return false;

        var fragment = hit.SelectionHintFragmentScore ?? 0;
        var navigation = hit.SelectionHintNavigationScore ?? 0;
        var actionability = hit.SelectionHintActionabilityScore ?? 0;
        var support = hit.SelectionHintSupportScore ?? 0;
        var qualityPenalty = hit.SelectionHintQualityPenalty ?? 0;
        var positive = Math.Max(actionability, support);

        return (fragment >= 8 && fragment >= positive + 2)
               || (navigation >= 8 && navigation >= positive + 2)
               || (qualityPenalty >= 12 && positive < 5);
    }

    private static string? InferBackendEvidenceRoleFromScores(RagHitSummary hit)
    {
        if (BackendSelectionHintsPreferNavigation(hit))
            return "navigation";
        if (BackendSelectionHintsPreferLowSignal(hit))
            return (hit.SelectionHintQualityPenalty ?? 0) >= 12 ? "low_confidence" : "fragment";

        var actionability = hit.SelectionHintActionabilityScore ?? 0;
        var support = hit.SelectionHintSupportScore ?? 0;
        if (actionability >= 8 && actionability >= support)
            return "actionable_item";
        if (support >= 8)
            return "supporting_context";
        if (support >= 5)
            return "advisory";

        return null;
    }

    private static int ComputeBackendSelectionPriority(RagHitSummary hit)
    {
        if (!HasBackendSelectionHints(hit))
            return 0;

        var role = NormalizeRagEvidenceRole(hit.SelectionHintRole);
        var roleScore = role switch
        {
            "actionable_item" => 100,
            "advisory" => 75,
            "supporting_context" => 65,
            "low_confidence" => 5,
            "fragment" => -65,
            "navigation" => -100,
            null => 0,
            _ => 35
        };

        var evidenceBonus = hit.MatchedContentCards?
            .Take(5)
            .Sum(static card => card.Evidence is not null ? 4 : 0) ?? 0;

        return roleScore
               + ((hit.SelectionHintActionabilityScore ?? 0) * 4)
               + ((hit.SelectionHintSupportScore ?? 0) * 3)
               - ((hit.SelectionHintFragmentScore ?? 0) * 4)
               - ((hit.SelectionHintNavigationScore ?? 0) * 5)
               - ((hit.SelectionHintQualityPenalty ?? 0) * 2)
               + evidenceBonus;
    }

    private static object BuildRagSelectionHintsPayload(RagHitSummary hit, string? query)
    {
        var profile = ClassifyRagHitEvidenceProfile(hit, query);
        return new
        {
            evidenceRole = profile.Role,
            actionabilityScore = profile.ActionabilityScore,
            supportScore = profile.SupportScore,
            fragmentScore = profile.FragmentScore,
            navigationScore = profile.NavigationScore,
            qualityPenalty = profile.QualityPenalty,
            contentRole = string.IsNullOrWhiteSpace(hit.ContentRole) ? null : hit.ContentRole,
            retrievalNavigationScore = hit.NavigationScore,
            contentDensityScore = hit.ContentDensityScore,
            navigationReason = string.IsNullOrWhiteSpace(hit.NavigationReason) ? null : hit.NavigationReason
        };
    }

    private static IEnumerable<string> ExtractQuerySignalTerms(string normalizedQuery)
    {
        var stopWords = new HashSet<string>(StringComparer.Ordinal)
        {
            "aide", "aider", "avec", "avoir", "cette", "comment", "dans", "faire", "facile", "idee",
            "peux", "pour", "propose", "proposes", "quoi", "semaine", "vais", "veux", "voudrais",
            "donne", "donner", "juste", "liste", "lister",
            "about", "find", "help", "make", "plan", "prepare", "recommend", "suggest", "what", "with",
            "list", "listing",
            "can", "could", "give", "ayuda", "ayudar", "ayudame", "puede", "puedes", "podrias", "propone",
            "recomienda", "ajuda", "ajudar", "pode", "podes", "recomenda", "kannst", "konntest", "helfen",
            "vorschlag", "empfiehl", "aiuta", "aiutami", "puoi", "consiglia", "planejamento",
            "planificacion", "organise", "organize", "organiser", "partir", "plusieurs", "multiple",
            "multiples", "several", "many", "option", "options", "utile", "utiles", "useful",
            "available", "disponible", "disponibles"
        };

        return Regex.Matches(normalizedQuery, @"[\p{L}\p{N}]{4,}")
            .Select(m => m.Value)
            .Where(term => !stopWords.Contains(term))
            .Distinct(StringComparer.Ordinal)
            .Take(8);
    }

    private static string NormalizeLexicalLookup(string? value)
    {
        var text = CollapseWhitespace(value ?? string.Empty)
            .ToLowerInvariant()
            .Replace("\u0153", "oe", StringComparison.Ordinal)
            .Replace("\u00e6", "ae", StringComparison.Ordinal)
            .Replace("\u00df", "ss", StringComparison.Ordinal);

        var decomposed = text.Normalize(NormalizationForm.FormD);
        var sb = new StringBuilder(decomposed.Length);
        foreach (var c in decomposed)
        {
            if (CharUnicodeInfo.GetUnicodeCategory(c) != UnicodeCategory.NonSpacingMark)
                sb.Append(c);
        }

        return sb.ToString().Normalize(NormalizationForm.FormC);
    }

    private static string NormalizeLooseLookup(string? value)
        => NormalizeLexicalLookup(value);

    private static string TryBuildSourcePolicyGuardAnswer(ToolResults toolResults, string query, string language)
    {
        if (!LooksLikeSourceBypassOrUnsupportedInventionRequest(query)
            || !toolResults.Items.Any(static item => item.ToolName is "rag.search" or "rag.multi_search"))
        {
            return string.Empty;
        }

        language = NormalizeLanguageCode(language);
        if (LooksLikeDocumentVersionYearOmissionRequest(query)
            && !LooksLikeDocumentInstructionPolicyRequest(query))
        {
            return string.Empty;
        }

        if ((LooksLikeDocumentVersionTraceabilityRequest(query)
             || LooksLikeDocumentVersionYearOmissionRequest(query))
            && !LooksLikeDocumentInstructionPolicyRequest(query)
            && !LooksLikeHardSourceBypassOrUnsupportedInventionRequest(query))
        {
            return string.Empty;
        }

        if (LooksLikeDocumentInstructionPolicyRequest(query))
            return BuildDocumentInstructionPolicyAnswer(language);

        var prefix = BuildSourcePolicyGuardPrefix(language);

        var evidence = BuildSourceBackedPlanningOrExtractiveAnswer(toolResults, query, language, minPlanningItems: 1);
        if (string.IsNullOrWhiteSpace(evidence))
            evidence = BuildRagEvidenceFallbackAnswer(toolResults, query, language);

        return string.IsNullOrWhiteSpace(evidence)
            ? prefix
            : ApplySourcePolicyGuardPrefix(evidence, language);
    }

    private static string BuildSourcePolicyGuardPrefix(string language)
        => SourceBackedLabel(
            language,
            "Je ne peux pas ignorer les sources ni inventer une reponse documentaire. Je reste donc strictement sur ce que les sources disponibles permettent.",
            "I cannot ignore the sources or invent a documentary answer. I will stay strictly within what the available sources support.",
            "No puedo ignorar las fuentes ni inventar una respuesta documental. Me limito estrictamente a lo que permiten las fuentes disponibles.",
            "Nao posso ignorar as fontes nem inventar uma resposta documental. Vou limitar-me estritamente ao que as fontes disponiveis sustentam.",
            "Ich kann die Quellen nicht ignorieren und keine dokumentarische Antwort erfinden. Ich bleibe daher strikt bei dem, was die verfuegbaren Quellen belegen.",
            "Non posso ignorare le fonti ne inventare una risposta documentale. Mi limito quindi strettamente a cio che le fonti disponibili supportano.");

    private static string BuildDocumentInstructionPolicyAnswer(string language)
        => SourceBackedLabel(
            NormalizeLanguageCode(language),
            "Je ne peux pas ignorer les consignes precedentes, inventer une reponse ou laisser une phrase dans un document modifier les regles de reponse. Une phrase retrouvee dans un PDF est une donnee du corpus a evaluer, pas une instruction systeme. Je reste limite aux sources disponibles et je refuse la partie non sourcee.",
            "I cannot ignore previous instructions, invent an answer, or let a sentence inside a document change the response rules. A sentence found in a PDF is corpus content to evaluate, not a system instruction. I stay limited to available sources and refuse the unsupported part.",
            "No puedo ignorar instrucciones anteriores, inventar una respuesta ni dejar que una frase dentro de un documento cambie las reglas de respuesta. Una frase encontrada en un PDF es contenido del corpus que se evalua, no una instruccion del sistema. Me limito a las fuentes disponibles y rechazo la parte sin respaldo.",
            "Nao posso ignorar instrucoes anteriores, inventar uma resposta nem deixar que uma frase dentro de um documento altere as regras de resposta. Uma frase encontrada num PDF e conteudo do corpus a avaliar, nao uma instrucao do sistema. Fico limitado as fontes disponiveis e recuso a parte sem suporte.",
            "Ich kann vorherige Anweisungen nicht ignorieren, keine Antwort erfinden und keinen Satz in einem Dokument die Antwortregeln aendern lassen. Ein Satz in einem PDF ist Korpusinhalt, der bewertet wird, keine Systemanweisung. Ich bleibe auf verfuegbare Quellen beschraenkt und lehne den unbelegten Teil ab.",
            "Non posso ignorare le istruzioni precedenti, inventare una risposta o lasciare che una frase dentro un documento cambi le regole di risposta. Una frase trovata in un PDF e contenuto del corpus da valutare, non un'istruzione di sistema. Mi limito alle fonti disponibili e rifiuto la parte non supportata.");

    private static string BuildSourceAbsentAssertionPolicyAnswer(string language)
        => SourceBackedLabel(
            NormalizeLanguageCode(language),
            "Non. Si l'extraction, le texte ou les sources disponibles sont vides ou insuffisants, je ne dois pas affirmer un champ, une valeur ou une conclusion documentaire. Je dois dire que l'information n'est pas confirmable avec les sources disponibles, demander une source exploitable ou citer uniquement les elements effectivement retrouves.",
            "No. If the extraction, text, or available sources are empty or insufficient, I must not assert a field, value, or documentary conclusion. I should state that the information cannot be confirmed from the available sources, ask for usable evidence, or cite only the evidence actually found.",
            "No. Si la extraccion, el texto o las fuentes disponibles estan vacios o son insuficientes, no debo afirmar un campo, valor o conclusion documental. Debo indicar que la informacion no se puede confirmar con las fuentes disponibles, pedir evidencia utilizable o citar solo lo encontrado.",
            "Nao. Se a extracao, o texto ou as fontes disponiveis estiverem vazios ou forem insuficientes, nao devo afirmar um campo, valor ou conclusao documental. Devo dizer que a informacao nao pode ser confirmada com as fontes disponiveis, pedir evidencia utilizavel ou citar apenas o que foi encontrado.",
            "Nein. Wenn Extraktion, Text oder verfuegbare Quellen leer oder unzureichend sind, darf ich kein Feld, keinen Wert und keine dokumentarische Schlussfolgerung behaupten. Ich sollte sagen, dass die Information mit den verfuegbaren Quellen nicht bestaetigt werden kann, nutzbare Nachweise anfordern oder nur gefundene Belege zitieren.",
            "No. Se l'estrazione, il testo o le fonti disponibili sono vuoti o insufficienti, non devo affermare un campo, un valore o una conclusione documentale. Devo dire che l'informazione non e confermabile con le fonti disponibili, chiedere evidenza utilizzabile o citare solo cio che e stato trovato.");

    private static string BuildBinaryAnswerWithSourceUncertaintyPolicyAnswer(string language)
        => SourceBackedLabel(
            NormalizeLanguageCode(language),
            "Je refuse de transformer la question en oui/non clair si les sources ne tranchent pas explicitement. Une reponse binaire n'est acceptable que si les passages cites etablissent directement la conclusion; sinon je dois expliquer la limite, citer les documents pertinents et eviter tout toujours/jamais non prouve.",
            "I will not turn the question into a clear yes/no if the sources do not explicitly settle it. A binary answer is acceptable only when the cited passages directly support the conclusion; otherwise I should explain the limit, cite the relevant documents, and avoid any unsupported always/never claim.",
            "No convertire la pregunta en un si/no claro si las fuentes no lo resuelven explicitamente. Una respuesta binaria solo es aceptable si los pasajes citados sostienen directamente la conclusion; si no, debo explicar el limite, citar los documentos pertinentes y evitar afirmaciones absolutas sin prueba.",
            "Nao transformo a pergunta num sim/nao claro se as fontes nao resolverem isso explicitamente. Uma resposta binaria so e aceitavel quando os trechos citados sustentam diretamente a conclusao; caso contrario devo explicar o limite, citar os documentos pertinentes e evitar qualquer sempre/nunca sem prova.",
            "Ich mache daraus kein klares Ja/Nein, wenn die Quellen es nicht ausdruecklich klaeren. Eine binaere Antwort ist nur akzeptabel, wenn die zitierten Passagen die Schlussfolgerung direkt stuetzen; sonst sollte ich die Grenze erklaeren, relevante Dokumente zitieren und unbelegte Immer/Nie-Aussagen vermeiden.",
            "Non trasformo la domanda in un si/no netto se le fonti non lo stabiliscono esplicitamente. Una risposta binaria e accettabile solo quando i passaggi citati supportano direttamente la conclusione; altrimenti devo spiegare il limite, citare i documenti pertinenti ed evitare affermazioni assolute non provate.");

    private static bool LooksLikeSourceAbsentAssertionPolicyRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var hasAssertionMarker = Regex.IsMatch(
            normalized,
            @"\b(?:affirmer|affirme|confirmer|confirme|conclure|deduire|declarer|dire|donner|donne|pretendre|assert|state|claim|confirm|conclude|infer|deduce|give|provide|afirmar|confirmar|concluir|deduzir|behaupten|bestaetigen|bestatigen|schlussfolgern|affermare|confermare|concludere)\b",
            RegexOptions.CultureInvariant);
        if (!hasAssertionMarker)
            return false;

        var asksExactUnsupportedValue = Regex.IsMatch(
            normalized,
            @"\b(?:valeur|valeurs|value|values|champ|champs|field|fields|table|tables|tableau|tableaux)\b.{0,45}\b(?:exact|exacte|exacts|exactes|precise|precis|precises|specific)\b|\b(?:exact|exacte|exacts|exactes|precise|precis|precises|specific)\b.{0,45}\b(?:valeur|valeurs|value|values|champ|champs|field|fields|table|tables|tableau|tableaux)\b",
            RegexOptions.CultureInvariant);
        var hasUnfoundEvidenceSurface = Regex.IsMatch(
            normalized,
            @"\b(?:ne\s+(?:re)?trouves?\s+pas|pas\s+(?:re)?trouvee?|not\s+found|cannot\s+find|can't\s+find|unable\s+to\s+find|introuvable|unavailable|indisponible|absent|absente|missing|manquant|manquante)\b.{0,70}\b(?:page|pages|source|sources|preuve|preuves|evidence|table|tables|tableau|tableaux)\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:page|pages|source|sources|preuve|preuves|evidence|table|tables|tableau|tableaux)\b.{0,70}\b(?:ne\s+(?:re)?trouves?\s+pas|pas\s+(?:re)?trouvee?|not\s+found|cannot\s+find|can't\s+find|unable\s+to\s+find|introuvable|unavailable|indisponible|absent|absente|missing|manquant|manquante)\b",
                RegexOptions.CultureInvariant);
        if (asksExactUnsupportedValue && hasUnfoundEvidenceSurface)
            return true;

        var hasEvidenceMissingMarker = Regex.IsMatch(
            normalized,
            @"\b(?:extraction|texte|text|source|sources|evidence|preuve|preuves|document|documents|page|pages|ocr)\b.{0,70}\b(?:vide|vides|empty|missing|absent|absente|absentes|manquant|manquante|manquantes|indisponible|unavailable|introuvable|not\s+found|insuffisant|insuffisante|insufficient|illlisible|illisible)\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:vide|vides|empty|missing|absent|absente|absentes|manquant|manquante|manquantes|indisponible|unavailable|introuvable|not\s+found|insuffisant|insuffisante|insufficient|illlisible|illisible)\b.{0,70}\b(?:extraction|texte|text|source|sources|evidence|preuve|preuves|document|documents|page|pages|ocr)\b",
                RegexOptions.CultureInvariant);
        if (hasEvidenceMissingMarker)
            return true;

        var hasMissingValueMarker = Regex.IsMatch(
            normalized,
            @"\b(?:valeur|valeurs|value|values|champ|champs|field|fields|information|informations|info|data|donnee|donnees)\b.{0,70}\b(?:vide|vides|empty|missing|absent|absente|absentes|manquant|manquante|manquantes|indisponible|unavailable|introuvable|not\s+found|insuffisant|insuffisante|insufficient|illlisible|illisible)\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:vide|vides|empty|missing|absent|absente|absentes|manquant|manquante|manquantes|indisponible|unavailable|introuvable|not\s+found|insuffisant|insuffisante|insufficient|illlisible|illisible)\b.{0,70}\b(?:valeur|valeurs|value|values|champ|champs|field|fields|information|informations|info|data|donnee|donnees)\b",
                RegexOptions.CultureInvariant);
        return hasMissingValueMarker;
    }

    private static bool ShouldAttachSourceAnchorForSourceAbsentAssertionPolicyRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:pdf|document|documents|source|sources|corpus|autre\s+document|other\s+document|vs|versus)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeBinaryAnswerWithSourceUncertaintyRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var asksBinary = Regex.IsMatch(
            normalized,
            @"\b(?:oui\s*/\s*non|oui\s+non|yes\s*/\s*no|yes\s+no|sim\s*/\s*nao|ja\s*/\s*nein|si\s*/\s*no|reponse\s+(?:binaire|oui\s*/\s*non)|binary\s+answer)\b",
            RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:reponse|answer|respuesta|antwort|risposta)\b.{0,25}\b(?:oui|non|yes|no|ja|nein|si|sim|nao)\b",
                RegexOptions.CultureInvariant);
        if (!asksBinary)
            return false;

        var hasSourceScope = Regex.IsMatch(
            normalized,
            @"\b(?:pdf|document|documents|source|sources|corpus|preuve|preuves|evidence|passages?)\b",
            RegexOptions.CultureInvariant);
        var hasUncertaintyPolicy = Regex.IsMatch(
            normalized,
            @"\b(?:ne\s+permettent\s+pas|ne\s+permet\s+pas|permettent\s+pas|permet\s+pas|not\s+allow|do\s+not\s+allow|cannot|can't|pas\s+clair|pas\s+claire|non\s+clair|unclear|insuffisant|insuffisante|insufficient|ne\s+tranche\s+pas|not\s+settle|refuse|refuser|refuses?|refusa|refuseren|simplification|simplifier|simplify)\b",
            RegexOptions.CultureInvariant);

        return hasSourceScope && hasUncertaintyPolicy;
    }

    private static bool LooksLikeDocumentInstructionPolicyRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var hasDocumentMarker = Regex.IsMatch(
            normalized,
            @"\b(?:pdf|document|documents|source|sources|corpus|phrase|texte|fichier|file|files)\b",
            RegexOptions.CultureInvariant);
        var hasPolicyMarker = Regex.IsMatch(
            normalized,
            @"\b(?:consigne|consignes|instruction|instructions|regle|regles|rules|systeme|system|reponse|response|prompt)\b",
            RegexOptions.CultureInvariant);
        var hasInstructionOverrideMarker = Regex.IsMatch(
            normalized,
            @"\b(?:ignore|ignorer|ignorez|modifier|modifie|change|changer|override|bypass|precedent|precedente|precedentes|previous|prior|obeir|obeis|obey|suivre|follow|appliquer|respecter)\b",
            RegexOptions.CultureInvariant);
        var hasNoCitationInstruction = Regex.IsMatch(
                normalized,
                @"\b(?:ne\s+pas|pas|sans|without|do\s+not|don\s*t|no)\b.{0,40}\b(?:citer|cite|citation|citations|sources?|references?)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:citer|cite|citation|citations|sources?|references?)\b.{0,40}\b(?:ne\s+pas|pas|sans|without|do\s+not|don\s*t|no)\b",
                RegexOptions.CultureInvariant);

        return hasDocumentMarker && hasPolicyMarker && (hasInstructionOverrideMarker || hasNoCitationInstruction);
    }

    private static bool LooksLikeDocumentVersionYearOmissionRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return Regex.IsMatch(
            normalized,
            @"\b(?:sans\s+(?:dire|preciser)|ne\s+precise\s+pas|ne\s+pas\s+preciser|without\s+(?:saying|specifying))\b.{0,80}\b(?:annee|annees|year|years|version|versions|edition|editions)\b",
            RegexOptions.CultureInvariant);
    }

    private static bool LooksLikeExplicitSourceBypassOrUnsupportedInventionRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        normalized = Regex.Replace(
            normalized,
            @"\b(?:sans\s+oublier|n\s*oublie\s+pas|ne\s+pas\s+oublier|without\s+forgetting|do\s+not\s+forget|don\s*t\s+forget|sin\s+olvidar|sem\s+esquecer|ohne\s+zu\s+vergessen|senza\s+dimenticare)\b",
            " ",
            RegexOptions.CultureInvariant);

        var asksToIgnoreSources =
            Regex.IsMatch(
                normalized,
                @"\b(?:ignore|ignorer|ignorez|oublie|oublier|disregard|ignora|ignorar|ignori|ignorare|ignoriere|ignorieren)\b.{0,60}\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b.{0,60}\b(?:ignore|ignorer|ignorez|oublie|oublier|disregard|ignora|ignorar|ignori|ignorare|ignoriere|ignorieren)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:sans|without|sin|sem|ohne|senza)\b.{0,60}\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b",
                RegexOptions.CultureInvariant);

        var asksToInvent = Regex.IsMatch(
            normalized,
            @"\b(?:invente|inventer|inventez|invent|invented|make\s+up|hallucinate|inventa|inventar|inventare|erfinde|erfinden|erfunden)\b",
            RegexOptions.CultureInvariant);

        return asksToIgnoreSources || asksToInvent;
    }

    private static bool LooksLikeHardSourceBypassOrUnsupportedInventionRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        normalized = Regex.Replace(
            normalized,
            @"\b(?:sans\s+oublier|n\s*oublie\s+pas|ne\s+pas\s+oublier|without\s+forgetting|do\s+not\s+forget|don\s*t\s+forget|sin\s+olvidar|sem\s+esquecer|ohne\s+zu\s+vergessen|senza\s+dimenticare)\b",
            " ",
            RegexOptions.CultureInvariant);

        return Regex.IsMatch(
                normalized,
                @"\b(?:ignore|ignorer|ignorez|oublie|oublier|disregard|ignora|ignorar|ignori|ignorare|ignoriere|ignorieren)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:sans|without|sin|sem|ohne|senza)\b.{0,60}\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:invente|inventer|inventez|invent|invented|make\s+up|hallucinate|inventa|inventar|inventare|erfinde|erfinden|erfunden)\b",
                RegexOptions.CultureInvariant);
    }

    private static string ApplySourcePolicyGuardPrefix(string answer, string language)
    {
        var prefix = BuildSourcePolicyGuardPrefix(language);
        if (string.IsNullOrWhiteSpace(answer))
            return prefix;

        return answer.Contains(prefix, StringComparison.OrdinalIgnoreCase)
            ? answer.Trim()
            : $"{prefix}{Environment.NewLine}{Environment.NewLine}{answer}".Trim();
    }

    private static bool LooksLikeSourceBypassOrUnsupportedInventionRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (LooksLikeSourceAbsentAssertionPolicyRequest(normalized))
            return true;

        if (LooksLikeBinaryAnswerWithSourceUncertaintyRequest(normalized))
            return true;

        if (LooksLikeDocumentInstructionPolicyRequest(normalized))
            return true;

        normalized = Regex.Replace(
            normalized,
            @"\b(?:sans\s+oublier|n\s*oublie\s+pas|ne\s+pas\s+oublier|without\s+forgetting|do\s+not\s+forget|don\s*t\s+forget|sin\s+olvidar|sem\s+esquecer|ohne\s+zu\s+vergessen|senza\s+dimenticare)\b",
            " ",
            RegexOptions.CultureInvariant);

        var asksToIgnoreSources =
            Regex.IsMatch(
                normalized,
                @"\b(?:ignore|ignorer|ignorez|oublie|oublier|disregard|ignora|ignorar|ignori|ignoren|ignorar|ignora|ignorar|ignora|ignora|ignori|ignora|ignori|ignori|ignori|ignorar|ignorare|ignoriere|ignorieren)\b.{0,60}\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b.{0,60}\b(?:ignore|ignorer|ignorez|oublie|oublier|disregard|ignora|ignorar|ignori|ignorare|ignoriere|ignorieren)\b",
                RegexOptions.CultureInvariant)
            || Regex.IsMatch(
                normalized,
                @"\b(?:sans|without|sin|sem|ohne|senza)\b.{0,60}\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b",
                RegexOptions.CultureInvariant);

        var asksToInvent =
            Regex.IsMatch(
                normalized,
                @"\b(?:invente|inventer|inventez|invent|invented|make\s+up|hallucinate|inventa|inventar|inventare|erfinde|erfinden|erfunden)\b",
                RegexOptions.CultureInvariant);

        return asksToIgnoreSources || asksToInvent;
    }

    private static string BuildSourcePolicyRetrievalQuery(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return string.Empty;

        normalized = Regex.Replace(
            normalized,
            @"\b(?:sans|without|sin|sem|ohne|senza)\b.{0,60}\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b",
            " ",
            RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"\b(?:ignore|ignorer|ignorez|oublie|oublier|disregard|ignora|ignorar|ignori|ignorare|ignoriere|ignorieren)\b.{0,60}\b(?:sources?|documents?|pdf|pages?|citations?|references?|fuentes?|fontes?|quellen?|fonti)\b",
            " ",
            RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"\b(?:sources?|documents?|pdf|fuentes?|fontes?|quellen?|fonti)\b.{0,60}\b(?:ignore|ignorer|ignorez|oublie|oublier|disregard|ignora|ignorar|ignori|ignorare|ignoriere|ignorieren)\b",
            " ",
            RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"\b(?:invente|inventer|inventez|invent|invented|make\s+up|hallucinate|inventa|inventar|inventare|erfinde|erfinden|erfunden)\b",
            " ",
            RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"\b(?:une|un|an|a|una|uma|eine|uno|un)\s+(?:version|versao|versione|variante|variant)\s+(?:amelioree|improved|mejorada|melhorada|verbesserte|migliorata)\s+(?:de|du|des|of|da|do|das|der|die|della|del|di)?\b",
            " ",
            RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"\b(?:une|un|an|a|una|uma|eine|uno|un)\s+(?:amelioree|improved|mejorada|melhorada|verbesserte|migliorata)\s+(?:version|versao|versione|variante|variant)\s+(?:de|du|des|of|da|do|das|der|die|della|del|di)?\b",
            " ",
            RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"\b(?:version|versao|versione|variante|variant)\s+(?:amelioree|improved|mejorada|melhorada|verbesserte|migliorata)\b",
            " ",
            RegexOptions.CultureInvariant);
        normalized = Regex.Replace(
            normalized,
            @"\b(?:amelioree|improved|mejorada|melhorada|verbesserte|migliorata)\s+(?:version|versao|versione|variante|variant)\b",
            " ",
            RegexOptions.CultureInvariant);

        return NormalizeRagQueryForRetrieval(normalized);
    }

    private static string BuildCategoryOverviewAnswer(ToolResults toolResults, string query, string language)
    {
        language = NormalizeLanguageCode(language);
        var hits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .Where(static hit => !string.IsNullOrWhiteSpace(hit.DocName) || !string.IsNullOrWhiteSpace(hit.DocPath))
            .GroupBy(hit => string.IsNullOrWhiteSpace(hit.DocPath) ? hit.DocName : hit.DocPath, StringComparer.OrdinalIgnoreCase)
            .Select(group => group
                .OrderByDescending(hit => ComputeRagHitLexicalRelevance(query, $"{hit.DocName} {hit.SectionTitle} {hit.HeadingPath} {hit.Excerpt}"))
                .ThenByDescending(hit => hit.Score)
                .First())
            .OrderByDescending(hit => ComputeRagHitLexicalRelevance(query, $"{hit.DocName} {hit.SectionTitle} {hit.HeadingPath} {hit.Excerpt}"))
            .ThenByDescending(hit => hit.Score)
            .Take(5)
            .ToList();

        if (hits.Count == 0)
            return string.Empty;

        var header = SourceBackedLabel(
            language,
            "Pour cette categorie, je partirais des documents indexes suivants. Je limite l'orientation aux sources retrouvees :",
            "For this category, I would start with these indexed documents. I am keeping the overview limited to retrieved sources:",
            "Para esta categoria, empezaria por estos documentos indexados. Limito la orientacion a las fuentes recuperadas:",
            "Para esta categoria, eu comecaria por estes documentos indexados. Limito a orientacao as fontes recuperadas:",
            "Fuer diese Kategorie wuerde ich mit diesen indexierten Dokumenten beginnen. Ich beschraenke die Uebersicht auf gefundene Quellen:",
            "Per questa categoria, inizierei da questi documenti indicizzati. Mantengo l'orientamento limitato alle fonti recuperate:");

        var caveat = SourceBackedLabel(
            language,
            "Limite : cette cartographie est une orientation de lecture, pas une validation exhaustive du corpus.",
            "Limit: this is a reading orientation, not an exhaustive validation of the corpus.",
            "Limite: es una orientacion de lectura, no una validacion exhaustiva del corpus.",
            "Limite: isto e uma orientacao de leitura, nao uma validacao exaustiva do corpus.",
            "Grenze: Das ist eine Leseorientierung, keine vollstaendige Korpusvalidierung.",
            "Limite: e un orientamento di lettura, non una validazione esaustiva del corpus.");

        var sb = new StringBuilder();
        sb.AppendLine(header);
        foreach (var hit in hits)
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? Path.GetFileName(hit.DocPath) : hit.DocName;
            sb.Append("- ");
            sb.Append(docLabel);
            sb.Append(" : ");
            sb.Append(InferGenericDocumentUseRole(docLabel, language));
            if (hit.PageStart > 0)
            {
                sb.Append(' ');
                sb.Append(SourceBackedPagePrefix(language));
                sb.Append(hit.PageStart);
                sb.Append('.');
            }
            sb.AppendLine();
        }

        sb.Append(caveat);
        return sb.ToString().TrimEnd();
    }

    private static string InferGenericDocumentUseRole(string? docName, string language)
    {
        _ = docName;
        var role = (
            "contexte source indexe pour les questions documentaires de la categorie",
            "indexed source context for documentary questions in the category");

        return NormalizeLanguageCode(language) switch
        {
            "en" or "es" or "pt" or "de" or "it" => role.Item2,
            _ => role.Item1
        };
    }

    private static bool LooksLikeBriefSourcedCitationRequest(string? query)
    {
        var normalized = NormalizeLexicalLookup(query);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var asksBrief = Regex.IsMatch(
            normalized,
            @"\b(?:tres\s+courte?|courte?|concis|concise|brief|short|breve|kurz)\b",
            RegexOptions.CultureInvariant);
        var asksCitation = Regex.IsMatch(
            normalized,
            @"\b(?:citation|citations|cite|citer|source|sources|page|pages|preuve|proof|evidence)\b",
            RegexOptions.CultureInvariant);
        var asksLimit = Regex.IsMatch(
            normalized,
            @"\b(?:limite|limites|limit|limits|caveat|reserve|preuve\s+faible|indirecte|confidence|confiance)\b",
            RegexOptions.CultureInvariant);

        return asksBrief && asksCitation && asksLimit;
    }

    private static string TryBuildBriefDocumentScopedCitationAnswer(
        ToolResults toolResults,
        string query,
        string requestedDocument,
        string language)
    {
        language = NormalizeLanguageCode(language);
        var hits = SelectSourceBackedExtractiveHits(toolResults, query, maxHits: 6)
            .Where(hit => CandidateMatchesDocumentIdentity(requestedDocument, hit.DocName, hit.DocPath))
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .GroupBy(hit => $"{hit.DocPath}|{hit.PageStart}|{hit.PageEnd}", StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .Take(3)
            .ToList();
        if (hits.Count == 0)
            return string.Empty;

        var topic = ExtractDelimitedNonFileTopics(query).FirstOrDefault();
        if (string.IsNullOrWhiteSpace(topic))
            topic = NormalizeRagQueryForRetrieval(query);
        if (string.IsNullOrWhiteSpace(topic))
            topic = SourceBackedLabel(language, "la question posee", "the requested topic", "el tema solicitado", "o tema pedido", "das angefragte Thema", "il tema richiesto");

        var best = hits[0];
        var excerpt = FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(best), maxLength: 280);
        var docLabel = string.IsNullOrWhiteSpace(best.DocName) ? requestedDocument : best.DocName;
        var page = best.PageStart > 0
            ? $"{SourceBackedPagePrefix(language)}{best.PageStart}"
            : SourceBackedLabel(language, "page non precisee", "unknown page", "pagina no indicada", "pagina nao indicada", "Seite unbekannt", "pagina non indicata");

        return language switch
        {
            "en" =>
                $"Short answer: the retrieved excerpts from {docLabel} support only a limited source-backed orientation on {topic}; they should not be treated as exhaustive proof of every sub-point.\nCitation: {docLabel} {page}: {excerpt}\nLimit: this conclusion is limited to the cited page(s) retrieved from the indexed corpus.",
            "es" =>
                $"Respuesta breve: los extractos recuperados de {docLabel} solo respaldan una orientacion limitada sobre {topic}; no deben tratarse como prueba exhaustiva de todos los subpuntos.\nCita: {docLabel} {page}: {excerpt}\nLimite: la conclusion se limita a las paginas citadas recuperadas del corpus indexado.",
            "pt" =>
                $"Resposta curta: os excertos recuperados de {docLabel} sustentam apenas uma orientacao limitada sobre {topic}; nao devem ser tratados como prova exaustiva de todos os subpontos.\nCitacao: {docLabel} {page}: {excerpt}\nLimite: a conclusao fica limitada as paginas citadas recuperadas do corpus indexado.",
            "de" =>
                $"Kurzantwort: Die gefundenen Auszuege aus {docLabel} stuetzen nur eine begrenzte, belegte Orientierung zu {topic}; sie sind kein vollstaendiger Nachweis fuer alle Teilpunkte.\nZitat: {docLabel} {page}: {excerpt}\nGrenze: Diese Aussage ist auf die zitierten Seiten aus dem indexierten Korpus beschraenkt.",
            "it" =>
                $"Risposta breve: gli estratti recuperati da {docLabel} supportano solo un orientamento limitato su {topic}; non sono una prova esaustiva di tutti i sottopunti.\nCitazione: {docLabel} {page}: {excerpt}\nLimite: la conclusione e limitata alle pagine citate recuperate dal corpus indicizzato.",
            _ =>
                $"Reponse courte : les extraits retrouves dans {docLabel} soutiennent seulement une orientation sourcee limitee sur {topic}; ils ne prouvent pas exhaustivement tous les sous-points.\nCitation : {docLabel} {page} : {excerpt}\nLimite : la conclusion reste limitee aux pages citees recuperees dans le corpus indexe."
        };
    }

    private static string BuildRagEvidenceFallbackAnswer(ToolResults toolResults, string query, string language)
    {
        language = NormalizeLanguageCode(language);
        var intentQuery = ResolveSourceBackedFallbackIntentQuery(query);
        var avoidRawSourceBackedFallback =
            ShouldAvoidRawSourceBackedFallback(intentQuery)
            || IsBroadenedSourceSearchConfirmationEnvelope(query);
        var missingRequiredEvidence = TryBuildMissingRequiredEvidenceAnswer(toolResults, intentQuery, language);
        if (!ShouldUseAdvisoryEvidenceGuardForBroadSynthesis(toolResults, intentQuery)
            && !string.IsNullOrWhiteSpace(missingRequiredEvidence))
            return missingRequiredEvidence;

        var missingPairingAnchor = TryBuildMissingPairingAnchorAnswer(toolResults, intentQuery, language);
        if (!ShouldUseAdvisoryEvidenceGuardForBroadSynthesis(toolResults, intentQuery)
            && !string.IsNullOrWhiteSpace(missingPairingAnchor))
            return missingPairingAnchor;

        var corpusClaimVerificationAnswer = TryBuildCorpusClaimVerificationAnswer(toolResults, intentQuery, language);
        if (!string.IsNullOrWhiteSpace(corpusClaimVerificationAnswer))
            return corpusClaimVerificationAnswer;

        if (!avoidRawSourceBackedFallback)
        {
            var comparativeAnswer = TryBuildComparativeDocumentaryAnswer(toolResults, intentQuery, language);
            if (!string.IsNullOrWhiteSpace(comparativeAnswer))
                return comparativeAnswer;
        }

        var usableHits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();

        if (!avoidRawSourceBackedFallback
            && (LooksLikeSourceBackedActionRequest(intentQuery) || LooksLikeComparativeDocumentaryRequest(intentQuery))
            && !LooksLikeSourceBackedOptionRequest(intentQuery)
            && !LooksLikeAnyDocumentaryPlanningRequest(intentQuery)
            && usableHits.Count > 0)
        {
            var extractiveAnswer = BuildSourceBackedExtractiveAnswer(toolResults, intentQuery, language);
            if (!string.IsNullOrWhiteSpace(extractiveAnswer))
                return extractiveAnswer;
        }

        var isPlanningFallback = LooksLikeAnyDocumentaryPlanningRequest(intentQuery);
        var rankedFallbackHits = SelectSourceBackedExtractiveHits(toolResults, intentQuery, maxHits: 8).ToList();
        if (rankedFallbackHits.Count > 0)
        {
            usableHits = isPlanningFallback
                ? rankedFallbackHits
                    .Concat(usableHits)
                    .GroupBy(BuildRagHitVisiblePageMergeKey, StringComparer.OrdinalIgnoreCase)
                    .Select(static group => group.First())
                    .ToList()
                : rankedFallbackHits;
        }

        var softChoiceOptionKindTerms = ExtractSoftChoiceRequestedOptionKindTerms(intentQuery);
        if (softChoiceOptionKindTerms.Count > 0)
        {
            var compatibleHits = usableHits
                .Where(hit => !SoftChoiceOptionKindContradictsHit(softChoiceOptionKindTerms, hit))
                .ToList();
            if (compatibleHits.Count > 0)
                usableHits = compatibleHits;
        }

        var candidateHits = isPlanningFallback
            ? usableHits
            : FilterHitsToDominantTopLevel(usableHits, intentQuery);
        var maxFallbackHits = isPlanningFallback
            ? Math.Min(6, Math.Max(3, ResolveSourceBackedPlanningTargetItemCount(intentQuery)))
            : 3;

        var hits = candidateHits
            .GroupBy(BuildRagHitVisiblePageMergeKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group.First())
            .Take(maxFallbackHits)
            .ToList();
        if (hits.Count == 0)
            return AppendBroadenedSearchOfferIfHelpful(
                DeterministicAgentText.AnswerNotEnoughUsableInfo(language),
                query,
                language);

        if (avoidRawSourceBackedFallback)
            return BuildBroadEvidenceStillInsufficientAnswer(language, query, intentQuery, hits.Count);

        if (isPlanningFallback)
        {
            var readablePlanningFallback = BuildReadablePartialPlanningEvidenceAnswer(hits, intentQuery, language);
            if (!string.IsNullOrWhiteSpace(readablePlanningFallback))
                return SuppressBroadenedSearchOfferIfAlreadyConfirmed(readablePlanningFallback, query, language);
        }

        var readableCandidateFallback = BuildReadableSourceBackedCandidateListFallbackAnswer(toolResults, intentQuery, language);
        if (!string.IsNullOrWhiteSpace(readableCandidateFallback))
            return SuppressBroadenedSearchOfferIfAlreadyConfirmed(readableCandidateFallback, query, language);

        if (!isPlanningFallback)
        {
            var readablePlanningFallback = BuildReadablePartialPlanningEvidenceAnswer(hits, intentQuery, language);
            if (!string.IsNullOrWhiteSpace(readablePlanningFallback))
                return SuppressBroadenedSearchOfferIfAlreadyConfirmed(readablePlanningFallback, query, language);
        }

        if (!RagFallbackHasAtLeastOneQueryAnchor(hits, intentQuery))
            return AppendBroadenedSearchOfferIfHelpful(BuildRagNeighborFallbackAnswer(hits, language), query, language);

        var topic = NormalizeRagQueryForRetrieval(intentQuery);
        topic = string.IsNullOrWhiteSpace(topic)
            ? SourceBackedLabel(language, "ce sujet", "this topic", "este tema", "este tema", "dieses Thema", "questo tema")
            : topic;

        var labels = language switch
        {
            "en" => (
                Header: $"Here is the documented material available for {topic}:",
                Caveat: "This does not fully prove every part of the request; use the cited pages to confirm the details."),
            "es" => (
                Header: $"Estas son las pistas con fuente disponibles sobre {topic}:",
                Caveat: "Esto no demuestra por completo cada parte de la solicitud; consulta las páginas citadas para confirmar los detalles."),
            "pt" => (
                Header: $"Estas são as pistas com fonte disponíveis sobre {topic}:",
                Caveat: "Isto não prova totalmente todas as partes do pedido; consulta as páginas citadas para confirmar os detalhes."),
            "de" => (
                Header: $"Diese belegten Hinweise sind zu {topic} verfügbar:",
                Caveat: "Das belegt nicht jeden Teil der Anfrage vollständig; prüfe die zitierten Seiten für die Details."),
            "it" => (
                Header: $"Queste sono le indicazioni con fonte disponibili su {topic}:",
                Caveat: "Questo non prova completamente ogni parte della richiesta; controlla le pagine citate per confermare i dettagli."),
            _ => (
                Header: $"Voici les éléments documentés disponibles sur {topic} :",
                Caveat: "Cela ne prouve pas complètement chaque partie de la demande ; vérifie les pages citées pour confirmer les détails.")
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        var emitted = 0;
        foreach (var hit in hits)
        {
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            var evidenceCue = BuildWriterEvidenceCueForPrompt(hit, intentQuery, maxLength: 180);
            if (string.IsNullOrWhiteSpace(evidenceCue))
                evidenceCue = CleanReadableProcedureArtifacts(FormatReadableEvidenceExcerpt(GetBestRagEvidenceText(hit), maxLength: 160));
            if (string.IsNullOrWhiteSpace(evidenceCue))
                continue;

            sb.Append("- ");
            sb.Append(evidenceCue);
            sb.Append(" (");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.AppendLine(").");
            emitted++;
        }
        if (emitted == 0)
            return AppendBroadenedSearchOfferIfHelpful(
                DeterministicAgentText.AnswerNotEnoughUsableInfo(language),
                query,
                language);

        sb.Append(labels.Caveat);
        return AppendBroadenedSearchOfferIfHelpful(sb.ToString(), query, language);
    }

    private static string BuildBroadEvidenceStillInsufficientAnswer(
        string language,
        string originalQuery,
        string intentQuery,
        int nearbyHitCount)
    {
        language = NormalizeLanguageCode(language);
        var alreadyConfirmed = IsBroadenedSourceSearchConfirmationEnvelope(originalQuery);
        var answer = (language, nearbyHitCount > 0) switch
        {
            ("en", true) =>
                "The search found nearby passages, but they are still too weak or too narrow to build a useful answer without inventing. I need broader or more diverse source material before turning this into a clean result.",
            ("en", false) =>
                "I do not have enough usable source material yet to build a useful answer without inventing.",
            ("es", true) =>
                "La busqueda encontro pasajes cercanos, pero siguen siendo demasiado debiles o estrechos para construir una respuesta util sin inventar. Necesito material fuente mas amplio o diverso antes de convertirlo en un resultado claro.",
            ("es", false) =>
                "Todavia no tengo suficiente material fuente util para construir una respuesta sin inventar.",
            ("pt", true) =>
                "A pesquisa encontrou passagens proximas, mas ainda sao demasiado fracas ou estreitas para construir uma resposta util sem inventar. Preciso de material fonte mais amplo ou diverso antes de transformar isto num resultado claro.",
            ("pt", false) =>
                "Ainda nao tenho material fonte util suficiente para construir uma resposta sem inventar.",
            ("de", true) =>
                "Die Suche hat nahe liegende Passagen gefunden, aber sie sind noch zu schwach oder zu eng, um ohne Erfindungen eine hilfreiche Antwort zu erstellen. Ich brauche breiteres oder vielfaeltigeres Quellenmaterial, bevor daraus ein sauberes Ergebnis wird.",
            ("de", false) =>
                "Ich habe noch nicht genug nutzbares Quellenmaterial, um ohne Erfindungen eine hilfreiche Antwort zu erstellen.",
            ("it", true) =>
                "La ricerca ha trovato passaggi vicini, ma sono ancora troppo deboli o ristretti per costruire una risposta utile senza inventare. Ho bisogno di materiale fonte piu ampio o piu vario prima di trasformarlo in un risultato chiaro.",
            ("it", false) =>
                "Non ho ancora abbastanza materiale fonte utilizzabile per costruire una risposta senza inventare.",
            (_, true) =>
                "La recherche a trouve des passages proches, mais ils restent trop faibles ou trop etroits pour construire une reponse utile sans inventer. Il faut des sources plus larges ou plus variees avant d'en faire un resultat propre.",
            _ =>
                "Je n'ai pas encore assez d'elements sources exploitables pour construire une reponse utile sans inventer."
        };

        return alreadyConfirmed
            ? SuppressBroadenedSearchOfferIfAlreadyConfirmed(answer, originalQuery, language)
            : AppendBroadenedSearchOfferIfHelpful(answer, intentQuery, language);
    }

    private static string SuppressBroadenedSearchOfferIfAlreadyConfirmed(string answer, string originalQuery, string language)
    {
        if (string.IsNullOrWhiteSpace(answer) || !IsBroadenedSourceSearchConfirmationEnvelope(originalQuery))
            return answer;

        var offer = DeterministicAgentText.SourceBackedExpandedSearchOffer(language);
        return answer
            .Replace($"{Environment.NewLine}{Environment.NewLine}{offer}", string.Empty, StringComparison.OrdinalIgnoreCase)
            .Replace(offer, string.Empty, StringComparison.OrdinalIgnoreCase)
            .TrimEnd();
    }

    private static string ResolveSourceBackedFallbackIntentQuery(string query)
        => IsBroadenedSourceSearchConfirmationEnvelope(query)
            && TryExtractPreviousUserRequestFromEnvelope(query, out var previousRequest)
            && !string.IsNullOrWhiteSpace(previousRequest)
                ? previousRequest
                : query;

    private static bool ShouldAvoidRawSourceBackedFallback(string? query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        return IsBroadenedSourceSearchConfirmationEnvelope(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query);
    }

    private static bool ShouldRequireWriterForBroadDocumentaryFinal(ToolResults toolResults, string? query, string language = "fr")
    {
        if (string.IsNullOrWhiteSpace(query)
            || LooksLikeExactPassageOrCitationRequest(query)
            || LooksLikeStrictCertificationOrExactProofRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query))
        {
            return false;
        }

        if (ShouldAvoidRawSourceBackedFallback(query))
            return true;

        if (!toolResults.Items.Any(static item => item.ToolName is ("rag.search" or "rag.multi_search") && HasRagHits(item.Result)))
            return false;

        return ShouldUseWriterForBroadSourceBackedSynthesis(toolResults, query)
            || ShouldPreferWriterForPolishedSourceBackedAnswer(toolResults, query)
            || ShouldAllowWriterForPartialSourceBackedPlanning(toolResults, query, language);
    }

    private static bool ShouldRouteSourceBackedAnswerThroughWriter(ToolResults toolResults, string? query, string language = "fr")
    {
        if (string.IsNullOrWhiteSpace(query)
            || LooksLikeExactPassageOrCitationRequest(query)
            || LooksLikeStrictCertificationOrExactProofRequest(query)
            || LooksLikeCorpusClaimVerificationRequest(query)
            || LooksLikeSourceBackedCountdownPlanningRequest(query)
            || LooksLikeSourceBackedVerificationChecklistRequest(query))
        {
            return false;
        }

        if (!toolResults.Items.Any(static item => item.ToolName is ("rag.search" or "rag.multi_search") && HasRagHits(item.Result)))
            return false;

        if (ShouldAvoidRawSourceBackedFallback(query)
            || ShouldUseWriterForBroadSourceBackedSynthesis(toolResults, query)
            || ShouldPreferWriterForPolishedSourceBackedAnswer(toolResults, query)
            || ShouldAllowWriterForPartialSourceBackedPlanning(toolResults, query, language))
        {
            return true;
        }

        var usableHits = EnumerateRagHitSummaries(toolResults)
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .ToList();
        if (usableHits.Count == 0)
            return false;

        var distinctPages = usableHits
            .Select(BuildRagHitVisiblePageMergeKey)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count();
        var hasRichEvidence = usableHits.Any(HasRichSourceBackedEvidence);
        var expectsSynthesis =
            LooksLikeSourceBackedActionRequest(query)
            || LooksLikeDocumentaryContentRequest(query)
            || LooksLikeComparativeDocumentaryRequest(query)
            || LooksLikeBroadSynthesisRequestShape(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedOptionRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query)
            || LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeUserNeedsSynthesizedDecisionOrPlan(query);

        if (expectsSynthesis)
            return usableHits.Count >= 2 || distinctPages >= 2 || hasRichEvidence;

        return ShouldUseSourceBackedExtractiveAnswer(query, toolResults)
            && (usableHits.Count >= 2 || distinctPages >= 2);
    }

    private static string BuildReadableSourceBackedCandidateListFallbackAnswer(ToolResults toolResults, string query, string language)
    {
        if (string.IsNullOrWhiteSpace(query))
            return string.Empty;

        var shouldListCandidates = LooksLikeGenericCollectionOrListRequest(query)
            || LooksLikeAnyDocumentaryPlanningRequest(query)
            || LooksLikeBroadSourceBackedCompositionRequest(query)
            || LooksLikeMultipleCandidateSynthesisRequest(query)
            || LooksLikeSoftChoiceRecommendationRequest(query)
            || LooksLikeSourceBackedOptionRequest(query)
            || LooksLikeSourceBackedPairingRecommendationRequest(query);
        if (!shouldListCandidates)
            return string.Empty;

        language = NormalizeLanguageCode(language);
        var maxItems = LooksLikeAnyDocumentaryPlanningRequest(query) ? 10 : 8;
        var candidates = SelectSourceBackedOptionCandidates(
                toolResults,
                query,
                keepOverRequestedDuration: true,
                language: language)
            .Where(static candidate => !LooksLikePageReferenceOnlyHit(candidate.Hit))
            .Where(static candidate => !LooksLikeLowSignalContentCandidateHit(candidate.Hit))
            .Select(candidate => NormalizeReadableSourceBackedCandidate(candidate, query, language))
            .OfType<SourceBackedOptionCandidate>()
            .GroupBy(BuildSourceBackedOptionCandidateKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group
                .OrderByDescending(static candidate => candidate.Score)
                .ThenByDescending(static candidate => ComputeSourceBackedEvidenceRichnessScore(candidate.Hit))
                .ThenByDescending(static candidate => candidate.Hit.Score)
                .First())
            .Take(maxItems)
            .ToList();
        if (candidates.Count == 0)
            return string.Empty;

        var minimumUsefulCandidateCount = LooksLikeAnyDocumentaryPlanningRequest(query)
            ? 6
            : LooksLikeGenericCollectionOrListRequest(query)
                || LooksLikeMultipleCandidateSynthesisRequest(query)
                || LooksLikeBroadSourceBackedCompositionRequest(query)
                    ? 2
                    : 1;
        if (candidates.Count < minimumUsefulCandidateCount)
            return string.Empty;

        var labels = language switch
        {
            "en" => (
                Header: "Here is a first usable selection from the cited documents.",
                Intro: "Use these items as a starting point, then check the cited pages before relying on quantities, timing or constraints:",
                Shortage: "The retrieved sources are still not enough to make a complete answer without repetition or invention."),
            "es" => (
                Header: "Aquí tienes una primera selección utilizable a partir de los documentos citados.",
                Intro: "Usa estos elementos como punto de partida y revisa las páginas citadas antes de aplicar cantidades, tiempos o restricciones:",
                Shortage: "Las fuentes recuperadas aún no bastan para construir una respuesta completa sin repetir ni inventar."),
            "pt" => (
                Header: "Aqui está uma primeira seleção utilizável a partir dos documentos citados.",
                Intro: "Usa estes itens como ponto de partida e verifica as páginas citadas antes de aplicar quantidades, tempos ou restrições:",
                Shortage: "As fontes recuperadas ainda não bastam para construir uma resposta completa sem repetir nem inventar."),
            "de" => (
                Header: "Hier ist eine erste brauchbare Auswahl aus den zitierten Dokumenten.",
                Intro: "Nutze diese Punkte als Ausgangsbasis und prüfe die zitierten Seiten, bevor du Mengen, Zeiten oder Einschränkungen übernimmst:",
                Shortage: "Die gefundenen Quellen reichen noch nicht für eine vollständige Antwort ohne Wiederholung oder Erfindung."),
            "it" => (
                Header: "Ecco una prima selezione utilizzabile dai documenti citati.",
                Intro: "Usa questi elementi come punto di partenza e controlla le pagine citate prima di applicare quantità, tempi o vincoli:",
                Shortage: "Le fonti recuperate non bastano ancora per costruire una risposta completa senza ripetere o inventare."),
            _ => (
                Header: "Voici une liste de départ plus exploitable, uniquement à partir des sources.",
                Intro: "Utilise ces éléments comme point de départ, puis vérifie les pages citées avant de reprendre des quantités, durées ou contraintes :",
                Shortage: "Les sources récupérées ne suffisent pas encore pour construire une réponse complète sans répétition ni invention.")
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(labels.Intro);
        foreach (var candidate in candidates)
        {
            var hit = candidate.Hit;
            var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? hit.DocPath : hit.DocName;
            sb.Append("- ");
            sb.Append(candidate.Title);
            sb.Append(" (");
            sb.Append(docLabel);
            sb.Append(' ');
            sb.Append(SourceBackedPagePrefix(language));
            sb.Append(hit.PageStart);
            sb.AppendLine(").");
        }

        if (candidates.Count < (LooksLikeAnyDocumentaryPlanningRequest(query) ? 6 : 4))
        {
            sb.Append(labels.Shortage);
            return AppendBroadenedSearchOfferIfHelpful(sb.ToString(), query, language);
        }

        return sb.ToString().TrimEnd();
    }

    private static SourceBackedOptionCandidate? NormalizeReadableSourceBackedCandidate(
        SourceBackedOptionCandidate candidate,
        string query,
        string language)
    {
        var title = ResolveReadableSourceBackedCandidateTitle(candidate.Hit, candidate.Title, query, language);
        return IsUsableSourceBackedOptionTitle(title)
            ? candidate with { Title = title }
            : null;
    }

    private static string ResolveReadableSourceBackedCandidateTitle(
        RagHitSummary hit,
        string? currentTitle,
        string query,
        string language)
    {
        var candidates = new List<string>();
        void AddCandidate(string? value)
        {
            var cleaned = CleanSourceBackedOptionTitle(value);
            if (!string.IsNullOrWhiteSpace(cleaned))
                candidates.Add(cleaned);
        }

        AddCandidate(currentTitle);
        foreach (var title in ExtractSourceBackedTitleCandidates(hit))
            AddCandidate(title);
        AddCandidate(ExtractReadablePartialPlanningLeadTitle(hit, query));
        AddCandidate(ExtractEvidenceLeadTitle(hit));

        return candidates
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Where(IsUsableSourceBackedOptionTitle)
            .OrderByDescending(title => ComputeReadableCandidateTitleQualityScore(title, hit, query))
            .ThenBy(title => title.Length)
            .FirstOrDefault() ?? string.Empty;
    }

    private static string ExtractEvidenceLeadTitle(RagHitSummary hit)
    {
        var evidence = CollapseWhitespace(GetBestRagEvidenceText(hit));
        if (string.IsNullOrWhiteSpace(evidence))
            return string.Empty;

        var match = Regex.Match(
            evidence,
            @"^(?<title>[\p{L}\p{N}][\p{L}\p{N} '&/\-,]{3,88})\s+(?:[:\-–]|(?:PREPARATION|PR[Ã‰E]PARATION|ETAPES?|[Ã‰E]TAPES?|STEPS?|METHOD|M[Ã‰E]THODE|PROCEDURE|PROC[Ã‰E]DURE|MATERIALS?|MATERIEL)\b)",
            RegexOptions.CultureInvariant);
        return match.Success ? match.Groups["title"].Value : string.Empty;
    }

    private static int ComputeReadableCandidateTitleQualityScore(string title, RagHitSummary hit, string query)
    {
        var score = 0;
        var normalized = NormalizeLexicalLookup(title);
        if (string.IsNullOrWhiteSpace(normalized))
            return score;

        if (hit.MatchedContentCards is { Count: > 0 }
            && hit.MatchedContentCards.Any(card => string.Equals(
                NormalizeLexicalLookup(CleanSourceBackedOptionTitle(card.Title)),
                normalized,
                StringComparison.Ordinal)))
        {
            score += 8;
        }

        if (!LooksLikeWeakSourceBackedOptionTitle(title))
            score += 5;
        var titleSignalTermCount = ExtractQuerySignalTerms(normalized).Take(7).Count();
        if (titleSignalTermCount is >= 2 and <= 6)
            score += 3;
        if (ComputeRagHitLexicalRelevance(query, $"{title} {GetRagHitLookupText(hit)}") > 0)
            score += 2;
        if (CountNumericFactMarkers(NormalizeStructuredScanText(title)) > 0)
            score -= 6;
        if (LooksLikeProcedureSentenceTitle(normalized))
            score -= 8;

        return score;
    }

    private static string BuildReadablePartialPlanningEvidenceAnswer(IReadOnlyList<RagHitSummary> hits, string query, string language)
    {
        if (!LooksLikeAnyDocumentaryPlanningRequest(query))
            return string.Empty;

        language = NormalizeLanguageCode(language);
        var leads = hits
            .Where(static hit => !LooksLikeNavigationOnlyHit(hit))
            .Where(static hit => !LooksLikeLowSignalContentCandidateHit(hit))
            .GroupBy(BuildRagHitVisiblePageMergeKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group.First())
            .Select(hit => BuildReadablePartialPlanningEvidenceLead(hit, query, language))
            .Where(static lead => !string.IsNullOrWhiteSpace(lead.Title))
            .Take(6)
            .ToList();
        if (leads.Count == 0)
            return string.Empty;

        var structuredAnswer = BuildStructuredReadablePartialPlanningEvidenceAnswer(leads, query, language);
        if (!string.IsNullOrWhiteSpace(structuredAnswer))
            return structuredAnswer;

        var labels = language switch
        {
            "en" => (
                Header: "Here is a usable starting point from the sourced material available.",
                Intro: "Use these sourced leads as a base:",
                Missing: "To turn this into a full plan, the missing slots still need to be completed or validated from additional sources.",
                Verify: "Check the cited pages before using exact quantities, timing or constraints."),
            "es" => (
                Header: "Aqui tienes una base de partida util a partir del material con fuente disponible.",
                Intro: "Usa estas pistas con fuente como base:",
                Missing: "Para convertirlo en un plan completo, aun hay que completar o validar los huecos que faltan con fuentes adicionales.",
                Verify: "Consulta las paginas citadas antes de usar cantidades, tiempos o restricciones exactas."),
            "pt" => (
                Header: "Aqui esta uma base de partida util a partir do material com fonte disponivel.",
                Intro: "Usa estas pistas com fonte como base:",
                Missing: "Para transformar isto num plano completo, ainda e preciso completar ou validar os espacos em falta com fontes adicionais.",
                Verify: "Consulta as paginas citadas antes de usar quantidades, tempos ou restricoes exatas."),
            "de" => (
                Header: "Hier ist ein nutzbarer Ausgangspunkt aus dem verfuegbaren Quellenmaterial.",
                Intro: "Nutze diese belegten Hinweise als Basis:",
                Missing: "Fuer einen vollstaendigen Plan muessen fehlende Plaetze noch aus weiteren Quellen ergaenzt oder geprueft werden.",
                Verify: "Pruefe die zitierten Seiten, bevor du genaue Mengen, Zeiten oder Einschraenkungen uebernimmst."),
            "it" => (
                Header: "Ecco una base di partenza utile dal materiale con fonte disponibile.",
                Intro: "Usa queste indicazioni con fonte come base:",
                Missing: "Per trasformarla in un piano completo, gli spazi mancanti vanno ancora completati o validati con fonti aggiuntive.",
                Verify: "Controlla le pagine citate prima di usare quantita, tempi o vincoli precisi."),
            _ => (
                Header: "Voici une base de travail exploitable à partir des éléments sourcés disponibles.",
                Intro: "À utiliser comme point de départ :",
                Missing: "Pour en faire un planning complet, il faut encore compléter ou valider les créneaux manquants avec d'autres sources.",
                Verify: "Vérifie les pages citées avant de reprendre des quantités, horaires ou contraintes exactes.")
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(labels.Intro);
        var sections = new[]
        {
            (Title: PartialPlanningSectionTitle(language, "frame"), Items: leads.Where(static lead => lead.IsPlanningFrame).ToList()),
            (Title: PartialPlanningSectionTitle(language, "options"), Items: leads.Where(static lead => !lead.IsPlanningFrame && lead.IsConcreteOption).ToList()),
            (Title: PartialPlanningSectionTitle(language, "context"), Items: leads.Where(static lead => !lead.IsPlanningFrame && !lead.IsConcreteOption).ToList())
        };

        foreach (var section in sections.Where(static section => section.Items.Count > 0))
        {
            sb.AppendLine(section.Title);
            foreach (var lead in section.Items)
            {
                sb.Append("- ");
                sb.Append(lead.Title);
                sb.Append(" (");
                sb.Append(lead.SourceLabel);
                sb.Append(' ');
                sb.Append(SourceBackedPagePrefix(language));
                sb.Append(lead.Page);
                sb.AppendLine(").");
            }
        }

        var needsAdditionalEvidence = leads.Count < ResolveSourceBackedPlanningTargetItemCount(query);
        if (needsAdditionalEvidence)
            sb.AppendLine(labels.Missing);
        sb.Append(labels.Verify);
        return needsAdditionalEvidence
            ? AppendBroadenedSearchOfferIfHelpful(sb.ToString(), query, language)
            : sb.ToString().TrimEnd();
    }

    private static string BuildStructuredReadablePartialPlanningEvidenceAnswer(
        IReadOnlyList<PartialPlanningEvidenceLead> leads,
        string query,
        string language)
    {
        var dayLabels = DetectRequestedDayAxisLabels(query, language);
        var periodLabels = DetectRequestedPeriodAxisLabels(query, language);
        if (dayLabels.Count == 0 || periodLabels.Count == 0)
            return string.Empty;

        var slotLeads = leads
            .Where(static lead => lead.IsConcreteOption)
            .GroupBy(static lead => $"{lead.Title}|{lead.SourceLabel}|{lead.Page}", StringComparer.OrdinalIgnoreCase)
            .Select(static group => group.First())
            .ToList();
        if (slotLeads.Count == 0)
            return string.Empty;

        var requiredSlots = dayLabels.Count * periodLabels.Count;
        var labels = NormalizeLanguageCode(language) switch
        {
            "en" => (
                Header: "Here is a readable starting plan from the available sourced elements.",
                Partial: $"The documented base is incomplete: {slotLeads.Count} usable elements for {requiredSlots} requested places. I place what is supported and leave the missing places explicit instead of inventing extra items.",
                MissingSlot: "to complete with an additional source",
                Verify: "Before using it as a final plan, check the cited pages for quantities, timing, constraints and substitutions."),
            "es" => (
                Header: "Aqui tienes un plan inicial legible basado en los elementos con fuente disponibles.",
                Partial: $"La base con fuente esta incompleta ({slotLeads.Count} elemento(s) util(es) para {requiredSlots} espacio(s)). Coloco lo que esta respaldado y dejo explicitos los espacios que faltan, sin inventar elementos adicionales.",
                MissingSlot: "completar con una fuente adicional",
                Verify: "Antes de usarlo como plan final, revisa las paginas citadas para cantidades, horarios, restricciones y sustituciones."),
            "pt" => (
                Header: "Aqui esta um plano inicial legivel baseado nos elementos com fonte disponiveis.",
                Partial: $"A base com fonte esta incompleta ({slotLeads.Count} item(ns) util(eis) para {requiredSlots} espaco(s)). Coloco o que esta apoiado pelas fontes e deixo explicitos os espacos em falta, sem inventar itens adicionais.",
                MissingSlot: "completar com uma fonte adicional",
                Verify: "Antes de usar isto como plano final, verifica as paginas citadas para quantidades, horarios, restricoes e substituicoes."),
            "de" => (
                Header: "Hier ist ein lesbarer Startplan aus den verfuegbaren belegten Elementen.",
                Partial: $"Die belegte Grundlage ist unvollstaendig ({slotLeads.Count} nutzbare Elemente fuer {requiredSlots} Plaetze). Ich setze ein, was belegt ist, und lasse fehlende Plaetze sichtbar, ohne weitere Elemente zu erfinden.",
                MissingSlot: "mit einer zusaetzlichen Quelle ergaenzen",
                Verify: "Pruefe vor der finalen Nutzung die zitierten Seiten zu Mengen, Zeiten, Einschraenkungen und Alternativen."),
            "it" => (
                Header: "Ecco un piano iniziale leggibile basato sugli elementi con fonte disponibili.",
                Partial: $"La base con fonte e incompleta ({slotLeads.Count} elemento/i utile/i per {requiredSlots} spazio/i). Inserisco cio che e supportato e lascio espliciti gli spazi mancanti, senza inventare elementi aggiuntivi.",
                MissingSlot: "completare con una fonte aggiuntiva",
                Verify: "Prima di usarlo come piano finale, controlla le pagine citate per quantita, tempi, vincoli e sostituzioni."),
            _ => (
                Header: "Voici une base de planning lisible à partir des éléments sourcés disponibles.",
                Partial: $"La base documentée est incomplète : {slotLeads.Count} élément(s) exploitable(s) pour {requiredSlots} emplacements demandés. Je place ce qui est appuyé par les sources et je laisse visibles les emplacements manquants, sans inventer d'éléments supplémentaires.",
                MissingSlot: "à compléter avec une source supplémentaire",
                Verify: "Avant d'en faire un planning définitif, vérifie les pages citées pour les quantités, horaires, contraintes et remplacements.")
        };

        var sb = new StringBuilder();
        sb.AppendLine(labels.Header);
        sb.AppendLine(labels.Partial);

        var slotIndex = 0;
        foreach (var day in dayLabels)
        {
            sb.AppendLine();
            sb.AppendLine($"{day} :");
            foreach (var period in periodLabels)
            {
                sb.Append("  - ");
                sb.Append(period);
                sb.Append(" : ");
                if (slotIndex < slotLeads.Count)
                {
                    var lead = slotLeads[slotIndex];
                    sb.Append(lead.Title);
                    sb.Append(" (");
                    sb.Append(lead.SourceLabel);
                    sb.Append(' ');
                    sb.Append(SourceBackedPagePrefix(language));
                    sb.Append(lead.Page);
                    sb.AppendLine(").");
                }
                else
                {
                    sb.AppendLine(labels.MissingSlot + ".");
                }
                slotIndex++;
            }
        }

        sb.AppendLine();
        sb.Append(labels.Verify);
        return slotLeads.Count < requiredSlots
            ? AppendBroadenedSearchOfferIfHelpful(sb.ToString(), query, language)
            : sb.ToString().TrimEnd();
    }

    private static string PartialPlanningSectionTitle(string language, string kind)
    {
        language = NormalizeLanguageCode(language);
        return kind switch
        {
            "frame" => language switch
            {
                "en" => "Planning frame",
                "es" => "Marco de organizacion",
                "pt" => "Base de organizacao",
                "de" => "Planungsrahmen",
                "it" => "Base organizzativa",
                _ => "Cadre d'organisation"
            },
            "options" => language switch
            {
                "en" => "Concrete candidates",
                "es" => "Candidatos concretos",
                "pt" => "Candidatos concretos",
                "de" => "Konkrete Kandidaten",
                "it" => "Candidati concreti",
                _ => "Candidats concrets"
            },
            _ => language switch
            {
                "en" => "Useful context",
                "es" => "Contexto util",
                "pt" => "Contexto util",
                "de" => "Nuetzlicher Kontext",
                "it" => "Contesto utile",
                _ => "Contexte utile"
            }
        };
    }

    private static PartialPlanningEvidenceLead BuildReadablePartialPlanningEvidenceLead(RagHitSummary hit, string query, string language)
    {
        var title = ExtractReadablePartialPlanningLeadTitle(hit, query);
        var normalizedTitle = NormalizeLexicalLookup(title);
        var hasConcreteTitle = !string.IsNullOrWhiteSpace(title)
            && !LooksLikeWeakPartialPlanningLeadTitle(title)
            && !LooksLikeProcedureSentenceTitle(normalizedTitle);
        var hasConcreteCardTitle = hit.MatchedContentCards?.Any(card =>
        {
            var cardTitle = CleanSourceBackedOptionTitle(card.Title);
            return IsUsableSourceBackedOptionTitle(cardTitle);
        }) == true;
        var hasConcreteProfileTitle = HasSourceBackedProfileTitle(hit);

        var evidence = NormalizeLexicalLookup(GetRagHitLookupText(hit));
        var isPlanningLead = Regex.IsMatch(
            evidence,
            @"\b(?:plan|planning|planification|organisation|organiser|horaire|horaires|calendrier|programme|temps\s+disponible|schedule|calendar|organize|organise|time\s+available|wochenplan|programma)\b",
            RegexOptions.CultureInvariant);
        var isConcreteOption = hasConcreteTitle || hasConcreteCardTitle || hasConcreteProfileTitle;

        var fallbackTitle = language switch
        {
            "en" when isPlanningLead => "Planning frame",
            "en" when isConcreteOption => "Sourced option",
            "en" => "Documented lead",
            "es" when isPlanningLead => "Marco de organizacion",
            "es" when isConcreteOption => "Opcion con fuente",
            "es" => "Pista con fuente",
            "pt" when isPlanningLead => "Base de organizacao",
            "pt" when isConcreteOption => "Opcao com fonte",
            "pt" => "Pista com fonte",
            "de" when isPlanningLead => "Planungsrahmen",
            "de" when isConcreteOption => "Belegte Option",
            "de" => "Belegter Hinweis",
            "it" when isPlanningLead => "Base organizzativa",
            "it" when isConcreteOption => "Opzione con fonte",
            "it" => "Indicazione con fonte",
            _ when isPlanningLead => "Cadre d'organisation",
            _ when isConcreteOption => "Option sourcée",
            _ => "Élément documenté"
        };

        var guidance = language switch
        {
            "en" when isPlanningLead => "use it to frame timing and organization before choosing the concrete items",
            "en" when isConcreteOption => "keep it as a concrete candidate in the rotation",
            "en" => "keep it as supporting context, not as a complete answer",
            "es" when isPlanningLead => "sirve para encuadrar tiempos y organizacion antes de elegir los elementos concretos",
            "es" when isConcreteOption => "puede quedar como candidato concreto dentro de la rotacion",
            "es" => "mantenla como contexto de apoyo, no como respuesta completa",
            "pt" when isPlanningLead => "serve para enquadrar tempos e organizacao antes de escolher os itens concretos",
            "pt" when isConcreteOption => "pode ficar como candidato concreto na rotacao",
            "pt" => "mantem isto como contexto de apoio, nao como resposta completa",
            "de" when isPlanningLead => "nutze ihn fuer Zeitrahmen und Organisation, bevor konkrete Elemente gewaehlt werden",
            "de" when isConcreteOption => "behalte sie als konkreten Kandidaten in der Rotation",
            "de" => "nutze ihn als Kontext, nicht als vollstaendige Antwort",
            "it" when isPlanningLead => "usala per definire tempi e organizzazione prima di scegliere gli elementi concreti",
            "it" when isConcreteOption => "tienila come candidata concreta nella rotazione",
            "it" => "tienila come contesto di supporto, non come risposta completa",
            _ when isPlanningLead => "sert à cadrer les horaires et l'organisation avant de choisir les éléments concrets",
            _ when isConcreteOption => "peut servir de candidat concret dans la rotation",
            _ => "sert de contexte d'appui, pas de réponse complète à elle seule"
        };

        var docLabel = string.IsNullOrWhiteSpace(hit.DocName) ? Path.GetFileName(hit.DocPath) : hit.DocName;
        return new PartialPlanningEvidenceLead(
            hasConcreteTitle ? title : fallbackTitle,
            guidance,
            string.IsNullOrWhiteSpace(docLabel) ? hit.DocPath : docLabel,
            hit.PageStart,
            isPlanningLead,
            isConcreteOption);
    }

    private static string ExtractReadablePartialPlanningLeadTitle(RagHitSummary hit, string query)
    {
        var title = ExtractSourceBackedOptionTitle(hit, query);
        if (!LooksLikeWeakPartialPlanningLeadTitle(title))
            return title;

        var profileTitle = ExtractProfileTitleCandidates(hit.ContextualSnippet ?? string.Empty)
            .Select(CleanSourceBackedOptionTitle)
            .Where(static candidate => !string.IsNullOrWhiteSpace(candidate))
            .Where(IsUsefulSourceBackedDisplayTitle)
            .FirstOrDefault(static candidate => !LooksLikeWeakPartialPlanningLeadTitle(candidate));
        if (!string.IsNullOrWhiteSpace(profileTitle))
            return profileTitle;

        var evidence = CollapseWhitespace(GetBestRagEvidenceText(hit));
        if (string.IsNullOrWhiteSpace(evidence))
            return string.Empty;

        var headingMatch = Regex.Match(
            evidence,
            @"^(?<title>[\p{Lu}\p{N}\u00c0-\u017f '&/\-,]{4,90})\s+(?:PREPARATION|PR[ÉE]PARATION|ETAPES?|[ÉE]TAPES?|STEPS?|METHOD|M[ÉE]THODE|PROCEDURE|PROC[ÉE]DURE)\b",
            RegexOptions.CultureInvariant);
        if (!headingMatch.Success)
            return string.Empty;

        var headingTitle = CleanSourceBackedOptionTitle(headingMatch.Groups["title"].Value);
        return !LooksLikeWeakPartialPlanningLeadTitle(headingTitle) && IsUsefulSourceBackedDisplayTitle(headingTitle)
            ? headingTitle
            : string.Empty;
    }

    private static bool LooksLikeWeakPartialPlanningLeadTitle(string title)
    {
        var normalized = NormalizeLexicalLookup(title);
        return string.IsNullOrWhiteSpace(normalized)
            || normalized.Length > 70
            || normalized.Contains(".pdf", StringComparison.Ordinal)
            || LooksLikeWeakSourceBackedOptionTitle(title)
            || Regex.IsMatch(normalized, @"\b(?:document|documents|source|sources|pistes?|trouvees?|disponibles?|couvre|comprend|sections?|conseils?|page|pages)\b", RegexOptions.CultureInvariant);
    }

    private static string BuildRagHitVisiblePageMergeKey(RagHitSummary hit)
    {
        var page = Math.Max(1, hit.PageStart);

        var path = NormalizeLexicalLookup(hit.DocPath);
        if (!string.IsNullOrWhiteSpace(path) && LooksLikeQualifiedDocumentPath(hit.DocPath))
            return $"path:{path}|p:{page}";

        var hash = CollapseWhitespace(hit.SourceHash ?? string.Empty).ToLowerInvariant();
        if (!string.IsNullOrWhiteSpace(hash))
            return $"hash:{hash}|p:{page}";

        if (!string.IsNullOrWhiteSpace(path))
            return $"path:{path}|p:{page}";

        var docId = CollapseWhitespace(hit.DocId ?? string.Empty).ToLowerInvariant();
        if (!string.IsNullOrWhiteSpace(docId))
            return $"id:{docId}|p:{page}";

        var name = NormalizeLexicalLookup(hit.DocName);
        return $"name:{name}|p:{page}";
    }

